function Get-WasmAstFuncExprLiftName {
    param(
        $Node,
        [string]$PreferredName = "",
        [switch]$PublicName
    )

    if ($null -eq $Node -or [string]$Node.node -ne "FUNC_EXPR") { return "" }
    if ($Node.PSObject.Properties.Name -contains "__wasm_func_expr_lift_name") {
        return [string]$Node.__wasm_func_expr_lift_name
    }

    $displayName = if (-not [string]::IsNullOrWhiteSpace($PreferredName)) { $PreferredName } else { "func_expr" }
    $liftName = $displayName
    if (-not $PublicName) {
        $safe = ($displayName -replace '[^A-Za-z0-9_]', '_')
        if ([string]::IsNullOrWhiteSpace($safe)) { $safe = "func_expr" }
        $liftName = "__sura_func_expr_${safe}_$script:wasmFuncExprLiftCounter"
        $script:wasmFuncExprLiftCounter++
    }

    $Node | Add-Member -NotePropertyName "__wasm_func_expr_lift_name" -NotePropertyValue $liftName -Force
    $Node | Add-Member -NotePropertyName "__wasm_func_expr_display_name" -NotePropertyValue $displayName -Force
    return $liftName
}

function Get-WasmAstFuncExprDisplayName {
    param($Node)

    if ($null -eq $Node -or [string]$Node.node -ne "FUNC_EXPR") { return "" }
    if ($Node.PSObject.Properties.Name -contains "__wasm_func_expr_display_name") {
        return [string]$Node.__wasm_func_expr_display_name
    }
    return ""
}

function Get-WasmAstExprHintKey {
    param($Node)

    if ($null -eq $Node) { return "" }
    try {
        return ($Node | ConvertTo-Json -Depth 100 -Compress)
    } catch {
        return ""
    }
}

function Get-WasmAstSpecializedFunctionCallReturnHint {
    param(
        $Node,
        [ValidateSet("display", "lift")][string]$Kind
    )

    if ($null -eq $Node -or [string]$Node.node -ne "CALL") { return "" }
    $key = Get-WasmAstExprHintKey $Node
    if ([string]::IsNullOrWhiteSpace($key)) { return "" }
    if ($Kind -eq "display") {
        if ($script:wasmSpecializedFunctionCallReturnDisplayHints.ContainsKey($key)) {
            return [string]$script:wasmSpecializedFunctionCallReturnDisplayHints[$key]
        }
        return ""
    }
    if ($script:wasmSpecializedFunctionCallReturnLiftHints.ContainsKey($key)) {
        return [string]$script:wasmSpecializedFunctionCallReturnLiftHints[$key]
    }
    return ""
}

function Copy-WasmAstCaptureMap {
    param([hashtable]$Map)

    $copy = @{}
    if ($null -eq $Map) { return $copy }
    foreach ($entry in $Map.GetEnumerator()) {
        $copy[[string]$entry.Key] = $entry.Value
    }
    return $copy
}

function Set-WasmAstCaptureMap {
    param([hashtable]$Target, [hashtable]$Source)

    if ($null -eq $Target) { return }
    foreach ($key in @($Target.Keys)) { $Target.Remove($key) }
    if ($null -eq $Source) { return }
    foreach ($entry in $Source.GetEnumerator()) {
        $Target[[string]$entry.Key] = $entry.Value
    }
}

function Test-WasmAstPrimitiveCaptureExpr {
    param($Node)

    if ($null -eq $Node) { return $false }
    return ([string]$Node.node -in @("NUM_LIT", "STR_LIT", "BOOL_LIT", "NIL_LIT"))
}

function Get-WasmAstPrimitiveCaptureExpr {
    param($Expr, [hashtable]$CaptureExprs)

    if ($null -ne $Expr -and [string]$Expr.node -eq "STR_LIT") {
        $text = [string]$Expr.value
        if ($text.IndexOf('{') -ge 0 -and $text.IndexOf('}') -ge 0) {
            $capturedText = Convert-WasmAstCaptureInterpolatedText $text $CaptureExprs
            if ($null -eq $capturedText) { return $null }
            return (New-WasmAstCaptureStrLit $capturedText $Expr)
        }
    }
    if ($null -ne $Expr -and [string]$Expr.node -eq "STR_INTERP") {
        $capturedText = Convert-WasmAstCaptureStringInterpolationNode $Expr $CaptureExprs
        if ($null -eq $capturedText) { return $null }
        return (New-WasmAstCaptureStrLit $capturedText $Expr)
    }
    if (Test-WasmAstPrimitiveCaptureExpr $Expr) {
        return (Copy-WasmAstNodeJson $Expr)
    }
    if ($null -ne $Expr -and [string]$Expr.node -eq "IDENT" -and $null -ne $CaptureExprs) {
        $name = [string]$Expr.name
        if ($CaptureExprs.ContainsKey($name)) {
            return (Copy-WasmAstNodeJson $CaptureExprs[$name])
        }
    }
    if ($null -ne $Expr -and [string]$Expr.node -eq "IDENT") {
        $name = [string]$Expr.name
        if ($script:wasmAstFunctionDefs.ContainsKey($name)) {
            return (Copy-WasmAstNodeJson $Expr)
        }
    }
    if ($null -ne $Expr -and [string]$Expr.node -eq "BIN_OP") {
        return (Get-WasmAstPrimitiveCaptureBinOpExpr $Expr $CaptureExprs)
    }
    if ($null -ne $Expr -and [string]$Expr.node -eq "UNARY_OP") {
        return (Get-WasmAstPrimitiveCaptureUnaryExpr $Expr $CaptureExprs)
    }
    if ($null -ne $Expr -and [string]$Expr.node -eq "TERNARY") {
        return (Get-WasmAstPrimitiveCaptureTernaryExpr $Expr $CaptureExprs)
    }
    if ($null -ne $Expr -and [string]$Expr.node -in @("ARRAY_LIT", "DICT_LIT")) {
        return (Get-WasmAstLiteralCollectionCaptureExpr $Expr $CaptureExprs)
    }
    if ($null -ne $Expr -and [string]$Expr.node -in @("INDEX", "DOT_ACCESS")) {
        return (Get-WasmAstLiteralCollectionAccessCaptureExpr $Expr $CaptureExprs)
    }
    if ($null -ne $Expr -and [string]$Expr.node -eq "CALL") {
        return (Get-WasmAstPureCallCaptureExpr $Expr $CaptureExprs)
    }
    if ($null -ne $Expr -and [string]$Expr.node -eq "METHOD_CALL") {
        return (Get-WasmAstPureMethodCaptureExpr $Expr $CaptureExprs)
    }
    return $null
}

function Copy-WasmAstNodeJson {
    param($Node)

    if ($null -eq $Node) { return $null }
    return ($Node | ConvertTo-Json -Depth 100 | ConvertFrom-Json)
}

function New-WasmAstCaptureNumLit {
    param([double]$Value, $SourceNode)

    return [pscustomobject]@{
        node = "NUM_LIT"
        line = $(if ($null -ne $SourceNode -and $SourceNode.PSObject.Properties.Name -contains "line") { $SourceNode.line } else { 0 })
        value = $Value
    }
}

function New-WasmAstCaptureBoolLit {
    param([bool]$Value, $SourceNode)

    return [pscustomobject]@{
        node = "BOOL_LIT"
        line = $(if ($null -ne $SourceNode -and $SourceNode.PSObject.Properties.Name -contains "line") { $SourceNode.line } else { 0 })
        value = $Value
    }
}

function New-WasmAstCaptureStrLit {
    param([string]$Value, $SourceNode)

    return [pscustomobject]@{
        node = "STR_LIT"
        line = $(if ($null -ne $SourceNode -and $SourceNode.PSObject.Properties.Name -contains "line") { $SourceNode.line } else { 0 })
        value = $Value
    }
}

function New-WasmAstCaptureIdent {
    param([string]$Name, $SourceNode)

    return [pscustomobject]@{
        node = "IDENT"
        line = $(if ($null -ne $SourceNode -and $SourceNode.PSObject.Properties.Name -contains "line") { $SourceNode.line } else { 0 })
        name = $Name
    }
}

function Test-WasmAstPrimitiveCaptureEqual {
    param($Left, $Right)

    $leftNode = [string]$Left.node
    $rightNode = [string]$Right.node
    if ($leftNode -ne $rightNode) { return $false }
    switch ($leftNode) {
        "NUM_LIT" { return ([double]$Left.value -eq [double]$Right.value) }
        "STR_LIT" { return ([string]$Left.value -eq [string]$Right.value) }
        "BOOL_LIT" { return ([bool]$Left.value -eq [bool]$Right.value) }
        "NIL_LIT" { return $true }
        "ARRAY_LIT" {
            $leftItems = @(As-WasmAstArray ($Left.elements))
            $rightItems = @(As-WasmAstArray ($Right.elements))
            if ($leftItems.Count -ne $rightItems.Count) { return $false }
            for ($i = 0; $i -lt $leftItems.Count; $i++) {
                if (-not (Test-WasmAstPrimitiveCaptureEqual $leftItems[$i] $rightItems[$i])) { return $false }
            }
            return $true
        }
        "DICT_LIT" {
            $leftEntries = @(As-WasmAstArray ($Left.entries))
            $rightEntries = @(As-WasmAstArray ($Right.entries))
            if ($leftEntries.Count -ne $rightEntries.Count) { return $false }
            $rightByKey = @{}
            foreach ($entry in $rightEntries) { $rightByKey[[string]$entry.key] = $entry.value }
            foreach ($entry in $leftEntries) {
                $key = [string]$entry.key
                if (-not $rightByKey.ContainsKey($key) -or -not (Test-WasmAstPrimitiveCaptureEqual ($entry.value) $rightByKey[$key])) {
                    return $false
                }
            }
            return $true
        }
        default { return $false }
    }
}

function Merge-WasmAstBranchCaptureMaps {
    param([hashtable]$Target, [hashtable]$ThenCaptures, [hashtable]$ElseCaptures)

    Merge-WasmAstCaptureMapSet $Target @($ThenCaptures, $ElseCaptures)
}

function Merge-WasmAstCaptureMapSet {
    param([hashtable]$Target, [object[]]$CaptureMaps)

    $merged = @{}
    $maps = @($CaptureMaps | Where-Object { $null -ne $_ })
    if ($maps.Count -eq 0) {
        Set-WasmAstCaptureMap $Target $merged
        return
    }
    foreach ($key in $maps[0].Keys) {
        $firstValue = $maps[0][$key]
        $sameAcrossAll = $true
        foreach ($map in $maps) {
            if (-not $map.ContainsKey($key) -or -not (Test-WasmAstPrimitiveCaptureEqual $firstValue $map[$key])) {
                $sameAcrossAll = $false
                break
            }
        }
        if ($sameAcrossAll) {
            $merged[[string]$key] = Copy-WasmAstNodeJson $firstValue
        }
    }
    Set-WasmAstCaptureMap $Target $merged
}

function Get-WasmAstStaticForIterationValues {
    param($FromExpr, $ToExpr, $StepExpr, [hashtable]$CaptureExprs)

    $fromCapture = Get-WasmAstPrimitiveCaptureExpr $FromExpr $CaptureExprs
    $toCapture = Get-WasmAstPrimitiveCaptureExpr $ToExpr $CaptureExprs
    $stepCapture = if ($null -eq $StepExpr) { [pscustomobject]@{ node = "NUM_LIT"; line = 0; value = 1 } } else { Get-WasmAstPrimitiveCaptureExpr $StepExpr $CaptureExprs }
    if ($null -eq $fromCapture -or $null -eq $toCapture -or $null -eq $stepCapture) { return $null }
    if ([string]$fromCapture.node -ne "NUM_LIT" -or [string]$toCapture.node -ne "NUM_LIT" -or [string]$stepCapture.node -ne "NUM_LIT") { return $null }

    $start = [int][Math]::Truncate([double]$fromCapture.value)
    $end = [int][Math]::Truncate([double]$toCapture.value)
    $step = [int][Math]::Truncate([double]$stepCapture.value)
    if ($step -eq 0) { return $null }

    $values = New-Object System.Collections.Generic.List[int]
    $current = $start
    while ((($step -gt 0) -and ($current -le $end)) -or (($step -lt 0) -and ($current -ge $end))) {
        if ($values.Count -ge 64) { return $null }
        $values.Add($current) | Out-Null
        $current += $step
    }
    return ,@($values.ToArray())
}

function Get-WasmAstStaticForeachCaptureEntries {
    param($CollectionExpr, [hashtable]$CaptureExprs)

    $collection = Get-WasmAstPrimitiveCaptureExpr $CollectionExpr $CaptureExprs
    if ($null -eq $collection) { return [pscustomobject]@{ Ok = $false; Entries = @() } }

    $entries = New-Object System.Collections.Generic.List[object]
    if ([string]$collection.node -eq "ARRAY_LIT") {
        $index = 0
        foreach ($element in @(As-WasmAstArray ($collection.elements))) {
            if ($entries.Count -ge 64) { return [pscustomobject]@{ Ok = $false; Entries = @() } }
            $entries.Add([pscustomobject]@{
                Key = New-WasmAstCaptureNumLit ([double]$index) $CollectionExpr
                Value = Copy-WasmAstNodeJson $element
            }) | Out-Null
            $index++
        }
        return [pscustomobject]@{ Ok = $true; Entries = @($entries.ToArray()) }
    }

    if ([string]$collection.node -eq "DICT_LIT") {
        foreach ($entry in @(As-WasmAstArray ($collection.entries))) {
            if ($entries.Count -ge 64) { return [pscustomobject]@{ Ok = $false; Entries = @() } }
            $entries.Add([pscustomobject]@{
                Key = New-WasmAstCaptureStrLit ([string]$entry.key) $CollectionExpr
                Value = Copy-WasmAstNodeJson ($entry.value)
            }) | Out-Null
        }
        return [pscustomobject]@{ Ok = $true; Entries = @($entries.ToArray()) }
    }

    return [pscustomobject]@{ Ok = $false; Entries = @() }
}

function Remove-WasmAstCaptureMutationRoot {
    param([hashtable]$CaptureExprs, $Expr)

    if ($null -eq $CaptureExprs -or $null -eq $Expr) { return }
    if ([string]$Expr.node -eq "IDENT") {
        $name = [string]$Expr.name
        if ($CaptureExprs.ContainsKey($name)) { $CaptureExprs.Remove($name) }
        return
    }
    if ([string]$Expr.node -in @("DOT_ACCESS", "INDEX")) {
        Remove-WasmAstCaptureMutationRoot $CaptureExprs ($Expr.obj)
    }
}

function Get-WasmAstPrimitiveCaptureUnaryExpr {
    param($Expr, [hashtable]$CaptureExprs)

    $operand = Get-WasmAstPrimitiveCaptureExpr ($Expr.operand) $CaptureExprs
    if ($null -eq $operand) { return $null }
    switch ([string]$Expr.op) {
        "not" {
            if ([string]$operand.node -ne "BOOL_LIT") { return $null }
            return (New-WasmAstCaptureBoolLit (-not [bool]$operand.value) $Expr)
        }
        "-" {
            if ([string]$operand.node -ne "NUM_LIT") { return $null }
            return (New-WasmAstCaptureNumLit (-[double]$operand.value) $Expr)
        }
        default { return $null }
    }
}

function Get-WasmAstLiteralCollectionCaptureExpr {
    param($Expr, [hashtable]$CaptureExprs)

    if ([string]$Expr.node -eq "ARRAY_LIT") {
        $items = New-Object System.Collections.Generic.List[object]
        foreach ($element in @(As-WasmAstArray ($Expr.elements))) {
            $captured = Get-WasmAstPrimitiveCaptureExpr $element $CaptureExprs
            if ($null -eq $captured) { return $null }
            $items.Add($captured) | Out-Null
        }
        return [pscustomobject]@{ node = "ARRAY_LIT"; line = $Expr.line; elements = @($items.ToArray()) }
    }
    if ([string]$Expr.node -eq "DICT_LIT") {
        $entries = New-Object System.Collections.Generic.List[object]
        foreach ($entry in @(As-WasmAstArray ($Expr.entries))) {
            $captured = Get-WasmAstPrimitiveCaptureExpr ($entry.value) $CaptureExprs
            if ($null -eq $captured) { return $null }
            $entries.Add([pscustomobject]@{ key = [string]$entry.key; value = $captured }) | Out-Null
        }
        return [pscustomobject]@{ node = "DICT_LIT"; line = $Expr.line; entries = @($entries.ToArray()) }
    }
    return $null
}

function Get-WasmAstLiteralCollectionAccessCaptureExpr {
    param($Expr, [hashtable]$CaptureExprs)

    if ([string]$Expr.node -eq "DOT_ACCESS") {
        $collection = Get-WasmAstPrimitiveCaptureExpr ($Expr.obj) $CaptureExprs
        if ($null -eq $collection -or [string]$collection.node -ne "DICT_LIT") { return $null }
        $key = [string]$Expr.prop
        foreach ($entry in @(As-WasmAstArray ($collection.entries))) {
            if ([string]$entry.key -eq $key) { return (Copy-WasmAstNodeJson ($entry.value)) }
        }
        return $null
    }
    if ([string]$Expr.node -eq "INDEX") {
        $collection = Get-WasmAstPrimitiveCaptureExpr ($Expr.obj) $CaptureExprs
        $key = Get-WasmAstPrimitiveCaptureExpr ($Expr.key) $CaptureExprs
        if ($null -eq $collection -or $null -eq $key) { return $null }
        if ([string]$collection.node -eq "ARRAY_LIT" -and [string]$key.node -eq "NUM_LIT") {
            $index = [int][Math]::Truncate([double]$key.value)
            $items = @(As-WasmAstArray ($collection.elements))
            if ($index -lt 0 -or $index -ge $items.Count) { return $null }
            return (Copy-WasmAstNodeJson $items[$index])
        }
        if ([string]$collection.node -eq "DICT_LIT" -and [string]$key.node -eq "STR_LIT") {
            $keyText = [string]$key.value
            foreach ($entry in @(As-WasmAstArray ($collection.entries))) {
                if ([string]$entry.key -eq $keyText) { return (Copy-WasmAstNodeJson ($entry.value)) }
            }
        }
    }
    return $null
}

function Get-WasmAstCaptureTypeName {
    param($Value)

    if ($null -eq $Value) { return "" }
    switch ([string]$Value.node) {
        "NUM_LIT" { return "num" }
        "STR_LIT" { return "string" }
        "BOOL_LIT" { return "bool" }
        "NIL_LIT" { return "nil" }
        "ARRAY_LIT" { return "array" }
        "DICT_LIT" { return "dict" }
        default { return "" }
    }
}

function Get-WasmAstCaptureLength {
    param($Value)

    if ($null -eq $Value) { return $null }
    switch ([string]$Value.node) {
        "STR_LIT" { return ([double]([string]$Value.value).Length) }
        "ARRAY_LIT" { return ([double]@(As-WasmAstArray ($Value.elements)).Count) }
        "DICT_LIT" { return ([double]@(As-WasmAstArray ($Value.entries)).Count) }
        default { return $null }
    }
}

function Get-WasmAstCaptureTruthy {
    param($Value)

    if ($null -eq $Value) { return $null }
    switch ([string]$Value.node) {
        "NIL_LIT" { return $false }
        "BOOL_LIT" { return [bool]$Value.value }
        "NUM_LIT" { return ([double]$Value.value -ne 0) }
        "STR_LIT" { return (([string]$Value.value).Length -gt 0) }
        "ARRAY_LIT" { return (@(As-WasmAstArray ($Value.elements)).Count -gt 0) }
        "DICT_LIT" { return (@(As-WasmAstArray ($Value.entries)).Count -gt 0) }
        default { return $null }
    }
}

function Convert-WasmAstCaptureStringLiteral {
    param([string]$Value)

    return ($Value | ConvertTo-Json -Compress)
}

function Convert-WasmAstCaptureToString {
    param($Value, [bool]$Nested = $false)

    if ($null -eq $Value) { return $null }
    switch ([string]$Value.node) {
        "NIL_LIT" { return "nil" }
        "BOOL_LIT" { return $(if ([bool]$Value.value) { "true" } else { "false" }) }
        "NUM_LIT" { return ([double]$Value.value).ToString("G15", [System.Globalization.CultureInfo]::InvariantCulture) }
        "STR_LIT" {
            if ($Nested) { return (Convert-WasmAstCaptureStringLiteral ([string]$Value.value)) }
            return [string]$Value.value
        }
        "ARRAY_LIT" {
            $parts = New-Object System.Collections.Generic.List[string]
            foreach ($element in @(As-WasmAstArray ($Value.elements))) {
                $text = Convert-WasmAstCaptureToString $element $true
                if ($null -eq $text) { return $null }
                $parts.Add($text) | Out-Null
            }
            return ("[{0}]" -f ([string]::Join(", ", [string[]]$parts.ToArray())))
        }
        "DICT_LIT" {
            $parts = New-Object System.Collections.Generic.List[string]
            foreach ($entry in @(As-WasmAstArray ($Value.entries))) {
                $text = Convert-WasmAstCaptureToString ($entry.value) $true
                if ($null -eq $text) { return $null }
                $parts.Add(("{0}: {1}" -f (Convert-WasmAstCaptureStringLiteral ([string]$entry.key)), $text)) | Out-Null
            }
            return ("{{{0}}}" -f ([string]::Join(", ", [string[]]$parts.ToArray())))
        }
        default { return $null }
    }
}

function Convert-WasmAstCaptureInterpolatedText {
    param([string]$Text, [hashtable]$CaptureExprs)

    if ([string]::IsNullOrEmpty($Text) -or $Text.IndexOf('{') -lt 0 -or $Text.IndexOf('}') -lt 0) {
        return $Text
    }

    $out = New-Object System.Text.StringBuilder
    $cursor = 0
    while ($cursor -lt $Text.Length) {
        $open = $Text.IndexOf('{', $cursor)
        if ($open -lt 0) {
            [void]$out.Append($Text.Substring($cursor))
            break
        }
        $close = Find-WasmAstInterpolationClose -Text $Text -Open $open
        if ($close -lt 0) { return $null }
        if ($open -gt $cursor) {
            [void]$out.Append($Text.Substring($cursor, $open - $cursor))
        }

        $exprText = $Text.Substring($open + 1, $close - $open - 1).Trim()
        if ([string]::IsNullOrWhiteSpace($exprText) -or $exprText -notmatch '[A-Za-z0-9_]') {
            [void]$out.Append($Text.Substring($open, $close - $open + 1))
        } else {
            $exprForWasm = $exprText.Replace('\"', '"')
            $exprNode = try {
                Convert-WasmAstInterpolationExprTextToNode $exprForWasm
            } catch {
                $null
            }
            if ($null -eq $exprNode) { return $null }
            $captured = Get-WasmAstPrimitiveCaptureExpr $exprNode $CaptureExprs
            if ($null -eq $captured) { return $null }
            $textPart = Convert-WasmAstCaptureToString $captured $false
            if ($null -eq $textPart) { return $null }
            [void]$out.Append($textPart)
        }
        $cursor = $close + 1
    }

    return $out.ToString()
}

function Convert-WasmAstCaptureStringInterpolationNode {
    param($Node, [hashtable]$CaptureExprs)

    if ($null -eq $Node -or [string]$Node.node -ne "STR_INTERP") { return $null }
    $out = New-Object System.Text.StringBuilder
    foreach ($part in @(As-WasmAstArray ($Node.parts))) {
        if ($null -eq $part) { continue }
        if ([string]$part.node -eq "STR_LIT") {
            [void]$out.Append([string]$part.value)
            continue
        }
        $captured = Get-WasmAstPrimitiveCaptureExpr $part $CaptureExprs
        if ($null -eq $captured) { return $null }
        $textPart = Convert-WasmAstCaptureToString $captured $false
        if ($null -eq $textPart) { return $null }
        [void]$out.Append($textPart)
    }
    return $out.ToString()
}

function Convert-WasmAstCaptureAsciiUpper {
    param([string]$Value)

    $out = New-Object System.Text.StringBuilder
    foreach ($ch in $Value.ToCharArray()) {
        $code = [int][char]$ch
        if ($code -ge 97 -and $code -le 122) { [void]$out.Append([char]($code - 32)) } else { [void]$out.Append($ch) }
    }
    return $out.ToString()
}

function Convert-WasmAstCaptureAsciiLower {
    param([string]$Value)

    $out = New-Object System.Text.StringBuilder
    foreach ($ch in $Value.ToCharArray()) {
        $code = [int][char]$ch
        if ($code -ge 65 -and $code -le 90) { [void]$out.Append([char]($code + 32)) } else { [void]$out.Append($ch) }
    }
    return $out.ToString()
}

function Convert-WasmAstCaptureAsciiTrim {
    param([string]$Value)

    return ([regex]::Replace($Value, '^[\x09-\x0d\x20]+|[\x09-\x0d\x20]+$', ''))
}

function Convert-WasmAstCaptureSubstring {
    param([string]$Value, [int]$Start, [int]$End, [bool]$Slice = $false)

    $length = $Value.Length
    if ($Slice) {
        if ($Start -lt 0) { $Start = $length + $Start }
        if ($End -lt 0) { $End = $length + $End }
    }
    if ($Start -lt 0) { $Start = 0 }
    if ($End -gt $length) { $End = $length }
    if ($End -lt $Start) { $End = $Start }
    return $Value.Substring($Start, $End - $Start)
}

function Get-WasmAstNumericCaptureArgs {
    param([object[]]$InputArgs, [hashtable]$CaptureExprs)

    $values = New-Object System.Collections.Generic.List[double]
    foreach ($arg in @($InputArgs)) {
        $captured = Get-WasmAstPrimitiveCaptureExpr $arg $CaptureExprs
        if ($null -eq $captured -or [string]$captured.node -ne "NUM_LIT") { return $null }
        $values.Add([double]$captured.value) | Out-Null
    }
    return [double[]]$values.ToArray()
}

function Convert-WasmAstCaptureRoundHalfAwayFromZero {
    param([double]$Value)

    if ($Value -ge 0) {
        return [Math]::Floor($Value + 0.5)
    }
    return [Math]::Ceiling($Value - 0.5)
}

function Get-WasmAstNumericArrayCaptureValues {
    param($Value)

    if ($null -eq $Value -or [string]$Value.node -ne "ARRAY_LIT") { return $null }
    $values = New-Object System.Collections.Generic.List[double]
    foreach ($element in @(As-WasmAstArray ($Value.elements))) {
        if ($null -eq $element -or [string]$element.node -ne "NUM_LIT") { return $null }
        $values.Add([double]$element.value) | Out-Null
    }
    return [double[]]$values.ToArray()
}

function New-WasmAstCaptureArrayLit {
    param([object[]]$Elements, $SourceNode)

    return [pscustomobject]@{
        node = "ARRAY_LIT"
        line = $(if ($null -ne $SourceNode -and $SourceNode.PSObject.Properties.Name -contains "line") { $SourceNode.line } else { 0 })
        elements = @($Elements)
    }
}

function Get-WasmAstPureArrayRangeCaptureResult {
    param([string]$Name, [object[]]$InputArgs, [hashtable]$CaptureExprs, $SourceNode)

    if ($Name -notin @("array.range", "array_range")) { return $null }
    if ($InputArgs.Count -lt 1 -or $InputArgs.Count -gt 3) { return $null }

    $nums = Get-WasmAstNumericCaptureArgs $InputArgs $CaptureExprs
    if ($null -eq $nums) { return $null }

    $start = 0
    $end = 0
    $step = 1
    if ($nums.Count -eq 1) {
        $end = [int][Math]::Truncate($nums[0])
    } elseif ($nums.Count -eq 2) {
        $start = [int][Math]::Truncate($nums[0])
        $end = [int][Math]::Truncate($nums[1])
    } else {
        $start = [int][Math]::Truncate($nums[0])
        $end = [int][Math]::Truncate($nums[1])
        $step = [int][Math]::Truncate($nums[2])
    }

    if ($step -eq 0) { return $null }

    $items = New-Object System.Collections.Generic.List[object]
    $value = $start
    while (($step -gt 0 -and $value -lt $end) -or ($step -lt 0 -and $value -gt $end)) {
        if ($items.Count -ge 10000) { return $null }
        $items.Add((New-WasmAstCaptureNumLit ([double]$value) $SourceNode)) | Out-Null
        $value += $step
    }
    return (New-WasmAstCaptureArrayLit ([object[]]$items.ToArray()) $SourceNode)
}

function Get-WasmAstPureArrayCaptureResult {
    param([string]$Name, $ArrayValue, [object[]]$ArrayArgs, [hashtable]$CaptureExprs, $SourceNode)

    $values = Get-WasmAstNumericArrayCaptureValues $ArrayValue
    if ($null -eq $values) { return $null }

    if ($Name -in @("len", "length", "array.len", "array.length", "array.size", "array_len", "array_length", "array_size")) {
        if ($ArrayArgs.Count -ne 0) { return $null }
        return (New-WasmAstCaptureNumLit ([double]$values.Count) $SourceNode)
    }
    if ($Name -in @("sum", "array.sum", "array_sum")) {
        if ($ArrayArgs.Count -ne 0) { return $null }
        return (New-WasmAstCaptureNumLit (($values | Measure-Object -Sum).Sum) $SourceNode)
    }
    if ($Name -in @("avg", "average", "array.avg", "array.average", "array_avg", "array_average")) {
        if ($ArrayArgs.Count -ne 0 -or $values.Count -eq 0) { return $null }
        return (New-WasmAstCaptureNumLit ((($values | Measure-Object -Sum).Sum) / $values.Count) $SourceNode)
    }
    if ($Name -in @("min", "array.min", "array_min")) {
        if ($ArrayArgs.Count -ne 0 -or $values.Count -eq 0) { return $null }
        return (New-WasmAstCaptureNumLit (($values | Measure-Object -Minimum).Minimum) $SourceNode)
    }
    if ($Name -in @("max", "array.max", "array_max")) {
        if ($ArrayArgs.Count -ne 0 -or $values.Count -eq 0) { return $null }
        return (New-WasmAstCaptureNumLit (($values | Measure-Object -Maximum).Maximum) $SourceNode)
    }
    if ($Name -in @("index_of", "indexOf", "array.index_of", "array.indexOf", "array.index", "array_index_of", "array_indexOf", "array_index")) {
        if ($ArrayArgs.Count -ne 1) { return $null }
        $needle = Get-WasmAstPrimitiveCaptureExpr $ArrayArgs[0] $CaptureExprs
        if ($null -eq $needle -or [string]$needle.node -ne "NUM_LIT") { return $null }
        for ($i = 0; $i -lt $values.Count; $i++) {
            if ($values[$i] -eq [double]$needle.value) { return (New-WasmAstCaptureNumLit ([double]$i) $SourceNode) }
        }
        return (New-WasmAstCaptureNumLit -1 $SourceNode)
    }
    if ($Name -in @("contains", "includes", "array.contains", "array.includes", "array_contains", "array_includes")) {
        if ($ArrayArgs.Count -ne 1) { return $null }
        $index = Get-WasmAstPureArrayCaptureResult "index_of" $ArrayValue $ArrayArgs $CaptureExprs $SourceNode
        if ($null -eq $index) { return $null }
        return (New-WasmAstCaptureBoolLit ([double]$index.value -ge 0) $SourceNode)
    }
    return $null
}

function Get-WasmAstPureStringCallCaptureExpr {
    param([string]$Name, [object[]]$InputArgs, [hashtable]$CaptureExprs, $SourceNode)

    $capturedArgs = New-Object System.Collections.Generic.List[object]
    foreach ($arg in @($InputArgs)) {
        $captured = Get-WasmAstPrimitiveCaptureExpr $arg $CaptureExprs
        if ($null -eq $captured) { return $null }
        $capturedArgs.Add($captured) | Out-Null
    }
    $items = @($capturedArgs.ToArray())
    if ($items.Count -lt 1 -or [string]$items[0].node -ne "STR_LIT") { return $null }
    $text = [string]$items[0].value

    if ($Name -in @("upper", "string.upper", "string_upper")) {
        if ($items.Count -ne 1) { return $null }
        return (New-WasmAstCaptureStrLit (Convert-WasmAstCaptureAsciiUpper $text) $SourceNode)
    }
    if ($Name -in @("lower", "string.lower", "string_lower")) {
        if ($items.Count -ne 1) { return $null }
        return (New-WasmAstCaptureStrLit (Convert-WasmAstCaptureAsciiLower $text) $SourceNode)
    }
    if ($Name -in @("trim", "string.trim", "string_trim")) {
        if ($items.Count -ne 1) { return $null }
        return (New-WasmAstCaptureStrLit (Convert-WasmAstCaptureAsciiTrim $text) $SourceNode)
    }
    if ($Name -in @("contains", "string.contains", "string_contains", "indexOf", "index_of", "string.indexOf", "string.index_of", "string_indexOf", "string_index_of", "startsWith", "starts_with", "string.startsWith", "string.starts_with", "string_startsWith", "string_starts_with", "endsWith", "ends_with", "string.endsWith", "string.ends_with", "string_endsWith", "string_ends_with")) {
        if ($items.Count -ne 2 -or [string]$items[1].node -ne "STR_LIT") { return $null }
        $needle = [string]$items[1].value
        if ($Name -in @("contains", "string.contains", "string_contains")) {
            return (New-WasmAstCaptureBoolLit ($text.IndexOf($needle, [System.StringComparison]::Ordinal) -ge 0) $SourceNode)
        }
        if ($Name -in @("indexOf", "index_of", "string.indexOf", "string.index_of", "string_indexOf", "string_index_of")) {
            return (New-WasmAstCaptureNumLit ([double]$text.IndexOf($needle, [System.StringComparison]::Ordinal)) $SourceNode)
        }
        if ($Name -in @("startsWith", "starts_with", "string.startsWith", "string.starts_with", "string_startsWith", "string_starts_with")) {
            return (New-WasmAstCaptureBoolLit ($text.StartsWith($needle, [System.StringComparison]::Ordinal)) $SourceNode)
        }
        return (New-WasmAstCaptureBoolLit ($text.EndsWith($needle, [System.StringComparison]::Ordinal)) $SourceNode)
    }
    if ($Name -in @("replace", "string.replace", "string_replace")) {
        if ($items.Count -ne 3 -or [string]$items[1].node -ne "STR_LIT" -or [string]$items[2].node -ne "STR_LIT") { return $null }
        $from = [string]$items[1].value
        if ($from.Length -eq 0) {
            return (New-WasmAstCaptureStrLit $text $SourceNode)
        }
        return (New-WasmAstCaptureStrLit ($text.Replace($from, [string]$items[2].value)) $SourceNode)
    }
    if ($Name -in @("substring", "string.substring", "string_substring", "slice", "sub", "string.slice", "string.sub", "string_slice", "string_sub")) {
        if ($items.Count -notin @(2, 3) -or [string]$items[1].node -ne "NUM_LIT") { return $null }
        $endValue = 2147483647
        if ($items.Count -eq 3) {
            if ([string]$items[2].node -ne "NUM_LIT") { return $null }
            $endValue = [int][Math]::Truncate([double]$items[2].value)
        }
        $startValue = [int][Math]::Truncate([double]$items[1].value)
        $sliceMode = ($Name -in @("slice", "sub", "string.slice", "string.sub", "string_slice", "string_sub"))
        return (New-WasmAstCaptureStrLit (Convert-WasmAstCaptureSubstring $text $startValue $endValue $sliceMode) $SourceNode)
    }
    return $null
}

function Get-WasmAstPureCallCaptureExpr {
    param($Expr, [hashtable]$CaptureExprs)

    $args = @(As-WasmAstArray ($Expr.args))
    $name = [string]$Expr.name
    if ($args.Count -eq 1) {
        $value = Get-WasmAstPrimitiveCaptureExpr $args[0] $CaptureExprs
        if ($null -eq $value) { return $null }
        switch ($name) {
        "type" {
            $typeName = Get-WasmAstCaptureTypeName $value
            if ([string]::IsNullOrWhiteSpace($typeName)) { return $null }
            return (New-WasmAstCaptureStrLit $typeName $Expr)
        }
        { $_ -in @("length", "len", "string_len", "string_length", "string_size", "string.len", "string.length", "string.size") } {
            $length = Get-WasmAstCaptureLength $value
            if ($null -eq $length) { return $null }
            return (New-WasmAstCaptureNumLit ([double]$length) $Expr)
        }
        "to_bool" {
            $truthy = Get-WasmAstCaptureTruthy $value
            if ($null -eq $truthy) { return $null }
            return (New-WasmAstCaptureBoolLit ([bool]$truthy) $Expr)
        }
        "to_str" {
            $text = Convert-WasmAstCaptureToString $value $false
            if ($null -eq $text) { return $null }
            return (New-WasmAstCaptureStrLit $text $Expr)
        }
            default { }
        }
    }

    $stringResult = Get-WasmAstPureStringCallCaptureExpr $name ([object[]]$args) $CaptureExprs $Expr
    if ($null -ne $stringResult) { return $stringResult }

    $rangeResult = Get-WasmAstPureArrayRangeCaptureResult $name ([object[]]$args) $CaptureExprs $Expr
    if ($null -ne $rangeResult) { return $rangeResult }

    if ($args.Count -ge 1 -and $name -match '^(array\.|array_)') {
        $arrayValue = Get-WasmAstPrimitiveCaptureExpr $args[0] $CaptureExprs
        if ($null -ne $arrayValue) {
            $arrayArgs = if ($args.Count -gt 1) { @($args | Select-Object -Skip 1) } else { @() }
            $arrayResult = Get-WasmAstPureArrayCaptureResult $name $arrayValue ([object[]]$arrayArgs) $CaptureExprs $Expr
            if ($null -ne $arrayResult) { return $arrayResult }
        }
    }

    $nums = Get-WasmAstNumericCaptureArgs ([object[]]$args) $CaptureExprs
    if ($null -eq $nums) { return $null }
    switch ($name) {
        "to_int" {
            if ($nums.Count -ne 1) { return $null }
            return (New-WasmAstCaptureNumLit ([Math]::Truncate($nums[0])) $Expr)
        }
        "to_float" {
            if ($nums.Count -ne 1) { return $null }
            return (New-WasmAstCaptureNumLit $nums[0] $Expr)
        }
        { $_ -in @("floor", "math.floor") } {
            if ($nums.Count -ne 1) { return $null }
            return (New-WasmAstCaptureNumLit ([Math]::Floor($nums[0])) $Expr)
        }
        { $_ -in @("ceil", "math.ceil") } {
            if ($nums.Count -ne 1) { return $null }
            return (New-WasmAstCaptureNumLit ([Math]::Ceiling($nums[0])) $Expr)
        }
        { $_ -in @("round", "math.round") } {
            if ($nums.Count -ne 1) { return $null }
            return (New-WasmAstCaptureNumLit (Convert-WasmAstCaptureRoundHalfAwayFromZero $nums[0]) $Expr)
        }
        { $_ -in @("abs", "math.abs") } {
            if ($nums.Count -ne 1) { return $null }
            return (New-WasmAstCaptureNumLit ([Math]::Abs($nums[0])) $Expr)
        }
        { $_ -in @("sign", "math.sign") } {
            if ($nums.Count -ne 1) { return $null }
            return (New-WasmAstCaptureNumLit ($(if ($nums[0] -gt 0) { 1 } elseif ($nums[0] -lt 0) { -1 } else { 0 })) $Expr)
        }
        { $_ -in @("sqrt", "math.sqrt") } {
            if ($nums.Count -ne 1 -or $nums[0] -lt 0) { return $null }
            return (New-WasmAstCaptureNumLit ([Math]::Floor([Math]::Sqrt($nums[0]))) $Expr)
        }
        { $_ -in @("pow", "math.pow") } {
            if ($nums.Count -ne 2 -or $nums[1] -lt 0) { return $null }
            return (New-WasmAstCaptureNumLit ([Math]::Pow($nums[0], [Math]::Truncate($nums[1]))) $Expr)
        }
        { $_ -in @("min", "math.min") } {
            if ($nums.Count -lt 1) { return $null }
            return (New-WasmAstCaptureNumLit (($nums | Measure-Object -Minimum).Minimum) $Expr)
        }
        { $_ -in @("max", "math.max") } {
            if ($nums.Count -lt 1) { return $null }
            return (New-WasmAstCaptureNumLit (($nums | Measure-Object -Maximum).Maximum) $Expr)
        }
        { $_ -in @("clamp", "math.clamp") } {
            if ($nums.Count -ne 3) { return $null }
            return (New-WasmAstCaptureNumLit ([Math]::Min([Math]::Max($nums[0], $nums[1]), $nums[2])) $Expr)
        }
        default { return $null }
    }
}

function Get-WasmAstPureMethodCaptureExpr {
    param($Expr, [hashtable]$CaptureExprs)

    $args = @(As-WasmAstArray ($Expr.args))
    $method = [string]$Expr.method
    if ($null -ne $Expr.obj -and [string]$Expr.obj.node -eq "IDENT" -and [string]$Expr.obj.name -eq "array") {
        $rangeResult = Get-WasmAstPureArrayRangeCaptureResult "array.$method" ([object[]]$args) $CaptureExprs $Expr
        if ($null -ne $rangeResult) { return $rangeResult }
        if ($args.Count -ge 1) {
            $arrayValue = Get-WasmAstPrimitiveCaptureExpr $args[0] $CaptureExprs
            if ($null -ne $arrayValue) {
                $arrayArgs = if ($args.Count -gt 1) { @($args | Select-Object -Skip 1) } else { @() }
                $arrayResult = Get-WasmAstPureArrayCaptureResult "array.$method" $arrayValue ([object[]]$arrayArgs) $CaptureExprs $Expr
                if ($null -ne $arrayResult) { return $arrayResult }
            }
        }
    }
    $receiver = Get-WasmAstPrimitiveCaptureExpr ($Expr.obj) $CaptureExprs
    if ($null -eq $receiver) { return $null }
    if ([string]$receiver.node -eq "ARRAY_LIT") {
        return (Get-WasmAstPureArrayCaptureResult $method $receiver ([object[]]$args) $CaptureExprs $Expr)
    }
    if ([string]$receiver.node -ne "STR_LIT") { return $null }
    $text = [string]$receiver.value
    switch ($method) {
        "upper" {
            if ($args.Count -ne 0) { return $null }
            return (New-WasmAstCaptureStrLit (Convert-WasmAstCaptureAsciiUpper $text) $Expr)
        }
        "lower" {
            if ($args.Count -ne 0) { return $null }
            return (New-WasmAstCaptureStrLit (Convert-WasmAstCaptureAsciiLower $text) $Expr)
        }
        "trim" {
            if ($args.Count -ne 0) { return $null }
            return (New-WasmAstCaptureStrLit (Convert-WasmAstCaptureAsciiTrim $text) $Expr)
        }
        { $_ -in @("substring", "slice", "sub") } {
            if ($args.Count -notin @(1, 2)) { return $null }
            $start = Get-WasmAstPrimitiveCaptureExpr $args[0] $CaptureExprs
            if ($null -eq $start -or [string]$start.node -ne "NUM_LIT") { return $null }
            $endValue = 2147483647
            if ($args.Count -eq 2) {
                $end = Get-WasmAstPrimitiveCaptureExpr $args[1] $CaptureExprs
                if ($null -eq $end -or [string]$end.node -ne "NUM_LIT") { return $null }
                $endValue = [int][Math]::Truncate([double]$end.value)
            }
            $startValue = [int][Math]::Truncate([double]$start.value)
            $sliceMode = ($method -in @("slice", "sub"))
            return (New-WasmAstCaptureStrLit (Convert-WasmAstCaptureSubstring $text $startValue $endValue $sliceMode) $Expr)
        }
        { $_ -in @("contains", "startsWith", "starts_with", "endsWith", "ends_with", "indexOf", "index_of", "replace") } {
            if ($args.Count -lt 1) { return $null }
            $first = Get-WasmAstPrimitiveCaptureExpr $args[0] $CaptureExprs
            if ($null -eq $first -or [string]$first.node -ne "STR_LIT") { return $null }
            $needle = [string]$first.value
            switch ($method) {
                "contains" {
                    if ($args.Count -ne 1) { return $null }
                    return (New-WasmAstCaptureBoolLit ($text.IndexOf($needle, [System.StringComparison]::Ordinal) -ge 0) $Expr)
                }
                { $_ -in @("startsWith", "starts_with") } {
                    if ($args.Count -ne 1) { return $null }
                    return (New-WasmAstCaptureBoolLit ($text.StartsWith($needle, [System.StringComparison]::Ordinal)) $Expr)
                }
                { $_ -in @("endsWith", "ends_with") } {
                    if ($args.Count -ne 1) { return $null }
                    return (New-WasmAstCaptureBoolLit ($text.EndsWith($needle, [System.StringComparison]::Ordinal)) $Expr)
                }
                { $_ -in @("indexOf", "index_of") } {
                    if ($args.Count -ne 1) { return $null }
                    return (New-WasmAstCaptureNumLit ([double]$text.IndexOf($needle, [System.StringComparison]::Ordinal)) $Expr)
                }
                "replace" {
                    if ($args.Count -ne 2) { return $null }
                    $replacement = Get-WasmAstPrimitiveCaptureExpr $args[1] $CaptureExprs
                    if ($null -eq $replacement -or [string]$replacement.node -ne "STR_LIT") { return $null }
                    return (New-WasmAstCaptureStrLit ($text.Replace($needle, [string]$replacement.value)) $Expr)
                }
            }
        }
        default { return $null }
    }
}

function Get-WasmAstPrimitiveCaptureTernaryExpr {
    param($Expr, [hashtable]$CaptureExprs)

    $cond = Get-WasmAstPrimitiveCaptureExpr ($Expr.cond) $CaptureExprs
    if ($null -eq $cond -or [string]$cond.node -ne "BOOL_LIT") { return $null }
    if ([bool]$cond.value) {
        return (Get-WasmAstPrimitiveCaptureExpr ($Expr.then) $CaptureExprs)
    }
    return (Get-WasmAstPrimitiveCaptureExpr ($Expr.else) $CaptureExprs)
}

function Get-WasmAstPrimitiveCaptureBinOpExpr {
    param($Expr, [hashtable]$CaptureExprs)

    $left = Get-WasmAstPrimitiveCaptureExpr ($Expr.left) $CaptureExprs
    $right = Get-WasmAstPrimitiveCaptureExpr ($Expr.right) $CaptureExprs
    if ($null -eq $left -or $null -eq $right) { return $null }
    $op = [string]$Expr.op

    if ($op -in @("==", "!=")) {
        $same = Test-WasmAstPrimitiveCaptureEqual $left $right
        return (New-WasmAstCaptureBoolLit ($(if ($op -eq "==") { $same } else { -not $same })) $Expr)
    }
    if ($op -eq "??") {
        if ([string]$left.node -eq "NIL_LIT") { return (Copy-WasmAstNodeJson $right) }
        return (Copy-WasmAstNodeJson $left)
    }
    if ($op -eq "and" -and [string]$left.node -eq "BOOL_LIT" -and [string]$right.node -eq "BOOL_LIT") {
        return (New-WasmAstCaptureBoolLit (([bool]$left.value) -and ([bool]$right.value)) $Expr)
    }
    if ($op -eq "or" -and [string]$left.node -eq "BOOL_LIT" -and [string]$right.node -eq "BOOL_LIT") {
        return (New-WasmAstCaptureBoolLit (([bool]$left.value) -or ([bool]$right.value)) $Expr)
    }
    if ($op -eq "+" -and [string]$left.node -eq "STR_LIT" -and [string]$right.node -eq "STR_LIT") {
        return (New-WasmAstCaptureStrLit (([string]$left.value) + ([string]$right.value)) $Expr)
    }
    if ([string]$left.node -ne "NUM_LIT" -or [string]$right.node -ne "NUM_LIT") { return $null }

    $a = [double]$left.value
    $b = [double]$right.value
    switch ($op) {
        "+" { return (New-WasmAstCaptureNumLit ($a + $b) $Expr) }
        "-" { return (New-WasmAstCaptureNumLit ($a - $b) $Expr) }
        "*" { return (New-WasmAstCaptureNumLit ($a * $b) $Expr) }
        "/" {
            if ($b -eq 0) { return $null }
            return (New-WasmAstCaptureNumLit ($a / $b) $Expr)
        }
        "%" {
            if ($b -eq 0) { return $null }
            return (New-WasmAstCaptureNumLit ($a % $b) $Expr)
        }
        "<" { return (New-WasmAstCaptureBoolLit ($a -lt $b) $Expr) }
        "<=" { return (New-WasmAstCaptureBoolLit ($a -le $b) $Expr) }
        ">" { return (New-WasmAstCaptureBoolLit ($a -gt $b) $Expr) }
        ">=" { return (New-WasmAstCaptureBoolLit ($a -ge $b) $Expr) }
        default { return $null }
    }
}

function Add-WasmAstBoundNames {
    param($Node, [hashtable]$Out)

    if ($null -eq $Node) { return }
    switch ([string]$Node.node) {
        "SuraBlock" {
            foreach ($stmt in @(As-WasmAstArray ($Node.body))) { Add-WasmAstBoundNames $stmt $Out }
        }
        "ASSIGN" { if (-not [string]::IsNullOrWhiteSpace([string]$Node.name)) { $Out[[string]$Node.name] = $true } }
        "IN_PLACE" { if (-not [string]::IsNullOrWhiteSpace([string]$Node.name)) { $Out[[string]$Node.name] = $true } }
        "FOR" {
            if (-not [string]::IsNullOrWhiteSpace([string]$Node.var)) { $Out[[string]$Node.var] = $true }
            Add-WasmAstBoundNames ($Node.body) $Out
        }
        "FOREACH" {
            if (-not [string]::IsNullOrWhiteSpace([string]$Node.var)) { $Out[[string]$Node.var] = $true }
            if (-not [string]::IsNullOrWhiteSpace([string]$Node.var2)) { $Out[[string]$Node.var2] = $true }
            Add-WasmAstBoundNames ($Node.body) $Out
        }
        "IF" {
            Add-WasmAstBoundNames ($Node.then_block) $Out
            Add-WasmAstBoundNames ($Node.else_block) $Out
        }
        "WHILE" { Add-WasmAstBoundNames ($Node.body) $Out }
        "REPEAT" { Add-WasmAstBoundNames ($Node.body) $Out }
        "MATCH" {
            foreach ($arm in @(As-WasmAstArray ($Node.arms))) { Add-WasmAstBoundNames ($arm.body) $Out }
        }
        "TRY" {
            if (-not [string]::IsNullOrWhiteSpace([string]$Node.catch_var)) { $Out[[string]$Node.catch_var] = $true }
            Add-WasmAstBoundNames ($Node.try_block) $Out
            Add-WasmAstBoundNames ($Node.catch_block) $Out
            Add-WasmAstBoundNames ($Node.finally_block) $Out
        }
        default { }
    }
}

function Resolve-WasmAstCapturedExprs {
    param($Node, [hashtable]$CaptureExprs, [hashtable]$BoundNames)

    if ($null -eq $Node) { return $null }
    if ([string]$Node.node -eq "IDENT") {
        $name = [string]$Node.name
        if (-not $BoundNames.ContainsKey($name) -and $CaptureExprs.ContainsKey($name)) {
            return (Copy-WasmAstNodeJson $CaptureExprs[$name])
        }
        return $Node
    }
    if ([string]$Node.node -eq "CALL") {
        $name = [string]$Node.name
        if (-not $BoundNames.ContainsKey($name) -and $CaptureExprs.ContainsKey($name)) {
            $captured = $CaptureExprs[$name]
            if ($null -ne $captured -and [string]$captured.node -eq "IDENT") {
                $Node.name = [string]$captured.name
            }
        }
    }
    foreach ($prop in @($Node.PSObject.Properties)) {
        $value = $prop.Value
        if ($null -eq $value) { continue }
        if ($value -is [System.Array]) {
            for ($i = 0; $i -lt $value.Count; $i++) {
                if ($null -ne $value[$i] -and $value[$i].PSObject.Properties.Name -contains "node") {
                    $value[$i] = Resolve-WasmAstCapturedExprs $value[$i] $CaptureExprs $BoundNames
                }
            }
        } elseif ($value.PSObject.Properties.Name -contains "node") {
            $prop.Value = Resolve-WasmAstCapturedExprs $value $CaptureExprs $BoundNames
        }
    }
    return $Node
}

function New-WasmAstCapturedFuncExpr {
    param($FuncExpr, [hashtable]$CaptureExprs)

    if ($null -eq $FuncExpr -or [string]$FuncExpr.node -ne "FUNC_EXPR" -or $null -eq $CaptureExprs -or $CaptureExprs.Count -eq 0) {
        return $FuncExpr
    }
    $copy = Copy-WasmAstNodeJson $FuncExpr
    $bound = @{}
    foreach ($paramName in @(Get-WasmAstParamNames ($copy.params))) {
        if (-not [string]::IsNullOrWhiteSpace($paramName)) { $bound[[string]$paramName] = $true }
    }
    Add-WasmAstBoundNames ($copy.body) $bound
    $copy.body = Resolve-WasmAstCapturedExprs ($copy.body) $CaptureExprs $bound
    return $copy
}

function Test-WasmAstCallNameNeedsBinding {
    param([string]$Name)

    if ([string]::IsNullOrWhiteSpace($Name)) { return $false }
    if ($script:wasmAstFunctionDefs.ContainsKey($Name)) { return $false }
    if ($Name -in @(
        "type", "length", "len", "string_len", "string_length", "string_size",
        "string.len", "string.length", "string.size", "to_str", "to_bool",
        "text_chunks", "text_chunk", "contains", "indexOf", "index_of",
        "startsWith", "starts_with", "endsWith", "ends_with", "substring",
        "slice", "sub", "lower", "upper", "trim", "replace", "split",
        "lines", "words", "chunks", "min", "max", "sqrt", "pow", "floor",
        "ceil", "round", "to_int", "to_float", "int", "float"
    )) { return $false }
    if ($Name -match '^(array|dict|math|vector|string|set)[\._]') { return $false }
    return $true
}

function Add-WasmAstFreeIdentifierRefs {
    param($Node, [hashtable]$BoundNames, [hashtable]$Out)

    if ($null -eq $Node) { return }
    switch ([string]$Node.node) {
        "IDENT" {
            $name = [string]$Node.name
            if ([string]::IsNullOrWhiteSpace($name)) { return }
            if ($BoundNames.ContainsKey($name) -or
                $script:wasmAstFunctionDefs.ContainsKey($name) -or
                $script:wasmEnumConsts.ContainsKey($name) -or
                $script:wasmEnumStringConsts.ContainsKey($name) -or
                $script:wasmModuleGlobals.ContainsKey($name)) {
                return
            }
            $Out[$name] = $true
            return
        }
        "CALL" {
            $name = [string]$Node.name
            if ((Test-WasmAstCallNameNeedsBinding $name) -and -not $BoundNames.ContainsKey($name)) {
                $Out[$name] = $true
            }
        }
        "STR_LIT" {
            $text = [string]$Node.value
            $cursor = 0
            while ($cursor -lt $text.Length) {
                $open = $text.IndexOf('{', $cursor)
                if ($open -lt 0) { break }
                $close = Find-WasmAstInterpolationClose $text $open
                if ($close -lt 0) {
                    $Out["__sura_unparsed_interpolation__"] = $true
                    return
                }
                $exprText = $text.Substring($open + 1, $close - $open - 1).Trim()
                if (-not [string]::IsNullOrWhiteSpace($exprText)) {
                    try {
                        $exprNode = Convert-WasmAstInterpolationExprTextToNode $exprText
                        if ($null -ne $exprNode) {
                            Add-WasmAstFreeIdentifierRefs $exprNode $BoundNames $Out
                        }
                    } catch {
                        # Conservatively reject lifting when interpolation cannot be analyzed.
                        $Out["__sura_unparsed_interpolation__"] = $true
                        return
                    }
                }
                $cursor = $close + 1
            }
            return
        }
        "FUNC_EXPR" {
            return
        }
    }

    foreach ($prop in @($Node.PSObject.Properties)) {
        $value = $prop.Value
        if ($null -eq $value) { continue }
        if ($value -is [System.Array]) {
            foreach ($item in @($value)) {
                if ($null -ne $item -and $item.PSObject.Properties.Name -contains "node") {
                    Add-WasmAstFreeIdentifierRefs $item $BoundNames $Out
                }
            }
        } elseif ($value.PSObject.Properties.Name -contains "node") {
            Add-WasmAstFreeIdentifierRefs $value $BoundNames $Out
        }
    }
}

function Test-WasmAstFuncExprLiftSkipped {
    param($FuncExpr)

    return ($null -ne $FuncExpr -and
        $FuncExpr.PSObject.Properties.Name -contains "__wasm_func_expr_lift_skipped" -and
        [bool]$FuncExpr.__wasm_func_expr_lift_skipped)
}

function Test-WasmAstFuncExprLiftable {
    param($FuncExpr)

    if ($null -eq $FuncExpr -or [string]$FuncExpr.node -ne "FUNC_EXPR") { return $false }
    $bound = @{}
    foreach ($paramName in @(Get-WasmAstParamNames ($FuncExpr.params))) {
        if (-not [string]::IsNullOrWhiteSpace($paramName)) { $bound[[string]$paramName] = $true }
    }
    Add-WasmAstBoundNames ($FuncExpr.body) $bound
    $free = @{}
    Add-WasmAstFreeIdentifierRefs ($FuncExpr.body) $bound $free
    return ($free.Count -eq 0)
}

function Resolve-WasmAstInlineFunctionCallExpr {
    param($Node, [hashtable]$ParamExprs)

    if ($null -eq $Node) { return $null }
    if ([string]$Node.node -eq "IDENT") {
        $name = [string]$Node.name
        if ($ParamExprs.ContainsKey($name)) {
            return (Copy-WasmAstNodeJson $ParamExprs[$name])
        }
        return (Copy-WasmAstNodeJson $Node)
    }

    $copy = Copy-WasmAstNodeJson $Node
    foreach ($prop in @($copy.PSObject.Properties)) {
        $value = $prop.Value
        if ($null -eq $value) { continue }
        if ($value -is [System.Array]) {
            for ($i = 0; $i -lt $value.Count; $i++) {
                if ($null -ne $value[$i] -and $value[$i].PSObject.Properties.Name -contains "node") {
                    $value[$i] = Resolve-WasmAstInlineFunctionCallExpr $value[$i] $ParamExprs
                }
            }
        } elseif ($value.PSObject.Properties.Name -contains "node") {
            $prop.Value = Resolve-WasmAstInlineFunctionCallExpr $value $ParamExprs
        }
    }
    return $copy
}

function Convert-WasmAstInlineFunctionExprCall {
    param([string]$Name, [object[]]$InputArgs)

    if ([string]::IsNullOrWhiteSpace($Name) -or
        [string]::IsNullOrWhiteSpace($script:wasmCurrentFunctionName) -or
        $script:wasmInlineFunctionExprCallStack.ContainsKey($Name)) {
        return @()
    }

    $funcExpr = $null
    if ($script:wasmCurrentLocalFunctionExprs.ContainsKey($Name)) {
        $funcExpr = $script:wasmCurrentLocalFunctionExprs[$Name]
    } elseif ($script:wasmCurrentLocalFunctionLiftHints.ContainsKey($Name)) {
        $liftName = [string]$script:wasmCurrentLocalFunctionLiftHints[$Name]
        if (-not [string]::IsNullOrWhiteSpace($liftName) -and $script:wasmAstFunctionDefs.ContainsKey($liftName)) {
            $funcExpr = $script:wasmAstFunctionDefs[$liftName].Node
        }
    } elseif ($script:wasmAstFunctionDefs.ContainsKey($Name)) {
        $funcExpr = $script:wasmAstFunctionDefs[$Name].Node
    }
    if ($null -eq $funcExpr -or [string]$funcExpr.node -ne "FUNC_EXPR") { return @() }
    if ($funcExpr.PSObject.Properties.Name -contains "__wasm_func_expr_lift_name") {
        $liftName = [string]$funcExpr.__wasm_func_expr_lift_name
        if (-not [string]::IsNullOrWhiteSpace($liftName) -and
            $script:wasmAstFunctionDefs.ContainsKey($liftName)) {
            # A promoted function expression has a real callable body with the
            # same tagged-Value parameter/return ABI used by the dispatcher.
            # Re-expanding only its return expression here can silently turn a
            # tagged return back into a raw i32 after parameter substitution.
            # Let normal direct-call lowering invoke the promoted function.
            return @()
        }
    }
    $params = @(Get-WasmAstParamNames ($funcExpr.params))
    if ($params.Count -ne $InputArgs.Count) { return @() }
    $body = @()
    if ($null -ne $funcExpr.body -and [string]$funcExpr.body.node -eq "SuraBlock") {
        $body = @(As-WasmAstArray ($funcExpr.body.body))
    }
    if ($body.Count -ne 1 -or [string]$body[0].node -ne "RETURN" -or $null -eq $body[0].value) {
        return @()
    }

    $paramExprs = @{}
    for ($i = 0; $i -lt $params.Count; $i++) {
        $paramExprs[[string]$params[$i]] = $InputArgs[$i]
    }

    $script:wasmInlineFunctionExprCallStack[$Name] = $true
    try {
        $returnExpr = Resolve-WasmAstInlineFunctionCallExpr ($body[0].value) $paramExprs
        return @(Convert-WasmAstExpr $returnExpr)
    } finally {
        $script:wasmInlineFunctionExprCallStack.Remove($Name)
    }
}

function Get-WasmAstKnownFunctionLiftName {
    param($Node)

    if ($null -eq $Node) { return "" }
    $specializedLift = Get-WasmAstSpecializedFunctionCallReturnHint $Node "lift"
    if (-not [string]::IsNullOrWhiteSpace($specializedLift)) { return $specializedLift }
    if ([string]$Node.node -eq "FUNC_EXPR") {
        if (Test-WasmAstFuncExprLiftSkipped $Node) { return "" }
        return (Get-WasmAstFuncExprLiftName $Node)
    }
    $inferredLift = Get-WasmAstFunctionHintFromExpr $Node "lift" $script:wasmCurrentClassContext $script:wasmCurrentLocalFunctionDisplayHints $script:wasmCurrentLocalFunctionLiftHints @{}
    if (-not [string]::IsNullOrWhiteSpace($inferredLift)) { return $inferredLift }
    if ([string]$Node.node -eq "IDENT") {
        $name = [string]$Node.name
        if ($script:wasmCurrentLocalFunctionLiftHints.ContainsKey($name)) {
            return [string]$script:wasmCurrentLocalFunctionLiftHints[$name]
        }
        if ($script:wasmGlobalFunctionLiftHints.ContainsKey($name)) {
            return [string]$script:wasmGlobalFunctionLiftHints[$name]
        }
        if ($script:wasmAstFunctionDefs.ContainsKey($name)) { return $name }
    }
    if ([string]$Node.node -eq "DOT_ACCESS") {
        $className = Get-WasmAstObjectClassTypeWithLocals ($Node.obj) $script:wasmCurrentLocalObjectClassHints $script:wasmCurrentClassContext @{}
        if (-not [string]::IsNullOrWhiteSpace($className)) {
            $fieldLift = Get-WasmAstClassFieldFunctionLiftHint $className ([string]$Node.prop)
            if (-not [string]::IsNullOrWhiteSpace($fieldLift)) { return $fieldLift }
        }
    }
    $accessKey = Get-WasmAstStringAccessHintKey $Node
    if (-not [string]::IsNullOrWhiteSpace($accessKey) -and
        -not $script:wasmConflictedAccessFunctionLiftHints.ContainsKey($accessKey) -and
        $script:wasmAccessFunctionLiftHints.ContainsKey($accessKey)) {
        return [string]$script:wasmAccessFunctionLiftHints[$accessKey]
    }
    if ([string]$Node.node -eq "TERNARY") {
        $thenName = Get-WasmAstKnownFunctionLiftName ($Node.then)
        $elseName = Get-WasmAstKnownFunctionLiftName ($Node.else)
        if (-not [string]::IsNullOrWhiteSpace($thenName) -and $thenName -eq $elseName) {
            return $thenName
        }
    }
    return ""
}

function Resolve-WasmImportPath {
    param(
        [Parameter(Mandatory=$true)][string]$ImportPath,
        [Parameter(Mandatory=$true)][string]$ImporterPath
    )
    $candidate = if ([System.IO.Path]::IsPathRooted($ImportPath)) {
        $ImportPath
    } else {
        Join-Path (Split-Path -Parent $ImporterPath) $ImportPath
    }
    if (-not (Test-Path -LiteralPath $candidate)) {
        throw "WASM target import not found: $ImportPath from $ImporterPath"
    }
    return (Resolve-Path -LiteralPath $candidate).Path
}

function Resolve-WasmEngine {
    param([string]$EnginePath)
    if ($EnginePath -and (Test-Path -LiteralPath $EnginePath)) {
        return (Resolve-Path -LiteralPath $EnginePath).Path
    }
    $root = Split-Path -Parent $PSScriptRoot
    foreach ($candidate in @((Join-Path $root "SuraLanguage.exe"), (Join-Path $root "SuraLanguage"))) {
        if (Test-Path -LiteralPath $candidate) {
            return (Resolve-Path -LiteralPath $candidate).Path
        }
    }
    throw "Sura engine not found for WASM AST import expansion"
}

function Invoke-WasmWatCompiler {
    param(
        [Parameter(Mandatory=$true)][string]$WatPath,
        [Parameter(Mandatory=$true)][string]$BinaryPath
    )

    $compiler = $null
    if (-not [string]::IsNullOrWhiteSpace($env:SURA_WAT2WASM)) {
        $candidate = [Environment]::ExpandEnvironmentVariables($env:SURA_WAT2WASM)
        if (-not (Test-Path -LiteralPath $candidate)) {
            throw "SURA_WAT2WASM does not exist: $candidate"
        }
        $compiler = (Resolve-Path -LiteralPath $candidate).Path
    } else {
        $command = Get-Command wat2wasm -ErrorAction SilentlyContinue
        if ($command) { $compiler = $command.Source }
    }

    if ($compiler) {
        & $compiler $WatPath -o $BinaryPath
    } else {
        $npx = Get-Command npx -ErrorAction SilentlyContinue
        if (-not $npx) {
            throw "wat2wasm is required to validate and emit binary WASM; install WABT, set SURA_WAT2WASM, or install Node.js/npx for the pinned WABT fallback"
        }
        & $npx.Source --yes -p wabt@1.0.39 wat2wasm $WatPath -o $BinaryPath
    }
    if ($LASTEXITCODE -ne 0 -or -not (Test-Path -LiteralPath $BinaryPath)) {
        throw "wat2wasm failed with exit code $LASTEXITCODE"
    }
}

function Unescape-SuraImportPath {
    param([string]$Path)
    return $Path.Replace('\"', '"').Replace("\\", "\")
}

function Expand-WasmSourceLines {
    param(
        [Parameter(Mandatory=$true)][string]$Path,
        [Parameter(Mandatory=$true)][hashtable]$State
    )
    $resolved = (Resolve-Path -LiteralPath $Path).Path
    if ($State.ContainsKey($resolved)) {
        if ($State[$resolved] -eq "active") {
            throw "cyclic WASM target import: $resolved"
        }
        return @("// import skipped: $resolved")
    }

    $State[$resolved] = "active"
    $out = New-Object System.Collections.Generic.List[string]
    foreach ($raw in @(Get-Content -LiteralPath $resolved)) {
        $t = $raw.Trim()
        $m = [regex]::Match($t, '^import\s+(?:"((?:\\.|[^"])*)"|''((?:\\.|[^''])*)'')\s*$')
        if ($m.Success) {
            $rawImport = if ($m.Groups[1].Success) { $m.Groups[1].Value } else { $m.Groups[2].Value }
            $importPath = Unescape-SuraImportPath $rawImport
            $importResolved = Resolve-WasmImportPath -ImportPath $importPath -ImporterPath $resolved
            $out.Add("// import $importPath") | Out-Null
            foreach ($line in (Expand-WasmSourceLines -Path $importResolved -State $State)) {
                $out.Add($line) | Out-Null
            }
            continue
        }
        $out.Add($raw) | Out-Null
    }
    $State[$resolved] = "done"
    return @($out.ToArray())
}

function Push-WasmLoopContext {
    param([switch]$ContinueToLoop)
    $id = $script:wasmLoopCounter
    $script:wasmLoopCounter++
    $loop = "__loop$id"
    $ctx = [pscustomobject]@{
        Break = "__break$id"
        Loop = $loop
        Continue = $(if ($ContinueToLoop) { $loop } else { "__continue$id" })
    }
    $script:wasmLoopStack.Add($ctx) | Out-Null
    return $ctx
}

function Pop-WasmLoopContext {
    if ($script:wasmLoopStack.Count -gt 0) {
        $script:wasmLoopStack.RemoveAt($script:wasmLoopStack.Count - 1)
    }
}

function Get-WasmLoopContext {
    if ($script:wasmLoopStack.Count -eq 0) { return $null }
    return $script:wasmLoopStack[$script:wasmLoopStack.Count - 1]
}

function Push-WasmTryContext {
    $id = $script:wasmTryCounter
    $script:wasmTryCounter++
    $ctx = [pscustomobject]@{
        End = "__try_end$id"
        Thrown = "__try_thrown$id"
        Value = "__try_value$id"
        TaggedValue = "__try_value_tagged$id"
    }
    $script:wasmTryStack.Add($ctx) | Out-Null
    return $ctx
}

function Pop-WasmTryContext {
    if ($script:wasmTryStack.Count -gt 0) {
        $script:wasmTryStack.RemoveAt($script:wasmTryStack.Count - 1)
    }
}

function Get-WasmTryContext {
    if ($script:wasmTryStack.Count -eq 0) { return $null }
    return $script:wasmTryStack[$script:wasmTryStack.Count - 1]
}

function Add-WasmAstClearExceptionState {
    param(
        [Parameter(Mandatory=$true)][System.Collections.Generic.List[string]]$Out,
        [string]$Indent = ""
    )
    $Out.Add("${Indent}i32.const 0")
    $Out.Add("${Indent}global.set `$__sura_exception_thrown")
    $Out.Add("${Indent}i32.const 0")
    $Out.Add("${Indent}global.set `$__sura_exception_value")
    $Out.Add("${Indent}i32.const 0")
    $Out.Add("${Indent}global.set `$__sura_exception_value_tagged")
}

function Add-WasmAstCallExceptionBridge {
    param(
        [Parameter(Mandatory=$true)][System.Collections.Generic.List[string]]$Out,
        [string]$Indent = ""
    )
    $tryCtx = Get-WasmTryContext
    if ($null -eq $tryCtx) { return }
    $Out.Add("${Indent}global.get `$__sura_exception_thrown")
    $Out.Add("${Indent}if")
    $Out.Add("${Indent}  global.get `$__sura_exception_value")
    $Out.Add("${Indent}  local.set `$$($tryCtx.Value)")
    $Out.Add("${Indent}  global.get `$__sura_exception_value_tagged")
    $Out.Add("${Indent}  local.set `$$($tryCtx.TaggedValue)")
    $Out.Add("${Indent}  i32.const 1")
    $Out.Add("${Indent}  local.set `$$($tryCtx.Thrown)")
    Add-WasmAstClearExceptionState -Out $Out -Indent ($Indent + "  ")
    $Out.Add("${Indent}  br `$$($tryCtx.End)")
    $Out.Add("${Indent}end")
}

function Convert-WasmAstGuardedCallResult {
    param([string[]]$CallCode)

    if ($null -eq $CallCode -or $CallCode.Count -eq 0) { return @() }

    $out = New-Object System.Collections.Generic.List[string]
    foreach ($line in $CallCode) { $out.Add([string]$line) | Out-Null }
    $out.Add("local.set `$__sura_wasm_call_tmp") | Out-Null
    $out.Add("global.get `$__sura_exception_thrown") | Out-Null
    $out.Add("if") | Out-Null

    $tryCtx = Get-WasmTryContext
    if ($null -ne $tryCtx) {
        $out.Add("  global.get `$__sura_exception_value") | Out-Null
        $out.Add("  local.set `$$($tryCtx.Value)") | Out-Null
        $out.Add("  global.get `$__sura_exception_value_tagged") | Out-Null
        $out.Add("  local.set `$$($tryCtx.TaggedValue)") | Out-Null
        $out.Add("  i32.const 1") | Out-Null
        $out.Add("  local.set `$$($tryCtx.Thrown)") | Out-Null
        $out.Add("  i32.const 0") | Out-Null
        $out.Add("  global.set `$__sura_exception_thrown") | Out-Null
        $out.Add("  i32.const 0") | Out-Null
        $out.Add("  global.set `$__sura_exception_value") | Out-Null
        $out.Add("  i32.const 0") | Out-Null
        $out.Add("  global.set `$__sura_exception_value_tagged") | Out-Null
        $out.Add("  br `$$($tryCtx.End)") | Out-Null
    } elseif ([string]$script:wasmCurrentFunctionName -eq "main" -or
              [string]::IsNullOrWhiteSpace($script:wasmCurrentFunctionName)) {
        # An uncaught exception in the exported entry point must remain observable.
        $out.Add("  unreachable") | Out-Null
    } else {
        # Keep the global payload intact and unwind one generated function frame.
        # Every user call site applies this guard, so propagation is transitive.
        $out.Add("  i32.const 0") | Out-Null
        $out.Add("  return") | Out-Null
    }

    $out.Add("end") | Out-Null
    $out.Add("local.get `$__sura_wasm_call_tmp") | Out-Null
    return @($out.ToArray())
}

function Test-WasmAstMayThrowCallExpr {
    param($Node)
    if ($null -eq $Node) { return $false }
    switch ([string]$Node.node) {
        "CALL" { return $true }
        "METHOD_CALL" { return $true }
        "SUPER_CALL" { return $true }
        "BIN_OP" { return ((Test-WasmAstMayThrowCallExpr ($Node.left)) -or (Test-WasmAstMayThrowCallExpr ($Node.right))) }
        "UNARY_OP" { return (Test-WasmAstMayThrowCallExpr ($Node.operand)) }
        "TERNARY" {
            return ((Test-WasmAstMayThrowCallExpr ($Node.cond)) -or
                (Test-WasmAstMayThrowCallExpr ($Node.then)) -or
                (Test-WasmAstMayThrowCallExpr ($Node.else)))
        }
        "DOT_ACCESS" { return (Test-WasmAstMayThrowCallExpr ($Node.obj)) }
        "INDEX" { return ((Test-WasmAstMayThrowCallExpr ($Node.obj)) -or (Test-WasmAstMayThrowCallExpr ($Node.key))) }
        "ARRAY_LIT" {
            foreach ($item in @(As-WasmAstArray ($Node.elements))) {
                if (Test-WasmAstMayThrowCallExpr $item) { return $true }
            }
            return $false
        }
        "DICT_LIT" {
            foreach ($entry in @(As-WasmAstArray ($Node.entries))) {
                if (Test-WasmAstMayThrowCallExpr ($entry.value)) { return $true }
            }
            return $false
        }
        "NEW_EXPR" {
            foreach ($arg in @(As-WasmAstArray ($Node.args))) {
                if (Test-WasmAstMayThrowCallExpr $arg) { return $true }
            }
            return $false
        }
        "STR_INTERP" {
            foreach ($part in @(As-WasmAstArray ($Node.parts))) {
                if (Test-WasmAstMayThrowCallExpr $part) { return $true }
            }
            return $false
        }
        default { return $false }
    }
}

function Tokenize-Expr {
    param([string]$Expr)
    $matches = [regex]::Matches($Expr, '\s*("(?:\\.|[^"])*"|''(?:\\.|[^''])*''|==|!=|<=|>=|<<|>>|[()\[\]+\-*/%,<>&|^~?:]|[A-Za-z_][A-Za-z0-9_]*(?:\.[A-Za-z_][A-Za-z0-9_]*)?|-?[0-9]+)')
    $out = @()
    foreach ($m in $matches) { $out += $m.Groups[1].Value }
    return $out
}

function Convert-WasmRoundedDecimalCall {
    param([string]$Expr)

    $trimmed = $Expr.Trim()
    if ($trimmed -notmatch '^(?:math\.)?(floor|ceil|round)\(\s*(-?[0-9]+)\.([0-9]+)\s*\)$') {
        return
    }

    $name = $Matches[1]
    $literalText = "$($Matches[2]).$($Matches[3])"
    $literal = [decimal]::Parse($literalText, [System.Globalization.CultureInfo]::InvariantCulture)
    $rounded = switch ($name) {
        "floor" { [System.Math]::Floor($literal) }
        "ceil"  { [System.Math]::Ceiling($literal) }
        "round" {
            if ($literal -ge 0) {
                [System.Math]::Floor($literal + [decimal]0.5)
            } else {
                [System.Math]::Ceiling($literal - [decimal]0.5)
            }
        }
    }

    "i32.const $([int]$rounded)"
}

function Convert-WasmDecimalOperand {
    param([string]$Operand)

    if ($Operand -eq "math.pi") {
        return [decimal]::Parse("3.1415926535897932384626433833", [System.Globalization.CultureInfo]::InvariantCulture)
    }
    return [decimal]::Parse($Operand, [System.Globalization.CultureInfo]::InvariantCulture)
}

function Convert-WasmDecimalComparison {
    param([string]$Expr)

    $trimmed = $Expr.Trim()
    if ($trimmed -notmatch '^(math\.pi|-?[0-9]+(?:\.[0-9]+)?)\s*(==|!=|<=|>=|<|>)\s*(math\.pi|-?[0-9]+(?:\.[0-9]+)?)$') {
        return
    }
    $leftText = $Matches[1]
    $op = $Matches[2]
    $rightText = $Matches[3]
    if ($leftText -notmatch '\.|math\.pi' -and $rightText -notmatch '\.|math\.pi') {
        return
    }

    $left = Convert-WasmDecimalOperand $leftText
    $right = Convert-WasmDecimalOperand $rightText
    $matched = switch ($op) {
        "==" { $left -eq $right }
        "!=" { $left -ne $right }
        "<"  { $left -lt $right }
        "<=" { $left -le $right }
        ">"  { $left -gt $right }
        ">=" { $left -ge $right }
    }
    $value = if ($matched) { 1 } else { 0 }
    "i32.const $value"
}

function Peek-Token {
    if ($script:pos -ge $script:tokens.Count) { return $null }
    return $script:tokens[$script:pos]
}

function Take-Token {
    $t = Peek-Token
    if ($null -ne $t) { $script:pos++ }
    return $t
}

function Match-Token {
    param([string]$Want)
    if ((Peek-Token) -eq $Want) {
        $script:pos++
        return $true
    }
    return $false
}

function Emit-Expr {
    param([Parameter(Mandatory=$true)][string]$Expr)
    $decimalComparison = @(Convert-WasmDecimalComparison -Expr $Expr)
    if ($decimalComparison.Count -gt 0) { return $decimalComparison }

    $roundedDecimal = @(Convert-WasmRoundedDecimalCall -Expr $Expr)
    if ($roundedDecimal.Count -gt 0) { return $roundedDecimal }

    $script:tokens = @(Tokenize-Expr $Expr)
    $script:pos = 0
    $code = @(Parse-Ternary)
    if ($script:pos -lt $script:tokens.Count) {
        throw "unexpected token '$($script:tokens[$script:pos])' in expression '$Expr'"
    }
    return $code
}

function Normalize-BoolCode {
    param([string[]]$Code)
    return @($Code + @("i32.eqz", "i32.eqz"))
}

function Parse-Ternary {
    $condition = @(Parse-Or)
    if (Match-Token "?") {
        $thenCode = @(Parse-Ternary)
        if (-not (Match-Token ":")) { throw "missing ':' in ternary expression" }
        $elseCode = @(Parse-Ternary)
        return @($condition + @("if (result i32)") + $thenCode + @("else") + $elseCode + @("end"))
    }
    return $condition
}

function Parse-Or {
    $left = @(Parse-And)
    while ((Peek-Token) -eq "or") {
        Take-Token | Out-Null
        $right = @(Parse-And)
        $left = @((Normalize-BoolCode -Code $left) + (Normalize-BoolCode -Code $right) + "i32.or")
    }
    return $left
}

function Parse-And {
    $left = @(Parse-Compare)
    while ((Peek-Token) -eq "and") {
        Take-Token | Out-Null
        $right = @(Parse-Compare)
        $left = @((Normalize-BoolCode -Code $left) + (Normalize-BoolCode -Code $right) + "i32.and")
    }
    return $left
}

function Parse-Compare {
    $left = @(Parse-BitOr)
    while ((Peek-Token) -in @("==","!=","<","<=",">",">=")) {
        $op = Take-Token
        $right = @(Parse-BitOr)
        $wat = switch ($op) {
            "==" { "i32.eq" }
            "!=" { "i32.ne" }
            "<"  { "i32.lt_s" }
            "<=" { "i32.le_s" }
            ">"  { "i32.gt_s" }
            ">=" { "i32.ge_s" }
        }
        $left = @($left + $right + $wat)
    }
    return $left
}

function Parse-BitOr {
    $left = @(Parse-BitXor)
    while ((Peek-Token) -eq "|") {
        Take-Token | Out-Null
        $right = @(Parse-BitXor)
        $left = @($left + $right + "i32.or")
    }
    return $left
}

function Parse-BitXor {
    $left = @(Parse-BitAnd)
    while ((Peek-Token) -eq "^") {
        Take-Token | Out-Null
        $right = @(Parse-BitAnd)
        $left = @($left + $right + "i32.xor")
    }
    return $left
}

function Parse-BitAnd {
    $left = @(Parse-Shift)
    while ((Peek-Token) -eq "&") {
        Take-Token | Out-Null
        $right = @(Parse-Shift)
        $left = @($left + $right + "i32.and")
    }
    return $left
}

function Parse-Shift {
    $left = @(Parse-Add)
    while ((Peek-Token) -in @("<<",">>")) {
        $op = Take-Token
        $right = @(Parse-Add)
        $left = @($left + $right + ($(if ($op -eq "<<") { "i32.shl" } else { "i32.shr_s" })))
    }
    return $left
}

function Parse-Add {
    $left = @(Parse-Mul)
    while ((Peek-Token) -in @("+","-")) {
        $op = Take-Token
        $right = @(Parse-Mul)
        $left = @($left + $right + ($(if ($op -eq "+") { "i32.add" } else { "i32.sub" })))
    }
    return $left
}

function Parse-Mul {
    $left = @(Parse-Unary)
    while ((Peek-Token) -in @("*","/","%")) {
        $op = Take-Token
        $right = @(Parse-Unary)
        $wat = switch ($op) {
            "*" { "i32.mul" }
            "/" { "i32.div_s" }
            "%" { "i32.rem_s" }
        }
        $left = @($left + $right + $wat)
    }
    return $left
}

function Parse-Unary {
    if (Match-Token "not") {
        return @(Parse-Unary) + @("i32.eqz")
    }
    if (Match-Token "-") {
        return @("i32.const 0") + @(Parse-Unary) + @("i32.sub")
    }
    if (Match-Token "~") {
        return @(Parse-Unary) + @("i32.const -1", "i32.xor")
    }
    return Parse-Primary
}

function Apply-WasmIndexPostfix {
    param([string[]]$BaseCode)
    $code = @($BaseCode)
    while (Match-Token "[") {
        $indexCode = @(Parse-Ternary)
        if (-not (Match-Token "]")) { throw "missing ']' in indexed expression" }
        $code = @($code + $indexCode + @("call `$__sura_array_get_checked"))
    }
    return $code
}

function New-WasmArrayLiteralExprCode {
    param([object[]]$ArgCodes)

    $count = [int]$ArgCodes.Count
    $script:wasmArrayLiteralArities[[string]$count] = $true
    $code = @()
    foreach ($argCode in $ArgCodes) { $code += @([string[]]$argCode) }
    $code += "call `$__sura_make_array_$count"
    return $code
}

function Convert-WasmStringLiteralToCodes {
    param([Parameter(Mandatory=$true)][string]$Literal)

    $inner = $Literal.Substring(1, $Literal.Length - 2)
    $codes = New-Object System.Collections.Generic.List[int]
    for ($i = 0; $i -lt $inner.Length; $i++) {
        $ch = $inner[$i]
        if ($ch -eq [char]92 -and $i + 1 -lt $inner.Length) {
            $i++
            $next = $inner[$i]
            switch ($next) {
                '"' { $codes.Add(34) | Out-Null; break }
                "\" { $codes.Add(92) | Out-Null; break }
                "/" { $codes.Add(47) | Out-Null; break }
                "b" { $codes.Add(8) | Out-Null; break }
                "f" { $codes.Add(12) | Out-Null; break }
                "n" { $codes.Add(10) | Out-Null; break }
                "r" { $codes.Add(13) | Out-Null; break }
                "t" { $codes.Add(9) | Out-Null; break }
                "u" {
                    if ($i + 4 -lt $inner.Length) {
                        $hex = $inner.Substring($i + 1, 4)
                        if ($hex -match '^[0-9a-fA-F]{4}$') {
                            $codes.Add([Convert]::ToInt32($hex, 16)) | Out-Null
                            $i += 4
                            break
                        }
                    }
                    $codes.Add([int][char]$next) | Out-Null
                    break
                }
                default { $codes.Add([int][char]$next) | Out-Null; break }
            }
            continue
        }
        $codes.Add([int][char]$ch) | Out-Null
    }
    return @($codes.ToArray())
}

function New-WasmStringLiteralExprCode {
    param([Parameter(Mandatory=$true)][string]$Literal)

    $argCodes = New-Object System.Collections.Generic.List[object]
    foreach ($code in (Convert-WasmStringLiteralToCodes -Literal $Literal)) {
        $argCodes.Add([string[]]@("i32.const $code")) | Out-Null
    }
    return New-WasmArrayLiteralExprCode -ArgCodes @($argCodes.ToArray())
}

function Get-WasmStringKeyHash {
    param([Parameter(Mandatory=$true)][string]$Key)

    $hash = [int64]0
    for ($i = 0; $i -lt $Key.Length; $i++) {
        $hash = (($hash * 131) + [int][char]$Key[$i]) % 2147483647
    }
    return [int]$hash
}

function New-WasmDictLiteralExprCode {
    param([object[]]$Entries)

    $count = [int]$Entries.Count
    $script:wasmDictLiteralArities[[string]$count] = $true
    $code = @()
    foreach ($entry in $Entries) {
        $code += "i32.const $($entry.Hash)"
        $code += @(New-WasmStringLiteralExprCode -Literal (Convert-WasmAstStringLiteral ([string]$entry.Key)))
        $code += @([string[]]$entry.ValueCode)
    }
    $code += "call `$__sura_make_dict_$count"
    return $code
}

function Add-WasmLiteralConstructorRuntime {
    param([System.Collections.Generic.List[string]]$Wat)

    foreach ($countValue in @($script:wasmArrayLiteralArities.Keys | ForEach-Object { [int]$_ } | Sort-Object -Unique)) {
        $count = [int]$countValue
        $params = @()
        for ($i = 0; $i -lt $count; $i++) { $params += "(param `$v$i i32)" }
        $Wat.Add("  (func `$__sura_make_array_$count $([string]::Join(' ', $params)) (result i32)")
        $Wat.Add("    (local `$base i32)")
        $Wat.Add("    (local `$ptr i32)")
        $Wat.Add("    i32.const $(($count + 1) * 4)")
        $Wat.Add("    call `$__sura_alloc")
        $Wat.Add("    local.set `$base")
        $Wat.Add("    local.get `$base")
        $Wat.Add("    i32.const $count")
        $Wat.Add("    i32.store")
        $Wat.Add("    local.get `$base")
        $Wat.Add("    i32.const 4")
        $Wat.Add("    i32.add")
        $Wat.Add("    local.set `$ptr")
        for ($i = 0; $i -lt $count; $i++) {
            $Wat.Add("    local.get `$ptr")
            $Wat.Add("    i32.const $($i * 4)")
            $Wat.Add("    i32.add")
            $Wat.Add("    local.get `$v$i")
            $Wat.Add("    i32.store")
        }
        $Wat.Add("    local.get `$ptr")
        $Wat.Add("  )")
    }

    foreach ($countValue in @($script:wasmDictLiteralArities.Keys | ForEach-Object { [int]$_ } | Sort-Object -Unique)) {
        $count = [int]$countValue
        $params = @()
        for ($i = 0; $i -lt $count; $i++) {
            $params += "(param `$hash$i i32)"
            $params += "(param `$key$i i32)"
            $params += "(param `$value$i i32)"
        }
        $Wat.Add("  (func `$__sura_make_dict_$count $([string]::Join(' ', $params)) (result i32)")
        $Wat.Add("    (local `$base i32)")
        $Wat.Add("    (local `$ptr i32)")
        $Wat.Add("    i32.const $((($count * 3) + 1) * 4)")
        $Wat.Add("    call `$__sura_alloc")
        $Wat.Add("    local.set `$base")
        $Wat.Add("    local.get `$base")
        $Wat.Add("    i32.const $count")
        $Wat.Add("    i32.store")
        $Wat.Add("    local.get `$base")
        $Wat.Add("    i32.const 4")
        $Wat.Add("    i32.add")
        $Wat.Add("    local.set `$ptr")
        for ($i = 0; $i -lt $count; $i++) {
            $offset = $i * 12
            foreach ($field in @(
                @{ Offset = $offset; Name = "hash$i" },
                @{ Offset = $offset + 4; Name = "key$i" },
                @{ Offset = $offset + 8; Name = "value$i" }
            )) {
                $Wat.Add("    local.get `$ptr")
                $Wat.Add("    i32.const $($field.Offset)")
                $Wat.Add("    i32.add")
                $Wat.Add("    local.get `$$($field.Name)")
                $Wat.Add("    i32.store")
            }
        }
        $Wat.Add("    local.get `$ptr")
        $Wat.Add("  )")
    }
}

function Join-WasmArgCodes {
    param([object[]]$ArgCodes)
    $out = @()
    foreach ($code in $ArgCodes) { $out += @([string[]]$code) }
    return $out
}

function Need-WasmIntrinsicArgs {
    param([string]$Name, [object[]]$ArgCodes, [int]$Count)
    if ($ArgCodes.Count -ne $Count) {
        throw "$Name requires $Count numeric argument(s)"
    }
}

function Need-WasmIntrinsicMinArgs {
    param([string]$Name, [object[]]$ArgCodes, [int]$MinCount)
    if ($ArgCodes.Count -lt $MinCount) {
        throw "$Name requires at least $MinCount numeric argument(s)"
    }
}

function Test-WasmConsoleOutputName {
    param([string]$Name)
    return @(
        "console_log", "console_print", "console_write", "console_write_line",
        "console_writeln", "console_println", "console_line",
        "console_info", "console_debug", "console_warn", "console_warning",
        "console_error", "console_exception",
        "console.log", "console.print", "console.write", "console.write_line",
        "console.writeln", "console.println", "console.line",
        "console.info", "console.debug", "console.warn", "console.warning",
        "console.error", "console.exception"
    ) -contains $Name
}

function Convert-WasmSourceConsoleArgToStringExpr {
    param([string]$Expr)

    $text = $Expr.Trim()
    if ($text -match '^(?:"(?:\\.|[^"])*"|''(?:\\.|[^''])*'')$') {
        return @(Emit-Expr $text)
    }
    if ($text -eq "true" -or $text -eq "false" -or $text -eq "nil") {
        return @(New-WasmAstLiteralStringExprCode $text)
    }
    return @(Emit-Expr $text) + @("call `$__sura_i32_to_string")
}

function Convert-WasmSourceConsoleArgsToStringExpr {
    param([string[]]$InputArgs)

    $parts = New-Object System.Collections.Generic.List[object]
    for ($i = 0; $i -lt $InputArgs.Count; $i++) {
        if ($i -gt 0) { $parts.Add([string[]]@(New-WasmAstLiteralStringExprCode " ")) | Out-Null }
        $parts.Add([string[]]@(Convert-WasmSourceConsoleArgToStringExpr $InputArgs[$i])) | Out-Null
    }
    return @(Join-WasmAstStringExprCodes @($parts.ToArray()))
}

function New-WasmMinCode {
    param([string[]]$A, [string[]]$B)
    return @($A + $B + $A + $B + "i32.lt_s" + "select")
}

function New-WasmMaxCode {
    param([string[]]$A, [string[]]$B)
    return @($A + $B + $A + $B + "i32.gt_s" + "select")
}

function New-WasmFoldMinCode {
    param([object[]]$ArgCodes)
    $code = @([string[]]$ArgCodes[0])
    for ($i = 1; $i -lt $ArgCodes.Count; $i++) {
        $code = @(New-WasmMinCode -A $code -B ([string[]]$ArgCodes[$i]))
    }
    return $code
}

function New-WasmFoldMaxCode {
    param([object[]]$ArgCodes)
    $code = @([string[]]$ArgCodes[0])
    for ($i = 1; $i -lt $ArgCodes.Count; $i++) {
        $code = @(New-WasmMaxCode -A $code -B ([string[]]$ArgCodes[$i]))
    }
    return $code
}

function New-WasmAbsCode {
    param([string[]]$X)
    return @($X + @("i32.const 0") + $X + @("i32.sub") + $X + @("i32.const 0", "i32.ge_s", "select"))
}

function New-WasmSignCode {
    param([string[]]$X)
    return @($X + @("i32.const 0", "i32.gt_s") + $X + @("i32.const 0", "i32.lt_s", "i32.sub"))
}

function Emit-WasmIntrinsicCall {
    param([string]$Name, [object[]]$ArgCodes)

    if (Is-WasmRejectedBuiltinName $Name) {
        Throw-WasmRejectedBuiltin $Name
    }

    switch ($Name) {
        { $_ -in @("vec3", "vector3", "vector.vec3", "vector.vector3") } {
            Need-WasmIntrinsicArgs $Name $ArgCodes 3
            return @(New-WasmArrayLiteralExprCode -ArgCodes @($ArgCodes))
        }
        { $_ -in @("vec3_add", "vector3_add", "vector.add3", "vector.vec3_add", "vector.vector3_add") } {
            Need-WasmIntrinsicArgs $Name $ArgCodes 2
            return @((Join-WasmArgCodes -ArgCodes @($ArgCodes))) + @("call `$__sura_vec3_add")
        }
        { $_ -in @("vec3_sub", "vector3_sub", "vector.sub3", "vector.vec3_sub", "vector.vector3_sub") } {
            Need-WasmIntrinsicArgs $Name $ArgCodes 2
            return @((Join-WasmArgCodes -ArgCodes @($ArgCodes))) + @("call `$__sura_vec3_sub")
        }
        { $_ -in @("vec3_dot", "vector3_dot", "vector.dot3", "vector.vec3_dot", "vector.vector3_dot") } {
            Need-WasmIntrinsicArgs $Name $ArgCodes 2
            return @((Join-WasmArgCodes -ArgCodes @($ArgCodes))) + @("call `$__sura_vec3_dot")
        }
        { $_ -in @("vec3_cross", "vector3_cross", "vector.cross", "vector.vec3_cross", "vector.vector3_cross") } {
            Need-WasmIntrinsicArgs $Name $ArgCodes 2
            return @((Join-WasmArgCodes -ArgCodes @($ArgCodes))) + @("call `$__sura_vec3_cross")
        }
        { $_ -in @("vec3_scale", "vector3_scale", "vector.scale3", "vector.vec3_scale", "vector.vector3_scale") } {
            Need-WasmIntrinsicArgs $Name $ArgCodes 2
            return @((Join-WasmArgCodes -ArgCodes @($ArgCodes))) + @("call `$__sura_vec3_scale")
        }
        { $_ -in @("vec3_norm", "vector3_norm", "vector.norm3", "vector.vec3_norm", "vector.vector3_norm") } {
            Need-WasmIntrinsicArgs $Name $ArgCodes 1
            return @((Join-WasmArgCodes -ArgCodes @($ArgCodes))) + @("call `$__sura_vec3_norm")
        }
        { $_ -in @("vec3_distance", "vector3_distance", "vector.distance3", "vector.vec3_distance", "vector.vector3_distance") } {
            Need-WasmIntrinsicArgs $Name $ArgCodes 2
            return @((Join-WasmArgCodes -ArgCodes @($ArgCodes))) + @("call `$__sura_vec3_distance")
        }
        { $_ -in @("array.len", "array.length", "array.size", "array_len", "array_length", "array_size") } {
            Need-WasmIntrinsicArgs $Name $ArgCodes 1
            return @([string[]]$ArgCodes[0]) + @("i32.const 4", "i32.sub", "i32.load")
        }
        { $_ -in @("array.sum", "array_sum") } {
            Need-WasmIntrinsicArgs $Name $ArgCodes 1
            return @((Join-WasmArgCodes -ArgCodes @($ArgCodes))) + @("call `$__sura_array_sum")
        }
        { $_ -in @("array.avg", "array.average", "array_avg", "array_average") } {
            Need-WasmIntrinsicArgs $Name $ArgCodes 1
            return @((Join-WasmArgCodes -ArgCodes @($ArgCodes))) + @("call `$__sura_array_avg")
        }
        { $_ -in @("array.min", "array_min") } {
            Need-WasmIntrinsicArgs $Name $ArgCodes 1
            return @((Join-WasmArgCodes -ArgCodes @($ArgCodes))) + @("call `$__sura_array_min")
        }
        { $_ -in @("array.max", "array_max") } {
            Need-WasmIntrinsicArgs $Name $ArgCodes 1
            return @((Join-WasmArgCodes -ArgCodes @($ArgCodes))) + @("call `$__sura_array_max")
        }
        { $_ -in @("array.range", "array_range") } {
            if ($ArgCodes.Count -eq 1) {
                return @("i32.const 0") + @([string[]]$ArgCodes[0]) + @("i32.const 1", "call `$__sura_array_range")
            }
            if ($ArgCodes.Count -eq 2) {
                return @([string[]]$ArgCodes[0]) + @([string[]]$ArgCodes[1]) + @("i32.const 1", "call `$__sura_array_range")
            }
