function Parse-Primary {
    $t = Take-Token
    if ($null -eq $t) { throw "unexpected end of expression" }
    if ($t -match '^-?[0-9]+$') { return @("i32.const $t") }
    if ($t -match '^(?:"(?:\\.|[^"])*"|''(?:\\.|[^''])*'')$') {
        return Apply-WasmIndexPostfix -BaseCode @(New-WasmStringLiteralExprCode -Literal $t)
    }
    if ($t -eq "true") { return @("i32.const 1") }
    if ($t -eq "false") { return @("i32.const 0") }
    if ($t -eq "nil") { return @("i32.const 0") }
    if ($t -eq "math.pi") { return @("i32.const 3") }
    if ($t -eq "(") {
        $inner = @(Parse-Ternary)
        if (-not (Match-Token ")")) { throw "missing ')' in expression" }
        return Apply-WasmIndexPostfix -BaseCode $inner
    }
    if ($t -eq "[") {
        $argCodes = New-Object System.Collections.Generic.List[object]
        if ((Peek-Token) -ne "]") {
            do { $argCodes.Add([string[]]@(Parse-Ternary)) | Out-Null } while (Match-Token ",")
        }
        if (-not (Match-Token "]")) { throw "missing ']' after array literal" }
        return Apply-WasmIndexPostfix -BaseCode @(New-WasmArrayLiteralExprCode -ArgCodes @($argCodes.ToArray()))
    }
    if ($t -match '^[A-Za-z_][A-Za-z0-9_]*(?:\.[A-Za-z_][A-Za-z0-9_]*)?$') {
        if (Match-Token "(") {
            $argCodes = New-Object System.Collections.Generic.List[object]
            if ((Peek-Token) -ne ")") {
                do { $argCodes.Add([string[]]@(Parse-Ternary)) | Out-Null } while (Match-Token ",")
            }
            if (-not (Match-Token ")")) { throw "missing ')' after call" }
            if ($t -match '^([A-Za-z_][A-Za-z0-9_]*)\.len$' -and $Matches[1] -ne "array") {
                if ($argCodes.Count -ne 0) { throw "$t requires no numeric argument(s)" }
                return @("local.get `$$($Matches[1])", "i32.const 4", "i32.sub", "i32.load")
            }
            $intrinsic = Emit-WasmIntrinsicCall -Name $t -ArgCodes @($argCodes.ToArray())
            if ($null -ne $intrinsic) { return Apply-WasmIndexPostfix -BaseCode @($intrinsic) }
            if ($t -match '\.') { throw "unsupported WASM module call: $t" }
            return Apply-WasmIndexPostfix -BaseCode (@((Join-WasmArgCodes -ArgCodes @($argCodes.ToArray()))) + @("call `$$t"))
        }
        if ($script:wasmEnumConsts.ContainsKey($t)) {
            return @("i32.const $($script:wasmEnumConsts[$t])")
        }
        if ($script:wasmEnumStringConsts.ContainsKey($t)) {
            return Apply-WasmIndexPostfix -BaseCode @(New-WasmStringLiteralExprCode -Literal (Convert-WasmAstStringLiteral ($script:wasmEnumStringConsts[$t])))
        }
        if ($t -match '\.') { throw "unsupported WASM dotted identifier: $t" }
        return Apply-WasmIndexPostfix -BaseCode @("local.get `$$t")
    }
    throw "unexpected token '$t'"
}

function Opens-Block {
    param([string]$Line)
    $t = $Line.Trim()
    return ($t -match '^if\b.*\bthen\s*$') -or
           ($t -match '^when\b.*\bdo\s*$') -or
           ($t -match '^match\b.+$') -or
           ($t -match '^(while|repeat|for)\b.*\bdo\s*$') -or
           ($t -match '^func\b.*\bdo\s*$')
}

function Collect-Locals {
    param([string[]]$Lines, [string[]]$Params)
    $locals = @{}
    $inEnum = $false
    foreach ($p in $Params) {
        if ($p.Trim()) { $locals[$p.Trim()] = "param" }
    }
    function Add-WasmLocal {
        param([string]$Name)
        if (-not $locals.ContainsKey($Name)) { $locals[$Name] = "local" }
    }
    function Add-WasmLocalsFromStatement {
        param([string]$Statement)
        $s = $Statement.Trim()
        if (-not $s) { return }
        if ($s -match '^([A-Za-z_][A-Za-z0-9_]*)\s*(?::\s*[^=]+?)?\s+is\b') { Add-WasmLocal $Matches[1] }
        if ($s -match '^([A-Za-z_][A-Za-z0-9_]*)\s*(\+=|-=|\*=|/=|%=)') { Add-WasmLocal $Matches[1] }
        if ($s -match '^for\s+([A-Za-z_][A-Za-z0-9_]*)\s*,\s*([A-Za-z_][A-Za-z0-9_]*)\s+in\s+') {
            Add-WasmLocal $Matches[1]
            Add-WasmLocal $Matches[2]
        } elseif ($s -match '^for\s+([A-Za-z_][A-Za-z0-9_]*)\s+in\s+') {
            Add-WasmLocal $Matches[1]
        }
        if ($s -match '\bthen\s+(.+)$') { Add-WasmLocalsFromStatement $Matches[1] }
    }
    foreach ($line in $Lines) {
        $t = $line.Trim()
        if ($inEnum) {
            if ($t -eq "end") { $inEnum = $false }
            continue
        }
        if ($t -match '^enum\s+[A-Za-z_][A-Za-z0-9_]*\s+do$') {
            $inEnum = $true
            continue
        }
        Add-WasmLocalsFromStatement $t
    }
    return $locals
}

function Get-WasmParamName {
    param([Parameter(Mandatory=$true)][string]$Param)

    $p = $Param.Trim()
    if ($p -match '^([A-Za-z_][A-Za-z0-9_]*)(?:\s*:\s*[^=]+?)?(?:\s+is\s+.+)?$') {
        return $Matches[1]
    }
    throw "unsupported WASM parameter syntax: $Param"
}

function Add-Code {
    param([System.Collections.Generic.List[string]]$Out, [string[]]$Code, [string]$Indent)
    foreach ($line in $Code) { $Out.Add("$Indent$line") }
}

function Get-WasmGlobalName {
    param([Parameter(Mandatory=$true)][string]$Name)
    return "__sura_global_$Name"
}

function Test-WasmAstModuleGlobalInScope {
    param([Parameter(Mandatory=$true)][string]$Name)
    if ([string]::IsNullOrWhiteSpace($Name)) { return $false }
    if (-not $script:wasmModuleGlobals.ContainsKey($Name)) { return $false }
    if ($script:wasmCurrentFunctionName -eq "main") { return $true }
    return $script:wasmCurrentGlobalDecls.ContainsKey($Name)
}

function Convert-WasmAstNameLoad {
    param([Parameter(Mandatory=$true)][string]$Name)
    if (Test-WasmAstModuleGlobalInScope $Name) {
        $globalName = Get-WasmGlobalName $Name
        return @("global.get `$$globalName")
    }
    return @("local.get `$$Name")
}

function Add-WasmAstNameStore {
    param(
        [Parameter(Mandatory=$true)][System.Collections.Generic.List[string]]$Out,
        [string]$Indent,
        [Parameter(Mandatory=$true)][string]$Name
    )
    if (Test-WasmAstModuleGlobalInScope $Name) {
        $globalName = Get-WasmGlobalName $Name
        $Out.Add("${Indent}global.set `$$globalName")
        return
    }
    $Out.Add("${Indent}local.set `$$Name")
}

function Add-WasmArrayLiteralAssignment {
    param(
        [string]$Name,
        [string]$ElementText,
        [System.Collections.Generic.List[string]]$Out,
        [string]$Indent
    )
    $items = @()
    if (-not [string]::IsNullOrWhiteSpace($ElementText)) {
        $items = @(Split-WasmArgs $ElementText)
    }
    $bytes = ($items.Count + 1) * 4
    $Out.Add("${Indent}i32.const $bytes")
    $Out.Add("${Indent}call `$__sura_alloc")
    $Out.Add("${Indent}local.set `$$Name")
    $Out.Add("${Indent}local.get `$$Name")
    $Out.Add("${Indent}i32.const $($items.Count)")
    $Out.Add("${Indent}i32.store")
    $Out.Add("${Indent}local.get `$$Name")
    $Out.Add("${Indent}i32.const 4")
    $Out.Add("${Indent}i32.add")
    $Out.Add("${Indent}local.set `$$Name")
    for ($i = 0; $i -lt $items.Count; $i++) {
        $Out.Add("${Indent}local.get `$$Name")
        $Out.Add("${Indent}i32.const $($i * 4)")
        $Out.Add("${Indent}i32.add")
        Add-Code $Out @(Emit-Expr $items[$i]) $Indent
        $Out.Add("${Indent}i32.store")
    }
}

function Add-WasmArrayStore {
    param(
        [string]$Name,
        [string]$IndexExpr,
        [string]$ValueExpr,
        [System.Collections.Generic.List[string]]$Out,
        [string]$Indent
    )
    $Out.Add("${Indent}local.get `$$Name")
    Add-Code $Out @(Emit-Expr $IndexExpr) $Indent
    $Out.Add("${Indent}i32.const 4")
    $Out.Add("${Indent}i32.mul")
    $Out.Add("${Indent}i32.add")
    Add-Code $Out @(Emit-Expr $ValueExpr) $Indent
    $Out.Add("${Indent}i32.store")
}

function Indent-AtDepth {
    param([string]$Base, [int]$Depth)
    return $Base + ("  " * $Depth)
}

function Split-WasmArgs {
    param([string]$Text)
    $args = New-Object System.Collections.Generic.List[string]
    $depth = 0
    $bracketDepth = 0
    $start = 0
    for ($i = 0; $i -lt $Text.Length; $i++) {
        $ch = $Text[$i]
        if ($ch -eq '(') {
            $depth++
        } elseif ($ch -eq ')') {
            if ($depth -gt 0) { $depth-- }
        } elseif ($ch -eq '[') {
            $bracketDepth++
        } elseif ($ch -eq ']') {
            if ($bracketDepth -gt 0) { $bracketDepth-- }
        } elseif ($ch -eq ',' -and $depth -eq 0 -and $bracketDepth -eq 0) {
            $args.Add($Text.Substring($start, $i - $start).Trim()) | Out-Null
            $start = $i + 1
        }
    }
    if ($start -le $Text.Length) {
        $tail = $Text.Substring($start).Trim()
        if ($tail) { $args.Add($tail) | Out-Null }
    }
    return @($args)
}

function Compile-AssertStatement {
    param(
        [string]$Name,
        [string]$ArgText,
        [System.Collections.Generic.List[string]]$Out,
        [string]$Indent
    )
    $args = @(Split-WasmArgs $ArgText)
    if ($Name -eq "assert") {
        if ($args.Count -lt 1) { throw "assert requires a condition" }
        Add-Code $Out @(Emit-Expr $args[0]) $Indent
        $Out.Add("${Indent}i32.eqz")
    } elseif ($Name -eq "assert_between") {
        if ($args.Count -lt 3) { throw "assert_between requires value, min, and max numeric expressions" }
        Add-Code $Out @(Emit-Expr $args[0]) $Indent
        Add-Code $Out @(Emit-Expr $args[1]) $Indent
        $Out.Add("${Indent}i32.lt_s")
        Add-Code $Out @(Emit-Expr $args[0]) $Indent
        Add-Code $Out @(Emit-Expr $args[2]) $Indent
        $Out.Add("${Indent}i32.gt_s")
        $Out.Add("${Indent}i32.or")
    } elseif ($Name -eq "assert_approx") {
        if ($args.Count -lt 2) { throw "assert_approx requires actual and expected numeric expressions" }
        $diff = @((Emit-Expr $args[0]) + (Emit-Expr $args[1]) + "i32.sub")
        Add-Code $Out @(New-WasmAbsCode -X $diff) $Indent
        if ($args.Count -ge 3) {
            Add-Code $Out @(Emit-Expr $args[2]) $Indent
        } else {
            $Out.Add("${Indent}i32.const 0")
        }
        $Out.Add("${Indent}i32.gt_s")
    } else {
        if ($args.Count -lt 2) { throw "$Name requires two numeric expressions" }
        Add-Code $Out @(Emit-Expr $args[0]) $Indent
        Add-Code $Out @(Emit-Expr $args[1]) $Indent
        if ($Name -eq "assert_eq") {
            $Out.Add("${Indent}i32.ne")
        } else {
            $Out.Add("${Indent}i32.eq")
        }
    }
    $Out.Add("${Indent}if")
    $Out.Add("${Indent}  unreachable")
    $Out.Add("${Indent}end")
}

function Is-WasmRejectedBuiltinName {
    param([string]$Name)
    return @(
        "input",
        "exit",
        "random",
        "random_seed",
        "random_int",
        "random_float",
        "random_bool",
        "random_choice",
        "random_shuffle",
        "random_bytes",
        "random_uuid",
        "random.seed",
        "random.int",
        "random.float",
        "random.bool",
        "random.choice",
        "random.shuffle",
        "random.bytes",
        "random.uuid",
        "console_raw",
        "console_flush",
        "console_json",
        "console_inspect",
        "console_hrtime",
        "console_beep",
        "console_status",
        "console.raw",
        "console.flush",
        "console.json",
        "console.inspect",
        "console.hrtime",
        "console.beep",
        "console.status"
    ) -contains $Name
}

function Throw-WasmRejectedBuiltin {
    param([string]$Name)
    throw ("unsupported WASM builtin '{0}': WASM numeric target explicitly rejects host-interactive/random command builtins; use the native or JS target" -f $Name)
}

function New-WasmWhenCondition {
    param(
        [string]$Subject,
        [string]$Kind,
        [string]$Value,
        [string]$RangeEnd = ""
    )
    if ($Kind -eq "is") {
        return @("local.get `$$Subject") + @(Emit-Expr $Value) + @("i32.eq")
    }
    if ($Kind -eq "in") {
        return @(
            @("local.get `$$Subject") + @(Emit-Expr $Value) + @("i32.ge_s") +
            @("local.get `$$Subject") + @(Emit-Expr $RangeEnd) + @("i32.le_s") +
            @("i32.and")
        )
    }
    throw "unsupported WASM when arm kind: $Kind"
}

function New-WasmMatchCondition {
    param(
        [string]$Subject,
        [string]$Pattern
    )
    return @("local.get `$$Subject") + @(Emit-Expr $Pattern) + @("i32.eq")
}

function Compile-Statement {
    param(
        [string]$Line,
        [System.Collections.Generic.List[string]]$Out,
        [string]$Indent,
        [switch]$Main
    )
    $t = $Line.Trim()
    if ($t -match '^([A-Za-z_][A-Za-z0-9_]*(?:\.[A-Za-z_][A-Za-z0-9_]*)?)\b' -and (Is-WasmRejectedBuiltinName $Matches[1])) {
        Throw-WasmRejectedBuiltin $Matches[1]
    }
    if ($t -match '^(assert|assert_eq|assert_ne|assert_neq|assert_between|assert_approx)\s*\((.*)\)$') {
        $name = $Matches[1]
        if ($name -eq "assert_neq") { $name = "assert_ne" }
        Compile-AssertStatement $name $Matches[2] $Out $Indent
        return
    }
    if ($t -match '^(assert|assert_eq|assert_ne|assert_neq|assert_between|assert_approx)\s+(.+)$') {
        $name = $Matches[1]
        if ($name -eq "assert_neq") { $name = "assert_ne" }
        Compile-AssertStatement $name $Matches[2] $Out $Indent
        return
    }
    if ($t -match '^return\s+(.+)$') {
        Add-Code $Out @(Emit-Expr $Matches[1]) $Indent
        $Out.Add("${Indent}return")
        return
    }
    if ($t -eq "return") {
        $Out.Add("${Indent}i32.const 0")
        $Out.Add("${Indent}return")
        return
    }
    if ($t -match '^throw(?:\s+.+)?$') {
        $Out.Add("${Indent}unreachable")
        return
    }
    if ($t -match '^print(?:_n|_no_nl)?\s+(.+)$') {
        Add-Code $Out @(Emit-Expr $Matches[1]) $Indent
        $Out.Add("${Indent}local.set `$__result")
        return
    }
    if ($t -match '^print(?:_n|_no_nl)?\s*\((.*)\)$') {
        $args = @(Split-WasmArgs $Matches[1])
        if ($args.Count -ne 1) { throw "WASM print/print_n/print_no_nl() requires exactly one numeric expression" }
        Add-Code $Out @(Emit-Expr $args[0]) $Indent
        $Out.Add("${Indent}local.set `$__result")
        return
    }
    if ($t -match '^([A-Za-z_][A-Za-z0-9_]*(?:\.[A-Za-z_][A-Za-z0-9_]*)?)\s*\((.*)\)$' -and (Test-WasmConsoleOutputName $Matches[1])) {
        $args = @(Split-WasmArgs $Matches[2])
        Add-Code $Out @(Convert-WasmSourceConsoleArgsToStringExpr ([string[]]$args)) $Indent
        if ($Main) { $Out.Add("${Indent}local.set `$__result") } else { $Out.Add("${Indent}drop") }
        return
    }
    if ($t -eq "break" -or $t -eq "continue") {
        $ctx = Get-WasmLoopContext
        if ($null -eq $ctx) { throw "$t outside loop" }
        $label = $(if ($t -eq "break") { $ctx.Break } else { $ctx.Continue })
        $Out.Add("${Indent}br `$$label")
        return
    }
    if ($t -match '^([A-Za-z_][A-Za-z0-9_]*)\s*\[(.+)\]\s*(?:is|=)\s*(.+)$') {
        Add-WasmArrayStore $Matches[1] $Matches[2] $Matches[3] $Out $Indent
        return
    }
    if ($t -match '^([A-Za-z_][A-Za-z0-9_]*)\s*(?::\s*[^=]+?)?\s+is\s+(.+)$') {
        $name = $Matches[1]
        $rhs = $Matches[2].Trim()
        if ($rhs -match '^\[(.*)\]$') {
            Add-WasmArrayLiteralAssignment $name $Matches[1] $Out $Indent
        } else {
            Add-Code $Out @(Emit-Expr $rhs) $Indent
            $Out.Add("${Indent}local.set `$$name")
        }
        return
    }
    if ($t -match '^([A-Za-z_][A-Za-z0-9_]*)\s*(\+=|-=|\*=|/=|%=)\s*(.+)$') {
        $name = $Matches[1]
        $op = switch ($Matches[2]) {
            "+=" { "i32.add" }
            "-=" { "i32.sub" }
            "*=" { "i32.mul" }
            "/=" { "i32.div_s" }
            "%=" { "i32.rem_s" }
        }
        $Out.Add("${Indent}local.get `$$name")
        Add-Code $Out @(Emit-Expr $Matches[3]) $Indent
        $Out.Add("${Indent}$op")
        $Out.Add("${Indent}local.set `$$name")
        return
    }
    if ($t -match '^([A-Za-z_][A-Za-z0-9_]*)\s*\((.*)\)$') {
        Add-Code $Out @(Emit-Expr $t) $Indent
        $Out.Add("${Indent}drop")
        return
    }
    if ($t -match '^(?:-?[0-9]+|true\b|false\b|nil\b|\(|\[|[A-Za-z_][A-Za-z0-9_]*(?:\.[A-Za-z_][A-Za-z0-9_]*)?)') {
        try {
            Add-Code $Out @(Emit-Expr $t) $Indent
            $Out.Add("${Indent}drop")
            return
        } catch {
            if (-not $AllowUnsupported) {
                throw "unsupported WASM statement: $t"
            }
        }
    }
    if ($AllowUnsupported) {
        $Out.Add("${Indent};; unsupported: $t")
        return
    }
    throw "unsupported WASM statement: $t"
}

function Compile-Lines {
    param(
        [string[]]$Lines,
        [ref]$Index,
        [System.Collections.Generic.List[string]]$Out,
        [string]$Indent,
        [switch]$Main
    )
    while ($Index.Value -lt $Lines.Count) {
        $t = $Lines[$Index.Value].Trim()
        $Index.Value++
        if ($t -eq "" -or $t.StartsWith("#") -or $t.StartsWith("//") -or $t -match '^use\s+[A-Za-z_][A-Za-z0-9_]*$') { continue }
        if ($t -eq "end" -or $t -eq "else" -or $t -match '^elif\s+.+\s+then(?:\s+.+)?$') {
            $Index.Value--
            return
        }
        if ($t -match '^(is\s+.+|in\s+.+\s+(?:to|~)\s+.+|else|when\s+.+)\s+then(?:\s+.+)?$') {
            $Index.Value--
            return
        }
        if ($t -match '^when\s+.+$' -and $t -notmatch '\s+do$') {
            $Index.Value--
            return
        }
        if ($t -match '^enum\s+([A-Za-z_][A-Za-z0-9_]*)\s+do$') {
            $enumName = $Matches[1]
            $Out.Add("${Indent};; numeric enum declarations: $enumName")
            while ($Index.Value -lt $Lines.Count) {
                $member = $Lines[$Index.Value].Trim()
                $Index.Value++
                if ($member -eq "" -or $member.StartsWith("#") -or $member.StartsWith("//")) { continue }
                if ($member -eq "end") { break }
                if ($member -notmatch '^([A-Za-z_][A-Za-z0-9_]*)(?:\s+is\s+(.+))?$') {
                    throw "unsupported WASM enum member: $member"
                }
                if (-not $Matches[2]) {
                    throw "WASM numeric enum member requires an explicit numeric value: $member"
                }
                $memberName = $Matches[1]
                $value = $Matches[2].Trim()
                if ($value -notmatch '^-?[0-9]+$') {
                    throw "WASM numeric enum member requires an integer literal value: $member"
                }
                $script:wasmEnumConsts["$enumName.$memberName"] = $value
            }
        } elseif ($t -match '^if\s+(.+)\s+then\s+(.+)$') {
            Add-Code $Out @(Emit-Expr $Matches[1]) $Indent
            $Out.Add("${Indent}if")
            $Out.Add("${Indent}  ;; inline then")
            Compile-Statement $Matches[2] $Out ($Indent + "  ") -Main:$Main
            $Out.Add("${Indent}end")
        } elseif ($t -match '^if\s+(.+)\s+then$') {
            Add-Code $Out @(Emit-Expr $Matches[1]) $Indent
            $Out.Add("${Indent}if")
            Compile-Lines $Lines $Index $Out ($Indent + "  ") -Main:$Main
            $nestedIfs = 0
            while ($Index.Value -lt $Lines.Count -and $Lines[$Index.Value].Trim() -match '^elif\s+(.+?)\s+then(?:\s+(.+))?$') {
                $elifCond = $Matches[1]
                $elifInline = $Matches[2]
                $elseIndent = Indent-AtDepth $Indent $nestedIfs
                $Index.Value++
                $Out.Add("${elseIndent}else")
                Add-Code $Out @(Emit-Expr $elifCond) ($elseIndent + "  ")
                $Out.Add("${elseIndent}  if")
                $nestedIfs++
                if ($elifInline) {
                    $Out.Add("${elseIndent}    ;; inline elif then")
                    Compile-Statement $elifInline $Out ($elseIndent + "    ") -Main:$Main
                } else {
                    Compile-Lines $Lines $Index $Out ($elseIndent + "    ") -Main:$Main
                }
            }
            if ($Index.Value -lt $Lines.Count -and $Lines[$Index.Value].Trim() -match '^else(?:\s+then(?:\s+(.+))?)?$') {
                $elseInline = $Matches[1]
                $elseIndent = Indent-AtDepth $Indent $nestedIfs
                $Index.Value++
                $Out.Add("${elseIndent}else")
                if ($elseInline) {
                    $Out.Add("${elseIndent}  ;; inline else then")
                    Compile-Statement $elseInline $Out ($elseIndent + "  ") -Main:$Main
                } else {
                    Compile-Lines $Lines $Index $Out ($elseIndent + "  ") -Main:$Main
                }
            }
            if ($Index.Value -lt $Lines.Count -and $Lines[$Index.Value].Trim() -eq "end") { $Index.Value++ }
            for ($closeDepth = $nestedIfs; $closeDepth -ge 0; $closeDepth--) {
                $Out.Add("$(Indent-AtDepth $Indent $closeDepth)end")
            }
        } elseif ($t -match '^when\s+(.+)\s+do$') {
            $subject = "__when$script:hiddenCounter"
            $matched = "__when_matched$script:hiddenCounter"
            $script:hiddenCounter++
            $Out.Insert(0, "    (local `$$subject i32)")
            $Out.Insert(0, "    (local `$$matched i32)")
            Add-Code $Out @(Emit-Expr $Matches[1]) $Indent
            $Out.Add("${Indent}local.set `$$subject")
            $Out.Add("${Indent}i32.const 0")
            $Out.Add("${Indent}local.set `$$matched")

            $armStarted = $false
            $elseSeen = $false
            while ($Index.Value -lt $Lines.Count) {
                $arm = $Lines[$Index.Value].Trim()
                if ($arm -eq "" -or $arm.StartsWith("#") -or $arm.StartsWith("//")) {
                    $Index.Value++
                    continue
                }
                if ($arm -eq "end") {
                    $Index.Value++
                    break
                }

                $kind = ""
                $value = ""
                $rangeEnd = ""
                $inline = ""
                if ($arm -match '^is\s+(.+?)\s+then(?:\s+(.+))?$') {
                    $kind = "is"
                    $value = $Matches[1]
                    $inline = $Matches[2]
                } elseif ($arm -match '^in\s+(.+?)\s+(?:to|~)\s+(.+?)\s+then(?:\s+(.+))?$') {
                    $kind = "in"
                    $value = $Matches[1]
                    $rangeEnd = $Matches[2]
                    $inline = $Matches[3]
                } elseif ($arm -match '^else\s+then(?:\s+(.+))?$') {
                    $kind = "else"
                    $inline = $Matches[1]
                } else {
                    throw "unsupported WASM when arm: $arm"
                }
                $Index.Value++

                if ($kind -eq "else") {
                    if ($elseSeen) { throw "WASM when has duplicate else arms" }
                    $Out.Add("${Indent}local.get `$$matched")
                    $Out.Add("${Indent}i32.eqz")
                    $Out.Add("${Indent}if")
                    if ($inline) {
                        Compile-Statement $inline $Out ($Indent + "  ") -Main:$Main
                    } else {
                        Compile-Lines $Lines $Index $Out ($Indent + "  ") -Main:$Main
                    }
                    $Out.Add("${Indent}end")
                    $armStarted = $true
                    $elseSeen = $true
                    continue
                }

                $Out.Add("${Indent}local.get `$$matched")
                $Out.Add("${Indent}i32.eqz")
                Add-Code $Out @(New-WasmWhenCondition -Subject $subject -Kind $kind -Value $value -RangeEnd $rangeEnd) $Indent
                $Out.Add("${Indent}i32.and")
                $Out.Add("${Indent}if")
                $Out.Add("${Indent}  i32.const 1")
                $Out.Add("${Indent}  local.set `$$matched")
                if ($inline) {
                    Compile-Statement $inline $Out ($Indent + "  ") -Main:$Main
                } else {
                    Compile-Lines $Lines $Index $Out ($Indent + "  ") -Main:$Main
                }
                $Out.Add("${Indent}end")
                $armStarted = $true
            }
            if (-not $armStarted) { throw "WASM when requires at least one arm" }
        } elseif ($t -match '^match\s+(.+)$') {
            $subject = "__match$script:hiddenCounter"
            $matched = "__match_matched$script:hiddenCounter"
            $script:hiddenCounter++
            $Out.Insert(0, "    (local `$$subject i32)")
            $Out.Insert(0, "    (local `$$matched i32)")
            Add-Code $Out @(Emit-Expr $Matches[1]) $Indent
            $Out.Add("${Indent}local.set `$$subject")
            $Out.Add("${Indent}i32.const 0")
            $Out.Add("${Indent}local.set `$$matched")

            $armStarted = $false
            $wildcardSeen = $false
            while ($Index.Value -lt $Lines.Count) {
                $arm = $Lines[$Index.Value].Trim()
                if ($arm -eq "" -or $arm.StartsWith("#") -or $arm.StartsWith("//")) {
                    $Index.Value++
                    continue
                }
                if ($arm -eq "end") {
                    $Index.Value++
                    break
                }
                if ($arm -notmatch '^when\s+(.+?)(?:\s+then(?:\s+(.+))?)?$') {
                    throw "unsupported WASM match arm: $arm"
                }

                $pattern = $Matches[1].Trim()
                $inline = $Matches[2]
                $Index.Value++
                $isWildcard = ($pattern -eq "_")

                if ($isWildcard) {
                    if ($wildcardSeen) { throw "WASM match has duplicate wildcard arms" }
                    $Out.Add("${Indent}local.get `$$matched")
                    $Out.Add("${Indent}i32.eqz")
                    $Out.Add("${Indent}if")
                    if ($inline) {
                        Compile-Statement $inline $Out ($Indent + "  ") -Main:$Main
                    } else {
                        Compile-Lines $Lines $Index $Out ($Indent + "  ") -Main:$Main
                    }
                    $Out.Add("${Indent}end")
                    $armStarted = $true
                    $wildcardSeen = $true
                    continue
                }

                $Out.Add("${Indent}local.get `$$matched")
                $Out.Add("${Indent}i32.eqz")
                Add-Code $Out @(New-WasmMatchCondition -Subject $subject -Pattern $pattern) $Indent
                $Out.Add("${Indent}i32.and")
                $Out.Add("${Indent}if")
                $Out.Add("${Indent}  i32.const 1")
                $Out.Add("${Indent}  local.set `$$matched")
                if ($inline) {
                    Compile-Statement $inline $Out ($Indent + "  ") -Main:$Main
                } else {
                    Compile-Lines $Lines $Index $Out ($Indent + "  ") -Main:$Main
                }
                $Out.Add("${Indent}end")
                $armStarted = $true
            }
            if (-not $armStarted) { throw "WASM match requires at least one arm" }
        } elseif ($t -match '^while\s+(.+)\s+do$') {
            $ctx = Push-WasmLoopContext -ContinueToLoop
            $Out.Add("${Indent}block `$$($ctx.Break)")
            $Out.Add("${Indent}  loop `$$($ctx.Loop)")
            Add-Code $Out @(Emit-Expr $Matches[1]) ($Indent + "    ")
            $Out.Add("${Indent}    i32.eqz")
            $Out.Add("${Indent}    br_if `$$($ctx.Break)")
            Compile-Lines $Lines $Index $Out ($Indent + "    ") -Main:$Main
            if ($Index.Value -lt $Lines.Count -and $Lines[$Index.Value].Trim() -eq "end") { $Index.Value++ }
            $Out.Add("${Indent}    br `$$($ctx.Loop)")
            $Out.Add("${Indent}  end")
            $Out.Add("${Indent}end")
            Pop-WasmLoopContext
        } elseif ($t -match '^repeat\s+(.+)\s+do$') {
            $counter = "__repeat$script:hiddenCounter"
            $limit = "__repeat_limit$script:hiddenCounter"
            $script:hiddenCounter++
            $ctx = Push-WasmLoopContext
            $Out.Insert(0, "    (local `$$limit i32)")
            $Out.Insert(0, "    (local `$$counter i32)")
            $Out.Add("${Indent}i32.const 0")
            $Out.Add("${Indent}local.set `$$counter")
            Add-Code $Out @(Emit-Expr $Matches[1]) $Indent
            $Out.Add("${Indent}local.set `$$limit")
            $Out.Add("${Indent}block `$$($ctx.Break)")
            $Out.Add("${Indent}  loop `$$($ctx.Loop)")
            $Out.Add("${Indent}    local.get `$$counter")
            $Out.Add("${Indent}    local.get `$$limit")
            $Out.Add("${Indent}    i32.ge_s")
            $Out.Add("${Indent}    br_if `$$($ctx.Break)")
            $Out.Add("${Indent}    block `$$($ctx.Continue)")
            Compile-Lines $Lines $Index $Out ($Indent + "      ") -Main:$Main
            $Out.Add("${Indent}    end")
            if ($Index.Value -lt $Lines.Count -and $Lines[$Index.Value].Trim() -eq "end") { $Index.Value++ }
            $Out.Add("${Indent}    local.get `$$counter")
            $Out.Add("${Indent}    i32.const 1")
            $Out.Add("${Indent}    i32.add")
            $Out.Add("${Indent}    local.set `$$counter")
            $Out.Add("${Indent}    br `$$($ctx.Loop)")
            $Out.Add("${Indent}  end")
            $Out.Add("${Indent}end")
            Pop-WasmLoopContext
        } elseif ($t -match '^for\s+([A-Za-z_][A-Za-z0-9_]*)\s+in\s+(.+?)\s+(?:to|~)\s+(.+?)\s+step\s+(.+)\s+do$') {
            $name = $Matches[1]
            $limit = "__for_end$script:hiddenCounter"
            $step = "__for_step$script:hiddenCounter"
            $script:hiddenCounter++
            $ctx = Push-WasmLoopContext
            $Out.Insert(0, "    (local `$$limit i32)")
            $Out.Insert(0, "    (local `$$step i32)")
            Add-Code $Out @(Emit-Expr $Matches[2]) $Indent
            $Out.Add("${Indent}local.set `$$name")
            Add-Code $Out @(Emit-Expr $Matches[3]) $Indent
            $Out.Add("${Indent}local.set `$$limit")
            Add-Code $Out @(Emit-Expr $Matches[4]) $Indent
            $Out.Add("${Indent}local.set `$$step")
            $Out.Add("${Indent}local.get `$$step")
            $Out.Add("${Indent}i32.eqz")
            $Out.Add("${Indent}if")
            $Out.Add("${Indent}  unreachable")
            $Out.Add("${Indent}end")
            $Out.Add("${Indent}block `$$($ctx.Break)")
            $Out.Add("${Indent}  loop `$$($ctx.Loop)")
            $Out.Add("${Indent}    local.get `$$step")
            $Out.Add("${Indent}    i32.const 0")
            $Out.Add("${Indent}    i32.gt_s")
            $Out.Add("${Indent}    if")
            $Out.Add("${Indent}      local.get `$$name")
            $Out.Add("${Indent}      local.get `$$limit")
            $Out.Add("${Indent}      i32.gt_s")
            $Out.Add("${Indent}      br_if `$$($ctx.Break)")
            $Out.Add("${Indent}    else")
            $Out.Add("${Indent}      local.get `$$name")
            $Out.Add("${Indent}      local.get `$$limit")
            $Out.Add("${Indent}      i32.lt_s")
            $Out.Add("${Indent}      br_if `$$($ctx.Break)")
            $Out.Add("${Indent}    end")
            $Out.Add("${Indent}    block `$$($ctx.Continue)")
            Compile-Lines $Lines $Index $Out ($Indent + "      ") -Main:$Main
            $Out.Add("${Indent}    end")
            if ($Index.Value -lt $Lines.Count -and $Lines[$Index.Value].Trim() -eq "end") { $Index.Value++ }
            $Out.Add("${Indent}    local.get `$$name")
            $Out.Add("${Indent}    local.get `$$step")
            $Out.Add("${Indent}    i32.add")
            $Out.Add("${Indent}    local.set `$$name")
            $Out.Add("${Indent}    br `$$($ctx.Loop)")
            $Out.Add("${Indent}  end")
            $Out.Add("${Indent}end")
            Pop-WasmLoopContext
        } elseif ($t -match '^for\s+([A-Za-z_][A-Za-z0-9_]*)\s+in\s+(.+)\s+(?:to|~)\s+(.+)\s+do$') {
            $name = $Matches[1]
            $limit = "__for_end$script:hiddenCounter"
            $script:hiddenCounter++
            $ctx = Push-WasmLoopContext
            $Out.Insert(0, "    (local `$$limit i32)")
            Add-Code $Out @(Emit-Expr $Matches[2]) $Indent
            $Out.Add("${Indent}local.set `$$name")
            Add-Code $Out @(Emit-Expr $Matches[3]) $Indent
            $Out.Add("${Indent}local.set `$$limit")
            $Out.Add("${Indent}block `$$($ctx.Break)")
            $Out.Add("${Indent}  loop `$$($ctx.Loop)")
            $Out.Add("${Indent}    local.get `$$name")
            $Out.Add("${Indent}    local.get `$$limit")
            $Out.Add("${Indent}    i32.gt_s")
            $Out.Add("${Indent}    br_if `$$($ctx.Break)")
            $Out.Add("${Indent}    block `$$($ctx.Continue)")
            Compile-Lines $Lines $Index $Out ($Indent + "      ") -Main:$Main
            $Out.Add("${Indent}    end")
            if ($Index.Value -lt $Lines.Count -and $Lines[$Index.Value].Trim() -eq "end") { $Index.Value++ }
            $Out.Add("${Indent}    local.get `$$name")
            $Out.Add("${Indent}    i32.const 1")
            $Out.Add("${Indent}    i32.add")
            $Out.Add("${Indent}    local.set `$$name")
            $Out.Add("${Indent}    br `$$($ctx.Loop)")
            $Out.Add("${Indent}  end")
            $Out.Add("${Indent}end")
            Pop-WasmLoopContext
        } elseif ($t -match '^for\s+([A-Za-z_][A-Za-z0-9_]*)\s*,\s*([A-Za-z_][A-Za-z0-9_]*)\s+in\s+(.+)\s+do$') {
            $indexName = $Matches[1]
            $itemName = $Matches[2]
            $array = "__for_array$script:hiddenCounter"
            $arrayIndex = "__for_index$script:hiddenCounter"
            $length = "__for_len$script:hiddenCounter"
            $script:hiddenCounter++
            $ctx = Push-WasmLoopContext
            $Out.Insert(0, "    (local `$$length i32)")
            $Out.Insert(0, "    (local `$$arrayIndex i32)")
            $Out.Insert(0, "    (local `$$array i32)")
            Add-Code $Out @(Emit-Expr $Matches[3]) $Indent
            $Out.Add("${Indent}local.set `$$array")
            $Out.Add("${Indent}local.get `$$array")
            $Out.Add("${Indent}call `$__sura_array_require")
            $Out.Add("${Indent}local.set `$$length")
            $Out.Add("${Indent}i32.const 0")
            $Out.Add("${Indent}local.set `$$arrayIndex")
            $Out.Add("${Indent}block `$$($ctx.Break)")
            $Out.Add("${Indent}  loop `$$($ctx.Loop)")
            $Out.Add("${Indent}    local.get `$$arrayIndex")
            $Out.Add("${Indent}    local.get `$$length")
            $Out.Add("${Indent}    i32.ge_s")
            $Out.Add("${Indent}    br_if `$$($ctx.Break)")
            $Out.Add("${Indent}    local.get `$$arrayIndex")
            $Out.Add("${Indent}    local.set `$$indexName")
            $Out.Add("${Indent}    local.get `$$array")
            $Out.Add("${Indent}    local.get `$$arrayIndex")
            $Out.Add("${Indent}    i32.const 4")
            $Out.Add("${Indent}    i32.mul")
            $Out.Add("${Indent}    i32.add")
            $Out.Add("${Indent}    i32.load")
            $Out.Add("${Indent}    local.set `$$itemName")
            $Out.Add("${Indent}    block `$$($ctx.Continue)")
            Compile-Lines $Lines $Index $Out ($Indent + "      ") -Main:$Main
            $Out.Add("${Indent}    end")
            if ($Index.Value -lt $Lines.Count -and $Lines[$Index.Value].Trim() -eq "end") { $Index.Value++ }
            $Out.Add("${Indent}    local.get `$$arrayIndex")
            $Out.Add("${Indent}    i32.const 1")
            $Out.Add("${Indent}    i32.add")
            $Out.Add("${Indent}    local.set `$$arrayIndex")
            $Out.Add("${Indent}    br `$$($ctx.Loop)")
            $Out.Add("${Indent}  end")
            $Out.Add("${Indent}end")
            Pop-WasmLoopContext
        } elseif ($t -match '^for\s+([A-Za-z_][A-Za-z0-9_]*)\s+in\s+(.+)\s+do$') {
            $name = $Matches[1]
            $array = "__for_array$script:hiddenCounter"
            $arrayIndex = "__for_index$script:hiddenCounter"
            $length = "__for_len$script:hiddenCounter"
            $script:hiddenCounter++
            $ctx = Push-WasmLoopContext
            $Out.Insert(0, "    (local `$$length i32)")
            $Out.Insert(0, "    (local `$$arrayIndex i32)")
            $Out.Insert(0, "    (local `$$array i32)")
            Add-Code $Out @(Emit-Expr $Matches[2]) $Indent
            $Out.Add("${Indent}local.set `$$array")
            $Out.Add("${Indent}local.get `$$array")
            $Out.Add("${Indent}call `$__sura_array_require")
            $Out.Add("${Indent}local.set `$$length")
            $Out.Add("${Indent}i32.const 0")
            $Out.Add("${Indent}local.set `$$arrayIndex")
            $Out.Add("${Indent}block `$$($ctx.Break)")
            $Out.Add("${Indent}  loop `$$($ctx.Loop)")
            $Out.Add("${Indent}    local.get `$$arrayIndex")
            $Out.Add("${Indent}    local.get `$$length")
            $Out.Add("${Indent}    i32.ge_s")
            $Out.Add("${Indent}    br_if `$$($ctx.Break)")
            $Out.Add("${Indent}    local.get `$$array")
            $Out.Add("${Indent}    local.get `$$arrayIndex")
            $Out.Add("${Indent}    i32.const 4")
            $Out.Add("${Indent}    i32.mul")
            $Out.Add("${Indent}    i32.add")
            $Out.Add("${Indent}    i32.load")
            $Out.Add("${Indent}    local.set `$$name")
            $Out.Add("${Indent}    block `$$($ctx.Continue)")
            Compile-Lines $Lines $Index $Out ($Indent + "      ") -Main:$Main
            $Out.Add("${Indent}    end")
            if ($Index.Value -lt $Lines.Count -and $Lines[$Index.Value].Trim() -eq "end") { $Index.Value++ }
            $Out.Add("${Indent}    local.get `$$arrayIndex")
            $Out.Add("${Indent}    i32.const 1")
            $Out.Add("${Indent}    i32.add")
            $Out.Add("${Indent}    local.set `$$arrayIndex")
            $Out.Add("${Indent}    br `$$($ctx.Loop)")
            $Out.Add("${Indent}  end")
            $Out.Add("${Indent}end")
            Pop-WasmLoopContext
        } else {
            Compile-Statement $t $Out $Indent -Main:$Main
        }
    }
}

function Register-WasmEnumConstants {
    param([string[]]$Lines)

    for ($i = 0; $i -lt $Lines.Count; $i++) {
        $t = $Lines[$i].Trim()
        if ($t -notmatch '^enum\s+([A-Za-z_][A-Za-z0-9_]*)\s+do$') { continue }
        $enumName = $Matches[1]
        $i++
        for (; $i -lt $Lines.Count; $i++) {
            $member = $Lines[$i].Trim()
            if ($member -eq "" -or $member.StartsWith("#") -or $member.StartsWith("//")) { continue }
            if ($member -eq "end") { break }
            if ($member -notmatch '^([A-Za-z_][A-Za-z0-9_]*)(?:\s+is\s+(.+))?$') {
                throw "unsupported WASM enum member: $member"
            }
            if (-not $Matches[2]) {
                throw "WASM numeric enum member requires an explicit numeric value: $member"
            }
            $memberName = $Matches[1]
            $value = $Matches[2].Trim()
            if ($value -notmatch '^-?[0-9]+$') {
                throw "WASM numeric enum member requires an integer literal value: $member"
            }
            $script:wasmEnumConsts["$enumName.$memberName"] = $value
        }
    }
}

function As-WasmAstArray {
    param($Items)
    if ($null -eq $Items) { return @() }
    if ($Items -is [System.Array]) { return @($Items) }
    if ($Items -is [System.Collections.IEnumerable] -and -not ($Items -is [string]) -and -not ($Items -is [pscustomobject])) {
        return @($Items)
    }
    return @($Items)
}

function Get-WasmAstParamNames {
    param($Params)
    $out = New-Object System.Collections.Generic.List[string]
    foreach ($param in @(As-WasmAstArray $Params)) {
        $name = ([string]$param).Trim()
        if ($name) { $out.Add($name) | Out-Null }
    }
    return @($out.ToArray())
}

function Test-WasmAstRawF64Type {
    param($TypeNode)

    if ($null -eq $TypeNode -or
        -not ($TypeNode.PSObject.Properties.Name -contains "present") -or
        -not [bool]$TypeNode.present) {
        return $false
    }
    if ($TypeNode.PSObject.Properties.Name -contains "source_name") {
        return ([string]$TypeNode.source_name -in @("float", "double"))
    }
    return ([string]$TypeNode.kind -in @("FLOAT", "DOUBLE"))
}

function Get-WasmAstAnnotatedRawReturnKind {
    param($FnNode)

    # An explicit non-f64 scalar return annotation pins the function to the
    # raw ABI regardless of what value-preserving analysis would infer from
    # the body. Annotations are context-free, so this also makes the ABI
    # classification deterministic for annotated functions.
    if ($null -eq $FnNode -or -not ($FnNode.PSObject.Properties.Name -contains "return_type")) { return "" }
    $typeNode = $FnNode.return_type
    if ($null -eq $typeNode -or
        -not ($typeNode.PSObject.Properties.Name -contains "present") -or
        -not [bool]$typeNode.present) {
        return ""
    }
    if (Test-WasmAstRawF64Type $typeNode) { return "" }
    $sourceName = if ($typeNode.PSObject.Properties.Name -contains "source_name") { [string]$typeNode.source_name } else { "" }
    $kindName = if ($typeNode.PSObject.Properties.Name -contains "kind") { [string]$typeNode.kind } else { "" }
    if ($sourceName -in @("number", "num") -or $kindName -eq "NUMBER") { return "num" }
    if ($sourceName -eq "string" -or $kindName -eq "STRING") { return "string" }
    if ($sourceName -eq "bool" -or $kindName -eq "BOOL") { return "bool" }
    return ""
}

function Register-WasmAstRawF64ExportFunctions {
    param($Root)

    $script:wasmRawF64ExportFunctions = @{}
    if ($null -eq $Root) { return }

    $declaredNames = @{}
    foreach ($stmt in @(As-WasmAstArray ($Root.body))) {
        if ($null -ne $stmt -and [string]$stmt.node -eq "FUNC_DEF") {
            $declaredNames[[string]$stmt.name] = $true
        }
    }

    foreach ($stmt in @(As-WasmAstArray ($Root.body))) {
        if ($null -eq $stmt -or [string]$stmt.node -ne "FUNC_DEF") { continue }
        $name = [string]$stmt.name
        if ([string]::IsNullOrWhiteSpace($name) -or -not (Test-WasmAstRawF64Type ($stmt.return_type))) { continue }
        $params = @(Get-WasmAstParamNames ($stmt.params))
        $paramTypes = @(As-WasmAstArray ($stmt.param_types))
        if ($params.Count -ne $paramTypes.Count) { continue }
        $allNumeric = $true
        foreach ($paramType in $paramTypes) {
            if (-not (Test-WasmAstRawF64Type $paramType)) {
                $allNumeric = $false
                break
            }
        }
        if (-not $allNumeric) { continue }
        $exportName = "${name}__f64"
        if ($declaredNames.ContainsKey($exportName)) {
            # A source-level function always owns its explicit public name.
            continue
        }
        $script:wasmRawF64ExportFunctions[$name] = [pscustomobject]@{
            Name = $name
            ExportName = $exportName
            Params = @($params)
        }
        for ($i = 0; $i -lt $params.Count; $i++) {
            $key = "$name.$([string]$params[$i])"
            # Typed numeric functions use the tagged numeric ABI internally so
            # both Sura call sites and the raw-f64 host wrapper can pass doubles.
            $script:wasmFunctionParamTypeHints[$key] = "value"
            if ($script:wasmConflictedFunctionParamTypeHints.ContainsKey($key)) {
                [void]$script:wasmConflictedFunctionParamTypeHints.Remove($key)
            }
        }
    }
}

function Add-WasmRawF64ExportWrappers {
    param(
        [System.Collections.Generic.List[string]]$Wat,
        [object[]]$Functions
    )

    if ($script:wasmRawF64ExportFunctions.Count -eq 0) { return }
    $functionNames = @{}
    foreach ($fn in @($Functions)) { $functionNames[[string]$fn.Name] = $true }

    foreach ($entry in @($script:wasmRawF64ExportFunctions.Values | Sort-Object Name)) {
        $name = [string]$entry.Name
        if (-not $functionNames.ContainsKey($name)) { continue }
        $params = @($entry.Params)
        $rawParams = New-Object System.Collections.Generic.List[string]
        for ($i = 0; $i -lt $params.Count; $i++) {
            $rawParams.Add("(param `$arg$i f64)") | Out-Null
        }
        $signature = [string]::Join(" ", [string[]]$rawParams.ToArray())
        $Wat.Add("  (func `$__sura_raw_f64_export_$name (export `"$([string]$entry.ExportName)`") $signature (result f64)")
        $Wat.Add("    (local `$tagged_result i32)")
        $Wat.Add("    (local `$raw_result f64)")
        $Wat.Add("    i32.const 0")
        $Wat.Add("    global.set `$__sura_exception_thrown")
        $Wat.Add("    i32.const 0")
        $Wat.Add("    global.set `$__sura_exception_value")
        $Wat.Add("    i32.const 0")
        $Wat.Add("    global.set `$__sura_exception_value_tagged")
        for ($i = 0; $i -lt $params.Count; $i++) {
            $Wat.Add("    local.get `$arg$i")
            $Wat.Add("    call `$__sura_value_num_f64")
        }
        $Wat.Add("    call `$$name")
        $Wat.Add("    local.set `$tagged_result")
        $Wat.Add("    global.get `$__sura_exception_thrown")
        $Wat.Add("    if")
        $Wat.Add("      unreachable")
        $Wat.Add("    end")
        $Wat.Add("    local.get `$tagged_result")
        $Wat.Add("    call `$__sura_value_require_number_f64")
        $Wat.Add("    local.set `$raw_result")
        $Wat.Add("    global.get `$__sura_exception_thrown")
        $Wat.Add("    if")
        $Wat.Add("      unreachable")
        $Wat.Add("    end")
        $Wat.Add("    local.get `$raw_result")
        $Wat.Add("  )")
    }
}

function Read-WasmAstReport {
    param([string]$Path)
    $astText = [System.IO.File]::ReadAllText((Resolve-Path -LiteralPath $Path).Path, [System.Text.Encoding]::UTF8)
    $astReport = $astText | ConvertFrom-Json
    if ($astReport.schema -ne "sura.ast.v1") {
        throw "unsupported AST JSON schema: $($astReport.schema)"
    }
    return $astReport
}

function Export-WasmAstReport {
    param([string]$SourcePath, [string]$EnginePath)
    $tmp = Join-Path ([System.IO.Path]::GetTempPath()) ("sura_wasm_ast_import_" + [System.Guid]::NewGuid().ToString("N") + ".json")
    & $EnginePath --ast-json --out $tmp $SourcePath | Out-Null
    if ($LASTEXITCODE -ne 0) {
        throw "AST JSON export failed for WASM import: $SourcePath"
    }
    return Read-WasmAstReport $tmp
}

function Expand-WasmAstImports {
    param(
        $AstReport,
        [Parameter(Mandatory=$true)][string]$AstJsonPath,
        [Parameter(Mandatory=$true)][hashtable]$State,
        [string]$EnginePath = ""
    )

    $sourcePath = [string]$AstReport.source
    $basePath = if (-not [string]::IsNullOrWhiteSpace($sourcePath) -and (Test-Path -LiteralPath $sourcePath)) {
        (Resolve-Path -LiteralPath $sourcePath).Path
    } else {
        (Resolve-Path -LiteralPath $AstJsonPath).Path
    }
    if ($State.ContainsKey($basePath)) {
        if ($State[$basePath] -eq "active") {
            throw "cyclic WASM AST import: $basePath"
        }
        return [pscustomobject]@{ node = "SuraBlock"; line = 0; body = @() }
    }

    $State[$basePath] = "active"
    $body = New-Object System.Collections.Generic.List[object]
    foreach ($stmt in @(As-WasmAstArray ($AstReport.ast.body))) {
        if ([string]$stmt.node -eq "IMPORT") {
            if ([string]::IsNullOrWhiteSpace($EnginePath)) {
                $EnginePath = Resolve-WasmEngine $Engine
            }
            $importPath = Unescape-SuraImportPath ([string]$stmt.path)
            $importResolved = Resolve-WasmImportPath -ImportPath $importPath -ImporterPath $basePath
            $childReport = Export-WasmAstReport -SourcePath $importResolved -EnginePath $EnginePath
            $childBlock = Expand-WasmAstImports -AstReport $childReport -AstJsonPath $importResolved -State $State -EnginePath $EnginePath
            foreach ($child in @(As-WasmAstArray ($childBlock.body))) {
                $body.Add($child) | Out-Null
            }
        } else {
            $body.Add($stmt) | Out-Null
        }
    }
    $State[$basePath] = "done"
    return [pscustomobject]@{ node = "SuraBlock"; line = $AstReport.ast.line; body = @($body.ToArray()) }
}

function Convert-WasmAstStringLiteral {
    param($Value)
    if ($null -eq $Value) { return '""' }
    return ($Value | ConvertTo-Json -Compress)
}

function Convert-WasmAstInterpolationPartExpr {
    param($Node)

    if ((Test-WasmAstRuntimeValueIndexCandidate $Node) -or (Test-WasmAstRuntimeValueDotCandidate $Node)) {
        return @(Convert-WasmAstValueExpr $Node) + @("call `$__sura_value_to_string")
    }
    $objectClassHint = Get-WasmAstObjectClassSetHintWithLocals $Node $script:wasmCurrentLocalObjectClassHints $script:wasmCurrentClassContext
    if (-not [string]::IsNullOrWhiteSpace($objectClassHint)) {
        return @(Convert-WasmAstValueExpr $Node) + @("call `$__sura_value_to_string")
    }
    if ((Test-WasmAstStringExprCandidate $Node) -or (Test-WasmAstKnownStringValueExprCandidate $Node)) {
        return @(Convert-WasmAstStringExpr $Node)
    }
    if (Test-WasmAstValuePreservingExprCandidate $Node) {
        return @(Convert-WasmAstValueExpr $Node) + @("call `$__sura_value_to_string")
    }
    $typeName = Get-WasmAstKnownValueType $Node
    if ([string]::IsNullOrWhiteSpace($typeName)) {
        $typeName = Get-WasmAstStaticValueType $Node
    }
    if ($typeName -eq "value") {
        return @(Convert-WasmAstValueExpr $Node) + @("call `$__sura_value_to_string")
    }
    if ($typeName -in @("bool", "nil")) {
        return @(Convert-WasmAstStringExpr $Node)
    }
    if ($typeName -in @("array", "dict", "function")) {
        return @(Convert-WasmAstToStringExpr $Node)
    }
    if ($null -ne $Node -and [string]$Node.node -in @("NIL_LIT", "BOOL_LIT")) {
        return @(Convert-WasmAstStringExpr $Node)
    }
    return @(Convert-WasmAstExpr $Node) + @("call `$__sura_i32_to_string")
}

function Join-WasmStringPartCodes {
    param([object[]]$PartCodes)

    if ($PartCodes.Count -eq 0) {
        return @(New-WasmStringLiteralExprCode -Literal '""')
    }
    $code = @([string[]]$PartCodes[0])
    for ($i = 1; $i -lt $PartCodes.Count; $i++) {
        $code = @($code + @([string[]]$PartCodes[$i]) + @("call `$__sura_string_concat"))
    }
    return $code
}

function Tokenize-WasmAstInterpolationExpr {
    param([string]$Expr)

    $tokens = New-Object System.Collections.Generic.List[string]
    $pos = 0
    $rx = [regex]'\G\s*("(?:\\.|[^"])*"|''(?:\\.|[^''])*''|==|!=|<=|>=|<<|>>|\?\.|\?\?|[()\[\]{}.,+\-*/%,<>&|^~?:]|[A-Za-z_][A-Za-z0-9_]*|-?[0-9]+(?:\.[0-9]+)?)'
    while ($pos -lt $Expr.Length) {
        if ($Expr.Substring($pos) -match '^\s*$') { break }
        $m = $rx.Match($Expr, $pos)
        if (-not $m.Success) {
            $nearLen = [Math]::Min(24, $Expr.Length - $pos)
            throw "unsupported WASM interpolation expression near '$($Expr.Substring($pos, $nearLen))'"
        }
        $tokens.Add($m.Groups[1].Value) | Out-Null
        $pos = $m.Index + $m.Length
    }
    return @($tokens.ToArray())
}

function New-WasmAstInterpolationParser {
    param([string]$Expr)

    return [pscustomobject]@{
        Tokens = @(Tokenize-WasmAstInterpolationExpr $Expr)
        Pos = 0
        Expr = $Expr
    }
}

function Peek-WasmAstInterpolationToken {
    param($Parser)

    if ($Parser.Pos -ge $Parser.Tokens.Count) { return $null }
    return $Parser.Tokens[$Parser.Pos]
}

function Take-WasmAstInterpolationToken {
    param($Parser)

    $t = Peek-WasmAstInterpolationToken $Parser
    if ($null -ne $t) { $Parser.Pos++ }
    return $t
}

function Match-WasmAstInterpolationToken {
    param($Parser, [string]$Want)

    if ((Peek-WasmAstInterpolationToken $Parser) -eq $Want) {
        $Parser.Pos++
        return $true
    }
    return $false
}

function Convert-WasmAstInterpolationStringToken {
    param([string]$Token)

    $inner = $Token.Substring(1, $Token.Length - 2)
    $sb = New-Object System.Text.StringBuilder
    for ($i = 0; $i -lt $inner.Length; $i++) {
        $ch = $inner[$i]
        if ($ch -eq [char]92 -and $i + 1 -lt $inner.Length) {
            $i++
            $next = $inner[$i]
            switch ([string]$next) {
                "n" { [void]$sb.Append([char]10); continue }
                "r" { [void]$sb.Append([char]13); continue }
                "t" { [void]$sb.Append([char]9); continue }
                default { [void]$sb.Append($next); continue }
            }
        }
        [void]$sb.Append($ch)
    }
    return $sb.ToString()
}

function New-WasmAstInterpolationBinaryNode {
    param($Left, [string]$Op, $Right)

    return [pscustomobject]@{
        node = "BIN_OP"
        line = 0
        op = $Op
        left = $Left
        right = $Right
    }
}

function Parse-WasmAstInterpolationCallArgs {
    param($Parser)

    $args = New-Object System.Collections.Generic.List[object]
    if ((Peek-WasmAstInterpolationToken $Parser) -ne ")") {
        do {
            $args.Add((Parse-WasmAstInterpolationTernary $Parser)) | Out-Null
        } while (Match-WasmAstInterpolationToken $Parser ",")
    }
    if (-not (Match-WasmAstInterpolationToken $Parser ")")) {
        throw "missing ')' in interpolation expression '$($Parser.Expr)'"
    }
    return @($args.ToArray())
}

function Apply-WasmAstInterpolationPostfix {
    param($Parser, $Node)

    $current = $Node
    while ($true) {
        $dotToken = $null
        if (Match-WasmAstInterpolationToken $Parser "?.") {
            $dotToken = "?."
        } elseif (Match-WasmAstInterpolationToken $Parser ".") {
            $dotToken = "."
        }
        if ($null -ne $dotToken) {
            $prop = Take-WasmAstInterpolationToken $Parser
            if ($prop -notmatch '^[A-Za-z_][A-Za-z0-9_]*$') {
                throw "missing property name in interpolation expression '$($Parser.Expr)'"
            }
            $current = [pscustomobject]@{
                node = "DOT_ACCESS"
                line = 0
                obj = $current
                prop = $prop
                optional = ($dotToken -eq "?.")
            }
            continue
        }
        if (Match-WasmAstInterpolationToken $Parser "[") {
            $key = Parse-WasmAstInterpolationTernary $Parser
            if (-not (Match-WasmAstInterpolationToken $Parser "]")) {
                throw "missing ']' in interpolation expression '$($Parser.Expr)'"
            }
            $current = [pscustomobject]@{
                node = "INDEX"
                line = 0
                obj = $current
                key = $key
            }
            continue
        }
        if (Match-WasmAstInterpolationToken $Parser "(") {
            $args = @(Parse-WasmAstInterpolationCallArgs $Parser)
            if ([string]$current.node -eq "IDENT") {
                $current = [pscustomobject]@{
                    node = "CALL"
                    line = 0
                    name = [string]$current.name
                    args = @($args)
                }
                continue
            }
            if ([string]$current.node -eq "DOT_ACCESS") {
                $root = $current.obj
                if ($null -ne $root -and [string]$root.node -eq "IDENT" -and [string]$root.name -eq "super") {
                    $current = [pscustomobject]@{
                        node = "SUPER_CALL"
                        line = 0
                        method = [string]$current.prop
                        args = @($args)
                    }
                } elseif ($null -ne $root -and [string]$root.node -eq "IDENT" -and [string]$root.name -in @("array", "math", "vector", "string")) {
                    $current = [pscustomobject]@{
                        node = "CALL"
                        line = 0
                        name = "$([string]$root.name).$([string]$current.prop)"
                        args = @($args)
                    }
                } else {
                    $current = [pscustomobject]@{
                        node = "METHOD_CALL"
                        line = 0
                        obj = $current.obj
                        method = [string]$current.prop
                        args = @($args)
                    }
                }
                continue
            }
            throw "unsupported callable receiver in interpolation expression '$($Parser.Expr)'"
        }
        break
    }
    return $current
}

function Parse-WasmAstInterpolationFuncExpr {
    param($Parser)

    if (-not (Match-WasmAstInterpolationToken $Parser "(")) {
        throw "missing '(' after func in interpolation expression '$($Parser.Expr)'"
    }
    $params = New-Object System.Collections.Generic.List[string]
    if ((Peek-WasmAstInterpolationToken $Parser) -ne ")") {
        do {
            $paramName = Take-WasmAstInterpolationToken $Parser
            if ($paramName -notmatch '^[A-Za-z_][A-Za-z0-9_]*$') {
                throw "invalid func parameter '$paramName' in interpolation expression '$($Parser.Expr)'"
            }
            $params.Add([string]$paramName) | Out-Null
        } while (Match-WasmAstInterpolationToken $Parser ",")
    }
    if (-not (Match-WasmAstInterpolationToken $Parser ")") -or
        -not (Match-WasmAstInterpolationToken $Parser "do")) {
        throw "missing ') do' after func parameters in interpolation expression '$($Parser.Expr)'"
    }

    $depth = 1
    $blockOpeners = @("func", "if", "while", "for", "repeat", "try", "match", "when")
    while ($Parser.Pos -lt $Parser.Tokens.Count) {
        $bodyToken = Take-WasmAstInterpolationToken $Parser
        if ($bodyToken -in $blockOpeners) {
            $depth++
            continue
        }
        if ($bodyToken -eq "end") {
            $depth--
            if ($depth -eq 0) { break }
        }
    }
    if ($depth -ne 0) {
        throw "missing end after func body in interpolation expression '$($Parser.Expr)'"
    }

    # Interpolation introspection only needs a stable function identity and display
    # name. The body remains opaque here; ordinary FUNC_EXPR nodes are still parsed
    # by the engine AST and promoted through the full lowering pipeline.
    $funcExpr = [pscustomobject]@{
        node = "FUNC_EXPR"
        line = 0
        params = @($params.ToArray())
        body = [pscustomobject]@{ node = "SuraBlock"; line = 0; body = @() }
    }
    [void](Get-WasmAstFuncExprLiftName $funcExpr "<lambda>")
    return (Apply-WasmAstInterpolationPostfix $Parser $funcExpr)
}

function Parse-WasmAstInterpolationPrimary {
    param($Parser)

    $t = Take-WasmAstInterpolationToken $Parser
    if ($null -eq $t) { throw "unexpected end of interpolation expression '$($Parser.Expr)'" }
    if ($t -match '^[0-9]+(?:\.[0-9]+)?$') {
        return [pscustomobject]@{ node = "NUM_LIT"; line = 0; value = [double]::Parse($t, [System.Globalization.CultureInfo]::InvariantCulture) }
    }
    if ($t -match '^(?:"(?:\\.|[^"])*"|''(?:\\.|[^''])*'')$') {
        return Apply-WasmAstInterpolationPostfix $Parser ([pscustomobject]@{
            node = "STR_LIT"
            line = 0
            value = (Convert-WasmAstInterpolationStringToken $t)
        })
    }
    if ($t -eq "true") { return [pscustomobject]@{ node = "BOOL_LIT"; line = 0; value = $true } }
    if ($t -eq "false") { return [pscustomobject]@{ node = "BOOL_LIT"; line = 0; value = $false } }
    if ($t -eq "nil") { return [pscustomobject]@{ node = "NIL_LIT"; line = 0 } }
    if ($t -eq "func") {
        return (Parse-WasmAstInterpolationFuncExpr $Parser)
    }
    if ($t -eq "(") {
        $inner = Parse-WasmAstInterpolationTernary $Parser
        if (-not (Match-WasmAstInterpolationToken $Parser ")")) {
            throw "missing ')' in interpolation expression '$($Parser.Expr)'"
        }
        return Apply-WasmAstInterpolationPostfix $Parser $inner
    }
    if ($t -eq "[") {
        $items = New-Object System.Collections.Generic.List[object]
        if ((Peek-WasmAstInterpolationToken $Parser) -ne "]") {
            do {
                $items.Add((Parse-WasmAstInterpolationTernary $Parser)) | Out-Null
            } while (Match-WasmAstInterpolationToken $Parser ",")
        }
        if (-not (Match-WasmAstInterpolationToken $Parser "]")) {
            throw "missing ']' after array literal in interpolation expression '$($Parser.Expr)'"
        }
        return Apply-WasmAstInterpolationPostfix $Parser ([pscustomobject]@{
            node = "ARRAY_LIT"
            line = 0
            elements = @($items.ToArray())
        })
    }
    if ($t -eq "{") {
        $entries = New-Object System.Collections.Generic.List[object]
        if ((Peek-WasmAstInterpolationToken $Parser) -ne "}") {
            do {
                $keyToken = Take-WasmAstInterpolationToken $Parser
                if ($null -eq $keyToken) { throw "missing dict key in interpolation expression '$($Parser.Expr)'" }
                if ($keyToken -match '^(?:"(?:\\.|[^"])*"|''(?:\\.|[^''])*'')$') {
                    $key = Convert-WasmAstInterpolationStringToken $keyToken
                } elseif ($keyToken -match '^[A-Za-z_][A-Za-z0-9_]*$') {
                    $key = $keyToken
                } else {
                    throw "unsupported dict key '$keyToken' in interpolation expression '$($Parser.Expr)'"
                }
                if (-not (Match-WasmAstInterpolationToken $Parser ":")) {
                    throw "missing ':' after dict key in interpolation expression '$($Parser.Expr)'"
                }
                $entries.Add([pscustomobject]@{
                    key = $key
                    value = (Parse-WasmAstInterpolationTernary $Parser)
                }) | Out-Null
            } while (Match-WasmAstInterpolationToken $Parser ",")
        }
        if (-not (Match-WasmAstInterpolationToken $Parser "}")) {
            throw "missing '}' after dict literal in interpolation expression '$($Parser.Expr)'"
        }
        return Apply-WasmAstInterpolationPostfix $Parser ([pscustomobject]@{
            node = "DICT_LIT"
            line = 0
            entries = @($entries.ToArray())
        })
    }
    if ($t -eq "new") {
        $className = Take-WasmAstInterpolationToken $Parser
        if ($className -notmatch '^[A-Za-z_][A-Za-z0-9_]*$') {
            throw "missing class name in interpolation expression '$($Parser.Expr)'"
        }
        if (-not (Match-WasmAstInterpolationToken $Parser "(")) {
            throw "missing '(' after new $className in interpolation expression '$($Parser.Expr)'"
        }
        $args = @(Parse-WasmAstInterpolationCallArgs $Parser)
        return Apply-WasmAstInterpolationPostfix $Parser ([pscustomobject]@{
            node = "NEW_EXPR"
            line = 0
            class_name = $className
            args = @($args)
        })
    }
    if ($t -match '^[A-Za-z_][A-Za-z0-9_]*$') {
        return Apply-WasmAstInterpolationPostfix $Parser ([pscustomobject]@{
            node = "IDENT"
            line = 0
            name = $t
        })
    }
    throw "unexpected interpolation token '$t'"
}

function Parse-WasmAstInterpolationUnary {
    param($Parser)

    if (Match-WasmAstInterpolationToken $Parser "not") {
        return [pscustomobject]@{
            node = "UNARY_OP"
            line = 0
            op = "not"
            operand = (Parse-WasmAstInterpolationUnary $Parser)
        }
    }
    if (Match-WasmAstInterpolationToken $Parser "-") {
        return [pscustomobject]@{
            node = "UNARY_OP"
            line = 0
            op = "-"
            operand = (Parse-WasmAstInterpolationUnary $Parser)
        }
    }
    if (Match-WasmAstInterpolationToken $Parser "~") {
        return [pscustomobject]@{
            node = "UNARY_OP"
            line = 0
            op = "~"
            operand = (Parse-WasmAstInterpolationUnary $Parser)
        }
    }
    return Parse-WasmAstInterpolationPrimary $Parser
}

function Parse-WasmAstInterpolationMul {
    param($Parser)

    $left = Parse-WasmAstInterpolationUnary $Parser
    while ((Peek-WasmAstInterpolationToken $Parser) -in @("*", "/", "%")) {
        $op = Take-WasmAstInterpolationToken $Parser
        $right = Parse-WasmAstInterpolationUnary $Parser
        $left = New-WasmAstInterpolationBinaryNode $left $op $right
    }
    return $left
}

function Parse-WasmAstInterpolationAdd {
    param($Parser)

    $left = Parse-WasmAstInterpolationMul $Parser
    while ((Peek-WasmAstInterpolationToken $Parser) -in @("+", "-")) {
        $op = Take-WasmAstInterpolationToken $Parser
        $right = Parse-WasmAstInterpolationMul $Parser
        $left = New-WasmAstInterpolationBinaryNode $left $op $right
    }
    return $left
}

function Parse-WasmAstInterpolationShift {
    param($Parser)

    $left = Parse-WasmAstInterpolationAdd $Parser
    while ((Peek-WasmAstInterpolationToken $Parser) -in @("<<", ">>")) {
        $op = Take-WasmAstInterpolationToken $Parser
        $right = Parse-WasmAstInterpolationAdd $Parser
        $left = New-WasmAstInterpolationBinaryNode $left $op $right
    }
    return $left
}

function Parse-WasmAstInterpolationBitAnd {
    param($Parser)

    $left = Parse-WasmAstInterpolationShift $Parser
    while ((Peek-WasmAstInterpolationToken $Parser) -eq "&") {
        $op = Take-WasmAstInterpolationToken $Parser
        $right = Parse-WasmAstInterpolationShift $Parser
        $left = New-WasmAstInterpolationBinaryNode $left $op $right
    }
    return $left
}

function Parse-WasmAstInterpolationBitXor {
    param($Parser)

    $left = Parse-WasmAstInterpolationBitAnd $Parser
    while ((Peek-WasmAstInterpolationToken $Parser) -eq "^") {
        $op = Take-WasmAstInterpolationToken $Parser
        $right = Parse-WasmAstInterpolationBitAnd $Parser
        $left = New-WasmAstInterpolationBinaryNode $left $op $right
    }
    return $left
}

function Parse-WasmAstInterpolationBitOr {
    param($Parser)

    $left = Parse-WasmAstInterpolationBitXor $Parser
    while ((Peek-WasmAstInterpolationToken $Parser) -eq "|") {
        $op = Take-WasmAstInterpolationToken $Parser
        $right = Parse-WasmAstInterpolationBitXor $Parser
        $left = New-WasmAstInterpolationBinaryNode $left $op $right
    }
    return $left
}

function Parse-WasmAstInterpolationCompare {
    param($Parser)

    $left = Parse-WasmAstInterpolationBitOr $Parser
    while ((Peek-WasmAstInterpolationToken $Parser) -in @("==", "!=", "<", "<=", ">", ">=")) {
        $op = Take-WasmAstInterpolationToken $Parser
        $right = Parse-WasmAstInterpolationBitOr $Parser
        $left = New-WasmAstInterpolationBinaryNode $left $op $right
    }
    return $left
}

function Parse-WasmAstInterpolationAnd {
    param($Parser)

    $left = Parse-WasmAstInterpolationCompare $Parser
    while ((Peek-WasmAstInterpolationToken $Parser) -eq "and") {
        $op = Take-WasmAstInterpolationToken $Parser
        $right = Parse-WasmAstInterpolationCompare $Parser
        $left = New-WasmAstInterpolationBinaryNode $left $op $right
    }
    return $left
}

function Parse-WasmAstInterpolationOr {
    param($Parser)

    $left = Parse-WasmAstInterpolationAnd $Parser
    while ((Peek-WasmAstInterpolationToken $Parser) -eq "or") {
        $op = Take-WasmAstInterpolationToken $Parser
        $right = Parse-WasmAstInterpolationAnd $Parser
        $left = New-WasmAstInterpolationBinaryNode $left $op $right
    }
    return $left
}

function Parse-WasmAstInterpolationCoalesce {
    param($Parser)

    $left = Parse-WasmAstInterpolationOr $Parser
    if (Match-WasmAstInterpolationToken $Parser "??") {
        $right = Parse-WasmAstInterpolationCoalesce $Parser
        return [pscustomobject]@{
            node = "BIN_OP"
            line = 0
            op = "??"
            left = $left
            right = $right
        }
    }
    return $left
}

function Parse-WasmAstInterpolationTernary {
    param($Parser)

    $cond = Parse-WasmAstInterpolationCoalesce $Parser
    if (Match-WasmAstInterpolationToken $Parser "?") {
        $thenNode = Parse-WasmAstInterpolationTernary $Parser
        if (-not (Match-WasmAstInterpolationToken $Parser ":")) {
            throw "missing ':' in interpolation expression '$($Parser.Expr)'"
        }
        $elseNode = Parse-WasmAstInterpolationTernary $Parser
        return [pscustomobject]@{
            node = "TERNARY"
            line = 0
            cond = $cond
            then = $thenNode
            else = $elseNode
        }
    }
    return $cond
}

function Convert-WasmAstInterpolationExprTextToNode {
    param([string]$Expr)

    $parser = New-WasmAstInterpolationParser $Expr
    if ($parser.Tokens.Count -eq 0) { return $null }
    $node = Parse-WasmAstInterpolationTernary $parser
    if ($parser.Pos -lt $parser.Tokens.Count) {
        throw "unexpected interpolation token '$($parser.Tokens[$parser.Pos])' in '$Expr'"
    }
    return $node
}

function Find-WasmAstInterpolationClose {
    param([string]$Text, [int]$Open)

    $depth = 0
    $quote = [char]0
    for ($i = $Open + 1; $i -lt $Text.Length; $i++) {
        $ch = $Text[$i]
        if ($quote -ne [char]0) {
            if ($ch -eq [char]92 -and $i + 1 -lt $Text.Length) {
                if ($Text[$i + 1] -eq $quote) {
                    $quote = [char]0
                    $i++
                    continue
                }
                $i++
                continue
            }
            if ($ch -eq $quote) { $quote = [char]0 }
            continue
        }
        if ($ch -eq [char]92 -and $i + 1 -lt $Text.Length -and
            ($Text[$i + 1] -eq [char]34 -or $Text[$i + 1] -eq [char]39)) {
            $quote = $Text[$i + 1]
            $i++
            continue
        }
        if ($ch -eq [char]34 -or $ch -eq [char]39) {
            $quote = $ch
            continue
        }
        if ($ch -eq [char]123) {
            $depth++
            continue
        }
        if ($ch -eq [char]125) {
            if ($depth -eq 0) { return $i }
            $depth--
        }
    }
    return -1
}

function Convert-WasmAstInterpolatedTextExpr {
    param([string]$Text)

    if ($Text.IndexOf('{') -lt 0 -or $Text.IndexOf('}') -lt 0) {
        return @(New-WasmStringLiteralExprCode -Literal (Convert-WasmAstStringLiteral $Text))
    }

    $parts = New-Object System.Collections.Generic.List[object]
    $cursor = 0
    $converted = 0
    while ($cursor -lt $Text.Length) {
        $open = $Text.IndexOf('{', $cursor)
        if ($open -lt 0) {
            $tail = $Text.Substring($cursor)
            if ($tail.Length -gt 0) {
                $parts.Add([string[]]@(New-WasmStringLiteralExprCode -Literal (Convert-WasmAstStringLiteral $tail))) | Out-Null
            }
            break
        }
        $close = Find-WasmAstInterpolationClose -Text $Text -Open $open
        if ($close -lt 0) {
            return @(New-WasmStringLiteralExprCode -Literal (Convert-WasmAstStringLiteral $Text))
        }

        if ($open -gt $cursor) {
            $prefix = $Text.Substring($cursor, $open - $cursor)
            $parts.Add([string[]]@(New-WasmStringLiteralExprCode -Literal (Convert-WasmAstStringLiteral $prefix))) | Out-Null
        }

        $exprText = $Text.Substring($open + 1, $close - $open - 1).Trim()
        if ([string]::IsNullOrWhiteSpace($exprText) -or $exprText -notmatch '[A-Za-z0-9_]') {
            $literal = $Text.Substring($open, $close - $open + 1)
            $parts.Add([string[]]@(New-WasmStringLiteralExprCode -Literal (Convert-WasmAstStringLiteral $literal))) | Out-Null
        } else {
            $exprForWasm = $exprText.Replace('\"', '"')
            $exprNode = try {
                Convert-WasmAstInterpolationExprTextToNode $exprForWasm
            } catch {
                $null
            }
            $convertedPart = $false
            if ($null -ne $exprNode) {
                $parts.Add([string[]]@(Convert-WasmAstInterpolationPartExpr $exprNode)) | Out-Null
                $convertedPart = $true
            } else {
                $emitCode = try {
                    [string[]]@(@(Emit-Expr $exprForWasm) + @("call `$__sura_i32_to_string"))
                } catch {
                    $null
                }
                if ($null -ne $emitCode) {
                    $parts.Add($emitCode) | Out-Null
                    $convertedPart = $true
                } else {
                    $literal = $Text.Substring($open, $close - $open + 1)
                    $parts.Add([string[]]@(New-WasmStringLiteralExprCode -Literal (Convert-WasmAstStringLiteral $literal))) | Out-Null
                }
            }
            if ($convertedPart) { $converted++ }
        }
        $cursor = $close + 1
    }

    if ($converted -eq 0) {
        return @(New-WasmStringLiteralExprCode -Literal (Convert-WasmAstStringLiteral $Text))
    }
    return @(Join-WasmStringPartCodes -PartCodes ([object[]]$parts.ToArray()))
}

function Get-WasmAstInterpolatedTextExprNodes {
    param([string]$Text)

    $nodes = New-Object System.Collections.Generic.List[object]
    if ([string]::IsNullOrEmpty($Text) -or $Text.IndexOf('{') -lt 0 -or $Text.IndexOf('}') -lt 0) {
        return @()
    }

    $cursor = 0
    while ($cursor -lt $Text.Length) {
        $open = $Text.IndexOf('{', $cursor)
        if ($open -lt 0) { break }
        $close = Find-WasmAstInterpolationClose -Text $Text -Open $open
        if ($close -lt 0) { break }
        $exprText = $Text.Substring($open + 1, $close - $open - 1).Trim()
        if (-not [string]::IsNullOrWhiteSpace($exprText) -and $exprText -match '[A-Za-z0-9_]') {
            $exprForWasm = $exprText.Replace('\"', '"')
            $exprNode = try {
                Convert-WasmAstInterpolationExprTextToNode $exprForWasm
            } catch {
                $null
            }
            if ($null -ne $exprNode) { $nodes.Add($exprNode) | Out-Null }
        }
        $cursor = $close + 1
    }
    return @($nodes.ToArray())
}

function Convert-WasmAstStringInterpolationNode {
    param($Node)

    $parts = New-Object System.Collections.Generic.List[object]
    foreach ($part in @(As-WasmAstArray ($Node.parts))) {
        if ($null -ne $part -and [string]$part.node -eq "STR_LIT") {
            $parts.Add([string[]]@(New-WasmStringLiteralExprCode -Literal (Convert-WasmAstStringLiteral ($part.value)))) | Out-Null
        } else {
            $parts.Add([string[]]@(Convert-WasmAstInterpolationPartExpr $part)) | Out-Null
        }
    }
    return @(Join-WasmStringPartCodes -PartCodes ([object[]]$parts.ToArray()))
}

function Get-WasmClassConstructorName {
    param([Parameter(Mandatory=$true)][string]$ClassName)
    return "__sura_new_$ClassName"
}

function Get-WasmClassMethodName {
    param(
        [Parameter(Mandatory=$true)][string]$ClassName,
        [Parameter(Mandatory=$true)][string]$MethodName
    )
    return "__sura_method_${ClassName}_${MethodName}"
}

function Get-WasmClassDispatchId {
    param([Parameter(Mandatory=$true)][string]$ClassName)

    $classNames = @($script:wasmClassDefs.Keys | ForEach-Object { [string]$_ } | Sort-Object -Unique)
    for ($i = 0; $i -lt $classNames.Count; $i++) {
        if ($classNames[$i] -ceq $ClassName) { return ($i + 1) }
    }
    return 0
}

function Get-WasmMethodDispatchName {
    param(
        [Parameter(Mandatory=$true)][string]$MethodName,
        [Parameter(Mandatory=$true)][int]$Arity
    )

    $methodNames = New-Object System.Collections.Generic.List[string]
    foreach ($classEntry in @($script:wasmClassDefs.GetEnumerator())) {
        foreach ($method in @(As-WasmAstArray ($classEntry.Value.Node.methods))) {
            $name = [string]$method.name
            if (-not [string]::IsNullOrWhiteSpace($name) -and $name -ne "init") {
                $methodNames.Add($name) | Out-Null
            }
        }
    }
    $sortedNames = @($methodNames.ToArray() | Sort-Object -Unique)
    for ($i = 0; $i -lt $sortedNames.Count; $i++) {
        if ($sortedNames[$i] -ceq $MethodName) {
            return "__sura_call_method_$($i + 1)_$Arity"
        }
    }
    return ""
}

function Get-WasmAstDynamicMethodCandidates {
    param(
        [Parameter(Mandatory=$true)][string]$MethodName,
        [Parameter(Mandatory=$true)][int]$Arity
    )

    $out = New-Object System.Collections.Generic.List[object]
    foreach ($className in @($script:wasmClassDefs.Keys | ForEach-Object { [string]$_ } | Sort-Object -Unique)) {
        $methodInfo = Get-WasmAstClassMethod -ClassName $className -MethodName $MethodName
        if ($null -eq $methodInfo -or @(Get-WasmAstParamNames ($methodInfo.Method.params)).Count -ne $Arity) {
            continue
        }
        $out.Add([pscustomobject]@{
            ClassName = $className
            ClassId = Get-WasmClassDispatchId $className
            FunctionName = [string]$methodInfo.FunctionName
        }) | Out-Null
    }
    return @($out.ToArray())
}

function Add-WasmClassField {
    param(
        [System.Collections.Generic.List[object]]$Fields,
        [Parameter(Mandatory=$true)][hashtable]$Seen,
        [Parameter(Mandatory=$true)][string]$Name,
        $DefaultValue
    )

    if ([string]::IsNullOrWhiteSpace($Name) -or $Seen.ContainsKey($Name)) { return }
    $Seen[$Name] = $true
    if ($null -eq $DefaultValue) {
        $DefaultValue = [pscustomobject]@{ node = "NUM_LIT"; line = 0; value = 0 }
    }
    $Fields.Add([pscustomobject]@{ key = $Name; value = $DefaultValue }) | Out-Null
}

function Add-WasmClassSelfFieldsFromBody {
    param(
        $Body,
        [System.Collections.Generic.List[object]]$Fields,
        [Parameter(Mandatory=$true)][hashtable]$Seen
    )

    if ($null -eq $Body) { return }
    foreach ($stmt in @(As-WasmAstArray ($Body.body))) {
        if ($null -eq $stmt) { continue }
        switch ([string]$stmt.node) {
            "DOT_ASSIGN" {
                if ([string]$stmt.obj_name -eq "self") {
                    Add-WasmClassField -Fields $Fields -Seen $Seen -Name ([string]$stmt.prop) -DefaultValue $null
                }
            }
            "SuraBlock" {
                Add-WasmClassSelfFieldsFromBody -Body $stmt -Fields $Fields -Seen $Seen
            }
            "IF" {
                Add-WasmClassSelfFieldsFromBody -Body ($stmt.then_block) -Fields $Fields -Seen $Seen
                Add-WasmClassSelfFieldsFromBody -Body ($stmt.else_block) -Fields $Fields -Seen $Seen
            }
            "WHILE" {
                Add-WasmClassSelfFieldsFromBody -Body ($stmt.body) -Fields $Fields -Seen $Seen
            }
            "REPEAT" {
                Add-WasmClassSelfFieldsFromBody -Body ($stmt.body) -Fields $Fields -Seen $Seen
            }
            "FOR" {
                Add-WasmClassSelfFieldsFromBody -Body ($stmt.body) -Fields $Fields -Seen $Seen
            }
            "FOREACH" {
                Add-WasmClassSelfFieldsFromBody -Body ($stmt.body) -Fields $Fields -Seen $Seen
            }
            "TRY" {
                Add-WasmClassSelfFieldsFromBody -Body ($stmt.try_block) -Fields $Fields -Seen $Seen
                Add-WasmClassSelfFieldsFromBody -Body ($stmt.finally_block) -Fields $Fields -Seen $Seen
            }
            default { }
        }
    }
}

function Get-WasmAstClassInitMethod {
    param($ClassNode)

    foreach ($method in @(As-WasmAstArray ($ClassNode.methods))) {
        if ([string]$method.name -eq "init") { return $method }
    }
    return $null
}

function Get-WasmAstClassMethod {
    param(
        [Parameter(Mandatory=$true)][string]$ClassName,
        [Parameter(Mandatory=$true)][string]$MethodName,
        [hashtable]$Seen = @{}
    )

    if ([string]::IsNullOrWhiteSpace($ClassName) -or -not $script:wasmClassDefs.ContainsKey($ClassName) -or $Seen.ContainsKey($ClassName)) {
        return $null
    }
    $Seen[$ClassName] = $true
    $classNode = $script:wasmClassDefs[$ClassName].Node
    foreach ($method in @(As-WasmAstArray ($classNode.methods))) {
        if ([string]$method.name -eq $MethodName -and [string]$method.name -ne "init") {
            return [pscustomobject]@{
                ClassName = $ClassName
                Method = $method
                FunctionName = Get-WasmClassMethodName $ClassName $MethodName
            }
        }
    }
    $parent = [string]$script:wasmClassDefs[$ClassName].Parent
    if (-not [string]::IsNullOrWhiteSpace($parent)) {
        return (Get-WasmAstClassMethod -ClassName $parent -MethodName $MethodName -Seen $Seen)
    }
    return $null
}

function Get-WasmAstSuperClassMethod {
    param(
        [Parameter(Mandatory=$true)][string]$ClassName,
        [Parameter(Mandatory=$true)][string]$MethodName
    )

    if ([string]::IsNullOrWhiteSpace($ClassName) -or -not $script:wasmClassDefs.ContainsKey($ClassName)) {
        return $null
    }
    $parent = [string]$script:wasmClassDefs[$ClassName].Parent
    if ([string]::IsNullOrWhiteSpace($parent)) { return $null }
    return (Get-WasmAstClassMethod -ClassName $parent -MethodName $MethodName)
}

function New-WasmAstClassMethodFunctions {
    param($ClassNode)

    $out = New-Object System.Collections.Generic.List[object]
    if ($null -eq $ClassNode -or [string]$ClassNode.node -ne "CLASS_DEF") { return @() }
    $className = [string]$ClassNode.name
    if ([string]::IsNullOrWhiteSpace($className)) { return @() }
    foreach ($method in @(As-WasmAstArray ($ClassNode.methods))) {
        $methodName = [string]$method.name
        if ($methodName -eq "init" -or [string]::IsNullOrWhiteSpace($methodName)) { continue }
        $params = New-Object System.Collections.Generic.List[string]
        $params.Add("self") | Out-Null
        foreach ($param in @(Get-WasmAstParamNames ($method.params))) {
            $params.Add($param) | Out-Null
        }
        $out.Add([pscustomobject]@{
            Name = Get-WasmClassMethodName $className $methodName
            Params = @($params.ToArray())
            Body = @()
            BodyAst = $method.body
            WasmClassMethod = $true
            WasmClassName = $className
        }) | Out-Null
    }
    return @($out.ToArray())
}

function Register-WasmAstClassDefs {
    param($Node)

    if ($null -eq $Node) { return }
    switch ([string]$Node.node) {
        "SuraBlock" {
            foreach ($stmt in @(As-WasmAstArray ($Node.body))) { Register-WasmAstClassDefs $stmt }
        }
        "CLASS_DEF" {
            $name = [string]$Node.name
            $parent = [string]$Node.parent
            if (-not [string]::IsNullOrWhiteSpace($name)) {
                $script:wasmClassDefs[$name] = [pscustomobject]@{
                    Name = $name
                    Parent = $parent
                    ConstructorName = Get-WasmClassConstructorName $name
                    Node = $Node
                }
            }
        }
        default { }
    }
}

function Register-WasmAstFunctionDefs {
    param($Node)

    if ($null -eq $Node) { return }
    switch ([string]$Node.node) {
        "SuraBlock" {
            foreach ($stmt in @(As-WasmAstArray ($Node.body))) { Register-WasmAstFunctionDefs $stmt }
        }
        "FUNC_DEF" {
            $name = [string]$Node.name
            if (-not [string]::IsNullOrWhiteSpace($name)) {
                $script:wasmAstFunctionDefs[$name] = [pscustomobject]@{
                    Name = $name
                    Params = @(Get-WasmAstParamNames ($Node.params))
                    Node = $Node
                }
            }
        }
        "ASSIGN" {
            if ($null -ne $Node.value -and [string]$Node.value.node -eq "FUNC_EXPR") {
                $name = [string]$Node.name
                if (-not [string]::IsNullOrWhiteSpace($name)) {
                    [void](Get-WasmAstFuncExprLiftName $Node.value $name -PublicName)
                    $script:wasmAstFunctionDefs[$name] = [pscustomobject]@{
                        Name = $name
                        Params = @(Get-WasmAstParamNames ($Node.value.params))
                        Node = $Node.value
                    }
                }
            }
        }
        "CLASS_DEF" { }
        default { }
    }
}

function Add-WasmAstFunctionExprPromotion {
    param(
        $FuncExpr,
        [System.Collections.Generic.List[object]]$Functions,
        [string]$DisplayName = "",
        [hashtable]$CaptureExprs = @{}
    )

    if ($null -eq $FuncExpr -or [string]$FuncExpr.node -ne "FUNC_EXPR") { return }
    $liftName = Get-WasmAstFuncExprLiftName $FuncExpr $DisplayName
    $promotedExpr = New-WasmAstCapturedFuncExpr $FuncExpr $CaptureExprs
    if (-not (Test-WasmAstFuncExprLiftable $promotedExpr)) {
        $FuncExpr | Add-Member -NotePropertyName "__wasm_func_expr_lift_skipped" -NotePropertyValue $true -Force
        return $false
    }
    $FuncExpr | Add-Member -NotePropertyName "__wasm_func_expr_lift_skipped" -NotePropertyValue $false -Force
    if (-not $script:wasmAstFunctionDefs.ContainsKey($liftName)) {
        $params = @(Get-WasmAstParamNames ($promotedExpr.params))
        $script:wasmAstFunctionDefs[$liftName] = [pscustomobject]@{
            Name = $liftName
            Params = $params
            Node = $promotedExpr
        }
        $Functions.Add([pscustomobject]@{
            Name = $liftName
            Params = $params
            Body = @()
            BodyAst = $promotedExpr.body
            WasmFuncExprPromotion = $true
            WasmFuncExprDisplayName = (Get-WasmAstFuncExprDisplayName $FuncExpr)
        }) | Out-Null
        # Promoted function expressions are dispatch candidates: pin every one
        # of them to the tagged-Value return ABI at promotion time. Without
        # this, the body's return conversion depends on classification state
        # that varies between fixtures (a bool capture emitted raw in one
        # module and tagged in another), which makes the boundary unwrap at
        # direct call sites impossible to get right.
        $script:wasmForcedValueReturnFunctions[$liftName] = $true
    }
    Add-WasmAstNestedFunctionExprPromotions -Node ($promotedExpr.body) -Functions $Functions -TopLevel $false -ScopeName $DisplayName -CaptureExprs (Copy-WasmAstCaptureMap $CaptureExprs)
    return $true
}

function Invoke-WasmAstPureReturnFuncExprFactoryBlock {
    param($Body, [hashtable]$CaptureExprs)

    if ($null -eq $Body) { return [pscustomobject]@{ Ok = $false; Returned = $false; FuncExpr = $null; CaptureExprs = @{} } }
    $localCaptures = Copy-WasmAstCaptureMap $CaptureExprs
    foreach ($stmt in @(As-WasmAstArray ($Body.body))) {
        if ($null -eq $stmt) { continue }
        switch ([string]$stmt.node) {
            "ASSIGN" {
                if (Test-WasmAstEffectfulExpr ($stmt.value)) { return [pscustomobject]@{ Ok = $false; Returned = $false; FuncExpr = $null; CaptureExprs = @{} } }
                $captureValue = Get-WasmAstPrimitiveCaptureExpr ($stmt.value) $localCaptures
                if ($null -eq $captureValue) { return [pscustomobject]@{ Ok = $false; Returned = $false; FuncExpr = $null; CaptureExprs = @{} } }
                $localCaptures[[string]$stmt.name] = $captureValue
            }
            "IF" {
                if (Test-WasmAstEffectfulExpr ($stmt.cond)) { return [pscustomobject]@{ Ok = $false; Returned = $false; FuncExpr = $null; CaptureExprs = @{} } }
                $condState = Get-WasmAstKnownBoolLiteralState ($stmt.cond)
                if ([string]::IsNullOrWhiteSpace($condState)) {
                    $capturedCond = Get-WasmAstPrimitiveCaptureExpr ($stmt.cond) $localCaptures
                    if ($null -ne $capturedCond -and [string]$capturedCond.node -eq "BOOL_LIT") {
                        $condState = $(if ([bool]$capturedCond.value) { "true" } else { "false" })
                    }
                }
                if ($condState -eq "true") {
                    $thenResult = Invoke-WasmAstPureReturnFuncExprFactoryBlock ($stmt.then_block) $localCaptures
                    if (-not [bool]$thenResult.Ok) { return $thenResult }
                    if ([bool]$thenResult.Returned) { return $thenResult }
                    $localCaptures = Copy-WasmAstCaptureMap $thenResult.CaptureExprs
                } elseif ($condState -eq "false") {
                    if ($null -ne $stmt.else_block) {
                        $elseResult = Invoke-WasmAstPureReturnFuncExprFactoryBlock ($stmt.else_block) $localCaptures
                        if (-not [bool]$elseResult.Ok) { return $elseResult }
                        if ([bool]$elseResult.Returned) { return $elseResult }
                        $localCaptures = Copy-WasmAstCaptureMap $elseResult.CaptureExprs
                    }
                } else {
                    $thenCaptures = Copy-WasmAstCaptureMap $localCaptures
                    $elseCaptures = Copy-WasmAstCaptureMap $localCaptures
                    $thenResult = Invoke-WasmAstPureReturnFuncExprFactoryBlock ($stmt.then_block) $thenCaptures
                    if ($null -ne $stmt.else_block) {
                        $elseResult = Invoke-WasmAstPureReturnFuncExprFactoryBlock ($stmt.else_block) $elseCaptures
                    } else {
                        $elseResult = [pscustomobject]@{
                            Ok = $true
                            Returned = $false
                            FuncExpr = $null
                            CaptureExprs = $elseCaptures
                        }
                    }
                    if (-not [bool]$thenResult.Ok -or -not [bool]$elseResult.Ok -or
                        [bool]$thenResult.Returned -or [bool]$elseResult.Returned) {
                        return [pscustomobject]@{ Ok = $false; Returned = $false; FuncExpr = $null; CaptureExprs = @{} }
                    }
                    Merge-WasmAstCaptureMapSet $localCaptures @($thenResult.CaptureExprs, $elseResult.CaptureExprs)
                }
            }
            "WHILE" {
                if (Test-WasmAstEffectfulExpr ($stmt.cond)) { return [pscustomobject]@{ Ok = $false; Returned = $false; FuncExpr = $null; CaptureExprs = @{} } }
                $condState = Get-WasmAstKnownBoolLiteralState ($stmt.cond)
                if ([string]::IsNullOrWhiteSpace($condState)) {
                    $capturedCond = Get-WasmAstPrimitiveCaptureExpr ($stmt.cond) $localCaptures
                    if ($null -ne $capturedCond -and [string]$capturedCond.node -eq "BOOL_LIT") {
                        $condState = $(if ([bool]$capturedCond.value) { "true" } else { "false" })
                    }
                }
                if ([string]::IsNullOrWhiteSpace($condState)) {
                    return [pscustomobject]@{ Ok = $false; Returned = $false; FuncExpr = $null; CaptureExprs = @{} }
                }
                if ($condState -eq "true") {
                    return [pscustomobject]@{ Ok = $false; Returned = $false; FuncExpr = $null; CaptureExprs = @{} }
                }
            }
            "MATCH" {
                $subject = if ($stmt.PSObject.Properties.Name -contains "subject") { $stmt.subject } else { $stmt.expr }
                if (Test-WasmAstEffectfulExpr $subject) { return [pscustomobject]@{ Ok = $false; Returned = $false; FuncExpr = $null; CaptureExprs = @{} } }
                $resolvedSubject = Get-WasmAstPrimitiveCaptureExpr $subject $localCaptures
                if ($null -eq $resolvedSubject) { $resolvedSubject = $subject }

                $matchedResult = $null
                $armResults = New-Object System.Collections.Generic.List[object]
                $hasWildcardArm = $false
                $hasUnknownArmMatch = $false
                foreach ($arm in @(As-WasmAstArray ($stmt.arms))) {
                    if ($null -ne $arm.pattern -and (Test-WasmAstEffectfulExpr ($arm.pattern))) {
                        return [pscustomobject]@{ Ok = $false; Returned = $false; FuncExpr = $null; CaptureExprs = @{} }
                    }
                    if ($null -ne $arm.range_end -and (Test-WasmAstEffectfulExpr ($arm.range_end))) {
                        return [pscustomobject]@{ Ok = $false; Returned = $false; FuncExpr = $null; CaptureExprs = @{} }
                    }
                    $armCaptures = Copy-WasmAstCaptureMap $localCaptures
                    $armResult = Invoke-WasmAstPureReturnFuncExprFactoryBlock ($arm.body) $armCaptures
                    if (-not [bool]$armResult.Ok) { return $armResult }
                    if ([bool]$armResult.Returned) { return [pscustomobject]@{ Ok = $false; Returned = $false; FuncExpr = $null; CaptureExprs = @{} } }
                    $armResults.Add($armResult.CaptureExprs) | Out-Null

                    $isWildcard = ($null -ne $arm.is_wildcard -and [bool]$arm.is_wildcard)
                    if ($isWildcard) {
                        $hasWildcardArm = $true
                        if ($null -eq $matchedResult -and -not $hasUnknownArmMatch) { $matchedResult = $armResult }
                        continue
                    }

                    $pattern = Get-WasmAstPrimitiveCaptureExpr ($arm.pattern) $localCaptures
                    if ($null -eq $pattern) { $pattern = $arm.pattern }
                    $rangeEnd = Get-WasmAstPrimitiveCaptureExpr ($arm.range_end) $localCaptures
                    if ($null -eq $rangeEnd) { $rangeEnd = $arm.range_end }
                    $matchState = Get-WasmAstLiteralMatchState $resolvedSubject $pattern $rangeEnd ([bool]$arm.is_range)
                    if ($matchState -eq "true") {
                        $matchedResult = $armResult
                        break
                    }
                    if ($matchState -eq "unknown") {
                        $matchedResult = $null
                        $hasUnknownArmMatch = $true
                    }
                }

                if ($null -ne $matchedResult) {
                    $localCaptures = Copy-WasmAstCaptureMap $matchedResult.CaptureExprs
                } elseif (-not $hasUnknownArmMatch -and -not $hasWildcardArm) {
                    # No arm is reachable; keep the pre-match captures unchanged.
                } else {
                    if (-not $hasWildcardArm) { $armResults.Add((Copy-WasmAstCaptureMap $localCaptures)) | Out-Null }
                    if ($armResults.Count -eq 0) { return [pscustomobject]@{ Ok = $false; Returned = $false; FuncExpr = $null; CaptureExprs = @{} } }
                    Merge-WasmAstCaptureMapSet $localCaptures @($armResults.ToArray())
                }
            }
            "REPEAT" {
                if (Test-WasmAstEffectfulExpr ($stmt.count)) { return [pscustomobject]@{ Ok = $false; Returned = $false; FuncExpr = $null; CaptureExprs = @{} } }
                $countExpr = Get-WasmAstPrimitiveCaptureExpr ($stmt.count) $localCaptures
                if ($null -eq $countExpr -or [string]$countExpr.node -ne "NUM_LIT") {
                    return [pscustomobject]@{ Ok = $false; Returned = $false; FuncExpr = $null; CaptureExprs = @{} }
                }
                $repeatCount = [int][Math]::Truncate([double]$countExpr.value)
                if ($repeatCount -lt 0 -or $repeatCount -gt 64) {
                    return [pscustomobject]@{ Ok = $false; Returned = $false; FuncExpr = $null; CaptureExprs = @{} }
                }
                for ($repeatIndex = 0; $repeatIndex -lt $repeatCount; $repeatIndex++) {
                    $repeatResult = Invoke-WasmAstPureReturnFuncExprFactoryBlock ($stmt.body) $localCaptures
                    if (-not [bool]$repeatResult.Ok) { return $repeatResult }
                    if ([bool]$repeatResult.Returned) { return $repeatResult }
                    $localCaptures = Copy-WasmAstCaptureMap $repeatResult.CaptureExprs
                }
            }
            "FOR" {
                if ((Test-WasmAstEffectfulExpr ($stmt.from)) -or (Test-WasmAstEffectfulExpr ($stmt.to)) -or (Test-WasmAstEffectfulExpr ($stmt.step))) {
                    return [pscustomobject]@{ Ok = $false; Returned = $false; FuncExpr = $null; CaptureExprs = @{} }
                }
                $iterationValues = Get-WasmAstStaticForIterationValues ($stmt.from) ($stmt.to) ($stmt.step) $localCaptures
                if ($null -eq $iterationValues) {
                    return [pscustomobject]@{ Ok = $false; Returned = $false; FuncExpr = $null; CaptureExprs = @{} }
                }
                $loopName = [string]$stmt.var
                foreach ($iterationValue in @($iterationValues)) {
                    if (-not [string]::IsNullOrWhiteSpace($loopName)) {
                        $localCaptures[$loopName] = New-WasmAstCaptureNumLit ([double]$iterationValue) $stmt
                    }
                    $forResult = Invoke-WasmAstPureReturnFuncExprFactoryBlock ($stmt.body) $localCaptures
                    if (-not [bool]$forResult.Ok) { return $forResult }
                    if ([bool]$forResult.Returned) { return $forResult }
                    $localCaptures = Copy-WasmAstCaptureMap $forResult.CaptureExprs
                }
                if (-not [string]::IsNullOrWhiteSpace($loopName) -and $localCaptures.ContainsKey($loopName)) {
                    $localCaptures.Remove($loopName)
                }
            }
            "FOREACH" {
                if (Test-WasmAstEffectfulExpr ($stmt.collection)) {
                    return [pscustomobject]@{ Ok = $false; Returned = $false; FuncExpr = $null; CaptureExprs = @{} }
                }
                $foreachInfo = Get-WasmAstStaticForeachCaptureEntries ($stmt.collection) $localCaptures
                if (-not [bool]$foreachInfo.Ok) {
                    return [pscustomobject]@{ Ok = $false; Returned = $false; FuncExpr = $null; CaptureExprs = @{} }
                }
                $name = [string]$stmt.var
                $name2 = [string]$stmt.var2
                foreach ($entry in @($foreachInfo.Entries)) {
                    if ([string]::IsNullOrWhiteSpace($name2)) {
                        if (-not [string]::IsNullOrWhiteSpace($name)) {
                            $localCaptures[$name] = Copy-WasmAstNodeJson ($entry.Value)
                        }
                    } else {
                        if (-not [string]::IsNullOrWhiteSpace($name)) {
                            $localCaptures[$name] = Copy-WasmAstNodeJson ($entry.Key)
                        }
                        $localCaptures[$name2] = Copy-WasmAstNodeJson ($entry.Value)
                    }
                    $foreachResult = Invoke-WasmAstPureReturnFuncExprFactoryBlock ($stmt.body) $localCaptures
                    if (-not [bool]$foreachResult.Ok) { return $foreachResult }
                    if ([bool]$foreachResult.Returned) { return $foreachResult }
                    $localCaptures = Copy-WasmAstCaptureMap $foreachResult.CaptureExprs
                }
                foreach ($loopName in @($name, $name2)) {
                    if (-not [string]::IsNullOrWhiteSpace($loopName) -and $localCaptures.ContainsKey($loopName)) {
                        $localCaptures.Remove($loopName)
                    }
                }
            }
            "RETURN" {
                if ($null -ne $stmt.value -and [string]$stmt.value.node -eq "FUNC_EXPR") {
                    return [pscustomobject]@{
                        Ok = $true
                        Returned = $true
                        FuncExpr = $stmt.value
                        CaptureExprs = $localCaptures
                    }
                }
                return [pscustomobject]@{ Ok = $false; Returned = $false; FuncExpr = $null; CaptureExprs = @{} }
            }
            default {
                return [pscustomobject]@{ Ok = $false; Returned = $false; FuncExpr = $null; CaptureExprs = @{} }
            }
        }
    }
    return [pscustomobject]@{ Ok = $true; Returned = $false; FuncExpr = $null; CaptureExprs = $localCaptures }
}

function Get-WasmAstPureReturnFuncExprFactoryInfo {
    param($Body, [hashtable]$CaptureExprs)

    $result = Invoke-WasmAstPureReturnFuncExprFactoryBlock $Body $CaptureExprs
    if ($null -eq $result -or -not [bool]$result.Ok -or -not [bool]$result.Returned) { return $null }
    return [pscustomobject]@{
        FuncExpr = $result.FuncExpr
        CaptureExprs = $result.CaptureExprs
    }
}

function Add-WasmAstSpecializedFunctionCallReturnPromotion {
    param(
        $CallExpr,
        [System.Collections.Generic.List[object]]$Functions,
        [string]$DisplayName = ""
    )

    if ($null -eq $CallExpr -or [string]$CallExpr.node -ne "CALL") { return }
    $key = Get-WasmAstExprHintKey $CallExpr
    if ([string]::IsNullOrWhiteSpace($key) -or $script:wasmSpecializedFunctionCallReturnLiftHints.ContainsKey($key)) { return }

    $name = [string]$CallExpr.name
    if ([string]::IsNullOrWhiteSpace($name) -or -not $script:wasmAstFunctionDefs.ContainsKey($name)) { return }
    $fn = $script:wasmAstFunctionDefs[$name]
    $params = @(Get-WasmAstParamNames ($fn.Node.params))
    $args = @(As-WasmAstArray ($CallExpr.args))
    if ($params.Count -ne $args.Count) { return }

    $captureExprs = @{}
    for ($i = 0; $i -lt $params.Count; $i++) {
        $captureExprs[[string]$params[$i]] = $args[$i]
    }

    $factoryInfo = Get-WasmAstPureReturnFuncExprFactoryInfo ($fn.Node.body) $captureExprs
    if ($null -eq $factoryInfo) { return }
    if (-not (Test-WasmAstFuncExprLiftSkipped $factoryInfo.FuncExpr)) { return }

    $callDisplayName = if (-not [string]::IsNullOrWhiteSpace($DisplayName)) { $DisplayName } else { "${name}_return" }
    $specializedExpr = New-WasmAstCapturedFuncExpr ($factoryInfo.FuncExpr) $factoryInfo.CaptureExprs
    foreach ($metaName in @("__wasm_func_expr_lift_name", "__wasm_func_expr_display_name", "__wasm_func_expr_lift_skipped")) {
        if ($specializedExpr.PSObject.Properties.Name -contains $metaName) {
            $specializedExpr.PSObject.Properties.Remove($metaName)
        }
    }
    if (-not (Test-WasmAstFuncExprLiftable $specializedExpr)) { return }

    $promoted = Add-WasmAstFunctionExprPromotion -FuncExpr $specializedExpr -Functions $Functions -DisplayName $callDisplayName -CaptureExprs @{}
    if (-not $promoted) { return }

    $liftName = Get-WasmAstFuncExprLiftName $specializedExpr $callDisplayName
    $script:wasmSpecializedFunctionCallReturnDisplayHints[$key] = Get-WasmAstFuncExprDisplayName $specializedExpr
    $script:wasmSpecializedFunctionCallReturnLiftHints[$key] = $liftName
}

function Add-WasmAstNestedFunctionExprPromotionsFromExpr {
    param(
        $Expr,
        [System.Collections.Generic.List[object]]$Functions,
        [string]$DisplayName = "",
        [hashtable]$CaptureExprs = @{}
    )

    if ($null -eq $Expr) { return }
    switch ([string]$Expr.node) {
        "FUNC_EXPR" {
            [void](Add-WasmAstFunctionExprPromotion -FuncExpr $Expr -Functions $Functions -DisplayName "<lambda>" -CaptureExprs $CaptureExprs)
        }
        "ARRAY_LIT" {
            $index = 0
            foreach ($element in @(As-WasmAstArray ($Expr.elements))) {
                Add-WasmAstNestedFunctionExprPromotionsFromExpr -Expr $element -Functions $Functions -DisplayName ("{0}_{1}" -f $(if ([string]::IsNullOrWhiteSpace($DisplayName)) { "item" } else { $DisplayName }), $index) -CaptureExprs $CaptureExprs
                $index++
            }
        }
        "DICT_LIT" {
            foreach ($entry in @(As-WasmAstArray ($Expr.entries))) {
                $keyName = [string]$entry.key
                if ([string]::IsNullOrWhiteSpace($keyName)) { $keyName = "value" }
                Add-WasmAstNestedFunctionExprPromotionsFromExpr -Expr ($entry.value) -Functions $Functions -DisplayName ("{0}_{1}" -f $(if ([string]::IsNullOrWhiteSpace($DisplayName)) { "field" } else { $DisplayName }), $keyName) -CaptureExprs $CaptureExprs
            }
        }
        "CALL" {
            Add-WasmAstSpecializedFunctionCallReturnPromotion -CallExpr $Expr -Functions $Functions -DisplayName $DisplayName
            $index = 0
            foreach ($arg in @(As-WasmAstArray ($Expr.args))) {
                Add-WasmAstNestedFunctionExprPromotionsFromExpr -Expr $arg -Functions $Functions -DisplayName ("{0}_arg{1}" -f ([string]$Expr.name), $index) -CaptureExprs $CaptureExprs
                $index++
            }
        }
        "METHOD_CALL" {
            Add-WasmAstNestedFunctionExprPromotionsFromExpr -Expr ($Expr.obj) -Functions $Functions -DisplayName $DisplayName -CaptureExprs $CaptureExprs
            $index = 0
            foreach ($arg in @(As-WasmAstArray ($Expr.args))) {
                Add-WasmAstNestedFunctionExprPromotionsFromExpr -Expr $arg -Functions $Functions -DisplayName ("{0}_arg{1}" -f ([string]$Expr.method), $index) -CaptureExprs $CaptureExprs
                $index++
            }
        }
        "SUPER_CALL" {
            $index = 0
            foreach ($arg in @(As-WasmAstArray ($Expr.args))) {
                Add-WasmAstNestedFunctionExprPromotionsFromExpr -Expr $arg -Functions $Functions -DisplayName ("super_{0}_arg{1}" -f ([string]$Expr.method), $index) -CaptureExprs $CaptureExprs
                $index++
            }
        }
        "NEW_EXPR" {
            $index = 0
            foreach ($arg in @(As-WasmAstArray ($Expr.args))) {
                Add-WasmAstNestedFunctionExprPromotionsFromExpr -Expr $arg -Functions $Functions -DisplayName ("{0}_arg{1}" -f ([string]$Expr.class_name), $index) -CaptureExprs $CaptureExprs
                $index++
            }
        }
        "BIN_OP" {
            Add-WasmAstNestedFunctionExprPromotionsFromExpr -Expr ($Expr.left) -Functions $Functions -DisplayName $DisplayName -CaptureExprs $CaptureExprs
            Add-WasmAstNestedFunctionExprPromotionsFromExpr -Expr ($Expr.right) -Functions $Functions -DisplayName $DisplayName -CaptureExprs $CaptureExprs
        }
        "UNARY_OP" {
            Add-WasmAstNestedFunctionExprPromotionsFromExpr -Expr ($Expr.operand) -Functions $Functions -DisplayName $DisplayName -CaptureExprs $CaptureExprs
        }
        "TERNARY" {
            Add-WasmAstNestedFunctionExprPromotionsFromExpr -Expr ($Expr.cond) -Functions $Functions -DisplayName $DisplayName -CaptureExprs $CaptureExprs
            Add-WasmAstNestedFunctionExprPromotionsFromExpr -Expr ($Expr.then) -Functions $Functions -DisplayName $DisplayName -CaptureExprs $CaptureExprs
            Add-WasmAstNestedFunctionExprPromotionsFromExpr -Expr ($Expr.else) -Functions $Functions -DisplayName $DisplayName -CaptureExprs $CaptureExprs
        }
        "DOT_ACCESS" {
            Add-WasmAstNestedFunctionExprPromotionsFromExpr -Expr ($Expr.obj) -Functions $Functions -DisplayName $DisplayName -CaptureExprs $CaptureExprs
        }
        "INDEX" {
            Add-WasmAstNestedFunctionExprPromotionsFromExpr -Expr ($Expr.obj) -Functions $Functions -DisplayName $DisplayName -CaptureExprs $CaptureExprs
            Add-WasmAstNestedFunctionExprPromotionsFromExpr -Expr ($Expr.key) -Functions $Functions -DisplayName $DisplayName -CaptureExprs $CaptureExprs
        }
        "STR_INTERP" {
            foreach ($part in @(As-WasmAstArray ($Expr.parts))) {
                if ($null -ne $part.expr) {
                    Add-WasmAstNestedFunctionExprPromotionsFromExpr -Expr ($part.expr) -Functions $Functions -DisplayName $DisplayName -CaptureExprs $CaptureExprs
                }
            }
        }
        default { }
    }
}

function Add-WasmAstNestedFunctionExprPromotions {
    param(
        $Node,
        [System.Collections.Generic.List[object]]$Functions,
        [bool]$TopLevel = $true,
        [string]$ScopeName = "",
        [hashtable]$CaptureExprs = @{}
    )

    if ($null -eq $Node) { return }
    switch ([string]$Node.node) {
        "SuraBlock" {
            $blockCaptures = Copy-WasmAstCaptureMap $CaptureExprs
            foreach ($stmt in @(As-WasmAstArray ($Node.body))) {
                Add-WasmAstNestedFunctionExprPromotions -Node $stmt -Functions $Functions -TopLevel $TopLevel -ScopeName $ScopeName -CaptureExprs $blockCaptures
            }
            Set-WasmAstCaptureMap $CaptureExprs $blockCaptures
        }
        "FUNC_DEF" {
            foreach ($paramDefault in @(As-WasmAstArray ($Node.params))) {
                if ($null -ne $paramDefault.default) {
                    Add-WasmAstNestedFunctionExprPromotionsFromExpr -Expr ($paramDefault.default) -Functions $Functions
                }
            }
            Add-WasmAstNestedFunctionExprPromotions -Node ($Node.body) -Functions $Functions -TopLevel $false -ScopeName ([string]$Node.name)
        }
        "ASSIGN" {
            if ($null -ne $Node.value -and [string]$Node.value.node -eq "FUNC_EXPR") {
                if (-not $TopLevel) {
                    $promoted = Add-WasmAstFunctionExprPromotion -FuncExpr ($Node.value) -Functions $Functions -DisplayName ([string]$Node.name) -CaptureExprs $CaptureExprs
                    $liftName = if ($promoted) { Get-WasmAstFuncExprLiftName ($Node.value) ([string]$Node.name) } else { "" }
                    if (-not [string]::IsNullOrWhiteSpace($liftName)) {
                        $CaptureExprs[[string]$Node.name] = New-WasmAstCaptureIdent $liftName $Node
                    } elseif ($CaptureExprs.ContainsKey([string]$Node.name)) {
                        $CaptureExprs.Remove([string]$Node.name)
                    }
                } else {
                    Add-WasmAstNestedFunctionExprPromotions -Node ($Node.value.body) -Functions $Functions -TopLevel $false -ScopeName ([string]$Node.name)
                    if ($CaptureExprs.ContainsKey([string]$Node.name)) { $CaptureExprs.Remove([string]$Node.name) }
                }
            } elseif ($null -ne $Node.value) {
                Add-WasmAstNestedFunctionExprPromotionsFromExpr -Expr ($Node.value) -Functions $Functions -DisplayName ([string]$Node.name) -CaptureExprs $CaptureExprs
                $captureValue = Get-WasmAstPrimitiveCaptureExpr ($Node.value) $CaptureExprs
                if ($null -ne $captureValue) {
                    $CaptureExprs[[string]$Node.name] = $captureValue
                } elseif ($CaptureExprs.ContainsKey([string]$Node.name)) {
                    $CaptureExprs.Remove([string]$Node.name)
                }
            }
        }
        "CLASS_DEF" {
            foreach ($method in @(As-WasmAstArray ($Node.methods))) {
                Add-WasmAstNestedFunctionExprPromotions -Node ($method.body) -Functions $Functions -TopLevel $false -ScopeName ("{0}_{1}" -f ([string]$Node.name), ([string]$method.name))
            }
        }
        "IF" {
            Add-WasmAstNestedFunctionExprPromotionsFromExpr -Expr ($Node.cond) -Functions $Functions -CaptureExprs $CaptureExprs
            $condState = Get-WasmAstKnownBoolLiteralState ($Node.cond)
            if ([string]::IsNullOrWhiteSpace($condState)) {
                $capturedCond = Get-WasmAstPrimitiveCaptureExpr ($Node.cond) $CaptureExprs
                if ($null -ne $capturedCond -and [string]$capturedCond.node -eq "BOOL_LIT") {
                    $condState = $(if ([bool]$capturedCond.value) { "true" } else { "false" })
                }
            }
            if ($condState -eq "true") {
                Add-WasmAstNestedFunctionExprPromotions -Node ($Node.then_block) -Functions $Functions -TopLevel $false -ScopeName $ScopeName -CaptureExprs $CaptureExprs
                return
            }
            if ($condState -eq "false") {
                Add-WasmAstNestedFunctionExprPromotions -Node ($Node.else_block) -Functions $Functions -TopLevel $false -ScopeName $ScopeName -CaptureExprs $CaptureExprs
                return
            }
            $thenCaptures = Copy-WasmAstCaptureMap $CaptureExprs
            $elseCaptures = Copy-WasmAstCaptureMap $CaptureExprs
            Add-WasmAstNestedFunctionExprPromotions -Node ($Node.then_block) -Functions $Functions -TopLevel $false -ScopeName $ScopeName -CaptureExprs $thenCaptures
            Add-WasmAstNestedFunctionExprPromotions -Node ($Node.else_block) -Functions $Functions -TopLevel $false -ScopeName $ScopeName -CaptureExprs $elseCaptures
            Merge-WasmAstBranchCaptureMaps $CaptureExprs $thenCaptures $elseCaptures
        }
        "WHILE" {
            Add-WasmAstNestedFunctionExprPromotionsFromExpr -Expr ($Node.cond) -Functions $Functions -CaptureExprs $CaptureExprs
            $condState = Get-WasmAstKnownBoolLiteralState ($Node.cond)
            if ([string]::IsNullOrWhiteSpace($condState)) {
                $capturedCond = Get-WasmAstPrimitiveCaptureExpr ($Node.cond) $CaptureExprs
                if ($null -ne $capturedCond -and [string]$capturedCond.node -eq "BOOL_LIT") {
                    $condState = $(if ([bool]$capturedCond.value) { "true" } else { "false" })
                }
            }
            if ($condState -eq "false") {
                return
            }
            Add-WasmAstNestedFunctionExprPromotions -Node ($Node.body) -Functions $Functions -TopLevel $false -ScopeName $ScopeName -CaptureExprs (Copy-WasmAstCaptureMap $CaptureExprs)
        }
        "REPEAT" {
            Add-WasmAstNestedFunctionExprPromotionsFromExpr -Expr ($Node.count) -Functions $Functions -CaptureExprs $CaptureExprs
            $countCapture = Get-WasmAstPrimitiveCaptureExpr ($Node.count) $CaptureExprs
            if ($null -ne $countCapture -and [string]$countCapture.node -eq "NUM_LIT") {
                $repeatCount = [int][Math]::Truncate([double]$countCapture.value)
                if ($repeatCount -ge 0 -and $repeatCount -le 64) {
                    for ($repeatIndex = 0; $repeatIndex -lt $repeatCount; $repeatIndex++) {
                        Add-WasmAstNestedFunctionExprPromotions -Node ($Node.body) -Functions $Functions -TopLevel $false -ScopeName $ScopeName -CaptureExprs $CaptureExprs
                    }
                } elseif ($repeatCount -ne 0) {
                    Add-WasmAstNestedFunctionExprPromotions -Node ($Node.body) -Functions $Functions -TopLevel $false -ScopeName $ScopeName -CaptureExprs (Copy-WasmAstCaptureMap $CaptureExprs)
                }
            } else {
                Add-WasmAstNestedFunctionExprPromotions -Node ($Node.body) -Functions $Functions -TopLevel $false -ScopeName $ScopeName -CaptureExprs (Copy-WasmAstCaptureMap $CaptureExprs)
            }
        }
        "FOR" {
            Add-WasmAstNestedFunctionExprPromotionsFromExpr -Expr ($Node.from) -Functions $Functions -CaptureExprs $CaptureExprs
            Add-WasmAstNestedFunctionExprPromotionsFromExpr -Expr ($Node.to) -Functions $Functions -CaptureExprs $CaptureExprs
            Add-WasmAstNestedFunctionExprPromotionsFromExpr -Expr ($Node.step) -Functions $Functions -CaptureExprs $CaptureExprs
            $iterationValues = Get-WasmAstStaticForIterationValues ($Node.from) ($Node.to) ($Node.step) $CaptureExprs
            if ($null -ne $iterationValues) {
                $loopName = [string]$Node.var
                foreach ($iterationValue in @($iterationValues)) {
                    if (-not [string]::IsNullOrWhiteSpace($loopName)) {
                        $CaptureExprs[$loopName] = New-WasmAstCaptureNumLit ([double]$iterationValue) $Node
                    }
                    Add-WasmAstNestedFunctionExprPromotions -Node ($Node.body) -Functions $Functions -TopLevel $false -ScopeName $ScopeName -CaptureExprs $CaptureExprs
                }
                if (-not [string]::IsNullOrWhiteSpace($loopName) -and $CaptureExprs.ContainsKey($loopName)) {
                    $CaptureExprs.Remove($loopName)
                }
            } else {
                $loopCaptures = Copy-WasmAstCaptureMap $CaptureExprs
                if ($loopCaptures.ContainsKey([string]$Node.var)) { $loopCaptures.Remove([string]$Node.var) }
                Add-WasmAstNestedFunctionExprPromotions -Node ($Node.body) -Functions $Functions -TopLevel $false -ScopeName $ScopeName -CaptureExprs $loopCaptures
            }
        }
        "FOREACH" {
            Add-WasmAstNestedFunctionExprPromotionsFromExpr -Expr ($Node.collection) -Functions $Functions -CaptureExprs $CaptureExprs
            $foreachInfo = Get-WasmAstStaticForeachCaptureEntries ($Node.collection) $CaptureExprs
            if ([bool]$foreachInfo.Ok) {
                $name = [string]$Node.var
                $name2 = [string]$Node.var2
                foreach ($entry in @($foreachInfo.Entries)) {
                    if ([string]::IsNullOrWhiteSpace($name2)) {
                        if (-not [string]::IsNullOrWhiteSpace($name)) {
                            $CaptureExprs[$name] = Copy-WasmAstNodeJson ($entry.Value)
                        }
                    } else {
                        if (-not [string]::IsNullOrWhiteSpace($name)) {
                            $CaptureExprs[$name] = Copy-WasmAstNodeJson ($entry.Key)
                        }
                        $CaptureExprs[$name2] = Copy-WasmAstNodeJson ($entry.Value)
                    }
                    Add-WasmAstNestedFunctionExprPromotions -Node ($Node.body) -Functions $Functions -TopLevel $false -ScopeName $ScopeName -CaptureExprs $CaptureExprs
                }
                foreach ($loopName in @($name, $name2)) {
                    if (-not [string]::IsNullOrWhiteSpace($loopName) -and $CaptureExprs.ContainsKey($loopName)) {
                        $CaptureExprs.Remove($loopName)
                    }
                }
            } else {
                $loopCaptures = Copy-WasmAstCaptureMap $CaptureExprs
                if ($loopCaptures.ContainsKey([string]$Node.var)) { $loopCaptures.Remove([string]$Node.var) }
                if ($loopCaptures.ContainsKey([string]$Node.var2)) { $loopCaptures.Remove([string]$Node.var2) }
                Add-WasmAstNestedFunctionExprPromotions -Node ($Node.body) -Functions $Functions -TopLevel $false -ScopeName $ScopeName -CaptureExprs $loopCaptures
            }
        }
        "MATCH" {
            $subject = if ($Node.PSObject.Properties.Name -contains "subject") { $Node.subject } else { $Node.expr }
            Add-WasmAstNestedFunctionExprPromotionsFromExpr -Expr $subject -Functions $Functions -CaptureExprs $CaptureExprs
            $resolvedSubject = Get-WasmAstPrimitiveCaptureExpr $subject $CaptureExprs
            if ($null -eq $resolvedSubject) { $resolvedSubject = $subject }
            $armCaptureMaps = New-Object System.Collections.Generic.List[object]
            $hasWildcardArm = $false
            $hasUnknownArmMatch = $false
            foreach ($arm in @(As-WasmAstArray ($Node.arms))) {
                $isWildcard = ($null -ne $arm.is_wildcard -and [bool]$arm.is_wildcard)
                if ($isWildcard) { $hasWildcardArm = $true }
                Add-WasmAstNestedFunctionExprPromotionsFromExpr -Expr ($arm.pattern) -Functions $Functions -CaptureExprs $CaptureExprs
                if (-not $isWildcard) {
                    $pattern = Get-WasmAstPrimitiveCaptureExpr ($arm.pattern) $CaptureExprs
                    if ($null -eq $pattern) { $pattern = $arm.pattern }
                    $rangeEnd = Get-WasmAstPrimitiveCaptureExpr ($arm.range_end) $CaptureExprs
                    if ($null -eq $rangeEnd) { $rangeEnd = $arm.range_end }
                    $matchState = Get-WasmAstLiteralMatchState $resolvedSubject $pattern $rangeEnd ([bool]$arm.is_range)
                    if ($matchState -eq "false") { continue }
                    if ($matchState -eq "unknown") { $hasUnknownArmMatch = $true }
                    if ($matchState -eq "true" -and -not $hasUnknownArmMatch) {
                        Add-WasmAstNestedFunctionExprPromotions -Node ($arm.body) -Functions $Functions -TopLevel $false -ScopeName $ScopeName -CaptureExprs $CaptureExprs
                        return
                    }
                } elseif (-not $hasUnknownArmMatch) {
                    Add-WasmAstNestedFunctionExprPromotions -Node ($arm.body) -Functions $Functions -TopLevel $false -ScopeName $ScopeName -CaptureExprs $CaptureExprs
                    return
                }
                $armCaptures = Copy-WasmAstCaptureMap $CaptureExprs
                Add-WasmAstNestedFunctionExprPromotions -Node ($arm.body) -Functions $Functions -TopLevel $false -ScopeName $ScopeName -CaptureExprs $armCaptures
                $armCaptureMaps.Add($armCaptures) | Out-Null
            }
            if (-not $hasUnknownArmMatch -and -not $hasWildcardArm) {
                return
            }
            if (-not $hasWildcardArm) {
                $armCaptureMaps.Add((Copy-WasmAstCaptureMap $CaptureExprs)) | Out-Null
            }
            if ($armCaptureMaps.Count -gt 0) {
                Merge-WasmAstCaptureMapSet $CaptureExprs @($armCaptureMaps.ToArray())
            }
        }
        "TRY" {
            Add-WasmAstNestedFunctionExprPromotions -Node ($Node.try_block) -Functions $Functions -TopLevel $false -ScopeName $ScopeName -CaptureExprs (Copy-WasmAstCaptureMap $CaptureExprs)
            $catchCaptures = Copy-WasmAstCaptureMap $CaptureExprs
            if ($catchCaptures.ContainsKey([string]$Node.catch_var)) { $catchCaptures.Remove([string]$Node.catch_var) }
            Add-WasmAstNestedFunctionExprPromotions -Node ($Node.catch_block) -Functions $Functions -TopLevel $false -ScopeName $ScopeName -CaptureExprs $catchCaptures
            Add-WasmAstNestedFunctionExprPromotions -Node ($Node.finally_block) -Functions $Functions -TopLevel $false -ScopeName $ScopeName -CaptureExprs (Copy-WasmAstCaptureMap $CaptureExprs)
        }
        "RETURN" {
            if ($null -ne $Node.value -and [string]$Node.value.node -eq "FUNC_EXPR") {
                $returnDisplayName = if (-not [string]::IsNullOrWhiteSpace($ScopeName)) { "${ScopeName}_return" } else { "return" }
                [void](Add-WasmAstFunctionExprPromotion -FuncExpr ($Node.value) -Functions $Functions -DisplayName $returnDisplayName -CaptureExprs $CaptureExprs)
            } else {
                Add-WasmAstNestedFunctionExprPromotionsFromExpr -Expr ($Node.value) -Functions $Functions -CaptureExprs $CaptureExprs
            }
        }
        "EXPR_STMT" {
            Add-WasmAstNestedFunctionExprPromotionsFromExpr -Expr ($Node.expr) -Functions $Functions -CaptureExprs $CaptureExprs
        }
        "THROW" {
            Add-WasmAstNestedFunctionExprPromotionsFromExpr -Expr ($Node.value) -Functions $Functions -CaptureExprs $CaptureExprs
        }
        "DOT_ASSIGN" {
            Add-WasmAstNestedFunctionExprPromotionsFromExpr -Expr ($Node.obj) -Functions $Functions -CaptureExprs $CaptureExprs
            Add-WasmAstNestedFunctionExprPromotionsFromExpr -Expr ($Node.value) -Functions $Functions -CaptureExprs $CaptureExprs
            Remove-WasmAstCaptureMutationRoot $CaptureExprs ($Node.obj)
        }
        "INDEX_ASSIGN" {
            Add-WasmAstNestedFunctionExprPromotionsFromExpr -Expr ($Node.obj) -Functions $Functions -CaptureExprs $CaptureExprs
            Add-WasmAstNestedFunctionExprPromotionsFromExpr -Expr ($Node.key) -Functions $Functions -CaptureExprs $CaptureExprs
            Add-WasmAstNestedFunctionExprPromotionsFromExpr -Expr ($Node.value) -Functions $Functions -CaptureExprs $CaptureExprs
            Remove-WasmAstCaptureMutationRoot $CaptureExprs ($Node.obj)
        }
        default { }
    }
}

function Register-WasmAstModuleGlobals {
    param($Node)

    if ($null -eq $Node) { return }
    switch ([string]$Node.node) {
        "SuraBlock" {
            foreach ($stmt in @(As-WasmAstArray ($Node.body))) { Register-WasmAstModuleGlobals $stmt }
        }
        "GLOBAL_DECL" {
            foreach ($nameValue in @(As-WasmAstArray ($Node.names))) {
                $name = [string]$nameValue
                if (-not [string]::IsNullOrWhiteSpace($name)) {
                    $script:wasmModuleGlobals[$name] = $true
                }
            }
        }
        "FUNC_DEF" {
            Register-WasmAstModuleGlobals ($Node.body)
        }
        "ASSIGN" {
            if ($null -ne $Node.value -and [string]$Node.value.node -eq "FUNC_EXPR") {
                Register-WasmAstModuleGlobals ($Node.value.body)
            }
        }
        "CLASS_DEF" {
            foreach ($method in @(As-WasmAstArray ($Node.methods))) {
                Register-WasmAstModuleGlobals ($method.body)
            }
        }
        "IF" {
            Register-WasmAstModuleGlobals ($Node.then_block)
            Register-WasmAstModuleGlobals ($Node.else_block)
        }
        "WHILE" { Register-WasmAstModuleGlobals ($Node.body) }
        "REPEAT" { Register-WasmAstModuleGlobals ($Node.body) }
        "FOR" { Register-WasmAstModuleGlobals ($Node.body) }
        "FOREACH" { Register-WasmAstModuleGlobals ($Node.body) }
        "MATCH" {
            foreach ($arm in @(As-WasmAstArray ($Node.arms))) { Register-WasmAstModuleGlobals ($arm.body) }
        }
        "TRY" {
            Register-WasmAstModuleGlobals ($Node.try_block)
            Register-WasmAstModuleGlobals ($Node.catch_block)
            Register-WasmAstModuleGlobals ($Node.finally_block)
        }
        default { }
    }
}

function Add-WasmAstGlobalDeclNames {
    param(
        $Node,
        [Parameter(Mandatory=$true)][hashtable]$Out
    )

    if ($null -eq $Node) { return }
    switch ([string]$Node.node) {
        "SuraBlock" {
            foreach ($stmt in @(As-WasmAstArray ($Node.body))) { Add-WasmAstGlobalDeclNames $stmt $Out }
        }
        "GLOBAL_DECL" {
            foreach ($nameValue in @(As-WasmAstArray ($Node.names))) {
                $name = [string]$nameValue
                if (-not [string]::IsNullOrWhiteSpace($name)) {
                    $Out[$name] = $true
                }
            }
        }
        "IF" {
            Add-WasmAstGlobalDeclNames ($Node.then_block) $Out
            Add-WasmAstGlobalDeclNames ($Node.else_block) $Out
        }
        "WHILE" { Add-WasmAstGlobalDeclNames ($Node.body) $Out }
        "REPEAT" { Add-WasmAstGlobalDeclNames ($Node.body) $Out }
        "FOR" { Add-WasmAstGlobalDeclNames ($Node.body) $Out }
        "FOREACH" { Add-WasmAstGlobalDeclNames ($Node.body) $Out }
        "MATCH" {
            foreach ($arm in @(As-WasmAstArray ($Node.arms))) { Add-WasmAstGlobalDeclNames ($arm.body) $Out }
        }
        "TRY" {
            Add-WasmAstGlobalDeclNames ($Node.try_block) $Out
            Add-WasmAstGlobalDeclNames ($Node.catch_block) $Out
            Add-WasmAstGlobalDeclNames ($Node.finally_block) $Out
        }
        default { }
    }
}

function New-WasmAstGlobalDeclMap {
    param($Node)
    $out = @{}
    Add-WasmAstGlobalDeclNames $Node $out
    return $out
}

function Test-WasmAstClassSupported {
    param(
        [Parameter(Mandatory=$true)][string]$ClassName,
        [hashtable]$Seen = @{}
    )

    if (-not $script:wasmClassDefs.ContainsKey($ClassName) -or $Seen.ContainsKey($ClassName)) { return $false }
    $Seen[$ClassName] = $true
    $parent = [string]$script:wasmClassDefs[$ClassName].Parent
    if ([string]::IsNullOrWhiteSpace($parent)) { return $true }
    return (Test-WasmAstClassSupported -ClassName $parent -Seen $Seen)
}

function Test-WasmAstSuperInitStmt {
    param($Stmt)

    return ($null -ne $Stmt -and
        [string]$Stmt.node -eq "EXPR_STMT" -and
        $null -ne $Stmt.expr -and
        [string]$Stmt.expr.node -eq "SUPER_CALL" -and
        [string]$Stmt.expr.method -eq "init")
}

function Get-WasmAstSuperInitArgs {
    param($Body)

    if ($null -eq $Body) { return $null }
    foreach ($stmt in @(As-WasmAstArray ($Body.body))) {
        if (Test-WasmAstSuperInitStmt $stmt) {
            return $stmt.expr.args
        }
    }
    return $null
}

function New-WasmAstClassConstructorFunction {
    param($ClassNode)

    $className = [string]$ClassNode.name
    $parent = [string]$ClassNode.parent
    if ([string]::IsNullOrWhiteSpace($className)) {
        return $null
    }
    if (-not [string]::IsNullOrWhiteSpace($parent) -and -not (Test-WasmAstClassSupported -ClassName $parent)) {
        return $null
    }

    $fields = New-Object System.Collections.Generic.List[object]
    $seen = @{}
    foreach ($field in @(As-WasmAstArray ($ClassNode.fields))) {
        $fieldName = [string]$field.name
        $defaultValue = $null
        if ($null -ne $field -and $field.PSObject.Properties.Name -contains "default") {
            $defaultValue = $field.PSObject.Properties["default"].Value
        }
        Add-WasmClassField -Fields $fields -Seen $seen -Name $fieldName -DefaultValue $defaultValue
    }

    $init = Get-WasmAstClassInitMethod $ClassNode
    if ($null -ne $init) {
        Add-WasmClassSelfFieldsFromBody -Body ($init.body) -Fields $fields -Seen $seen
    }

    $body = New-Object System.Collections.Generic.List[object]
    $superInitArgs = if (-not [string]::IsNullOrWhiteSpace($parent) -and $null -ne $init) {
        Get-WasmAstSuperInitArgs ($init.body)
    } else {
        $null
    }
    if ($null -ne $superInitArgs) {
        $body.Add([pscustomobject]@{
            node = "ASSIGN"
            line = [int]$ClassNode.line
            name = "self"
            value = [pscustomobject]@{
                node = "NEW_EXPR"
                line = [int]$ClassNode.line
                class_name = $parent
                args = @(As-WasmAstArray $superInitArgs)
            }
        }) | Out-Null
    } else {
        $body.Add([pscustomobject]@{
            node = "ASSIGN"
            line = [int]$ClassNode.line
            name = "self"
            value = [pscustomobject]@{
                node = "DICT_LIT"
                line = [int]$ClassNode.line
                entries = @($fields.ToArray())
            }
        }) | Out-Null
    }

    if ($null -ne $init) {
        foreach ($stmt in @(As-WasmAstArray ($init.body.body))) {
            if (Test-WasmAstSuperInitStmt $stmt) { continue }
            $body.Add($stmt) | Out-Null
        }
    }

    $body.Add([pscustomobject]@{
        node = "EXPR_STMT"
        line = [int]$ClassNode.line
        expr = [pscustomobject]@{
            node = "WASM_OBJECT_REGISTER"
            line = [int]$ClassNode.line
            class_name = $className
            value = [pscustomobject]@{ node = "IDENT"; line = [int]$ClassNode.line; name = "self" }
        }
    }) | Out-Null

    $body.Add([pscustomobject]@{
        node = "RETURN"
        line = [int]$ClassNode.line
        value = [pscustomobject]@{ node = "IDENT"; line = [int]$ClassNode.line; name = "self" }
    }) | Out-Null

    $ctorParams = if ($null -ne $init) { @(Get-WasmAstParamNames ($init.params)) } else { @() }
    return [pscustomobject]@{
        Name = Get-WasmClassConstructorName $className
        Params = $ctorParams
        Body = @()
        BodyAst = [pscustomobject]@{ node = "SuraBlock"; line = [int]$ClassNode.line; body = @($body.ToArray()) }
        WasmClassConstructor = $true
    }
}

function Test-WasmAstStringExprCandidate {
    param($Node)

    if ($null -eq $Node) { return $false }
    if ((Get-WasmAstStaticValueType $Node) -eq "string") { return $true }
    if (Test-WasmAstKnownStringValueExprCandidate $Node) { return $true }
    switch ([string]$Node.node) {
        "STR_LIT" { return $true }
        "STR_INTERP" { return $true }
        "BIN_OP" {
            if ([string]$Node.op -eq "??") {
                return ((Test-WasmAstStringExprCandidate ($Node.left)) -or
                    (Test-WasmAstStringExprCandidate ($Node.right)))
            }
            if ([string]$Node.op -ne "+") { return $false }
            return ((Test-WasmAstStringExprCandidate ($Node.left)) -or (Test-WasmAstStringExprCandidate ($Node.right)))
        }
        "TERNARY" {
            if (-not (Test-WasmAstStringConvertibleExprCandidate ($Node.then)) -or
                -not (Test-WasmAstStringConvertibleExprCandidate ($Node.else))) {
                return $false
            }
            return ((Test-WasmAstStringExprCandidate ($Node.then)) -or (Test-WasmAstStringExprCandidate ($Node.else)))
        }
        default { return $false }
    }
}

function Test-WasmAstStringConvertibleExprCandidate {
    param($Node)

    if ($null -eq $Node) { return $true }
    $typeName = Get-WasmAstKnownValueType $Node
    if ([string]::IsNullOrWhiteSpace($typeName)) {
        $typeName = Get-WasmAstStaticValueType $Node
    }
    if ($typeName -in @("string", "bool", "nil", "num")) { return $true }
    switch ([string]$Node.node) {
        "STR_LIT" { return $true }
        "STR_INTERP" { return $true }
        "BOOL_LIT" { return $true }
        "NIL_LIT" { return $true }
        "NUM_LIT" { return $true }
        "BIN_OP" {
            if ([string]$Node.op -eq "??") {
                return (((Test-WasmAstStringConvertibleExprCandidate ($Node.left)) -or (Test-WasmAstOptionalAccessExpr ($Node.left))) -and
                    (Test-WasmAstStringConvertibleExprCandidate ($Node.right)))
            }
            return ([string]$Node.op -eq "+" -and
                ((Test-WasmAstStringExprCandidate ($Node.left)) -or (Test-WasmAstStringExprCandidate ($Node.right))))
        }
        "TERNARY" {
            return ((Test-WasmAstStringConvertibleExprCandidate ($Node.then)) -and
                (Test-WasmAstStringConvertibleExprCandidate ($Node.else)))
        }
        default { return $false }
    }
}

function Test-WasmAstOptionalAccessExpr {
    param($Node)

    if ($null -eq $Node) { return $false }
    switch ([string]$Node.node) {
        "DOT_ACCESS" {
            if ($null -ne $Node.optional -and [bool]$Node.optional) { return $true }
            return (Test-WasmAstOptionalAccessExpr ($Node.obj))
        }
        "INDEX" {
            if ($null -ne $Node.optional -and [bool]$Node.optional) { return $true }
            return ((Test-WasmAstOptionalAccessExpr ($Node.obj)) -or (Test-WasmAstOptionalAccessExpr ($Node.key)))
        }
        default { return $false }
    }
}

function Test-WasmAstStringAccessExprCandidate {
    param($Node)

    if ($null -eq $Node) { return $false }
    switch ([string]$Node.node) {
        "DOT_ACCESS" { return $true }
        "INDEX" { return $true }
        default { return $false }
    }
}

function Get-WasmAstStringAccessHintKey {
    param($Node)

    if ($null -eq $Node) { return "" }
    switch ([string]$Node.node) {
        "DOT_ACCESS" {
            if ($null -ne $Node.obj -and [string]$Node.obj.node -eq "IDENT") {
                return "$([string]$Node.obj.name).$([string]$Node.prop)"
            }
            return ""
        }
        "INDEX" {
            if ($null -ne $Node.obj -and [string]$Node.obj.node -eq "IDENT" -and
                $null -ne $Node.key -and [string]$Node.key.node -eq "STR_LIT") {
                return "$([string]$Node.obj.name).$([string]$Node.key.value)"
            }
            if ($null -ne $Node.obj -and [string]$Node.obj.node -eq "IDENT" -and
                $null -ne $Node.key -and [string]$Node.key.node -eq "NUM_LIT") {
                $indexValue = [int][Math]::Truncate([double]$Node.key.value)
                return ("{0}[{1}]" -f ([string]$Node.obj.name), $indexValue)
            }
            if ($null -ne $Node.obj -and [string]$Node.obj.node -eq "IDENT" -and $null -ne $Node.key) {
                $literalKey = Get-WasmAstKnownStringLiteralValue ($Node.key)
                if (-not [string]::IsNullOrWhiteSpace($literalKey)) {
                    return "$([string]$Node.obj.name).$literalKey"
                }
                $literalIndex = Get-WasmAstKnownNumericLiteralValue ($Node.key)
                if ($null -ne $literalIndex) {
                    $indexValue = [int][Math]::Truncate([double]$literalIndex)
                    return ("{0}[{1}]" -f ([string]$Node.obj.name), $indexValue)
                }
            }
            if ($null -ne $Node.obj -and [string]$Node.obj.node -eq "IDENT" -and
                $null -ne $Node.key -and [string]$Node.key.node -eq "IDENT") {
                $literalKey = Get-WasmAstKnownStringLiteralValue ($Node.key)
                if (-not [string]::IsNullOrWhiteSpace($literalKey)) {
                    return "$([string]$Node.obj.name).$literalKey"
                }
                $dynamicKey = ('{0}[${1}]' -f ([string]$Node.obj.name), [string]$Node.key.name)
                if ($script:wasmAccessTypeHints.ContainsKey($dynamicKey) -or
                    $script:wasmConflictedAccessTypeHints.ContainsKey($dynamicKey) -or
                    $script:wasmAccessObjectClassHints.ContainsKey($dynamicKey) -or
                    $script:wasmConflictedAccessObjectClassHints.ContainsKey($dynamicKey) -or
                    $script:wasmAccessFunctionDisplayHints.ContainsKey($dynamicKey) -or
                    $script:wasmConflictedAccessFunctionDisplayHints.ContainsKey($dynamicKey) -or
                    $script:wasmStringAccessHints.ContainsKey($dynamicKey)) {
                    return $dynamicKey
                }
                return $dynamicKey
            }
            return ""
        }
        default { return "" }
    }
}

function Test-WasmAstKnownStringAccessExprCandidate {
    param($Node)

    $key = Get-WasmAstStringAccessHintKey $Node
    if (-not [string]::IsNullOrWhiteSpace($key) -and $script:wasmConflictedAccessTypeHints.ContainsKey($key)) {
        return $false
    }
    if (-not [string]::IsNullOrWhiteSpace($key) -and $script:wasmAccessTypeHints.ContainsKey($key)) {
        return ([string]$script:wasmAccessTypeHints[$key] -eq "string")
    }
    return ((Get-WasmAstKnownValueType $Node) -eq "string")
}

function Test-WasmAstKnownStringValueExprCandidate {
    param($Node)

    if ($null -eq $Node) { return $false }
    if ([string]$Node.node -eq "IDENT") {
        $name = [string]$Node.name
        if ($script:wasmConflictedValueTypeHints.ContainsKey($name)) { return $false }
        if ($script:wasmValueTypeHints.ContainsKey($name)) {
            return ([string]$script:wasmValueTypeHints[$name] -eq "string")
        }
        return ((Get-WasmAstKnownValueType $Node) -eq "string")
    }
    return (Test-WasmAstKnownStringAccessExprCandidate $Node)
}

function Add-WasmAstStringValueHint {
    param([string]$Name)

    if ([string]::IsNullOrWhiteSpace($Name)) { return }
    $script:wasmStringValueHints[$Name] = $true
}

function Set-WasmAstStringLiteralValueHint {
    param([string]$Name, [string]$Value)

    if ([string]::IsNullOrWhiteSpace($Name)) { return }
    if ($script:wasmConflictedStringLiteralValueHints.ContainsKey($Name)) { return }
    if ($script:wasmStringLiteralValueHints.ContainsKey($Name) -and
        [string]$script:wasmStringLiteralValueHints[$Name] -ne $Value) {
        $script:wasmStringLiteralValueHints.Remove($Name)
        $script:wasmConflictedStringLiteralValueHints[$Name] = $true
        return
    }
    $script:wasmStringLiteralValueHints[$Name] = $Value
}

function Clear-WasmAstStringLiteralValueHint {
    param([string]$Name)

    if ([string]::IsNullOrWhiteSpace($Name)) { return }
    if ($script:wasmStringLiteralValueHints.ContainsKey($Name)) {
        $script:wasmStringLiteralValueHints.Remove($Name)
        $script:wasmConflictedStringLiteralValueHints[$Name] = $true
    }
}

function Test-WasmAstStringLiteralIsConstant {
    param([string]$Text)

    if ([string]::IsNullOrEmpty($Text) -or $Text.IndexOf('{') -lt 0 -or $Text.IndexOf('}') -lt 0) {
        return $true
    }

    $cursor = 0
    while ($cursor -lt $Text.Length) {
        $open = $Text.IndexOf('{', $cursor)
        if ($open -lt 0) { break }
        $close = Find-WasmAstInterpolationClose -Text $Text -Open $open
        if ($close -lt 0) { return $true }
        $exprText = $Text.Substring($open + 1, $close - $open - 1).Trim()
        if (-not [string]::IsNullOrWhiteSpace($exprText) -and $exprText -match '[A-Za-z0-9_]') {
            return $false
        }
        $cursor = $close + 1
    }
    return $true
}

function Get-WasmAstKnownStringLiteralValue {
    param($Node, [hashtable]$Seen = @{})

    if ($null -eq $Node) { return "" }
    if ([string]$Node.node -eq "STR_LIT") {
        $text = [string]$Node.value
        if (Test-WasmAstStringLiteralIsConstant $text) { return $text }
        return ""
    }
    if ([string]$Node.node -eq "IDENT") {
        $name = [string]$Node.name
        if ($script:wasmConflictedStringLiteralValueHints.ContainsKey($name)) { return "" }
        if ($script:wasmStringLiteralValueHints.ContainsKey($name)) {
            return [string]$script:wasmStringLiteralValueHints[$name]
        }
    }
    if ([string]$Node.node -eq "CALL") {
        $name = [string]$Node.name
        $seenKey = "func:$name"
        if ([string]::IsNullOrWhiteSpace($name) -or $Seen.ContainsKey($seenKey)) { return "" }
        $Seen[$seenKey] = $true
        try {
            $resolvedReturn = Resolve-WasmAstFunctionCallReturnExpr $Node
            if ($null -ne $resolvedReturn) {
                return (Get-WasmAstKnownStringLiteralValue $resolvedReturn $Seen)
            }
        } finally {
            [void]$Seen.Remove($seenKey)
        }
    }
    if ([string]$Node.node -eq "METHOD_CALL") {
        $method = [string]$Node.method
        $className = Get-WasmAstObjectClassTypeWithLocals ($Node.obj) $script:wasmCurrentLocalObjectClassHints $script:wasmCurrentClassContext @{}
        $seenKey = "method:$className.$method"
        if ([string]::IsNullOrWhiteSpace($method) -or [string]::IsNullOrWhiteSpace($className) -or $Seen.ContainsKey($seenKey)) { return "" }
        $Seen[$seenKey] = $true
        try {
            $resolvedReturn = Resolve-WasmAstMethodCallReturnExpr $Node
            if ($null -ne $resolvedReturn) {
                return (Get-WasmAstKnownStringLiteralValue $resolvedReturn $Seen)
            }
        } finally {
            [void]$Seen.Remove($seenKey)
        }
    }
    if ([string]$Node.node -eq "TERNARY") {
        $condState = Get-WasmAstKnownBoolLiteralState ($Node.cond)
        if ($condState -eq "true") {
            return (Get-WasmAstKnownStringLiteralValue ($Node.then) $Seen)
        }
        if ($condState -eq "false") {
            return (Get-WasmAstKnownStringLiteralValue ($Node.else) $Seen)
        }
        $thenValue = Get-WasmAstKnownStringLiteralValue ($Node.then) $Seen
        $elseValue = Get-WasmAstKnownStringLiteralValue ($Node.else) $Seen
        if (-not [string]::IsNullOrWhiteSpace($thenValue) -and $thenValue -eq $elseValue) {
            return $thenValue
        }
    }
    return ""
}

function Get-WasmAstKnownStringIndexResult {
    param($Node)

    if ($null -eq $Node -or [string]$Node.node -ne "INDEX" -or $null -eq $Node.obj -or $null -eq $Node.key) {
        return $null
    }

    $textKnown = $false
    $text = ""
    if ([string]$Node.obj.node -eq "STR_LIT" -and
        (Test-WasmAstStringLiteralIsConstant ([string]$Node.obj.value))) {
        $textKnown = $true
        $text = [string]$Node.obj.value
    } elseif ([string]$Node.obj.node -eq "IDENT") {
        $name = [string]$Node.obj.name
        if (-not $script:wasmConflictedStringLiteralValueHints.ContainsKey($name) -and
            $script:wasmStringLiteralValueHints.ContainsKey($name)) {
            $textKnown = $true
            $text = [string]$script:wasmStringLiteralValueHints[$name]
        }
    }
    if (-not $textKnown) { return $null }

    $indexKnown = $false
    $indexValue = 0
    $literalIndex = Get-WasmAstKnownNumericLiteralValue ($Node.key)
    if ($null -ne $literalIndex) {
        $indexKnown = $true
        $indexValue = [int][Math]::Truncate([double]$literalIndex)
    } elseif ([string]$Node.key.node -eq "IDENT") {
        $keyName = [string]$Node.key.name
        if (-not $script:wasmConflictedNumericLiteralValueHints.ContainsKey($keyName) -and
            $script:wasmNumericLiteralValueHints.ContainsKey($keyName)) {
            $indexKnown = $true
            $indexValue = [int][Math]::Truncate([double]$script:wasmNumericLiteralValueHints[$keyName])
        }
    }
    if (-not $indexKnown) { return $null }

    $length = $text.Length
    if ($indexValue -lt 0) { $indexValue += $length }
    if ($indexValue -lt 0 -or $indexValue -ge $length) {
        return [pscustomobject]@{ Known = $true; Type = "nil"; Value = "" }
    }

    return [pscustomobject]@{ Known = $true; Type = "string"; Value = [string]$text[$indexValue] }
}

function Test-WasmAstStringIndexExpr {
    param($Node)

    if ($null -eq $Node -or [string]$Node.node -ne "INDEX" -or $null -eq $Node.obj -or $null -eq $Node.key) {
        return $false
    }
    if ([string]$Node.key.node -eq "STR_LIT") { return $false }

    $keyType = Get-WasmAstKnownValueType ($Node.key)
    if ([string]::IsNullOrWhiteSpace($keyType)) { $keyType = Get-WasmAstStaticValueType ($Node.key) }
    if ($keyType -eq "string") { return $false }

    $objType = Get-WasmAstKnownValueType ($Node.obj)
    if ([string]::IsNullOrWhiteSpace($objType)) { $objType = Get-WasmAstStaticValueType ($Node.obj) }
    return ($objType -eq "string")
}

function Set-WasmAstNumericLiteralValueHint {
    param([string]$Name, [double]$Value)

    if ([string]::IsNullOrWhiteSpace($Name) -or [double]::IsNaN($Value) -or [double]::IsInfinity($Value)) { return }
    if ($script:wasmConflictedNumericLiteralValueHints.ContainsKey($Name)) { return }
    if ($script:wasmNumericLiteralValueHints.ContainsKey($Name) -and
        [double]$script:wasmNumericLiteralValueHints[$Name] -ne $Value) {
        $script:wasmNumericLiteralValueHints.Remove($Name)
        $script:wasmConflictedNumericLiteralValueHints[$Name] = $true
        return
    }
    $script:wasmNumericLiteralValueHints[$Name] = $Value
}

function Clear-WasmAstNumericLiteralValueHint {
    param([string]$Name)

    if ([string]::IsNullOrWhiteSpace($Name)) { return }
    if ($script:wasmNumericLiteralValueHints.ContainsKey($Name)) {
        $script:wasmNumericLiteralValueHints.Remove($Name)
        $script:wasmConflictedNumericLiteralValueHints[$Name] = $true
    }
}

function Get-WasmAstKnownNumericLiteralValue {
    param($Node, [hashtable]$Seen = @{})

    if ($null -eq $Node) { return $null }
    if ([string]$Node.node -eq "NUM_LIT") {
        return [double]$Node.value
    }
    if ([string]$Node.node -eq "IDENT") {
        $name = [string]$Node.name
        if ($script:wasmConflictedNumericLiteralValueHints.ContainsKey($name)) { return $null }
        if ($script:wasmNumericLiteralValueHints.ContainsKey($name)) {
            return [double]$script:wasmNumericLiteralValueHints[$name]
        }
    }
    if ([string]$Node.node -eq "CALL") {
        $name = [string]$Node.name
        $seenKey = "func:$name"
        if ([string]::IsNullOrWhiteSpace($name) -or $Seen.ContainsKey($seenKey)) { return $null }
        $Seen[$seenKey] = $true
        try {
            $resolvedReturn = Resolve-WasmAstFunctionCallReturnExpr $Node
            if ($null -ne $resolvedReturn) {
                return (Get-WasmAstKnownNumericLiteralValue $resolvedReturn $Seen)
            }
        } finally {
            [void]$Seen.Remove($seenKey)
        }
    }
    if ([string]$Node.node -eq "METHOD_CALL") {
        $method = [string]$Node.method
        $className = Get-WasmAstObjectClassTypeWithLocals ($Node.obj) $script:wasmCurrentLocalObjectClassHints $script:wasmCurrentClassContext @{}
        $seenKey = "method:$className.$method"
        if ([string]::IsNullOrWhiteSpace($method) -or [string]::IsNullOrWhiteSpace($className) -or $Seen.ContainsKey($seenKey)) { return $null }
        $Seen[$seenKey] = $true
        try {
            $resolvedReturn = Resolve-WasmAstMethodCallReturnExpr $Node
            if ($null -ne $resolvedReturn) {
                return (Get-WasmAstKnownNumericLiteralValue $resolvedReturn $Seen)
            }
        } finally {
            [void]$Seen.Remove($seenKey)
        }
    }
    if ([string]$Node.node -eq "TERNARY") {
        $condState = Get-WasmAstKnownBoolLiteralState ($Node.cond)
        if ($condState -eq "true") {
            return (Get-WasmAstKnownNumericLiteralValue ($Node.then) $Seen)
        }
        if ($condState -eq "false") {
            return (Get-WasmAstKnownNumericLiteralValue ($Node.else) $Seen)
        }
        $thenValue = Get-WasmAstKnownNumericLiteralValue ($Node.then) $Seen
        $elseValue = Get-WasmAstKnownNumericLiteralValue ($Node.else) $Seen
        if ($null -ne $thenValue -and $null -ne $elseValue -and [double]$thenValue -eq [double]$elseValue) {
            return [double]$thenValue
        }
    }
    return $null
}

function Add-WasmAstStringAccessHint {
    param([string]$BaseName, [string]$KeyName)

    if ([string]::IsNullOrWhiteSpace($BaseName) -or [string]::IsNullOrWhiteSpace($KeyName)) { return }
    $script:wasmStringAccessHints["$BaseName.$KeyName"] = $true
}

function Set-WasmAstValueTypeHint {
    param([string]$Name, [string]$TypeName)

    if ([string]::IsNullOrWhiteSpace($Name) -or [string]::IsNullOrWhiteSpace($TypeName)) { return }
    if ($script:wasmConflictedValueTypeHints.ContainsKey($Name)) { return }
    if ($script:wasmValueTypeHints.ContainsKey($Name) -and [string]$script:wasmValueTypeHints[$Name] -ne $TypeName) {
        $script:wasmValueTypeHints.Remove($Name)
        if ($script:wasmStringValueHints.ContainsKey($Name)) { $script:wasmStringValueHints.Remove($Name) }
        $script:wasmConflictedValueTypeHints[$Name] = $true
        return
    }
    $script:wasmValueTypeHints[$Name] = $TypeName
    if ($TypeName -eq "string") { Add-WasmAstStringValueHint $Name }
}

function Set-WasmAstValueTypeHintAfterWrite {
    param([string]$Name, [string]$TypeName)

    if ([string]::IsNullOrWhiteSpace($Name) -or [string]::IsNullOrWhiteSpace($TypeName)) { return }
    if ($script:wasmConflictedValueTypeHints.ContainsKey($Name)) {
        $script:wasmConflictedValueTypeHints.Remove($Name)
    }
    $script:wasmValueTypeHints[$Name] = $TypeName
    if ($TypeName -eq "string") {
        Add-WasmAstStringValueHint $Name
    } elseif ($script:wasmStringValueHints.ContainsKey($Name)) {
        $script:wasmStringValueHints.Remove($Name)
    }
}

function Copy-WasmAstTypeHints {
    param([hashtable]$Hints)

    $copy = @{}
    if ($null -eq $Hints) { return $copy }
    foreach ($entry in $Hints.GetEnumerator()) {
        $copy[[string]$entry.Key] = [string]$entry.Value
    }
    return $copy
}

function Copy-WasmAstFunctionLiftCandidateHints {
    param([hashtable]$Hints)

    $copy = @{}
    if ($null -eq $Hints) { return $copy }
    foreach ($entry in $Hints.GetEnumerator()) {
        $copy[[string]$entry.Key] = [string[]]@($entry.Value)
    }
    return $copy
}

function Get-WasmAstAccessHintFlowState {
    return [pscustomobject]@{
        Types = Copy-WasmAstTypeHints $script:wasmAccessTypeHints
        TypeConflicts = Copy-WasmAstTypeHints $script:wasmConflictedAccessTypeHints
        Strings = Copy-WasmAstTypeHints $script:wasmStringAccessHints
        FunctionDisplays = Copy-WasmAstTypeHints $script:wasmAccessFunctionDisplayHints
        FunctionDisplayConflicts = Copy-WasmAstTypeHints $script:wasmConflictedAccessFunctionDisplayHints
        FunctionLifts = Copy-WasmAstTypeHints $script:wasmAccessFunctionLiftHints
        FunctionLiftConflicts = Copy-WasmAstTypeHints $script:wasmConflictedAccessFunctionLiftHints
        ObjectClasses = Copy-WasmAstTypeHints $script:wasmAccessObjectClassHints
        ObjectClassConflicts = Copy-WasmAstTypeHints $script:wasmConflictedAccessObjectClassHints
    }
}

function Set-WasmAstAccessHintFlowState {
    param($State)

    if ($null -eq $State) { return }
    $script:wasmAccessTypeHints = Copy-WasmAstTypeHints $State.Types
    $script:wasmConflictedAccessTypeHints = Copy-WasmAstTypeHints $State.TypeConflicts
    $script:wasmStringAccessHints = Copy-WasmAstTypeHints $State.Strings
    $script:wasmAccessFunctionDisplayHints = Copy-WasmAstTypeHints $State.FunctionDisplays
    $script:wasmConflictedAccessFunctionDisplayHints = Copy-WasmAstTypeHints $State.FunctionDisplayConflicts
    $script:wasmAccessFunctionLiftHints = Copy-WasmAstTypeHints $State.FunctionLifts
    $script:wasmConflictedAccessFunctionLiftHints = Copy-WasmAstTypeHints $State.FunctionLiftConflicts
    $script:wasmAccessObjectClassHints = Copy-WasmAstTypeHints $State.ObjectClasses
    $script:wasmConflictedAccessObjectClassHints = Copy-WasmAstTypeHints $State.ObjectClassConflicts
}

function Merge-WasmAstBranchedHintMaps {
    param(
        [hashtable]$LeftHints,
        [hashtable]$LeftConflicts,
        [hashtable]$RightHints,
        [hashtable]$RightConflicts
    )

    $hints = @{}
    $conflicts = @{}
    $keys = @{}
    foreach ($map in @($LeftHints, $LeftConflicts, $RightHints, $RightConflicts)) {
        if ($null -eq $map) { continue }
        foreach ($entry in $map.GetEnumerator()) { $keys[[string]$entry.Key] = $true }
    }
    foreach ($key in $keys.Keys) {
        if (($null -ne $LeftConflicts -and $LeftConflicts.ContainsKey($key)) -or
            ($null -ne $RightConflicts -and $RightConflicts.ContainsKey($key))) {
            $conflicts[$key] = $true
            continue
        }
        if ($null -ne $LeftHints -and $null -ne $RightHints -and
            $LeftHints.ContainsKey($key) -and $RightHints.ContainsKey($key) -and
            [string]$LeftHints[$key] -eq [string]$RightHints[$key]) {
            $hints[$key] = [string]$LeftHints[$key]
        } else {
            $conflicts[$key] = $true
        }
    }
    return [pscustomobject]@{ Hints = $hints; Conflicts = $conflicts }
}

function Merge-WasmAstAccessHintFlowStates {
    param($Left, $Right)

    if ($null -eq $Left) { return $Right }
    if ($null -eq $Right) { return $Left }
    $types = Merge-WasmAstBranchedHintMaps $Left.Types $Left.TypeConflicts $Right.Types $Right.TypeConflicts
    $displays = Merge-WasmAstBranchedHintMaps $Left.FunctionDisplays $Left.FunctionDisplayConflicts $Right.FunctionDisplays $Right.FunctionDisplayConflicts
    $lifts = Merge-WasmAstBranchedHintMaps $Left.FunctionLifts $Left.FunctionLiftConflicts $Right.FunctionLifts $Right.FunctionLiftConflicts
    $objects = Merge-WasmAstBranchedHintMaps $Left.ObjectClasses $Left.ObjectClassConflicts $Right.ObjectClasses $Right.ObjectClassConflicts
    $strings = @{}
    $stringKeys = @{}
    foreach ($entry in $Left.Strings.GetEnumerator()) { $stringKeys[[string]$entry.Key] = $true }
    foreach ($entry in $Right.Strings.GetEnumerator()) { $stringKeys[[string]$entry.Key] = $true }
    foreach ($key in $stringKeys.Keys) {
        if (-not $types.Conflicts.ContainsKey($key) -and
            $Left.Strings.ContainsKey($key) -and $Right.Strings.ContainsKey($key)) {
            $strings[$key] = $true
        }
    }
    foreach ($entry in $types.Hints.GetEnumerator()) {
        if ([string]$entry.Value -eq "string") { $strings[[string]$entry.Key] = $true }
    }
    return [pscustomobject]@{
        Types = $types.Hints
        TypeConflicts = $types.Conflicts
        Strings = $strings
        FunctionDisplays = $displays.Hints
        FunctionDisplayConflicts = $displays.Conflicts
        FunctionLifts = $lifts.Hints
        FunctionLiftConflicts = $lifts.Conflicts
        ObjectClasses = $objects.Hints
        ObjectClassConflicts = $objects.Conflicts
    }
}

function Copy-WasmAstStringArrayHints {
    param([hashtable]$Hints)

    $copy = @{}
    if ($null -eq $Hints) { return $copy }
    foreach ($entry in $Hints.GetEnumerator()) {
        $copy[[string]$entry.Key] = [string[]]@($entry.Value)
    }
    return $copy
}

function Get-WasmAstCurrentValueTypeScopeHints {
    $hints = Copy-WasmAstTypeHints $script:wasmCurrentFunctionParamTypeHints
    foreach ($entry in $script:wasmCurrentLocalValueTypeHints.GetEnumerator()) {
        $hints[[string]$entry.Key] = [string]$entry.Value
    }
    return $hints
}

function Set-WasmAstCurrentLocalValueTypeHint {
    param([string]$Name, [string]$TypeName)

    if ([string]::IsNullOrWhiteSpace($Name)) { return }
    if ($TypeName -in @("string", "bool", "nil", "num", "array", "dict", "function", "value")) {
        $script:wasmCurrentLocalValueTypeHints[$Name] = $TypeName
    } elseif ($script:wasmCurrentLocalValueTypeHints.ContainsKey($Name)) {
        $script:wasmCurrentLocalValueTypeHints.Remove($Name)
    }
}

function Merge-WasmAstLocalValueTypeHints {
    param([hashtable]$Left, [hashtable]$Right)

    $merged = @{}
    $keys = @{}
    foreach ($entry in $Left.GetEnumerator()) { $keys[[string]$entry.Key] = $true }
    foreach ($entry in $Right.GetEnumerator()) { $keys[[string]$entry.Key] = $true }
    foreach ($key in $keys.Keys) {
        if ($Left.ContainsKey($key) -and $Right.ContainsKey($key) -and [string]$Left[$key] -eq [string]$Right[$key]) {
            $merged[$key] = [string]$Left[$key]
        }
    }
    return $merged
}

function Set-WasmAstCurrentLocalObjectClassHint {
    param([string]$Name, [string]$ClassName)

    if ([string]::IsNullOrWhiteSpace($Name)) { return }
    if (-not [string]::IsNullOrWhiteSpace($ClassName) -and $script:wasmClassDefs.ContainsKey($ClassName)) {
        $script:wasmCurrentLocalObjectClassHints[$Name] = $ClassName
    } elseif ($script:wasmCurrentLocalObjectClassHints.ContainsKey($Name)) {
        $script:wasmCurrentLocalObjectClassHints.Remove($Name)
    }
}

function Get-WasmAstObjectClassNamesFromHint {
    param([string]$Hint)

    if ([string]::IsNullOrWhiteSpace($Hint)) { return @() }
    if ($Hint.StartsWith("@union:")) {
        return @($Hint.Substring(7).Split('|') | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | Sort-Object -Unique)
    }
    return @($Hint)
}

function New-WasmAstObjectClassSetHint {
    param([string[]]$ClassNames)

    $names = @($ClassNames | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | Sort-Object -Unique)
    if ($names.Count -eq 0) { return "" }
    if ($names.Count -eq 1) { return [string]$names[0] }
    return "@union:$([string]::Join('|', [string[]]$names))"
}

function Merge-WasmAstLocalObjectClassHints {
    param([hashtable]$Left, [hashtable]$Right)

    $merged = @{}
    $keys = @{}
    foreach ($entry in $Left.GetEnumerator()) { $keys[[string]$entry.Key] = $true }
    foreach ($entry in $Right.GetEnumerator()) { $keys[[string]$entry.Key] = $true }
    foreach ($key in $keys.Keys) {
        if ($Left.ContainsKey($key) -and $Right.ContainsKey($key) -and [string]$Left[$key] -eq [string]$Right[$key]) {
            $merged[$key] = [string]$Left[$key]
        }
    }
    return $merged
}

function Set-WasmAstCurrentLocalFunctionDisplayHint {
    param([string]$Name, [string]$DisplayName)

    if ([string]::IsNullOrWhiteSpace($Name)) { return }
    if (-not [string]::IsNullOrWhiteSpace($DisplayName)) {
        $script:wasmCurrentLocalFunctionDisplayHints[$Name] = $DisplayName
    } elseif ($script:wasmCurrentLocalFunctionDisplayHints.ContainsKey($Name)) {
        $script:wasmCurrentLocalFunctionDisplayHints.Remove($Name)
    }
}

function Set-WasmAstCurrentLocalFunctionLiftHint {
    param([string]$Name, [string]$LiftName)

    if ([string]::IsNullOrWhiteSpace($Name)) { return }
    if (-not [string]::IsNullOrWhiteSpace($LiftName)) {
        $script:wasmCurrentLocalFunctionLiftHints[$Name] = $LiftName
    } elseif ($script:wasmCurrentLocalFunctionLiftHints.ContainsKey($Name)) {
        $script:wasmCurrentLocalFunctionLiftHints.Remove($Name)
    }
}

function Merge-WasmAstLocalFunctionDisplayHints {
    param([hashtable]$Left, [hashtable]$Right)

    return (Merge-WasmAstLocalValueTypeHints $Left $Right)
}

function Merge-WasmAstLocalFunctionLiftHints {
    param([hashtable]$Left, [hashtable]$Right)

    return (Merge-WasmAstLocalValueTypeHints $Left $Right)
}

function Get-WasmAstKnownObjectClassName {
    param([string]$Name)

    if ([string]::IsNullOrWhiteSpace($Name)) { return "" }
    if ($Name -eq "self" -and -not [string]::IsNullOrWhiteSpace($script:wasmCurrentClassContext)) {
        return $script:wasmCurrentClassContext
    }
    if ($script:wasmCurrentLocalObjectClassHints.ContainsKey($Name)) {
        return [string]$script:wasmCurrentLocalObjectClassHints[$Name]
    }
    if ($script:wasmObjectClassHints.ContainsKey($Name)) {
        return [string]$script:wasmObjectClassHints[$Name]
    }
    return ""
}

function Get-WasmAstObjectClassTypeHint {
    param($Node)

    return (Get-WasmAstObjectClassTypeWithLocals $Node @{} "" @{})
}

function Get-WasmAstObjectClassTypeWithLocals {
    param(
        $Node,
        [hashtable]$LocalObjectTypes = @{},
        [string]$SelfClassName = "",
        [hashtable]$Seen = @{}
    )

    if ($null -eq $Node) { return "" }
    switch ([string]$Node.node) {
        "NEW_EXPR" {
            $className = [string]$Node.class_name
            if ($script:wasmClassDefs.ContainsKey($className)) { return $className }
            return ""
        }
        "IDENT" {
            $name = [string]$Node.name
            if ($name -eq "self" -and -not [string]::IsNullOrWhiteSpace($SelfClassName)) { return $SelfClassName }
            if ($LocalObjectTypes.ContainsKey($name)) { return [string]$LocalObjectTypes[$name] }
            return (Get-WasmAstKnownObjectClassName $name)
        }
        "CALL" {
            return (Get-WasmAstFunctionCallObjectClassHint $Node $Seen)
        }
        "METHOD_CALL" {
            return (Get-WasmAstMethodCallObjectClassHint $Node $LocalObjectTypes $SelfClassName $Seen)
        }
        "DOT_ACCESS" {
            if ($null -ne $Node.obj -and [string]$Node.obj.node -eq "IDENT") {
                if ([string]$Node.obj.name -eq "self" -and -not [string]::IsNullOrWhiteSpace($SelfClassName)) {
                    $selfFieldClass = Get-WasmAstClassFieldObjectClassHint $SelfClassName ([string]$Node.prop)
                    if (-not [string]::IsNullOrWhiteSpace($selfFieldClass)) { return $selfFieldClass }
                }
                return (Get-WasmAstAccessObjectClassHint "$([string]$Node.obj.name).$([string]$Node.prop)")
            }
            return ""
        }
        "INDEX" {
            if ($null -ne $Node.obj -and [string]$Node.obj.node -eq "IDENT") {
                $baseName = [string]$Node.obj.name
                if ($null -ne $Node.key -and [string]$Node.key.node -eq "STR_LIT") {
                    if ($baseName -eq "self" -and -not [string]::IsNullOrWhiteSpace($SelfClassName)) {
                        $selfFieldClass = Get-WasmAstClassFieldObjectClassHint $SelfClassName ([string]$Node.key.value)
                        if (-not [string]::IsNullOrWhiteSpace($selfFieldClass)) { return $selfFieldClass }
                    }
                    return (Get-WasmAstAccessObjectClassHint "$baseName.$([string]$Node.key.value)")
                }
                if ($null -ne $Node.key -and [string]$Node.key.node -eq "NUM_LIT") {
                    $indexValue = [int][Math]::Truncate([double]$Node.key.value)
                    $localIndexedHint = Get-WasmAstCurrentLocalIndexedAccessHint $baseName $indexValue
                    if ($null -ne $localIndexedHint -and -not [string]::IsNullOrWhiteSpace([string]$localIndexedHint.ObjectClassName)) {
                        return [string]$localIndexedHint.ObjectClassName
                    }
                    return (Get-WasmAstAccessObjectClassHint ("{0}[{1}]" -f $baseName, $indexValue))
                }
                if ($null -ne $Node.key) {
                    $literalIndex = Get-WasmAstKnownNumericLiteralValue ($Node.key)
                    if ($null -ne $literalIndex) {
                        $indexValue = [int][Math]::Truncate([double]$literalIndex)
                        $localIndexedHint = Get-WasmAstCurrentLocalIndexedAccessHint $baseName $indexValue
                        if ($null -ne $localIndexedHint -and -not [string]::IsNullOrWhiteSpace([string]$localIndexedHint.ObjectClassName)) {
                            return [string]$localIndexedHint.ObjectClassName
                        }
                        return (Get-WasmAstAccessObjectClassHint ("{0}[{1}]" -f $baseName, $indexValue))
                    }
                }
                if ($null -ne $Node.key -and [string]$Node.key.node -eq "IDENT") {
                    $dynamicIndexClass = Get-WasmAstAccessObjectClassHint ('{0}[${1}]' -f $baseName, [string]$Node.key.name)
                    if (-not [string]::IsNullOrWhiteSpace($dynamicIndexClass)) { return $dynamicIndexClass }
                }
                if ($null -ne $Node.key) {
                    $literalKey = Get-WasmAstKnownStringLiteralValue ($Node.key)
                    if (-not [string]::IsNullOrWhiteSpace($literalKey)) {
                        return (Get-WasmAstAccessObjectClassHint "$baseName.$literalKey")
                    }
                }
            }
            if ($null -ne $Node.obj -and $null -ne $Node.key) {
                $keyType = Get-WasmAstKnownValueType ($Node.key)
                if ([string]::IsNullOrWhiteSpace($keyType)) { $keyType = Get-WasmAstStaticValueType ($Node.key) }
                $objType = Get-WasmAstKnownValueType ($Node.obj)
                if ([string]::IsNullOrWhiteSpace($objType)) { $objType = Get-WasmAstStaticValueType ($Node.obj) }
                if ($keyType -eq "string" -and $objType -eq "dict") {
                    $dictClass = Get-WasmAstDictValueObjectClassHint ($Node.obj)
                    if (-not [string]::IsNullOrWhiteSpace($dictClass)) { return $dictClass }
                }
                if ([string]$Node.key.node -ne "STR_LIT" -and $objType -eq "array") {
                    $arrayClass = Get-WasmAstArrayElementObjectClassHint ($Node.obj)
                    if (-not [string]::IsNullOrWhiteSpace($arrayClass)) { return $arrayClass }
                }
            }
            return ""
        }
        "TERNARY" {
            $thenClass = Get-WasmAstObjectClassTypeWithLocals ($Node.then) $LocalObjectTypes $SelfClassName $Seen
            $elseClass = Get-WasmAstObjectClassTypeWithLocals ($Node.else) $LocalObjectTypes $SelfClassName $Seen
            if (-not [string]::IsNullOrWhiteSpace($thenClass) -and $thenClass -eq $elseClass) {
                return $thenClass
            }
            return ""
        }
        default { return "" }
    }
}

function Get-WasmAstObjectClassSetHintWithLocals {
    param(
        $Node,
        [hashtable]$LocalObjectTypes = @{},
        [string]$SelfClassName = ""
    )

    if ($null -eq $Node) { return "" }
    if ([string]$Node.node -eq "TERNARY") {
        $thenHint = Get-WasmAstObjectClassSetHintWithLocals ($Node.then) $LocalObjectTypes $SelfClassName
        $elseHint = Get-WasmAstObjectClassSetHintWithLocals ($Node.else) $LocalObjectTypes $SelfClassName
        $thenNames = @(Get-WasmAstObjectClassNamesFromHint $thenHint)
        $elseNames = @(Get-WasmAstObjectClassNamesFromHint $elseHint)
        if ($thenNames.Count -eq 0 -or $elseNames.Count -eq 0) { return "" }
        return (New-WasmAstObjectClassSetHint ([string[]]@($thenNames + $elseNames)))
    }
    if ([string]$Node.node -eq "IDENT") {
        $name = [string]$Node.name
        if ($name -eq "self" -and -not [string]::IsNullOrWhiteSpace($SelfClassName)) { return $SelfClassName }
        if ($LocalObjectTypes.ContainsKey($name)) { return [string]$LocalObjectTypes[$name] }
        if ($script:wasmCurrentLocalObjectClassHints.ContainsKey($name)) {
            return [string]$script:wasmCurrentLocalObjectClassHints[$name]
        }
    }
    $exact = Get-WasmAstObjectClassTypeWithLocals $Node $LocalObjectTypes $SelfClassName @{}
    if (-not [string]::IsNullOrWhiteSpace($exact) -and $script:wasmClassDefs.ContainsKey($exact)) { return $exact }
    return ""
}

function Get-WasmAstReturnObjectClassFromBody {
    param(
        $Body,
        [string]$SelfClassName = "",
        [hashtable]$ParamObjectTypes = @{},
        [hashtable]$Seen = @{}
    )

    if ($null -eq $Body) { return "" }
    $localObjects = Copy-WasmAstTypeHints $ParamObjectTypes
    foreach ($stmt in @(As-WasmAstArray ($Body.body))) {
        if ($null -eq $stmt) { continue }
        switch ([string]$stmt.node) {
            "ASSIGN" {
                $className = Get-WasmAstObjectClassTypeWithLocals ($stmt.value) $localObjects $SelfClassName $Seen
                if (-not [string]::IsNullOrWhiteSpace($className)) {
                    $localObjects[[string]$stmt.name] = $className
                } elseif ($localObjects.ContainsKey([string]$stmt.name)) {
                    $localObjects.Remove([string]$stmt.name)
                }
            }
            "RETURN" {
                return (Get-WasmAstObjectClassTypeWithLocals ($stmt.value) $localObjects $SelfClassName $Seen)
            }
            "SuraBlock" {
                $className = Get-WasmAstReturnObjectClassFromBody $stmt $SelfClassName $localObjects $Seen
                if (-not [string]::IsNullOrWhiteSpace($className)) { return $className }
            }
            "IF" {
                $thenClass = Get-WasmAstReturnObjectClassFromBody ($stmt.then_block) $SelfClassName $localObjects $Seen
                $elseClass = Get-WasmAstReturnObjectClassFromBody ($stmt.else_block) $SelfClassName $localObjects $Seen
                if (-not [string]::IsNullOrWhiteSpace($thenClass) -and $thenClass -eq $elseClass) {
                    return $thenClass
                }
            }
            "WHILE" {
                $className = Get-WasmAstReturnObjectClassFromBody ($stmt.body) $SelfClassName $localObjects $Seen
                if (-not [string]::IsNullOrWhiteSpace($className)) { return $className }
            }
            "REPEAT" {
                $className = Get-WasmAstReturnObjectClassFromBody ($stmt.body) $SelfClassName $localObjects $Seen
                if (-not [string]::IsNullOrWhiteSpace($className)) { return $className }
            }
            "FOR" {
                $className = Get-WasmAstReturnObjectClassFromBody ($stmt.body) $SelfClassName $localObjects $Seen
                if (-not [string]::IsNullOrWhiteSpace($className)) { return $className }
            }
            "FOREACH" {
                $loopObjects = Copy-WasmAstTypeHints $localObjects
                $loopVar = [string]$stmt.var
                $loopVar2 = [string]$stmt.var2
                $collectionType = Get-WasmAstStaticValueTypeWithClassSelf ($stmt.collection) $SelfClassName @{} $localObjects
                if ($collectionType -eq "dict") {
                    if (-not [string]::IsNullOrWhiteSpace($loopVar2)) {
                        $valueClass = Get-WasmAstDictValueObjectClassHint ($stmt.collection)
                        if (-not [string]::IsNullOrWhiteSpace($valueClass)) {
                            $loopObjects[$loopVar2] = $valueClass
                        }
                    }
                } else {
                    $elementClass = Get-WasmAstArrayElementObjectClassHint ($stmt.collection)
                    if (-not [string]::IsNullOrWhiteSpace($elementClass)) {
                        if (-not [string]::IsNullOrWhiteSpace($loopVar2)) {
                            $loopObjects[$loopVar2] = $elementClass
                        } else {
                            $loopObjects[$loopVar] = $elementClass
                        }
                    }
                }
                $className = Get-WasmAstReturnObjectClassFromBody ($stmt.body) $SelfClassName $loopObjects $Seen
                if (-not [string]::IsNullOrWhiteSpace($className)) { return $className }
            }
            "MATCH" {
                $armClasses = New-Object System.Collections.Generic.List[string]
                $armCount = 0
                $hasWildcardArm = $false
                foreach ($arm in @(As-WasmAstArray ($stmt.arms))) {
                    $armCount++
                    if ([bool]$arm.is_wildcard) { $hasWildcardArm = $true }
                    $className = Get-WasmAstReturnObjectClassFromBody ($arm.body) $SelfClassName $localObjects $Seen
                    if (-not [string]::IsNullOrWhiteSpace($className)) {
                        $armClasses.Add($className) | Out-Null
                    }
                }
                if ($hasWildcardArm -and $armCount -gt 0 -and $armClasses.Count -eq $armCount) {
                    $commonClass = [string]$armClasses[0]
                    $sameClass = $true
                    foreach ($className in $armClasses) {
                        if ([string]$className -ne $commonClass) {
                            $sameClass = $false
                            break
                        }
                    }
                    if ($sameClass) { return $commonClass }
                }
            }
            "TRY" {
                $className = Get-WasmAstReturnObjectClassFromBody ($stmt.try_block) $SelfClassName $localObjects $Seen
                if (-not [string]::IsNullOrWhiteSpace($className)) { return $className }
            }
            default { }
        }
    }
    return ""
}

function Get-WasmAstFunctionCallObjectClassHint {
    param($Node, [hashtable]$Seen = @{})

    if ($null -eq $Node -or [string]$Node.node -ne "CALL") { return "" }
    $name = [string]$Node.name
    if (-not $script:wasmAstFunctionDefs.ContainsKey($name)) { return "" }
    $seenKey = "func:$name"
    if ($Seen.ContainsKey($seenKey)) { return "" }
    $Seen[$seenKey] = $true
    try {
        $fn = $script:wasmAstFunctionDefs[$name]
        if ($null -eq $fn.Node -or $null -eq $fn.Node.body) { return "" }
        $paramObjectTypes = @{}
        $params = @($fn.Params)
        $args = @(As-WasmAstArray ($Node.args))
        for ($i = 0; $i -lt $params.Count -and $i -lt $args.Count; $i++) {
            $argClass = Get-WasmAstObjectClassTypeWithLocals ($args[$i]) @{} "" $Seen
            if (-not [string]::IsNullOrWhiteSpace($argClass)) {
                $paramObjectTypes[[string]$params[$i]] = $argClass
            }
        }
        return (Get-WasmAstReturnObjectClassFromBody ($fn.Node.body) "" $paramObjectTypes $Seen)
    } finally {
        $Seen.Remove($seenKey)
    }
}

function Get-WasmAstMethodCallObjectClassHint {
    param(
        $Node,
        [hashtable]$LocalObjectTypes = @{},
        [string]$SelfClassName = "",
        [hashtable]$Seen = @{}
    )

    if ($null -eq $Node -or [string]$Node.node -ne "METHOD_CALL") { return "" }
    $className = Get-WasmAstObjectClassTypeWithLocals ($Node.obj) $LocalObjectTypes $SelfClassName $Seen
    if ([string]::IsNullOrWhiteSpace($className)) { return "" }
    $methodName = [string]$Node.method
    $seenKey = "method:$className.$methodName"
    if ($Seen.ContainsKey($seenKey)) { return "" }
    $Seen[$seenKey] = $true
    $methodInfo = Get-WasmAstClassMethod -ClassName $className -MethodName $methodName
    if ($null -eq $methodInfo) { return "" }
    $paramObjectTypes = @{}
    $params = @(Get-WasmAstParamNames ($methodInfo.Method.params))
    $args = @(As-WasmAstArray ($Node.args))
    for ($i = 0; $i -lt $params.Count -and $i -lt $args.Count; $i++) {
        $argClass = Get-WasmAstObjectClassTypeWithLocals ($args[$i]) $LocalObjectTypes $SelfClassName $Seen
        if (-not [string]::IsNullOrWhiteSpace($argClass)) {
            $paramObjectTypes[[string]$params[$i]] = $argClass
        }
    }
    return (Get-WasmAstReturnObjectClassFromBody ($methodInfo.Method.body) ([string]$methodInfo.ClassName) $paramObjectTypes $Seen)
}

function Set-WasmAstObservedFunctionParamTypeHint {
    param([string]$FunctionName, [string]$ParamName, [string]$TypeName)

    if ([string]::IsNullOrWhiteSpace($FunctionName) -or [string]::IsNullOrWhiteSpace($ParamName) -or
        [string]::IsNullOrWhiteSpace($TypeName)) { return }
    if ($TypeName -notin @("string", "bool", "nil", "num", "array", "dict", "function")) { return }
    $key = "$FunctionName.$ParamName"
    if ($script:wasmConflictedFunctionParamTypeHints.ContainsKey($key)) { return }
    if ($script:wasmFunctionParamTypeHints.ContainsKey($key) -and
        [string]$script:wasmFunctionParamTypeHints[$key] -ne $TypeName) {
        $script:wasmFunctionParamTypeHints.Remove($key)
        $script:wasmConflictedFunctionParamTypeHints[$key] = $true
        return
    }
    $script:wasmFunctionParamTypeHints[$key] = $TypeName
}

function Get-WasmAstObservedFunctionParamTypeHints {
    param([string]$FunctionName)

    $types = @{}
    if ([string]::IsNullOrWhiteSpace($FunctionName)) { return $types }
    $prefix = "$FunctionName."
    foreach ($entry in $script:wasmFunctionParamTypeHints.GetEnumerator()) {
        $key = [string]$entry.Key
        if ($key -like "$prefix*" -and -not $script:wasmConflictedFunctionParamTypeHints.ContainsKey($key)) {
            $types[$key.Substring($prefix.Length)] = [string]$entry.Value
        }
    }
    foreach ($keyValue in @($script:wasmConflictedFunctionParamTypeHints.Keys)) {
        $key = [string]$keyValue
        if ($key.StartsWith($prefix)) {
            # A parameter observed with more than one concrete type has a stable
            # tagged-Value ABI.  Dropping the hint made string payloads look like
            # raw i32 numbers in the generated module.
            $types[$key.Substring($prefix.Length)] = "value"
        }
    }
    return $types
}

function Convert-WasmAstObservedCallArgs {
    param(
        [string]$TargetName,
        [string[]]$Params,
        $InputArgs
    )

    $out = New-Object System.Collections.Generic.List[string]
    $args = @(As-WasmAstArray $InputArgs)
    $paramTypes = Get-WasmAstObservedFunctionParamTypeHints $TargetName
    for ($i = 0; $i -lt $args.Count; $i++) {
        $useValueAbi = $false
        if ($null -ne $Params -and $i -lt $Params.Count) {
            $paramName = [string]$Params[$i]
            $useValueAbi = ($paramTypes.ContainsKey($paramName) -and [string]$paramTypes[$paramName] -eq "value")
        }
        $code = if ($useValueAbi) {
            $dynamicDictCode = @(Convert-WasmAstRawDictExprToDynamicValue ($args[$i]))
            if ($dynamicDictCode.Count -gt 0) {
                [string[]]$dynamicDictCode
            } else {
                [string[]]@(Convert-WasmAstValueExpr ($args[$i]))
            }
        } else {
            [string[]]@(Convert-WasmAstExpr ($args[$i]))
        }
        foreach ($line in $code) { $out.Add([string]$line) | Out-Null }
    }
    return [string[]]$out.ToArray()
}

function Set-WasmAstObservedFunctionParamObjectClassHint {
    param([string]$FunctionName, [string]$ParamName, [string]$ClassName)

    if ([string]::IsNullOrWhiteSpace($FunctionName) -or [string]::IsNullOrWhiteSpace($ParamName) -or
        [string]::IsNullOrWhiteSpace($ClassName) -or -not $script:wasmClassDefs.ContainsKey($ClassName)) {
        return
    }
    $key = "$FunctionName.$ParamName"
    if ($script:wasmConflictedFunctionParamObjectClassHints.ContainsKey($key)) { return }
    if ($script:wasmFunctionParamObjectClassHints.ContainsKey($key) -and
        [string]$script:wasmFunctionParamObjectClassHints[$key] -ne $ClassName) {
        $script:wasmFunctionParamObjectClassHints.Remove($key)
        $script:wasmConflictedFunctionParamObjectClassHints[$key] = $true
        return
    }
    $script:wasmFunctionParamObjectClassHints[$key] = $ClassName
}

