    if ([string]::IsNullOrWhiteSpace($FunctionName) -or [string]::IsNullOrWhiteSpace($ParamName)) { return }
    $key = "$FunctionName.$ParamName"
    if ($script:wasmConflictedFunctionParamObjectClassHints.ContainsKey($key)) { return }
    if ($script:wasmFunctionParamObjectClassHints.ContainsKey($key)) {
        [void]$script:wasmFunctionParamObjectClassHints.Remove($key)
    }
    $script:wasmConflictedFunctionParamObjectClassHints[$key] = $true
}

