function Get-WasmAstObservedFunctionParamKey {
    param([string]$FunctionName, [string]$ParamName)

    if ([string]::IsNullOrWhiteSpace($FunctionName) -or [string]::IsNullOrWhiteSpace($ParamName)) { return "" }
    return ("{0}.{1}" -f $FunctionName, $ParamName)
}

function Set-WasmAstObservedFunctionParamArrayShapeConflict {
    param([string]$Key)

    if ([string]::IsNullOrWhiteSpace($Key)) { return }
    if ($script:wasmFunctionParamIndexedAccessHints.ContainsKey($Key)) { $script:wasmFunctionParamIndexedAccessHints.Remove($Key) }
    if ($script:wasmFunctionParamEmptyArrayHints.ContainsKey($Key)) { $script:wasmFunctionParamEmptyArrayHints.Remove($Key) }
    $script:wasmConflictedFunctionParamIndexedAccessHints[$Key] = $true
    $script:wasmConflictedFunctionParamEmptyArrayHints[$Key] = $true
}

function Set-WasmAstObservedFunctionParamDictShapeConflict {
    param([string]$Key)

    if ([string]::IsNullOrWhiteSpace($Key)) { return }
    if ($script:wasmFunctionParamOrderedDictEntryHints.ContainsKey($Key)) { $script:wasmFunctionParamOrderedDictEntryHints.Remove($Key) }
    if ($script:wasmFunctionParamEmptyDictHints.ContainsKey($Key)) { $script:wasmFunctionParamEmptyDictHints.Remove($Key) }
    $script:wasmConflictedFunctionParamOrderedDictEntryHints[$Key] = $true
    $script:wasmConflictedFunctionParamEmptyDictHints[$Key] = $true
}

function Set-WasmAstObservedFunctionParamIndexedAccessHints {
    param([string]$FunctionName, [string]$ParamName, [hashtable]$Map)

    $key = Get-WasmAstObservedFunctionParamKey $FunctionName $ParamName
    if ([string]::IsNullOrWhiteSpace($key) -or -not (Test-WasmAstFixedIndexedHintMapHasItems $Map)) { return }
    if ($script:wasmConflictedFunctionParamIndexedAccessHints.ContainsKey($key) -or
        $script:wasmConflictedFunctionParamEmptyArrayHints.ContainsKey($key)) { return }
    if ($script:wasmFunctionParamEmptyArrayHints.ContainsKey($key)) {
        Set-WasmAstObservedFunctionParamArrayShapeConflict $key
        return
    }
    if ($script:wasmFunctionParamIndexedAccessHints.ContainsKey($key)) {
        $existing = $script:wasmFunctionParamIndexedAccessHints[$key]
        $merged = Merge-WasmAstFixedIndexedHintMaps $existing $Map
        if ($merged.Count -eq $existing.Count -and $merged.Count -eq $Map.Count) {
            $script:wasmFunctionParamIndexedAccessHints[$key] = Copy-WasmAstFixedIndexedHintMap $merged
        } else {
            Set-WasmAstObservedFunctionParamArrayShapeConflict $key
        }
        return
    }
    $script:wasmFunctionParamIndexedAccessHints[$key] = Copy-WasmAstFixedIndexedHintMap $Map
}

function Set-WasmAstObservedFunctionParamOrderedDictEntryHints {
    param([string]$FunctionName, [string]$ParamName, $Entries)

    $key = Get-WasmAstObservedFunctionParamKey $FunctionName $ParamName
    $entryArray = @($Entries)
    if ([string]::IsNullOrWhiteSpace($key) -or $entryArray.Count -eq 0) { return }
    if ($script:wasmConflictedFunctionParamOrderedDictEntryHints.ContainsKey($key) -or
        $script:wasmConflictedFunctionParamEmptyDictHints.ContainsKey($key)) { return }
    if ($script:wasmFunctionParamEmptyDictHints.ContainsKey($key)) {
        Set-WasmAstObservedFunctionParamDictShapeConflict $key
        return
    }
    if ($script:wasmFunctionParamOrderedDictEntryHints.ContainsKey($key)) {
        $existing = @($script:wasmFunctionParamOrderedDictEntryHints[$key])
        $merged = @(Merge-WasmAstOrderedDictEntryTypes $existing $entryArray)
        if ($merged.Count -eq $existing.Count -and $merged.Count -eq $entryArray.Count) {
            $script:wasmFunctionParamOrderedDictEntryHints[$key] = @(Copy-WasmAstOrderedDictEntryTypes $merged)
        } else {
            Set-WasmAstObservedFunctionParamDictShapeConflict $key
        }
        return
    }
    $script:wasmFunctionParamOrderedDictEntryHints[$key] = @(Copy-WasmAstOrderedDictEntryTypes $entryArray)
}

function Set-WasmAstObservedFunctionParamEmptyArrayHint {
    param([string]$FunctionName, [string]$ParamName)

    $key = Get-WasmAstObservedFunctionParamKey $FunctionName $ParamName
    if ([string]::IsNullOrWhiteSpace($key)) { return }
    if ($script:wasmConflictedFunctionParamIndexedAccessHints.ContainsKey($key) -or
        $script:wasmConflictedFunctionParamEmptyArrayHints.ContainsKey($key)) { return }
    if ($script:wasmFunctionParamIndexedAccessHints.ContainsKey($key)) {
        Set-WasmAstObservedFunctionParamArrayShapeConflict $key
        return
    }
    $script:wasmFunctionParamEmptyArrayHints[$key] = $true
}

function Set-WasmAstObservedFunctionParamEmptyDictHint {
    param([string]$FunctionName, [string]$ParamName)

    $key = Get-WasmAstObservedFunctionParamKey $FunctionName $ParamName
    if ([string]::IsNullOrWhiteSpace($key)) { return }
    if ($script:wasmConflictedFunctionParamOrderedDictEntryHints.ContainsKey($key) -or
        $script:wasmConflictedFunctionParamEmptyDictHints.ContainsKey($key)) { return }
    if ($script:wasmFunctionParamOrderedDictEntryHints.ContainsKey($key)) {
        Set-WasmAstObservedFunctionParamDictShapeConflict $key
        return
    }
    $script:wasmFunctionParamEmptyDictHints[$key] = $true
}

function Set-WasmAstObservedFunctionParamCollectionHints {
    param([string]$FunctionName, [string]$ParamName, $ArgExpr)

    if ([string]::IsNullOrWhiteSpace($FunctionName) -or [string]::IsNullOrWhiteSpace($ParamName) -or $null -eq $ArgExpr) { return }
    $indexedHints = Get-WasmAstFixedIndexedAccessHintsForExpr $ArgExpr
    if (Test-WasmAstFixedIndexedHintMapHasItems $indexedHints) {
        Set-WasmAstObservedFunctionParamIndexedAccessHints $FunctionName $ParamName $indexedHints
    } elseif (Test-WasmAstKnownEmptyArrayExpr $ArgExpr) {
        Set-WasmAstObservedFunctionParamEmptyArrayHint $FunctionName $ParamName
    }

    $orderedEntries = @(Get-WasmAstOrderedDictEntryTypes $ArgExpr)
    if ($orderedEntries.Count -gt 0) {
        Set-WasmAstObservedFunctionParamOrderedDictEntryHints $FunctionName $ParamName $orderedEntries
    } elseif (Test-WasmAstKnownEmptyDictExpr $ArgExpr) {
        Set-WasmAstObservedFunctionParamEmptyDictHint $FunctionName $ParamName
    }
}

function Resolve-WasmAstObservedParamExpr {
    param($Expr, [hashtable]$ParamExprs)

    if ($null -eq $Expr) { return $null }
    if ([string]$Expr.node -eq "IDENT") {
        $name = [string]$Expr.name
        if ($ParamExprs.ContainsKey($name)) { return $ParamExprs[$name] }
    }
    return $Expr
}

function Register-WasmAstObservedSuperInitCallParamTypesFromBody {
    param(
        [string]$ClassName,
        $Body,
        [hashtable]$ParamExprs,
        [hashtable]$Seen = @{}
    )

    if ([string]::IsNullOrWhiteSpace($ClassName) -or $null -eq $Body -or -not $script:wasmClassDefs.ContainsKey($ClassName)) { return }
    foreach ($stmt in @(As-WasmAstArray ($Body.body))) {
        if ($null -eq $stmt) { continue }
        switch ([string]$stmt.node) {
            "EXPR_STMT" {
                if (Test-WasmAstSuperInitStmt $stmt) {
                    $parentName = [string]$script:wasmClassDefs[$ClassName].Parent
                    if ([string]::IsNullOrWhiteSpace($parentName) -or -not $script:wasmClassDefs.ContainsKey($parentName)) { continue }
                    $parentInit = Get-WasmAstClassInitMethod ($script:wasmClassDefs[$parentName].Node)
                    if ($null -eq $parentInit) { continue }
                    $resolvedArgs = New-Object System.Collections.Generic.List[object]
                    foreach ($arg in @(As-WasmAstArray ($stmt.expr.args))) {
                        $resolvedArgs.Add((Resolve-WasmAstObservedParamExpr $arg $ParamExprs)) | Out-Null
                    }
                    Register-WasmAstObservedCallParamTypes (Get-WasmClassConstructorName $parentName) ([string[]]@(Get-WasmAstParamNames ($parentInit.params))) @($resolvedArgs.ToArray())
                    Register-WasmAstObservedSuperInitCallParamTypes $parentName @($resolvedArgs.ToArray()) $Seen
                }
            }
            "SuraBlock" { Register-WasmAstObservedSuperInitCallParamTypesFromBody $ClassName $stmt $ParamExprs $Seen }
            "IF" {
                Register-WasmAstObservedSuperInitCallParamTypesFromBody $ClassName ($stmt.then_block) $ParamExprs $Seen
                Register-WasmAstObservedSuperInitCallParamTypesFromBody $ClassName ($stmt.else_block) $ParamExprs $Seen
            }
            "WHILE" { Register-WasmAstObservedSuperInitCallParamTypesFromBody $ClassName ($stmt.body) $ParamExprs $Seen }
            "REPEAT" { Register-WasmAstObservedSuperInitCallParamTypesFromBody $ClassName ($stmt.body) $ParamExprs $Seen }
            "FOR" { Register-WasmAstObservedSuperInitCallParamTypesFromBody $ClassName ($stmt.body) $ParamExprs $Seen }
            "FOREACH" { Register-WasmAstObservedSuperInitCallParamTypesFromBody $ClassName ($stmt.body) $ParamExprs $Seen }
            "MATCH" {
                foreach ($arm in @(As-WasmAstArray ($stmt.arms))) {
                    Register-WasmAstObservedSuperInitCallParamTypesFromBody $ClassName ($arm.body) $ParamExprs $Seen
                }
            }
            "TRY" {
                Register-WasmAstObservedSuperInitCallParamTypesFromBody $ClassName ($stmt.try_block) $ParamExprs $Seen
                Register-WasmAstObservedSuperInitCallParamTypesFromBody $ClassName ($stmt.catch_block) $ParamExprs $Seen
                Register-WasmAstObservedSuperInitCallParamTypesFromBody $ClassName ($stmt.finally_block) $ParamExprs $Seen
            }
            default { }
        }
    }
}

function Register-WasmAstObservedSuperInitCallParamTypes {
    param([string]$ClassName, $InputArgs, [hashtable]$Seen = @{})

    if ([string]::IsNullOrWhiteSpace($ClassName) -or -not $script:wasmClassDefs.ContainsKey($ClassName) -or $Seen.ContainsKey($ClassName)) { return }
    $Seen[$ClassName] = $true
    $init = Get-WasmAstClassInitMethod ($script:wasmClassDefs[$ClassName].Node)
    if ($null -eq $init) { return }
    $paramExprs = @{}
    $params = @(Get-WasmAstParamNames ($init.params))
    $args = @(As-WasmAstArray $InputArgs)
    for ($i = 0; $i -lt $params.Count -and $i -lt $args.Count; $i++) {
        $paramExprs[[string]$params[$i]] = $args[$i]
    }
    Register-WasmAstObservedSuperInitCallParamTypesFromBody $ClassName ($init.body) $paramExprs $Seen
}

function Register-WasmAstObservedSuperMethodCallParamTypesFromExpr {
    param(
        [string]$ClassName,
        $Expr,
        [hashtable]$ParamExprs,
        [hashtable]$Seen = @{}
    )

    if ([string]::IsNullOrWhiteSpace($ClassName) -or $null -eq $Expr -or -not $script:wasmClassDefs.ContainsKey($ClassName)) { return }
    switch ([string]$Expr.node) {
        "SUPER_CALL" {
            $methodName = [string]$Expr.method
            if ($methodName -ne "init") {
                $methodInfo = Get-WasmAstSuperClassMethod -ClassName $ClassName -MethodName $methodName
                if ($null -ne $methodInfo) {
                    $resolvedArgs = New-Object System.Collections.Generic.List[object]
                    foreach ($arg in @(As-WasmAstArray ($Expr.args))) {
                        $resolvedArgs.Add((Resolve-WasmAstObservedParamExpr $arg $ParamExprs)) | Out-Null
                    }
                    Register-WasmAstObservedCallParamTypes ([string]$methodInfo.FunctionName) ([string[]]@(Get-WasmAstParamNames ($methodInfo.Method.params))) @($resolvedArgs.ToArray())
                    Register-WasmAstObservedSuperMethodCallParamTypes ([string]$methodInfo.ClassName) ($methodInfo.Method) @($resolvedArgs.ToArray()) $Seen
                }
            }
            foreach ($arg in @(As-WasmAstArray ($Expr.args))) {
                Register-WasmAstObservedSuperMethodCallParamTypesFromExpr $ClassName $arg $ParamExprs $Seen
            }
        }
        "CALL" {
            foreach ($arg in @(As-WasmAstArray ($Expr.args))) {
                Register-WasmAstObservedSuperMethodCallParamTypesFromExpr $ClassName $arg $ParamExprs $Seen
            }
        }
        "METHOD_CALL" {
            Register-WasmAstObservedSuperMethodCallParamTypesFromExpr $ClassName ($Expr.obj) $ParamExprs $Seen
            foreach ($arg in @(As-WasmAstArray ($Expr.args))) {
                Register-WasmAstObservedSuperMethodCallParamTypesFromExpr $ClassName $arg $ParamExprs $Seen
            }
        }
        "BIN_OP" {
            Register-WasmAstObservedSuperMethodCallParamTypesFromExpr $ClassName ($Expr.left) $ParamExprs $Seen
            Register-WasmAstObservedSuperMethodCallParamTypesFromExpr $ClassName ($Expr.right) $ParamExprs $Seen
        }
        "UNARY_OP" { Register-WasmAstObservedSuperMethodCallParamTypesFromExpr $ClassName ($Expr.operand) $ParamExprs $Seen }
        "TERNARY" {
            Register-WasmAstObservedSuperMethodCallParamTypesFromExpr $ClassName ($Expr.cond) $ParamExprs $Seen
            Register-WasmAstObservedSuperMethodCallParamTypesFromExpr $ClassName ($Expr.then) $ParamExprs $Seen
            Register-WasmAstObservedSuperMethodCallParamTypesFromExpr $ClassName ($Expr.else) $ParamExprs $Seen
        }
        "DOT_ACCESS" { Register-WasmAstObservedSuperMethodCallParamTypesFromExpr $ClassName ($Expr.obj) $ParamExprs $Seen }
        "INDEX" {
            Register-WasmAstObservedSuperMethodCallParamTypesFromExpr $ClassName ($Expr.obj) $ParamExprs $Seen
            Register-WasmAstObservedSuperMethodCallParamTypesFromExpr $ClassName ($Expr.key) $ParamExprs $Seen
        }
        "ARRAY_LIT" {
            foreach ($item in @(As-WasmAstArray ($Expr.elements))) {
                Register-WasmAstObservedSuperMethodCallParamTypesFromExpr $ClassName $item $ParamExprs $Seen
            }
        }
        "DICT_LIT" {
            foreach ($entry in @(As-WasmAstArray ($Expr.entries))) {
                Register-WasmAstObservedSuperMethodCallParamTypesFromExpr $ClassName ($entry.value) $ParamExprs $Seen
            }
        }
        "STR_LIT" {
            foreach ($part in @(Get-WasmAstInterpolatedTextExprNodes ([string]$Expr.value))) {
                Register-WasmAstObservedSuperMethodCallParamTypesFromExpr $ClassName $part $ParamExprs $Seen
            }
        }
        "STR_INTERP" {
            foreach ($part in @(As-WasmAstArray ($Expr.parts))) {
                Register-WasmAstObservedSuperMethodCallParamTypesFromExpr $ClassName $part $ParamExprs $Seen
            }
        }
        "NEW_EXPR" {
            foreach ($arg in @(As-WasmAstArray ($Expr.args))) {
                Register-WasmAstObservedSuperMethodCallParamTypesFromExpr $ClassName $arg $ParamExprs $Seen
            }
        }
        default { }
    }
}

function Register-WasmAstObservedSuperMethodCallParamTypesFromBody {
    param(
        [string]$ClassName,
        $Body,
        [hashtable]$ParamExprs,
        [hashtable]$Seen = @{}
    )

    if ([string]::IsNullOrWhiteSpace($ClassName) -or $null -eq $Body -or -not $script:wasmClassDefs.ContainsKey($ClassName)) { return }
    foreach ($stmt in @(As-WasmAstArray ($Body.body))) {
        if ($null -eq $stmt) { continue }
        switch ([string]$stmt.node) {
            "ASSIGN" { Register-WasmAstObservedSuperMethodCallParamTypesFromExpr $ClassName ($stmt.value) $ParamExprs $Seen }
            "DOT_ASSIGN" { Register-WasmAstObservedSuperMethodCallParamTypesFromExpr $ClassName ($stmt.value) $ParamExprs $Seen }
            "INDEX_ASSIGN" {
                Register-WasmAstObservedSuperMethodCallParamTypesFromExpr $ClassName ($stmt.key) $ParamExprs $Seen
                Register-WasmAstObservedSuperMethodCallParamTypesFromExpr $ClassName ($stmt.value) $ParamExprs $Seen
            }
            "EXPR_STMT" { Register-WasmAstObservedSuperMethodCallParamTypesFromExpr $ClassName ($stmt.expr) $ParamExprs $Seen }
            "RETURN" { Register-WasmAstObservedSuperMethodCallParamTypesFromExpr $ClassName ($stmt.value) $ParamExprs $Seen }
            "CMD" {
                foreach ($arg in @(As-WasmAstArray ($stmt.args))) {
                    Register-WasmAstObservedSuperMethodCallParamTypesFromExpr $ClassName $arg $ParamExprs $Seen
                }
            }
            "SuraBlock" { Register-WasmAstObservedSuperMethodCallParamTypesFromBody $ClassName $stmt $ParamExprs $Seen }
            "IF" {
                Register-WasmAstObservedSuperMethodCallParamTypesFromBody $ClassName ($stmt.then_block) $ParamExprs $Seen
                Register-WasmAstObservedSuperMethodCallParamTypesFromBody $ClassName ($stmt.else_block) $ParamExprs $Seen
            }
            "WHILE" { Register-WasmAstObservedSuperMethodCallParamTypesFromBody $ClassName ($stmt.body) $ParamExprs $Seen }
            "REPEAT" { Register-WasmAstObservedSuperMethodCallParamTypesFromBody $ClassName ($stmt.body) $ParamExprs $Seen }
            "FOR" { Register-WasmAstObservedSuperMethodCallParamTypesFromBody $ClassName ($stmt.body) $ParamExprs $Seen }
            "FOREACH" { Register-WasmAstObservedSuperMethodCallParamTypesFromBody $ClassName ($stmt.body) $ParamExprs $Seen }
            "MATCH" {
                foreach ($arm in @(As-WasmAstArray ($stmt.arms))) {
                    Register-WasmAstObservedSuperMethodCallParamTypesFromBody $ClassName ($arm.body) $ParamExprs $Seen
                }
            }
            "TRY" {
                Register-WasmAstObservedSuperMethodCallParamTypesFromBody $ClassName ($stmt.try_block) $ParamExprs $Seen
                Register-WasmAstObservedSuperMethodCallParamTypesFromBody $ClassName ($stmt.catch_block) $ParamExprs $Seen
                Register-WasmAstObservedSuperMethodCallParamTypesFromBody $ClassName ($stmt.finally_block) $ParamExprs $Seen
            }
            default { }
        }
    }
}

function Get-WasmAstObservedSuperMethodSeenKey {
    param([string]$ClassName, [string]$MethodName, $InputArgs)

    $argJson = try {
        (@(As-WasmAstArray $InputArgs) | ConvertTo-Json -Depth 8 -Compress)
    } catch {
        ""
    }
    return "$ClassName.$MethodName|$argJson"
}

function Register-WasmAstObservedSuperMethodCallParamTypes {
    param([string]$ClassName, $MethodNode, $InputArgs, [hashtable]$Seen = @{})

    if ([string]::IsNullOrWhiteSpace($ClassName) -or $null -eq $MethodNode -or -not $script:wasmClassDefs.ContainsKey($ClassName)) { return }
    $methodName = [string]$MethodNode.name
    $seenKey = Get-WasmAstObservedSuperMethodSeenKey $ClassName $methodName $InputArgs
    if ($Seen.ContainsKey($seenKey)) { return }
    $Seen[$seenKey] = $true
    $paramExprs = @{}
    $params = @(Get-WasmAstParamNames ($MethodNode.params))
    $args = @(As-WasmAstArray $InputArgs)
    for ($i = 0; $i -lt $params.Count -and $i -lt $args.Count; $i++) {
        $paramExprs[[string]$params[$i]] = $args[$i]
    }
    Register-WasmAstObservedSuperMethodCallParamTypesFromBody $ClassName ($MethodNode.body) $paramExprs $Seen
}

function Remove-WasmAstCollectionAccessHintsForBase {
    param([hashtable]$Map, [string]$BaseName)

    if ($null -eq $Map -or [string]::IsNullOrWhiteSpace($BaseName)) { return }
    $prefixDot = "$BaseName."
    $prefixIndex = "$BaseName["
    foreach ($key in @($Map.Keys)) {
        $text = [string]$key
        if ($text.StartsWith($prefixDot) -or $text.StartsWith($prefixIndex)) {
            $Map.Remove($key)
        }
    }
}

function Clear-WasmAstScopedCollectionShapeHints {
    param([string]$BaseName)

    if ([string]::IsNullOrWhiteSpace($BaseName)) { return }
    Clear-WasmAstEmptyCollectionHints $BaseName
    if ($script:wasmDictKeyOrderHints.ContainsKey($BaseName)) { $script:wasmDictKeyOrderHints.Remove($BaseName) }
    foreach ($map in @(
        $script:wasmAccessTypeHints,
        $script:wasmConflictedAccessTypeHints,
        $script:wasmStringAccessHints,
        $script:wasmAccessFunctionDisplayHints,
        $script:wasmConflictedAccessFunctionDisplayHints,
        $script:wasmAccessFunctionLiftHints,
        $script:wasmConflictedAccessFunctionLiftHints,
        $script:wasmAccessObjectClassHints,
        $script:wasmConflictedAccessObjectClassHints
    )) {
        Remove-WasmAstCollectionAccessHintsForBase $map $BaseName
    }
}

function Set-WasmAstCurrentFunctionParamCollectionHints {
    param([string]$FunctionName, [string[]]$Params)

    if ([string]::IsNullOrWhiteSpace($FunctionName) -or $null -eq $Params) { return }
    foreach ($paramNameItem in @($Params)) {
        $paramName = [string]$paramNameItem
        if ([string]::IsNullOrWhiteSpace($paramName)) { continue }
        $key = Get-WasmAstObservedFunctionParamKey $FunctionName $paramName
        if ([string]::IsNullOrWhiteSpace($key)) { continue }
        Clear-WasmAstScopedCollectionShapeHints $paramName
        if ($script:wasmFunctionParamIndexedAccessHints.ContainsKey($key) -and
            -not $script:wasmConflictedFunctionParamIndexedAccessHints.ContainsKey($key)) {
            $map = Copy-WasmAstFixedIndexedHintMap $script:wasmFunctionParamIndexedAccessHints[$key]
            Set-WasmAstCurrentLocalIndexedAccessHintsFromMap $paramName $map
            Set-WasmAstIndexedAccessHintsFromMap $paramName $map
        }
        if ($script:wasmFunctionParamOrderedDictEntryHints.ContainsKey($key) -and
            -not $script:wasmConflictedFunctionParamOrderedDictEntryHints.ContainsKey($key)) {
            Set-WasmAstOrderedDictEntryHintsForBase $paramName $script:wasmFunctionParamOrderedDictEntryHints[$key]
        }
        if ($script:wasmFunctionParamEmptyArrayHints.ContainsKey($key) -and
            -not $script:wasmConflictedFunctionParamEmptyArrayHints.ContainsKey($key)) {
            Set-WasmAstEmptyArrayHint $paramName
        }
        if ($script:wasmFunctionParamEmptyDictHints.ContainsKey($key) -and
            -not $script:wasmConflictedFunctionParamEmptyDictHints.ContainsKey($key)) {
            Set-WasmAstEmptyDictHint $paramName
        }
    }
}

function Set-WasmAstAccessTypeHint {
    param([string]$BaseName, [string]$KeyName, [string]$TypeName)

    if ([string]::IsNullOrWhiteSpace($BaseName) -or [string]::IsNullOrWhiteSpace($KeyName) -or
        [string]::IsNullOrWhiteSpace($TypeName)) { return }
    $hintKey = "$BaseName.$KeyName"
    if ($script:wasmConflictedAccessTypeHints.ContainsKey($hintKey)) { return }
    if ($script:wasmAccessTypeHints.ContainsKey($hintKey) -and [string]$script:wasmAccessTypeHints[$hintKey] -ne $TypeName) {
        $script:wasmAccessTypeHints.Remove($hintKey)
        if ($script:wasmStringAccessHints.ContainsKey($hintKey)) { $script:wasmStringAccessHints.Remove($hintKey) }
        $script:wasmConflictedAccessTypeHints[$hintKey] = $true
        return
    }
    $script:wasmAccessTypeHints[$hintKey] = $TypeName
    if ($TypeName -eq "string") { Add-WasmAstStringAccessHint $BaseName $KeyName }
}

function Set-WasmAstAccessTypeHintAfterWrite {
    param([string]$BaseName, [string]$KeyName, [string]$TypeName)

    if ([string]::IsNullOrWhiteSpace($BaseName) -or [string]::IsNullOrWhiteSpace($KeyName) -or
        [string]::IsNullOrWhiteSpace($TypeName)) { return }
    $hintKey = "$BaseName.$KeyName"
    if ($script:wasmConflictedAccessTypeHints.ContainsKey($hintKey)) {
        $script:wasmConflictedAccessTypeHints.Remove($hintKey)
    }
    $script:wasmAccessTypeHints[$hintKey] = $TypeName
    if ($TypeName -eq "string") {
        Add-WasmAstStringAccessHint $BaseName $KeyName
    } elseif ($script:wasmStringAccessHints.ContainsKey($hintKey)) {
        $script:wasmStringAccessHints.Remove($hintKey)
    }
}

function Set-WasmAstIndexedAccessTypeHint {
    param([string]$BaseName, [int]$Index, [string]$TypeName)

    if ([string]::IsNullOrWhiteSpace($BaseName) -or [string]::IsNullOrWhiteSpace($TypeName)) { return }
    $hintKey = ("{0}[{1}]" -f $BaseName, $Index)
    if ($script:wasmConflictedAccessTypeHints.ContainsKey($hintKey)) { return }
    if ($script:wasmAccessTypeHints.ContainsKey($hintKey) -and [string]$script:wasmAccessTypeHints[$hintKey] -ne $TypeName) {
        $script:wasmAccessTypeHints.Remove($hintKey)
        if ($script:wasmStringAccessHints.ContainsKey($hintKey)) { $script:wasmStringAccessHints.Remove($hintKey) }
        $script:wasmConflictedAccessTypeHints[$hintKey] = $true
        return
    }
    $script:wasmAccessTypeHints[$hintKey] = $TypeName
    if ($TypeName -eq "string") { $script:wasmStringAccessHints[$hintKey] = $true }
}

function Set-WasmAstIndexedAccessTypeHintAfterWrite {
    param([string]$BaseName, [int]$Index, [string]$TypeName)

    if ([string]::IsNullOrWhiteSpace($BaseName) -or [string]::IsNullOrWhiteSpace($TypeName) -or $Index -lt 0) { return }
    $hintKey = ("{0}[{1}]" -f $BaseName, $Index)
    if ($script:wasmConflictedAccessTypeHints.ContainsKey($hintKey)) {
        $script:wasmConflictedAccessTypeHints.Remove($hintKey)
    }
    $script:wasmAccessTypeHints[$hintKey] = $TypeName
    if ($TypeName -eq "string") {
        $script:wasmStringAccessHints[$hintKey] = $true
    } elseif ($script:wasmStringAccessHints.ContainsKey($hintKey)) {
        $script:wasmStringAccessHints.Remove($hintKey)
    }
}

function Set-WasmAstDynamicIndexedAccessTypeHint {
    param([string]$BaseName, [string]$IndexName, [string]$TypeName)

    if ([string]::IsNullOrWhiteSpace($BaseName) -or [string]::IsNullOrWhiteSpace($IndexName) -or
        [string]::IsNullOrWhiteSpace($TypeName)) { return }
    $hintKey = ('{0}[${1}]' -f $BaseName, $IndexName)
    if ($script:wasmConflictedAccessTypeHints.ContainsKey($hintKey)) { return }
    if ($script:wasmAccessTypeHints.ContainsKey($hintKey) -and [string]$script:wasmAccessTypeHints[$hintKey] -ne $TypeName) {
        $script:wasmAccessTypeHints.Remove($hintKey)
        if ($script:wasmStringAccessHints.ContainsKey($hintKey)) { $script:wasmStringAccessHints.Remove($hintKey) }
        $script:wasmConflictedAccessTypeHints[$hintKey] = $true
        return
    }
    $script:wasmAccessTypeHints[$hintKey] = $TypeName
    if ($TypeName -eq "string") { $script:wasmStringAccessHints[$hintKey] = $true }
}

function Set-WasmAstDynamicKeyAccessTypeHint {
    param([string]$BaseName, [string]$KeyName, [string]$TypeName)

    Set-WasmAstDynamicIndexedAccessTypeHint $BaseName $KeyName $TypeName
}

function Set-WasmAstAccessFunctionDisplayHintByKey {
    param([string]$HintKey, [string]$DisplayName)

    if ([string]::IsNullOrWhiteSpace($HintKey)) { return }
    if ($script:wasmConflictedAccessFunctionDisplayHints.ContainsKey($HintKey)) { return }
    if ([string]::IsNullOrWhiteSpace($DisplayName)) {
        if ($script:wasmAccessFunctionDisplayHints.ContainsKey($HintKey)) {
            $script:wasmAccessFunctionDisplayHints.Remove($HintKey)
            $script:wasmConflictedAccessFunctionDisplayHints[$HintKey] = $true
        }
        return
    }
    if ($script:wasmAccessFunctionDisplayHints.ContainsKey($HintKey) -and
        [string]$script:wasmAccessFunctionDisplayHints[$HintKey] -ne $DisplayName) {
        $script:wasmAccessFunctionDisplayHints.Remove($HintKey)
        $script:wasmConflictedAccessFunctionDisplayHints[$HintKey] = $true
        return
    }
