function New-WasmAstFixedIndexedHint {
    param([string]$TypeName = "", [string]$FunctionDisplayName = "", [string]$ObjectClassName = "")

    return [pscustomobject]@{
        TypeName = $TypeName
        FunctionDisplayName = $FunctionDisplayName
        ObjectClassName = $ObjectClassName
    }
}

function Test-WasmAstFixedIndexedHintMapHasItems {
    param([hashtable]$Map)

    return ($null -ne $Map -and $Map.get_Count() -gt 0)
}

function Copy-WasmAstFixedIndexedHintMap {
    param([hashtable]$Map)

    $copy = @{}
    if ($null -eq $Map) { return $copy }
    foreach ($entry in $Map.GetEnumerator()) {
        $hint = $entry.Value
        $copy[[string]$entry.Key] = New-WasmAstFixedIndexedHint ([string]$hint.TypeName) ([string]$hint.FunctionDisplayName) ([string]$hint.ObjectClassName)
    }
    return $copy
}

function Get-WasmAstContiguousFixedIndexedHintCount {
    param([hashtable]$Map)

    if (-not (Test-WasmAstFixedIndexedHintMapHasItems $Map)) { return -1 }
    $indexes = New-Object System.Collections.Generic.List[int]
    foreach ($key in @($Map.Keys)) {
        $parsed = 0
        if (-not [int]::TryParse([string]$key, [ref]$parsed) -or $parsed -lt 0) { return -1 }
        $indexes.Add($parsed) | Out-Null
    }
    $ordered = @($indexes.ToArray() | Sort-Object)
    for ($i = 0; $i -lt $ordered.Count; $i++) {
        if ([int]$ordered[$i] -ne $i) { return -1 }
    }
    return $ordered.Count
}

function New-WasmAstFixedNumericIndexedHintsFromCaptureArray {
    param($ArrayValue)

    $out = @{}
    if ($null -eq $ArrayValue -or [string]$ArrayValue.node -ne "ARRAY_LIT") { return $out }
    $index = 0
    foreach ($element in @(As-WasmAstArray ($ArrayValue.elements))) {
        if ($null -ne $element -and [string]$element.node -eq "NUM_LIT") {
            $out[[string]$index] = New-WasmAstFixedIndexedHint "num" "" ""
        }
        $index++
    }
    return $out
}

function Copy-WasmAstLocalIndexedAccessHints {
    param([hashtable]$Hints)

    $copy = @{}
    if ($null -eq $Hints) { return $copy }
    foreach ($entry in $Hints.GetEnumerator()) {
        $copy[[string]$entry.Key] = Copy-WasmAstFixedIndexedHintMap $entry.Value
    }
    return $copy
}

function Set-WasmAstCurrentLocalIndexedAccessHintsFromMap {
    param([string]$BaseName, [hashtable]$Map)

    if ([string]::IsNullOrWhiteSpace($BaseName)) { return }
    if (Test-WasmAstFixedIndexedHintMapHasItems $Map) {
        $script:wasmCurrentLocalIndexedAccessHints[$BaseName] = Copy-WasmAstFixedIndexedHintMap $Map
    } elseif ($script:wasmCurrentLocalIndexedAccessHints.ContainsKey($BaseName)) {
        $script:wasmCurrentLocalIndexedAccessHints.Remove($BaseName)
    }
}

function Clear-WasmAstCurrentLocalCollectionShapeHints {
    param([string]$BaseName)

    if ([string]::IsNullOrWhiteSpace($BaseName)) { return }
    $prefixDot = "$BaseName."
    $prefixIndex = "$BaseName["
    foreach ($key in @($script:wasmCurrentLocalIndexedAccessHints.Keys)) {
        $text = [string]$key
        if ($text -eq $BaseName -or $text.StartsWith($prefixDot) -or $text.StartsWith($prefixIndex)) {
            $script:wasmCurrentLocalIndexedAccessHints.Remove($key)
        }
    }
}

function Copy-WasmAstCurrentLocalCollectionShapeDescendants {
    param([string]$TargetName, [string]$SourceName)

    if ([string]::IsNullOrWhiteSpace($TargetName) -or
        [string]::IsNullOrWhiteSpace($SourceName) -or
        $TargetName -eq $SourceName) {
        return
    }

    $sourceDot = "$SourceName."
    $sourceIndex = "$SourceName["
    foreach ($key in @($script:wasmCurrentLocalIndexedAccessHints.Keys)) {
        $text = [string]$key
        if (-not ($text.StartsWith($sourceDot) -or $text.StartsWith($sourceIndex))) { continue }
        $suffix = $text.Substring($SourceName.Length)
        $script:wasmCurrentLocalIndexedAccessHints["$TargetName$suffix"] =
            Copy-WasmAstFixedIndexedHintMap $script:wasmCurrentLocalIndexedAccessHints[$key]
    }
}

function Set-WasmAstCurrentLocalCollectionShapeHintsFromExpr {
    param([string]$BaseName, $Expr, [hashtable]$Seen = @{})

    if ([string]::IsNullOrWhiteSpace($BaseName)) { return }
    Clear-WasmAstCurrentLocalCollectionShapeHints $BaseName
    if ($null -eq $Expr) { return }

    $indexedHints = Get-WasmAstFixedIndexedAccessHintsForExpr $Expr $script:wasmCurrentLocalIndexedAccessHints
    $keyedHints = Get-WasmAstFixedStringKeyAccessHintsForExpr $Expr $script:wasmCurrentLocalIndexedAccessHints
    if (Test-WasmAstFixedIndexedHintMapHasItems $keyedHints) {
        Set-WasmAstCurrentLocalIndexedAccessHintsFromMap $BaseName $keyedHints
    } elseif (Test-WasmAstFixedIndexedHintMapHasItems $indexedHints) {
        Set-WasmAstCurrentLocalIndexedAccessHintsFromMap $BaseName $indexedHints
    }

    switch ([string]$Expr.node) {
        "IDENT" {
            Copy-WasmAstCurrentLocalCollectionShapeDescendants $BaseName ([string]$Expr.name)
        }
        "DICT_LIT" {
            foreach ($entry in @(As-WasmAstArray ($Expr.entries))) {
                $key = [string]$entry.key
                if ([string]::IsNullOrWhiteSpace($key)) { continue }
                Set-WasmAstCurrentLocalCollectionShapeHintsFromExpr "$BaseName.$key" ($entry.value) $Seen
            }
        }
        "ARRAY_LIT" {
            $index = 0
            foreach ($element in @(As-WasmAstArray ($Expr.elements))) {
                Set-WasmAstCurrentLocalCollectionShapeHintsFromExpr "$BaseName[$index]" $element $Seen
                $index++
            }
        }
        "TERNARY" {
            $condState = Get-WasmAstKnownBoolLiteralState ($Expr.cond)
            if ($condState -eq "true") {
                Set-WasmAstCurrentLocalCollectionShapeHintsFromExpr $BaseName ($Expr.then) $Seen
            } elseif ($condState -eq "false") {
                Set-WasmAstCurrentLocalCollectionShapeHintsFromExpr $BaseName ($Expr.else) $Seen
            }
        }
        "CALL" {
            $seenKey = "call:$([string]$Expr.name)"
            if (-not $Seen.ContainsKey($seenKey)) {
                $Seen[$seenKey] = $true
                try {
                    $resolved = Resolve-WasmAstFunctionCallReturnExpr $Expr
                    if ($null -ne $resolved) {
                        Set-WasmAstCurrentLocalCollectionShapeHintsFromExpr $BaseName $resolved $Seen
                    }
                } finally {
                    $Seen.Remove($seenKey)
                }
            }
        }
        "METHOD_CALL" {
            $seenKey = "method:$([string]$Expr.method)"
            if (-not $Seen.ContainsKey($seenKey)) {
                $Seen[$seenKey] = $true
                try {
                    $resolved = Resolve-WasmAstMethodCallReturnExpr $Expr
                    if ($null -ne $resolved) {
                        Set-WasmAstCurrentLocalCollectionShapeHintsFromExpr $BaseName $resolved $Seen
                    }
                } finally {
                    $Seen.Remove($seenKey)
                }
            }
        }
    }
}

function Get-WasmAstCurrentLocalIndexedAccessHint {
    param([string]$BaseName, [int]$Index)

    if ([string]::IsNullOrWhiteSpace($BaseName) -or
        -not $script:wasmCurrentLocalIndexedAccessHints.ContainsKey($BaseName)) {
        return $null
    }
    $map = $script:wasmCurrentLocalIndexedAccessHints[$BaseName]
    $key = [string]$Index
    if ($null -ne $map -and $map.ContainsKey($key)) { return $map[$key] }
    return $null
}

function Set-WasmAstCurrentLocalIndexedAccessHint {
    param(
        [string]$BaseName,
        [int]$Index,
        [string]$TypeName = "",
        [string]$FunctionDisplayName = "",
        [string]$ObjectClassName = ""
    )

    if ([string]::IsNullOrWhiteSpace($BaseName) -or $Index -lt 0) { return }
    $hasType = ([string]$TypeName -in @("string", "bool", "nil", "num", "array", "dict", "function"))
    $hasClass = (-not [string]::IsNullOrWhiteSpace($ObjectClassName) -and $script:wasmClassDefs.ContainsKey($ObjectClassName))
    $key = [string]$Index
    $map = @{}
    if ($script:wasmCurrentLocalIndexedAccessHints.ContainsKey($BaseName)) {
        $map = Copy-WasmAstFixedIndexedHintMap $script:wasmCurrentLocalIndexedAccessHints[$BaseName]
    }

    if ($hasType -or $hasClass) {
        $map[$key] = New-WasmAstFixedIndexedHint $(if ($hasType) { [string]$TypeName } else { "" }) ([string]$FunctionDisplayName) $(if ($hasClass) { [string]$ObjectClassName } else { "" })
    } elseif ($map.ContainsKey($key)) {
        $map.Remove($key)
    }

    if (Test-WasmAstFixedIndexedHintMapHasItems $map) {
        $script:wasmCurrentLocalIndexedAccessHints[$BaseName] = $map
    } elseif ($script:wasmCurrentLocalIndexedAccessHints.ContainsKey($BaseName)) {
        $script:wasmCurrentLocalIndexedAccessHints.Remove($BaseName)
    }
}

function Set-WasmAstCurrentLocalKeyedAccessHint {
    param(
        [string]$BaseName,
        [string]$KeyName,
        [string]$TypeName = "",
        [string]$FunctionDisplayName = "",
        [string]$ObjectClassName = ""
    )

    if ([string]::IsNullOrWhiteSpace($BaseName) -or [string]::IsNullOrWhiteSpace($KeyName)) { return }
    $hasType = ([string]$TypeName -in @("string", "bool", "nil", "num", "array", "dict", "function"))
    $hasClass = (-not [string]::IsNullOrWhiteSpace($ObjectClassName) -and $script:wasmClassDefs.ContainsKey($ObjectClassName))
    $map = @{}
    if ($script:wasmCurrentLocalIndexedAccessHints.ContainsKey($BaseName)) {
        $map = Copy-WasmAstFixedIndexedHintMap $script:wasmCurrentLocalIndexedAccessHints[$BaseName]
    }

    if ($hasType -or $hasClass) {
        $map[$KeyName] = New-WasmAstFixedIndexedHint $(if ($hasType) { [string]$TypeName } else { "" }) ([string]$FunctionDisplayName) $(if ($hasClass) { [string]$ObjectClassName } else { "" })
    } elseif ($map.ContainsKey($KeyName)) {
        $map.Remove($KeyName)
    }

    if (Test-WasmAstFixedIndexedHintMapHasItems $map) {
        $script:wasmCurrentLocalIndexedAccessHints[$BaseName] = $map
    } elseif ($script:wasmCurrentLocalIndexedAccessHints.ContainsKey($BaseName)) {
        $script:wasmCurrentLocalIndexedAccessHints.Remove($BaseName)
    }
}

function Merge-WasmAstFixedIndexedHintMaps {
    param([hashtable]$Left, [hashtable]$Right)

    $merged = @{}
    if (-not (Test-WasmAstFixedIndexedHintMapHasItems $Left) -or
        -not (Test-WasmAstFixedIndexedHintMapHasItems $Right)) {
        return $merged
    }
    foreach ($entry in $Left.GetEnumerator()) {
        $key = [string]$entry.Key
        if (-not $Right.ContainsKey($key)) { continue }
        $a = $entry.Value
        $b = $Right[$key]
        if ([string]$a.TypeName -eq [string]$b.TypeName -and
            [string]$a.FunctionDisplayName -eq [string]$b.FunctionDisplayName -and
            [string]$a.ObjectClassName -eq [string]$b.ObjectClassName) {
            $merged[$key] = New-WasmAstFixedIndexedHint ([string]$a.TypeName) ([string]$a.FunctionDisplayName) ([string]$a.ObjectClassName)
        }
    }
    return $merged
}

function Merge-WasmAstLocalIndexedAccessHints {
    param([hashtable]$Left, [hashtable]$Right)

    $merged = @{}
    if ($null -eq $Left -or $null -eq $Right) { return $merged }
    foreach ($entry in $Left.GetEnumerator()) {
        $name = [string]$entry.Key
        if (-not $Right.ContainsKey($name)) { continue }
        $map = Merge-WasmAstFixedIndexedHintMaps $entry.Value $Right[$name]
        if (Test-WasmAstFixedIndexedHintMapHasItems $map) {
            $merged[$name] = $map
        }
    }
    return $merged
}

function Set-WasmAstIndexedAccessHintsFromMap {
    param([string]$BaseName, [hashtable]$Map)

    if ([string]::IsNullOrWhiteSpace($BaseName) -or -not (Test-WasmAstFixedIndexedHintMapHasItems $Map)) { return }
    foreach ($entry in $Map.GetEnumerator()) {
        $index = 0
        if (-not [int]::TryParse([string]$entry.Key, [ref]$index) -or $index -lt 0) { continue }
        $hint = $entry.Value
        if ([string]$hint.TypeName -in @("string", "bool", "nil", "num", "array", "dict", "function")) {
            Set-WasmAstIndexedAccessTypeHint $BaseName $index ([string]$hint.TypeName)
        }
        if ([string]$hint.TypeName -eq "function") {
            Set-WasmAstIndexedAccessFunctionDisplayHint $BaseName $index ([string]$hint.FunctionDisplayName)
        }
        Set-WasmAstIndexedAccessObjectClassHint $BaseName $index ([string]$hint.ObjectClassName)
    }
}

function Set-WasmAstStringKeyAccessHintsFromMap {
    param([string]$BaseName, [hashtable]$Map)

    if ([string]::IsNullOrWhiteSpace($BaseName) -or -not (Test-WasmAstFixedIndexedHintMapHasItems $Map)) { return }
    foreach ($entry in $Map.GetEnumerator()) {
        $keyName = [string]$entry.Key
        $hint = $entry.Value
        if ([string]::IsNullOrWhiteSpace($keyName)) { continue }
        if ([string]$hint.TypeName -in @("string", "bool", "nil", "num", "array", "dict", "function")) {
            Set-WasmAstAccessTypeHint $BaseName $keyName ([string]$hint.TypeName)
        }
        if ([string]$hint.TypeName -eq "function") {
            Set-WasmAstAccessFunctionDisplayHint $BaseName $keyName ([string]$hint.FunctionDisplayName)
        }
        Set-WasmAstAccessObjectClassHint $BaseName $keyName ([string]$hint.ObjectClassName)
    }
}

function Get-WasmAstAccessPathName {
    param($Node)

    if ($null -eq $Node) { return "" }
    switch ([string]$Node.node) {
        "IDENT" {
            return [string]$Node.name
        }
        "DOT_ACCESS" {
            $base = Get-WasmAstAccessPathName ($Node.obj)
            if ([string]::IsNullOrWhiteSpace($base)) { return "" }
            return "$base.$([string]$Node.prop)"
        }
        "INDEX" {
            $base = Get-WasmAstAccessPathName ($Node.obj)
            if ([string]::IsNullOrWhiteSpace($base) -or $null -eq $Node.key) { return "" }
            if ([string]$Node.key.node -eq "STR_LIT") {
                return "$base.$([string]$Node.key.value)"
            }
            $literalKey = Get-WasmAstKnownStringLiteralValue ($Node.key)
            if (-not [string]::IsNullOrWhiteSpace($literalKey)) {
                return "$base.$literalKey"
            }
            return ""
        }
        default {
            return ""
        }
    }
}

function Clear-WasmAstEmptyCollectionHints {
    param([string]$BaseName)

    if ([string]::IsNullOrWhiteSpace($BaseName)) { return }
    if ($script:wasmEmptyArrayHints.ContainsKey($BaseName)) { $script:wasmEmptyArrayHints.Remove($BaseName) }
    if ($script:wasmEmptyDictHints.ContainsKey($BaseName)) { $script:wasmEmptyDictHints.Remove($BaseName) }
}

function Set-WasmAstEmptyArrayHint {
    param([string]$BaseName)

    if ([string]::IsNullOrWhiteSpace($BaseName)) { return }
    Clear-WasmAstEmptyCollectionHints $BaseName
    $script:wasmEmptyArrayHints[$BaseName] = $true
}

function Set-WasmAstEmptyDictHint {
    param([string]$BaseName)

    if ([string]::IsNullOrWhiteSpace($BaseName)) { return }
    Clear-WasmAstEmptyCollectionHints $BaseName
    $script:wasmEmptyDictHints[$BaseName] = $true
    $script:wasmDictKeyOrderHints[$BaseName] = [string[]]@()
}

function Test-WasmAstEmptyArrayLiteral {
    param($Node)

    return ($null -ne $Node -and [string]$Node.node -eq "ARRAY_LIT" -and @(As-WasmAstArray ($Node.elements)).Count -eq 0)
}

function Test-WasmAstEmptyDictLiteral {
    param($Node)

    return ($null -ne $Node -and [string]$Node.node -eq "DICT_LIT" -and @(As-WasmAstArray ($Node.entries)).Count -eq 0)
}

function Test-WasmAstKnownEmptyArrayExpr {
    param($Node)

    if (Test-WasmAstEmptyArrayLiteral $Node) { return $true }
    $accessName = Get-WasmAstAccessPathName $Node
    return (-not [string]::IsNullOrWhiteSpace($accessName) -and $script:wasmEmptyArrayHints.ContainsKey($accessName))
}

function Test-WasmAstKnownEmptyDictExpr {
    param($Node)

    if (Test-WasmAstEmptyDictLiteral $Node) { return $true }
    $accessName = Get-WasmAstAccessPathName $Node
    return (-not [string]::IsNullOrWhiteSpace($accessName) -and $script:wasmEmptyDictHints.ContainsKey($accessName))
}

function Get-WasmAstKnownBoolLiteralState {
    param($Node)

    if ($null -eq $Node) { return "" }
    if ([string]$Node.node -eq "BOOL_LIT") {
        if ([System.Convert]::ToBoolean($Node.value)) { return "true" }
        return "false"
    }
    if ([string]$Node.node -eq "UNARY_OP" -and [string]$Node.op -eq "not") {
        $inner = Get-WasmAstKnownBoolLiteralState ($Node.operand)
        if ($inner -eq "true") { return "false" }
        if ($inner -eq "false") { return "true" }
    }
    return ""
}

function Get-WasmAstFixedIndexedAccessHintsByBase {
    param([string]$BaseName, [hashtable]$LocalIndexedHints = @{})

    $out = @{}
    if ([string]::IsNullOrWhiteSpace($BaseName)) { return $out }
    if ($LocalIndexedHints.ContainsKey($BaseName)) {
        foreach ($entry in $LocalIndexedHints[$BaseName].GetEnumerator()) {
            $key = [string]$entry.Key
            if ($key -match '^\d+$') {
                $hint = $entry.Value
                $out[$key] = New-WasmAstFixedIndexedHint ([string]$hint.TypeName) ([string]$hint.FunctionDisplayName) ([string]$hint.ObjectClassName)
            }
        }
        return $out
    }
    if ($script:wasmCurrentLocalIndexedAccessHints.ContainsKey($BaseName)) {
        foreach ($entry in $script:wasmCurrentLocalIndexedAccessHints[$BaseName].GetEnumerator()) {
            $key = [string]$entry.Key
            if ($key -match '^\d+$') {
                $hint = $entry.Value
                $out[$key] = New-WasmAstFixedIndexedHint ([string]$hint.TypeName) ([string]$hint.FunctionDisplayName) ([string]$hint.ObjectClassName)
            }
        }
        return $out
    }
    foreach ($entry in $script:wasmAccessTypeHints.GetEnumerator()) {
        $key = [string]$entry.Key
        if ($key -match "^$([regex]::Escape($BaseName))\[(\d+)\]$" -and
            -not $script:wasmConflictedAccessTypeHints.ContainsKey($key)) {
            $idx = [string][int]$Matches[1]
            $out[$idx] = New-WasmAstFixedIndexedHint ([string]$entry.Value) "" ""
        }
    }
    foreach ($entry in $script:wasmAccessFunctionDisplayHints.GetEnumerator()) {
        $key = [string]$entry.Key
        if ($key -match "^$([regex]::Escape($BaseName))\[(\d+)\]$" -and
            -not $script:wasmConflictedAccessFunctionDisplayHints.ContainsKey($key)) {
            $idx = [string][int]$Matches[1]
            if (-not $out.ContainsKey($idx)) { $out[$idx] = New-WasmAstFixedIndexedHint }
            $out[$idx].FunctionDisplayName = [string]$entry.Value
        }
    }
    foreach ($entry in $script:wasmAccessObjectClassHints.GetEnumerator()) {
        $key = [string]$entry.Key
        if ($key -match "^$([regex]::Escape($BaseName))\[(\d+)\]$" -and
            -not $script:wasmConflictedAccessObjectClassHints.ContainsKey($key)) {
            $idx = [string][int]$Matches[1]
            if (-not $out.ContainsKey($idx)) { $out[$idx] = New-WasmAstFixedIndexedHint }
            $out[$idx].ObjectClassName = [string]$entry.Value
        }
    }
    return $out
}

function Get-WasmAstFixedStringKeyAccessHintsByBase {
    param([string]$BaseName, [hashtable]$LocalKeyedHints = @{})

    $out = @{}
    if ([string]::IsNullOrWhiteSpace($BaseName)) { return $out }
    if ($LocalKeyedHints.ContainsKey($BaseName)) {
        foreach ($entry in $LocalKeyedHints[$BaseName].GetEnumerator()) {
            $key = [string]$entry.Key
            if ($key -match '^[A-Za-z_][A-Za-z0-9_]*$') {
                $hint = $entry.Value
                $out[$key] = New-WasmAstFixedIndexedHint ([string]$hint.TypeName) ([string]$hint.FunctionDisplayName) ([string]$hint.ObjectClassName)
            }
        }
        return $out
    }
    if ($script:wasmCurrentLocalIndexedAccessHints.ContainsKey($BaseName)) {
        foreach ($entry in $script:wasmCurrentLocalIndexedAccessHints[$BaseName].GetEnumerator()) {
            $key = [string]$entry.Key
            if ($key -match '^[A-Za-z_][A-Za-z0-9_]*$') {
                $hint = $entry.Value
                $out[$key] = New-WasmAstFixedIndexedHint ([string]$hint.TypeName) ([string]$hint.FunctionDisplayName) ([string]$hint.ObjectClassName)
            }
        }
        return $out
    }
    foreach ($entry in $script:wasmAccessTypeHints.GetEnumerator()) {
        $key = [string]$entry.Key
        if ($key -match "^$([regex]::Escape($BaseName))\.([A-Za-z_][A-Za-z0-9_]*)$" -and
            -not $script:wasmConflictedAccessTypeHints.ContainsKey($key)) {
            $out[[string]$Matches[1]] = New-WasmAstFixedIndexedHint ([string]$entry.Value) "" ""
        }
    }
    foreach ($entry in $script:wasmAccessFunctionDisplayHints.GetEnumerator()) {
        $key = [string]$entry.Key
        if ($key -match "^$([regex]::Escape($BaseName))\.([A-Za-z_][A-Za-z0-9_]*)$" -and
            -not $script:wasmConflictedAccessFunctionDisplayHints.ContainsKey($key)) {
            $field = [string]$Matches[1]
            if (-not $out.ContainsKey($field)) { $out[$field] = New-WasmAstFixedIndexedHint }
            $out[$field].FunctionDisplayName = [string]$entry.Value
        }
    }
    foreach ($entry in $script:wasmAccessObjectClassHints.GetEnumerator()) {
        $key = [string]$entry.Key
        if ($key -match "^$([regex]::Escape($BaseName))\.([A-Za-z_][A-Za-z0-9_]*)$" -and
            -not $script:wasmConflictedAccessObjectClassHints.ContainsKey($key)) {
            $field = [string]$Matches[1]
            if (-not $out.ContainsKey($field)) { $out[$field] = New-WasmAstFixedIndexedHint }
            $out[$field].ObjectClassName = [string]$entry.Value
        }
    }
    return $out
}

function Get-WasmAstFixedIndexedAccessHintsForExpr {
    param($Node, [hashtable]$LocalIndexedHints = @{}, [hashtable]$SeenFunctions = @{})

    $out = @{}
    if ($null -eq $Node) { return $out }
    switch ([string]$Node.node) {
        "ARRAY_LIT" {
            $index = 0
            foreach ($element in @(As-WasmAstArray ($Node.elements))) {
                $elementType = Get-WasmAstStaticValueTypeWithParams $element @{}
                $functionDisplay = if ($elementType -eq "function") { Get-WasmAstKnownFunctionDisplayName $element } else { "" }
                $elementClass = Get-WasmAstObjectClassTypeHint $element
                if ($elementType -in @("string", "bool", "nil", "num", "array", "dict", "function") -or
                    -not [string]::IsNullOrWhiteSpace($elementClass)) {
                    $out[[string]$index] = New-WasmAstFixedIndexedHint $elementType $functionDisplay $elementClass
                }
                $index++
            }
            return $out
        }
        "IDENT" {
            $name = [string]$Node.name
            return (Get-WasmAstFixedIndexedAccessHintsByBase $name $LocalIndexedHints)
        }
        { $_ -in @("DOT_ACCESS", "INDEX") } {
            $accessName = Get-WasmAstAccessPathName $Node
            return (Get-WasmAstFixedIndexedAccessHintsByBase $accessName $LocalIndexedHints)
        }
        "TERNARY" {
            $condState = Get-WasmAstKnownBoolLiteralState ($Node.cond)
            if ($condState -eq "true") {
                return (Get-WasmAstFixedIndexedAccessHintsForExpr ($Node.then) $LocalIndexedHints $SeenFunctions)
            }
            if ($condState -eq "false") {
                return (Get-WasmAstFixedIndexedAccessHintsForExpr ($Node.else) $LocalIndexedHints $SeenFunctions)
            }
            $thenHints = Get-WasmAstFixedIndexedAccessHintsForExpr ($Node.then) $LocalIndexedHints $SeenFunctions
            $elseHints = Get-WasmAstFixedIndexedAccessHintsForExpr ($Node.else) $LocalIndexedHints $SeenFunctions
            return (Merge-WasmAstFixedIndexedHintMaps $thenHints $elseHints)
        }
        "BIN_OP" {
            if ([string]$Node.op -eq "+") {
                $leftHints = Get-WasmAstFixedIndexedAccessHintsForExpr ($Node.left) $LocalIndexedHints $SeenFunctions
                $rightHints = Get-WasmAstFixedIndexedAccessHintsForExpr ($Node.right) $LocalIndexedHints $SeenFunctions
                $leftCount = if ([string]$Node.left.node -eq "ARRAY_LIT") {
                    @(As-WasmAstArray ($Node.left.elements)).Count
                } elseif (Test-WasmAstKnownEmptyArrayExpr ($Node.left)) {
                    0
                } else {
                    Get-WasmAstContiguousFixedIndexedHintCount $leftHints
                }
                $rightCount = if ([string]$Node.right.node -eq "ARRAY_LIT") {
                    @(As-WasmAstArray ($Node.right.elements)).Count
                } elseif (Test-WasmAstKnownEmptyArrayExpr ($Node.right)) {
                    0
                } else {
                    Get-WasmAstContiguousFixedIndexedHintCount $rightHints
                }
                if ($leftCount -lt 0 -or $rightCount -lt 0) { return $out }
                foreach ($entry in $leftHints.GetEnumerator()) {
                    $hint = $entry.Value
                    $out[[string]$entry.Key] = New-WasmAstFixedIndexedHint ([string]$hint.TypeName) ([string]$hint.FunctionDisplayName) ([string]$hint.ObjectClassName)
                }
                foreach ($entry in $rightHints.GetEnumerator()) {
                    $hint = $entry.Value
                    $shifted = $leftCount + [int][string]$entry.Key
                    $out[[string]$shifted] = New-WasmAstFixedIndexedHint ([string]$hint.TypeName) ([string]$hint.FunctionDisplayName) ([string]$hint.ObjectClassName)
                }
                return $out
            }
            if ([string]$Node.op -ne "??") { return $out }
            $leftHints = Get-WasmAstFixedIndexedAccessHintsForExpr ($Node.left) $LocalIndexedHints $SeenFunctions
            $rightHints = Get-WasmAstFixedIndexedAccessHintsForExpr ($Node.right) $LocalIndexedHints $SeenFunctions
            if (-not (Test-WasmAstFixedIndexedHintMapHasItems $leftHints)) { return $rightHints }
            if (-not (Test-WasmAstFixedIndexedHintMapHasItems $rightHints)) { return $leftHints }
            return (Merge-WasmAstFixedIndexedHintMaps $leftHints $rightHints)
        }
        "CALL" {
            $name = [string]$Node.name
            $rangeSnapshot = Get-WasmAstPureArrayRangeCaptureResult $name ([object[]]@(As-WasmAstArray ($Node.args))) @{} $Node
            if ($null -ne $rangeSnapshot) {
                return (New-WasmAstFixedNumericIndexedHintsFromCaptureArray $rangeSnapshot)
            }
            if ([string]::IsNullOrWhiteSpace($name) -or -not $script:wasmAstFunctionDefs.ContainsKey($name) -or $SeenFunctions.ContainsKey($name)) {
                return $out
            }
            $SeenFunctions[$name] = $true
            try {
                $resolvedReturn = Resolve-WasmAstFunctionCallReturnExpr $Node
                if ($null -ne $resolvedReturn) {
                    $resolvedHints = Get-WasmAstFixedIndexedAccessHintsForExpr $resolvedReturn $LocalIndexedHints $SeenFunctions
                    if (Test-WasmAstFixedIndexedHintMapHasItems $resolvedHints) { return $resolvedHints }
                }
                $fn = $script:wasmAstFunctionDefs[$name]
                $callParamTypes = Copy-WasmAstTypeHints (Get-WasmAstObservedFunctionParamTypeHints $name)
                $callParams = @([string[]]$fn.Params)
                $callArgs = @(As-WasmAstArray ($Node.args))
                $scopeTypes = Get-WasmAstCurrentValueTypeScopeHints
                for ($i = 0; $i -lt $callParams.Count -and $i -lt $callArgs.Count; $i++) {
                    $argType = Get-WasmAstStaticValueTypeWithParams ($callArgs[$i]) $scopeTypes
                    if ($argType -in @("string", "bool", "nil", "num", "array", "dict", "function")) {
                        $callParamTypes[[string]$callParams[$i]] = $argType
                    }
                }
                return (Get-WasmAstReturnFixedIndexedAccessHintsFromBody ($fn.Node.body) $SeenFunctions $callParamTypes)
            } finally {
                $SeenFunctions.Remove($name)
            }
        }
        "METHOD_CALL" {
            if ($null -ne $Node.obj -and [string]$Node.obj.node -eq "IDENT" -and [string]$Node.obj.name -eq "array") {
                $rangeSnapshot = Get-WasmAstPureArrayRangeCaptureResult "array.$([string]$Node.method)" ([object[]]@(As-WasmAstArray ($Node.args))) @{} $Node
                if ($null -ne $rangeSnapshot) {
                    return (New-WasmAstFixedNumericIndexedHintsFromCaptureArray $rangeSnapshot)
                }
            }
            $resolvedReturn = Resolve-WasmAstMethodCallReturnExpr $Node
            if ($null -ne $resolvedReturn) {
                $resolvedHints = Get-WasmAstFixedIndexedAccessHintsForExpr $resolvedReturn $LocalIndexedHints $SeenFunctions
                if (Test-WasmAstFixedIndexedHintMapHasItems $resolvedHints) { return $resolvedHints }
            }
            $objName = Get-WasmAstAccessPathName ($Node.obj)
            if ([string]::IsNullOrWhiteSpace($objName)) { return $out }
            $className = Get-WasmAstObjectClassTypeWithLocals ($Node.obj) $script:wasmCurrentLocalObjectClassHints $script:wasmCurrentClassContext @{}
            if ([string]::IsNullOrWhiteSpace($className)) { return $out }
            $methodInfo = Get-WasmAstClassMethod -ClassName $className -MethodName ([string]$Node.method)
            if ($null -eq $methodInfo) { return $out }
            return (Get-WasmAstReturnFixedIndexedAccessHintsFromBodyForObject ($methodInfo.Method.body) $objName $SeenFunctions)
        }
        default { return $out }
    }
}

function Get-WasmAstExactIndexedAccessHint {
    param($Node)

    if ($null -eq $Node -or [string]$Node.node -ne "INDEX" -or
        $null -eq $Node.obj -or $null -eq $Node.key) {
        return $null
    }

    $literalIndex = Get-WasmAstKnownNumericLiteralValue ($Node.key)
    if ($null -eq $literalIndex) { return $null }

    $indexValue = [int][Math]::Truncate([double]$literalIndex)
    $hints = Get-WasmAstFixedIndexedAccessHintsForExpr ($Node.obj) $script:wasmCurrentLocalIndexedAccessHints
    $key = [string]$indexValue
    if ($null -ne $hints -and $hints.ContainsKey($key)) {
        return [pscustomobject]@{
            Index = $indexValue
            Hint = $hints[$key]
        }
    }
    return $null
}

function Get-WasmAstFixedStringKeyAccessHintsForExpr {
    param($Node, [hashtable]$LocalKeyedHints = @{}, [hashtable]$SeenFunctions = @{})

    $out = @{}
    if ($null -eq $Node) { return $out }
    switch ([string]$Node.node) {
        "DICT_LIT" {
            foreach ($entry in @(As-WasmAstArray ($Node.entries))) {
                $key = [string]$entry.key
                if ([string]::IsNullOrWhiteSpace($key)) { continue }
                $valueType = Get-WasmAstStaticValueTypeWithParams ($entry.value) @{}
                $functionDisplay = if ($valueType -eq "function") { Get-WasmAstKnownFunctionDisplayName ($entry.value) } else { "" }
                $valueClass = Get-WasmAstObjectClassTypeHint ($entry.value)
                if ($valueType -in @("string", "bool", "nil", "num", "array", "dict", "function") -or
                    -not [string]::IsNullOrWhiteSpace($valueClass)) {
                    $out[$key] = New-WasmAstFixedIndexedHint $valueType $functionDisplay $valueClass
                }
            }
            return $out
        }
        "IDENT" {
            $name = [string]$Node.name
            return (Get-WasmAstFixedStringKeyAccessHintsByBase $name $LocalKeyedHints)
        }
        { $_ -in @("DOT_ACCESS", "INDEX") } {
            $accessName = Get-WasmAstAccessPathName $Node
            return (Get-WasmAstFixedStringKeyAccessHintsByBase $accessName $LocalKeyedHints)
        }
        "TERNARY" {
            $condState = Get-WasmAstKnownBoolLiteralState ($Node.cond)
            if ($condState -eq "true") {
                return (Get-WasmAstFixedStringKeyAccessHintsForExpr ($Node.then) $LocalKeyedHints $SeenFunctions)
            }
            if ($condState -eq "false") {
                return (Get-WasmAstFixedStringKeyAccessHintsForExpr ($Node.else) $LocalKeyedHints $SeenFunctions)
            }
            $thenHints = Get-WasmAstFixedStringKeyAccessHintsForExpr ($Node.then) $LocalKeyedHints $SeenFunctions
            $elseHints = Get-WasmAstFixedStringKeyAccessHintsForExpr ($Node.else) $LocalKeyedHints $SeenFunctions
            return (Merge-WasmAstFixedIndexedHintMaps $thenHints $elseHints)
        }
        "BIN_OP" {
            if ([string]$Node.op -ne "??") { return $out }
            $leftHints = Get-WasmAstFixedStringKeyAccessHintsForExpr ($Node.left) $LocalKeyedHints $SeenFunctions
            $rightHints = Get-WasmAstFixedStringKeyAccessHintsForExpr ($Node.right) $LocalKeyedHints $SeenFunctions
            if (-not (Test-WasmAstFixedIndexedHintMapHasItems $leftHints)) { return $rightHints }
            if (-not (Test-WasmAstFixedIndexedHintMapHasItems $rightHints)) { return $leftHints }
            return (Merge-WasmAstFixedIndexedHintMaps $leftHints $rightHints)
        }
        "CALL" {
            $name = [string]$Node.name
            if ([string]::IsNullOrWhiteSpace($name) -or -not $script:wasmAstFunctionDefs.ContainsKey($name) -or $SeenFunctions.ContainsKey($name)) {
                return $out
            }
            $SeenFunctions[$name] = $true
            try {
                $resolvedReturn = Resolve-WasmAstFunctionCallReturnExpr $Node
                if ($null -ne $resolvedReturn) {
                    $resolvedHints = Get-WasmAstFixedStringKeyAccessHintsForExpr $resolvedReturn $LocalKeyedHints $SeenFunctions
                    if (Test-WasmAstFixedIndexedHintMapHasItems $resolvedHints) { return $resolvedHints }
                }
                $fn = $script:wasmAstFunctionDefs[$name]
                $callParamTypes = Copy-WasmAstTypeHints (Get-WasmAstObservedFunctionParamTypeHints $name)
                $callParams = @([string[]]$fn.Params)
                $callArgs = @(As-WasmAstArray ($Node.args))
                $scopeTypes = Get-WasmAstCurrentValueTypeScopeHints
                for ($i = 0; $i -lt $callParams.Count -and $i -lt $callArgs.Count; $i++) {
                    $argType = Get-WasmAstStaticValueTypeWithParams ($callArgs[$i]) $scopeTypes
                    if ($argType -in @("string", "bool", "nil", "num", "array", "dict", "function")) {
                        $callParamTypes[[string]$callParams[$i]] = $argType
                    }
                }
                return (Get-WasmAstReturnFixedStringKeyAccessHintsFromBody ($fn.Node.body) $SeenFunctions $callParamTypes)
            } finally {
                $SeenFunctions.Remove($name)
            }
        }
        "METHOD_CALL" {
            $resolvedReturn = Resolve-WasmAstMethodCallReturnExpr $Node
            if ($null -ne $resolvedReturn) {
                $resolvedHints = Get-WasmAstFixedStringKeyAccessHintsForExpr $resolvedReturn $LocalKeyedHints $SeenFunctions
                if (Test-WasmAstFixedIndexedHintMapHasItems $resolvedHints) { return $resolvedHints }
            }
            $objName = Get-WasmAstAccessPathName ($Node.obj)
            if ([string]::IsNullOrWhiteSpace($objName)) { return $out }
            $className = Get-WasmAstObjectClassTypeWithLocals ($Node.obj) $script:wasmCurrentLocalObjectClassHints $script:wasmCurrentClassContext @{}
            if ([string]::IsNullOrWhiteSpace($className)) { return $out }
            $methodInfo = Get-WasmAstClassMethod -ClassName $className -MethodName ([string]$Node.method)
            if ($null -eq $methodInfo) { return $out }
            $methodParamTypes = Copy-WasmAstTypeHints (Get-WasmAstObservedFunctionParamTypeHints ([string]$methodInfo.FunctionName))
            $methodParams = @(Get-WasmAstParamNames ($methodInfo.Method.params))
            $methodArgs = @(As-WasmAstArray ($Node.args))
            $scopeTypes = Get-WasmAstCurrentValueTypeScopeHints
            for ($i = 0; $i -lt $methodParams.Count -and $i -lt $methodArgs.Count; $i++) {
                $argType = Get-WasmAstStaticValueTypeWithParams ($methodArgs[$i]) $scopeTypes
                if ($argType -in @("string", "bool", "nil", "num", "array", "dict", "function")) {
                    $methodParamTypes[[string]$methodParams[$i]] = $argType
                }
            }
            return (Get-WasmAstReturnFixedStringKeyAccessHintsFromBody ($methodInfo.Method.body) $SeenFunctions $methodParamTypes)
        }
        default { return $out }
    }
}

function Get-WasmAstExactStringKeyAccessHint {
    param($Node)

    if ($null -eq $Node -or $null -eq $Node.obj) {
        return $null
    }

    $keyName = ""
    switch ([string]$Node.node) {
        "DOT_ACCESS" { $keyName = [string]$Node.prop }
        "INDEX" {
            if ($null -eq $Node.key) { return $null }
            $keyName = Get-WasmAstKnownStringLiteralValue ($Node.key)
        }
        default { return $null }
    }
    if ([string]::IsNullOrWhiteSpace($keyName)) { return $null }

    $hints = Get-WasmAstFixedStringKeyAccessHintsForExpr ($Node.obj) $script:wasmCurrentLocalIndexedAccessHints
    if ($null -ne $hints -and $hints.ContainsKey($keyName)) {
        return [pscustomobject]@{
            Key = $keyName
            Hint = $hints[$keyName]
        }
    }
    return $null
}

function Get-WasmAstShapeAnalysisArgumentExpr {
    param($Node, [hashtable]$LocalTypes = @{})

    if ($null -eq $Node -or [string]$Node.node -ne "IDENT" -or
        -not $LocalTypes.ContainsKey([string]$Node.name)) {
        return $Node
    }

    switch ([string]$LocalTypes[[string]$Node.name]) {
        "num" { return (New-WasmAstCaptureNumLit 0 $Node) }
        "string" { return (New-WasmAstCaptureStrLit "" $Node) }
        "bool" { return (New-WasmAstCaptureBoolLit $false $Node) }
        "nil" {
            return [pscustomobject]@{
                node = "NIL_LIT"
                line = $(if ($Node.PSObject.Properties.Name -contains "line") { $Node.line } else { 0 })
            }
        }
        "array" {
            return [pscustomobject]@{
                node = "ARRAY_LIT"
                line = $(if ($Node.PSObject.Properties.Name -contains "line") { $Node.line } else { 0 })
                elements = @()
            }
        }
        "dict" {
            return [pscustomobject]@{
                node = "DICT_LIT"
                line = $(if ($Node.PSObject.Properties.Name -contains "line") { $Node.line } else { 0 })
                entries = @()
            }
        }
        default { return $Node }
    }
}

function Get-WasmAstShapeAnalysisCallArgs {
    param($InputArgs, [hashtable]$LocalTypes = @{})

    $out = New-Object System.Collections.Generic.List[object]
    foreach ($arg in @(As-WasmAstArray $InputArgs)) {
        $out.Add((Get-WasmAstShapeAnalysisArgumentExpr $arg $LocalTypes)) | Out-Null
    }
    return @($out.ToArray())
}

function Get-WasmAstReturnFixedIndexedAccessHintsFromBody {
    param($Body, [hashtable]$SeenFunctions = @{}, [hashtable]$LocalTypes = @{})

    $empty = @{}
    if ($null -eq $Body) { return $empty }
    $localIndexedHints = @{}
    $localValueTypes = Copy-WasmAstTypeHints $LocalTypes
    $localFunctionLiftCandidates = @{}
    $localDictFunctionLiftCandidates = @{}
    $localArrayFunctionLiftCandidates = @{}
    foreach ($stmt in @(As-WasmAstArray ($Body.body))) {
        if ($null -eq $stmt) { continue }
        switch ([string]$stmt.node) {
            "ASSIGN" {
                $hints = Get-WasmAstFixedIndexedAccessHintsForExpr ($stmt.value) $localIndexedHints $SeenFunctions
                if (Test-WasmAstFixedIndexedHintMapHasItems $hints) {
                    $localIndexedHints[[string]$stmt.name] = $hints
                } elseif ($localIndexedHints.ContainsKey([string]$stmt.name)) {
                    $localIndexedHints.Remove([string]$stmt.name)
                }
                $valueType = Get-WasmAstStaticValueTypeWithParams ($stmt.value) $localValueTypes
                if ($null -ne $stmt.value -and [string]$stmt.value.node -eq "INDEX" -and
                    $null -ne $stmt.value.obj -and [string]$stmt.value.obj.node -eq "IDENT") {
                    $containerName = [string]$stmt.value.obj.name
                    $keyType = Get-WasmAstStaticValueTypeWithParams ($stmt.value.key) $localValueTypes
                    if ($localDictFunctionLiftCandidates.ContainsKey($containerName) -and $keyType -eq "string") {
                        $valueType = "function"
                    } elseif ($localArrayFunctionLiftCandidates.ContainsKey($containerName) -and $keyType -ne "string") {
                        $valueType = "function"
                    }
                }
                if ($valueType -in @("string", "bool", "nil", "num", "array", "dict", "function")) {
                    $localValueTypes[[string]$stmt.name] = $valueType
                } elseif ($localValueTypes.ContainsKey([string]$stmt.name)) {
                    $localValueTypes.Remove([string]$stmt.name)
                }
                $functionCandidates = @(Get-WasmAstFunctionValueLiftCandidatesFromExpr ($stmt.value) "" $localValueTypes @{} $localFunctionLiftCandidates $localDictFunctionLiftCandidates $localArrayFunctionLiftCandidates)
                if ($functionCandidates.Count -gt 0) {
                    $localFunctionLiftCandidates[[string]$stmt.name] = [string[]]$functionCandidates
                } elseif ($localFunctionLiftCandidates.ContainsKey([string]$stmt.name)) {
                    $localFunctionLiftCandidates.Remove([string]$stmt.name)
                }
                if ($valueType -eq "dict") {
                    $dictFunctionCandidates = @(Get-WasmAstDictLiteralFunctionLiftCandidates ($stmt.value) "" $localValueTypes @{} $localFunctionLiftCandidates $localDictFunctionLiftCandidates $localArrayFunctionLiftCandidates)
                    if ($dictFunctionCandidates.Count -gt 0) {
                        $localDictFunctionLiftCandidates[[string]$stmt.name] = [string[]]$dictFunctionCandidates
                    } elseif ($localDictFunctionLiftCandidates.ContainsKey([string]$stmt.name)) {
                        $localDictFunctionLiftCandidates.Remove([string]$stmt.name)
                    }
                } elseif ($localDictFunctionLiftCandidates.ContainsKey([string]$stmt.name)) {
                    $localDictFunctionLiftCandidates.Remove([string]$stmt.name)
                }
                if ($valueType -eq "array") {
                    $arrayFunctionCandidates = @(Get-WasmAstArrayLiteralFunctionLiftCandidates ($stmt.value) "" $localValueTypes @{} $localFunctionLiftCandidates $localDictFunctionLiftCandidates $localArrayFunctionLiftCandidates)
                    if ($arrayFunctionCandidates.Count -gt 0) {
                        $localArrayFunctionLiftCandidates[[string]$stmt.name] = [string[]]$arrayFunctionCandidates
                    } elseif ($localArrayFunctionLiftCandidates.ContainsKey([string]$stmt.name)) {
                        $localArrayFunctionLiftCandidates.Remove([string]$stmt.name)
                    }
                } elseif ($localArrayFunctionLiftCandidates.ContainsKey([string]$stmt.name)) {
                    $localArrayFunctionLiftCandidates.Remove([string]$stmt.name)
                }
            }
            "RETURN" {
                if ($null -ne $stmt.value -and [string]$stmt.value.node -eq "CALL" -and
                    $localFunctionLiftCandidates.ContainsKey([string]$stmt.value.name)) {
                    $mergedHints = $null
                    foreach ($candidate in @($localFunctionLiftCandidates[[string]$stmt.value.name])) {
                        $liftName = [string]$candidate
                        if ([string]::IsNullOrWhiteSpace($liftName) -or -not $script:wasmAstFunctionDefs.ContainsKey($liftName)) { return $empty }
                        $fakeCall = [pscustomobject]@{
                            node = "CALL"
                            name = $liftName
                            args = @(Get-WasmAstShapeAnalysisCallArgs ($stmt.value.args) $localValueTypes)
                        }
                        $candidateHints = Get-WasmAstFixedIndexedAccessHintsForExpr $fakeCall $localIndexedHints $SeenFunctions
                        if (-not (Test-WasmAstFixedIndexedHintMapHasItems $candidateHints)) { return $empty }
                        if ($null -eq $mergedHints) {
                            $mergedHints = Copy-WasmAstFixedIndexedHintMap $candidateHints
                        } else {
                            $mergedHints = Merge-WasmAstFixedIndexedHintMaps $mergedHints $candidateHints
                        }
                    }
                    if (Test-WasmAstFixedIndexedHintMapHasItems $mergedHints) { return $mergedHints }
                }
                return (Get-WasmAstFixedIndexedAccessHintsForExpr ($stmt.value) $localIndexedHints $SeenFunctions)
            }
            "SuraBlock" {
                $nested = Get-WasmAstReturnFixedIndexedAccessHintsFromBody $stmt $SeenFunctions $localValueTypes
                if (Test-WasmAstFixedIndexedHintMapHasItems $nested) { return $nested }
            }
            "IF" {
                $thenHints = Get-WasmAstReturnFixedIndexedAccessHintsFromBody ($stmt.then_block) $SeenFunctions $localValueTypes
                $elseHints = Get-WasmAstReturnFixedIndexedAccessHintsFromBody ($stmt.else_block) $SeenFunctions $localValueTypes
                $merged = Merge-WasmAstFixedIndexedHintMaps $thenHints $elseHints
                if (Test-WasmAstFixedIndexedHintMapHasItems $merged) { return $merged }
            }
            default { }
        }
    }
    return $empty
}

function Get-WasmAstReturnFixedStringKeyAccessHintsFromBody {
    param($Body, [hashtable]$SeenFunctions = @{}, [hashtable]$LocalTypes = @{})

    $empty = @{}
    if ($null -eq $Body) { return $empty }
    $localKeyedHints = @{}
    $localValueTypes = Copy-WasmAstTypeHints $LocalTypes
    $localFunctionLiftCandidates = @{}
    $localDictFunctionLiftCandidates = @{}
    $localArrayFunctionLiftCandidates = @{}
    foreach ($stmt in @(As-WasmAstArray ($Body.body))) {
        if ($null -eq $stmt) { continue }
        switch ([string]$stmt.node) {
            "ASSIGN" {
                $hints = Get-WasmAstFixedStringKeyAccessHintsForExpr ($stmt.value) $localKeyedHints $SeenFunctions
                if (Test-WasmAstFixedIndexedHintMapHasItems $hints) {
                    $localKeyedHints[[string]$stmt.name] = $hints
                } elseif ($localKeyedHints.ContainsKey([string]$stmt.name)) {
                    $localKeyedHints.Remove([string]$stmt.name)
                }
                $valueType = Get-WasmAstStaticValueTypeWithParams ($stmt.value) $localValueTypes
                if ($null -ne $stmt.value -and [string]$stmt.value.node -eq "INDEX" -and
                    $null -ne $stmt.value.obj -and [string]$stmt.value.obj.node -eq "IDENT") {
                    $containerName = [string]$stmt.value.obj.name
                    $keyType = Get-WasmAstStaticValueTypeWithParams ($stmt.value.key) $localValueTypes
                    if ($localDictFunctionLiftCandidates.ContainsKey($containerName) -and $keyType -eq "string") {
                        $valueType = "function"
                    } elseif ($localArrayFunctionLiftCandidates.ContainsKey($containerName) -and $keyType -ne "string") {
                        $valueType = "function"
                    }
                }
                if ($valueType -in @("string", "bool", "nil", "num", "array", "dict", "function")) {
                    $localValueTypes[[string]$stmt.name] = $valueType
                } elseif ($localValueTypes.ContainsKey([string]$stmt.name)) {
                    $localValueTypes.Remove([string]$stmt.name)
                }
                $functionCandidates = @(Get-WasmAstFunctionValueLiftCandidatesFromExpr ($stmt.value) "" $localValueTypes @{} $localFunctionLiftCandidates $localDictFunctionLiftCandidates $localArrayFunctionLiftCandidates)
                if ($functionCandidates.Count -gt 0) {
                    $localFunctionLiftCandidates[[string]$stmt.name] = [string[]]$functionCandidates
                } elseif ($localFunctionLiftCandidates.ContainsKey([string]$stmt.name)) {
                    $localFunctionLiftCandidates.Remove([string]$stmt.name)
                }
                if ($valueType -eq "dict") {
                    $dictFunctionCandidates = @(Get-WasmAstDictLiteralFunctionLiftCandidates ($stmt.value) "" $localValueTypes @{} $localFunctionLiftCandidates $localDictFunctionLiftCandidates $localArrayFunctionLiftCandidates)
                    if ($dictFunctionCandidates.Count -gt 0) {
                        $localDictFunctionLiftCandidates[[string]$stmt.name] = [string[]]$dictFunctionCandidates
                    } elseif ($localDictFunctionLiftCandidates.ContainsKey([string]$stmt.name)) {
                        $localDictFunctionLiftCandidates.Remove([string]$stmt.name)
                    }
                } elseif ($localDictFunctionLiftCandidates.ContainsKey([string]$stmt.name)) {
                    $localDictFunctionLiftCandidates.Remove([string]$stmt.name)
                }
                if ($valueType -eq "array") {
                    $arrayFunctionCandidates = @(Get-WasmAstArrayLiteralFunctionLiftCandidates ($stmt.value) "" $localValueTypes @{} $localFunctionLiftCandidates $localDictFunctionLiftCandidates $localArrayFunctionLiftCandidates)
                    if ($arrayFunctionCandidates.Count -gt 0) {
                        $localArrayFunctionLiftCandidates[[string]$stmt.name] = [string[]]$arrayFunctionCandidates
                    } elseif ($localArrayFunctionLiftCandidates.ContainsKey([string]$stmt.name)) {
                        $localArrayFunctionLiftCandidates.Remove([string]$stmt.name)
                    }
                } elseif ($localArrayFunctionLiftCandidates.ContainsKey([string]$stmt.name)) {
                    $localArrayFunctionLiftCandidates.Remove([string]$stmt.name)
                }
            }
            "RETURN" {
                if ($null -ne $stmt.value -and [string]$stmt.value.node -eq "CALL" -and
                    $localFunctionLiftCandidates.ContainsKey([string]$stmt.value.name)) {
                    $mergedHints = $null
                    foreach ($candidate in @($localFunctionLiftCandidates[[string]$stmt.value.name])) {
                        $liftName = [string]$candidate
                        if ([string]::IsNullOrWhiteSpace($liftName) -or -not $script:wasmAstFunctionDefs.ContainsKey($liftName)) { return $empty }
                        $fakeCall = [pscustomobject]@{
                            node = "CALL"
                            name = $liftName
                            args = @(Get-WasmAstShapeAnalysisCallArgs ($stmt.value.args) $localValueTypes)
                        }
                        $candidateHints = Get-WasmAstFixedStringKeyAccessHintsForExpr $fakeCall $localKeyedHints $SeenFunctions
                        if (-not (Test-WasmAstFixedIndexedHintMapHasItems $candidateHints)) { return $empty }
                        if ($null -eq $mergedHints) {
                            $mergedHints = Copy-WasmAstFixedIndexedHintMap $candidateHints
                        } else {
                            $mergedHints = Merge-WasmAstFixedIndexedHintMaps $mergedHints $candidateHints
                        }
                    }
                    if (Test-WasmAstFixedIndexedHintMapHasItems $mergedHints) { return $mergedHints }
                }
                return (Get-WasmAstFixedStringKeyAccessHintsForExpr ($stmt.value) $localKeyedHints $SeenFunctions)
            }
            "SuraBlock" {
                $nested = Get-WasmAstReturnFixedStringKeyAccessHintsFromBody $stmt $SeenFunctions $localValueTypes
                if (Test-WasmAstFixedIndexedHintMapHasItems $nested) { return $nested }
            }
            "IF" {
                $thenHints = Get-WasmAstReturnFixedStringKeyAccessHintsFromBody ($stmt.then_block) $SeenFunctions $localValueTypes
                $elseHints = Get-WasmAstReturnFixedStringKeyAccessHintsFromBody ($stmt.else_block) $SeenFunctions $localValueTypes
                $merged = Merge-WasmAstFixedIndexedHintMaps $thenHints $elseHints
                if (Test-WasmAstFixedIndexedHintMapHasItems $merged) { return $merged }
            }
            default { }
        }
    }
    return $empty
}

function Get-WasmAstFixedIndexedAccessHintsForExprWithObjectSelf {
    param($Node, [string]$ObjectName, [hashtable]$LocalIndexedHints = @{}, [hashtable]$SeenFunctions = @{})

    if ($null -eq $Node) { return @{} }
    if (-not [string]::IsNullOrWhiteSpace($ObjectName) -and
        [string]$Node.node -eq "DOT_ACCESS" -and
        $null -ne $Node.obj -and [string]$Node.obj.node -eq "IDENT" -and [string]$Node.obj.name -eq "self") {
        return (Get-WasmAstFixedIndexedAccessHintsByBase "$ObjectName.$([string]$Node.prop)" $LocalIndexedHints)
    }
    if (-not [string]::IsNullOrWhiteSpace($ObjectName) -and
        [string]$Node.node -eq "INDEX" -and
        $null -ne $Node.obj -and [string]$Node.obj.node -eq "IDENT" -and [string]$Node.obj.name -eq "self" -and
        $null -ne $Node.key -and [string]$Node.key.node -eq "STR_LIT") {
        return (Get-WasmAstFixedIndexedAccessHintsByBase "$ObjectName.$([string]$Node.key.value)" $LocalIndexedHints)
    }
    if ([string]$Node.node -eq "TERNARY") {
        $condState = Get-WasmAstKnownBoolLiteralState ($Node.cond)
        if ($condState -eq "true") {
            return (Get-WasmAstFixedIndexedAccessHintsForExprWithObjectSelf ($Node.then) $ObjectName $LocalIndexedHints $SeenFunctions)
        }
        if ($condState -eq "false") {
            return (Get-WasmAstFixedIndexedAccessHintsForExprWithObjectSelf ($Node.else) $ObjectName $LocalIndexedHints $SeenFunctions)
        }
        $thenHints = Get-WasmAstFixedIndexedAccessHintsForExprWithObjectSelf ($Node.then) $ObjectName $LocalIndexedHints $SeenFunctions
        $elseHints = Get-WasmAstFixedIndexedAccessHintsForExprWithObjectSelf ($Node.else) $ObjectName $LocalIndexedHints $SeenFunctions
        return (Merge-WasmAstFixedIndexedHintMaps $thenHints $elseHints)
    }
    return (Get-WasmAstFixedIndexedAccessHintsForExpr $Node $LocalIndexedHints $SeenFunctions)
}

