function Get-WasmAstReturnOrderedDictEntryTypesFromBodyForObject {
    param($Body, [string]$ObjectName, [hashtable]$SeenFunctions = @{})

    if ($null -eq $Body) { return @() }
    $localOrderedEntries = @{}
    foreach ($stmt in @(As-WasmAstArray ($Body.body))) {
        if ($null -eq $stmt) { continue }
        switch ([string]$stmt.node) {
            "ASSIGN" {
                $name = [string]$stmt.name
                if ([string]::IsNullOrWhiteSpace($name)) { continue }
                $entries = @(Get-WasmAstOrderedDictEntryTypesForExprWithObjectSelf ($stmt.value) $ObjectName $localOrderedEntries $SeenFunctions)
                if ($entries.Count -gt 0) {
                    $localOrderedEntries[$name] = @(Copy-WasmAstOrderedDictEntryTypes $entries)
                } elseif ($localOrderedEntries.ContainsKey($name)) {
                    $localOrderedEntries.Remove($name)
                }
            }
            "RETURN" {
                return @(Get-WasmAstOrderedDictEntryTypesForExprWithObjectSelf ($stmt.value) $ObjectName $localOrderedEntries $SeenFunctions)
            }
            "SuraBlock" {
                $nested = @(Get-WasmAstReturnOrderedDictEntryTypesFromBodyForObject $stmt $ObjectName $SeenFunctions)
                if ($nested.Count -gt 0) { return $nested }
            }
            "IF" {
                $thenEntries = @(Get-WasmAstReturnOrderedDictEntryTypesFromBodyForObject ($stmt.then_block) $ObjectName $SeenFunctions)
                $elseEntries = @(Get-WasmAstReturnOrderedDictEntryTypesFromBodyForObject ($stmt.else_block) $ObjectName $SeenFunctions)
                $merged = @(Merge-WasmAstOrderedDictEntryTypes $thenEntries $elseEntries)
                if ($merged.Count -gt 0) { return $merged }
            }
            default { }
        }
    }
    return @()
}

function Get-WasmAstAccessObjectClassHint {
    param([string]$HintKey)

    if ([string]::IsNullOrWhiteSpace($HintKey) -or $script:wasmConflictedAccessObjectClassHints.ContainsKey($HintKey)) {
        return ""
    }
    if ($script:wasmAccessObjectClassHints.ContainsKey($HintKey)) {
        return [string]$script:wasmAccessObjectClassHints[$HintKey]
    }
    return ""
}

function Get-WasmAstCommonTypeName {
    param([string[]]$Types)

    $common = ""
    foreach ($typeName in @($Types)) {
        if ($typeName -notin @("string", "bool", "nil", "num", "array", "dict", "function")) { return "" }
        if ([string]::IsNullOrWhiteSpace($common)) {
            $common = $typeName
        } elseif ($common -ne $typeName) {
            return ""
        }
    }
    return $common
}

function Get-WasmAstValueTagForTypeName {
    param([string]$TypeName)

    switch ([string]$TypeName) {
        "nil" { 0 }
        "num" { 1 }
        "bool" { 2 }
        "string" { 3 }
        "array" { 4 }
        "dict" { 5 }
        "object" { 6 }
        "function" { 7 }
        default { -1 }
    }
}

function Get-WasmAstCommonObjectClassName {
    param([string[]]$ClassNames)

    $common = ""
    foreach ($className in @($ClassNames)) {
        if ([string]::IsNullOrWhiteSpace($className) -or -not $script:wasmClassDefs.ContainsKey($className)) {
            return ""
        }
        if ([string]::IsNullOrWhiteSpace($common)) {
            $common = $className
        } elseif ($common -ne $className) {
            return ""
        }
    }
    return $common
}

function Convert-WasmAstFixedIndexedHintMapToTypeList {
    param(
        [hashtable]$Map,
        [string[]]$AllowedTypes = @("string", "bool", "nil", "num", "array", "dict", "function")
    )

    if (-not (Test-WasmAstFixedIndexedHintMapHasItems $Map)) { return @() }
    $byIndex = @{}
    foreach ($entry in $Map.GetEnumerator()) {
        $index = 0
        if (-not [int]::TryParse([string]$entry.Key, [ref]$index) -or $index -lt 0) { return @() }
        $typeName = [string]$entry.Value.TypeName
        if ($typeName -notin $AllowedTypes) { return @() }
        $byIndex[$index] = $typeName
    }
    if ($byIndex.get_Count() -eq 0) { return @() }
    $maxIndex = ($byIndex.Keys | Measure-Object -Maximum).Maximum
    $types = New-Object System.Collections.Generic.List[string]
    for ($i = 0; $i -le [int]$maxIndex; $i++) {
        if (-not $byIndex.ContainsKey($i)) { return @() }
        $types.Add([string]$byIndex[$i]) | Out-Null
    }
    return @($types.ToArray())
}

function Get-WasmAstArrayElementTypeHint {
    param($Collection, [hashtable]$LocalIndexedHints = @{})

    if ($null -eq $Collection) { return "" }
    if ([string]$Collection.node -eq "BIN_OP" -and [string]$Collection.op -eq "+") {
        $leftType = Get-WasmAstArrayElementTypeHint ($Collection.left) $LocalIndexedHints
        $rightType = Get-WasmAstArrayElementTypeHint ($Collection.right) $LocalIndexedHints
        return (Get-WasmAstCommonTypeName @($leftType, $rightType))
    }
    if (Test-WasmAstDictKeysExpr $Collection) {
        return "string"
    }
    if ([string]$Collection.node -eq "CALL" -and [string]$Collection.name -in @("array.range", "array_range")) {
        return "num"
    }
    if ([string]$Collection.node -eq "METHOD_CALL" -and
        $null -ne $Collection.obj -and [string]$Collection.obj.node -eq "IDENT" -and
        [string]$Collection.obj.name -eq "array" -and [string]$Collection.method -eq "range") {
        return "num"
    }
    if ([string]$Collection.node -eq "CALL" -and [string]$Collection.name -in @("array.repeat", "array_repeat")) {
        $repeatArgs = @(As-WasmAstArray ($Collection.args))
        if ($repeatArgs.Count -ge 1) { return (Get-WasmAstStaticValueType ($repeatArgs[0])) }
    }
    if ([string]$Collection.node -eq "METHOD_CALL" -and
        $null -ne $Collection.obj -and [string]$Collection.obj.node -eq "IDENT" -and
        [string]$Collection.obj.name -eq "array" -and [string]$Collection.method -eq "repeat") {
        $repeatArgs = @(As-WasmAstArray ($Collection.args))
        if ($repeatArgs.Count -ge 1) { return (Get-WasmAstStaticValueType ($repeatArgs[0])) }
    }
    if ([string]$Collection.node -eq "CALL" -and [string]$Collection.name -in @("array.unique", "array_unique")) {
        $uniqueArgs = @(As-WasmAstArray ($Collection.args))
        if ($uniqueArgs.Count -ge 1) { return (Get-WasmAstArrayElementTypeHint ($uniqueArgs[0]) $LocalIndexedHints) }
    }
    if ([string]$Collection.node -eq "CALL" -and [string]$Collection.name -in @("array.flatten", "array_flatten")) {
        $flattenArgs = @(As-WasmAstArray ($Collection.args))
        if ($flattenArgs.Count -ge 1) { return (Get-WasmAstArrayNestedElementTypeHint ($flattenArgs[0]) $LocalIndexedHints) }
    }
    if ([string]$Collection.node -eq "CALL" -and [string]$Collection.name -in @("array.clone", "array.copy")) {
        $cloneArgs = @(As-WasmAstArray ($Collection.args))
        if ($cloneArgs.Count -ge 1) { return (Get-WasmAstArrayElementTypeHint ($cloneArgs[0]) $LocalIndexedHints) }
    }
    if ([string]$Collection.node -eq "CALL" -and [string]$Collection.name -eq "array.concat") {
        $concatTypes = New-Object System.Collections.Generic.List[string]
        foreach ($concatArg in @(As-WasmAstArray ($Collection.args))) {
            $concatTypes.Add((Get-WasmAstArrayElementTypeHint $concatArg $LocalIndexedHints)) | Out-Null
        }
        return (Get-WasmAstCommonTypeName ([string[]]$concatTypes.ToArray()))
    }
    if ([string]$Collection.node -eq "CALL" -and [string]$Collection.name -in @("array.chunk", "array.chunks", "array_chunk")) {
        return "array"
    }
    if ([string]$Collection.node -eq "CALL" -and [string]$Collection.name -in @("array.zip", "array_zip")) {
        return "array"
    }
    if ([string]$Collection.node -eq "METHOD_CALL" -and
        $null -ne $Collection.obj -and [string]$Collection.obj.node -eq "IDENT" -and
        [string]$Collection.obj.name -eq "array" -and [string]$Collection.method -eq "unique") {
        $uniqueArgs = @(As-WasmAstArray ($Collection.args))
        if ($uniqueArgs.Count -ge 1) { return (Get-WasmAstArrayElementTypeHint ($uniqueArgs[0]) $LocalIndexedHints) }
    }
    if ([string]$Collection.node -eq "METHOD_CALL" -and
        $null -ne $Collection.obj -and [string]$Collection.obj.node -eq "IDENT" -and
        [string]$Collection.obj.name -eq "array" -and [string]$Collection.method -eq "flatten") {
        $flattenArgs = @(As-WasmAstArray ($Collection.args))
        if ($flattenArgs.Count -ge 1) { return (Get-WasmAstArrayNestedElementTypeHint ($flattenArgs[0]) $LocalIndexedHints) }
    }
    if ([string]$Collection.node -eq "METHOD_CALL" -and
        $null -ne $Collection.obj -and [string]$Collection.obj.node -eq "IDENT" -and
        [string]$Collection.obj.name -eq "array" -and [string]$Collection.method -in @("clone", "copy")) {
        $cloneArgs = @(As-WasmAstArray ($Collection.args))
        if ($cloneArgs.Count -ge 1) { return (Get-WasmAstArrayElementTypeHint ($cloneArgs[0]) $LocalIndexedHints) }
    }
    if ([string]$Collection.node -eq "METHOD_CALL" -and
        $null -ne $Collection.obj -and [string]$Collection.obj.node -eq "IDENT" -and
        [string]$Collection.obj.name -eq "array" -and [string]$Collection.method -eq "concat") {
        $concatTypes = New-Object System.Collections.Generic.List[string]
        foreach ($concatArg in @(As-WasmAstArray ($Collection.args))) {
            $concatTypes.Add((Get-WasmAstArrayElementTypeHint $concatArg $LocalIndexedHints)) | Out-Null
        }
        return (Get-WasmAstCommonTypeName ([string[]]$concatTypes.ToArray()))
    }
    if ([string]$Collection.node -eq "METHOD_CALL" -and
        $null -ne $Collection.obj -and [string]$Collection.obj.node -eq "IDENT" -and
        [string]$Collection.obj.name -eq "array" -and [string]$Collection.method -in @("chunk", "chunks")) {
        return "array"
    }
    if ([string]$Collection.node -eq "METHOD_CALL" -and
        $null -ne $Collection.obj -and [string]$Collection.obj.node -eq "IDENT" -and
        [string]$Collection.obj.name -eq "array" -and [string]$Collection.method -eq "zip") {
        return "array"
    }
    if ([string]$Collection.node -eq "METHOD_CALL" -and [string]$Collection.method -eq "unique") {
        return (Get-WasmAstArrayElementTypeHint ($Collection.obj) $LocalIndexedHints)
    }
    if ([string]$Collection.node -eq "METHOD_CALL" -and [string]$Collection.method -eq "flatten") {
        return (Get-WasmAstArrayNestedElementTypeHint ($Collection.obj) $LocalIndexedHints)
    }
    if ([string]$Collection.node -eq "METHOD_CALL" -and [string]$Collection.method -eq "slice") {
        if ($null -ne $Collection.obj -and [string]$Collection.obj.node -eq "IDENT" -and [string]$Collection.obj.name -eq "array") {
            $sliceArgs = @(As-WasmAstArray ($Collection.args))
            if ($sliceArgs.Count -ge 1) { return (Get-WasmAstArrayElementTypeHint ($sliceArgs[0]) $LocalIndexedHints) }
        }
        return (Get-WasmAstArrayElementTypeHint ($Collection.obj) $LocalIndexedHints)
    }
    if ([string]$Collection.node -eq "METHOD_CALL" -and [string]$Collection.method -eq "reverse") {
        if ($null -ne $Collection.obj -and [string]$Collection.obj.node -eq "IDENT" -and [string]$Collection.obj.name -eq "array") {
            $reverseArgs = @(As-WasmAstArray ($Collection.args))
            if ($reverseArgs.Count -ge 1) { return (Get-WasmAstArrayElementTypeHint ($reverseArgs[0]) $LocalIndexedHints) }
        }
        return (Get-WasmAstArrayElementTypeHint ($Collection.obj) $LocalIndexedHints)
    }
    if ([string]$Collection.node -eq "METHOD_CALL" -and [string]$Collection.method -eq "sort") {
        if ($null -ne $Collection.obj -and [string]$Collection.obj.node -eq "IDENT" -and [string]$Collection.obj.name -eq "array") {
            $sortArgs = @(As-WasmAstArray ($Collection.args))
            if ($sortArgs.Count -ge 1) { return (Get-WasmAstArrayElementTypeHint ($sortArgs[0]) $LocalIndexedHints) }
        }
        return (Get-WasmAstArrayElementTypeHint ($Collection.obj) $LocalIndexedHints)
    }
    if ([string]$Collection.node -eq "ARRAY_LIT") {
        $types = New-Object System.Collections.Generic.List[string]
        foreach ($item in @(As-WasmAstArray ($Collection.elements))) {
            $types.Add((Get-WasmAstStaticValueType $item)) | Out-Null
        }
        return (Get-WasmAstCommonTypeName ([string[]]$types.ToArray()))
    }
    $fixedHints = Get-WasmAstFixedIndexedAccessHintsForExpr $Collection $LocalIndexedHints
    if (Test-WasmAstFixedIndexedHintMapHasItems $fixedHints) {
        $types = @(Convert-WasmAstFixedIndexedHintMapToTypeList $fixedHints)
        if ($types.Count -gt 0) {
            return (Get-WasmAstCommonTypeName ([string[]]$types))
        }
    }
    if ([string]$Collection.node -eq "IDENT") {
        $name = [string]$Collection.name
        if ([string]::IsNullOrWhiteSpace($name)) { return "" }
        $types = New-Object System.Collections.Generic.List[string]
        if ($script:wasmCurrentLocalIndexedAccessHints.ContainsKey($name)) {
            $localTypes = @(Convert-WasmAstFixedIndexedHintMapToTypeList $script:wasmCurrentLocalIndexedAccessHints[$name])
            if ($localTypes.Count -gt 0) {
                return (Get-WasmAstCommonTypeName ([string[]]$localTypes))
            }
        }
        $wildcardKey = "$name[*]"
        if ($script:wasmAccessTypeHints.ContainsKey($wildcardKey) -and
            -not $script:wasmConflictedAccessTypeHints.ContainsKey($wildcardKey)) {
            return [string]$script:wasmAccessTypeHints[$wildcardKey]
        }
        $prefix = "$name["
        foreach ($entry in $script:wasmAccessTypeHints.GetEnumerator()) {
            $key = [string]$entry.Key
            if ($key.StartsWith($prefix) -and $key.EndsWith("]") -and -not $script:wasmConflictedAccessTypeHints.ContainsKey($key)) {
                $types.Add([string]$entry.Value) | Out-Null
            }
        }
        return (Get-WasmAstCommonTypeName ([string[]]$types.ToArray()))
    }
    return ""
}

function Get-WasmAstArrayNestedElementTypeHint {
    param($Collection, [hashtable]$LocalIndexedHints = @{})

    if ($null -eq $Collection) { return "" }
    if ([string]$Collection.node -eq "CALL" -and [string]$Collection.name -in @("array.chunk", "array.chunks", "array_chunk")) {
        $chunkArgs = @(As-WasmAstArray ($Collection.args))
        if ($chunkArgs.Count -ge 1) { return (Get-WasmAstArrayElementTypeHint ($chunkArgs[0]) $LocalIndexedHints) }
    }
    if ([string]$Collection.node -eq "CALL" -and [string]$Collection.name -in @("array.zip", "array_zip")) {
        $zipTypes = New-Object System.Collections.Generic.List[string]
        foreach ($zipArg in @(As-WasmAstArray ($Collection.args))) {
            $zipTypes.Add((Get-WasmAstArrayElementTypeHint $zipArg $LocalIndexedHints)) | Out-Null
        }
        return (Get-WasmAstCommonTypeName ([string[]]$zipTypes.ToArray()))
    }
    if ([string]$Collection.node -eq "METHOD_CALL" -and
        $null -ne $Collection.obj -and [string]$Collection.obj.node -eq "IDENT" -and
        [string]$Collection.obj.name -eq "array" -and [string]$Collection.method -in @("chunk", "chunks")) {
        $chunkArgs = @(As-WasmAstArray ($Collection.args))
        if ($chunkArgs.Count -ge 1) { return (Get-WasmAstArrayElementTypeHint ($chunkArgs[0]) $LocalIndexedHints) }
    }
    if ([string]$Collection.node -eq "METHOD_CALL" -and
        $null -ne $Collection.obj -and [string]$Collection.obj.node -eq "IDENT" -and
        [string]$Collection.obj.name -eq "array" -and [string]$Collection.method -eq "zip") {
        $zipTypes = New-Object System.Collections.Generic.List[string]
        foreach ($zipArg in @(As-WasmAstArray ($Collection.args))) {
            $zipTypes.Add((Get-WasmAstArrayElementTypeHint $zipArg $LocalIndexedHints)) | Out-Null
        }
        return (Get-WasmAstCommonTypeName ([string[]]$zipTypes.ToArray()))
    }
    if ([string]$Collection.node -eq "ARRAY_LIT") {
        $types = New-Object System.Collections.Generic.List[string]
        foreach ($row in @(As-WasmAstArray ($Collection.elements))) {
            $types.Add((Get-WasmAstArrayElementTypeHint $row $LocalIndexedHints)) | Out-Null
        }
        return (Get-WasmAstCommonTypeName ([string[]]$types.ToArray()))
    }
    if ([string]$Collection.node -eq "IDENT") {
        $name = [string]$Collection.name
        if ([string]::IsNullOrWhiteSpace($name)) { return "" }
        $nestedWildcardKey = "$name[*][*]"
        if ($script:wasmAccessTypeHints.ContainsKey($nestedWildcardKey) -and
            -not $script:wasmConflictedAccessTypeHints.ContainsKey($nestedWildcardKey)) {
            return [string]$script:wasmAccessTypeHints[$nestedWildcardKey]
        }
    }
    return ""
}

function Get-WasmAstArrayElementObjectClassHint {
    param($Collection)

    if ($null -eq $Collection) { return "" }
    if ([string]$Collection.node -eq "ARRAY_LIT") {
        $classes = New-Object System.Collections.Generic.List[string]
        foreach ($item in @(As-WasmAstArray ($Collection.elements))) {
            $classes.Add((Get-WasmAstObjectClassTypeHint $item)) | Out-Null
        }
        return (Get-WasmAstCommonObjectClassName ([string[]]$classes.ToArray()))
    }
    if ([string]$Collection.node -eq "IDENT") {
        $name = [string]$Collection.name
        if ([string]::IsNullOrWhiteSpace($name)) { return "" }
        $prefix = "$name["
        foreach ($entry in $script:wasmConflictedAccessObjectClassHints.GetEnumerator()) {
            $key = [string]$entry.Key
            if ($key.StartsWith($prefix) -and $key.EndsWith("]")) { return "" }
        }
        foreach ($entry in $script:wasmAccessTypeHints.GetEnumerator()) {
            $key = [string]$entry.Key
            if ($key.StartsWith($prefix) -and $key.EndsWith("]") -and -not $script:wasmConflictedAccessTypeHints.ContainsKey($key)) {
                return ""
            }
        }
        $classes = New-Object System.Collections.Generic.List[string]
        foreach ($entry in $script:wasmAccessObjectClassHints.GetEnumerator()) {
            $key = [string]$entry.Key
            if ($key.StartsWith($prefix) -and $key.EndsWith("]") -and -not $script:wasmConflictedAccessObjectClassHints.ContainsKey($key)) {
                $classes.Add([string]$entry.Value) | Out-Null
            }
        }
        return (Get-WasmAstCommonObjectClassName ([string[]]$classes.ToArray()))
    }
    return ""
}

