}

function Get-WasmAstDictValueObjectClassHint {
    param($Collection)

    if ($null -eq $Collection) { return "" }
    if ([string]$Collection.node -eq "DICT_LIT") {
        $classes = New-Object System.Collections.Generic.List[string]
        foreach ($entry in @(As-WasmAstArray ($Collection.entries))) {
            $classes.Add((Get-WasmAstObjectClassTypeHint ($entry.value))) | Out-Null
        }
        return (Get-WasmAstCommonObjectClassName ([string[]]$classes.ToArray()))
    }
    if ([string]$Collection.node -eq "IDENT") {
        $name = [string]$Collection.name
        if ([string]::IsNullOrWhiteSpace($name)) { return "" }
        $prefix = "$name."
        foreach ($entry in $script:wasmConflictedAccessObjectClassHints.GetEnumerator()) {
            $key = [string]$entry.Key
            if ($key.StartsWith($prefix)) { return "" }
        }
        foreach ($entry in $script:wasmAccessTypeHints.GetEnumerator()) {
            $key = [string]$entry.Key
            if ($key.StartsWith($prefix) -and -not $script:wasmConflictedAccessTypeHints.ContainsKey($key)) {
                return ""
            }
        }
        $classes = New-Object System.Collections.Generic.List[string]
        foreach ($entry in $script:wasmAccessObjectClassHints.GetEnumerator()) {
            $key = [string]$entry.Key
            if ($key.StartsWith($prefix) -and -not $script:wasmConflictedAccessObjectClassHints.ContainsKey($key)) {
                $classes.Add([string]$entry.Value) | Out-Null
            }
        }
        return (Get-WasmAstCommonObjectClassName ([string[]]$classes.ToArray()))
    }
    return ""
}

function Get-WasmAstKnownValueType {
    param($Node)

    if ($null -eq $Node) { return "" }
    $nodeIdentity = [System.Runtime.CompilerServices.RuntimeHelpers]::GetHashCode($Node)
    $inferenceKey = "$nodeIdentity|$([string]$Node.node)|$([int]$Node.line)"
    if ($script:wasmKnownValueTypeInferenceStack.ContainsKey($inferenceKey)) {
        # Known-type and static-type inference intentionally consult each
        # other. Recursive call graphs can revisit the exact same AST node,
        # so stop that dependency at unknown instead of exhausting the
        # PowerShell call stack.
        return ""
    }
    if ($script:wasmKnownValueTypeInferenceDepth -ge $script:wasmKnownValueTypeInferenceMaxDepth) {
        # A long acyclic function/method graph can still exceed PowerShell's
        # call-depth limit even when no AST node repeats. Unknown is the safe
        # conservative result: lowering can keep the tagged Value path rather
        # than crashing the transpiler or emitting a partially analyzed main.
        return ""
    }
    $script:wasmKnownValueTypeInferenceStack[$inferenceKey] = $true
    $script:wasmKnownValueTypeInferenceDepth++
    try {
    if ([string]$Node.node -eq "DOT_ACCESS" -and [bool]$Node.optional -and $null -ne $Node.obj) {
        $receiverType = Get-WasmAstKnownValueType ($Node.obj)
        if ([string]::IsNullOrWhiteSpace($receiverType)) { $receiverType = Get-WasmAstStaticValueType ($Node.obj) }
        if ($receiverType -eq "nil") { return "nil" }
        if ($receiverType -eq "value") { return "value" }
    }
    if ([string]$Node.node -eq "METHOD_CALL") {
        if (Test-WasmAstJsonHasPathExpr $Node) { return "bool" }
        $dictPathType = Get-WasmAstDictGetPathStaticType $Node
        if (-not [string]::IsNullOrWhiteSpace($dictPathType)) { return $dictPathType }
        return (Get-WasmAstMethodCallTypeHint $Node (Get-WasmAstCurrentValueTypeScopeHints) $script:wasmCurrentClassContext $script:wasmCurrentLocalObjectClassHints)
    }
    if ([string]$Node.node -eq "SUPER_CALL") {
        return (Get-WasmAstSuperCallTypeHint $Node $script:wasmCurrentClassContext (Get-WasmAstCurrentValueTypeScopeHints) $script:wasmCurrentLocalObjectClassHints)
    }
    if ([string]$Node.node -eq "CALL") {
        if ([string]$Node.name -eq "type") { return "string" }
        if ([string]$Node.name -in @("length", "len", "string_len", "string_length", "string_size", "string.len", "string.length", "string.size")) { return "num" }
        if ([string]$Node.name -eq "to_str") { return "string" }
        if ([string]$Node.name -eq "to_bool") { return "bool" }
        if (Test-WasmAstJsonHasPathExpr $Node) { return "bool" }
        $dictPathType = Get-WasmAstDictGetPathStaticType $Node
        if (-not [string]::IsNullOrWhiteSpace($dictPathType)) { return $dictPathType }
        $arrayCallType = Get-WasmArrayCallReturnTypeName ([string]$Node.name)
        if (-not [string]::IsNullOrWhiteSpace($arrayCallType)) { return $arrayCallType }
        $dictCallType = Get-WasmDictCallReturnTypeName ([string]$Node.name)
        if (-not [string]::IsNullOrWhiteSpace($dictCallType)) { return $dictCallType }
        $stringCallType = Get-WasmStringCallReturnTypeName ([string]$Node.name)
        if (-not [string]::IsNullOrWhiteSpace($stringCallType) -and [string]$Node.name -ne "slice") { return $stringCallType }
        if ([string]$Node.name -in @("substring", "string.substring", "string_substring", "string.slice", "string.sub", "string_slice", "string_sub")) { return "string" }
        if ([string]$Node.name -eq "slice") {
            $sliceArgs = @(As-WasmAstArray ($Node.args))
            if ($sliceArgs.Count -ge 1) {
                $targetType = Get-WasmAstKnownValueType ($sliceArgs[0])
                if ([string]::IsNullOrWhiteSpace($targetType)) { $targetType = Get-WasmAstStaticValueType ($sliceArgs[0]) }
                if ($targetType -eq "string") { return "string" }
            }
        }
        if ([string]$Node.name -in @("indexOf", "string.indexOf", "string.index_of", "string_indexOf", "string_index_of")) { return "num" }
        if ([string]$Node.name -in @("contains", "startsWith", "endsWith", "string.contains", "string.startsWith", "string.endsWith", "string.starts_with", "string.ends_with", "string_contains", "string_startsWith", "string_starts_with", "string_endsWith", "string_ends_with")) { return "bool" }
        $functionValueReturnType = Get-WasmAstCurrentFunctionValueCallReturnTypeHint $Node (Get-WasmAstCurrentValueTypeScopeHints) $script:wasmCurrentLocalFunctionLiftCandidates
        if ($functionValueReturnType -in @("string", "bool", "nil", "num", "array", "dict", "function", "value")) {
            return $functionValueReturnType
        }
        $directFunctionValueLift = Get-WasmAstDirectFunctionValueCallLiftName $Node
        if (-not [string]::IsNullOrWhiteSpace($directFunctionValueLift)) {
            $directFunctionValueCall = [pscustomobject]@{
                node = "CALL"
                name = $directFunctionValueLift
                args = @(As-WasmAstArray ($Node.args))
            }
            $directFunctionValueType = Get-WasmAstFunctionCallTypeHint $directFunctionValueCall (Get-WasmAstCurrentValueTypeScopeHints)
            if ($directFunctionValueType -in @("string", "bool", "nil", "num", "array", "dict", "function", "value")) {
                return $directFunctionValueType
            }
        }
        return (Get-WasmAstFunctionCallTypeHint $Node)
    }
    if ([string]$Node.node -eq "IDENT") {
        $name = [string]$Node.name
        if ($script:wasmCurrentLocalValueTypeHints.ContainsKey($name)) { return [string]$script:wasmCurrentLocalValueTypeHints[$name] }
        if ($script:wasmCurrentFunctionParamTypeHints.ContainsKey($name)) { return [string]$script:wasmCurrentFunctionParamTypeHints[$name] }
        if (-not $script:wasmConflictedValueTypeHints.ContainsKey($name)) {
            if ($script:wasmValueTypeHints.ContainsKey($name)) { return [string]$script:wasmValueTypeHints[$name] }
            if ($script:wasmStringValueHints.ContainsKey($name)) { return "string" }
        }
        if ($script:wasmAstFunctionDefs.ContainsKey($name)) { return "function" }
        return ""
    }
    if ([string]$Node.node -eq "DOT_ACCESS" -and
        $null -ne $Node.obj -and [string]$Node.obj.node -eq "IDENT") {
        $enumKey = "$([string]$Node.obj.name).$([string]$Node.prop)"
        if ($script:wasmEnumStringConsts.ContainsKey($enumKey)) { return "string" }
        if ($script:wasmEnumConsts.ContainsKey($enumKey)) { return "num" }
    }
    $exactAccessTypeKey = ""
    $hasConflictedExactAccessType = $false
    if ([string]$Node.node -in @("DOT_ACCESS", "INDEX")) {
        $exactAccessTypeKey = Get-WasmAstStringAccessHintKey $Node
        $hasConflictedExactAccessType = (-not [string]::IsNullOrWhiteSpace($exactAccessTypeKey) -and
            $script:wasmConflictedAccessTypeHints.ContainsKey($exactAccessTypeKey))
    }
    if ($hasConflictedExactAccessType) {
        if ([string]$Node.node -eq "DOT_ACCESS" -and $null -ne $Node.obj) {
            $conflictedClassName = Get-WasmAstObjectClassTypeWithLocals ($Node.obj) $script:wasmCurrentLocalObjectClassHints $script:wasmCurrentClassContext @{}
            if ([string]$Node.obj.node -eq "IDENT" -and [string]$Node.obj.name -eq "self") {
                $conflictedClassName = $script:wasmCurrentClassContext
            }
            if (-not [string]::IsNullOrWhiteSpace($conflictedClassName) -and
                $script:wasmConflictedClassFieldTypeHints.ContainsKey("$conflictedClassName.$([string]$Node.prop)")) {
                return "value"
            }
        }
        if ([string]$Node.node -eq "INDEX" -and
            $null -ne $Node.obj -and [string]$Node.obj.node -eq "IDENT" -and $null -ne $Node.key) {
            $conflictedLiteralIndex = Get-WasmAstKnownNumericLiteralValue ($Node.key)
            if ($null -ne $conflictedLiteralIndex) {
                $conflictedLocalHint = Get-WasmAstCurrentLocalIndexedAccessHint ([string]$Node.obj.name) ([int][Math]::Truncate([double]$conflictedLiteralIndex))
                if ($null -ne $conflictedLocalHint -and
                    [string]$conflictedLocalHint.TypeName -in @("string", "bool", "nil", "num", "array", "dict", "function")) {
                    return [string]$conflictedLocalHint.TypeName
                }
            }
        }
        return ""
    }
    if ([string]$Node.node -eq "DOT_ACCESS" -and
        -not $hasConflictedExactAccessType -and
        $null -ne $Node.obj -and [string]$Node.obj.node -eq "IDENT" -and [string]$Node.obj.name -eq "self") {
        $selfType = Get-WasmAstCurrentSelfFieldTypeHint ([string]$Node.prop)
        if (-not [string]::IsNullOrWhiteSpace($selfType)) { return $selfType }
    }
    if ([string]$Node.node -eq "DOT_ACCESS" -and
        -not $hasConflictedExactAccessType -and
        $null -ne $Node.obj) {
        $className = Get-WasmAstObjectClassTypeWithLocals ($Node.obj) $script:wasmCurrentLocalObjectClassHints $script:wasmCurrentClassContext @{}
        if (-not [string]::IsNullOrWhiteSpace($className)) {
            $fieldType = Get-WasmAstClassFieldTypeHint $className ([string]$Node.prop)
            if (-not [string]::IsNullOrWhiteSpace($fieldType)) { return $fieldType }
            $observedType = Get-WasmAstObservedClassFieldTypeHint $className ([string]$Node.prop)
            if (-not [string]::IsNullOrWhiteSpace($observedType)) { return $observedType }
        }
    }
    if ([string]$Node.node -eq "DOT_ACCESS" -and
        $null -ne $Node.obj) {
        $exactStringKeyHint = Get-WasmAstExactStringKeyAccessHint $Node
        if ($null -ne $exactStringKeyHint -and
            [string]$exactStringKeyHint.Hint.TypeName -in @("string", "bool", "nil", "num", "array", "dict", "function")) {
            return [string]$exactStringKeyHint.Hint.TypeName
        }
    }
    if ([string]$Node.node -eq "INDEX" -and
        -not $hasConflictedExactAccessType -and
        $null -ne $Node.obj -and [string]$Node.obj.node -eq "IDENT" -and [string]$Node.obj.name -eq "self" -and
        $null -ne $Node.key -and [string]$Node.key.node -eq "STR_LIT") {
        $selfType = Get-WasmAstCurrentSelfFieldTypeHint ([string]$Node.key.value)
        if (-not [string]::IsNullOrWhiteSpace($selfType)) { return $selfType }
    }
    if ([string]$Node.node -eq "INDEX" -and
        -not $hasConflictedExactAccessType -and
        $null -ne $Node.obj -and $null -ne $Node.key -and [string]$Node.key.node -eq "STR_LIT") {
        $className = Get-WasmAstObjectClassTypeWithLocals ($Node.obj) $script:wasmCurrentLocalObjectClassHints $script:wasmCurrentClassContext @{}
        if (-not [string]::IsNullOrWhiteSpace($className)) {
            $fieldName = [string]$Node.key.value
            $fieldType = Get-WasmAstClassFieldTypeHint $className $fieldName
            if (-not [string]::IsNullOrWhiteSpace($fieldType)) { return $fieldType }
            $observedType = Get-WasmAstObservedClassFieldTypeHint $className $fieldName
            if (-not [string]::IsNullOrWhiteSpace($observedType)) { return $observedType }
        }
    }
    if ([string]$Node.node -eq "INDEX" -and
        $null -ne $Node.obj -and $null -ne $Node.key) {
        $exactIndexedHint = Get-WasmAstExactIndexedAccessHint $Node
        if ($null -ne $exactIndexedHint -and
            [string]$exactIndexedHint.Hint.TypeName -in @("string", "bool", "nil", "num", "array", "dict", "function")) {
            return [string]$exactIndexedHint.Hint.TypeName
        }
        $exactStringKeyHint = Get-WasmAstExactStringKeyAccessHint $Node
        if ($null -ne $exactStringKeyHint -and
            [string]$exactStringKeyHint.Hint.TypeName -in @("string", "bool", "nil", "num", "array", "dict", "function")) {
            return [string]$exactStringKeyHint.Hint.TypeName
        }
    }
    if ([string]$Node.node -eq "INDEX" -and
        $null -ne $Node.obj -and [string]$Node.obj.node -eq "IDENT" -and $null -ne $Node.key) {
        $literalIndex = Get-WasmAstKnownNumericLiteralValue ($Node.key)
        if ($null -ne $literalIndex) {
            $localIndexedHint = Get-WasmAstCurrentLocalIndexedAccessHint ([string]$Node.obj.name) ([int][Math]::Truncate([double]$literalIndex))
            if ($null -ne $localIndexedHint -and [string]$localIndexedHint.TypeName -in @("string", "bool", "nil", "num", "array", "dict", "function")) {
                return [string]$localIndexedHint.TypeName
            }
        }
        $accessKey = Get-WasmAstStringAccessHintKey $Node
        if (-not [string]::IsNullOrWhiteSpace($accessKey) -and
            -not $script:wasmConflictedAccessTypeHints.ContainsKey($accessKey)) {
            if ($script:wasmAccessTypeHints.ContainsKey($accessKey)) { return [string]$script:wasmAccessTypeHints[$accessKey] }
            if ($script:wasmStringAccessHints.ContainsKey($accessKey)) { return "string" }
        }
    }
    if ([string]$Node.node -eq "INDEX" -and
        $null -ne $Node.obj -and $null -ne $Node.key -and [string]$Node.key.node -ne "STR_LIT") {
        $stringIndexResult = Get-WasmAstKnownStringIndexResult $Node
        if ($null -ne $stringIndexResult) {
            return [string]$stringIndexResult.Type
        }
        $keyType = Get-WasmAstKnownValueType ($Node.key)
        if ([string]::IsNullOrWhiteSpace($keyType)) { $keyType = Get-WasmAstStaticValueType ($Node.key) }
        $objType = Get-WasmAstKnownValueType ($Node.obj)
        if ([string]::IsNullOrWhiteSpace($objType)) { $objType = Get-WasmAstStaticValueType ($Node.obj) }
        if ($objType -eq "string" -and $keyType -ne "string") {
            return "string"
        }
        if ($keyType -eq "string" -and $objType -eq "dict") {
            $dictValueType = Get-WasmAstDictValueTypeHint ($Node.obj)
            if ($dictValueType -in @("string", "bool", "nil", "num", "array", "dict", "function")) { return $dictValueType }
        }
    }
    if ([string]$Node.node -eq "INDEX" -and
        $null -ne $Node.obj -and $null -ne $Node.key -and [string]$Node.key.node -ne "STR_LIT") {
        $elementType = Get-WasmAstArrayElementTypeHint ($Node.obj)
        if ($elementType -in @("string", "bool", "nil", "num", "array", "dict", "function")) { return $elementType }
    }
    if ([string]$Node.node -eq "INDEX" -and
        $null -ne $Node.obj -and $null -ne $Node.key) {
        $objType = Get-WasmAstKnownValueType ($Node.obj)
        if ([string]::IsNullOrWhiteSpace($objType)) { $objType = Get-WasmAstStaticValueType ($Node.obj) }
        $receiverObjectClass = Get-WasmAstObjectClassTypeWithLocals ($Node.obj) $script:wasmCurrentLocalObjectClassHints $script:wasmCurrentClassContext @{}
        $indexedObjectClass = Get-WasmAstObjectClassTypeWithLocals $Node $script:wasmCurrentLocalObjectClassHints $script:wasmCurrentClassContext @{}
        if ($objType -eq "nil" -and
            [string]::IsNullOrWhiteSpace($receiverObjectClass) -and
            [string]::IsNullOrWhiteSpace($indexedObjectClass)) {
            return "nil"
        }
    }
    $key = Get-WasmAstStringAccessHintKey $Node
    if (-not [string]::IsNullOrWhiteSpace($key)) {
        if (-not $script:wasmConflictedAccessTypeHints.ContainsKey($key)) {
            if ($script:wasmAccessTypeHints.ContainsKey($key)) { return [string]$script:wasmAccessTypeHints[$key] }
            if ($script:wasmStringAccessHints.ContainsKey($key)) { return "string" }
        }
    }
    return ""
    } finally {
        $script:wasmKnownValueTypeInferenceStack.Remove($inferenceKey)
        $script:wasmKnownValueTypeInferenceDepth--
    }
}

function Get-WasmAstStaticValueType {
    param($Node)

    if ($null -eq $Node) { return "nil" }
    switch ([string]$Node.node) {
        "STR_LIT" { return "string" }
        "STR_INTERP" { return "string" }
        "BOOL_LIT" { return "bool" }
        "NIL_LIT" { return "nil" }
        "NUM_LIT" { return "num" }
        "ARRAY_LIT" { return "array" }
        "DICT_LIT" { return "dict" }
        "FUNC_EXPR" { return "function" }
        "BIN_OP" {
            if ([string]$Node.op -eq "in") {
                # The VM returns a boolean for string/array/dict receivers and
                # nil for every other receiver. Keep the result tagged because
                # the receiver can be a runtime Value whose concrete type is
                # not known while the module is being lowered.
                return "value"
            }
            if ([string]$Node.op -eq "??") {
                $leftType = Get-WasmAstStaticValueType ($Node.left)
                $rightType = Get-WasmAstStaticValueType ($Node.right)
                if ($leftType -eq "nil") { return $rightType }
                if (-not [string]::IsNullOrWhiteSpace($leftType) -and $leftType -eq $rightType) { return $leftType }
                if ((Test-WasmAstOptionalAccessExpr ($Node.left)) -and -not [string]::IsNullOrWhiteSpace($rightType)) { return $rightType }
                return ""
            }
            if ([string]$Node.op -eq "+") {
                if ((Test-WasmAstStringExprCandidate ($Node.left)) -or
                    (Test-WasmAstStringExprCandidate ($Node.right))) {
                    return "string"
                }
                $leftType = Get-WasmAstKnownValueType ($Node.left)
                if ([string]::IsNullOrWhiteSpace($leftType)) { $leftType = Get-WasmAstStaticValueType ($Node.left) }
                $rightType = Get-WasmAstKnownValueType ($Node.right)
                if ([string]::IsNullOrWhiteSpace($rightType)) { $rightType = Get-WasmAstStaticValueType ($Node.right) }
                if ($leftType -eq "array" -and $rightType -eq "array") { return "array" }
                if ($leftType -eq "value" -or $rightType -eq "value") { return "value" }
                return "num"
            }
            if ([string]$Node.op -in @("and", "or", "==", "!=", "<", "<=", ">", ">=")) {
                return "bool"
            }
            if ([string]$Node.op -in @("-", "*", "/", "%")) {
                $leftType = Get-WasmAstKnownValueType ($Node.left)
                if ([string]::IsNullOrWhiteSpace($leftType)) { $leftType = Get-WasmAstStaticValueType ($Node.left) }
                $rightType = Get-WasmAstKnownValueType ($Node.right)
                if ([string]::IsNullOrWhiteSpace($rightType)) { $rightType = Get-WasmAstStaticValueType ($Node.right) }
                if ($leftType -eq "value" -or $rightType -eq "value") { return "value" }
                return "num"
            }
            if ([string]$Node.op -in @("&", "|", "^", "<<", ">>")) {
                return "num"
            }
            return (Get-WasmAstKnownValueType $Node)
        }
        "UNARY_OP" {
            if ([string]$Node.op -eq "not") { return "bool" }
            if ([string]$Node.op -in @("-", "~")) { return "num" }
            return (Get-WasmAstKnownValueType $Node)
        }
        "TERNARY" {
            $thenType = Get-WasmAstStaticValueType ($Node.then)
            $elseType = Get-WasmAstStaticValueType ($Node.else)
            if (-not [string]::IsNullOrWhiteSpace($thenType) -and $thenType -eq $elseType) {
                return $thenType
            }
            return ""
        }
        default { return (Get-WasmAstKnownValueType $Node) }
    }
}

function Get-WasmAstRuntimeTypeName {
    param($Node)

    if ($null -eq $Node) { return "nil" }
    $className = Get-WasmAstObjectClassTypeHint $Node
    if (-not [string]::IsNullOrWhiteSpace($className)) { return "instance" }

    $typeName = Get-WasmAstKnownValueType $Node
    if ([string]::IsNullOrWhiteSpace($typeName)) {
        $typeName = Get-WasmAstStaticValueType $Node
    }

    switch ([string]$typeName) {
        "string" { return "string" }
        "bool" { return "bool" }
        "nil" { return "nil" }
        "array" { return "array" }
        "dict" { return "dict" }
        "function" { return "function" }
        "num" { return "number" }
        default {
            if ($null -ne $Node -and [string]$Node.node -eq "FUNC_EXPR") { return "function" }
            return "number"
        }
    }
}

function Test-WasmAstRuntimeTypeNameValueCandidate {
    param($Node)

    if ($null -eq $Node) { return $true }
    if (Test-WasmAstStringIndexExpr $Node) { return $true }
    if ([string]$Node.node -eq "FUNC_EXPR") { return $false }
    if (-not [string]::IsNullOrWhiteSpace((Get-WasmAstObjectClassTypeHint $Node))) { return $false }

    $typeName = Get-WasmAstKnownValueType $Node
    if ([string]::IsNullOrWhiteSpace($typeName)) {
        $typeName = Get-WasmAstStaticValueType $Node
    }
    if ([string]::IsNullOrWhiteSpace($typeName)) { return $true }
    if ($typeName -eq "value") { return $true }
    return ($typeName -in @("string", "bool", "nil", "num", "array", "dict", "function"))
}

function Convert-WasmAstRuntimeTypeNameExpr {
    param($Node)

    if ($null -ne $Node -and [string]$Node.node -eq "TERNARY") {
        $condCode = @(Convert-WasmAstConditionExpr ($Node.cond))
        $thenCode = @(Convert-WasmAstRuntimeTypeNameExpr ($Node.then))
        $elseCode = @(Convert-WasmAstRuntimeTypeNameExpr ($Node.else))
        return @(
            $condCode +
            @("if (result i32)") +
            $thenCode +
            @("else") +
            $elseCode +
            @("end")
        )
    }

    $exactIndexedTypeName = @(Convert-WasmAstExactIndexedArrayAccessTypeNameExpr $Node)
    if ($exactIndexedTypeName.Count -gt 0) {
        return $exactIndexedTypeName
    }

    if (Test-WasmAstRuntimeTypeNameValueCandidate $Node) {
        return @(Convert-WasmAstValueExpr $Node) + @("call `$__sura_value_type_name")
    }

    $typeName = Get-WasmAstRuntimeTypeName $Node
    $typeCode = New-Object System.Collections.Generic.List[string]
    Add-Code $typeCode @(Convert-WasmAstExpr $Node) ""
    $typeCode.Add("drop")
    Add-Code $typeCode @(New-WasmStringLiteralExprCode -Literal (Convert-WasmAstStringLiteral $typeName)) ""
    return @($typeCode.ToArray())
}

function Get-WasmAstKnownFunctionDisplayName {
    param($Node)

    if ($null -eq $Node) { return "" }
    $specializedDisplay = Get-WasmAstSpecializedFunctionCallReturnHint $Node "display"
    if (-not [string]::IsNullOrWhiteSpace($specializedDisplay)) { return $specializedDisplay }
    if ([string]$Node.node -eq "FUNC_EXPR") {
        $displayName = Get-WasmAstFuncExprDisplayName $Node
        if (-not [string]::IsNullOrWhiteSpace($displayName)) { return $displayName }
    }
    $inferredDisplay = Get-WasmAstFunctionHintFromExpr $Node "display" $script:wasmCurrentClassContext $script:wasmCurrentLocalFunctionDisplayHints $script:wasmCurrentLocalFunctionLiftHints @{}
    if (-not [string]::IsNullOrWhiteSpace($inferredDisplay)) { return $inferredDisplay }
    if ([string]$Node.node -eq "DOT_ACCESS") {
        $className = Get-WasmAstObjectClassTypeWithLocals ($Node.obj) $script:wasmCurrentLocalObjectClassHints $script:wasmCurrentClassContext @{}
        if (-not [string]::IsNullOrWhiteSpace($className)) {
            $fieldDisplay = Get-WasmAstClassFieldFunctionDisplayHint $className ([string]$Node.prop)
            if (-not [string]::IsNullOrWhiteSpace($fieldDisplay)) { return $fieldDisplay }
        }
    }
    if ([string]$Node.node -eq "INDEX" -and
        $null -ne $Node.obj -and [string]$Node.obj.node -eq "IDENT" -and
        $null -ne $Node.key) {
        $literalIndex = Get-WasmAstKnownNumericLiteralValue ($Node.key)
        if ($null -ne $literalIndex) {
            $accessKey = ("{0}[{1}]" -f ([string]$Node.obj.name), [int][Math]::Truncate([double]$literalIndex))
            if (-not $script:wasmConflictedAccessTypeHints.ContainsKey($accessKey) -and
                -not $script:wasmConflictedAccessFunctionDisplayHints.ContainsKey($accessKey) -and
                $script:wasmAccessTypeHints.ContainsKey($accessKey) -and
                [string]$script:wasmAccessTypeHints[$accessKey] -eq "function" -and
                $script:wasmAccessFunctionDisplayHints.ContainsKey($accessKey)) {
                return [string]$script:wasmAccessFunctionDisplayHints[$accessKey]
            }
        }
    }
    $accessKey = Get-WasmAstStringAccessHintKey $Node
    if (-not [string]::IsNullOrWhiteSpace($accessKey) -and
        -not $script:wasmConflictedAccessTypeHints.ContainsKey($accessKey) -and
        -not $script:wasmConflictedAccessFunctionDisplayHints.ContainsKey($accessKey) -and
        $script:wasmAccessTypeHints.ContainsKey($accessKey) -and
        [string]$script:wasmAccessTypeHints[$accessKey] -eq "function" -and
        $script:wasmAccessFunctionDisplayHints.ContainsKey($accessKey)) {
        return [string]$script:wasmAccessFunctionDisplayHints[$accessKey]
    }
    if ([string]$Node.node -eq "IDENT") {
        $name = [string]$Node.name
        if ($script:wasmAstFunctionDefs.ContainsKey($name)) { return $name }
        if ($script:wasmGlobalFunctionDisplayHints.ContainsKey($name)) {
            return [string]$script:wasmGlobalFunctionDisplayHints[$name]
        }
        if ($script:wasmCurrentLocalFunctionDisplayHints.ContainsKey($name)) {
            return [string]$script:wasmCurrentLocalFunctionDisplayHints[$name]
        }
        if ($script:wasmCurrentLocalValueTypeHints.ContainsKey($name) -and
            [string]$script:wasmCurrentLocalValueTypeHints[$name] -eq "function") {
            return $name
        }
        if (-not $script:wasmConflictedValueTypeHints.ContainsKey($name) -and
            $script:wasmValueTypeHints.ContainsKey($name) -and
            [string]$script:wasmValueTypeHints[$name] -eq "function") {
            return $name
        }
    }
    if ([string]$Node.node -eq "TERNARY") {
        $thenName = Get-WasmAstKnownFunctionDisplayName ($Node.then)
        $elseName = Get-WasmAstKnownFunctionDisplayName ($Node.else)
        if (-not [string]::IsNullOrWhiteSpace($thenName) -and $thenName -eq $elseName) {
            return $thenName
        }
    }
    return ""
}

function Join-WasmAstStringExprCodes {
    param([object[]]$Parts)

    $partsList = @($Parts)
    if ($partsList.Count -eq 0) {
        return @(New-WasmStringLiteralExprCode -Literal '""')
    }
    $code = @([string[]]$partsList[0])
    for ($i = 1; $i -lt $partsList.Count; $i++) {
        $code = @($code + @([string[]]$partsList[$i]) + @("call `$__sura_string_concat"))
    }
    return $code
}

function New-WasmAstLiteralStringExprCode {
    param([string]$Text)

    return @(New-WasmStringLiteralExprCode -Literal (Convert-WasmAstStringLiteral $Text))
}

function Test-WasmAstConsoleOutputCall {
    param($Node)

    if ($null -eq $Node) { return $false }
    if ([string]$Node.node -eq "CALL") {
        return (Test-WasmConsoleOutputName ([string]$Node.name))
    }
    if ([string]$Node.node -eq "METHOD_CALL" -and
        $null -ne $Node.obj -and [string]$Node.obj.node -eq "IDENT" -and [string]$Node.obj.name -eq "console") {
        return (Test-WasmConsoleOutputName ("console.$([string]$Node.method)"))
    }
    return $false
}

function Convert-WasmAstConsoleArgsToStringExpr {
    param([object[]]$InputArgs)

    $parts = New-Object System.Collections.Generic.List[object]
    for ($i = 0; $i -lt $InputArgs.Count; $i++) {
        if ($i -gt 0) { $parts.Add([string[]]@(New-WasmAstLiteralStringExprCode " ")) | Out-Null }
        $parts.Add([string[]]@(Convert-WasmAstToStringExpr $InputArgs[$i])) | Out-Null
    }
    return @(Join-WasmAstStringExprCodes @($parts.ToArray()))
}

function Add-WasmAstConsoleOutputCall {
    param($Node, [System.Collections.Generic.List[string]]$Out, [string]$Indent, [switch]$Main)

    $args = @()
    if ([string]$Node.node -eq "CALL") {
        $args = @(As-WasmAstArray ($Node.args))
    } elseif ([string]$Node.node -eq "METHOD_CALL") {
        $args = @(As-WasmAstArray ($Node.args))
    } else {
        throw "unsupported WASM AST console output node: $([string]$Node.node)"
    }
    Add-Code $Out @(Convert-WasmAstConsoleArgsToStringExpr ([object[]]$args)) $Indent
    if ($Main) { $Out.Add("${Indent}local.set `$__result") } else { $Out.Add("${Indent}drop") }
}

function Add-WasmAstPrintOutputCall {
    param([object[]]$InputArgs, [System.Collections.Generic.List[string]]$Out, [string]$Indent, [switch]$Main)

    $argsList = @($InputArgs)
    if ($argsList.Count -lt 1) {
        return
    }
    Add-Code $Out @(Convert-WasmAstConsoleArgsToStringExpr ([object[]]$argsList)) $Indent
    if ($Main) { $Out.Add("${Indent}local.set `$__result") } else { $Out.Add("${Indent}drop") }
    foreach ($arg in $argsList) {
        Apply-WasmAstGlobalAssignmentHintsFromExpr $arg
    }
}

function Test-WasmAstStringifiedValueCandidate {
    param($Node)

    if ($null -eq $Node) { return $true }
    if ([string]$Node.node -in @("ARRAY_LIT", "DICT_LIT")) { return $true }
    if ((Test-WasmAstKnownEmptyArrayExpr $Node) -or (Test-WasmAstKnownEmptyDictExpr $Node)) { return $true }
    if (-not [string]::IsNullOrWhiteSpace((Get-WasmAstKnownFunctionDisplayName $Node))) { return $true }
    if ([string]$Node.node -eq "TERNARY") {
        return ((Test-WasmAstStringifiedValueCandidate ($Node.then)) -and
            (Test-WasmAstStringifiedValueCandidate ($Node.else)))
    }
    $typeName = Get-WasmAstKnownValueType $Node
    if ([string]::IsNullOrWhiteSpace($typeName)) {
        $typeName = Get-WasmAstStaticValueType $Node
    }
    if ($typeName -in @("string", "bool", "nil", "num")) { return $true }
    if ($typeName -eq "array") {
        $elementType = Get-WasmAstArrayElementTypeHint $Node
        if ($elementType -in @("string", "bool", "nil", "num")) { return $true }
        return (@(Get-WasmAstIndexedArrayElementTypes $Node).Count -gt 0)
    }
    if ($typeName -eq "dict") {
        return (@(Get-WasmAstOrderedDictEntryTypes $Node).Count -gt 0)
    }
    return $false
}

function Test-WasmAstRuntimeValueLiteralElementCandidate {
    param($Node)

    if ($null -eq $Node) { return $true }
    if ([string]$Node.node -eq "TERNARY") {
        return ((Test-WasmAstRuntimeValueLiteralElementCandidate ($Node.then)) -and
            (Test-WasmAstRuntimeValueLiteralElementCandidate ($Node.else)))
    }
    if (Test-WasmAstRuntimeValueCollectionLiteralCandidate $Node) { return $true }
    $typeName = Get-WasmAstKnownValueType $Node
    if ([string]::IsNullOrWhiteSpace($typeName)) {
        $typeName = Get-WasmAstStaticValueType $Node
    }
    return ($typeName -in @("string", "bool", "nil", "num"))
}

function Test-WasmAstRuntimeValueCollectionLiteralCandidate {
    param($Node)

    if ($null -eq $Node) { return $false }
    if ([string]$Node.node -eq "TERNARY") {
        return ((Test-WasmAstRuntimeValueCollectionLiteralCandidate ($Node.then)) -and
            (Test-WasmAstRuntimeValueCollectionLiteralCandidate ($Node.else)))
    }
    if ([string]$Node.node -eq "ARRAY_LIT") {
        foreach ($item in @(As-WasmAstArray ($Node.elements))) {
            if (-not (Test-WasmAstRuntimeValueLiteralElementCandidate $item)) { return $false }
        }
        return $true
    }
    if ([string]$Node.node -eq "DICT_LIT") {
        foreach ($entry in @(As-WasmAstArray ($Node.entries))) {
            if (-not (Test-WasmAstRuntimeValueLiteralElementCandidate ($entry.value))) { return $false }
        }
        return $true
    }
    return $false
}

function Convert-WasmAstStringifiedValueExpr {
    param($Node)

    if ($null -eq $Node) { return @(New-WasmAstLiteralStringExprCode "nil") }
    if ([string]$Node.node -eq "ARRAY_LIT") { return @(Convert-WasmAstArrayLiteralToStringExpr $Node) }
    if ([string]$Node.node -eq "DICT_LIT") { return @(Convert-WasmAstDictLiteralToStringExpr $Node) }
    if ([string]$Node.node -eq "TERNARY" -and
        (Test-WasmAstStringifiedValueCandidate ($Node.then)) -and
        (Test-WasmAstStringifiedValueCandidate ($Node.else))) {
        $condCode = @(Convert-WasmAstConditionExpr ($Node.cond))
        $thenCode = @(Convert-WasmAstStringifiedValueExpr ($Node.then))
        $elseCode = @(Convert-WasmAstStringifiedValueExpr ($Node.else))
        return @(
            $condCode +
            @("if (result i32)") +
            $thenCode +
            @("else") +
            $elseCode +
            @("end")
        )
    }

    $functionName = Get-WasmAstKnownFunctionDisplayName $Node
    if (-not [string]::IsNullOrWhiteSpace($functionName)) {
        return @(New-WasmAstLiteralStringExprCode ("<Func $functionName>"))
    }

    $typeName = Get-WasmAstKnownValueType $Node
    if ([string]::IsNullOrWhiteSpace($typeName)) {
        $typeName = Get-WasmAstStaticValueType $Node
    }
    if ($typeName -eq "string") {
        return @(Join-WasmAstStringExprCodes @(
            @(New-WasmAstLiteralStringExprCode '"'),
            @(Convert-WasmAstStringExpr $Node),
            @(New-WasmAstLiteralStringExprCode '"')
        ))
    }
    if ($typeName -in @("bool", "nil", "num")) {
        return @(Convert-WasmAstStringExpr $Node)
    }
    if ($typeName -in @("array", "dict")) {
        return @(Convert-WasmAstToStringExpr $Node)
    }
    throw "unsupported WASM AST to_str() collection element type: $typeName"
}

function Convert-WasmAstArrayLiteralToStringExpr {
    param($Node)

    $parts = New-Object System.Collections.Generic.List[object]
    $parts.Add([string[]]@(New-WasmAstLiteralStringExprCode "[")) | Out-Null
    $index = 0
    foreach ($item in @(As-WasmAstArray ($Node.elements))) {
        if ($index -gt 0) { $parts.Add([string[]]@(New-WasmAstLiteralStringExprCode ", ")) | Out-Null }
        $parts.Add([string[]]@(Convert-WasmAstStringifiedValueExpr $item)) | Out-Null
        $index++
    }
    $parts.Add([string[]]@(New-WasmAstLiteralStringExprCode "]")) | Out-Null
    return @(Join-WasmAstStringExprCodes @($parts.ToArray()))
}

function Convert-WasmAstDictLiteralToStringExpr {
    param($Node)

    $parts = New-Object System.Collections.Generic.List[object]
    $parts.Add([string[]]@(New-WasmAstLiteralStringExprCode "{")) | Out-Null
    $index = 0
    foreach ($entry in @(As-WasmAstArray ($Node.entries))) {
        if ($index -gt 0) { $parts.Add([string[]]@(New-WasmAstLiteralStringExprCode ", ")) | Out-Null }
        $parts.Add([string[]]@(New-WasmAstLiteralStringExprCode ('"{0}": ' -f [string]$entry.key))) | Out-Null
        $parts.Add([string[]]@(Convert-WasmAstStringifiedValueExpr ($entry.value))) | Out-Null
        $index++
    }
    $parts.Add([string[]]@(New-WasmAstLiteralStringExprCode "}")) | Out-Null
    return @(Join-WasmAstStringExprCodes @($parts.ToArray()))
}

function New-WasmAstOrderedDictEntryType {
    param([string]$Key, [string]$TypeName)

    return [pscustomobject]@{
        Key = $Key
        Type = $TypeName
    }
}

function Copy-WasmAstOrderedDictEntryTypes {
    param($Entries)

    $copy = New-Object System.Collections.Generic.List[object]
    foreach ($entry in @($Entries)) {
        if ($null -eq $entry) { return @() }
        $copy.Add((New-WasmAstOrderedDictEntryType ([string]$entry.Key) ([string]$entry.Type))) | Out-Null
    }
    return @($copy.ToArray())
}

function Get-WasmAstDictLiteralOrderedEntryTypes {
    param($Node)

    if ($null -eq $Node -or [string]$Node.node -ne "DICT_LIT") { return @() }
    $entries = New-Object System.Collections.Generic.List[object]
    foreach ($entry in @(As-WasmAstArray ($Node.entries))) {
        $key = [string]$entry.key
        if ([string]::IsNullOrWhiteSpace($key)) { return @() }
        $typeName = [string](Get-WasmAstStaticValueType ($entry.value))
        if ($typeName -notin @("string", "bool", "nil", "num", "array", "dict")) { return @() }
        $entries.Add((New-WasmAstOrderedDictEntryType $key $typeName)) | Out-Null
    }
    return @($entries.ToArray())
}

function Merge-WasmAstOrderedDictEntryTypes {
    param($Left, $Right)

    $leftEntries = @($Left)
    $rightEntries = @($Right)
    if ($leftEntries.Count -eq 0 -or $leftEntries.Count -ne $rightEntries.Count) { return @() }

    $merged = New-Object System.Collections.Generic.List[object]
    for ($i = 0; $i -lt $leftEntries.Count; $i++) {
        $leftEntry = $leftEntries[$i]
        $rightEntry = $rightEntries[$i]
        if ($null -eq $leftEntry -or $null -eq $rightEntry) { return @() }
        if ([string]$leftEntry.Key -ne [string]$rightEntry.Key -or
            [string]$leftEntry.Type -ne [string]$rightEntry.Type) {
            return @()
        }
        $merged.Add((New-WasmAstOrderedDictEntryType ([string]$leftEntry.Key) ([string]$leftEntry.Type))) | Out-Null
    }
    return @($merged.ToArray())
}

function Get-WasmAstIdentOrderedDictEntryTypes {
    param([string]$Name, [hashtable]$LocalOrderedEntries = @{})

    if ([string]::IsNullOrWhiteSpace($Name)) { return @() }
    if ($null -ne $LocalOrderedEntries -and $LocalOrderedEntries.ContainsKey($Name)) {
        return @(Copy-WasmAstOrderedDictEntryTypes $LocalOrderedEntries[$Name])
    }
    if (-not $script:wasmDictKeyOrderHints.ContainsKey($Name)) { return @() }

    $localHints = $null
    if ($script:wasmCurrentLocalIndexedAccessHints.ContainsKey($Name)) {
        $localHints = $script:wasmCurrentLocalIndexedAccessHints[$Name]
    }

    $entries = New-Object System.Collections.Generic.List[object]
    foreach ($keyName in @($script:wasmDictKeyOrderHints[$Name])) {
        $key = [string]$keyName
        if ([string]::IsNullOrWhiteSpace($key)) { return @() }
        if ($null -ne $localHints) {
            if (-not $localHints.ContainsKey($key)) { return @() }
            $typeName = [string]$localHints[$key].TypeName
            if ($typeName -notin @("string", "bool", "nil", "num", "array", "dict")) { return @() }
            $entries.Add((New-WasmAstOrderedDictEntryType $key $typeName)) | Out-Null
            continue
        }
        $hintKey = "$Name.$key"
        if ($script:wasmConflictedAccessTypeHints.ContainsKey($hintKey) -or
            -not $script:wasmAccessTypeHints.ContainsKey($hintKey)) {
            return @()
        }
        $typeName = [string]$script:wasmAccessTypeHints[$hintKey]
        if ($typeName -notin @("string", "bool", "nil", "num", "array", "dict")) { return @() }
        $entries.Add((New-WasmAstOrderedDictEntryType $key $typeName)) | Out-Null
    }
    return @($entries.ToArray())
}

function Get-WasmAstReturnOrderedDictEntryTypesFromBody {
    param($Body, [hashtable]$SeenFunctions = @{})

    if ($null -eq $Body) { return @() }
    $localOrderedEntries = @{}
    foreach ($stmt in @(As-WasmAstArray ($Body.body))) {
        if ($null -eq $stmt) { continue }
        switch ([string]$stmt.node) {
            "ASSIGN" {
                $name = [string]$stmt.name
                if ([string]::IsNullOrWhiteSpace($name)) { continue }
                $entries = @(Get-WasmAstOrderedDictEntryTypes ($stmt.value) $localOrderedEntries $SeenFunctions)
                if ($entries.Count -gt 0) {
                    $localOrderedEntries[$name] = @(Copy-WasmAstOrderedDictEntryTypes $entries)
                } elseif ($localOrderedEntries.ContainsKey($name)) {
                    $localOrderedEntries.Remove($name)
                }
            }
            "RETURN" {
                return @(Get-WasmAstOrderedDictEntryTypes ($stmt.value) $localOrderedEntries $SeenFunctions)
            }
            "SuraBlock" {
                $nested = @(Get-WasmAstReturnOrderedDictEntryTypesFromBody $stmt $SeenFunctions)
                if ($nested.Count -gt 0) { return $nested }
            }
            "IF" {
                $thenEntries = @(Get-WasmAstReturnOrderedDictEntryTypesFromBody ($stmt.then_block) $SeenFunctions)
                $elseEntries = @(Get-WasmAstReturnOrderedDictEntryTypesFromBody ($stmt.else_block) $SeenFunctions)
                $merged = @(Merge-WasmAstOrderedDictEntryTypes $thenEntries $elseEntries)
                if ($merged.Count -gt 0) { return $merged }
            }
            default { }
        }
    }
    return @()
}

function Get-WasmAstOrderedDictEntryTypes {
    param($Collection, [hashtable]$LocalOrderedEntries = @{}, [hashtable]$SeenFunctions = @{})

    if ($null -eq $Collection) { return @() }
    switch ([string]$Collection.node) {
        "DICT_LIT" {
            return @(Get-WasmAstDictLiteralOrderedEntryTypes $Collection)
        }
        "IDENT" {
            return @(Get-WasmAstIdentOrderedDictEntryTypes ([string]$Collection.name) $LocalOrderedEntries)
        }
        { $_ -in @("DOT_ACCESS", "INDEX") } {
            $accessName = Get-WasmAstAccessPathName $Collection
            if ([string]::IsNullOrWhiteSpace($accessName)) { return @() }
            return @(Get-WasmAstIdentOrderedDictEntryTypes $accessName $LocalOrderedEntries)
        }
        "TERNARY" {
            $condState = Get-WasmAstKnownBoolLiteralState ($Collection.cond)
            if ($condState -eq "true") {
                return @(Get-WasmAstOrderedDictEntryTypes ($Collection.then) $LocalOrderedEntries $SeenFunctions)
            }
            if ($condState -eq "false") {
                return @(Get-WasmAstOrderedDictEntryTypes ($Collection.else) $LocalOrderedEntries $SeenFunctions)
            }
            $thenEntries = @(Get-WasmAstOrderedDictEntryTypes ($Collection.then) $LocalOrderedEntries $SeenFunctions)
            $elseEntries = @(Get-WasmAstOrderedDictEntryTypes ($Collection.else) $LocalOrderedEntries $SeenFunctions)
            return @(Merge-WasmAstOrderedDictEntryTypes $thenEntries $elseEntries)
        }
        "CALL" {
            $name = [string]$Collection.name
            if ([string]::IsNullOrWhiteSpace($name) -or -not $script:wasmAstFunctionDefs.ContainsKey($name) -or
                $SeenFunctions.ContainsKey($name)) {
                return @()
            }
            $SeenFunctions[$name] = $true
            try {
                $resolvedReturn = Resolve-WasmAstFunctionCallReturnExpr $Collection
                if ($null -ne $resolvedReturn) {
                    return @(Get-WasmAstOrderedDictEntryTypes $resolvedReturn $LocalOrderedEntries $SeenFunctions)
                }
                $fn = $script:wasmAstFunctionDefs[$name]
                return @(Get-WasmAstReturnOrderedDictEntryTypesFromBody ($fn.Node.body) $SeenFunctions)
            } finally {
                $SeenFunctions.Remove($name)
            }
        }
        "METHOD_CALL" {
            $resolvedReturn = Resolve-WasmAstMethodCallReturnExpr $Collection
            if ($null -ne $resolvedReturn) {
                return @(Get-WasmAstOrderedDictEntryTypes $resolvedReturn $LocalOrderedEntries $SeenFunctions)
            }
            $objName = Get-WasmAstAccessPathName ($Collection.obj)
            if ([string]::IsNullOrWhiteSpace($objName)) { return @() }
            $className = Get-WasmAstObjectClassTypeWithLocals ($Collection.obj) $script:wasmCurrentLocalObjectClassHints $script:wasmCurrentClassContext @{}
            if ([string]::IsNullOrWhiteSpace($className)) { return @() }
            $methodInfo = Get-WasmAstClassMethod -ClassName $className -MethodName ([string]$Collection.method)
            if ($null -eq $methodInfo) { return @() }
            return @(Get-WasmAstReturnOrderedDictEntryTypesFromBodyForObject ($methodInfo.Method.body) $objName $SeenFunctions)
        }
        default { return @() }
    }
}

function Convert-WasmAstDictEntryToStringExpr {
    param($DictNode, [string]$KeyName, [string]$TypeName)

    $load = @(
        @(Convert-WasmAstExpr $DictNode) +
        @("i32.const $(Get-WasmStringKeyHash $KeyName)", "call `$__sura_dict_get")
    )

    switch ([string]$TypeName) {
        "num" { return @($load + @("call `$__sura_i32_to_string")) }
        "string" {
            return @(Join-WasmAstStringExprCodes @(
                @(New-WasmAstLiteralStringExprCode '"'),
                $load,
                @(New-WasmAstLiteralStringExprCode '"')
            ))
        }
        "bool" {
            return @(
                $load +
                @("if (result i32)") +
                @(New-WasmAstLiteralStringExprCode "true") +
                @("else") +
                @(New-WasmAstLiteralStringExprCode "false") +
                @("end")
            )
        }
        "nil" {
            return @($load + @("drop") + @(New-WasmAstLiteralStringExprCode "nil"))
        }
        { $_ -in @("array", "dict") } {
            $entryNode = [pscustomobject]@{
                node = "DOT_ACCESS"
                obj = $DictNode
                prop = $KeyName
            }
            return @(Convert-WasmAstToStringExpr $entryNode)
        }
        default { return @() }
    }
}

function Convert-WasmAstOrderedDictToStringExpr {
    param($Node)

    $entries = @(Get-WasmAstOrderedDictEntryTypes $Node)
    if ($entries.Count -eq 0) {
        if ($null -ne $Node -and [string]$Node.node -eq "IDENT" -and
            $script:wasmDictKeyOrderHints.ContainsKey([string]$Node.name) -and
            @($script:wasmDictKeyOrderHints[[string]$Node.name]).Count -eq 0) {
            return @(New-WasmAstLiteralStringExprCode "{}")
        }
        return @()
    }

    $prefix = @()
    $entryNode = $Node
    if ((Test-WasmAstEffectfulExpr $Node) -or
        ($null -ne $Node -and [string]$Node.node -eq "BIN_OP" -and [string]$Node.op -eq "??")) {
        $prefix = @(Convert-WasmAstExpr $Node) + @("local.set `$__sura_wasm_value_tmp")
        $entryNode = [pscustomobject]@{ node = "IDENT"; name = "__sura_wasm_value_tmp" }
    }

    $parts = New-Object System.Collections.Generic.List[object]
    $parts.Add([string[]]@(New-WasmAstLiteralStringExprCode "{")) | Out-Null
    for ($i = 0; $i -lt $entries.Count; $i++) {
        $entry = $entries[$i]
        if ($i -gt 0) { $parts.Add([string[]]@(New-WasmAstLiteralStringExprCode ", ")) | Out-Null }
        $parts.Add([string[]]@(New-WasmAstLiteralStringExprCode ('"{0}": ' -f [string]$entry.Key))) | Out-Null
        $parts.Add([string[]]@(Convert-WasmAstDictEntryToStringExpr $entryNode ([string]$entry.Key) ([string]$entry.Type))) | Out-Null
    }
    $parts.Add([string[]]@(New-WasmAstLiteralStringExprCode "}")) | Out-Null
    return @($prefix + @(Join-WasmAstStringExprCodes @($parts.ToArray())))
}

function Convert-WasmAstFixedIndexedHintMapToPrimitiveTypeList {
    param([hashtable]$Map)

    return @(Convert-WasmAstFixedIndexedHintMapToTypeList $Map @("string", "bool", "nil", "num"))
}

function Get-WasmAstIndexedArrayElementTypes {
    param($Collection, [hashtable]$LocalIndexedHints = @{}, [hashtable]$SeenFunctions = @{})

    if ($null -eq $Collection) { return @() }
    $hints = Get-WasmAstFixedIndexedAccessHintsForExpr $Collection $LocalIndexedHints $SeenFunctions
    return @(Convert-WasmAstFixedIndexedHintMapToPrimitiveTypeList $hints)
}

function Convert-WasmAstIndexedArrayElementToStringExpr {
    param($ArrayNode, [int]$Index, [string]$TypeName)

    $load = @(
        @(Convert-WasmAstExpr $ArrayNode) +
        @("i32.const $Index", "call `$__sura_array_get_checked")
    )

    switch ([string]$TypeName) {
        "num" { return @($load + @("call `$__sura_i32_to_string")) }
        "string" {
            return @(Join-WasmAstStringExprCodes @(
                @(New-WasmAstLiteralStringExprCode '"'),
                $load,
                @(New-WasmAstLiteralStringExprCode '"')
            ))
        }
        "bool" {
            return @(
                $load +
                @("if (result i32)") +
                @(New-WasmAstLiteralStringExprCode "true") +
                @("else") +
                @(New-WasmAstLiteralStringExprCode "false") +
                @("end")
            )
        }
        "nil" {
            return @($load + @("drop") + @(New-WasmAstLiteralStringExprCode "nil"))
        }
        default { return @() }
    }
}

function Convert-WasmAstIndexedArrayElementValueToStringExpr {
    param($ArrayNode, [int]$Index, [string]$TypeName, $KeyNode = $null)

    $load = @(
        @(Convert-WasmAstExpr $ArrayNode) +
        $(if ($null -ne $KeyNode -and (Test-WasmAstEffectfulExpr $KeyNode)) { @(Convert-WasmAstExpr $KeyNode) + @("drop") } else { @() }) +
        @("i32.const $Index", "call `$__sura_array_get_checked")
    )

    switch ([string]$TypeName) {
        "num" { return @($load + @("call `$__sura_i32_to_string")) }
        "string" { return @($load) }
        "bool" {
            return @(
                $load +
                @("if (result i32)") +
                @(New-WasmAstLiteralStringExprCode "true") +
                @("else") +
                @(New-WasmAstLiteralStringExprCode "false") +
                @("end")
            )
        }
        "nil" {
            return @($load + @("drop") + @(New-WasmAstLiteralStringExprCode "nil"))
        }
        default { return @() }
    }
}

function Convert-WasmAstExactIndexedArrayAccessToStringExpr {
    param($Node)

    if ($null -eq $Node -or [string]$Node.node -ne "INDEX" -or
        $null -eq $Node.obj -or $null -eq $Node.key) {
        return @()
    }
    if (Test-WasmAstRuntimeValueIndexCandidate $Node) { return @() }

    $exactIndexedHint = Get-WasmAstExactIndexedAccessHint $Node
    if ($null -eq $exactIndexedHint) { return @() }
    $indexValue = [int]$exactIndexedHint.Index
    $typeName = [string]$exactIndexedHint.Hint.TypeName
    if ($typeName -notin @("string", "bool", "nil", "num")) { return @() }
    return @(Convert-WasmAstIndexedArrayElementValueToStringExpr ($Node.obj) $indexValue $typeName ($Node.key))
}

function Convert-WasmAstExactIndexedArrayAccessTypeNameExpr {
    param($Node)

    if ($null -eq $Node -or [string]$Node.node -ne "INDEX" -or
        $null -eq $Node.obj -or $null -eq $Node.key) {
        return @()
    }
    if (Test-WasmAstRuntimeValueIndexCandidate $Node) { return @() }
    if ($null -eq (Get-WasmAstKnownNumericLiteralValue ($Node.key))) { return @() }

    $exactIndexedHint = Get-WasmAstExactIndexedAccessHint $Node
    if ($null -eq $exactIndexedHint) { return @() }
    $typeName = [string]$exactIndexedHint.Hint.TypeName
    if ($typeName -notin @("string", "bool", "nil", "num")) { return @() }

    $runtimeName = switch ([string]$typeName) {
        "num" { "number" }
        "bool" { "bool" }
        "nil" { "nil" }
        default { [string]$typeName }
    }
    return @(Convert-WasmAstExpr $Node) + @("drop") + @(New-WasmStringLiteralExprCode -Literal (Convert-WasmAstStringLiteral $runtimeName))
}

function Convert-WasmAstIndexedArrayToStringExpr {
    param($Node)

    $types = @(Get-WasmAstIndexedArrayElementTypes $Node)
    if ($types.Count -eq 0) { return @() }

    $prefix = @()
    $elementNode = $Node
    if ((Test-WasmAstEffectfulExpr $Node) -or
        ($null -ne $Node -and [string]$Node.node -eq "BIN_OP" -and [string]$Node.op -eq "??")) {
        $prefix = @(Convert-WasmAstExpr $Node) + @("local.set `$__sura_wasm_value_tmp")
        $elementNode = [pscustomobject]@{ node = "IDENT"; name = "__sura_wasm_value_tmp" }
    }

    $parts = New-Object System.Collections.Generic.List[object]
    $parts.Add([string[]]@(New-WasmAstLiteralStringExprCode "[")) | Out-Null
    for ($i = 0; $i -lt $types.Count; $i++) {
        if ($i -gt 0) { $parts.Add([string[]]@(New-WasmAstLiteralStringExprCode ", ")) | Out-Null }
        $parts.Add([string[]]@(Convert-WasmAstIndexedArrayElementToStringExpr $elementNode $i ([string]$types[$i]))) | Out-Null
    }
    $parts.Add([string[]]@(New-WasmAstLiteralStringExprCode "]")) | Out-Null
    return @($prefix + @(Join-WasmAstStringExprCodes @($parts.ToArray())))
}

function Copy-WasmAstStringObjectMap {
    param([hashtable]$Map)

    $copy = @{}
    if ($null -eq $Map) { return $copy }
    foreach ($entry in $Map.GetEnumerator()) {
        $copy[[string]$entry.Key] = $entry.Value
    }
    return $copy
}

function Resolve-WasmAstExprWithMethodContext {
    param($Node, $ObjectExpr, [hashtable]$ParamExprs, [hashtable]$LocalExprs, [string]$ClassName = "")

    if ($null -eq $Node) { return $null }
    switch ([string]$Node.node) {
        "IDENT" {
            $name = [string]$Node.name
            if ($null -ne $LocalExprs -and $LocalExprs.ContainsKey($name)) { return $LocalExprs[$name] }
            if ($null -ne $ParamExprs -and $ParamExprs.ContainsKey($name)) { return $ParamExprs[$name] }
            return $Node
        }
        "DOT_ACCESS" {
            if ($null -ne $Node.obj -and [string]$Node.obj.node -eq "IDENT" -and [string]$Node.obj.name -eq "self") {
                return [pscustomobject]@{ node = "DOT_ACCESS"; obj = $ObjectExpr; prop = [string]$Node.prop }
            }
            return [pscustomobject]@{
                node = "DOT_ACCESS"
                obj = Resolve-WasmAstExprWithMethodContext ($Node.obj) $ObjectExpr $ParamExprs $LocalExprs $ClassName
                prop = [string]$Node.prop
            }
        }
        "INDEX" {
            $resolvedObj = if ($null -ne $Node.obj -and [string]$Node.obj.node -eq "IDENT" -and [string]$Node.obj.name -eq "self") {
                $ObjectExpr
            } else {
                Resolve-WasmAstExprWithMethodContext ($Node.obj) $ObjectExpr $ParamExprs $LocalExprs $ClassName
            }
            return [pscustomobject]@{
                node = "INDEX"
                obj = $resolvedObj
                key = Resolve-WasmAstExprWithMethodContext ($Node.key) $ObjectExpr $ParamExprs $LocalExprs $ClassName
            }
        }
        "TERNARY" {
            return [pscustomobject]@{
                node = "TERNARY"
                cond = Resolve-WasmAstExprWithMethodContext ($Node.cond) $ObjectExpr $ParamExprs $LocalExprs $ClassName
                then = Resolve-WasmAstExprWithMethodContext ($Node.then) $ObjectExpr $ParamExprs $LocalExprs $ClassName
                'else' = Resolve-WasmAstExprWithMethodContext ($Node.else) $ObjectExpr $ParamExprs $LocalExprs $ClassName
            }
        }
        "BIN_OP" {
            return [pscustomobject]@{
                node = "BIN_OP"
                op = [string]$Node.op
                left = Resolve-WasmAstExprWithMethodContext ($Node.left) $ObjectExpr $ParamExprs $LocalExprs $ClassName
                right = Resolve-WasmAstExprWithMethodContext ($Node.right) $ObjectExpr $ParamExprs $LocalExprs $ClassName
            }
        }
        "UNARY_OP" {
            return [pscustomobject]@{
                node = "UNARY_OP"
                op = [string]$Node.op
                operand = Resolve-WasmAstExprWithMethodContext ($Node.operand) $ObjectExpr $ParamExprs $LocalExprs $ClassName
            }
        }
        "CALL" {
            $args = New-Object System.Collections.Generic.List[object]
            foreach ($arg in @(As-WasmAstArray ($Node.args))) {
                $args.Add((Resolve-WasmAstExprWithMethodContext $arg $ObjectExpr $ParamExprs $LocalExprs $ClassName)) | Out-Null
            }
            return [pscustomobject]@{ node = "CALL"; name = [string]$Node.name; args = @($args.ToArray()) }
        }
        "METHOD_CALL" {
            $args = New-Object System.Collections.Generic.List[object]
            foreach ($arg in @(As-WasmAstArray ($Node.args))) {
                $args.Add((Resolve-WasmAstExprWithMethodContext $arg $ObjectExpr $ParamExprs $LocalExprs $ClassName)) | Out-Null
            }
            return [pscustomobject]@{
                node = "METHOD_CALL"
                obj = Resolve-WasmAstExprWithMethodContext ($Node.obj) $ObjectExpr $ParamExprs $LocalExprs $ClassName
                method = [string]$Node.method
                args = @($args.ToArray())
            }
        }
        "SUPER_CALL" {
            $methodName = [string]$Node.method
            if (-not [string]::IsNullOrWhiteSpace($ClassName) -and $methodName -ne "init") {
                $methodInfo = Get-WasmAstSuperClassMethod -ClassName $ClassName -MethodName $methodName
                if ($null -ne $methodInfo) {
                    $superParamExprs = @{}
                    $params = @(Get-WasmAstParamNames ($methodInfo.Method.params))
                    $args = @(As-WasmAstArray ($Node.args))
                    for ($i = 0; $i -lt $params.Count -and $i -lt $args.Count; $i++) {
                        $superParamExprs[[string]$params[$i]] = Resolve-WasmAstExprWithMethodContext $args[$i] $ObjectExpr $ParamExprs $LocalExprs $ClassName
                    }
                    $resolved = Resolve-WasmAstMethodBodyReturnExpr ($methodInfo.Method.body) $ObjectExpr $superParamExprs @{} ([string]$methodInfo.ClassName)
                    if ($null -ne $resolved) { return $resolved }
                }
            }

            $resolvedArgs = New-Object System.Collections.Generic.List[object]
            foreach ($arg in @(As-WasmAstArray ($Node.args))) {
                $resolvedArgs.Add((Resolve-WasmAstExprWithMethodContext $arg $ObjectExpr $ParamExprs $LocalExprs $ClassName)) | Out-Null
            }
            return [pscustomobject]@{ node = "SUPER_CALL"; method = $methodName; args = @($resolvedArgs.ToArray()) }
        }
        "ARRAY_LIT" {
            $items = New-Object System.Collections.Generic.List[object]
            foreach ($item in @(As-WasmAstArray ($Node.elements))) {
                $items.Add((Resolve-WasmAstExprWithMethodContext $item $ObjectExpr $ParamExprs $LocalExprs $ClassName)) | Out-Null
            }
            return [pscustomobject]@{ node = "ARRAY_LIT"; elements = @($items.ToArray()) }
        }
        "DICT_LIT" {
            $entries = New-Object System.Collections.Generic.List[object]
            foreach ($entry in @(As-WasmAstArray ($Node.entries))) {
                $entries.Add([pscustomobject]@{
                    key = [string]$entry.key
                    value = Resolve-WasmAstExprWithMethodContext ($entry.value) $ObjectExpr $ParamExprs $LocalExprs $ClassName
                }) | Out-Null
            }
            return [pscustomobject]@{ node = "DICT_LIT"; entries = @($entries.ToArray()) }
        }
        default { return $Node }
    }
}

function Get-WasmAstKnownStringLiteralInfo {
    param($Node)

    if ($null -eq $Node) { return [pscustomobject]@{ Known = $false; Value = "" } }
    if ([string]$Node.node -eq "STR_LIT") {
        return [pscustomobject]@{ Known = $true; Value = [string]$Node.value }
    }
    $value = Get-WasmAstKnownStringLiteralValue $Node
    if (-not [string]::IsNullOrWhiteSpace($value)) {
        return [pscustomobject]@{ Known = $true; Value = $value }
    }
    return [pscustomobject]@{ Known = $false; Value = "" }
}

function Get-WasmAstLiteralMatchState {
    param(
        $Subject,
        $Pattern,
        $RangeEnd = $null,
        [bool]$IsRange = $false
    )

    if ($IsRange) {
        $subjectNum = Get-WasmAstKnownNumericLiteralValue $Subject
        $startNum = Get-WasmAstKnownNumericLiteralValue $Pattern
        $endNum = Get-WasmAstKnownNumericLiteralValue $RangeEnd
        if ($null -eq $subjectNum -or $null -eq $startNum -or $null -eq $endNum) { return "unknown" }
        if ([double]$subjectNum -ge [double]$startNum -and [double]$subjectNum -le [double]$endNum) { return "true" }
        return "false"
    }

    $subjectNum = Get-WasmAstKnownNumericLiteralValue $Subject
    $patternNum = Get-WasmAstKnownNumericLiteralValue $Pattern
    if ($null -ne $subjectNum -and $null -ne $patternNum) {
        if ([double]$subjectNum -eq [double]$patternNum) { return "true" }
        return "false"
    }

    $subjectString = Get-WasmAstKnownStringLiteralInfo $Subject
    $patternString = Get-WasmAstKnownStringLiteralInfo $Pattern
    if ([bool]$subjectString.Known -and [bool]$patternString.Known) {
        if ([string]$subjectString.Value -eq [string]$patternString.Value) { return "true" }
        return "false"
    }

    $subjectBool = Get-WasmAstKnownBoolLiteralState $Subject
    $patternBool = Get-WasmAstKnownBoolLiteralState $Pattern
    if (-not [string]::IsNullOrWhiteSpace($subjectBool) -and -not [string]::IsNullOrWhiteSpace($patternBool)) {
        if ($subjectBool -eq $patternBool) { return "true" }
        return "false"
    }

    $subjectNil = ($null -ne $Subject -and [string]$Subject.node -eq "NIL_LIT")
    $patternNil = ($null -ne $Pattern -and [string]$Pattern.node -eq "NIL_LIT")
    if ($subjectNil -or $patternNil) {
        if ($subjectNil -and $patternNil) { return "true" }
        return "false"
    }

    return "unknown"
}

function Resolve-WasmAstMethodBodyReturnExpr {
    param($Body, $ObjectExpr, [hashtable]$ParamExprs, [hashtable]$LocalExprs, [string]$ClassName = "")

    if ($null -eq $Body) { return $null }
    foreach ($stmt in @(As-WasmAstArray ($Body.body))) {
        if ($null -eq $stmt) { continue }
        switch ([string]$stmt.node) {
            "ASSIGN" {
                $LocalExprs[[string]$stmt.name] = Resolve-WasmAstExprWithMethodContext ($stmt.value) $ObjectExpr $ParamExprs $LocalExprs $ClassName
            }
            "RETURN" {
                return (Resolve-WasmAstExprWithMethodContext ($stmt.value) $ObjectExpr $ParamExprs $LocalExprs $ClassName)
            }
            "SuraBlock" {
                $nested = Resolve-WasmAstMethodBodyReturnExpr $stmt $ObjectExpr $ParamExprs $LocalExprs $ClassName
                if ($null -ne $nested) { return $nested }
            }
            "IF" {
                $cond = Resolve-WasmAstExprWithMethodContext ($stmt.cond) $ObjectExpr $ParamExprs $LocalExprs $ClassName
                $condState = Get-WasmAstKnownBoolLiteralState $cond
                if ($condState -eq "true") {
                    return (Resolve-WasmAstMethodBodyReturnExpr ($stmt.then_block) $ObjectExpr $ParamExprs (Copy-WasmAstStringObjectMap $LocalExprs) $ClassName)
                }
                if ($condState -eq "false") {
                    return (Resolve-WasmAstMethodBodyReturnExpr ($stmt.else_block) $ObjectExpr $ParamExprs (Copy-WasmAstStringObjectMap $LocalExprs) $ClassName)
                }
                return $null
            }
            "MATCH" {
                $subject = Resolve-WasmAstExprWithMethodContext ($stmt.subject) $ObjectExpr $ParamExprs $LocalExprs $ClassName
                foreach ($arm in @(As-WasmAstArray ($stmt.arms))) {
                    if ([bool]$arm.is_wildcard) {
                        return (Resolve-WasmAstMethodBodyReturnExpr ($arm.body) $ObjectExpr $ParamExprs (Copy-WasmAstStringObjectMap $LocalExprs) $ClassName)
                    }
                    $pattern = Resolve-WasmAstExprWithMethodContext ($arm.pattern) $ObjectExpr $ParamExprs $LocalExprs $ClassName
                    $rangeEnd = Resolve-WasmAstExprWithMethodContext ($arm.range_end) $ObjectExpr $ParamExprs $LocalExprs $ClassName
                    $matchState = Get-WasmAstLiteralMatchState $subject $pattern $rangeEnd ([bool]$arm.is_range)
                    if ($matchState -eq "true") {
                        return (Resolve-WasmAstMethodBodyReturnExpr ($arm.body) $ObjectExpr $ParamExprs (Copy-WasmAstStringObjectMap $LocalExprs) $ClassName)
                    }
                    if ($matchState -eq "unknown") { return $null }
                }
                return $null
            }
            default { }
        }
    }
    return $null
}

function Resolve-WasmAstFunctionCallReturnExpr {
    param($Node)

    if ($null -eq $Node -or [string]$Node.node -ne "CALL") { return $null }
    $name = [string]$Node.name
    if ([string]::IsNullOrWhiteSpace($name) -or -not $script:wasmAstFunctionDefs.ContainsKey($name)) { return $null }
    $fn = $script:wasmAstFunctionDefs[$name]
    $paramExprs = @{}
    $params = @(Get-WasmAstParamNames ($fn.Node.params))
    $args = @(As-WasmAstArray ($Node.args))
    for ($i = 0; $i -lt $params.Count -and $i -lt $args.Count; $i++) {
        $paramExprs[[string]$params[$i]] = $args[$i]
    }
    return (Resolve-WasmAstMethodBodyReturnExpr ($fn.Node.body) $null $paramExprs @{} "")
}

function Resolve-WasmAstMethodCallReturnExpr {
    param($Node)

    if ($null -eq $Node -or [string]$Node.node -ne "METHOD_CALL" -or $null -eq $Node.obj) { return $null }
    $className = Get-WasmAstObjectClassTypeWithLocals ($Node.obj) $script:wasmCurrentLocalObjectClassHints $script:wasmCurrentClassContext @{}
    if ([string]::IsNullOrWhiteSpace($className)) { return $null }
    $methodInfo = Get-WasmAstClassMethod -ClassName $className -MethodName ([string]$Node.method)
    if ($null -eq $methodInfo) { return $null }
    $paramExprs = @{}
    $params = @(Get-WasmAstParamNames ($methodInfo.Method.params))
    $args = @(As-WasmAstArray ($Node.args))
    for ($i = 0; $i -lt $params.Count -and $i -lt $args.Count; $i++) {
        $paramExprs[[string]$params[$i]] = $args[$i]
    }
    return (Resolve-WasmAstMethodBodyReturnExpr ($methodInfo.Method.body) ($Node.obj) $paramExprs @{} ([string]$methodInfo.ClassName))
}

function Convert-WasmAstToStringExprWithMethodContext {
    param($Node, $ObjectExpr, [hashtable]$ParamExprs, [hashtable]$LocalExprs, [string]$ClassName = "")

    $resolved = Resolve-WasmAstExprWithMethodContext $Node $ObjectExpr $ParamExprs $LocalExprs $ClassName
    if ($null -ne $resolved -and [string]$resolved.node -eq "TERNARY") {
        $thenCode = @(Convert-WasmAstToStringExprWithMethodContext ($resolved.then) $ObjectExpr $ParamExprs $LocalExprs $ClassName)
        $elseCode = @(Convert-WasmAstToStringExprWithMethodContext ($resolved.else) $ObjectExpr $ParamExprs $LocalExprs $ClassName)
        if ($thenCode.Count -eq 0 -or $elseCode.Count -eq 0) { return @() }
        return @(
            @(Convert-WasmAstConditionExpr ($resolved.cond)) +
            @("if (result i32)") +
            $thenCode +
            @("else") +
            $elseCode +
            @("end")
        )
    }
    if (Test-WasmAstKnownEmptyArrayExpr $resolved) { return @(New-WasmAstLiteralStringExprCode "[]") }
    if (Test-WasmAstKnownEmptyDictExpr $resolved) { return @(New-WasmAstLiteralStringExprCode "{}") }
    return @(Convert-WasmAstToStringExpr $resolved)
}

function Convert-WasmAstMethodBodyReturnToStringExpr {
    param($Body, $ObjectExpr, [hashtable]$ParamExprs, [hashtable]$LocalExprs, [string]$ClassName = "")

    if ($null -eq $Body) { return @() }
    foreach ($stmt in @(As-WasmAstArray ($Body.body))) {
        if ($null -eq $stmt) { continue }
        switch ([string]$stmt.node) {
            "ASSIGN" {
                $LocalExprs[[string]$stmt.name] = Resolve-WasmAstExprWithMethodContext ($stmt.value) $ObjectExpr $ParamExprs $LocalExprs $ClassName
            }
            "RETURN" {
                return @(Convert-WasmAstToStringExprWithMethodContext ($stmt.value) $ObjectExpr $ParamExprs $LocalExprs $ClassName)
            }
            "SuraBlock" {
                $nested = @(Convert-WasmAstMethodBodyReturnToStringExpr $stmt $ObjectExpr $ParamExprs $LocalExprs $ClassName)
                if ($nested.Count -gt 0) { return $nested }
            }
            "IF" {
                $thenLocals = Copy-WasmAstStringObjectMap $LocalExprs
                $elseLocals = Copy-WasmAstStringObjectMap $LocalExprs
                $thenCode = @(Convert-WasmAstMethodBodyReturnToStringExpr ($stmt.then_block) $ObjectExpr $ParamExprs $thenLocals $ClassName)
                $elseCode = @(Convert-WasmAstMethodBodyReturnToStringExpr ($stmt.else_block) $ObjectExpr $ParamExprs $elseLocals $ClassName)
                if ($thenCode.Count -gt 0 -and $elseCode.Count -gt 0) {
                    return @(
                        @(Convert-WasmAstConditionExpr (Resolve-WasmAstExprWithMethodContext ($stmt.cond) $ObjectExpr $ParamExprs $LocalExprs $ClassName)) +
                        @("if (result i32)") +
                        $thenCode +
                        @("else") +
                        $elseCode +
                        @("end")
                    )
                }
            }
            default { }
        }
    }
    return @()
}

function Convert-WasmAstMethodReturnToStringExpr {
    param($Node)

    if ($null -eq $Node -or [string]$Node.node -ne "METHOD_CALL" -or $null -eq $Node.obj) { return @() }
    try {
        $className = Get-WasmAstObjectClassTypeWithLocals ($Node.obj) $script:wasmCurrentLocalObjectClassHints $script:wasmCurrentClassContext @{}
        if ([string]::IsNullOrWhiteSpace($className)) { return @() }
        $methodInfo = Get-WasmAstClassMethod -ClassName $className -MethodName ([string]$Node.method)
        if ($null -eq $methodInfo) { return @() }
        $paramExprs = @{}
        $params = @(Get-WasmAstParamNames ($methodInfo.Method.params))
        $args = @(As-WasmAstArray ($Node.args))
        for ($i = 0; $i -lt $params.Count -and $i -lt $args.Count; $i++) {
            $paramExprs[[string]$params[$i]] = $args[$i]
        }
        $resolvedReturn = Resolve-WasmAstMethodBodyReturnExpr ($methodInfo.Method.body) ($Node.obj) $paramExprs @{} ([string]$methodInfo.ClassName)
        $bodyString = @(Convert-WasmAstMethodBodyReturnToStringExpr ($methodInfo.Method.body) ($Node.obj) $paramExprs @{} ([string]$methodInfo.ClassName))
        if ($bodyString.Count -gt 0 -and $null -ne $Node.obj -and [string]$Node.obj.node -eq "IDENT" -and
            (Test-WasmAstEffectfulExpr $Node) -and -not (Test-WasmAstEffectfulExpr $resolvedReturn)) {
            return @(Convert-WasmAstExpr $Node) + @("drop") + $bodyString
        }
        return $bodyString
    } catch {
        return @()
    }
}

function Convert-WasmAstFunctionReturnToStringExpr {
    param($Node)

    if ($null -eq $Node -or [string]$Node.node -ne "CALL") { return @() }
    $name = [string]$Node.name
    if ([string]::IsNullOrWhiteSpace($name) -or -not $script:wasmAstFunctionDefs.ContainsKey($name)) { return @() }
    try {
        $fn = $script:wasmAstFunctionDefs[$name]
        $paramExprs = @{}
        $params = @(Get-WasmAstParamNames ($fn.Node.params))
        $args = @(As-WasmAstArray ($Node.args))
        for ($i = 0; $i -lt $params.Count -and $i -lt $args.Count; $i++) {
            $paramExprs[[string]$params[$i]] = $args[$i]
        }
        $resolvedReturn = Resolve-WasmAstMethodBodyReturnExpr ($fn.Node.body) $null $paramExprs @{} ""
        $bodyString = @(Convert-WasmAstMethodBodyReturnToStringExpr ($fn.Node.body) $null $paramExprs @{} "")
        if ($bodyString.Count -gt 0 -and (Test-WasmAstEffectfulExpr $Node) -and -not (Test-WasmAstEffectfulExpr $resolvedReturn)) {
            return @(Convert-WasmAstExpr $Node) + @("drop") + $bodyString
        }
        return $bodyString
    } catch {
        return @()
    }
}

function Test-WasmAstLengthExprCandidate {
    param($Node)

    if ($null -eq $Node) { return $false }
    if ((Test-WasmAstRuntimeValueIndexCandidate $Node) -or (Test-WasmAstRuntimeValueDotCandidate $Node)) {
        return $true
    }
    if ([string]$Node.node -eq "TERNARY") {
        return ((Test-WasmAstLengthExprCandidate ($Node.then)) -and
            (Test-WasmAstLengthExprCandidate ($Node.else)))
    }
    $typeName = Get-WasmAstKnownValueType $Node
    if ([string]::IsNullOrWhiteSpace($typeName)) {
        $typeName = Get-WasmAstStaticValueType $Node
    }
    return ($typeName -in @("string", "array", "dict", "value"))
}

function Convert-WasmAstLengthExpr {
    param($Node)

    if (Test-WasmAstLengthExprCandidate $Node) {
        return @(Convert-WasmAstValueExpr $Node) + @("call `$__sura_value_length")
    }

    $typeName = Get-WasmAstKnownValueType $Node
    if ([string]::IsNullOrWhiteSpace($typeName)) {
        $typeName = Get-WasmAstStaticValueType $Node
    }
    if ($typeName -notin @("string", "array", "dict")) {
        $nodeKind = if ($null -eq $Node) { "<null>" } else { [string]$Node.node }
        $lineInfo = if ($null -ne $Node -and $Node.PSObject.Properties.Name -contains "line") { " at line $([int]$Node.line)" } else { "" }
        $nodeSummary = try { $Node | ConvertTo-Json -Compress -Depth 6 } catch { "" }
        throw "unsupported WASM AST length() argument type '$typeName' for $nodeKind${lineInfo}: $nodeSummary"
    }
    return @(Convert-WasmAstExpr $Node) + @("i32.const 4", "i32.sub", "i32.load")
}

function Test-WasmAstPrimitiveToStringValueCandidate {
    param($Node)

    if ($null -eq $Node) { return $true }
    if (Test-WasmAstStringIndexExpr $Node) { return $true }
    if ([string]$Node.node -eq "TERNARY") {
        return ((Test-WasmAstPrimitiveToStringValueCandidate ($Node.then)) -and
            (Test-WasmAstPrimitiveToStringValueCandidate ($Node.else)))
    }
    if (-not [string]::IsNullOrWhiteSpace((Get-WasmAstObjectClassTypeHint $Node))) { return $false }

    $typeName = Get-WasmAstKnownValueType $Node
    if ([string]::IsNullOrWhiteSpace($typeName)) {
        $typeName = Get-WasmAstStaticValueType $Node
    }
    if ($typeName -eq "value") { return $true }
    return ($typeName -in @("string", "bool", "nil", "num"))
}

function Convert-WasmAstToStringExpr {
    param($Node)

    $functionName = Get-WasmAstKnownFunctionDisplayName $Node
    if (-not [string]::IsNullOrWhiteSpace($functionName)) {
        if (Test-WasmAstEffectfulExpr $Node) {
            return @(Convert-WasmAstExpr $Node) + @("drop") + @(New-WasmStringLiteralExprCode -Literal (Convert-WasmAstStringLiteral ("<Func $functionName>")))
        }
        return @(New-WasmStringLiteralExprCode -Literal (Convert-WasmAstStringLiteral ("<Func $functionName>")))
    }
    if ($null -ne $Node -and [string]$Node.node -eq "BIN_OP" -and [string]$Node.op -eq "??") {
        $coalesceType = Get-WasmAstKnownValueType $Node
        if ([string]::IsNullOrWhiteSpace($coalesceType)) {
            $coalesceType = Get-WasmAstStaticValueType $Node
        }
        if ($coalesceType -eq "array") {
            $elementType = Get-WasmAstArrayElementTypeHint $Node
            switch ([string]$elementType) {
                "num" { return @(Convert-WasmAstExpr $Node) + @("call `$__sura_array_to_string_num") }
                "string" { return @(Convert-WasmAstExpr $Node) + @("call `$__sura_array_to_string_string") }
                "bool" { return @(Convert-WasmAstExpr $Node) + @("call `$__sura_array_to_string_bool") }
                "nil" { return @(Convert-WasmAstExpr $Node) + @("call `$__sura_array_to_string_nil") }
            }
            $indexedCoalesceString = @(Convert-WasmAstIndexedArrayToStringExpr $Node)
            if ($indexedCoalesceString.Count -gt 0) { return $indexedCoalesceString }
        }
        if ($coalesceType -eq "dict") {
            $orderedCoalesceString = @(Convert-WasmAstOrderedDictToStringExpr $Node)
            if ($orderedCoalesceString.Count -gt 0) { return $orderedCoalesceString }
        }
    }
    if (Test-WasmAstRuntimeValueCollectionLiteralCandidate $Node) {
        return @(Convert-WasmAstValueExpr $Node) + @("call `$__sura_value_to_string")
    }
    if ((Test-WasmAstRuntimeValueIndexCandidate $Node) -or (Test-WasmAstRuntimeValueDotCandidate $Node)) {
        return @(Convert-WasmAstValueExpr $Node) + @("call `$__sura_value_to_string")
    }
    $exactIndexedAccessString = @(Convert-WasmAstExactIndexedArrayAccessToStringExpr $Node)
    if ($exactIndexedAccessString.Count -gt 0) {
        return $exactIndexedAccessString
    }
    if (Test-WasmAstPrimitiveToStringValueCandidate $Node) {
        return @(Convert-WasmAstValueExpr $Node) + @("call `$__sura_value_to_string")
    }
    if ($null -ne $Node -and [string]$Node.node -eq "ARRAY_LIT") {
        return @(Convert-WasmAstArrayLiteralToStringExpr $Node)
    }
    if ($null -ne $Node -and [string]$Node.node -eq "DICT_LIT") {
        return @(Convert-WasmAstDictLiteralToStringExpr $Node)
    }
    if (Test-WasmAstKnownEmptyArrayExpr $Node) {
        return @(New-WasmAstLiteralStringExprCode "[]")
    }
    if (Test-WasmAstKnownEmptyDictExpr $Node) {
        return @(New-WasmAstLiteralStringExprCode "{}")
    }
    if ($null -ne $Node -and [string]$Node.node -eq "TERNARY" -and
        (Test-WasmAstStringifiedValueCandidate ($Node.then)) -and
        (Test-WasmAstStringifiedValueCandidate ($Node.else))) {
        $condCode = @(Convert-WasmAstConditionExpr ($Node.cond))
        $thenCode = @(Convert-WasmAstToStringExpr ($Node.then))
        $elseCode = @(Convert-WasmAstToStringExpr ($Node.else))
        return @(
            $condCode +
            @("if (result i32)") +
            $thenCode +
            @("else") +
            $elseCode +
            @("end")
        )
    }

    $typeName = Get-WasmAstKnownValueType $Node
    if ([string]::IsNullOrWhiteSpace($typeName)) {
        $typeName = Get-WasmAstStaticValueType $Node
    }
    if ($typeName -notin @("string", "bool", "nil", "num")) {
        if ($typeName -eq "function") {
            return @(Convert-WasmAstValueExpr $Node) + @("call `$__sura_value_to_string")
        }
        if ($typeName -eq "array") {
            $elementType = Get-WasmAstArrayElementTypeHint $Node
            switch ([string]$elementType) {
                "num" { return @(Convert-WasmAstExpr $Node) + @("call `$__sura_array_to_string_num") }
                "string" { return @(Convert-WasmAstExpr $Node) + @("call `$__sura_array_to_string_string") }
                "bool" { return @(Convert-WasmAstExpr $Node) + @("call `$__sura_array_to_string_bool") }
                "nil" { return @(Convert-WasmAstExpr $Node) + @("call `$__sura_array_to_string_nil") }
            }
            $indexedString = @(Convert-WasmAstIndexedArrayToStringExpr $Node)
            if ($indexedString.Count -gt 0) { return $indexedString }
            return @(Convert-WasmAstValueExpr $Node) + @("call `$__sura_value_to_string")
        }
        if ($typeName -eq "dict") {
            $orderedDictString = @(Convert-WasmAstOrderedDictToStringExpr $Node)
            if ($orderedDictString.Count -gt 0) { return $orderedDictString }
            return @(Convert-WasmAstValueExpr $Node) + @("call `$__sura_value_to_string")
        }
        $functionReturnString = @(Convert-WasmAstFunctionReturnToStringExpr $Node)
        if ($functionReturnString.Count -gt 0) { return $functionReturnString }
        $methodReturnString = @(Convert-WasmAstMethodReturnToStringExpr $Node)
        if ($methodReturnString.Count -gt 0) { return $methodReturnString }
        if ([string]::IsNullOrWhiteSpace($typeName)) {
            return @(Convert-WasmAstValueExpr $Node) + @("call `$__sura_value_to_string")
        }
        $nodeKind = if ($null -eq $Node) { "<null>" } else { [string]$Node.node }
        $nodeJson = try { ($Node | ConvertTo-Json -Depth 6 -Compress) } catch { "" }
        throw "unsupported WASM AST to_str() argument type: $typeName for ${nodeKind}: $nodeJson"
    }
    return @(Convert-WasmAstStringExpr $Node)
}

function Get-WasmAstTryThrowPayloadType {
    param($Body, [hashtable]$Seen = @{}, [string]$ClassName = "", [hashtable]$ParamTypes = @{})

    $types = New-Object System.Collections.Generic.List[string]
    function Add-WasmAstThrowPayloadType {
        param([string]$TypeName)
        if ($TypeName -in @("string", "bool", "nil", "num", "array", "dict", "function")) {
            $types.Add($TypeName) | Out-Null
        }
    }
    function Visit-WasmAstThrowPayloadExpr {
        param($Expr)
        if ($null -eq $Expr) { return }
        switch ([string]$Expr.node) {
            "CALL" {
                $name = [string]$Expr.name
                if ($script:wasmAstFunctionDefs.ContainsKey($name)) {
                    $seenKey = "func:$name"
                    if (-not $Seen.ContainsKey($seenKey)) {
                        $Seen[$seenKey] = $true
                        $fn = $script:wasmAstFunctionDefs[$name]
                        if ($null -ne $fn.Node -and $null -ne $fn.Node.body) {
                            $callParamTypes = @{}
                            $params = @(Get-WasmAstParamNames ($fn.Node.params))
                            $args = @(As-WasmAstArray ($Expr.args))
                            for ($i = 0; $i -lt $params.Count -and $i -lt $args.Count; $i++) {
                                $argType = Get-WasmAstStaticValueTypeWithParams ($args[$i]) $ParamTypes
                                if ($argType -in @("string", "bool", "nil", "num", "array", "dict", "function")) {
                                    $callParamTypes[[string]$params[$i]] = $argType
                                }
                            }
                            Add-WasmAstThrowPayloadType (Get-WasmAstTryThrowPayloadType ($fn.Node.body) $Seen "" $callParamTypes)
                        }
                    }
                }
                foreach ($arg in @(As-WasmAstArray ($Expr.args))) { Visit-WasmAstThrowPayloadExpr $arg }
            }
            "METHOD_CALL" {
                $methodClassName = Get-WasmAstObjectClassTypeHint ($Expr.obj)
                if (-not [string]::IsNullOrWhiteSpace($methodClassName)) {
                    $methodInfo = Get-WasmAstClassMethod -ClassName $methodClassName -MethodName ([string]$Expr.method)
                    if ($null -ne $methodInfo) {
                        $seenKey = "method:$([string]$methodInfo.ClassName).$([string]$Expr.method)"
                        if (-not $Seen.ContainsKey($seenKey)) {
                            $Seen[$seenKey] = $true
                            $methodParamTypes = @{}
                            $params = @(Get-WasmAstParamNames ($methodInfo.Method.params))
                            $args = @(As-WasmAstArray ($Expr.args))
                            for ($i = 0; $i -lt $params.Count -and $i -lt $args.Count; $i++) {
                                $argType = Get-WasmAstStaticValueTypeWithParams ($args[$i]) $ParamTypes
                                if ($argType -in @("string", "bool", "nil", "num", "array", "dict", "function")) {
                                    $methodParamTypes[[string]$params[$i]] = $argType
                                }
                            }
                            Add-WasmAstThrowPayloadType (Get-WasmAstTryThrowPayloadType ($methodInfo.Method.body) $Seen ([string]$methodInfo.ClassName) $methodParamTypes)
                        }
                    }
                }
                Visit-WasmAstThrowPayloadExpr ($Expr.obj)
                foreach ($arg in @(As-WasmAstArray ($Expr.args))) { Visit-WasmAstThrowPayloadExpr $arg }
            }
            "SUPER_CALL" {
                if (-not [string]::IsNullOrWhiteSpace($ClassName)) {
                    $methodInfo = Get-WasmAstSuperClassMethod -ClassName $ClassName -MethodName ([string]$Expr.method)
                    if ($null -ne $methodInfo) {
                        $seenKey = "super:$ClassName->$([string]$methodInfo.ClassName).$([string]$Expr.method)"
                        if (-not $Seen.ContainsKey($seenKey)) {
                            $Seen[$seenKey] = $true
                            $methodParamTypes = @{}
                            $params = @(Get-WasmAstParamNames ($methodInfo.Method.params))
                            $args = @(As-WasmAstArray ($Expr.args))
                            for ($i = 0; $i -lt $params.Count -and $i -lt $args.Count; $i++) {
                                $argType = Get-WasmAstStaticValueTypeWithClassSelf ($args[$i]) $ClassName $ParamTypes
                                if ($argType -in @("string", "bool", "nil", "num", "array", "dict", "function")) {
                                    $methodParamTypes[[string]$params[$i]] = $argType
                                }
                            }
                            Add-WasmAstThrowPayloadType (Get-WasmAstTryThrowPayloadType ($methodInfo.Method.body) $Seen ([string]$methodInfo.ClassName) $methodParamTypes)
                        }
                    }
                }
                foreach ($arg in @(As-WasmAstArray ($Expr.args))) { Visit-WasmAstThrowPayloadExpr $arg }
            }
            "BIN_OP" {
                Visit-WasmAstThrowPayloadExpr ($Expr.left)
                Visit-WasmAstThrowPayloadExpr ($Expr.right)
            }
            "UNARY_OP" { Visit-WasmAstThrowPayloadExpr ($Expr.operand) }
            "TERNARY" {
                Visit-WasmAstThrowPayloadExpr ($Expr.cond)
                Visit-WasmAstThrowPayloadExpr ($Expr.then)
                Visit-WasmAstThrowPayloadExpr ($Expr.else)
            }
            "DOT_ACCESS" { Visit-WasmAstThrowPayloadExpr ($Expr.obj) }
            "INDEX" {
                Visit-WasmAstThrowPayloadExpr ($Expr.obj)
                Visit-WasmAstThrowPayloadExpr ($Expr.key)
            }
            "ARRAY_LIT" {
                foreach ($item in @(As-WasmAstArray ($Expr.elements))) { Visit-WasmAstThrowPayloadExpr $item }
            }
            "DICT_LIT" {
                foreach ($entry in @(As-WasmAstArray ($Expr.entries))) { Visit-WasmAstThrowPayloadExpr ($entry.value) }
            }
            "NEW_EXPR" {
                foreach ($arg in @(As-WasmAstArray ($Expr.args))) { Visit-WasmAstThrowPayloadExpr $arg }
            }
            "STR_INTERP" {
                foreach ($part in @(As-WasmAstArray ($Expr.parts))) { Visit-WasmAstThrowPayloadExpr $part }
            }
            default { }
        }
    }
    function Visit-WasmAstThrowPayloadStmt {
        param($Stmt)
        if ($null -eq $Stmt) { return }
        switch ([string]$Stmt.node) {
            "SuraBlock" {
                foreach ($child in @(As-WasmAstArray ($Stmt.body))) { Visit-WasmAstThrowPayloadStmt $child }
            }
            "THROW" {
                if (-not [string]::IsNullOrWhiteSpace($ClassName)) {
                    Add-WasmAstThrowPayloadType (Get-WasmAstStaticValueTypeWithClassSelf ($Stmt.msg) $ClassName $ParamTypes)
                } else {
                    Add-WasmAstThrowPayloadType (Get-WasmAstStaticValueTypeWithParams ($Stmt.msg) $ParamTypes)
                }
            }
            "ASSIGN" {
                $name = [string]$Stmt.name
                if (-not [string]::IsNullOrWhiteSpace($name)) {
                    $assignedType = if (-not [string]::IsNullOrWhiteSpace($ClassName)) {
                        Get-WasmAstStaticValueTypeWithClassSelf ($Stmt.value) $ClassName $ParamTypes
                    } else {
                        Get-WasmAstStaticValueTypeWithParams ($Stmt.value) $ParamTypes
                    }
                    if ($assignedType -in @("string", "bool", "nil", "num", "array", "dict", "function")) {
                        $ParamTypes[$name] = $assignedType
                    } elseif ($ParamTypes.ContainsKey($name)) {
                        [void]$ParamTypes.Remove($name)
                    }
                }
                Visit-WasmAstThrowPayloadExpr ($Stmt.value)
            }
            "IN_PLACE" {
                Visit-WasmAstThrowPayloadExpr ($Stmt.value)
            }
            "DOT_ASSIGN" {
                Visit-WasmAstThrowPayloadExpr ($Stmt.value)
            }
            "INDEX_ASSIGN" {
                Visit-WasmAstThrowPayloadExpr ($Stmt.key)
                Visit-WasmAstThrowPayloadExpr ($Stmt.value)
            }
            "EXPR_STMT" {
                Visit-WasmAstThrowPayloadExpr ($Stmt.expr)
            }
            "RETURN" {
                Visit-WasmAstThrowPayloadExpr ($Stmt.value)
            }
            "IF" {
                Visit-WasmAstThrowPayloadExpr ($Stmt.cond)
                Visit-WasmAstThrowPayloadStmt ($Stmt.then_block)
                Visit-WasmAstThrowPayloadStmt ($Stmt.else_block)
            }
            "WHILE" {
                Visit-WasmAstThrowPayloadExpr ($Stmt.cond)
                Visit-WasmAstThrowPayloadStmt ($Stmt.body)
            }
            "REPEAT" {
                Visit-WasmAstThrowPayloadExpr ($Stmt.count)
                Visit-WasmAstThrowPayloadStmt ($Stmt.body)
            }
            "FOR" {
                Visit-WasmAstThrowPayloadExpr ($Stmt.from)
                Visit-WasmAstThrowPayloadExpr ($Stmt.to)
                Visit-WasmAstThrowPayloadExpr ($Stmt.step)
                Visit-WasmAstThrowPayloadStmt ($Stmt.body)
            }
            "FOREACH" {
                Visit-WasmAstThrowPayloadExpr ($Stmt.collection)
                Visit-WasmAstThrowPayloadStmt ($Stmt.body)
            }
            "MATCH" {
                Visit-WasmAstThrowPayloadExpr ($Stmt.subject)
                foreach ($arm in @(As-WasmAstArray ($Stmt.arms))) { Visit-WasmAstThrowPayloadStmt ($arm.body) }
            }
            "TRY" {
                if ($null -eq $Stmt.catch_block) {
                    Visit-WasmAstThrowPayloadStmt ($Stmt.try_block)
                } else {
                    Visit-WasmAstThrowPayloadStmt ($Stmt.catch_block)
                }
                Visit-WasmAstThrowPayloadStmt ($Stmt.finally_block)
            }
            default { }
        }
    }
    Visit-WasmAstThrowPayloadStmt $Body
    if ($types.Count -eq 0) { return "" }
    return (Get-WasmAstCommonTypeName ([string[]]$types.ToArray()))
}

function Get-WasmAstTryThrowPayloadObjectInfo {
    param(
        $Body,
        [hashtable]$Seen = @{},
        [string]$ClassName = "",
        [hashtable]$LocalObjectHints = @{}
    )

    $state = @{
        SawThrow = $false
        SawNonObject = $false
        Classes = @{}
    }

    function Merge-WasmAstThrowObjectInfo {
        param($Info)
        if ($null -eq $Info -or -not [bool]$Info.HasThrows) { return }
        $state.SawThrow = $true
        if (-not [bool]$Info.AllObjects) {
            $state.SawNonObject = $true
            return
        }
        foreach ($name in @(Get-WasmAstObjectClassNamesFromHint ([string]$Info.ClassHint))) {
            if ($script:wasmClassDefs.ContainsKey([string]$name)) {
                $state.Classes[[string]$name] = $true
            }
        }
    }

    function Visit-WasmAstThrowObjectExpr {
        param($Expr, [hashtable]$ObjectHints)
        if ($null -eq $Expr) { return }
        switch ([string]$Expr.node) {
            "CALL" {
                $name = [string]$Expr.name
                if ($script:wasmAstFunctionDefs.ContainsKey($name)) {
                    $seenKey = "func-object-throw:$name"
                    if (-not $Seen.ContainsKey($seenKey)) {
                        $Seen[$seenKey] = $true
                        try {
                            $fn = $script:wasmAstFunctionDefs[$name]
                            if ($null -ne $fn.Node -and $null -ne $fn.Node.body) {
                                $paramObjects = Copy-WasmAstTypeHints (Get-WasmAstObservedFunctionParamObjectClassHints $name)
                                $params = @(Get-WasmAstParamNames ($fn.Node.params))
                                $args = @(As-WasmAstArray ($Expr.args))
                                for ($i = 0; $i -lt $params.Count -and $i -lt $args.Count; $i++) {
                                    $hint = Get-WasmAstObjectClassSetHintWithLocals ($args[$i]) $ObjectHints $ClassName
                                    if (-not [string]::IsNullOrWhiteSpace($hint)) {
                                        $paramObjects[[string]$params[$i]] = $hint
                                    }
                                }
                                Merge-WasmAstThrowObjectInfo (Get-WasmAstTryThrowPayloadObjectInfo ($fn.Node.body) $Seen "" $paramObjects)
                            }
                        } finally {
                            [void]$Seen.Remove($seenKey)
                        }
                    }
                }
                foreach ($arg in @(As-WasmAstArray ($Expr.args))) {
                    Visit-WasmAstThrowObjectExpr $arg $ObjectHints
                }
            }
            "METHOD_CALL" {
                $receiverHint = Get-WasmAstObjectClassSetHintWithLocals ($Expr.obj) $ObjectHints $ClassName
                foreach ($receiverClass in @(Get-WasmAstObjectClassNamesFromHint $receiverHint)) {
                    $methodInfo = Get-WasmAstClassMethod -ClassName ([string]$receiverClass) -MethodName ([string]$Expr.method)
                    if ($null -eq $methodInfo) { continue }
                    $seenKey = "method-object-throw:$([string]$methodInfo.FunctionName)"
                    if ($Seen.ContainsKey($seenKey)) { continue }
                    $Seen[$seenKey] = $true
                    try {
                        $paramObjects = Copy-WasmAstTypeHints (Get-WasmAstObservedFunctionParamObjectClassHints ([string]$methodInfo.FunctionName))
                        $params = @(Get-WasmAstParamNames ($methodInfo.Method.params))
                        $args = @(As-WasmAstArray ($Expr.args))
                        for ($i = 0; $i -lt $params.Count -and $i -lt $args.Count; $i++) {
                            $hint = Get-WasmAstObjectClassSetHintWithLocals ($args[$i]) $ObjectHints $ClassName
                            if (-not [string]::IsNullOrWhiteSpace($hint)) {
                                $paramObjects[[string]$params[$i]] = $hint
                            }
                        }
                        Merge-WasmAstThrowObjectInfo (Get-WasmAstTryThrowPayloadObjectInfo ($methodInfo.Method.body) $Seen ([string]$methodInfo.ClassName) $paramObjects)
                    } finally {
                        [void]$Seen.Remove($seenKey)
                    }
                }
                Visit-WasmAstThrowObjectExpr ($Expr.obj) $ObjectHints
                foreach ($arg in @(As-WasmAstArray ($Expr.args))) {
                    Visit-WasmAstThrowObjectExpr $arg $ObjectHints
                }
            }
            "SUPER_CALL" {
                if (-not [string]::IsNullOrWhiteSpace($ClassName)) {
                    $methodInfo = Get-WasmAstSuperClassMethod -ClassName $ClassName -MethodName ([string]$Expr.method)
                    if ($null -ne $methodInfo) {
                        $seenKey = "super-object-throw:$([string]$methodInfo.FunctionName)"
                        if (-not $Seen.ContainsKey($seenKey)) {
                            $Seen[$seenKey] = $true
                            try {
                                $paramObjects = Copy-WasmAstTypeHints (Get-WasmAstObservedFunctionParamObjectClassHints ([string]$methodInfo.FunctionName))
                                $params = @(Get-WasmAstParamNames ($methodInfo.Method.params))
                                $args = @(As-WasmAstArray ($Expr.args))
                                for ($i = 0; $i -lt $params.Count -and $i -lt $args.Count; $i++) {
                                    $hint = Get-WasmAstObjectClassSetHintWithLocals ($args[$i]) $ObjectHints $ClassName
                                    if (-not [string]::IsNullOrWhiteSpace($hint)) {
                                        $paramObjects[[string]$params[$i]] = $hint
                                    }
                                }
                                Merge-WasmAstThrowObjectInfo (Get-WasmAstTryThrowPayloadObjectInfo ($methodInfo.Method.body) $Seen ([string]$methodInfo.ClassName) $paramObjects)
                            } finally {
                                [void]$Seen.Remove($seenKey)
                            }
                        }
                    }
                }
                foreach ($arg in @(As-WasmAstArray ($Expr.args))) {
                    Visit-WasmAstThrowObjectExpr $arg $ObjectHints
                }
            }
            "BIN_OP" {
                Visit-WasmAstThrowObjectExpr ($Expr.left) $ObjectHints
                Visit-WasmAstThrowObjectExpr ($Expr.right) $ObjectHints
            }
            "UNARY_OP" { Visit-WasmAstThrowObjectExpr ($Expr.operand) $ObjectHints }
            "TERNARY" {
                Visit-WasmAstThrowObjectExpr ($Expr.cond) $ObjectHints
                Visit-WasmAstThrowObjectExpr ($Expr.then) $ObjectHints
                Visit-WasmAstThrowObjectExpr ($Expr.else) $ObjectHints
            }
            "DOT_ACCESS" { Visit-WasmAstThrowObjectExpr ($Expr.obj) $ObjectHints }
            "INDEX" {
                Visit-WasmAstThrowObjectExpr ($Expr.obj) $ObjectHints
                Visit-WasmAstThrowObjectExpr ($Expr.key) $ObjectHints
            }
            "ARRAY_LIT" {
                foreach ($item in @(As-WasmAstArray ($Expr.elements))) {
                    Visit-WasmAstThrowObjectExpr $item $ObjectHints
                }
            }
            "DICT_LIT" {
                foreach ($entry in @(As-WasmAstArray ($Expr.entries))) {
                    Visit-WasmAstThrowObjectExpr ($entry.value) $ObjectHints
                }
            }
            "NEW_EXPR" {
                foreach ($arg in @(As-WasmAstArray ($Expr.args))) {
                    Visit-WasmAstThrowObjectExpr $arg $ObjectHints
                }
            }
            "STR_INTERP" {
                foreach ($part in @(As-WasmAstArray ($Expr.parts))) {
                    Visit-WasmAstThrowObjectExpr $part $ObjectHints
                }
            }
            default { }
        }
    }

    function Visit-WasmAstThrowObjectStmt {
        param($Stmt, [hashtable]$ObjectHints)
        if ($null -eq $Stmt) { return }
        switch ([string]$Stmt.node) {
            "SuraBlock" {
                foreach ($child in @(As-WasmAstArray ($Stmt.body))) {
                    Visit-WasmAstThrowObjectStmt $child $ObjectHints
                }
            }
            "THROW" {
                $state.SawThrow = $true
                $hint = Get-WasmAstObjectClassSetHintWithLocals ($Stmt.msg) $ObjectHints $ClassName
                $names = @(Get-WasmAstObjectClassNamesFromHint $hint)
                if ($names.Count -eq 0) {
                    $state.SawNonObject = $true
                } else {
                    foreach ($name in $names) {
                        if ($script:wasmClassDefs.ContainsKey([string]$name)) {
                            $state.Classes[[string]$name] = $true
                        } else {
                            $state.SawNonObject = $true
                        }
                    }
                }
                Visit-WasmAstThrowObjectExpr ($Stmt.msg) $ObjectHints
            }
            "ASSIGN" {
                Visit-WasmAstThrowObjectExpr ($Stmt.value) $ObjectHints
                $name = [string]$Stmt.name
                $hint = Get-WasmAstObjectClassSetHintWithLocals ($Stmt.value) $ObjectHints $ClassName
                if (-not [string]::IsNullOrWhiteSpace($name) -and -not [string]::IsNullOrWhiteSpace($hint)) {
                    $ObjectHints[$name] = $hint
                } elseif (-not [string]::IsNullOrWhiteSpace($name) -and $ObjectHints.ContainsKey($name)) {
                    [void]$ObjectHints.Remove($name)
                }
            }
            "IN_PLACE" { Visit-WasmAstThrowObjectExpr ($Stmt.value) $ObjectHints }
            "DOT_ASSIGN" { Visit-WasmAstThrowObjectExpr ($Stmt.value) $ObjectHints }
            "INDEX_ASSIGN" {
                Visit-WasmAstThrowObjectExpr ($Stmt.key) $ObjectHints
                Visit-WasmAstThrowObjectExpr ($Stmt.value) $ObjectHints
            }
            "EXPR_STMT" { Visit-WasmAstThrowObjectExpr ($Stmt.expr) $ObjectHints }
            "RETURN" { Visit-WasmAstThrowObjectExpr ($Stmt.value) $ObjectHints }
            "IF" {
                Visit-WasmAstThrowObjectExpr ($Stmt.cond) $ObjectHints
                Visit-WasmAstThrowObjectStmt ($Stmt.then_block) (Copy-WasmAstTypeHints $ObjectHints)
                Visit-WasmAstThrowObjectStmt ($Stmt.else_block) (Copy-WasmAstTypeHints $ObjectHints)
            }
            { $_ -in @("WHILE", "REPEAT", "FOR", "FOREACH") } {
                foreach ($propertyName in @("cond", "count", "from", "to", "step", "collection")) {
                    if ($Stmt.PSObject.Properties.Name -contains $propertyName) {
                        Visit-WasmAstThrowObjectExpr ($Stmt.PSObject.Properties[$propertyName].Value) $ObjectHints
                    }
                }
                Visit-WasmAstThrowObjectStmt ($Stmt.body) (Copy-WasmAstTypeHints $ObjectHints)
            }
            "MATCH" {
                Visit-WasmAstThrowObjectExpr ($Stmt.subject) $ObjectHints
                foreach ($arm in @(As-WasmAstArray ($Stmt.arms))) {
                    Visit-WasmAstThrowObjectStmt ($arm.body) (Copy-WasmAstTypeHints $ObjectHints)
                }
            }
            "TRY" {
                if ($null -eq $Stmt.catch_block) {
                    Visit-WasmAstThrowObjectStmt ($Stmt.try_block) (Copy-WasmAstTypeHints $ObjectHints)
                } else {
                    Visit-WasmAstThrowObjectStmt ($Stmt.catch_block) (Copy-WasmAstTypeHints $ObjectHints)
                }
                Visit-WasmAstThrowObjectStmt ($Stmt.finally_block) (Copy-WasmAstTypeHints $ObjectHints)
            }
            "CMD" {
                foreach ($arg in @(As-WasmAstArray ($Stmt.args))) {
                    Visit-WasmAstThrowObjectExpr $arg $ObjectHints
                }
            }
            default { }
        }
    }

    Visit-WasmAstThrowObjectStmt $Body (Copy-WasmAstTypeHints $LocalObjectHints)
    $classNames = @($state.Classes.Keys | Sort-Object)
    $allObjects = ([bool]$state.SawThrow -and -not [bool]$state.SawNonObject -and $classNames.Count -gt 0)
    return [pscustomobject]@{
        HasThrows = [bool]$state.SawThrow
        AllObjects = $allObjects
        ClassHint = $(if ($allObjects) { New-WasmAstObjectClassSetHint ([string[]]$classNames) } else { "" })
    }
}

function Get-WasmAstTryThrowPayloadFunctionHint {
    param(
        $Body,
        [ValidateSet("display", "lift")][string]$Kind,
        [hashtable]$Seen = @{},
        [string]$ClassName = "",
        [hashtable]$LocalDisplayHints = @{},
        [hashtable]$LocalLiftHints = @{},
        [hashtable]$LocalObjectHints = @{}
    )

    $hints = New-Object System.Collections.Generic.List[string]
    function Add-WasmAstThrowFunctionHint {
        param([string]$Hint)
        if (-not [string]::IsNullOrWhiteSpace($Hint)) {
            $hints.Add($Hint) | Out-Null
        }
    }
    function Visit-WasmAstThrowFunctionExpr {
        param($Expr)
        if ($null -eq $Expr) { return }
        switch ([string]$Expr.node) {
            "CALL" {
                $name = [string]$Expr.name
                if ($script:wasmAstFunctionDefs.ContainsKey($name)) {
                    $seenKey = "func-throw-hint:${Kind}:$name"
                    if (-not $Seen.ContainsKey($seenKey)) {
                        $Seen[$seenKey] = $true
                        try {
                            $fn = $script:wasmAstFunctionDefs[$name]
                            if ($null -ne $fn.Node -and $null -ne $fn.Node.body) {
                                $paramDisplays = @{}
                                $paramLifts = @{}
                                $paramObjects = @{}
                                $params = @(Get-WasmAstParamNames ($fn.Node.params))
                                $args = @(As-WasmAstArray ($Expr.args))
                                for ($i = 0; $i -lt $params.Count -and $i -lt $args.Count; $i++) {
                                    $display = Get-WasmAstFunctionHintFromExpr ($args[$i]) "display" $ClassName $LocalDisplayHints $LocalLiftHints $LocalObjectHints $Seen
                                    $lift = Get-WasmAstFunctionHintFromExpr ($args[$i]) "lift" $ClassName $LocalDisplayHints $LocalLiftHints $LocalObjectHints $Seen
                                    $objectClass = Get-WasmAstObjectClassTypeWithLocals ($args[$i]) $LocalObjectHints $ClassName $Seen
                                    if (-not [string]::IsNullOrWhiteSpace($display)) { $paramDisplays[[string]$params[$i]] = $display }
                                    if (-not [string]::IsNullOrWhiteSpace($lift)) { $paramLifts[[string]$params[$i]] = $lift }
                                    if (-not [string]::IsNullOrWhiteSpace($objectClass)) { $paramObjects[[string]$params[$i]] = $objectClass }
                                }
                                Add-WasmAstThrowFunctionHint (Get-WasmAstTryThrowPayloadFunctionHint ($fn.Node.body) $Kind $Seen "" $paramDisplays $paramLifts $paramObjects)
                            }
                        } finally {
                            [void]$Seen.Remove($seenKey)
                        }
                    }
                }
                foreach ($arg in @(As-WasmAstArray ($Expr.args))) { Visit-WasmAstThrowFunctionExpr $arg }
            }
            "METHOD_CALL" {
                $methodClassName = Get-WasmAstObjectClassTypeWithLocals ($Expr.obj) $LocalObjectHints $ClassName @{}
                if ([string]::IsNullOrWhiteSpace($methodClassName)) {
                    $methodClassName = Get-WasmAstObjectClassTypeHint ($Expr.obj)
                }
                if (-not [string]::IsNullOrWhiteSpace($methodClassName)) {
                    $methodInfo = Get-WasmAstClassMethod -ClassName $methodClassName -MethodName ([string]$Expr.method)
                    if ($null -ne $methodInfo) {
                        $seenKey = "method-throw-hint:${Kind}:$([string]$methodInfo.FunctionName)"
                        if (-not $Seen.ContainsKey($seenKey)) {
                            $Seen[$seenKey] = $true
                            try {
                                $paramDisplays = @{}
                                $paramLifts = @{}
                                $paramObjects = Copy-WasmAstTypeHints (Get-WasmAstObservedFunctionParamObjectClassHints ([string]$methodInfo.FunctionName))
                                $params = @(Get-WasmAstParamNames ($methodInfo.Method.params))
                                $args = @(As-WasmAstArray ($Expr.args))
                                for ($i = 0; $i -lt $params.Count -and $i -lt $args.Count; $i++) {
                                    $display = Get-WasmAstFunctionHintFromExpr ($args[$i]) "display" $ClassName $LocalDisplayHints $LocalLiftHints $LocalObjectHints $Seen
                                    $lift = Get-WasmAstFunctionHintFromExpr ($args[$i]) "lift" $ClassName $LocalDisplayHints $LocalLiftHints $LocalObjectHints $Seen
                                    $objectClass = Get-WasmAstObjectClassTypeWithLocals ($args[$i]) $LocalObjectHints $ClassName $Seen
                                    if (-not [string]::IsNullOrWhiteSpace($display)) { $paramDisplays[[string]$params[$i]] = $display }
                                    if (-not [string]::IsNullOrWhiteSpace($lift)) { $paramLifts[[string]$params[$i]] = $lift }
                                    if (-not [string]::IsNullOrWhiteSpace($objectClass)) { $paramObjects[[string]$params[$i]] = $objectClass }
                                }
                                Add-WasmAstThrowFunctionHint (Get-WasmAstTryThrowPayloadFunctionHint ($methodInfo.Method.body) $Kind $Seen ([string]$methodInfo.ClassName) $paramDisplays $paramLifts $paramObjects)
                            } finally {
                                [void]$Seen.Remove($seenKey)
                            }
                        }
                    }
                }
                Visit-WasmAstThrowFunctionExpr ($Expr.obj)
                foreach ($arg in @(As-WasmAstArray ($Expr.args))) { Visit-WasmAstThrowFunctionExpr $arg }
            }
            "SUPER_CALL" {
                if (-not [string]::IsNullOrWhiteSpace($ClassName) -and $script:wasmClassDefs.ContainsKey($ClassName)) {
                    $parentClass = [string]$script:wasmClassDefs[$ClassName].Parent
                    if (-not [string]::IsNullOrWhiteSpace($parentClass)) {
                        $methodInfo = Get-WasmAstClassMethod -ClassName $parentClass -MethodName ([string]$Expr.method)
                        if ($null -ne $methodInfo) {
                            $seenKey = "super-throw-hint:${Kind}:$([string]$methodInfo.FunctionName)"
                            if (-not $Seen.ContainsKey($seenKey)) {
                                $Seen[$seenKey] = $true
                                try {
                                    $paramDisplays = @{}
                                    $paramLifts = @{}
                                    $paramObjects = Copy-WasmAstTypeHints (Get-WasmAstObservedFunctionParamObjectClassHints ([string]$methodInfo.FunctionName))
                                    $params = @(Get-WasmAstParamNames ($methodInfo.Method.params))
                                    $args = @(As-WasmAstArray ($Expr.args))
                                    for ($i = 0; $i -lt $params.Count -and $i -lt $args.Count; $i++) {
                                        $display = Get-WasmAstFunctionHintFromExpr ($args[$i]) "display" $ClassName $LocalDisplayHints $LocalLiftHints $LocalObjectHints $Seen
                                        $lift = Get-WasmAstFunctionHintFromExpr ($args[$i]) "lift" $ClassName $LocalDisplayHints $LocalLiftHints $LocalObjectHints $Seen
                                        $objectClass = Get-WasmAstObjectClassTypeWithLocals ($args[$i]) $LocalObjectHints $ClassName $Seen
                                        if (-not [string]::IsNullOrWhiteSpace($display)) { $paramDisplays[[string]$params[$i]] = $display }
                                        if (-not [string]::IsNullOrWhiteSpace($lift)) { $paramLifts[[string]$params[$i]] = $lift }
                                        if (-not [string]::IsNullOrWhiteSpace($objectClass)) { $paramObjects[[string]$params[$i]] = $objectClass }
                                    }
                                    Add-WasmAstThrowFunctionHint (Get-WasmAstTryThrowPayloadFunctionHint ($methodInfo.Method.body) $Kind $Seen ([string]$methodInfo.ClassName) $paramDisplays $paramLifts $paramObjects)
                                } finally {
                                    [void]$Seen.Remove($seenKey)
                                }
                            }
                        }
                    }
                }
                foreach ($arg in @(As-WasmAstArray ($Expr.args))) { Visit-WasmAstThrowFunctionExpr $arg }
            }
            "BIN_OP" {
                Visit-WasmAstThrowFunctionExpr ($Expr.left)
                Visit-WasmAstThrowFunctionExpr ($Expr.right)
            }
            "UNARY_OP" { Visit-WasmAstThrowFunctionExpr ($Expr.operand) }
            "TERNARY" {
                Visit-WasmAstThrowFunctionExpr ($Expr.cond)
                Visit-WasmAstThrowFunctionExpr ($Expr.then)
                Visit-WasmAstThrowFunctionExpr ($Expr.else)
            }
            "DOT_ACCESS" { Visit-WasmAstThrowFunctionExpr ($Expr.obj) }
            "INDEX" {
                Visit-WasmAstThrowFunctionExpr ($Expr.obj)
                Visit-WasmAstThrowFunctionExpr ($Expr.key)
            }
            "ARRAY_LIT" {
                foreach ($item in @(As-WasmAstArray ($Expr.elements))) { Visit-WasmAstThrowFunctionExpr $item }
            }
            "DICT_LIT" {
                foreach ($entry in @(As-WasmAstArray ($Expr.entries))) { Visit-WasmAstThrowFunctionExpr ($entry.value) }
            }
            "NEW_EXPR" {
                foreach ($arg in @(As-WasmAstArray ($Expr.args))) { Visit-WasmAstThrowFunctionExpr $arg }
            }
            "STR_INTERP" {
                foreach ($part in @(As-WasmAstArray ($Expr.parts))) { Visit-WasmAstThrowFunctionExpr $part }
            }
            default { }
        }
    }
    function Visit-WasmAstThrowFunctionStmt {
        param($Stmt)
        if ($null -eq $Stmt) { return }
        switch ([string]$Stmt.node) {
            "SuraBlock" {
                foreach ($child in @(As-WasmAstArray ($Stmt.body))) { Visit-WasmAstThrowFunctionStmt $child }
            }
            "THROW" {
                Add-WasmAstThrowFunctionHint (Get-WasmAstFunctionHintFromExpr ($Stmt.msg) $Kind $ClassName $LocalDisplayHints $LocalLiftHints $LocalObjectHints $Seen)
            }
            "ASSIGN" {
                $name = [string]$Stmt.name
                if (-not [string]::IsNullOrWhiteSpace($name)) {
                    $display = Get-WasmAstFunctionHintFromExpr ($Stmt.value) "display" $ClassName $LocalDisplayHints $LocalLiftHints $LocalObjectHints $Seen
                    $lift = Get-WasmAstFunctionHintFromExpr ($Stmt.value) "lift" $ClassName $LocalDisplayHints $LocalLiftHints $LocalObjectHints $Seen
                    $objectClass = Get-WasmAstObjectClassTypeWithLocals ($Stmt.value) $LocalObjectHints $ClassName $Seen
                    if (-not [string]::IsNullOrWhiteSpace($display)) {
                        $LocalDisplayHints[$name] = $display
                    } elseif ($LocalDisplayHints.ContainsKey($name)) {
                        [void]$LocalDisplayHints.Remove($name)
                    }
                    if (-not [string]::IsNullOrWhiteSpace($lift)) {
                        $LocalLiftHints[$name] = $lift
                    } elseif ($LocalLiftHints.ContainsKey($name)) {
                        [void]$LocalLiftHints.Remove($name)
                    }
                    if (-not [string]::IsNullOrWhiteSpace($objectClass)) {
                        $LocalObjectHints[$name] = $objectClass
                    } elseif ($LocalObjectHints.ContainsKey($name)) {
                        [void]$LocalObjectHints.Remove($name)
                    }
                }
                Visit-WasmAstThrowFunctionExpr ($Stmt.value)
            }
            "IN_PLACE" { Visit-WasmAstThrowFunctionExpr ($Stmt.value) }
            "DOT_ASSIGN" { Visit-WasmAstThrowFunctionExpr ($Stmt.value) }
            "INDEX_ASSIGN" {
                Visit-WasmAstThrowFunctionExpr ($Stmt.key)
                Visit-WasmAstThrowFunctionExpr ($Stmt.value)
            }
            "EXPR_STMT" { Visit-WasmAstThrowFunctionExpr ($Stmt.expr) }
            "RETURN" { Visit-WasmAstThrowFunctionExpr ($Stmt.value) }
            "IF" {
                Visit-WasmAstThrowFunctionExpr ($Stmt.cond)
                Visit-WasmAstThrowFunctionStmt ($Stmt.then_block)
                Visit-WasmAstThrowFunctionStmt ($Stmt.else_block)
            }
            "WHILE" {
                Visit-WasmAstThrowFunctionExpr ($Stmt.cond)
                Visit-WasmAstThrowFunctionStmt ($Stmt.body)
            }
            "REPEAT" {
                Visit-WasmAstThrowFunctionExpr ($Stmt.count)
                Visit-WasmAstThrowFunctionStmt ($Stmt.body)
            }
            "FOR" {
                Visit-WasmAstThrowFunctionExpr ($Stmt.from)
                Visit-WasmAstThrowFunctionExpr ($Stmt.to)
                Visit-WasmAstThrowFunctionExpr ($Stmt.step)
                Visit-WasmAstThrowFunctionStmt ($Stmt.body)
            }
            "FOREACH" {
                Visit-WasmAstThrowFunctionExpr ($Stmt.collection)
                Visit-WasmAstThrowFunctionStmt ($Stmt.body)
            }
            "MATCH" {
                Visit-WasmAstThrowFunctionExpr ($Stmt.subject)
                foreach ($arm in @(As-WasmAstArray ($Stmt.arms))) { Visit-WasmAstThrowFunctionStmt ($arm.body) }
            }
            "TRY" {
                if ($null -eq $Stmt.catch_block) {
                    Visit-WasmAstThrowFunctionStmt ($Stmt.try_block)
                } else {
                    Visit-WasmAstThrowFunctionStmt ($Stmt.catch_block)
                }
                Visit-WasmAstThrowFunctionStmt ($Stmt.finally_block)
            }
            default { }
        }
    }

    Visit-WasmAstThrowFunctionStmt $Body
    if ($hints.Count -eq 0) { return "" }
    $first = [string]$hints[0]
    foreach ($hint in $hints) {
        if ([string]$hint -ne $first) { return "" }
    }
    return $first
}

function Set-WasmAstClassFieldTypeHint {
    param([string]$ClassName, [string]$FieldName, [string]$TypeName)

    if ([string]::IsNullOrWhiteSpace($ClassName) -or [string]::IsNullOrWhiteSpace($FieldName) -or
        [string]::IsNullOrWhiteSpace($TypeName)) { return }
    if ($TypeName -notin @("string", "bool", "nil", "num", "array", "dict", "function")) { return }
    $script:wasmClassFieldTypeHints["$ClassName.$FieldName"] = $TypeName
}

function Set-WasmAstObservedClassFieldTypeHint {
    param([string]$ClassName, [string]$FieldName, [string]$TypeName)

    if ([string]::IsNullOrWhiteSpace($ClassName) -or [string]::IsNullOrWhiteSpace($FieldName) -or
        [string]::IsNullOrWhiteSpace($TypeName)) { return }
    if ($TypeName -notin @("string", "bool", "nil", "num", "array", "dict", "function")) { return }
    $key = "$ClassName.$FieldName"
    if ($script:wasmConflictedClassFieldTypeHints.ContainsKey($key)) { return }
    if ($script:wasmObservedClassFieldTypeHints.ContainsKey($key) -and
        [string]$script:wasmObservedClassFieldTypeHints[$key] -ne $TypeName) {
        $script:wasmObservedClassFieldTypeHints.Remove($key)
        $script:wasmConflictedClassFieldTypeHints[$key] = $true
        return
    }
    $script:wasmObservedClassFieldTypeHints[$key] = $TypeName
}

function Get-WasmAstObservedClassFieldTypeHint {
    param([string]$ClassName, [string]$FieldName)

    if ([string]::IsNullOrWhiteSpace($ClassName) -or [string]::IsNullOrWhiteSpace($FieldName)) { return "" }
    $key = "$ClassName.$FieldName"
    if ($script:wasmConflictedClassFieldTypeHints.ContainsKey($key)) { return "value" }
    if ($script:wasmObservedClassFieldTypeHints.ContainsKey($key)) {
        return [string]$script:wasmObservedClassFieldTypeHints[$key]
    }
    return ""
}

function Set-WasmAstClassFieldObjectClassHint {
    param([string]$ClassName, [string]$FieldName, [string]$ObjectClassName)

    if ([string]::IsNullOrWhiteSpace($ClassName) -or [string]::IsNullOrWhiteSpace($FieldName)) { return }
    $key = "$ClassName.$FieldName"
    if ($script:wasmConflictedClassFieldObjectClassHints.ContainsKey($key)) { return }
    if ([string]::IsNullOrWhiteSpace($ObjectClassName) -or -not $script:wasmClassDefs.ContainsKey($ObjectClassName)) {
        if ($script:wasmClassFieldObjectClassHints.ContainsKey($key)) {
            $script:wasmClassFieldObjectClassHints.Remove($key)
            $script:wasmConflictedClassFieldObjectClassHints[$key] = $true
        }
        return
    }
    if ($script:wasmClassFieldObjectClassHints.ContainsKey($key) -and
        [string]$script:wasmClassFieldObjectClassHints[$key] -ne $ObjectClassName) {
        $script:wasmClassFieldObjectClassHints.Remove($key)
        $script:wasmConflictedClassFieldObjectClassHints[$key] = $true
        return
    }
    $script:wasmClassFieldObjectClassHints[$key] = $ObjectClassName
}

function Set-WasmAstClassFieldFunctionDisplayHint {
    param([string]$ClassName, [string]$FieldName, [string]$DisplayName)

    if ([string]::IsNullOrWhiteSpace($ClassName) -or [string]::IsNullOrWhiteSpace($FieldName) -or
        [string]::IsNullOrWhiteSpace($DisplayName)) { return }
    $key = "$ClassName.$FieldName"
    if ($script:wasmConflictedClassFieldFunctionDisplayHints.ContainsKey($key)) { return }
    if ($script:wasmClassFieldFunctionDisplayHints.ContainsKey($key) -and
        [string]$script:wasmClassFieldFunctionDisplayHints[$key] -ne $DisplayName) {
        $script:wasmClassFieldFunctionDisplayHints.Remove($key)
        $script:wasmConflictedClassFieldFunctionDisplayHints[$key] = $true
        return
    }
    $script:wasmClassFieldFunctionDisplayHints[$key] = $DisplayName
}

function Get-WasmAstClassFieldFunctionDisplayHint {
    param([string]$ClassName, [string]$FieldName)

    if ([string]::IsNullOrWhiteSpace($ClassName) -or [string]::IsNullOrWhiteSpace($FieldName)) { return "" }
    $key = "$ClassName.$FieldName"
    if ($script:wasmConflictedClassFieldFunctionDisplayHints.ContainsKey($key)) { return "" }
    if ($script:wasmClassFieldFunctionDisplayHints.ContainsKey($key)) {
        return [string]$script:wasmClassFieldFunctionDisplayHints[$key]
    }
    return ""
}

function Set-WasmAstClassFieldFunctionLiftHint {
    param([string]$ClassName, [string]$FieldName, [string]$LiftName)

    if ([string]::IsNullOrWhiteSpace($ClassName) -or [string]::IsNullOrWhiteSpace($FieldName) -or
        [string]::IsNullOrWhiteSpace($LiftName)) { return }
    $key = "$ClassName.$FieldName"
    if ($script:wasmConflictedClassFieldFunctionLiftHints.ContainsKey($key)) { return }
    if ($script:wasmClassFieldFunctionLiftHints.ContainsKey($key) -and
        [string]$script:wasmClassFieldFunctionLiftHints[$key] -ne $LiftName) {
        $script:wasmClassFieldFunctionLiftHints.Remove($key)
        $script:wasmConflictedClassFieldFunctionLiftHints[$key] = $true
        return
    }
    $script:wasmClassFieldFunctionLiftHints[$key] = $LiftName
}

function Get-WasmAstClassFieldFunctionLiftHint {
    param([string]$ClassName, [string]$FieldName)

    if ([string]::IsNullOrWhiteSpace($ClassName) -or [string]::IsNullOrWhiteSpace($FieldName)) { return "" }
    $key = "$ClassName.$FieldName"
    if ($script:wasmConflictedClassFieldFunctionLiftHints.ContainsKey($key)) { return "" }
    if ($script:wasmClassFieldFunctionLiftHints.ContainsKey($key)) {
        return [string]$script:wasmClassFieldFunctionLiftHints[$key]
    }
    return ""
}

function Get-WasmAstFunctionHintSummaryFromBody {
    param(
        $Body,
        [ValidateSet("display", "lift")][string]$Kind,
        [string]$ClassName = "",
        [hashtable]$LocalDisplayHints = @{},
        [hashtable]$LocalLiftHints = @{},
        [hashtable]$LocalObjectHints = @{},
        [hashtable]$Seen = @{}
    )

    $hints = New-Object System.Collections.Generic.List[string]
    $returnCount = 0
    $hasUnknownReturn = $false
    if ($null -eq $Body) {
        return [pscustomobject]@{
            Hints = @()
            ReturnCount = 0
            HasUnknownReturn = $false
        }
    }
    $displays = Copy-WasmAstTypeHints $LocalDisplayHints
    $lifts = Copy-WasmAstTypeHints $LocalLiftHints
    $objects = Copy-WasmAstTypeHints $LocalObjectHints
    foreach ($stmt in @(As-WasmAstArray ($Body.body))) {
        if ($null -eq $stmt) { continue }
        switch ([string]$stmt.node) {
            "ASSIGN" {
                $name = [string]$stmt.name
                $display = Get-WasmAstFunctionHintFromExpr ($stmt.value) "display" $ClassName $displays $lifts $objects $Seen
                $lift = Get-WasmAstFunctionHintFromExpr ($stmt.value) "lift" $ClassName $displays $lifts $objects $Seen
                if (-not [string]::IsNullOrWhiteSpace($display)) { $displays[$name] = $display } elseif ($displays.ContainsKey($name)) { $displays.Remove($name) }
                if (-not [string]::IsNullOrWhiteSpace($lift)) { $lifts[$name] = $lift } elseif ($lifts.ContainsKey($name)) { $lifts.Remove($name) }
                $objectClass = Get-WasmAstObjectClassTypeWithLocals ($stmt.value) $objects $ClassName $Seen
                if (-not [string]::IsNullOrWhiteSpace($objectClass)) { $objects[$name] = $objectClass } elseif ($objects.ContainsKey($name)) { $objects.Remove($name) }
            }
            "RETURN" {
                $returnCount++
                $hint = Get-WasmAstFunctionHintFromExpr ($stmt.value) $Kind $ClassName $displays $lifts $objects $Seen
                if ([string]::IsNullOrWhiteSpace($hint)) {
                    $hasUnknownReturn = $true
                } else {
                    $hints.Add([string]$hint) | Out-Null
                }
            }
            "SuraBlock" {
                $summary = Get-WasmAstFunctionHintSummaryFromBody $stmt $Kind $ClassName $displays $lifts $objects $Seen
                $returnCount += [int]$summary.ReturnCount
                if ([bool]$summary.HasUnknownReturn) { $hasUnknownReturn = $true }
                foreach ($hint in @($summary.Hints)) { $hints.Add([string]$hint) | Out-Null }
            }
            "IF" {
                foreach ($branch in @($stmt.then_block, $stmt.else_block)) {
                    $summary = Get-WasmAstFunctionHintSummaryFromBody $branch $Kind $ClassName $displays $lifts $objects $Seen
                    $returnCount += [int]$summary.ReturnCount
                    if ([bool]$summary.HasUnknownReturn) { $hasUnknownReturn = $true }
                    foreach ($hint in @($summary.Hints)) { $hints.Add([string]$hint) | Out-Null }
                }
            }
            "MATCH" {
                foreach ($arm in @(As-WasmAstArray ($stmt.arms))) {
                    $summary = Get-WasmAstFunctionHintSummaryFromBody ($arm.body) $Kind $ClassName $displays $lifts $objects $Seen
                    $returnCount += [int]$summary.ReturnCount
                    if ([bool]$summary.HasUnknownReturn) { $hasUnknownReturn = $true }
                    foreach ($hint in @($summary.Hints)) { $hints.Add([string]$hint) | Out-Null }
                }
            }
            "TRY" {
                foreach ($branch in @($stmt.try_block, $stmt.catch_block, $stmt.finally_block)) {
                    $summary = Get-WasmAstFunctionHintSummaryFromBody $branch $Kind $ClassName $displays $lifts $objects $Seen
                    $returnCount += [int]$summary.ReturnCount
                    if ([bool]$summary.HasUnknownReturn) { $hasUnknownReturn = $true }
                    foreach ($hint in @($summary.Hints)) { $hints.Add([string]$hint) | Out-Null }
                }
            }
            default { }
        }
    }
    return [pscustomobject]@{
        Hints = @($hints.ToArray())
        ReturnCount = $returnCount
        HasUnknownReturn = $hasUnknownReturn
    }
}

function Get-WasmAstFunctionHintFromBody {
    param(
        $Body,
        [ValidateSet("display", "lift")][string]$Kind,
        [string]$ClassName = "",
        [hashtable]$LocalDisplayHints = @{},
        [hashtable]$LocalLiftHints = @{},
        [hashtable]$LocalObjectHints = @{},
        [hashtable]$Seen = @{}
    )

    $summary = Get-WasmAstFunctionHintSummaryFromBody $Body $Kind $ClassName $LocalDisplayHints $LocalLiftHints $LocalObjectHints $Seen
    if ([int]$summary.ReturnCount -eq 0 -or [bool]$summary.HasUnknownReturn) { return "" }
    $uniqueHints = @($summary.Hints | Sort-Object -Unique)
    if ($uniqueHints.Count -eq 1) { return [string]$uniqueHints[0] }
    return ""
}

function Get-WasmAstFunctionCallFunctionHint {
    param(
        $Node,
        [ValidateSet("display", "lift")][string]$Kind,
        [string]$ClassName = "",
        [hashtable]$LocalDisplayHints = @{},
        [hashtable]$LocalLiftHints = @{},
        [hashtable]$LocalObjectHints = @{},
        [hashtable]$Seen = @{}
    )

    if ($null -eq $Node -or [string]$Node.node -ne "CALL") { return "" }
    $name = [string]$Node.name
    if (-not $script:wasmAstFunctionDefs.ContainsKey($name)) { return "" }
    $seenKey = "func:${Kind}:$name"
    if ($Seen.ContainsKey($seenKey) -or $script:wasmFunctionReturnFunctionHintInferenceStack.ContainsKey($seenKey)) { return "" }
    $Seen[$seenKey] = $true
    $script:wasmFunctionReturnFunctionHintInferenceStack[$seenKey] = $true
    try {
        $fn = $script:wasmAstFunctionDefs[$name]
        if ($null -eq $fn.Node -or $null -eq $fn.Node.body) { return "" }
        $paramDisplays = @{}
        $paramLifts = @{}
        $params = @($fn.Params)
        $args = @(As-WasmAstArray ($Node.args))
        for ($i = 0; $i -lt $params.Count -and $i -lt $args.Count; $i++) {
            $display = Get-WasmAstFunctionHintFromExpr ($args[$i]) "display" $ClassName $LocalDisplayHints $LocalLiftHints $LocalObjectHints $Seen
            $lift = Get-WasmAstFunctionHintFromExpr ($args[$i]) "lift" $ClassName $LocalDisplayHints $LocalLiftHints $LocalObjectHints $Seen
            if (-not [string]::IsNullOrWhiteSpace($display)) { $paramDisplays[[string]$params[$i]] = $display }
            if (-not [string]::IsNullOrWhiteSpace($lift)) { $paramLifts[[string]$params[$i]] = $lift }
        }
        $resolvedReturn = Resolve-WasmAstFunctionCallReturnExpr $Node
        if ($null -ne $resolvedReturn) {
            $resolvedHint = Get-WasmAstFunctionHintFromExpr $resolvedReturn $Kind $ClassName $LocalDisplayHints $LocalLiftHints $LocalObjectHints $Seen
            if (-not [string]::IsNullOrWhiteSpace($resolvedHint)) { return $resolvedHint }
        }
        return (Get-WasmAstFunctionHintFromBody ($fn.Node.body) $Kind "" $paramDisplays $paramLifts @{} $Seen)
    } finally {
        $script:wasmFunctionReturnFunctionHintInferenceStack.Remove($seenKey)
        $Seen.Remove($seenKey)
    }
}

function Get-WasmAstMethodCallFunctionHint {
    param(
        $Node,
        [ValidateSet("display", "lift")][string]$Kind,
        [string]$SelfClassName = "",
        [hashtable]$LocalDisplayHints = @{},
        [hashtable]$LocalLiftHints = @{},
        [hashtable]$LocalObjectHints = @{},
        [hashtable]$Seen = @{}
    )

    if ($null -eq $Node -or [string]$Node.node -ne "METHOD_CALL" -or $null -eq $Node.obj) { return "" }
    $className = Get-WasmAstObjectClassTypeWithLocals ($Node.obj) $LocalObjectHints $SelfClassName $Seen
    if ([string]::IsNullOrWhiteSpace($className)) { return "" }
    $methodInfo = Get-WasmAstClassMethod -ClassName $className -MethodName ([string]$Node.method)
    if ($null -eq $methodInfo) { return "" }
    $seenKey = "method:${Kind}:$([string]$methodInfo.FunctionName)"
    if ($Seen.ContainsKey($seenKey) -or $script:wasmMethodReturnFunctionHintInferenceStack.ContainsKey($seenKey)) { return "" }
    $Seen[$seenKey] = $true
    $script:wasmMethodReturnFunctionHintInferenceStack[$seenKey] = $true
    try {
        $paramDisplays = @{}
        $paramLifts = @{}
        $params = @(Get-WasmAstParamNames ($methodInfo.Method.params))
        $args = @(As-WasmAstArray ($Node.args))
        for ($i = 0; $i -lt $params.Count -and $i -lt $args.Count; $i++) {
            $display = Get-WasmAstFunctionHintFromExpr ($args[$i]) "display" $SelfClassName $LocalDisplayHints $LocalLiftHints $LocalObjectHints $Seen
            $lift = Get-WasmAstFunctionHintFromExpr ($args[$i]) "lift" $SelfClassName $LocalDisplayHints $LocalLiftHints $LocalObjectHints $Seen
            if (-not [string]::IsNullOrWhiteSpace($display)) { $paramDisplays[[string]$params[$i]] = $display }
            if (-not [string]::IsNullOrWhiteSpace($lift)) { $paramLifts[[string]$params[$i]] = $lift }
        }
        $methodObjects = Copy-WasmAstTypeHints (Get-WasmAstObservedFunctionParamObjectClassHints ([string]$methodInfo.FunctionName))
        $resolvedReturn = Resolve-WasmAstMethodCallReturnExpr $Node
        if ($null -ne $resolvedReturn) {
            $resolvedHint = Get-WasmAstFunctionHintFromExpr $resolvedReturn $Kind $SelfClassName $LocalDisplayHints $LocalLiftHints $LocalObjectHints $Seen
            if (-not [string]::IsNullOrWhiteSpace($resolvedHint)) { return $resolvedHint }
        }
        return (Get-WasmAstFunctionHintFromBody ($methodInfo.Method.body) $Kind ([string]$methodInfo.ClassName) $paramDisplays $paramLifts $methodObjects $Seen)
    } finally {
        $script:wasmMethodReturnFunctionHintInferenceStack.Remove($seenKey)
        $Seen.Remove($seenKey)
    }
}

function Get-WasmAstSuperCallFunctionHint {
    param(
        $Node,
        [ValidateSet("display", "lift")][string]$Kind,
        [string]$ClassName = "",
        [hashtable]$LocalDisplayHints = @{},
        [hashtable]$LocalLiftHints = @{},
        [hashtable]$LocalObjectHints = @{},
        [hashtable]$Seen = @{}
    )

    if ($null -eq $Node -or [string]$Node.node -ne "SUPER_CALL" -or [string]::IsNullOrWhiteSpace($ClassName)) { return "" }
    $methodName = [string]$Node.method
    if ([string]::IsNullOrWhiteSpace($methodName) -or $methodName -eq "init") { return "" }
    $methodInfo = Get-WasmAstSuperClassMethod -ClassName $ClassName -MethodName $methodName
    if ($null -eq $methodInfo) { return "" }

    $seenKey = "super:${Kind}:$ClassName->$([string]$methodInfo.FunctionName)"
    if ($Seen.ContainsKey($seenKey) -or $script:wasmMethodReturnFunctionHintInferenceStack.ContainsKey($seenKey)) { return "" }
    $Seen[$seenKey] = $true
    $script:wasmMethodReturnFunctionHintInferenceStack[$seenKey] = $true
    try {
        $paramDisplays = @{}
        $paramLifts = @{}
        $params = @(Get-WasmAstParamNames ($methodInfo.Method.params))
        $args = @(As-WasmAstArray ($Node.args))
        $paramExprs = @{}
        for ($i = 0; $i -lt $params.Count -and $i -lt $args.Count; $i++) {
            $paramExprs[[string]$params[$i]] = $args[$i]
            $display = Get-WasmAstFunctionHintFromExpr ($args[$i]) "display" $ClassName $LocalDisplayHints $LocalLiftHints $LocalObjectHints $Seen
            $lift = Get-WasmAstFunctionHintFromExpr ($args[$i]) "lift" $ClassName $LocalDisplayHints $LocalLiftHints $LocalObjectHints $Seen
            if (-not [string]::IsNullOrWhiteSpace($display)) { $paramDisplays[[string]$params[$i]] = $display }
            if (-not [string]::IsNullOrWhiteSpace($lift)) { $paramLifts[[string]$params[$i]] = $lift }
        }
        $methodObjects = Copy-WasmAstTypeHints (Get-WasmAstObservedFunctionParamObjectClassHints ([string]$methodInfo.FunctionName))
        $resolvedReturn = Resolve-WasmAstMethodBodyReturnExpr ($methodInfo.Method.body) ([pscustomobject]@{ node = "IDENT"; name = "self" }) $paramExprs @{} ([string]$methodInfo.ClassName)
        if ($null -ne $resolvedReturn) {
            $resolvedHint = Get-WasmAstFunctionHintFromExpr $resolvedReturn $Kind $ClassName $LocalDisplayHints $LocalLiftHints $LocalObjectHints $Seen
            if (-not [string]::IsNullOrWhiteSpace($resolvedHint)) { return $resolvedHint }
        }
        return (Get-WasmAstFunctionHintFromBody ($methodInfo.Method.body) $Kind ([string]$methodInfo.ClassName) $paramDisplays $paramLifts $methodObjects $Seen)
    } finally {
        $script:wasmMethodReturnFunctionHintInferenceStack.Remove($seenKey)
        $Seen.Remove($seenKey)
    }
}

function Get-WasmAstFunctionHintFromExpr {
    param(
        $Node,
        [ValidateSet("display", "lift")][string]$Kind,
        [string]$ClassName = "",
        [hashtable]$LocalDisplayHints = @{},
        [hashtable]$LocalLiftHints = @{},
        [hashtable]$LocalObjectHints = @{},
        [hashtable]$Seen = @{}
    )

    if ($null -eq $Node) { return "" }
    switch ([string]$Node.node) {
        "FUNC_EXPR" {
            if ($Kind -eq "display") { return (Get-WasmAstFuncExprDisplayName $Node) }
            return (Get-WasmAstFuncExprLiftName $Node)
        }
        "IDENT" {
            $name = [string]$Node.name
            if ($Kind -eq "display") {
                if ($LocalDisplayHints.ContainsKey($name)) { return [string]$LocalDisplayHints[$name] }
                if ($script:wasmCurrentLocalFunctionDisplayHints.ContainsKey($name)) { return [string]$script:wasmCurrentLocalFunctionDisplayHints[$name] }
                if ($script:wasmGlobalFunctionDisplayHints.ContainsKey($name)) { return [string]$script:wasmGlobalFunctionDisplayHints[$name] }
                if ($script:wasmAstFunctionDefs.ContainsKey($name)) { return $name }
            } else {
                if ($LocalLiftHints.ContainsKey($name)) { return [string]$LocalLiftHints[$name] }
                if ($script:wasmCurrentLocalFunctionLiftHints.ContainsKey($name)) { return [string]$script:wasmCurrentLocalFunctionLiftHints[$name] }
                if ($script:wasmGlobalFunctionLiftHints.ContainsKey($name)) { return [string]$script:wasmGlobalFunctionLiftHints[$name] }
                if ($script:wasmAstFunctionDefs.ContainsKey($name)) { return $name }
            }
            return ""
        }
        "DOT_ACCESS" {
            $receiverClass = Get-WasmAstObjectClassTypeWithLocals ($Node.obj) $LocalObjectHints $ClassName $Seen
            if (-not [string]::IsNullOrWhiteSpace($receiverClass)) {
                if ($Kind -eq "display") { return (Get-WasmAstClassFieldFunctionDisplayHint $receiverClass ([string]$Node.prop)) }
                return (Get-WasmAstClassFieldFunctionLiftHint $receiverClass ([string]$Node.prop))
            }
            $accessKey = Get-WasmAstStringAccessHintKey $Node
            if (-not [string]::IsNullOrWhiteSpace($accessKey)) {
                if ($Kind -eq "display" -and -not $script:wasmConflictedAccessFunctionDisplayHints.ContainsKey($accessKey) -and $script:wasmAccessFunctionDisplayHints.ContainsKey($accessKey)) {
                    return [string]$script:wasmAccessFunctionDisplayHints[$accessKey]
                }
                if ($Kind -eq "lift" -and -not $script:wasmConflictedAccessFunctionLiftHints.ContainsKey($accessKey) -and $script:wasmAccessFunctionLiftHints.ContainsKey($accessKey)) {
                    return [string]$script:wasmAccessFunctionLiftHints[$accessKey]
                }
            }
            return ""
        }
        "INDEX" {
            $accessKey = Get-WasmAstStringAccessHintKey $Node
            if (-not [string]::IsNullOrWhiteSpace($accessKey)) {
                if ($Kind -eq "display" -and -not $script:wasmConflictedAccessFunctionDisplayHints.ContainsKey($accessKey) -and $script:wasmAccessFunctionDisplayHints.ContainsKey($accessKey)) {
                    return [string]$script:wasmAccessFunctionDisplayHints[$accessKey]
                }
                if ($Kind -eq "lift" -and -not $script:wasmConflictedAccessFunctionLiftHints.ContainsKey($accessKey) -and $script:wasmAccessFunctionLiftHints.ContainsKey($accessKey)) {
                    return [string]$script:wasmAccessFunctionLiftHints[$accessKey]
                }
            }
            return ""
        }
        "CALL" {
            $specializedHint = Get-WasmAstSpecializedFunctionCallReturnHint $Node $Kind
            if (-not [string]::IsNullOrWhiteSpace($specializedHint)) { return $specializedHint }
            return (Get-WasmAstFunctionCallFunctionHint $Node $Kind $ClassName $LocalDisplayHints $LocalLiftHints $LocalObjectHints $Seen)
        }
        "METHOD_CALL" {
            return (Get-WasmAstMethodCallFunctionHint $Node $Kind $ClassName $LocalDisplayHints $LocalLiftHints $LocalObjectHints $Seen)
        }
        "SUPER_CALL" {
            return (Get-WasmAstSuperCallFunctionHint $Node $Kind $ClassName $LocalDisplayHints $LocalLiftHints $LocalObjectHints $Seen)
        }
        "TERNARY" {
            $condState = Get-WasmAstKnownBoolLiteralState ($Node.cond)
            if ($condState -eq "true") {
                return (Get-WasmAstFunctionHintFromExpr ($Node.then) $Kind $ClassName $LocalDisplayHints $LocalLiftHints $LocalObjectHints $Seen)
            }
            if ($condState -eq "false") {
                return (Get-WasmAstFunctionHintFromExpr ($Node.else) $Kind $ClassName $LocalDisplayHints $LocalLiftHints $LocalObjectHints $Seen)
            }
            $thenHint = Get-WasmAstFunctionHintFromExpr ($Node.then) $Kind $ClassName $LocalDisplayHints $LocalLiftHints $LocalObjectHints $Seen
            $elseHint = Get-WasmAstFunctionHintFromExpr ($Node.else) $Kind $ClassName $LocalDisplayHints $LocalLiftHints $LocalObjectHints $Seen
            if (-not [string]::IsNullOrWhiteSpace($thenHint) -and $thenHint -eq $elseHint) { return $thenHint }
            return ""
        }
        default { return "" }
    }
}

function Get-WasmAstClassFieldObjectClassHint {
    param([string]$ClassName, [string]$FieldName, [hashtable]$Seen = @{})

    if ([string]::IsNullOrWhiteSpace($ClassName) -or [string]::IsNullOrWhiteSpace($FieldName) -or $Seen.ContainsKey($ClassName)) {
        return ""
    }
    $Seen[$ClassName] = $true
    $key = "$ClassName.$FieldName"
    if ($script:wasmConflictedClassFieldObjectClassHints.ContainsKey($key)) { return "" }
    if ($script:wasmClassFieldObjectClassHints.ContainsKey($key)) {
        return [string]$script:wasmClassFieldObjectClassHints[$key]
    }
    if ($script:wasmClassDefs.ContainsKey($ClassName)) {
        $parent = [string]$script:wasmClassDefs[$ClassName].Parent
        if (-not [string]::IsNullOrWhiteSpace($parent)) {
            return (Get-WasmAstClassFieldObjectClassHint $parent $FieldName $Seen)
        }
    }
    return ""
}

function Get-WasmAstClassFieldTypeHints {
    param([string]$ClassName, [hashtable]$Seen = @{})

    $types = @{}
    if ([string]::IsNullOrWhiteSpace($ClassName) -or $Seen.ContainsKey($ClassName)) { return $types }
    $Seen[$ClassName] = $true
    if ($script:wasmClassDefs.ContainsKey($ClassName)) {
        $parent = [string]$script:wasmClassDefs[$ClassName].Parent
        if (-not [string]::IsNullOrWhiteSpace($parent)) {
            foreach ($entry in (Get-WasmAstClassFieldTypeHints $parent $Seen).GetEnumerator()) {
                $types[$entry.Key] = $entry.Value
            }
        }
    }
    foreach ($entry in $script:wasmClassFieldTypeHints.GetEnumerator()) {
        $prefix = "$ClassName."
        if ([string]$entry.Key -like "$prefix*") {
            $types[([string]$entry.Key).Substring($prefix.Length)] = [string]$entry.Value
        }
    }
    return $types
}

function Get-WasmAstClassFieldTypeHint {
    param([string]$ClassName, [string]$FieldName)

    if ([string]::IsNullOrWhiteSpace($ClassName) -or [string]::IsNullOrWhiteSpace($FieldName)) { return "" }
    $types = Get-WasmAstClassFieldTypeHints $ClassName
    if ($types.ContainsKey($FieldName)) { return [string]$types[$FieldName] }
    return ""
}

function Test-WasmAstReturnValuePreservingFromBody {
    param($Body, [hashtable]$Seen = @{})

    if ($null -eq $Body) { return $false }
    foreach ($stmt in @(As-WasmAstArray ($Body.body))) {
        if ($null -eq $stmt) { continue }
        switch ([string]$stmt.node) {
            "RETURN" {
                if (Test-WasmAstValuePreservingExprCandidate ($stmt.value) $Seen) { return $true }
            }
            "SuraBlock" {
                if (Test-WasmAstReturnValuePreservingFromBody $stmt $Seen) { return $true }
            }
            "IF" {
                if ((Test-WasmAstReturnValuePreservingFromBody ($stmt.then_block) $Seen) -or
                    (Test-WasmAstReturnValuePreservingFromBody ($stmt.else_block) $Seen)) {
                    return $true
                }
            }
            "WHILE" {
                if (Test-WasmAstReturnValuePreservingFromBody ($stmt.body) $Seen) { return $true }
            }
            "REPEAT" {
                if (Test-WasmAstReturnValuePreservingFromBody ($stmt.body) $Seen) { return $true }
            }
            "FOR" {
                if (Test-WasmAstReturnValuePreservingFromBody ($stmt.body) $Seen) { return $true }
            }
            "FOREACH" {
                if (Test-WasmAstReturnValuePreservingFromBody ($stmt.body) $Seen) { return $true }
            }
            "MATCH" {
                foreach ($arm in @(As-WasmAstArray ($stmt.arms))) {
                    if (Test-WasmAstReturnValuePreservingFromBody ($arm.body) $Seen) { return $true }
                }
            }
            "TRY" {
                if ((Test-WasmAstReturnValuePreservingFromBody ($stmt.try_block) $Seen) -or
                    (Test-WasmAstReturnValuePreservingFromBody ($stmt.catch_block) $Seen) -or
                    (Test-WasmAstReturnValuePreservingFromBody ($stmt.finally_block) $Seen)) {
                    return $true
                }
                # A return in both the try and catch paths can carry different
                # runtime types (including an exception payload identifier
                # whose type is known only after throw-flow analysis). Use the
                # tagged return ABI conservatively instead of compiling one
                # branch as a raw i32 based on whichever branch was inspected
                # first.
                $tryHasReturn = Test-WasmAstBodyContainsReturn ($stmt.try_block)
                $catchHasReturn = Test-WasmAstBodyContainsReturn ($stmt.catch_block)
                $finallyHasReturn = Test-WasmAstBodyContainsReturn ($stmt.finally_block)
                if (($tryHasReturn -and $catchHasReturn) -or
                    ($finallyHasReturn -and ($tryHasReturn -or $catchHasReturn))) {
                    return $true
                }
            }
            default { }
        }
    }
    return $false
}

function Test-WasmAstBodyContainsReturn {
    param($Body)

    if ($null -eq $Body) { return $false }
    foreach ($stmt in @(As-WasmAstArray ($Body.body))) {
        if ($null -eq $stmt) { continue }
        switch ([string]$stmt.node) {
            "RETURN" { return $true }
            "SuraBlock" {
                if (Test-WasmAstBodyContainsReturn $stmt) { return $true }
            }
            "IF" {
                if ((Test-WasmAstBodyContainsReturn ($stmt.then_block)) -or
                    (Test-WasmAstBodyContainsReturn ($stmt.else_block))) { return $true }
            }
            { $_ -in @("WHILE", "REPEAT", "FOR", "FOREACH") } {
                if (Test-WasmAstBodyContainsReturn ($stmt.body)) { return $true }
            }
            "MATCH" {
                foreach ($arm in @(As-WasmAstArray ($stmt.arms))) {
                    if (Test-WasmAstBodyContainsReturn ($arm.body)) { return $true }
                }
            }
            "TRY" {
                if ((Test-WasmAstBodyContainsReturn ($stmt.try_block)) -or
                    (Test-WasmAstBodyContainsReturn ($stmt.catch_block)) -or
                    (Test-WasmAstBodyContainsReturn ($stmt.finally_block))) { return $true }
            }
            default { }
        }
    }
    return $false
}

function Get-WasmAstShallowReturnValueType {
    param($Node)

    if ($null -eq $Node) { return "nil" }
    switch ([string]$Node.node) {
        "STR_LIT" { return "string" }
        "STR_INTERP" { return "string" }
        "BOOL_LIT" { return "bool" }
        "NIL_LIT" { return "nil" }
        "NUM_LIT" { return "num" }
        "ARRAY_LIT" { return "array" }
        "DICT_LIT" { return "dict" }
        "FUNC_EXPR" { return "function" }
        "TERNARY" {
            $thenType = Get-WasmAstShallowReturnValueType ($Node.then)
            $elseType = Get-WasmAstShallowReturnValueType ($Node.else)
            if ([string]::IsNullOrWhiteSpace($thenType) -or [string]::IsNullOrWhiteSpace($elseType)) { return "" }
            if ($thenType -eq $elseType) { return $thenType }
            return "value"
        }
        "BIN_OP" {
            if ([string]$Node.op -ne "??") { return "" }
            $leftType = Get-WasmAstShallowReturnValueType ($Node.left)
            $rightType = Get-WasmAstShallowReturnValueType ($Node.right)
            if ($leftType -eq "nil") { return $rightType }
            if ([string]::IsNullOrWhiteSpace($leftType) -or [string]::IsNullOrWhiteSpace($rightType)) { return "" }
            if ($leftType -eq $rightType) { return $leftType }
            return "value"
        }
        default { return "" }
    }
}

function Get-WasmAstReturnValueTypesFromBody {
    param($Body, [hashtable]$Seen = @{})

    $types = New-Object System.Collections.Generic.List[string]
    if ($null -eq $Body) { return @() }
    foreach ($stmt in @(As-WasmAstArray ($Body.body))) {
        if ($null -eq $stmt) { continue }
        switch ([string]$stmt.node) {
            "RETURN" {
                if (-not (Test-WasmAstEffectfulExpr ($stmt.value))) {
                    $typeName = Get-WasmAstShallowReturnValueType ($stmt.value)
                    if ($typeName -in @("string", "bool", "nil", "num", "array", "dict", "function", "value")) {
                        $types.Add($typeName) | Out-Null
                    }
                }
            }
            "SuraBlock" {
                foreach ($typeName in @(Get-WasmAstReturnValueTypesFromBody $stmt $Seen)) {
                    $types.Add([string]$typeName) | Out-Null
                }
            }
            "IF" {
                foreach ($block in @($stmt.then_block, $stmt.else_block)) {
                    foreach ($typeName in @(Get-WasmAstReturnValueTypesFromBody $block $Seen)) {
                        $types.Add([string]$typeName) | Out-Null
                    }
                }
            }
            { $_ -in @("WHILE", "REPEAT", "FOR", "FOREACH") } {
                foreach ($typeName in @(Get-WasmAstReturnValueTypesFromBody ($stmt.body) $Seen)) {
                    $types.Add([string]$typeName) | Out-Null
                }
            }
            "MATCH" {
                foreach ($arm in @(As-WasmAstArray ($stmt.arms))) {
                    foreach ($typeName in @(Get-WasmAstReturnValueTypesFromBody ($arm.body) $Seen)) {
                        $types.Add([string]$typeName) | Out-Null
                    }
                }
            }
            "TRY" {
                foreach ($block in @($stmt.try_block, $stmt.catch_block, $stmt.finally_block)) {
                    foreach ($typeName in @(Get-WasmAstReturnValueTypesFromBody $block $Seen)) {
                        $types.Add([string]$typeName) | Out-Null
                    }
                }
            }
            default { }
        }
    }
    return @($types.ToArray() | Sort-Object -Unique)
}

function Test-WasmAstFunctionReturnValuePreserving {
    param([string]$Name, [hashtable]$Seen = @{})

    if ([string]::IsNullOrWhiteSpace($Name) -or -not $script:wasmAstFunctionDefs.ContainsKey($Name)) { return $false }
    if (-not [string]::IsNullOrWhiteSpace((Get-WasmAstAnnotatedRawReturnKind $script:wasmAstFunctionDefs[$Name].Node)) -and
        -not ($null -ne $script:wasmEscapingFunctionValueNames -and $script:wasmEscapingFunctionValueNames.ContainsKey($Name))) {
        # An explicit scalar return annotation pins the raw ABI. It overrides
        # flow-propagated value-return inference, but not the escaping rule: a
        # function used as a value must keep the dispatcher's tagged ABI.
        $script:wasmFunctionReturnValuePreservingCache[$Name] = $false
        return $false
    }
    if ($script:wasmForcedValueReturnFunctions.ContainsKey($Name)) { return $true }
    if ($script:wasmRawF64ExportFunctions.ContainsKey($Name)) { return $true }
    if ($script:wasmFunctionReturnValuePreservingCache.ContainsKey($Name)) {
        return [bool]$script:wasmFunctionReturnValuePreservingCache[$Name]
    }
    $cacheable = ($Seen.Count -eq 0)
    $key = "function:$Name"
    if ($Seen.ContainsKey($key)) { return $false }
    $Seen[$key] = $true
    $previousParamHints = $script:wasmCurrentFunctionParamTypeHints
    try {
        $script:wasmCurrentFunctionParamTypeHints = Get-WasmAstObservedFunctionParamTypeHints $Name
        $fn = $script:wasmAstFunctionDefs[$Name]
        if ($null -eq $fn.Node -or $null -eq $fn.Node.body) { return $false }
        $result = Test-WasmAstReturnValuePreservingFromBody ($fn.Node.body) $Seen
        if (-not $result) {
            $returnTypes = @(Get-WasmAstReturnValueTypesFromBody ($fn.Node.body) $Seen)
            $result = ($returnTypes.Count -gt 1 -or "value" -in $returnTypes)
        }
        if ($cacheable) {
            $script:wasmFunctionReturnValuePreservingCache[$Name] = [bool]$result
        }
        return [bool]$result
    } finally {
        $script:wasmCurrentFunctionParamTypeHints = $previousParamHints
        [void]$Seen.Remove($key)
    }
}

function Get-WasmAstCurrentSelfFieldTypeHint {
    param([string]$FieldName)

    if ([string]::IsNullOrWhiteSpace($script:wasmCurrentClassContext) -or [string]::IsNullOrWhiteSpace($FieldName)) {
        return ""
    }
    $typeName = Get-WasmAstClassFieldTypeHint $script:wasmCurrentClassContext $FieldName
    if (-not [string]::IsNullOrWhiteSpace($typeName)) { return $typeName }
    return (Get-WasmAstObservedClassFieldTypeHint $script:wasmCurrentClassContext $FieldName)
}

function Get-WasmAstStaticValueTypeWithParams {
    param($Node, [hashtable]$ParamTypes)

    if ($null -eq $Node) { return "nil" }
    if ([string]$Node.node -eq "CALL") {
        $callType = Get-WasmAstFunctionCallTypeHint $Node $ParamTypes
        if (-not [string]::IsNullOrWhiteSpace($callType)) { return $callType }
        $callName = [string]$Node.name
        if (-not $script:wasmAstFunctionDefs.ContainsKey($callName) -and
            $ParamTypes.ContainsKey($callName) -and
            [string]$ParamTypes[$callName] -eq "function") {
            # Function-typed locals and parameters use the indirect dispatcher,
            # whose result is always normalized to the tagged Value ABI.
            return "value"
        }
    }
    if ([string]$Node.node -eq "IDENT") {
        $name = [string]$Node.name
        if ($ParamTypes.ContainsKey($name)) { return [string]$ParamTypes[$name] }
    }
    if ([string]$Node.node -eq "BIN_OP") {
        $op = [string]$Node.op
        $leftType = Get-WasmAstStaticValueTypeWithParams ($Node.left) $ParamTypes
        $rightType = Get-WasmAstStaticValueTypeWithParams ($Node.right) $ParamTypes
        if ($op -in @("+", "-", "*", "/", "%") -and ($leftType -eq "value" -or $rightType -eq "value")) {
            return "value"
        }
        if ($op -eq "+" -and ($leftType -eq "string" -or $rightType -eq "string")) {
            return "string"
        }
        if ($op -eq "+" -and $leftType -eq "array" -and $rightType -eq "array") {
            return "array"
        }
        if ($op -eq "in") { return "value" }
        if ($op -in @("and", "or")) { return "bool" }
        if ($op -in @("+", "-", "*", "/", "%", "&", "|", "^", "<<", ">>") -and $leftType -eq "num" -and $rightType -eq "num") { return "num" }
        if ($op -in @("==", "!=", "<", "<=", ">", ">=") -and -not [string]::IsNullOrWhiteSpace($leftType) -and -not [string]::IsNullOrWhiteSpace($rightType)) { return "bool" }
    }
    if ([string]$Node.node -eq "UNARY_OP") {
        if ([string]$Node.op -eq "not") { return "bool" }
    }
    if ([string]$Node.node -eq "TERNARY") {
        $thenType = Get-WasmAstStaticValueTypeWithParams ($Node.then) $ParamTypes
        $elseType = Get-WasmAstStaticValueTypeWithParams ($Node.else) $ParamTypes
        if (-not [string]::IsNullOrWhiteSpace($thenType) -and $thenType -eq $elseType) {
            return $thenType
        }
    }
    if (Test-WasmAstValuePreservingExprCandidate $Node) { return "value" }
    return (Get-WasmAstStaticValueType $Node)
}

function Get-WasmAstStaticValueTypeWithClassSelf {
    param($Node, [string]$ClassName, [hashtable]$ParamTypes = @{}, [hashtable]$LocalObjectTypes = @{})

    if ($null -eq $Node) { return "nil" }
    if ([string]$Node.node -eq "METHOD_CALL") {
        return (Get-WasmAstMethodCallTypeHint $Node $ParamTypes $ClassName $LocalObjectTypes)
    }
    if ([string]$Node.node -eq "SUPER_CALL") {
        return (Get-WasmAstSuperCallTypeHint $Node $ClassName $ParamTypes $LocalObjectTypes)
    }
    if ([string]$Node.node -eq "DOT_ACCESS" -and
        $null -ne $Node.obj -and [string]$Node.obj.node -eq "IDENT" -and [string]$Node.obj.name -eq "self") {
        $fieldType = Get-WasmAstClassFieldTypeHint $ClassName ([string]$Node.prop)
        if (-not [string]::IsNullOrWhiteSpace($fieldType)) { return $fieldType }
        return (Get-WasmAstObservedClassFieldTypeHint $ClassName ([string]$Node.prop))
    }
    if ([string]$Node.node -eq "DOT_ACCESS" -and $null -ne $Node.obj) {
        $receiverClass = Get-WasmAstObjectClassTypeWithLocals ($Node.obj) $LocalObjectTypes $ClassName @{}
        if (-not [string]::IsNullOrWhiteSpace($receiverClass)) {
            $fieldType = Get-WasmAstClassFieldTypeHint $receiverClass ([string]$Node.prop)
            if (-not [string]::IsNullOrWhiteSpace($fieldType)) { return $fieldType }
            $observedType = Get-WasmAstObservedClassFieldTypeHint $receiverClass ([string]$Node.prop)
            if (-not [string]::IsNullOrWhiteSpace($observedType)) { return $observedType }
        }
    }
    if ([string]$Node.node -eq "INDEX" -and
        $null -ne $Node.obj -and $null -ne $Node.key -and [string]$Node.key.node -eq "STR_LIT") {
        $receiverClass = Get-WasmAstObjectClassTypeWithLocals ($Node.obj) $LocalObjectTypes $ClassName @{}
        if (-not [string]::IsNullOrWhiteSpace($receiverClass)) {
            $fieldName = [string]$Node.key.value
            $fieldType = Get-WasmAstClassFieldTypeHint $receiverClass $fieldName
            if (-not [string]::IsNullOrWhiteSpace($fieldType)) { return $fieldType }
            $observedType = Get-WasmAstObservedClassFieldTypeHint $receiverClass $fieldName
            if (-not [string]::IsNullOrWhiteSpace($observedType)) { return $observedType }
        }
    }
    if ([string]$Node.node -eq "IDENT" -and $ParamTypes.ContainsKey([string]$Node.name)) {
        return [string]$ParamTypes[[string]$Node.name]
    }
    if ([string]$Node.node -eq "BIN_OP") {
        $op = [string]$Node.op
        $leftType = Get-WasmAstStaticValueTypeWithClassSelf ($Node.left) $ClassName $ParamTypes $LocalObjectTypes
        $rightType = Get-WasmAstStaticValueTypeWithClassSelf ($Node.right) $ClassName $ParamTypes $LocalObjectTypes
        if ($op -in @("+", "-", "*", "/", "%") -and ($leftType -eq "value" -or $rightType -eq "value")) {
            return "value"
        }
        if ($op -eq "+" -and ($leftType -eq "string" -or $rightType -eq "string")) {
            return "string"
        }
        if ($op -eq "+" -and $leftType -eq "array" -and $rightType -eq "array") {
            return "array"
        }
        if ($op -in @("and", "or")) { return "bool" }
        if ($op -in @("+", "-", "*", "/", "%", "&", "|", "^", "<<", ">>") -and $leftType -eq "num" -and $rightType -eq "num") { return "num" }
        if ($op -in @("==", "!=", "<", "<=", ">", ">=") -and -not [string]::IsNullOrWhiteSpace($leftType) -and -not [string]::IsNullOrWhiteSpace($rightType)) { return "bool" }
    }
    if ([string]$Node.node -eq "UNARY_OP") {
        if ([string]$Node.op -eq "not") { return "bool" }
    }
    if ([string]$Node.node -eq "TERNARY") {
        $thenType = Get-WasmAstStaticValueTypeWithClassSelf ($Node.then) $ClassName $ParamTypes $LocalObjectTypes
        $elseType = Get-WasmAstStaticValueTypeWithClassSelf ($Node.else) $ClassName $ParamTypes $LocalObjectTypes
        if (-not [string]::IsNullOrWhiteSpace($thenType) -and $thenType -eq $elseType) {
            return $thenType
        }
    }
    if (Test-WasmAstValuePreservingExprCandidate $Node) { return "value" }
    return (Get-WasmAstStaticValueTypeWithParams $Node $ParamTypes)
}

function Add-WasmAstUniqueFunctionLiftCandidate {
    param([System.Collections.Generic.List[string]]$Out, [hashtable]$Seen, [string]$LiftName)

    if ([string]::IsNullOrWhiteSpace($LiftName)) { return }
    if ($Seen.ContainsKey($LiftName)) { return }
    $Seen[$LiftName] = $true
    $Out.Add($LiftName) | Out-Null
}

function Get-WasmAstFunctionValueLiftCandidatesFromExpr {
    param(
        $Node,
        [string]$ClassName,
        [hashtable]$LocalTypes = @{},
        [hashtable]$LocalObjectTypes = @{},
        [hashtable]$LocalFunctionLiftCandidates = @{},
        [hashtable]$LocalDictFunctionLiftCandidates = @{},
        [hashtable]$LocalArrayFunctionLiftCandidates = @{}
    )

    $out = New-Object System.Collections.Generic.List[string]
    $seen = @{}
    if ($null -eq $Node) { return @() }

    switch ([string]$Node.node) {
        "FUNC_EXPR" {
            if ($Node.PSObject.Properties.Name -contains "__wasm_func_expr_lift_name" -and
                -not (Test-WasmAstFuncExprLiftSkipped $Node)) {
                Add-WasmAstUniqueFunctionLiftCandidate $out $seen ([string]$Node.__wasm_func_expr_lift_name)
            }
        }
        "IDENT" {
            $name = [string]$Node.name
            if ($LocalFunctionLiftCandidates.ContainsKey($name)) {
                foreach ($candidate in @($LocalFunctionLiftCandidates[$name])) {
                    Add-WasmAstUniqueFunctionLiftCandidate $out $seen ([string]$candidate)
                }
            }
            if ($script:wasmAstFunctionDefs.ContainsKey($name)) {
                Add-WasmAstUniqueFunctionLiftCandidate $out $seen $name
            }
            if ($script:wasmCurrentLocalFunctionLiftHints.ContainsKey($name)) {
                Add-WasmAstUniqueFunctionLiftCandidate $out $seen ([string]$script:wasmCurrentLocalFunctionLiftHints[$name])
            }
            if ($script:wasmGlobalFunctionLiftHints.ContainsKey($name)) {
                Add-WasmAstUniqueFunctionLiftCandidate $out $seen ([string]$script:wasmGlobalFunctionLiftHints[$name])
            }
        }
        "TERNARY" {
            foreach ($candidate in @(Get-WasmAstFunctionValueLiftCandidatesFromExpr ($Node.then) $ClassName $LocalTypes $LocalObjectTypes $LocalFunctionLiftCandidates $LocalDictFunctionLiftCandidates $LocalArrayFunctionLiftCandidates)) {
                Add-WasmAstUniqueFunctionLiftCandidate $out $seen ([string]$candidate)
            }
            foreach ($candidate in @(Get-WasmAstFunctionValueLiftCandidatesFromExpr ($Node.else) $ClassName $LocalTypes $LocalObjectTypes $LocalFunctionLiftCandidates $LocalDictFunctionLiftCandidates $LocalArrayFunctionLiftCandidates)) {
                Add-WasmAstUniqueFunctionLiftCandidate $out $seen ([string]$candidate)
            }
        }
        "CALL" {
            $name = [string]$Node.name
            $calleeCandidates = @()
            if (-not [string]::IsNullOrWhiteSpace($name)) {
                if ($script:wasmAstFunctionDefs.ContainsKey($name)) {
                    $calleeCandidates = @($name)
                } elseif ($LocalFunctionLiftCandidates.ContainsKey($name)) {
                    $calleeCandidates = @($LocalFunctionLiftCandidates[$name])
                }
            }
            foreach ($calleeCandidate in $calleeCandidates) {
                $calleeName = [string]$calleeCandidate
                if ([string]::IsNullOrWhiteSpace($calleeName) -or
                    -not $script:wasmAstFunctionDefs.ContainsKey($calleeName)) {
                    continue
                }
                $candidateLocals = @{}
                $fn = $script:wasmAstFunctionDefs[$calleeName]
                $params = @([string[]]$fn.Params)
                $args = @(As-WasmAstArray ($Node.args))
                for ($i = 0; $i -lt $params.Count -and $i -lt $args.Count; $i++) {
                    $argCandidates = @(Get-WasmAstFunctionValueLiftCandidatesFromExpr ($args[$i]) $ClassName $LocalTypes $LocalObjectTypes $LocalFunctionLiftCandidates $LocalDictFunctionLiftCandidates $LocalArrayFunctionLiftCandidates)
                    if ($argCandidates.Count -gt 0) {
                        $candidateLocals[[string]$params[$i]] = [string[]]$argCandidates
                    }
                }
                foreach ($candidate in @(Get-WasmAstFunctionReturnLiftCandidatesFromBody ($fn.Node.body) "" $candidateLocals @{})) {
                    Add-WasmAstUniqueFunctionLiftCandidate $out $seen ([string]$candidate)
                }
            }
        }
        "METHOD_CALL" {
            $receiverClass = Get-WasmAstObjectClassTypeWithLocals ($Node.obj) $LocalObjectTypes $ClassName @{}
            if (-not [string]::IsNullOrWhiteSpace($receiverClass)) {
                $methodInfo = Get-WasmAstClassMethod -ClassName $receiverClass -MethodName ([string]$Node.method)
                if ($null -ne $methodInfo) {
                    $candidateLocals = @{}
                    $params = @(Get-WasmAstParamNames ($methodInfo.Method.params))
                    $args = @(As-WasmAstArray ($Node.args))
                    for ($i = 0; $i -lt $params.Count -and $i -lt $args.Count; $i++) {
                        $argCandidates = @(Get-WasmAstFunctionValueLiftCandidatesFromExpr ($args[$i]) $ClassName $LocalTypes $LocalObjectTypes $LocalFunctionLiftCandidates $LocalDictFunctionLiftCandidates $LocalArrayFunctionLiftCandidates)
                        if ($argCandidates.Count -gt 0) {
                            $candidateLocals[[string]$params[$i]] = [string[]]$argCandidates
                        }
                    }
                    foreach ($candidate in @(Get-WasmAstFunctionReturnLiftCandidatesFromBody ($methodInfo.Method.body) ([string]$methodInfo.ClassName) $candidateLocals @{})) {
                        Add-WasmAstUniqueFunctionLiftCandidate $out $seen ([string]$candidate)
                    }
                }
            }
        }
        "METHOD_CALL" {
            if ($null -eq $Node.obj) { break }
            $methodClassName = Get-WasmAstObjectClassTypeWithLocals ($Node.obj) $LocalObjectTypes $ClassName @{}
            if ([string]::IsNullOrWhiteSpace($methodClassName)) { break }
            $methodInfo = Get-WasmAstClassMethod -ClassName $methodClassName -MethodName ([string]$Node.method)
            if ($null -eq $methodInfo) { break }
            $candidateLocals = @{}
            $params = @(Get-WasmAstParamNames ($methodInfo.Method.params))
            $args = @(As-WasmAstArray ($Node.args))
            for ($i = 0; $i -lt $params.Count -and $i -lt $args.Count; $i++) {
                $argCandidates = @(Get-WasmAstFunctionValueLiftCandidatesFromExpr ($args[$i]) $ClassName $LocalTypes $LocalObjectTypes $LocalFunctionLiftCandidates $LocalDictFunctionLiftCandidates $LocalArrayFunctionLiftCandidates)
                if ($argCandidates.Count -gt 0) {
                    $candidateLocals[[string]$params[$i]] = [string[]]$argCandidates
                }
            }
            foreach ($candidate in @(Get-WasmAstFunctionReturnLiftCandidatesFromBody ($methodInfo.Method.body) ([string]$methodInfo.ClassName) $candidateLocals @{})) {
                Add-WasmAstUniqueFunctionLiftCandidate $out $seen ([string]$candidate)
            }
        }
        "DOT_ACCESS" {
            $accessKey = Get-WasmAstStringAccessHintKey $Node
            if (-not [string]::IsNullOrWhiteSpace($accessKey) -and
                -not $script:wasmConflictedAccessFunctionLiftHints.ContainsKey($accessKey) -and
                $script:wasmAccessFunctionLiftHints.ContainsKey($accessKey)) {
                Add-WasmAstUniqueFunctionLiftCandidate $out $seen ([string]$script:wasmAccessFunctionLiftHints[$accessKey])
            }
        }
        "INDEX" {
            $accessKey = Get-WasmAstStringAccessHintKey $Node
            if (-not [string]::IsNullOrWhiteSpace($accessKey) -and
                -not $script:wasmConflictedAccessFunctionLiftHints.ContainsKey($accessKey) -and
                $script:wasmAccessFunctionLiftHints.ContainsKey($accessKey)) {
                Add-WasmAstUniqueFunctionLiftCandidate $out $seen ([string]$script:wasmAccessFunctionLiftHints[$accessKey])
            }
            if ($null -ne $Node.obj -and [string]$Node.obj.node -eq "IDENT" -and $null -ne $Node.key) {
                $baseName = [string]$Node.obj.name
                $objType = Get-WasmAstStaticValueTypeWithClassSelf ($Node.obj) $ClassName $LocalTypes $LocalObjectTypes
                if ([string]::IsNullOrWhiteSpace($objType)) { $objType = Get-WasmAstStaticValueType ($Node.obj) }
                $keyType = Get-WasmAstStaticValueTypeWithClassSelf ($Node.key) $ClassName $LocalTypes $LocalObjectTypes
                if ([string]::IsNullOrWhiteSpace($keyType)) { $keyType = Get-WasmAstStaticValueType ($Node.key) }
                if (($objType -eq "dict" -or $LocalDictFunctionLiftCandidates.ContainsKey($baseName)) -and
                    $keyType -eq "string") {
                    if ($LocalDictFunctionLiftCandidates.ContainsKey($baseName)) {
                        foreach ($candidate in @($LocalDictFunctionLiftCandidates[$baseName])) {
                            Add-WasmAstUniqueFunctionLiftCandidate $out $seen ([string]$candidate)
                        }
                    }
                    $prefix = "$baseName."
                    foreach ($entry in $script:wasmAccessFunctionLiftHints.GetEnumerator()) {
                        $key = [string]$entry.Key
                        if ($key.StartsWith($prefix) -and
                            -not $script:wasmConflictedAccessFunctionLiftHints.ContainsKey($key) -and
                            -not $script:wasmConflictedAccessTypeHints.ContainsKey($key) -and
                            $script:wasmAccessTypeHints.ContainsKey($key) -and
                            [string]$script:wasmAccessTypeHints[$key] -eq "function") {
                            Add-WasmAstUniqueFunctionLiftCandidate $out $seen ([string]$entry.Value)
                        }
                    }
                }
                if (($objType -eq "array" -or $LocalArrayFunctionLiftCandidates.ContainsKey($baseName)) -and
                    $keyType -ne "string") {
                    if ($LocalArrayFunctionLiftCandidates.ContainsKey($baseName)) {
                        foreach ($candidate in @($LocalArrayFunctionLiftCandidates[$baseName])) {
                            Add-WasmAstUniqueFunctionLiftCandidate $out $seen ([string]$candidate)
                        }
                    }
                    $prefix = "$baseName["
                    foreach ($entry in $script:wasmAccessFunctionLiftHints.GetEnumerator()) {
                        $key = [string]$entry.Key
                        if ($key.StartsWith($prefix) -and $key.EndsWith("]") -and
                            -not $script:wasmConflictedAccessFunctionLiftHints.ContainsKey($key) -and
                            -not $script:wasmConflictedAccessTypeHints.ContainsKey($key) -and
                            $script:wasmAccessTypeHints.ContainsKey($key) -and
                            [string]$script:wasmAccessTypeHints[$key] -eq "function") {
                            Add-WasmAstUniqueFunctionLiftCandidate $out $seen ([string]$entry.Value)
                        }
                    }
                }
            }
        }
        default { }
    }

    return @($out.ToArray())
}

function Get-WasmAstFunctionReturnLiftCandidatesFromBody {
    param(
        $Body,
        [string]$ClassName = "",
        [hashtable]$LocalFunctionLiftCandidates = @{},
        [hashtable]$Seen = @{},
        [hashtable]$LocalDictFunctionLiftCandidates = @{},
        [hashtable]$LocalArrayFunctionLiftCandidates = @{}
    )

    $out = New-Object System.Collections.Generic.List[string]
    $outSeen = @{}
    if ($null -eq $Body) { return @() }
    $bodyIdentity = [System.Runtime.CompilerServices.RuntimeHelpers]::GetHashCode($Body)
    $seenKey = "function-return-lifts:$bodyIdentity"
    if ($Seen.ContainsKey($seenKey)) { return @() }
    $Seen[$seenKey] = $true
    $locals = Copy-WasmAstFunctionLiftCandidateHints $LocalFunctionLiftCandidates
    $localDicts = Copy-WasmAstFunctionLiftCandidateHints $LocalDictFunctionLiftCandidates
    $localArrays = Copy-WasmAstFunctionLiftCandidateHints $LocalArrayFunctionLiftCandidates
    try {
        foreach ($stmt in @(As-WasmAstArray ($Body.body))) {
            if ($null -eq $stmt) { continue }
            switch ([string]$stmt.node) {
                "ASSIGN" {
                    $name = [string]$stmt.name
                    $candidates = @(Get-WasmAstFunctionValueLiftCandidatesFromExpr ($stmt.value) $ClassName @{} @{} $locals $localDicts $localArrays)
                    if ($candidates.Count -gt 0) {
                        $locals[$name] = [string[]]$candidates
                    } elseif ($locals.ContainsKey($name)) {
                        [void]$locals.Remove($name)
                    }
                    $dictCandidates = @(Get-WasmAstDictLiteralFunctionLiftCandidates ($stmt.value) $ClassName @{} @{} $locals $localDicts $localArrays)
                    if ($dictCandidates.Count -gt 0) {
                        $localDicts[$name] = [string[]]$dictCandidates
                    } elseif ($localDicts.ContainsKey($name)) {
                        [void]$localDicts.Remove($name)
                    }
                    $arrayCandidates = @(Get-WasmAstArrayLiteralFunctionLiftCandidates ($stmt.value) $ClassName @{} @{} $locals $localDicts $localArrays)
                    if ($arrayCandidates.Count -gt 0) {
                        $localArrays[$name] = [string[]]$arrayCandidates
                    } elseif ($localArrays.ContainsKey($name)) {
                        [void]$localArrays.Remove($name)
                    }
                }
                "RETURN" {
                    foreach ($candidate in @(Get-WasmAstFunctionValueLiftCandidatesFromExpr ($stmt.value) $ClassName @{} @{} $locals $localDicts $localArrays)) {
                        Add-WasmAstUniqueFunctionLiftCandidate $out $outSeen ([string]$candidate)
                    }
                }
                "SuraBlock" {
                    foreach ($candidate in @(Get-WasmAstFunctionReturnLiftCandidatesFromBody $stmt $ClassName $locals $Seen $localDicts $localArrays)) {
                        Add-WasmAstUniqueFunctionLiftCandidate $out $outSeen ([string]$candidate)
                    }
                }
                "IF" {
                    foreach ($branch in @($stmt.then_block, $stmt.else_block)) {
                        foreach ($candidate in @(Get-WasmAstFunctionReturnLiftCandidatesFromBody $branch $ClassName $locals $Seen $localDicts $localArrays)) {
                            Add-WasmAstUniqueFunctionLiftCandidate $out $outSeen ([string]$candidate)
                        }
                    }
                }
                "MATCH" {
                    foreach ($arm in @(As-WasmAstArray ($stmt.arms))) {
                        foreach ($candidate in @(Get-WasmAstFunctionReturnLiftCandidatesFromBody ($arm.body) $ClassName $locals $Seen $localDicts $localArrays)) {
                            Add-WasmAstUniqueFunctionLiftCandidate $out $outSeen ([string]$candidate)
                        }
                    }
                }
                "TRY" {
                    foreach ($branch in @($stmt.try_block, $stmt.catch_block, $stmt.finally_block)) {
                        foreach ($candidate in @(Get-WasmAstFunctionReturnLiftCandidatesFromBody $branch $ClassName $locals $Seen $localDicts $localArrays)) {
                            Add-WasmAstUniqueFunctionLiftCandidate $out $outSeen ([string]$candidate)
                        }
                    }
                }
                default { }
            }
        }
    } finally {
        [void]$Seen.Remove($seenKey)
    }
    return @($out.ToArray())
}

function Get-WasmAstDictLiteralFunctionLiftCandidates {
    param(
        $Node,
        [string]$ClassName,
        [hashtable]$LocalTypes = @{},
        [hashtable]$LocalObjectTypes = @{},
        [hashtable]$LocalFunctionLiftCandidates = @{},
        [hashtable]$LocalDictFunctionLiftCandidates = @{},
        [hashtable]$LocalArrayFunctionLiftCandidates = @{}
    )

    $out = New-Object System.Collections.Generic.List[string]
    $seen = @{}
    if ($null -eq $Node -or [string]$Node.node -ne "DICT_LIT") { return @() }
    $entries = @(As-WasmAstArray ($Node.entries))
    if ($entries.Count -eq 0) { return @() }
    foreach ($entry in $entries) {
        $entryCandidates = @(Get-WasmAstFunctionValueLiftCandidatesFromExpr ($entry.value) $ClassName $LocalTypes $LocalObjectTypes $LocalFunctionLiftCandidates $LocalDictFunctionLiftCandidates $LocalArrayFunctionLiftCandidates)
        if ($entryCandidates.Count -eq 0) { return @() }
        foreach ($candidate in $entryCandidates) {
            Add-WasmAstUniqueFunctionLiftCandidate $out $seen ([string]$candidate)
        }
    }
    return @($out.ToArray())
}

function Get-WasmAstArrayLiteralFunctionLiftCandidates {
    param(
        $Node,
        [string]$ClassName,
        [hashtable]$LocalTypes = @{},
        [hashtable]$LocalObjectTypes = @{},
        [hashtable]$LocalFunctionLiftCandidates = @{},
        [hashtable]$LocalDictFunctionLiftCandidates = @{},
        [hashtable]$LocalArrayFunctionLiftCandidates = @{}
    )

    $out = New-Object System.Collections.Generic.List[string]
    $seen = @{}
    if ($null -eq $Node -or [string]$Node.node -ne "ARRAY_LIT") { return @() }
    $elements = @(As-WasmAstArray ($Node.elements))
    if ($elements.Count -eq 0) { return @() }
    foreach ($element in $elements) {
        $entryCandidates = @(Get-WasmAstFunctionValueLiftCandidatesFromExpr $element $ClassName $LocalTypes $LocalObjectTypes $LocalFunctionLiftCandidates $LocalDictFunctionLiftCandidates $LocalArrayFunctionLiftCandidates)
        if ($entryCandidates.Count -eq 0) { return @() }
        foreach ($candidate in $entryCandidates) {
            Add-WasmAstUniqueFunctionLiftCandidate $out $seen ([string]$candidate)
        }
    }
    return @($out.ToArray())
}

function Get-WasmAstFunctionValueCallReturnTypeHint {
    param(
        $CallNode,
        [hashtable]$LocalTypes = @{},
        [hashtable]$LocalFunctionLiftCandidates = @{}
    )

    if ($null -eq $CallNode -or [string]$CallNode.node -ne "CALL") { return "" }
    $name = [string]$CallNode.name
    if ([string]::IsNullOrWhiteSpace($name) -or -not $LocalFunctionLiftCandidates.ContainsKey($name)) { return "" }

    $types = New-Object System.Collections.Generic.List[string]
    $candidateCount = 0
    foreach ($candidate in @($LocalFunctionLiftCandidates[$name])) {
        $liftName = [string]$candidate
        if ([string]::IsNullOrWhiteSpace($liftName) -or -not $script:wasmAstFunctionDefs.ContainsKey($liftName)) { continue }
        $candidateCount++
        $candidateParams = @([string[]]$script:wasmAstFunctionDefs[$liftName].Params)
        $callArgs = @(As-WasmAstArray ($CallNode.args))
        for ($argIndex = 0; $argIndex -lt $candidateParams.Count -and $argIndex -lt $callArgs.Count; $argIndex++) {
            # Indirect function-value calls use one stable tagged argument ABI.
            # A later call can carry a fractional number, a large integer, or a
            # different runtime type even when an earlier call looked like a raw
            # i32. Keep every reachable candidate parameter on the Value ABI so
            # the dispatcher never has to reinterpret the same i32 differently.
            Set-WasmAstForwardedFunctionParamTypeHint $liftName ([string]$candidateParams[$argIndex]) "value"
        }
        $fakeCall = [pscustomobject]@{
            node = "CALL"
            name = $liftName
            args = @($callArgs)
        }
        $typeName = Get-WasmAstFunctionCallTypeHint $fakeCall $LocalTypes
        if ($typeName -notin @("string", "bool", "nil", "num", "array", "dict", "function", "value")) {
            return ""
        }
        $types.Add($typeName) | Out-Null
    }
    if ($candidateCount -eq 0 -or $types.Count -ne $candidateCount) { return "" }
    # Calls represented by a function-value candidate set are lowered through
    # __sura_call_function_N. The dispatcher normalizes every successful
    # candidate result to the tagged Value ABI, even when every candidate has
    # the same semantic source type.
    return "value"
}

function Get-WasmAstCurrentFunctionValueCallReturnTypeHint {
    param(
        $CallNode,
        [hashtable]$LocalTypes = @{},
        [hashtable]$LocalFunctionLiftCandidates = @{}
    )

    if ($null -eq $CallNode -or [string]$CallNode.node -ne "CALL") { return "" }
    $name = [string]$CallNode.name
    if ([string]::IsNullOrWhiteSpace($name) -or -not $LocalFunctionLiftCandidates.ContainsKey($name)) { return "" }

    $types = New-Object System.Collections.Generic.List[string]
    $candidateCount = 0
    foreach ($candidate in @($LocalFunctionLiftCandidates[$name])) {
        $liftName = [string]$candidate
        if ([string]::IsNullOrWhiteSpace($liftName) -or -not $script:wasmAstFunctionDefs.ContainsKey($liftName)) { continue }
        $candidateCount++
        if (Test-WasmAstFunctionReturnValuePreserving $liftName) {
            $types.Add("value") | Out-Null
            continue
        }
        $fakeCall = [pscustomobject]@{
            node = "CALL"
            name = $liftName
            args = @(As-WasmAstArray ($CallNode.args))
        }
        $typeName = Get-WasmAstFunctionCallTypeHint $fakeCall $LocalTypes
        if ($typeName -notin @("string", "bool", "nil", "num", "array", "dict", "function", "value")) {
            return ""
        }
        $types.Add($typeName) | Out-Null
    }
    if ($candidateCount -eq 0 -or $types.Count -ne $candidateCount) { return "" }
    # Exact lifted aliases are handled before this helper. Remaining candidate
    # calls use the indirect dispatcher and therefore always return a tagged
    # Value at the WASM boundary.
    return "value"
}

function Get-WasmAstFlowHintsAfterBody {
    param($Body, [string]$ClassName, [hashtable]$BaseTypes = @{}, [hashtable]$BaseObjects = @{})

    $localTypes = Copy-WasmAstTypeHints $BaseTypes
    $localObjects = Copy-WasmAstTypeHints $BaseObjects
    if ($null -eq $Body) {
        return [pscustomobject]@{ ValueTypes = $localTypes; ObjectTypes = $localObjects }
    }
    foreach ($stmt in @(As-WasmAstArray ($Body.body))) {
        if ($null -eq $stmt) { continue }
        switch ([string]$stmt.node) {
            "ASSIGN" {
                $objectClass = Get-WasmAstObjectClassTypeWithLocals ($stmt.value) $localObjects $ClassName @{}
                if (-not [string]::IsNullOrWhiteSpace($objectClass)) {
                    $localObjects[[string]$stmt.name] = $objectClass
                } elseif ($localObjects.ContainsKey([string]$stmt.name)) {
                    $localObjects.Remove([string]$stmt.name)
                }
                $typeName = Get-WasmAstStaticValueTypeWithClassSelf ($stmt.value) $ClassName $localTypes $localObjects
                if ($typeName -in @("string", "bool", "nil", "num", "array", "dict", "function")) {
                    $localTypes[[string]$stmt.name] = $typeName
                } else {
                    if ($localTypes.ContainsKey([string]$stmt.name)) {
                        $localTypes.Remove([string]$stmt.name)
                    }
                }
            }
            "SuraBlock" {
                $flow = Get-WasmAstFlowHintsAfterBody $stmt $ClassName $localTypes $localObjects
                $localTypes = Copy-WasmAstTypeHints $flow.ValueTypes
                $localObjects = Copy-WasmAstTypeHints $flow.ObjectTypes
            }
            "IF" {
                $thenFlow = Get-WasmAstFlowHintsAfterBody ($stmt.then_block) $ClassName $localTypes $localObjects
                if ($null -ne $stmt.else_block) {
                    $elseFlow = Get-WasmAstFlowHintsAfterBody ($stmt.else_block) $ClassName $localTypes $localObjects
                } else {
                    $elseFlow = [pscustomobject]@{
                        ValueTypes = Copy-WasmAstTypeHints $localTypes
                        ObjectTypes = Copy-WasmAstTypeHints $localObjects
                    }
                }
                $localTypes = Merge-WasmAstLocalValueTypeHints $thenFlow.ValueTypes $elseFlow.ValueTypes
                $localObjects = Merge-WasmAstLocalObjectClassHints $thenFlow.ObjectTypes $elseFlow.ObjectTypes
            }
            "MATCH" {
                $beforeTypes = Copy-WasmAstTypeHints $localTypes
                $beforeObjects = Copy-WasmAstTypeHints $localObjects
                $mergedTypes = $null
                $mergedObjects = $null
                $hasWildcardArm = $false
                foreach ($arm in @(As-WasmAstArray ($stmt.arms))) {
                    if ([bool]$arm.is_wildcard) { $hasWildcardArm = $true }
                    $armFlow = Get-WasmAstFlowHintsAfterBody ($arm.body) $ClassName $beforeTypes $beforeObjects
                    if ($null -eq $mergedTypes) {
                        $mergedTypes = Copy-WasmAstTypeHints $armFlow.ValueTypes
                    } else {
                        $mergedTypes = Merge-WasmAstLocalValueTypeHints $mergedTypes $armFlow.ValueTypes
                    }
                    if ($null -eq $mergedObjects) {
                        $mergedObjects = Copy-WasmAstTypeHints $armFlow.ObjectTypes
                    } else {
                        $mergedObjects = Merge-WasmAstLocalObjectClassHints $mergedObjects $armFlow.ObjectTypes
                    }
                }
                if ($null -eq $mergedTypes) { $mergedTypes = Copy-WasmAstTypeHints $beforeTypes }
                if ($null -eq $mergedObjects) { $mergedObjects = Copy-WasmAstTypeHints $beforeObjects }
                if (-not $hasWildcardArm) {
                    $mergedTypes = Merge-WasmAstLocalValueTypeHints $mergedTypes $beforeTypes
                    $mergedObjects = Merge-WasmAstLocalObjectClassHints $mergedObjects $beforeObjects
                }
                $localTypes = $mergedTypes
                $localObjects = $mergedObjects
            }
            "RETURN" {
                return [pscustomobject]@{ ValueTypes = $localTypes; ObjectTypes = $localObjects }
            }
            default { }
        }
    }
    return [pscustomobject]@{ ValueTypes = $localTypes; ObjectTypes = $localObjects }
}

function Get-WasmAstReturnTypeFromBody {
    param(
        $Body,
        [string]$ClassName,
        [hashtable]$ParamTypes = @{},
        [hashtable]$ParamObjectTypes = @{},
        [hashtable]$LocalIndexedAccessHints = @{}
    )

    if ($null -eq $Body) { return "" }
    $localTypes = @{}
    foreach ($entry in $ParamTypes.GetEnumerator()) {
        $localTypes[[string]$entry.Key] = [string]$entry.Value
    }
    $localObjects = Copy-WasmAstTypeHints $ParamObjectTypes
    $localIndexedHints = Copy-WasmAstLocalIndexedAccessHints $LocalIndexedAccessHints
    $localFunctionLiftCandidates = @{}
    $localDictFunctionLiftCandidates = @{}
    $localArrayFunctionLiftCandidates = @{}
    $localFunctionExprs = @{}
    foreach ($stmt in @(As-WasmAstArray ($Body.body))) {
        if ($null -eq $stmt) { continue }
        switch ([string]$stmt.node) {
            "ASSIGN" {
                if ($null -ne $stmt.value -and [string]$stmt.value.node -eq "FUNC_EXPR") {
                    $localFunctionExprs[[string]$stmt.name] = $stmt.value
                } elseif ($null -ne $stmt.value -and [string]$stmt.value.node -eq "IDENT" -and
                    $localFunctionExprs.ContainsKey([string]$stmt.value.name)) {
                    $localFunctionExprs[[string]$stmt.name] = $localFunctionExprs[[string]$stmt.value.name]
                } elseif ($localFunctionExprs.ContainsKey([string]$stmt.name)) {
                    $localFunctionExprs.Remove([string]$stmt.name)
                }
                $objectClass = Get-WasmAstObjectClassTypeWithLocals ($stmt.value) $localObjects $ClassName @{}
                if (-not [string]::IsNullOrWhiteSpace($objectClass)) {
                    $localObjects[[string]$stmt.name] = $objectClass
                } elseif ($localObjects.ContainsKey([string]$stmt.name)) {
                    $localObjects.Remove([string]$stmt.name)
                }
                $typeName = Get-WasmAstStaticValueTypeWithClassSelf ($stmt.value) $ClassName $localTypes $localObjects
                if ([string]::IsNullOrWhiteSpace($typeName) -and
                    $null -ne $stmt.value -and [string]$stmt.value.node -eq "INDEX" -and
                    $null -ne $stmt.value.obj -and [string]$stmt.value.obj.node -eq "IDENT" -and
                    $localDictFunctionLiftCandidates.ContainsKey([string]$stmt.value.obj.name)) {
                    $dictKeyType = Get-WasmAstStaticValueTypeWithClassSelf ($stmt.value.key) $ClassName $localTypes $localObjects
                    if ([string]::IsNullOrWhiteSpace($dictKeyType)) { $dictKeyType = Get-WasmAstStaticValueType ($stmt.value.key) }
                    if ($dictKeyType -eq "string") { $typeName = "function" }
                }
                if ([string]::IsNullOrWhiteSpace($typeName) -and
                    $null -ne $stmt.value -and [string]$stmt.value.node -eq "INDEX" -and
                    $null -ne $stmt.value.obj -and [string]$stmt.value.obj.node -eq "IDENT" -and
                    $localArrayFunctionLiftCandidates.ContainsKey([string]$stmt.value.obj.name)) {
                    $arrayKeyType = Get-WasmAstStaticValueTypeWithClassSelf ($stmt.value.key) $ClassName $localTypes $localObjects
                    if ([string]::IsNullOrWhiteSpace($arrayKeyType)) { $arrayKeyType = Get-WasmAstStaticValueType ($stmt.value.key) }
                    if ($arrayKeyType -ne "string") { $typeName = "function" }
                }
                if ($typeName -in @("string", "bool", "nil", "num", "array", "dict", "function", "value")) {
                    $localTypes[[string]$stmt.name] = $typeName
                }
                $assignedIndexedHints = Get-WasmAstFixedIndexedAccessHintsForExpr ($stmt.value) $localIndexedHints
                if ($typeName -eq "array" -and (Test-WasmAstFixedIndexedHintMapHasItems $assignedIndexedHints)) {
                    $localIndexedHints[[string]$stmt.name] = Copy-WasmAstFixedIndexedHintMap $assignedIndexedHints
                } elseif ($localIndexedHints.ContainsKey([string]$stmt.name)) {
                    $localIndexedHints.Remove([string]$stmt.name)
                }
                if ($typeName -eq "function") {
                    $candidates = @(Get-WasmAstFunctionValueLiftCandidatesFromExpr ($stmt.value) $ClassName $localTypes $localObjects $localFunctionLiftCandidates $localDictFunctionLiftCandidates $localArrayFunctionLiftCandidates)
                    if ($candidates.Count -gt 0) {
                        $localFunctionLiftCandidates[[string]$stmt.name] = [string[]]$candidates
                    } elseif ($localFunctionLiftCandidates.ContainsKey([string]$stmt.name)) {
                        $localFunctionLiftCandidates.Remove([string]$stmt.name)
                    }
                } elseif ($localFunctionLiftCandidates.ContainsKey([string]$stmt.name)) {
                    $localFunctionLiftCandidates.Remove([string]$stmt.name)
                }
                if ($typeName -eq "dict") {
                    $dictFunctionCandidates = @(Get-WasmAstDictLiteralFunctionLiftCandidates ($stmt.value) $ClassName $localTypes $localObjects $localFunctionLiftCandidates $localDictFunctionLiftCandidates $localArrayFunctionLiftCandidates)
                    if ($dictFunctionCandidates.Count -gt 0) {
                        $localDictFunctionLiftCandidates[[string]$stmt.name] = [string[]]$dictFunctionCandidates
                    } elseif ($localDictFunctionLiftCandidates.ContainsKey([string]$stmt.name)) {
                        $localDictFunctionLiftCandidates.Remove([string]$stmt.name)
                    }
                } elseif ($localDictFunctionLiftCandidates.ContainsKey([string]$stmt.name)) {
                    $localDictFunctionLiftCandidates.Remove([string]$stmt.name)
                }
                if ($typeName -eq "array") {
                    $arrayFunctionCandidates = @(Get-WasmAstArrayLiteralFunctionLiftCandidates ($stmt.value) $ClassName $localTypes $localObjects $localFunctionLiftCandidates $localDictFunctionLiftCandidates $localArrayFunctionLiftCandidates)
                    if ($arrayFunctionCandidates.Count -gt 0) {
                        $localArrayFunctionLiftCandidates[[string]$stmt.name] = [string[]]$arrayFunctionCandidates
                    } elseif ($localArrayFunctionLiftCandidates.ContainsKey([string]$stmt.name)) {
                        $localArrayFunctionLiftCandidates.Remove([string]$stmt.name)
                    }
                } elseif ($localArrayFunctionLiftCandidates.ContainsKey([string]$stmt.name)) {
                    $localArrayFunctionLiftCandidates.Remove([string]$stmt.name)
                }
            }
            "RETURN" {
                if ($null -ne $stmt.value -and [string]$stmt.value.node -eq "CALL" -and
                    $localFunctionExprs.ContainsKey([string]$stmt.value.name)) {
                    $funcExpr = $localFunctionExprs[[string]$stmt.value.name]
                    $inlineParamTypes = Copy-WasmAstTypeHints $localTypes
                    $inlineParams = @(Get-WasmAstParamNames ($funcExpr.params))
                    $inlineArgs = @(As-WasmAstArray ($stmt.value.args))
                    for ($i = 0; $i -lt $inlineParams.Count -and $i -lt $inlineArgs.Count; $i++) {
                        $inlineArgType = Get-WasmAstStaticValueTypeWithClassSelf ($inlineArgs[$i]) $ClassName $localTypes $localObjects
                        if ($inlineArgType -in @("string", "bool", "nil", "num", "array", "dict", "function", "value")) {
                            $inlineParamTypes[[string]$inlineParams[$i]] = $inlineArgType
                        }
                    }
                    $inlineReturnType = Get-WasmAstReturnTypeFromBody ($funcExpr.body) $ClassName $inlineParamTypes $localObjects $localIndexedHints
                    if ($inlineReturnType -in @("string", "bool", "nil", "num", "array", "dict", "function", "value")) {
                        return $inlineReturnType
                    }
                }
                $functionValueReturnType = Get-WasmAstFunctionValueCallReturnTypeHint ($stmt.value) $localTypes $localFunctionLiftCandidates
                if ($functionValueReturnType -in @("string", "bool", "nil", "num", "array", "dict", "function", "value")) {
                    return $functionValueReturnType
                }
                return (Get-WasmAstStaticValueTypeWithClassSelf ($stmt.value) $ClassName $localTypes $localObjects)
            }
            "SuraBlock" {
                $typeName = Get-WasmAstReturnTypeFromBody $stmt $ClassName $localTypes $localObjects $localIndexedHints
                if (-not [string]::IsNullOrWhiteSpace($typeName)) { return $typeName }
            }
            "IF" {
                $thenType = Get-WasmAstReturnTypeFromBody ($stmt.then_block) $ClassName $localTypes $localObjects $localIndexedHints
                $elseType = Get-WasmAstReturnTypeFromBody ($stmt.else_block) $ClassName $localTypes $localObjects $localIndexedHints
                if (-not [string]::IsNullOrWhiteSpace($thenType) -and $thenType -eq $elseType) { return $thenType }
                $thenFlow = Get-WasmAstFlowHintsAfterBody ($stmt.then_block) $ClassName $localTypes $localObjects
                if ($null -ne $stmt.else_block) {
                    $elseFlow = Get-WasmAstFlowHintsAfterBody ($stmt.else_block) $ClassName $localTypes $localObjects
                } else {
                    $elseFlow = [pscustomobject]@{
                        ValueTypes = Copy-WasmAstTypeHints $localTypes
                        ObjectTypes = Copy-WasmAstTypeHints $localObjects
                    }
                }
                $localTypes = Merge-WasmAstLocalValueTypeHints $thenFlow.ValueTypes $elseFlow.ValueTypes
                $localObjects = Merge-WasmAstLocalObjectClassHints $thenFlow.ObjectTypes $elseFlow.ObjectTypes
            }
            "WHILE" {
                $typeName = Get-WasmAstReturnTypeFromBody ($stmt.body) $ClassName $localTypes $localObjects $localIndexedHints
                if (-not [string]::IsNullOrWhiteSpace($typeName)) { return $typeName }
            }
            "REPEAT" {
                $typeName = Get-WasmAstReturnTypeFromBody ($stmt.body) $ClassName $localTypes $localObjects $localIndexedHints
                if (-not [string]::IsNullOrWhiteSpace($typeName)) { return $typeName }
            }
            "FOR" {
                $typeName = Get-WasmAstReturnTypeFromBody ($stmt.body) $ClassName $localTypes $localObjects $localIndexedHints
                if (-not [string]::IsNullOrWhiteSpace($typeName)) { return $typeName }
            }
            "FOREACH" {
                $loopTypes = Copy-WasmAstTypeHints $localTypes
                $loopObjects = Copy-WasmAstTypeHints $localObjects
                $loopVar = [string]$stmt.var
                $loopVar2 = [string]$stmt.var2
                $collectionType = Get-WasmAstStaticValueTypeWithClassSelf ($stmt.collection) $ClassName $localTypes $localObjects
                if ($collectionType -eq "dict") {
                    if (-not [string]::IsNullOrWhiteSpace($loopVar2)) {
                        $loopTypes[$loopVar] = "string"
                        $valueType = Get-WasmAstDictValueTypeHint ($stmt.collection)
                        if ($valueType -in @("string", "bool", "nil", "num", "array", "dict", "function")) {
                            $loopTypes[$loopVar2] = $valueType
                        }
                        $valueClass = Get-WasmAstDictValueObjectClassHint ($stmt.collection)
                        if (-not [string]::IsNullOrWhiteSpace($valueClass)) {
                            $loopObjects[$loopVar2] = $valueClass
                        }
                    }
                } else {
                    $elementType = Get-WasmAstArrayElementTypeHint ($stmt.collection) $localIndexedHints
                    $elementClass = Get-WasmAstArrayElementObjectClassHint ($stmt.collection)
                    if (-not [string]::IsNullOrWhiteSpace($loopVar2)) {
                        $loopTypes[$loopVar] = "num"
                        if ($elementType -in @("string", "bool", "nil", "num", "array", "dict", "function")) {
                            $loopTypes[$loopVar2] = $elementType
                        }
                        if (-not [string]::IsNullOrWhiteSpace($elementClass)) {
                            $loopObjects[$loopVar2] = $elementClass
                        }
                    } elseif ($elementType -in @("string", "bool", "nil", "num", "array", "dict", "function")) {
                        $loopTypes[$loopVar] = $elementType
                    } elseif (-not [string]::IsNullOrWhiteSpace($elementClass)) {
                        $loopObjects[$loopVar] = $elementClass
                    }
                }
                $typeName = Get-WasmAstReturnTypeFromBody ($stmt.body) $ClassName $loopTypes $loopObjects $localIndexedHints
                if (-not [string]::IsNullOrWhiteSpace($typeName)) { return $typeName }
            }
            "MATCH" {
                $armTypes = New-Object System.Collections.Generic.List[string]
                foreach ($arm in @(As-WasmAstArray ($stmt.arms))) {
                    $typeName = Get-WasmAstReturnTypeFromBody ($arm.body) $ClassName $localTypes $localObjects $localIndexedHints
                    if ($typeName -in @("string", "bool", "nil", "num", "array", "dict", "function")) {
                        $armTypes.Add($typeName) | Out-Null
                    }
                }
                if ($armTypes.Count -gt 0) {
                    $commonType = Get-WasmAstCommonTypeName ([string[]]$armTypes.ToArray())
                    if (-not [string]::IsNullOrWhiteSpace($commonType)) { return $commonType }
                }
                $flow = Get-WasmAstFlowHintsAfterBody ([pscustomobject]@{ body = @($stmt) }) $ClassName $localTypes $localObjects
                $localTypes = Copy-WasmAstTypeHints $flow.ValueTypes
                $localObjects = Copy-WasmAstTypeHints $flow.ObjectTypes
            }
            "TRY" {
                $typeName = Get-WasmAstReturnTypeFromBody ($stmt.try_block) $ClassName $localTypes $localObjects $localIndexedHints
                if (-not [string]::IsNullOrWhiteSpace($typeName)) { return $typeName }
            }
            default { }
        }
    }
    return ""
}

function Get-WasmAstObservedFunctionParamTypeStateSignature {
    $parts = New-Object System.Collections.Generic.List[string]
    foreach ($key in @($script:wasmFunctionParamTypeHints.Keys | Sort-Object)) {
        $parts.Add("H:$key=$([string]$script:wasmFunctionParamTypeHints[$key])") | Out-Null
    }
    foreach ($key in @($script:wasmConflictedFunctionParamTypeHints.Keys | Sort-Object)) {
        $parts.Add("C:$key") | Out-Null
    }
    return ($parts -join "|")
}

function Set-WasmAstForwardedFunctionParamTypeHint {
    param([string]$FunctionName, [string]$ParamName, [string]$TypeName)

    if ([string]::IsNullOrWhiteSpace($FunctionName) -or [string]::IsNullOrWhiteSpace($ParamName)) { return }
    if ($TypeName -eq "value") {
        # A forwarded parameter that already has a tagged-Value ABI must keep
        # that ABI in the callee.  Represent it with the same conflict state
        # used for parameters observed with multiple concrete types.
        $key = "$FunctionName.$ParamName"
        if ($script:wasmFunctionParamTypeHints.ContainsKey($key)) {
            $script:wasmFunctionParamTypeHints.Remove($key)
        }
        $script:wasmConflictedFunctionParamTypeHints[$key] = $true
        return
    }
    Set-WasmAstObservedFunctionParamTypeHint $FunctionName $ParamName $TypeName
}

function Get-WasmAstForwardedValueType {
    param($Node, [hashtable]$LocalTypes = @{})

    if ($null -eq $Node) { return "nil" }
    switch ([string]$Node.node) {
        "NUM_LIT" { return "num" }
        "STR_LIT" { return "string" }
        "BOOL_LIT" { return "bool" }
        "NIL_LIT" { return "nil" }
        "ARRAY_LIT" { return "array" }
        "DICT_LIT" { return "dict" }
        "FUNC_EXPR" { return "function" }
        "IDENT" {
            $name = [string]$Node.name
            if ($LocalTypes.ContainsKey($name)) { return [string]$LocalTypes[$name] }
            return ""
        }
        "STR_INTERP" { return "string" }
        "UNARY_OP" {
            if ([string]$Node.op -eq "not") { return "bool" }
            return "num"
        }
        "BIN_OP" {
            $op = [string]$Node.op
            if ($op -in @("==", "!=", "<", "<=", ">", ">=", "and", "or", "in", "is")) { return "bool" }
            if ($op -in @("-", "*", "/", "%", "**", "<<", ">>", "&", "|", "^")) { return "num" }
            if ($op -eq "+") {
                $leftType = Get-WasmAstForwardedValueType ($Node.left) $LocalTypes
                $rightType = Get-WasmAstForwardedValueType ($Node.right) $LocalTypes
                if ($leftType -eq "string" -or $rightType -eq "string") { return "string" }
                if ($leftType -eq "array" -and $rightType -eq "array") { return "array" }
                if ($leftType -eq "num" -and $rightType -eq "num") { return "num" }
                if ($leftType -eq "value" -or $rightType -eq "value") { return "value" }
            }
            return ""
        }
        "TERNARY" {
            $thenType = Get-WasmAstForwardedValueType ($Node.then) $LocalTypes
            $elseType = Get-WasmAstForwardedValueType ($Node.else) $LocalTypes
            if (-not [string]::IsNullOrWhiteSpace($thenType) -and $thenType -eq $elseType) { return $thenType }
            if ($thenType -in @("string", "bool", "nil", "num", "array", "dict", "function", "value") -and
                $elseType -in @("string", "bool", "nil", "num", "array", "dict", "function", "value")) {
                return "value"
            }
            return ""
        }
        default { return "" }
    }
}

function Register-WasmAstForwardedCallParamTypes {
    param(
        [string]$FunctionName,
        [string[]]$Params,
        $InputArgs,
        [hashtable]$LocalTypes
    )

    if ([string]::IsNullOrWhiteSpace($FunctionName) -or $null -eq $Params) { return }
    $args = @(As-WasmAstArray $InputArgs)
    for ($i = 0; $i -lt $Params.Count -and $i -lt $args.Count; $i++) {
        $argType = Get-WasmAstForwardedValueType ($args[$i]) $LocalTypes
        if ($argType -in @("string", "bool", "nil", "num", "array", "dict", "function", "value")) {
            Set-WasmAstForwardedFunctionParamTypeHint $FunctionName ([string]$Params[$i]) $argType
        }
    }
}

function Register-WasmAstForwardedParamTypesFromExpr {
    param(
        $Node,
        [hashtable]$LocalTypes,
        [string]$ClassName = ""
    )

    if ($null -eq $Node) { return }
    switch ([string]$Node.node) {
        "CALL" {
            $name = [string]$Node.name
            if ($script:wasmAstFunctionDefs.ContainsKey($name)) {
                Register-WasmAstForwardedCallParamTypes $name ([string[]]$script:wasmAstFunctionDefs[$name].Params) ($Node.args) $LocalTypes
            }
            foreach ($arg in @(As-WasmAstArray ($Node.args))) {
                Register-WasmAstForwardedParamTypesFromExpr $arg $LocalTypes $ClassName
            }
        }
        "METHOD_CALL" {
            Register-WasmAstForwardedParamTypesFromExpr ($Node.obj) $LocalTypes $ClassName
            $receiverClass = ""
            if ($null -ne $Node.obj -and [string]$Node.obj.node -eq "IDENT" -and [string]$Node.obj.name -eq "self") {
                $receiverClass = $ClassName
            } elseif ($null -ne $Node.obj -and [string]$Node.obj.node -eq "NEW_EXPR") {
                $receiverClass = [string]$Node.obj.class_name
            }
            if (-not [string]::IsNullOrWhiteSpace($receiverClass)) {
                $methodInfo = Get-WasmAstClassMethod -ClassName $receiverClass -MethodName ([string]$Node.method)
                if ($null -ne $methodInfo) {
                    Register-WasmAstForwardedCallParamTypes ([string]$methodInfo.FunctionName) ([string[]]@(Get-WasmAstParamNames ($methodInfo.Method.params))) ($Node.args) $LocalTypes
                }
            }
            foreach ($arg in @(As-WasmAstArray ($Node.args))) {
                Register-WasmAstForwardedParamTypesFromExpr $arg $LocalTypes $ClassName
            }
        }
        "SUPER_CALL" {
            if (-not [string]::IsNullOrWhiteSpace($ClassName)) {
                $methodInfo = Get-WasmAstSuperClassMethod -ClassName $ClassName -MethodName ([string]$Node.method)
                if ($null -ne $methodInfo) {
                    Register-WasmAstForwardedCallParamTypes ([string]$methodInfo.FunctionName) ([string[]]@(Get-WasmAstParamNames ($methodInfo.Method.params))) ($Node.args) $LocalTypes
                }
            }
            foreach ($arg in @(As-WasmAstArray ($Node.args))) {
                Register-WasmAstForwardedParamTypesFromExpr $arg $LocalTypes $ClassName
            }
        }
        "NEW_EXPR" {
            $newClass = [string]$Node.class_name
            if (-not [string]::IsNullOrWhiteSpace($newClass) -and $script:wasmClassDefs.ContainsKey($newClass)) {
                $init = Get-WasmAstClassInitMethod ($script:wasmClassDefs[$newClass].Node)
                if ($null -ne $init) {
                    Register-WasmAstForwardedCallParamTypes (Get-WasmClassConstructorName $newClass) ([string[]]@(Get-WasmAstParamNames ($init.params))) ($Node.args) $LocalTypes
                }
            }
            foreach ($arg in @(As-WasmAstArray ($Node.args))) {
                Register-WasmAstForwardedParamTypesFromExpr $arg $LocalTypes $ClassName
            }
        }
        "BIN_OP" {
            Register-WasmAstForwardedParamTypesFromExpr ($Node.left) $LocalTypes $ClassName
            Register-WasmAstForwardedParamTypesFromExpr ($Node.right) $LocalTypes $ClassName
        }
        "UNARY_OP" { Register-WasmAstForwardedParamTypesFromExpr ($Node.operand) $LocalTypes $ClassName }
        "TERNARY" {
            Register-WasmAstForwardedParamTypesFromExpr ($Node.cond) $LocalTypes $ClassName
            Register-WasmAstForwardedParamTypesFromExpr ($Node.then) $LocalTypes $ClassName
            Register-WasmAstForwardedParamTypesFromExpr ($Node.else) $LocalTypes $ClassName
        }
        "DOT_ACCESS" { Register-WasmAstForwardedParamTypesFromExpr ($Node.obj) $LocalTypes $ClassName }
        "INDEX" {
            Register-WasmAstForwardedParamTypesFromExpr ($Node.obj) $LocalTypes $ClassName
            Register-WasmAstForwardedParamTypesFromExpr ($Node.key) $LocalTypes $ClassName
        }
        "ARRAY_LIT" {
            foreach ($item in @(As-WasmAstArray ($Node.elements))) {
                Register-WasmAstForwardedParamTypesFromExpr $item $LocalTypes $ClassName
            }
        }
        "DICT_LIT" {
            foreach ($entry in @(As-WasmAstArray ($Node.entries))) {
                Register-WasmAstForwardedParamTypesFromExpr ($entry.value) $LocalTypes $ClassName
            }
        }
        "STR_LIT" {
            foreach ($part in @(Get-WasmAstInterpolatedTextExprNodes ([string]$Node.value))) {
                Register-WasmAstForwardedParamTypesFromExpr $part $LocalTypes $ClassName
            }
        }
        "STR_INTERP" {
            foreach ($part in @(As-WasmAstArray ($Node.parts))) {
                Register-WasmAstForwardedParamTypesFromExpr $part $LocalTypes $ClassName
            }
        }
        # Function-expression bodies are emitted as their own lifted functions
        # and must not inherit the enclosing function's local type map.
        "FUNC_EXPR" { }
        default { }
    }
}

function Register-WasmAstForwardedParamTypesFromBody {
    param(
        $Node,
        [hashtable]$LocalTypes,
        [string]$ClassName = ""
    )

    if ($null -eq $Node) { return }
    switch ([string]$Node.node) {
        "SuraBlock" {
            foreach ($stmt in @(As-WasmAstArray ($Node.body))) {
                Register-WasmAstForwardedParamTypesFromBody $stmt $LocalTypes $ClassName
            }
        }
        "ASSIGN" {
            Register-WasmAstForwardedParamTypesFromExpr ($Node.value) $LocalTypes $ClassName
            $typeName = Get-WasmAstForwardedValueType ($Node.value) $LocalTypes
            $name = [string]$Node.name
            if ($typeName -in @("string", "bool", "nil", "num", "array", "dict", "function", "value")) {
                $LocalTypes[$name] = $typeName
            } elseif ($LocalTypes.ContainsKey($name)) {
                $LocalTypes.Remove($name)
            }
        }
        "IN_PLACE" {
            Register-WasmAstForwardedParamTypesFromExpr ($Node.value) $LocalTypes $ClassName
        }
        "DOT_ASSIGN" {
            Register-WasmAstForwardedParamTypesFromExpr ($Node.value) $LocalTypes $ClassName
        }
        "INDEX_ASSIGN" {
            Register-WasmAstForwardedParamTypesFromExpr ($Node.key) $LocalTypes $ClassName
            Register-WasmAstForwardedParamTypesFromExpr ($Node.value) $LocalTypes $ClassName
        }
        "EXPR_STMT" { Register-WasmAstForwardedParamTypesFromExpr ($Node.expr) $LocalTypes $ClassName }
        "RETURN" { Register-WasmAstForwardedParamTypesFromExpr ($Node.value) $LocalTypes $ClassName }
        "THROW" { Register-WasmAstForwardedParamTypesFromExpr ($Node.msg) $LocalTypes $ClassName }
        "CMD" {
            foreach ($arg in @(As-WasmAstArray ($Node.args))) {
                Register-WasmAstForwardedParamTypesFromExpr $arg $LocalTypes $ClassName
            }
        }
        "IF" {
            Register-WasmAstForwardedParamTypesFromExpr ($Node.cond) $LocalTypes $ClassName
            Register-WasmAstForwardedParamTypesFromBody ($Node.then_block) (Copy-WasmAstTypeHints $LocalTypes) $ClassName
            Register-WasmAstForwardedParamTypesFromBody ($Node.else_block) (Copy-WasmAstTypeHints $LocalTypes) $ClassName
        }
        "WHILE" {
            Register-WasmAstForwardedParamTypesFromExpr ($Node.cond) $LocalTypes $ClassName
            Register-WasmAstForwardedParamTypesFromBody ($Node.body) (Copy-WasmAstTypeHints $LocalTypes) $ClassName
        }
        "REPEAT" {
            Register-WasmAstForwardedParamTypesFromExpr ($Node.count) $LocalTypes $ClassName
            Register-WasmAstForwardedParamTypesFromBody ($Node.body) (Copy-WasmAstTypeHints $LocalTypes) $ClassName
        }
        "FOR" {
            Register-WasmAstForwardedParamTypesFromExpr ($Node.from) $LocalTypes $ClassName
            Register-WasmAstForwardedParamTypesFromExpr ($Node.to) $LocalTypes $ClassName
            Register-WasmAstForwardedParamTypesFromExpr ($Node.step) $LocalTypes $ClassName
            $bodyTypes = Copy-WasmAstTypeHints $LocalTypes
            $bodyTypes[[string]$Node.var] = "num"
            Register-WasmAstForwardedParamTypesFromBody ($Node.body) $bodyTypes $ClassName
        }
        "FOREACH" {
            Register-WasmAstForwardedParamTypesFromExpr ($Node.collection) $LocalTypes $ClassName
            Register-WasmAstForwardedParamTypesFromBody ($Node.body) (Copy-WasmAstTypeHints $LocalTypes) $ClassName
        }
        "MATCH" {
            Register-WasmAstForwardedParamTypesFromExpr ($Node.subject) $LocalTypes $ClassName
            foreach ($arm in @(As-WasmAstArray ($Node.arms))) {
                if ($arm.PSObject.Properties.Name -contains "pattern") {
                    Register-WasmAstForwardedParamTypesFromExpr ($arm.pattern) $LocalTypes $ClassName
                }
                if ($arm.PSObject.Properties.Name -contains "guard") {
                    Register-WasmAstForwardedParamTypesFromExpr ($arm.guard) $LocalTypes $ClassName
                }
                Register-WasmAstForwardedParamTypesFromBody ($arm.body) (Copy-WasmAstTypeHints $LocalTypes) $ClassName
            }
        }
        "TRY" {
            Register-WasmAstForwardedParamTypesFromBody ($Node.try_block) (Copy-WasmAstTypeHints $LocalTypes) $ClassName
            $catchTypes = Copy-WasmAstTypeHints $LocalTypes
            if (-not [string]::IsNullOrWhiteSpace([string]$Node.catch_var)) {
                $catchTypes[[string]$Node.catch_var] = "value"
            }
            Register-WasmAstForwardedParamTypesFromBody ($Node.catch_block) $catchTypes $ClassName
            Register-WasmAstForwardedParamTypesFromBody ($Node.finally_block) (Copy-WasmAstTypeHints $LocalTypes) $ClassName
        }
        # Nested definitions are represented separately in the emission list.
        "FUNC_DEF" { }
        "CLASS_DEF" { }
        default { Register-WasmAstForwardedParamTypesFromExpr $Node $LocalTypes $ClassName }
    }
}

function Register-WasmAstForwardedFunctionParamTypeHints {
    param($Functions)

    $functionList = @(As-WasmAstArray $Functions)
    if ($functionList.Count -eq 0) { return }
    $maxPasses = [Math]::Max(2, $functionList.Count + 1)
    for ($pass = 0; $pass -lt $maxPasses; $pass++) {
        $before = Get-WasmAstObservedFunctionParamTypeStateSignature
        foreach ($fn in $functionList) {
            if ($null -eq $fn -or $null -eq $fn.BodyAst) { continue }
            $name = [string]$fn.Name
            $className = ""
            if ($fn.PSObject.Properties.Name -contains "WasmClassName") {
                $className = [string]$fn.WasmClassName
            }
            $localTypes = Get-WasmAstObservedFunctionParamTypeHints $name
            Register-WasmAstForwardedParamTypesFromBody ($fn.BodyAst) $localTypes $className
        }
        $after = Get-WasmAstObservedFunctionParamTypeStateSignature
        if ($after -eq $before) { break }
    }
}

function Register-WasmAstIndirectFunctionParamTypeHints {
    param($Functions)

    $functionList = @(As-WasmAstArray $Functions)
    if ($functionList.Count -eq 0) { return }

    # Return-type inference also discovers calls through local function values.
    # Run it before WAT bodies are emitted so a candidate function does not get
    # compiled before the indirect caller has propagated its argument types.
    $maxPasses = [Math]::Max(2, $functionList.Count + 1)
    for ($pass = 0; $pass -lt $maxPasses; $pass++) {
        $before = Get-WasmAstObservedFunctionParamTypeStateSignature
        foreach ($fn in $functionList) {
            if ($null -eq $fn -or $null -eq $fn.BodyAst) { continue }
            $functionName = [string]$fn.Name
            $className = ""
            if ($fn.PSObject.Properties.Name -contains "WasmClassName") {
                $className = [string]$fn.WasmClassName
            }
            $paramTypes = Get-WasmAstObservedFunctionParamTypeHints $functionName
            $paramObjectTypes = Get-WasmAstObservedFunctionParamObjectClassHints $functionName
            Get-WasmAstReturnTypeFromBody ($fn.BodyAst) $className $paramTypes $paramObjectTypes | Out-Null
        }
        $after = Get-WasmAstObservedFunctionParamTypeStateSignature
        if ($after -eq $before) { break }
    }
}

function Add-WasmAstEscapingFunctionValueNames {
    param(
        $Node,
        [hashtable]$Names
    )

    if ($null -eq $Node -or $null -eq $Names) { return }
    if ($Node -is [string] -or $Node -is [ValueType]) { return }
    if ($Node -is [System.Collections.IEnumerable] -and
        -not ($Node -is [System.Management.Automation.PSCustomObject])) {
        foreach ($item in $Node) {
            Add-WasmAstEscapingFunctionValueNames $item $Names
        }
        return
    }
    if (-not ($Node.PSObject.Properties.Name -contains "node")) { return }

    $nodeKind = [string]$Node.node
    if ($nodeKind -eq "IDENT") {
        $name = [string]$Node.name
        if ($script:wasmAstFunctionDefs.ContainsKey($name)) {
            $Names[$name] = $true
        }
        return
    }
    if ($nodeKind -eq "FUNC_EXPR") {
        $liftName = Get-WasmAstFuncExprLiftName $Node
        if (-not [string]::IsNullOrWhiteSpace($liftName) -and
            $script:wasmAstFunctionDefs.ContainsKey($liftName)) {
            $Names[$liftName] = $true
        }
    }

    foreach ($property in $Node.PSObject.Properties) {
        if ([string]$property.Name -in @("node", "line", "name")) { continue }
        Add-WasmAstEscapingFunctionValueNames $property.Value $Names
    }
}

function Register-WasmAstEscapingFunctionValueParamTypeHints {
    param(
        $Functions,
        $MainAst
    )

    $escapingNames = @{}
    Add-WasmAstEscapingFunctionValueNames $MainAst $escapingNames
    foreach ($fn in @(As-WasmAstArray $Functions)) {
        if ($null -ne $fn -and $null -ne $fn.BodyAst) {
            Add-WasmAstEscapingFunctionValueNames ($fn.BodyAst) $escapingNames
        }
        if ($null -ne $fn -and
            $fn.PSObject.Properties.Name -contains "WasmFuncExprDisplayName" -and
            -not [string]::IsNullOrWhiteSpace([string]$fn.Name)) {
            $escapingNames[[string]$fn.Name] = $true
        }
    }

    foreach ($nameValue in @($escapingNames.Keys)) {
        $name = [string]$nameValue
        if (-not $script:wasmAstFunctionDefs.ContainsKey($name)) { continue }
        $params = @([string[]]$script:wasmAstFunctionDefs[$name].Params)
        foreach ($paramName in $params) {
            Set-WasmAstForwardedFunctionParamTypeHint $name ([string]$paramName) "value"
        }
        # Function values need one complete ABI, not only tagged parameters.
        # In particular, an array or dict result can contain tagged arguments;
        # wrapping its raw container pointer later in the dispatcher loses the
        # per-entry type information. Compile every escaping candidate's return
        # through Convert-WasmAstValueExpr so scalars and composite values both
        # arrive at the dispatcher already normalized.
        $script:wasmForcedValueReturnFunctions[$name] = $true
    }
    $script:wasmEscapingFunctionValueNames = $escapingNames
}

function Register-WasmAstFlowValueReturnHints {
    param($Functions)

    $functionList = @(As-WasmAstArray $Functions)
    $maxPasses = [Math]::Max(2, $functionList.Count + 1)
    for ($pass = 0; $pass -lt $maxPasses; $pass++) {
        $changed = $false
        $script:wasmFunctionReturnValuePreservingCache = @{}
        foreach ($fn in $functionList) {
            if ($null -eq $fn -or $null -eq $fn.BodyAst) { continue }
            $name = [string]$fn.Name
            if ([string]::IsNullOrWhiteSpace($name) -or
                $script:wasmForcedValueReturnFunctions.ContainsKey($name)) {
                continue
            }
            $className = ""
            if ($fn.PSObject.Properties.Name -contains "WasmClassName") {
                $className = [string]$fn.WasmClassName
            }
            $script:wasmFunctionReturnTypeInferenceStack[$name] = $true
            try {
                $returnType = Get-WasmAstReturnTypeFromBody ($fn.BodyAst) $className (Get-WasmAstObservedFunctionParamTypeHints $name) (Get-WasmAstObservedFunctionParamObjectClassHints $name)
            } finally {
                $script:wasmFunctionReturnTypeInferenceStack.Remove($name)
            }
            if ($returnType -eq "value") {
                $script:wasmForcedValueReturnFunctions[$name] = $true
                $changed = $true
            }
        }
        if (-not $changed) { break }
    }
    $script:wasmFunctionReturnValuePreservingCache = @{}
}

function Get-WasmAstStaticValueTypeWithObjectSelf {
    param(
        $Node,
        [string]$ObjectName,
        [string]$ClassName,
        [hashtable]$ParamTypes = @{},
        [hashtable]$ParamObjectTypes = @{}
    )

    if ($null -eq $Node) { return "nil" }
    switch ([string]$Node.node) {
        "METHOD_CALL" {
            return (Get-WasmAstMethodCallTypeHint $Node $ParamTypes $ClassName $ParamObjectTypes)
        }
        "SUPER_CALL" {
            return (Get-WasmAstSuperCallTypeHint $Node $ClassName $ParamTypes $ParamObjectTypes)
        }
        "DOT_ACCESS" {
            if ($null -ne $Node.obj -and [string]$Node.obj.node -eq "IDENT" -and [string]$Node.obj.name -eq "self") {
                $fieldName = [string]$Node.prop
                if (-not [string]::IsNullOrWhiteSpace($ObjectName)) {
                    $hintKey = "$ObjectName.$fieldName"
                    if ($script:wasmAccessTypeHints.ContainsKey($hintKey) -and -not $script:wasmConflictedAccessTypeHints.ContainsKey($hintKey)) {
                        return [string]$script:wasmAccessTypeHints[$hintKey]
                    }
                }
                $fieldType = Get-WasmAstClassFieldTypeHint $ClassName $fieldName
                if (-not [string]::IsNullOrWhiteSpace($fieldType)) { return $fieldType }
                return (Get-WasmAstObservedClassFieldTypeHint $ClassName $fieldName)
            }
            if ($null -ne $Node.obj) {
                $receiverClass = Get-WasmAstObjectClassTypeWithLocals ($Node.obj) $ParamObjectTypes $ClassName @{}
                if (-not [string]::IsNullOrWhiteSpace($receiverClass)) {
                    $fieldType = Get-WasmAstClassFieldTypeHint $receiverClass ([string]$Node.prop)
                    if (-not [string]::IsNullOrWhiteSpace($fieldType)) { return $fieldType }
                    $observedType = Get-WasmAstObservedClassFieldTypeHint $receiverClass ([string]$Node.prop)
                    if (-not [string]::IsNullOrWhiteSpace($observedType)) { return $observedType }
                }
            }
        }
        "INDEX" {
            if ($null -ne $Node.obj -and [string]$Node.obj.node -eq "IDENT" -and [string]$Node.obj.name -eq "self" -and
                -not [string]::IsNullOrWhiteSpace($ObjectName)) {
                $hintKey = ""
                if ($null -ne $Node.key -and [string]$Node.key.node -eq "STR_LIT") {
                    $hintKey = "$ObjectName.$([string]$Node.key.value)"
                } elseif ($null -ne $Node.key -and [string]$Node.key.node -eq "NUM_LIT") {
                    $indexValue = [int][Math]::Truncate([double]$Node.key.value)
                    $hintKey = ("{0}[{1}]" -f $ObjectName, $indexValue)
                }
                if (-not [string]::IsNullOrWhiteSpace($hintKey) -and $script:wasmAccessTypeHints.ContainsKey($hintKey) -and
                    -not $script:wasmConflictedAccessTypeHints.ContainsKey($hintKey)) {
                    return [string]$script:wasmAccessTypeHints[$hintKey]
                }
            }
            if ($null -ne $Node.obj -and $null -ne $Node.key -and [string]$Node.key.node -eq "STR_LIT") {
                $receiverClass = Get-WasmAstObjectClassTypeWithLocals ($Node.obj) $ParamObjectTypes $ClassName @{}
                if (-not [string]::IsNullOrWhiteSpace($receiverClass)) {
                    $fieldName = [string]$Node.key.value
                    $fieldType = Get-WasmAstClassFieldTypeHint $receiverClass $fieldName
                    if (-not [string]::IsNullOrWhiteSpace($fieldType)) { return $fieldType }
                    $observedType = Get-WasmAstObservedClassFieldTypeHint $receiverClass $fieldName
                    if (-not [string]::IsNullOrWhiteSpace($observedType)) { return $observedType }
                }
            }
        }
        "IDENT" {
            $name = [string]$Node.name
            if ($ParamTypes.ContainsKey($name)) { return [string]$ParamTypes[$name] }
        }
        "STR_LIT" { return "string" }
        "STR_INTERP" { return "string" }
        "BOOL_LIT" { return "bool" }
        "NIL_LIT" { return "nil" }
        "NUM_LIT" { return "num" }
        "ARRAY_LIT" { return "array" }
        "DICT_LIT" { return "dict" }
        "BIN_OP" {
            $op = [string]$Node.op
            $leftType = Get-WasmAstStaticValueTypeWithObjectSelf ($Node.left) $ObjectName $ClassName $ParamTypes $ParamObjectTypes
            $rightType = Get-WasmAstStaticValueTypeWithObjectSelf ($Node.right) $ObjectName $ClassName $ParamTypes $ParamObjectTypes
            if ($op -eq "+" -and ($leftType -eq "string" -or $rightType -eq "string")) { return "string" }
            if ($op -eq "+" -and $leftType -eq "array" -and $rightType -eq "array") { return "array" }
            if ($op -in @("and", "or")) { return "bool" }
            if ($op -in @("+", "-", "*", "/", "%", "&", "|", "^", "<<", ">>") -and $leftType -eq "num" -and $rightType -eq "num") { return "num" }
            if ($op -in @("==", "!=", "<", "<=", ">", ">=") -and -not [string]::IsNullOrWhiteSpace($leftType) -and -not [string]::IsNullOrWhiteSpace($rightType)) { return "bool" }
        }
        "UNARY_OP" {
            if ([string]$Node.op -eq "not") { return "bool" }
        }
        "TERNARY" {
            $thenType = Get-WasmAstStaticValueTypeWithObjectSelf ($Node.then) $ObjectName $ClassName $ParamTypes $ParamObjectTypes
            $elseType = Get-WasmAstStaticValueTypeWithObjectSelf ($Node.else) $ObjectName $ClassName $ParamTypes $ParamObjectTypes
            if (-not [string]::IsNullOrWhiteSpace($thenType) -and $thenType -eq $elseType) { return $thenType }
        }
        default { }
    }
    return (Get-WasmAstStaticValueTypeWithParams $Node $ParamTypes)
}

function Get-WasmAstReturnTypeFromBodyForObject {
    param(
        $Body,
        [string]$ObjectName,
        [string]$ClassName,
        [hashtable]$ParamTypes = @{},
        [hashtable]$ParamObjectTypes = @{},
        [hashtable]$LocalIndexedAccessHints = @{}
    )

    if ($null -eq $Body) { return "" }
    $localTypes = @{}
    foreach ($entry in $ParamTypes.GetEnumerator()) {
        $localTypes[[string]$entry.Key] = [string]$entry.Value
    }
    $localObjects = Copy-WasmAstTypeHints $ParamObjectTypes
    $localIndexedHints = Copy-WasmAstLocalIndexedAccessHints $LocalIndexedAccessHints
    $localFunctionLiftCandidates = @{}
    $localDictFunctionLiftCandidates = @{}
    $localArrayFunctionLiftCandidates = @{}
    foreach ($stmt in @(As-WasmAstArray ($Body.body))) {
        if ($null -eq $stmt) { continue }
        switch ([string]$stmt.node) {
            "ASSIGN" {
                $objectClass = Get-WasmAstObjectClassTypeWithLocals ($stmt.value) $localObjects $ClassName @{}
                if (-not [string]::IsNullOrWhiteSpace($objectClass)) {
                    $localObjects[[string]$stmt.name] = $objectClass
                } elseif ($localObjects.ContainsKey([string]$stmt.name)) {
                    $localObjects.Remove([string]$stmt.name)
                }
                $typeName = Get-WasmAstStaticValueTypeWithObjectSelf ($stmt.value) $ObjectName $ClassName $localTypes $localObjects
                if ([string]::IsNullOrWhiteSpace($typeName) -and
                    $null -ne $stmt.value -and [string]$stmt.value.node -eq "INDEX" -and
                    $null -ne $stmt.value.obj -and [string]$stmt.value.obj.node -eq "IDENT" -and
                    $localDictFunctionLiftCandidates.ContainsKey([string]$stmt.value.obj.name)) {
                    $dictKeyType = Get-WasmAstStaticValueTypeWithObjectSelf ($stmt.value.key) $ObjectName $ClassName $localTypes $localObjects
                    if ([string]::IsNullOrWhiteSpace($dictKeyType)) { $dictKeyType = Get-WasmAstStaticValueType ($stmt.value.key) }
                    if ($dictKeyType -eq "string") { $typeName = "function" }
                }
                if ([string]::IsNullOrWhiteSpace($typeName) -and
                    $null -ne $stmt.value -and [string]$stmt.value.node -eq "INDEX" -and
                    $null -ne $stmt.value.obj -and [string]$stmt.value.obj.node -eq "IDENT" -and
                    $localArrayFunctionLiftCandidates.ContainsKey([string]$stmt.value.obj.name)) {
                    $arrayKeyType = Get-WasmAstStaticValueTypeWithObjectSelf ($stmt.value.key) $ObjectName $ClassName $localTypes $localObjects
                    if ([string]::IsNullOrWhiteSpace($arrayKeyType)) { $arrayKeyType = Get-WasmAstStaticValueType ($stmt.value.key) }
                    if ($arrayKeyType -ne "string") { $typeName = "function" }
                }
                if ($typeName -in @("string", "bool", "nil", "num", "array", "dict", "function")) {
                    $localTypes[[string]$stmt.name] = $typeName
                }
                $assignedIndexedHints = Get-WasmAstFixedIndexedAccessHintsForExpr ($stmt.value) $localIndexedHints
                if ($typeName -eq "array" -and (Test-WasmAstFixedIndexedHintMapHasItems $assignedIndexedHints)) {
                    $localIndexedHints[[string]$stmt.name] = Copy-WasmAstFixedIndexedHintMap $assignedIndexedHints
                } elseif ($localIndexedHints.ContainsKey([string]$stmt.name)) {
                    $localIndexedHints.Remove([string]$stmt.name)
                }
                if ($typeName -eq "function") {
                    $candidates = @(Get-WasmAstFunctionValueLiftCandidatesFromExpr ($stmt.value) $ClassName $localTypes $localObjects $localFunctionLiftCandidates $localDictFunctionLiftCandidates $localArrayFunctionLiftCandidates)
                    if ($candidates.Count -gt 0) {
                        $localFunctionLiftCandidates[[string]$stmt.name] = [string[]]$candidates
                    } elseif ($localFunctionLiftCandidates.ContainsKey([string]$stmt.name)) {
                        $localFunctionLiftCandidates.Remove([string]$stmt.name)
                    }
                } elseif ($localFunctionLiftCandidates.ContainsKey([string]$stmt.name)) {
                    $localFunctionLiftCandidates.Remove([string]$stmt.name)
                }
                if ($typeName -eq "dict") {
                    $dictFunctionCandidates = @(Get-WasmAstDictLiteralFunctionLiftCandidates ($stmt.value) $ClassName $localTypes $localObjects $localFunctionLiftCandidates $localDictFunctionLiftCandidates $localArrayFunctionLiftCandidates)
                    if ($dictFunctionCandidates.Count -gt 0) {
                        $localDictFunctionLiftCandidates[[string]$stmt.name] = [string[]]$dictFunctionCandidates
                    } elseif ($localDictFunctionLiftCandidates.ContainsKey([string]$stmt.name)) {
                        $localDictFunctionLiftCandidates.Remove([string]$stmt.name)
                    }
                } elseif ($localDictFunctionLiftCandidates.ContainsKey([string]$stmt.name)) {
                    $localDictFunctionLiftCandidates.Remove([string]$stmt.name)
                }
                if ($typeName -eq "array") {
                    $arrayFunctionCandidates = @(Get-WasmAstArrayLiteralFunctionLiftCandidates ($stmt.value) $ClassName $localTypes $localObjects $localFunctionLiftCandidates $localDictFunctionLiftCandidates $localArrayFunctionLiftCandidates)
                    if ($arrayFunctionCandidates.Count -gt 0) {
                        $localArrayFunctionLiftCandidates[[string]$stmt.name] = [string[]]$arrayFunctionCandidates
                    } elseif ($localArrayFunctionLiftCandidates.ContainsKey([string]$stmt.name)) {
                        $localArrayFunctionLiftCandidates.Remove([string]$stmt.name)
                    }
                } elseif ($localArrayFunctionLiftCandidates.ContainsKey([string]$stmt.name)) {
                    $localArrayFunctionLiftCandidates.Remove([string]$stmt.name)
                }
            }
            "RETURN" {
                $functionValueReturnType = Get-WasmAstFunctionValueCallReturnTypeHint ($stmt.value) $localTypes $localFunctionLiftCandidates
                if ($functionValueReturnType -in @("string", "bool", "nil", "num", "array", "dict", "function", "value")) {
                    return $functionValueReturnType
                }
                return (Get-WasmAstStaticValueTypeWithObjectSelf ($stmt.value) $ObjectName $ClassName $localTypes $localObjects)
            }
            "SuraBlock" {
                $typeName = Get-WasmAstReturnTypeFromBodyForObject $stmt $ObjectName $ClassName $localTypes $localObjects $localIndexedHints
                if (-not [string]::IsNullOrWhiteSpace($typeName)) { return $typeName }
            }
            "IF" {
                $thenType = Get-WasmAstReturnTypeFromBodyForObject ($stmt.then_block) $ObjectName $ClassName $localTypes $localObjects $localIndexedHints
                $elseType = Get-WasmAstReturnTypeFromBodyForObject ($stmt.else_block) $ObjectName $ClassName $localTypes $localObjects $localIndexedHints
                if (-not [string]::IsNullOrWhiteSpace($thenType) -and $thenType -eq $elseType) { return $thenType }
            }
            "WHILE" {
                $typeName = Get-WasmAstReturnTypeFromBodyForObject ($stmt.body) $ObjectName $ClassName $localTypes $localObjects $localIndexedHints
                if (-not [string]::IsNullOrWhiteSpace($typeName)) { return $typeName }
            }
            "REPEAT" {
                $typeName = Get-WasmAstReturnTypeFromBodyForObject ($stmt.body) $ObjectName $ClassName $localTypes $localObjects $localIndexedHints
                if (-not [string]::IsNullOrWhiteSpace($typeName)) { return $typeName }
            }
            "FOR" {
                $typeName = Get-WasmAstReturnTypeFromBodyForObject ($stmt.body) $ObjectName $ClassName $localTypes $localObjects $localIndexedHints
                if (-not [string]::IsNullOrWhiteSpace($typeName)) { return $typeName }
            }
            "FOREACH" {
                $loopTypes = Copy-WasmAstTypeHints $localTypes
                $loopObjects = Copy-WasmAstTypeHints $localObjects
                $loopVar = [string]$stmt.var
                $loopVar2 = [string]$stmt.var2
                $collectionType = Get-WasmAstStaticValueTypeWithObjectSelf ($stmt.collection) $ObjectName $ClassName $localTypes $localObjects
                if ($collectionType -eq "dict") {
                    if (-not [string]::IsNullOrWhiteSpace($loopVar2)) {
                        $loopTypes[$loopVar] = "string"
                        $valueType = Get-WasmAstDictValueTypeHint ($stmt.collection)
                        if ($valueType -in @("string", "bool", "nil", "num", "array", "dict", "function")) {
                            $loopTypes[$loopVar2] = $valueType
                        }
                        $valueClass = Get-WasmAstDictValueObjectClassHint ($stmt.collection)
                        if (-not [string]::IsNullOrWhiteSpace($valueClass)) {
                            $loopObjects[$loopVar2] = $valueClass
                        }
                    }
                } else {
                    $elementType = Get-WasmAstArrayElementTypeHint ($stmt.collection) $localIndexedHints
                    $elementClass = Get-WasmAstArrayElementObjectClassHint ($stmt.collection)
                    if (-not [string]::IsNullOrWhiteSpace($loopVar2)) {
                        $loopTypes[$loopVar] = "num"
                        if ($elementType -in @("string", "bool", "nil", "num", "array", "dict", "function")) {
                            $loopTypes[$loopVar2] = $elementType
                        }
                        if (-not [string]::IsNullOrWhiteSpace($elementClass)) {
                            $loopObjects[$loopVar2] = $elementClass
                        }
                    } elseif ($elementType -in @("string", "bool", "nil", "num", "array", "dict", "function")) {
                        $loopTypes[$loopVar] = $elementType
                    } elseif (-not [string]::IsNullOrWhiteSpace($elementClass)) {
                        $loopObjects[$loopVar] = $elementClass
                    }
                }
                $typeName = Get-WasmAstReturnTypeFromBodyForObject ($stmt.body) $ObjectName $ClassName $loopTypes $loopObjects $localIndexedHints
                if (-not [string]::IsNullOrWhiteSpace($typeName)) { return $typeName }
            }
            "MATCH" {
                $armTypes = New-Object System.Collections.Generic.List[string]
                foreach ($arm in @(As-WasmAstArray ($stmt.arms))) {
                    $typeName = Get-WasmAstReturnTypeFromBodyForObject ($arm.body) $ObjectName $ClassName $localTypes $localObjects $localIndexedHints
                    if ($typeName -in @("string", "bool", "nil", "num", "array", "dict", "function")) {
                        $armTypes.Add($typeName) | Out-Null
                    }
                }
                if ($armTypes.Count -gt 0) {
                    $commonType = Get-WasmAstCommonTypeName ([string[]]$armTypes.ToArray())
                    if (-not [string]::IsNullOrWhiteSpace($commonType)) { return $commonType }
                }
            }
            "TRY" {
                $typeName = Get-WasmAstReturnTypeFromBodyForObject ($stmt.try_block) $ObjectName $ClassName $localTypes $localObjects $localIndexedHints
                if (-not [string]::IsNullOrWhiteSpace($typeName)) { return $typeName }
            }
            default { }
        }
    }
    return ""
}

function Register-WasmAstClassMethodReturnTypeHints {
    param($ClassNode)

    if ($null -eq $ClassNode -or [string]$ClassNode.node -ne "CLASS_DEF") { return }
    $className = [string]$ClassNode.name
    if ([string]::IsNullOrWhiteSpace($className)) { return }
    foreach ($method in @(As-WasmAstArray ($ClassNode.methods))) {
        $methodName = [string]$method.name
        if ([string]::IsNullOrWhiteSpace($methodName) -or $methodName -eq "init") { continue }
        $key = "$className.$methodName"
        if ($script:wasmMethodReturnTypeInferenceStack.ContainsKey($key)) { continue }
        $script:wasmMethodReturnTypeInferenceStack[$key] = $true
        try {
            $typeName = Get-WasmAstReturnTypeFromBody ($method.body) $className @{}
        } finally {
            $script:wasmMethodReturnTypeInferenceStack.Remove($key)
        }
        if ($typeName -in @("string", "bool", "nil", "num", "array", "dict", "function")) {
            $script:wasmClassMethodReturnTypeHints[$key] = $typeName
        }
    }
}

function Get-WasmAstMethodCallTypeHint {
    param($Node, [hashtable]$ContextTypes = @{}, [string]$SelfClassName = "", [hashtable]$LocalObjectTypes = @{})

    if ($null -eq $Node -or [string]$Node.node -ne "METHOD_CALL") { return "" }
    if ($null -eq $Node.obj) { return "" }
    $objName = if ([string]$Node.obj.node -eq "IDENT") { [string]$Node.obj.name } else { "" }
    if ($objName -eq "array") {
        if ([string]$Node.method -eq "remove") {
            return "value"
        }
        if ([string]$Node.method -eq "pop") {
            $moduleArgs = @(As-WasmAstArray ($Node.args))
            if ($moduleArgs.Count -eq 1) {
                $elementType = Get-WasmAstArrayElementTypeHint ($moduleArgs[0])
                if ($elementType -in @("string", "bool", "nil", "num", "array", "dict", "function")) { return $elementType }
            }
        }
        $arrayModuleType = Get-WasmArrayCallReturnTypeName "array.$([string]$Node.method)"
        if (-not [string]::IsNullOrWhiteSpace($arrayModuleType)) { return $arrayModuleType }
    }
    if ($objName -eq "dict") {
        $dictModuleType = Get-WasmDictCallReturnTypeName "dict.$([string]$Node.method)"
        if (-not [string]::IsNullOrWhiteSpace($dictModuleType)) { return $dictModuleType }
    }
    if ($objName -eq "set") {
        $setModuleType = Get-WasmArrayCallReturnTypeName "set.$([string]$Node.method)"
        if (-not [string]::IsNullOrWhiteSpace($setModuleType)) { return $setModuleType }
    }
    $stringMethodType = Get-WasmStringMethodReturnTypeName ([string]$Node.method)
    if ($objName -eq "string") {
        if (-not [string]::IsNullOrWhiteSpace($stringMethodType)) { return $stringMethodType }
        if ([string]$Node.method -in @("len", "length", "size")) { return "num" }
    }
    if ((Test-WasmAstRuntimeValueIndexCandidate ($Node.obj)) -or (Test-WasmAstRuntimeValueDotCandidate ($Node.obj))) {
        if (-not [string]::IsNullOrWhiteSpace($stringMethodType)) { return $stringMethodType }
        $arrayMethodType = Get-WasmArrayMethodReturnTypeName ([string]$Node.method)
        if (-not [string]::IsNullOrWhiteSpace($arrayMethodType)) { return $arrayMethodType }
        if ([string]$Node.method -in @("len", "length", "size")) { return "num" }
    }
    $receiverType = Get-WasmAstKnownValueType ($Node.obj)
    if ([string]::IsNullOrWhiteSpace($receiverType)) { $receiverType = Get-WasmAstStaticValueType ($Node.obj) }
    if ($receiverType -eq "value") {
        if (-not [string]::IsNullOrWhiteSpace($stringMethodType)) { return $stringMethodType }
        $arrayMethodType = Get-WasmArrayMethodReturnTypeName ([string]$Node.method)
        if (-not [string]::IsNullOrWhiteSpace($arrayMethodType)) { return $arrayMethodType }
        $dictMethodType = Get-WasmDictMethodReturnTypeName ([string]$Node.method)
        if (-not [string]::IsNullOrWhiteSpace($dictMethodType)) { return $dictMethodType }
        if ([string]$Node.method -in @("len", "length", "size")) { return "num" }
    }
    if ($receiverType -eq "string") {
        if (-not [string]::IsNullOrWhiteSpace($stringMethodType)) { return $stringMethodType }
        if ([string]$Node.method -in @("len", "length", "size")) { return "num" }
    }
    if ($receiverType -eq "array") {
        if ([string]$Node.method -eq "remove") {
            return "value"
        }
        if ([string]$Node.method -eq "pop") {
            $elementType = Get-WasmAstArrayElementTypeHint ($Node.obj)
            if ($elementType -in @("string", "bool", "nil", "num", "array", "dict", "function")) { return $elementType }
        }
        $arrayMethodType = Get-WasmArrayMethodReturnTypeName ([string]$Node.method)
        if (-not [string]::IsNullOrWhiteSpace($arrayMethodType)) { return $arrayMethodType }
    }
    if ($receiverType -eq "dict") {
        $dictMethodType = Get-WasmDictMethodReturnTypeName ([string]$Node.method)
        if (-not [string]::IsNullOrWhiteSpace($dictMethodType)) { return $dictMethodType }
    }
    $className = Get-WasmAstObjectClassTypeWithLocals ($Node.obj) $LocalObjectTypes $SelfClassName @{}
    if ([string]::IsNullOrWhiteSpace($className)) {
        $className = Get-WasmAstObjectClassSetHintWithLocals ($Node.obj) $LocalObjectTypes $SelfClassName
    }
    if ([string]::IsNullOrWhiteSpace($className)) { return "" }
    $classNames = @(Get-WasmAstObjectClassNamesFromHint $className)
    if ($classNames.Count -gt 1) {
        $candidateTypes = New-Object System.Collections.Generic.List[string]
        foreach ($candidateClass in $classNames) {
            $candidateMethod = Get-WasmAstClassMethod -ClassName ([string]$candidateClass) -MethodName ([string]$Node.method)
            if ($null -eq $candidateMethod) { return "" }
            $candidateKey = "$([string]$candidateMethod.ClassName).$([string]$Node.method)"
            $candidateType = ""
            if ($script:wasmClassMethodReturnTypeHints.ContainsKey($candidateKey)) {
                $candidateType = [string]$script:wasmClassMethodReturnTypeHints[$candidateKey]
            } elseif (-not $script:wasmMethodReturnTypeInferenceStack.ContainsKey($candidateKey)) {
                $candidateParamTypes = Get-WasmAstObservedFunctionParamTypeHints ([string]$candidateMethod.FunctionName)
                $candidateParamObjects = Get-WasmAstObservedFunctionParamObjectClassHints ([string]$candidateMethod.FunctionName)
                $script:wasmMethodReturnTypeInferenceStack[$candidateKey] = $true
                try {
                    $candidateType = Get-WasmAstReturnTypeFromBody ($candidateMethod.Method.body) ([string]$candidateMethod.ClassName) $candidateParamTypes $candidateParamObjects
                } finally {
                    [void]$script:wasmMethodReturnTypeInferenceStack.Remove($candidateKey)
                }
            }
            if ($candidateType -notin @("string", "bool", "nil", "num", "array", "dict", "function", "value")) {
                return ""
            }
            $candidateTypes.Add($candidateType) | Out-Null
        }
        $distinctTypes = @($candidateTypes.ToArray() | Sort-Object -Unique)
        if ($distinctTypes.Count -eq 1) { return [string]$distinctTypes[0] }
        return ""
    }
    $methodInfo = Get-WasmAstClassMethod -ClassName $className -MethodName ([string]$Node.method)
    if ($null -eq $methodInfo) { return "" }
    $key = "$([string]$methodInfo.ClassName).$([string]$Node.method)"
    if ($script:wasmMethodReturnTypeInferenceStack.ContainsKey($key)) {
        if ($script:wasmClassMethodReturnTypeHints.ContainsKey($key)) {
            return [string]$script:wasmClassMethodReturnTypeHints[$key]
        }
        return ""
    }
    if (Test-WasmAstReturnValuePreservingFromBody ($methodInfo.Method.body)) { return "value" }
    $abiParamTypes = Get-WasmAstObservedFunctionParamTypeHints ([string]$methodInfo.FunctionName)
    $abiParamObjectTypes = Get-WasmAstObservedFunctionParamObjectClassHints ([string]$methodInfo.FunctionName)
    $script:wasmMethodReturnTypeInferenceStack[$key] = $true
    try {
        $abiReturnType = Get-WasmAstReturnTypeFromBody ($methodInfo.Method.body) ([string]$methodInfo.ClassName) $abiParamTypes $abiParamObjectTypes
    } finally {
        $script:wasmMethodReturnTypeInferenceStack.Remove($key)
    }
    if ($abiReturnType -eq "value") { return "value" }
    $paramTypes = @{}
    $paramObjectTypes = Get-WasmAstObservedFunctionParamObjectClassHints ([string]$methodInfo.FunctionName)
    $params = @(Get-WasmAstParamNames ($methodInfo.Method.params))
    $args = @(As-WasmAstArray ($Node.args))
    for ($i = 0; $i -lt $params.Count -and $i -lt $args.Count; $i++) {
        $argType = Get-WasmAstStaticValueTypeWithClassSelf ($args[$i]) $SelfClassName $ContextTypes $LocalObjectTypes
        if ($argType -in @("string", "bool", "nil", "num", "array", "dict", "function")) {
            $paramTypes[[string]$params[$i]] = $argType
        }
        $argClass = Get-WasmAstObjectClassTypeWithLocals ($args[$i]) $LocalObjectTypes $SelfClassName @{}
        if (-not [string]::IsNullOrWhiteSpace($argClass)) {
            $paramObjectTypes[[string]$params[$i]] = $argClass
        }
    }
    $script:wasmMethodReturnTypeInferenceStack[$key] = $true
    try {
        $objectType = Get-WasmAstReturnTypeFromBodyForObject ($methodInfo.Method.body) $objName ([string]$methodInfo.ClassName) $paramTypes $paramObjectTypes
    } finally {
        $script:wasmMethodReturnTypeInferenceStack.Remove($key)
    }
    if ($objectType -in @("string", "bool", "nil", "num", "array", "dict", "function", "value")) {
        return $objectType
    }
    if ($script:wasmClassMethodReturnTypeHints.ContainsKey($key)) {
        return [string]$script:wasmClassMethodReturnTypeHints[$key]
    }
    return ""
}

function Get-WasmAstSuperCallTypeHint {
    param(
        $Node,
        [string]$ClassName,
        [hashtable]$ParamTypes = @{},
        [hashtable]$ContextObjectTypes = @{}
    )

    if ($null -eq $Node -or [string]$Node.node -ne "SUPER_CALL" -or [string]::IsNullOrWhiteSpace($ClassName)) {
        return ""
    }
    $methodName = [string]$Node.method
    if ([string]::IsNullOrWhiteSpace($methodName) -or $methodName -eq "init") { return "" }
    $methodInfo = Get-WasmAstSuperClassMethod -ClassName $ClassName -MethodName $methodName
    if ($null -eq $methodInfo) { return "" }
    $key = "$([string]$methodInfo.ClassName).$methodName"
    if ($script:wasmMethodReturnTypeInferenceStack.ContainsKey($key)) {
        if ($script:wasmClassMethodReturnTypeHints.ContainsKey($key)) {
            return [string]$script:wasmClassMethodReturnTypeHints[$key]
        }
        return ""
    }
    if (Test-WasmAstReturnValuePreservingFromBody ($methodInfo.Method.body)) { return "value" }
    $abiParamTypes = Get-WasmAstObservedFunctionParamTypeHints ([string]$methodInfo.FunctionName)
    $abiParamObjectTypes = Get-WasmAstObservedFunctionParamObjectClassHints ([string]$methodInfo.FunctionName)
    $script:wasmMethodReturnTypeInferenceStack[$key] = $true
    try {
        $abiReturnType = Get-WasmAstReturnTypeFromBody ($methodInfo.Method.body) ([string]$methodInfo.ClassName) $abiParamTypes $abiParamObjectTypes
    } finally {
        $script:wasmMethodReturnTypeInferenceStack.Remove($key)
    }
    if ($abiReturnType -eq "value") { return "value" }
    $callParamTypes = @{}
    $callParamObjectTypes = Get-WasmAstObservedFunctionParamObjectClassHints ([string]$methodInfo.FunctionName)
    $params = @(Get-WasmAstParamNames ($methodInfo.Method.params))
    $args = @(As-WasmAstArray ($Node.args))
    for ($i = 0; $i -lt $params.Count -and $i -lt $args.Count; $i++) {
        $argType = Get-WasmAstStaticValueTypeWithClassSelf ($args[$i]) $ClassName $ParamTypes $ContextObjectTypes
        if ($argType -in @("string", "bool", "nil", "num", "array", "dict", "function")) {
            $callParamTypes[[string]$params[$i]] = $argType
        }
        $argClass = Get-WasmAstObjectClassTypeWithLocals ($args[$i]) $ContextObjectTypes $ClassName @{}
        if (-not [string]::IsNullOrWhiteSpace($argClass)) {
            $callParamObjectTypes[[string]$params[$i]] = $argClass
        }
    }
    $script:wasmMethodReturnTypeInferenceStack[$key] = $true
    try {
        $typeName = Get-WasmAstReturnTypeFromBodyForObject ($methodInfo.Method.body) "self" ([string]$methodInfo.ClassName) $callParamTypes $callParamObjectTypes
    } finally {
        $script:wasmMethodReturnTypeInferenceStack.Remove($key)
    }
    if ($typeName -in @("string", "bool", "nil", "num", "array", "dict", "function", "value")) { return $typeName }
    if ($script:wasmClassMethodReturnTypeHints.ContainsKey($key)) {
        return [string]$script:wasmClassMethodReturnTypeHints[$key]
    }
    return ""
}

function Get-WasmAstFunctionCallTypeHint {
    param($Node, [hashtable]$ContextTypes = @{})

    if ($null -eq $Node -or [string]$Node.node -ne "CALL") { return "" }
    $name = [string]$Node.name
    if (-not $script:wasmAstFunctionDefs.ContainsKey($name)) { return "" }
    if (Test-WasmAstFunctionReturnValuePreserving $name) { return "value" }
    if ($script:wasmFunctionReturnTypeInferenceStack.ContainsKey($name)) { return "" }
    $fn = $script:wasmAstFunctionDefs[$name]
    if ($null -eq $fn.Node -or $null -eq $fn.Node.body) { return "" }
    $paramTypes = @{}
    $paramObjectTypes = Get-WasmAstObservedFunctionParamObjectClassHints ([string]$name)
    $params = @($fn.Params)
    $args = @(As-WasmAstArray ($Node.args))
    for ($i = 0; $i -lt $params.Count -and $i -lt $args.Count; $i++) {
        $argType = Get-WasmAstStaticValueTypeWithParams ($args[$i]) $ContextTypes
        if ($argType -in @("string", "bool", "nil", "num", "array", "dict", "function", "value")) {
            $paramTypes[[string]$params[$i]] = $argType
        }
        $argClass = Get-WasmAstObjectClassTypeHint ($args[$i])
        if (-not [string]::IsNullOrWhiteSpace($argClass)) {
            $paramObjectTypes[[string]$params[$i]] = $argClass
        }
    }
    $script:wasmFunctionReturnTypeInferenceStack[$name] = $true
    try {
        $typeName = Get-WasmAstReturnTypeFromBody ($fn.Node.body) "" $paramTypes $paramObjectTypes
    } finally {
        $script:wasmFunctionReturnTypeInferenceStack.Remove($name)
    }
    if ($typeName -in @("string", "bool", "nil", "num", "array", "dict", "function", "value")) { return $typeName }
    return ""
}

function Add-WasmAstConstructorParamFieldHintsFromBody {
    param(
        [string]$ClassName,
        $Body,
        [hashtable]$ParamTypes,
        [hashtable]$Out
    )

    if ([string]::IsNullOrWhiteSpace($ClassName) -or $null -eq $Body) { return }
    foreach ($stmt in @(As-WasmAstArray ($Body.body))) {
        if ($null -eq $stmt) { continue }
        switch ([string]$stmt.node) {
            "DOT_ASSIGN" {
                if ([string]$stmt.obj_name -eq "self") {
                    $fieldType = Get-WasmAstStaticValueTypeWithParams ($stmt.value) $ParamTypes
                    if ($fieldType -in @("string", "bool", "nil", "num", "array", "dict", "function")) {
                        $Out[[string]$stmt.prop] = $fieldType
                    }
                }
            }
            "EXPR_STMT" {
                if (Test-WasmAstSuperInitStmt $stmt) {
                    $parent = [string]$script:wasmClassDefs[$ClassName].Parent
                    if (-not [string]::IsNullOrWhiteSpace($parent)) {
                        $parentArgTypes = New-Object System.Collections.Generic.List[string]
                        foreach ($arg in @(As-WasmAstArray ($stmt.expr.args))) {
                            $parentArgTypes.Add((Get-WasmAstStaticValueTypeWithParams $arg $ParamTypes)) | Out-Null
                        }
                        foreach ($entry in (Get-WasmAstConstructorParamFieldHints $parent @($parentArgTypes.ToArray())).GetEnumerator()) {
                            $Out[[string]$entry.Key] = [string]$entry.Value
                        }
                    }
                }
            }
            "SuraBlock" { Add-WasmAstConstructorParamFieldHintsFromBody $ClassName $stmt $ParamTypes $Out }
            "IF" {
                Add-WasmAstConstructorParamFieldHintsFromBody $ClassName ($stmt.then_block) $ParamTypes $Out
                Add-WasmAstConstructorParamFieldHintsFromBody $ClassName ($stmt.else_block) $ParamTypes $Out
            }
            "WHILE" { Add-WasmAstConstructorParamFieldHintsFromBody $ClassName ($stmt.body) $ParamTypes $Out }
            "REPEAT" { Add-WasmAstConstructorParamFieldHintsFromBody $ClassName ($stmt.body) $ParamTypes $Out }
            "FOR" { Add-WasmAstConstructorParamFieldHintsFromBody $ClassName ($stmt.body) $ParamTypes $Out }
            "FOREACH" { Add-WasmAstConstructorParamFieldHintsFromBody $ClassName ($stmt.body) $ParamTypes $Out }
            "TRY" {
                Add-WasmAstConstructorParamFieldHintsFromBody $ClassName ($stmt.try_block) $ParamTypes $Out
                Add-WasmAstConstructorParamFieldHintsFromBody $ClassName ($stmt.finally_block) $ParamTypes $Out
            }
            default { }
        }
    }
}

function Get-WasmAstConstructorParamFieldHints {
    param([string]$ClassName, [string[]]$ArgTypes, [hashtable]$Seen = @{})

    $types = @{}
    if ([string]::IsNullOrWhiteSpace($ClassName) -or -not $script:wasmClassDefs.ContainsKey($ClassName) -or $Seen.ContainsKey($ClassName)) {
        return $types
    }
    $Seen[$ClassName] = $true
    foreach ($entry in (Get-WasmAstClassFieldTypeHints $ClassName).GetEnumerator()) {
        $types[[string]$entry.Key] = [string]$entry.Value
    }
    $classNode = $script:wasmClassDefs[$ClassName].Node
    $init = Get-WasmAstClassInitMethod $classNode
    if ($null -eq $init) { return $types }

    $paramTypes = @{}
    $params = @(Get-WasmAstParamNames ($init.params))
    for ($i = 0; $i -lt $params.Count -and $i -lt $ArgTypes.Count; $i++) {
        if ($ArgTypes[$i] -in @("string", "bool", "nil", "num", "array", "dict", "function")) {
            $paramTypes[$params[$i]] = $ArgTypes[$i]
        }
    }
    Add-WasmAstConstructorParamFieldHintsFromBody $ClassName ($init.body) $paramTypes $types
    return $types
}

function Add-WasmAstConstructorParamFieldObjectHintsFromBody {
    param(
        [string]$ClassName,
        $Body,
        [hashtable]$ParamObjectTypes,
        [hashtable]$Out
    )

    if ([string]::IsNullOrWhiteSpace($ClassName) -or $null -eq $Body) { return }
    foreach ($stmt in @(As-WasmAstArray ($Body.body))) {
        if ($null -eq $stmt) { continue }
        switch ([string]$stmt.node) {
            "DOT_ASSIGN" {
                if ([string]$stmt.obj_name -eq "self") {
                    $fieldClass = Get-WasmAstObjectClassTypeWithLocals ($stmt.value) $ParamObjectTypes $ClassName @{}
                    if (-not [string]::IsNullOrWhiteSpace($fieldClass)) {
                        $Out[[string]$stmt.prop] = $fieldClass
                    }
                }
            }
            "EXPR_STMT" {
                if (Test-WasmAstSuperInitStmt $stmt) {
                    $parent = [string]$script:wasmClassDefs[$ClassName].Parent
                    if (-not [string]::IsNullOrWhiteSpace($parent)) {
                        $parentArgClasses = New-Object System.Collections.Generic.List[string]
                        foreach ($arg in @(As-WasmAstArray ($stmt.expr.args))) {
                            $parentArgClasses.Add((Get-WasmAstObjectClassTypeWithLocals $arg $ParamObjectTypes $ClassName @{})) | Out-Null
                        }
                        foreach ($entry in (Get-WasmAstConstructorParamFieldObjectHints $parent @($parentArgClasses.ToArray())).GetEnumerator()) {
                            $Out[[string]$entry.Key] = [string]$entry.Value
                        }
                    }
                }
            }
            "SuraBlock" { Add-WasmAstConstructorParamFieldObjectHintsFromBody $ClassName $stmt $ParamObjectTypes $Out }
            "IF" {
                Add-WasmAstConstructorParamFieldObjectHintsFromBody $ClassName ($stmt.then_block) $ParamObjectTypes $Out
                Add-WasmAstConstructorParamFieldObjectHintsFromBody $ClassName ($stmt.else_block) $ParamObjectTypes $Out
            }
            "WHILE" { Add-WasmAstConstructorParamFieldObjectHintsFromBody $ClassName ($stmt.body) $ParamObjectTypes $Out }
            "REPEAT" { Add-WasmAstConstructorParamFieldObjectHintsFromBody $ClassName ($stmt.body) $ParamObjectTypes $Out }
            "FOR" { Add-WasmAstConstructorParamFieldObjectHintsFromBody $ClassName ($stmt.body) $ParamObjectTypes $Out }
            "FOREACH" { Add-WasmAstConstructorParamFieldObjectHintsFromBody $ClassName ($stmt.body) $ParamObjectTypes $Out }
            "TRY" {
                Add-WasmAstConstructorParamFieldObjectHintsFromBody $ClassName ($stmt.try_block) $ParamObjectTypes $Out
                Add-WasmAstConstructorParamFieldObjectHintsFromBody $ClassName ($stmt.finally_block) $ParamObjectTypes $Out
            }
            default { }
        }
    }
}

function Get-WasmAstConstructorParamFieldObjectHints {
    param([string]$ClassName, [string[]]$ArgObjectClasses, [hashtable]$Seen = @{})

    $classes = @{}
    if ([string]::IsNullOrWhiteSpace($ClassName) -or -not $script:wasmClassDefs.ContainsKey($ClassName) -or $Seen.ContainsKey($ClassName)) {
        return $classes
    }
    $Seen[$ClassName] = $true
    $classNode = $script:wasmClassDefs[$ClassName].Node
    $init = Get-WasmAstClassInitMethod $classNode
    if ($null -eq $init) { return $classes }

    $paramObjectTypes = @{}
    $params = @(Get-WasmAstParamNames ($init.params))
    for ($i = 0; $i -lt $params.Count -and $i -lt $ArgObjectClasses.Count; $i++) {
        if (-not [string]::IsNullOrWhiteSpace($ArgObjectClasses[$i]) -and $script:wasmClassDefs.ContainsKey($ArgObjectClasses[$i])) {
            $paramObjectTypes[$params[$i]] = $ArgObjectClasses[$i]
        }
    }
    Add-WasmAstConstructorParamFieldObjectHintsFromBody $ClassName ($init.body) $paramObjectTypes $classes
    return $classes
}

function Get-WasmAstClassNameForConstructorFunction {
    param([string]$FunctionName)

    if ([string]::IsNullOrWhiteSpace($FunctionName)) { return "" }
    foreach ($entry in $script:wasmClassDefs.GetEnumerator()) {
        $className = [string]$entry.Key
        if ((Get-WasmClassConstructorName $className) -eq $FunctionName) {
            return $className
        }
    }
    return ""
}

function Add-WasmAstConstructorParamFunctionFieldHintsFromBody {
    param(
        [string]$ClassName,
        $Body,
        [hashtable]$ParamDisplayHints,
        [hashtable]$ParamLiftHints,
        [hashtable]$Seen = @{}
    )

    if ([string]::IsNullOrWhiteSpace($ClassName) -or $null -eq $Body -or $Seen.ContainsKey($ClassName)) { return }
    $Seen[$ClassName] = $true
    foreach ($stmt in @(As-WasmAstArray ($Body.body))) {
        if ($null -eq $stmt) { continue }
        switch ([string]$stmt.node) {
            "DOT_ASSIGN" {
                if ([string]$stmt.obj_name -eq "self" -and $null -ne $stmt.value -and [string]$stmt.value.node -eq "IDENT") {
                    $paramName = [string]$stmt.value.name
                    if ($ParamDisplayHints.ContainsKey($paramName)) {
                        Set-WasmAstClassFieldFunctionDisplayHint $ClassName ([string]$stmt.prop) ([string]$ParamDisplayHints[$paramName])
                    }
                    if ($ParamLiftHints.ContainsKey($paramName)) {
                        Set-WasmAstClassFieldFunctionLiftHint $ClassName ([string]$stmt.prop) ([string]$ParamLiftHints[$paramName])
                    }
                }
            }
            "EXPR_STMT" {
                if (Test-WasmAstSuperInitStmt $stmt) {
                    $parent = [string]$script:wasmClassDefs[$ClassName].Parent
                    if (-not [string]::IsNullOrWhiteSpace($parent) -and $script:wasmClassDefs.ContainsKey($parent)) {
                        $parentNode = $script:wasmClassDefs[$parent].Node
                        $parentInit = Get-WasmAstClassInitMethod $parentNode
                        if ($null -ne $parentInit) {
                            $parentDisplays = @{}
                            $parentLifts = @{}
                            $parentParams = @(Get-WasmAstParamNames ($parentInit.params))
                            $args = @(As-WasmAstArray ($stmt.expr.args))
                            for ($i = 0; $i -lt $parentParams.Count -and $i -lt $args.Count; $i++) {
                                if ($null -ne $args[$i] -and [string]$args[$i].node -eq "IDENT") {
                                    $argName = [string]$args[$i].name
                                    if ($ParamDisplayHints.ContainsKey($argName)) {
                                        $parentDisplays[[string]$parentParams[$i]] = [string]$ParamDisplayHints[$argName]
                                    }
                                    if ($ParamLiftHints.ContainsKey($argName)) {
                                        $parentLifts[[string]$parentParams[$i]] = [string]$ParamLiftHints[$argName]
                                    }
                                }
                            }
                            Add-WasmAstConstructorParamFunctionFieldHintsFromBody $parent ($parentInit.body) $parentDisplays $parentLifts $Seen
                        }
                    }
                }
            }
            "SuraBlock" { Add-WasmAstConstructorParamFunctionFieldHintsFromBody $ClassName $stmt $ParamDisplayHints $ParamLiftHints $Seen }
            "IF" {
                Add-WasmAstConstructorParamFunctionFieldHintsFromBody $ClassName ($stmt.then_block) $ParamDisplayHints $ParamLiftHints $Seen
                Add-WasmAstConstructorParamFunctionFieldHintsFromBody $ClassName ($stmt.else_block) $ParamDisplayHints $ParamLiftHints $Seen
            }
            "WHILE" { Add-WasmAstConstructorParamFunctionFieldHintsFromBody $ClassName ($stmt.body) $ParamDisplayHints $ParamLiftHints $Seen }
            "REPEAT" { Add-WasmAstConstructorParamFunctionFieldHintsFromBody $ClassName ($stmt.body) $ParamDisplayHints $ParamLiftHints $Seen }
            "FOR" { Add-WasmAstConstructorParamFunctionFieldHintsFromBody $ClassName ($stmt.body) $ParamDisplayHints $ParamLiftHints $Seen }
            "FOREACH" { Add-WasmAstConstructorParamFunctionFieldHintsFromBody $ClassName ($stmt.body) $ParamDisplayHints $ParamLiftHints $Seen }
            "TRY" {
                Add-WasmAstConstructorParamFunctionFieldHintsFromBody $ClassName ($stmt.try_block) $ParamDisplayHints $ParamLiftHints $Seen
                Add-WasmAstConstructorParamFunctionFieldHintsFromBody $ClassName ($stmt.finally_block) $ParamDisplayHints $ParamLiftHints $Seen
            }
            default { }
        }
    }
}

function Set-WasmAstOrderedDictEntryHintsForBase {
    param([string]$BaseName, $Entries)

    if ([string]::IsNullOrWhiteSpace($BaseName)) { return }
    $entryArray = @($Entries)
    if ($entryArray.Count -eq 0) { return }
    $keyOrder = New-Object System.Collections.Generic.List[string]
    foreach ($entry in $entryArray) {
        $key = [string]$entry.Key
        $typeName = [string]$entry.Type
        if ([string]::IsNullOrWhiteSpace($key) -or $typeName -notin @("string", "bool", "nil", "num", "array", "dict")) { return }
        $keyOrder.Add($key) | Out-Null
        Set-WasmAstAccessTypeHint $BaseName $key $typeName
    }
    $script:wasmDictKeyOrderHints[$BaseName] = [string[]]$keyOrder.ToArray()
}

function Resolve-WasmAstConstructorFieldSourceExpr {
    param($Expr, [hashtable]$ParamExprs)

    if ($null -eq $Expr) { return $null }
    if ([string]$Expr.node -eq "IDENT") {
        $name = [string]$Expr.name
        if ($ParamExprs.ContainsKey($name)) { return $ParamExprs[$name] }
    }
    return $Expr
}

function Add-WasmAstCollectionFieldHintsFromExpr {
    param([string]$BaseName, $Expr, [hashtable]$Seen = @{})

    if ([string]::IsNullOrWhiteSpace($BaseName) -or $null -eq $Expr) { return }
    $fixedStringKeyHints = Get-WasmAstFixedStringKeyAccessHintsForExpr $Expr
    if (Test-WasmAstFixedIndexedHintMapHasItems $fixedStringKeyHints) {
        Set-WasmAstStringKeyAccessHintsFromMap $BaseName $fixedStringKeyHints
    }
    $seenKey = ""
    if ([string]$Expr.node -eq "CALL") {
        $seenKey = "call:$([string]$Expr.name)"
        if (-not $Seen.ContainsKey($seenKey)) {
            $Seen[$seenKey] = $true
            $resolved = Resolve-WasmAstFunctionCallReturnExpr $Expr
            if ($null -ne $resolved) {
                Add-WasmAstCollectionFieldHintsFromExpr $BaseName $resolved $Seen
                return
            }
        }
    } elseif ([string]$Expr.node -eq "METHOD_CALL") {
        $seenKey = "method:$([string]$Expr.method)"
        if (-not $Seen.ContainsKey($seenKey)) {
            $Seen[$seenKey] = $true
            $resolved = Resolve-WasmAstMethodCallReturnExpr $Expr
            if ($null -ne $resolved) {
                Add-WasmAstCollectionFieldHintsFromExpr $BaseName $resolved $Seen
                return
            }
        }
    }
    if ([string]$Expr.node -eq "TERNARY") {
        $condState = Get-WasmAstKnownBoolLiteralState ($Expr.cond)
        if ($condState -eq "true") {
            Add-WasmAstCollectionFieldHintsFromExpr $BaseName ($Expr.then) $Seen
            return
        }
        if ($condState -eq "false") {
            Add-WasmAstCollectionFieldHintsFromExpr $BaseName ($Expr.else) $Seen
            return
        }
    }
    Clear-WasmAstEmptyCollectionHints $BaseName
    if (Test-WasmAstEmptyArrayLiteral $Expr) {
        Set-WasmAstEmptyArrayHint $BaseName
        return
    }
    if (Test-WasmAstEmptyDictLiteral $Expr) {
        Set-WasmAstEmptyDictHint $BaseName
        return
    }
    $indexedHints = Get-WasmAstFixedIndexedAccessHintsForExpr $Expr
    if (Test-WasmAstFixedIndexedHintMapHasItems $indexedHints) {
        Set-WasmAstIndexedAccessHintsFromMap $BaseName $indexedHints
    }
    if ([string]$Expr.node -eq "DICT_LIT") {
        foreach ($entry in @(As-WasmAstArray ($Expr.entries))) {
            $entryKey = [string]$entry.key
            if ([string]::IsNullOrWhiteSpace($entryKey)) { continue }
            $entryType = Get-WasmAstStaticValueType ($entry.value)
            if ($entryType -eq "function") {
                Set-WasmAstAccessTypeHintAfterWrite $BaseName $entryKey $entryType
                Set-WasmAstAccessFunctionDisplayHintAfterWrite $BaseName $entryKey (Get-WasmAstKnownFunctionDisplayName ($entry.value))
                Set-WasmAstAccessFunctionLiftHintAfterWrite $BaseName $entryKey (Get-WasmAstKnownFunctionLiftName ($entry.value))
            }
        }
    }
    $dictPickEntries = @(Get-WasmAstDictPickOrderedEntryTypes $Expr)
    if ($dictPickEntries.Count -gt 0) {
        Set-WasmAstOrderedDictEntryHintsForBase $BaseName $dictPickEntries
        return
    }
    $dictMergeEntries = @(Get-WasmAstDictMergeOrderedEntryTypes $Expr)
    if ($dictMergeEntries.Count -gt 0) {
        Set-WasmAstOrderedDictEntryHintsForBase $BaseName $dictMergeEntries
        return
    }
    $orderedEntries = @(Get-WasmAstOrderedDictEntryTypes $Expr)
    if ($orderedEntries.Count -gt 0) {
        Set-WasmAstOrderedDictEntryHintsForBase $BaseName $orderedEntries
        if ([string]$Expr.node -eq "DICT_LIT") {
            foreach ($entry in @(As-WasmAstArray ($Expr.entries))) {
                $entryKey = [string]$entry.key
                if ([string]::IsNullOrWhiteSpace($entryKey)) { continue }
                Add-WasmAstCollectionFieldHintsFromExpr "$BaseName.$entryKey" ($entry.value) $Seen
            }
        }
    }
}

function Add-WasmAstConstructorFieldCollectionHintsFromBody {
    param(
        [string]$ClassName,
        $Body,
        [hashtable]$ParamExprs,
        [string]$ObjectName
    )

    if ([string]::IsNullOrWhiteSpace($ClassName) -or [string]::IsNullOrWhiteSpace($ObjectName) -or $null -eq $Body) { return }
    foreach ($stmt in @(As-WasmAstArray ($Body.body))) {
        if ($null -eq $stmt) { continue }
        switch ([string]$stmt.node) {
            "DOT_ASSIGN" {
                if ([string]$stmt.obj_name -eq "self") {
                    $sourceExpr = Resolve-WasmAstConstructorFieldSourceExpr ($stmt.value) $ParamExprs
                    Add-WasmAstCollectionFieldHintsFromExpr "$ObjectName.$([string]$stmt.prop)" $sourceExpr
                }
            }
            "SuraBlock" { Add-WasmAstConstructorFieldCollectionHintsFromBody $ClassName $stmt $ParamExprs $ObjectName }
            "IF" {
                Add-WasmAstConstructorFieldCollectionHintsFromBody $ClassName ($stmt.then_block) $ParamExprs $ObjectName
                Add-WasmAstConstructorFieldCollectionHintsFromBody $ClassName ($stmt.else_block) $ParamExprs $ObjectName
            }
            "WHILE" { Add-WasmAstConstructorFieldCollectionHintsFromBody $ClassName ($stmt.body) $ParamExprs $ObjectName }
            "REPEAT" { Add-WasmAstConstructorFieldCollectionHintsFromBody $ClassName ($stmt.body) $ParamExprs $ObjectName }
            "FOR" { Add-WasmAstConstructorFieldCollectionHintsFromBody $ClassName ($stmt.body) $ParamExprs $ObjectName }
            "FOREACH" { Add-WasmAstConstructorFieldCollectionHintsFromBody $ClassName ($stmt.body) $ParamExprs $ObjectName }
            "TRY" {
                Add-WasmAstConstructorFieldCollectionHintsFromBody $ClassName ($stmt.try_block) $ParamExprs $ObjectName
                Add-WasmAstConstructorFieldCollectionHintsFromBody $ClassName ($stmt.finally_block) $ParamExprs $ObjectName
            }
            default { }
        }
    }
}

function Add-WasmAstConstructorFieldCollectionHints {
    param([string]$ObjectName, [string]$ClassName, $InputArgs)

    if ([string]::IsNullOrWhiteSpace($ObjectName) -or [string]::IsNullOrWhiteSpace($ClassName) -or
        -not $script:wasmClassDefs.ContainsKey($ClassName)) {
        return
    }
    $classNode = $script:wasmClassDefs[$ClassName].Node
    $init = Get-WasmAstClassInitMethod $classNode
    if ($null -eq $init) { return }
    $paramExprs = @{}
    $params = @(Get-WasmAstParamNames ($init.params))
    $args = @(As-WasmAstArray $InputArgs)
    for ($i = 0; $i -lt $params.Count -and $i -lt $args.Count; $i++) {
        $paramExprs[[string]$params[$i]] = $args[$i]
    }
    Add-WasmAstConstructorFieldCollectionHintsFromBody $ClassName ($init.body) $paramExprs $ObjectName
}

function Register-WasmAstClassFieldTypeHintsFromBody {
    param([string]$ClassName, $Body)

    if ([string]::IsNullOrWhiteSpace($ClassName) -or $null -eq $Body) { return }
    foreach ($stmt in @(As-WasmAstArray ($Body.body))) {
        if ($null -eq $stmt) { continue }
        switch ([string]$stmt.node) {
            "DOT_ASSIGN" {
                if ([string]$stmt.obj_name -eq "self") {
                    Set-WasmAstClassFieldTypeHint $ClassName ([string]$stmt.prop) (Get-WasmAstStaticValueType ($stmt.value))
                }
            }
            "SuraBlock" { Register-WasmAstClassFieldTypeHintsFromBody $ClassName $stmt }
            "IF" {
                Register-WasmAstClassFieldTypeHintsFromBody $ClassName ($stmt.then_block)
                Register-WasmAstClassFieldTypeHintsFromBody $ClassName ($stmt.else_block)
            }
            "WHILE" { Register-WasmAstClassFieldTypeHintsFromBody $ClassName ($stmt.body) }
            "REPEAT" { Register-WasmAstClassFieldTypeHintsFromBody $ClassName ($stmt.body) }
            "FOR" { Register-WasmAstClassFieldTypeHintsFromBody $ClassName ($stmt.body) }
            "FOREACH" { Register-WasmAstClassFieldTypeHintsFromBody $ClassName ($stmt.body) }
            "TRY" {
                Register-WasmAstClassFieldTypeHintsFromBody $ClassName ($stmt.try_block)
                Register-WasmAstClassFieldTypeHintsFromBody $ClassName ($stmt.finally_block)
            }
            default { }
        }
    }
}

function Register-WasmAstClassFieldTypeHints {
    param($ClassNode)

    if ($null -eq $ClassNode -or [string]$ClassNode.node -ne "CLASS_DEF") { return }
    $className = [string]$ClassNode.name
    if ([string]::IsNullOrWhiteSpace($className)) { return }
    foreach ($field in @(As-WasmAstArray ($ClassNode.fields))) {
        if ($null -ne $field -and $field.PSObject.Properties.Name -contains "default") {
            Set-WasmAstClassFieldTypeHint $className ([string]$field.name) (Get-WasmAstStaticValueType ($field.PSObject.Properties["default"].Value))
        }
    }
    $init = Get-WasmAstClassInitMethod $ClassNode
    if ($null -ne $init) {
        Register-WasmAstClassFieldTypeHintsFromBody $className ($init.body)
    }
}

function Register-WasmAstObservedCallParamTypes {
    param([string]$FunctionName, [string[]]$Params, $InputArgs)

    if ([string]::IsNullOrWhiteSpace($FunctionName) -or $null -eq $Params) { return }
    $argList = @(As-WasmAstArray $InputArgs)
    $observedFunctionParamDisplays = @{}
    $observedFunctionParamLifts = @{}
    for ($i = 0; $i -lt $Params.Count -and $i -lt $argList.Count; $i++) {
        $paramName = [string]$Params[$i]
        $argType = Get-WasmAstStaticValueType ($argList[$i])
        if ((Test-WasmAstFractionalStorageExpr ($argList[$i])) -or $argType -eq "value") {
            # A Value-preserving argument (notably a fractional number or a
            # collection containing one), including an alias already known to
            # hold a Value, needs the same tagged ABI in the callee. Reuse the
            # conflict marker that already denotes a stable Value parameter
            # instead of adding a second physical signature.
            Set-WasmAstForwardedFunctionParamTypeHint $FunctionName $paramName "value"
        } elseif ($argType -in @("string", "bool", "nil", "num", "array", "dict", "function")) {
            Set-WasmAstObservedFunctionParamTypeHint $FunctionName $paramName $argType
        }
        if ($argType -eq "function") {
            $argDisplayName = Get-WasmAstKnownFunctionDisplayName ($argList[$i])
            if (-not [string]::IsNullOrWhiteSpace($argDisplayName)) {
                Set-WasmAstObservedFunctionParamFunctionDisplayHint $FunctionName $paramName $argDisplayName
                $observedFunctionParamDisplays[$paramName] = $argDisplayName
            }
            $argLiftName = Get-WasmAstKnownFunctionLiftName ($argList[$i])
            if (-not [string]::IsNullOrWhiteSpace($argLiftName)) {
                Set-WasmAstObservedFunctionParamFunctionLiftHint $FunctionName $paramName $argLiftName
                $observedFunctionParamLifts[$paramName] = $argLiftName
            }
        }
        $argClass = Get-WasmAstObjectClassTypeHint ($argList[$i])
        if (-not [string]::IsNullOrWhiteSpace($argClass)) {
            Set-WasmAstObservedFunctionParamObjectClassHint $FunctionName $paramName $argClass
        } elseif ($argType -in @("string", "bool", "nil", "num", "array", "dict", "function")) {
            Set-WasmAstObservedFunctionParamNonObjectClassHint $FunctionName $paramName
        }
        Set-WasmAstObservedFunctionParamCollectionHints $FunctionName $paramName ($argList[$i])
    }
    if ($observedFunctionParamLifts.Count -gt 0) {
        $className = Get-WasmAstClassNameForConstructorFunction $FunctionName
        if (-not [string]::IsNullOrWhiteSpace($className) -and $script:wasmClassDefs.ContainsKey($className)) {
            $init = Get-WasmAstClassInitMethod ($script:wasmClassDefs[$className].Node)
            if ($null -ne $init) {
                Add-WasmAstConstructorParamFunctionFieldHintsFromBody $className ($init.body) $observedFunctionParamDisplays $observedFunctionParamLifts
            }
        }
    }
}

function Register-WasmAstObservedCallParamTypesFromExpr {
    param($Node)

    if ($null -eq $Node) { return }
    switch ([string]$Node.node) {
        "CALL" {
            $name = [string]$Node.name
            if ($script:wasmAstFunctionDefs.ContainsKey($name)) {
                Register-WasmAstObservedCallParamTypes $name ([string[]]$script:wasmAstFunctionDefs[$name].Params) ($Node.args)
            }
            foreach ($arg in @(As-WasmAstArray ($Node.args))) { Register-WasmAstObservedCallParamTypesFromExpr $arg }
        }
        "METHOD_CALL" {
            if ($null -ne $Node.obj) { Register-WasmAstObservedCallParamTypesFromExpr ($Node.obj) }
            if ($null -ne $Node.obj) {
                $className = Get-WasmAstObjectClassTypeHint ($Node.obj)
                if (-not [string]::IsNullOrWhiteSpace($className)) {
                    $methodInfo = Get-WasmAstClassMethod -ClassName $className -MethodName ([string]$Node.method)
                    if ($null -ne $methodInfo) {
                        Register-WasmAstObservedCallParamTypes ([string]$methodInfo.FunctionName) ([string[]]@(Get-WasmAstParamNames ($methodInfo.Method.params))) ($Node.args)
                        Register-WasmAstObservedSuperMethodCallParamTypes ([string]$methodInfo.ClassName) ($methodInfo.Method) ($Node.args)
                    }
                }
            }
            foreach ($arg in @(As-WasmAstArray ($Node.args))) { Register-WasmAstObservedCallParamTypesFromExpr $arg }
        }
        "SUPER_CALL" {
            $className = [string]$script:wasmCurrentClassContext
            $methodName = [string]$Node.method
            if (-not [string]::IsNullOrWhiteSpace($className) -and $script:wasmClassDefs.ContainsKey($className)) {
                if ($methodName -eq "init") {
                    $parentName = [string]$script:wasmClassDefs[$className].Parent
                    if (-not [string]::IsNullOrWhiteSpace($parentName) -and $script:wasmClassDefs.ContainsKey($parentName)) {
                        $parentInit = Get-WasmAstClassInitMethod ($script:wasmClassDefs[$parentName].Node)
                        if ($null -ne $parentInit) {
                            Register-WasmAstObservedCallParamTypes (Get-WasmClassConstructorName $parentName) ([string[]]@(Get-WasmAstParamNames ($parentInit.params))) ($Node.args)
                        }
                    }
                } else {
                    $methodInfo = Get-WasmAstSuperClassMethod -ClassName $className -MethodName $methodName
                    if ($null -ne $methodInfo) {
                        Register-WasmAstObservedCallParamTypes ([string]$methodInfo.FunctionName) ([string[]]@(Get-WasmAstParamNames ($methodInfo.Method.params))) ($Node.args)
                        Register-WasmAstObservedSuperMethodCallParamTypes ([string]$methodInfo.ClassName) ($methodInfo.Method) ($Node.args)
                    }
                }
            }
            foreach ($arg in @(As-WasmAstArray ($Node.args))) { Register-WasmAstObservedCallParamTypesFromExpr $arg }
        }
        "BIN_OP" {
            Register-WasmAstObservedCallParamTypesFromExpr ($Node.left)
            Register-WasmAstObservedCallParamTypesFromExpr ($Node.right)
        }
        "UNARY_OP" { Register-WasmAstObservedCallParamTypesFromExpr ($Node.operand) }
        "TERNARY" {
            Register-WasmAstObservedCallParamTypesFromExpr ($Node.cond)
            Register-WasmAstObservedCallParamTypesFromExpr ($Node.then)
            Register-WasmAstObservedCallParamTypesFromExpr ($Node.else)
        }
        "DOT_ACCESS" { Register-WasmAstObservedCallParamTypesFromExpr ($Node.obj) }
        "INDEX" {
            Register-WasmAstObservedCallParamTypesFromExpr ($Node.obj)
            Register-WasmAstObservedCallParamTypesFromExpr ($Node.key)
        }
        "ARRAY_LIT" {
            foreach ($item in @(As-WasmAstArray ($Node.elements))) { Register-WasmAstObservedCallParamTypesFromExpr $item }
        }
        "DICT_LIT" {
            foreach ($entry in @(As-WasmAstArray ($Node.entries))) { Register-WasmAstObservedCallParamTypesFromExpr ($entry.value) }
        }
        "STR_LIT" {
            foreach ($part in @(Get-WasmAstInterpolatedTextExprNodes ([string]$Node.value))) {
                Register-WasmAstObservedCallParamTypesFromExpr $part
            }
        }
        "NEW_EXPR" {
            $className = [string]$Node.class_name
            if (-not [string]::IsNullOrWhiteSpace($className) -and $script:wasmClassDefs.ContainsKey($className)) {
                $classNode = $script:wasmClassDefs[$className].Node
                $init = Get-WasmAstClassInitMethod $classNode
                if ($null -ne $init) {
                    Register-WasmAstObservedCallParamTypes (Get-WasmClassConstructorName $className) ([string[]]@(Get-WasmAstParamNames ($init.params))) ($Node.args)
                    Register-WasmAstObservedSuperInitCallParamTypes $className ($Node.args)
                }
            }
            foreach ($arg in @(As-WasmAstArray ($Node.args))) { Register-WasmAstObservedCallParamTypesFromExpr $arg }
        }
        "STR_INTERP" {
            foreach ($part in @(As-WasmAstArray ($Node.parts))) { Register-WasmAstObservedCallParamTypesFromExpr $part }
        }
        default { }
    }
}

function Register-WasmAstLoopAccessHints {
    param($Body, [switch]$LocalScope)

    if ($LocalScope) {
        Register-WasmAstStringAccessHints $Body -LocalScope
        return
    }
    $beforeLoopAccessHints = Get-WasmAstAccessHintFlowState
    Register-WasmAstStringAccessHints $Body -LocalScope:$LocalScope
    $bodyLoopAccessHints = Get-WasmAstAccessHintFlowState
    Set-WasmAstAccessHintFlowState (Merge-WasmAstAccessHintFlowStates $beforeLoopAccessHints $bodyLoopAccessHints)
}

function Register-WasmAstStringAccessHints {
    param($Node, [switch]$LocalScope)

    if ($null -eq $Node) { return }
    switch ([string]$Node.node) {
        "SuraBlock" {
            foreach ($stmt in @(As-WasmAstArray ($Node.body))) { Register-WasmAstStringAccessHints $stmt -LocalScope:$LocalScope }
        }
        "ASSIGN" {
            Register-WasmAstObservedCallParamTypesFromExpr ($Node.value)
            if ($LocalScope) { return }
            Clear-WasmAstEmptyCollectionHints ([string]$Node.name)
            if (Test-WasmAstEmptyArrayLiteral ($Node.value)) {
                Set-WasmAstEmptyArrayHint ([string]$Node.name)
            }
            if (Test-WasmAstEmptyDictLiteral ($Node.value)) {
                Set-WasmAstEmptyDictHint ([string]$Node.name)
            }
            if ($null -ne $Node.value -and [string]$Node.value.node -eq "DICT_LIT") {
                $keyOrder = New-Object System.Collections.Generic.List[string]
                foreach ($entry in @(As-WasmAstArray ($Node.value.entries))) {
                    $keyOrder.Add([string]$entry.key) | Out-Null
                    $entryType = Get-WasmAstStaticValueType ($entry.value)
                    if ($entryType -in @("string", "bool", "nil", "num", "array", "dict", "function")) {
                        Set-WasmAstAccessTypeHint ([string]$Node.name) ([string]$entry.key) $entryType
                    }
                    if ($entryType -eq "function") {
                        Set-WasmAstAccessFunctionDisplayHint ([string]$Node.name) ([string]$entry.key) (Get-WasmAstKnownFunctionDisplayName ($entry.value))
                        Set-WasmAstAccessFunctionLiftHint ([string]$Node.name) ([string]$entry.key) (Get-WasmAstKnownFunctionLiftName ($entry.value))
                    }
                    $entryClass = Get-WasmAstObjectClassTypeHint ($entry.value)
                    Set-WasmAstAccessObjectClassHint ([string]$Node.name) ([string]$entry.key) $entryClass
                }
                $script:wasmDictKeyOrderHints[[string]$Node.name] = [string[]]$keyOrder.ToArray()
            } elseif ($script:wasmDictKeyOrderHints.ContainsKey([string]$Node.name)) {
                $script:wasmDictKeyOrderHints.Remove([string]$Node.name)
            }
            if ($null -ne $Node.value -and [string]$Node.value.node -eq "ARRAY_LIT") {
                $elementIndex = 0
                foreach ($element in @(As-WasmAstArray ($Node.value.elements))) {
                    $elementType = Get-WasmAstStaticValueType $element
                    if ($elementType -in @("string", "bool", "nil", "num", "array", "dict", "function")) {
                        Set-WasmAstIndexedAccessTypeHint ([string]$Node.name) $elementIndex $elementType
                    }
                    if ($elementType -eq "function") {
                        Set-WasmAstIndexedAccessFunctionDisplayHint ([string]$Node.name) $elementIndex (Get-WasmAstKnownFunctionDisplayName $element)
                        Set-WasmAstIndexedAccessFunctionLiftHint ([string]$Node.name) $elementIndex (Get-WasmAstKnownFunctionLiftName $element)
                    }
                    $elementClass = Get-WasmAstObjectClassTypeHint $element
                    Set-WasmAstIndexedAccessObjectClassHint ([string]$Node.name) $elementIndex $elementClass
                    $elementIndex++
                }
            }
            $fixedIndexedReturnHints = Get-WasmAstFixedIndexedAccessHintsForExpr ($Node.value)
            Set-WasmAstIndexedAccessHintsFromMap ([string]$Node.name) $fixedIndexedReturnHints
            Add-WasmAstCollectionFieldHintsFromExpr ([string]$Node.name) ($Node.value)
            if ($null -ne $Node.value -and [string]$Node.value.node -eq "NEW_EXPR") {
                $className = [string]$Node.value.class_name
                $script:wasmObjectClassHints[[string]$Node.name] = $className
                foreach ($entry in (Get-WasmAstClassFieldTypeHints $className).GetEnumerator()) {
                    Set-WasmAstAccessTypeHint ([string]$Node.name) ([string]$entry.Key) ([string]$entry.Value)
                    Set-WasmAstObservedClassFieldTypeHint $className ([string]$entry.Key) ([string]$entry.Value)
                }
                $argTypes = New-Object System.Collections.Generic.List[string]
                $argObjectClasses = New-Object System.Collections.Generic.List[string]
                foreach ($arg in @(As-WasmAstArray ($Node.value.args))) {
                    $argTypes.Add((Get-WasmAstStaticValueType $arg)) | Out-Null
                    $argObjectClasses.Add((Get-WasmAstObjectClassTypeHint $arg)) | Out-Null
                }
                foreach ($entry in (Get-WasmAstConstructorParamFieldHints $className @($argTypes.ToArray())).GetEnumerator()) {
                    Set-WasmAstAccessTypeHint ([string]$Node.name) ([string]$entry.Key) ([string]$entry.Value)
                    Set-WasmAstObservedClassFieldTypeHint $className ([string]$entry.Key) ([string]$entry.Value)
                }
                foreach ($entry in (Get-WasmAstConstructorParamFieldObjectHints $className @($argObjectClasses.ToArray())).GetEnumerator()) {
                    Set-WasmAstAccessObjectClassHint ([string]$Node.name) ([string]$entry.Key) ([string]$entry.Value)
                    Set-WasmAstClassFieldObjectClassHint $className ([string]$entry.Key) ([string]$entry.Value)
                }
                Add-WasmAstConstructorFieldCollectionHints ([string]$Node.name) $className ($Node.value.args)
            }
            $valueType = if (Test-WasmAstValuePreservingExprCandidate ($Node.value)) { "value" } else { Get-WasmAstStaticValueType ($Node.value) }
            if ($valueType -in @("string", "bool", "nil", "num", "array", "dict", "function")) {
                Set-WasmAstValueTypeHint ([string]$Node.name) $valueType
            } elseif ($valueType -eq "value") {
                Set-WasmAstValueTypeHint ([string]$Node.name) "value"
            }
            if ($null -ne $Node.value -and [string]$Node.value.node -eq "STR_LIT" -and
                (Test-WasmAstStringLiteralIsConstant ([string]$Node.value.value))) {
                Set-WasmAstStringLiteralValueHint ([string]$Node.name) ([string]$Node.value.value)
            } else {
                Clear-WasmAstStringLiteralValueHint ([string]$Node.name)
            }
            if ($null -ne $Node.value -and [string]$Node.value.node -eq "NUM_LIT") {
                Set-WasmAstNumericLiteralValueHint ([string]$Node.name) ([double]$Node.value.value)
            } else {
                Clear-WasmAstNumericLiteralValueHint ([string]$Node.name)
            }
        }
        "DOT_ASSIGN" {
            Register-WasmAstObservedCallParamTypesFromExpr ($Node.value)
            if ($LocalScope) { return }
            $targetType = Get-WasmAstKnownValueType ([pscustomobject]@{ node = "IDENT"; name = [string]$Node.obj_name })
            if ([string]::IsNullOrWhiteSpace($targetType)) { $targetType = Get-WasmAstStaticValueType ([pscustomobject]@{ node = "IDENT"; name = [string]$Node.obj_name }) }
            if ($targetType -eq "value") { return }
            $dotBaseName = "$([string]$Node.obj_name).$([string]$Node.prop)"
            Clear-WasmAstEmptyCollectionHints $dotBaseName
            if (Test-WasmAstEmptyArrayLiteral ($Node.value)) {
                Set-WasmAstEmptyArrayHint $dotBaseName
            }
            if (Test-WasmAstEmptyDictLiteral ($Node.value)) {
                Set-WasmAstEmptyDictHint $dotBaseName
            }
            $valueType = Get-WasmAstStaticValueType ($Node.value)
            if ($valueType -in @("string", "bool", "nil", "num", "array", "dict", "function")) {
                Set-WasmAstAccessTypeHintAfterWrite ([string]$Node.obj_name) ([string]$Node.prop) $valueType
            }
            Set-WasmAstAccessFunctionDisplayHintAfterWrite ([string]$Node.obj_name) ([string]$Node.prop) (Get-WasmAstKnownFunctionDisplayName ($Node.value))
            Set-WasmAstAccessFunctionLiftHintAfterWrite ([string]$Node.obj_name) ([string]$Node.prop) (Get-WasmAstKnownFunctionLiftName ($Node.value))
            $valueClass = Get-WasmAstObjectClassTypeHint ($Node.value)
            Set-WasmAstAccessObjectClassHint ([string]$Node.obj_name) ([string]$Node.prop) $valueClass
        }
        "INDEX_ASSIGN" {
            Register-WasmAstObservedCallParamTypesFromExpr ($Node.key)
            Register-WasmAstObservedCallParamTypesFromExpr ($Node.value)
            if ($LocalScope) { return }
            $valueType = Get-WasmAstStaticValueType ($Node.value)
            $valueClass = Get-WasmAstObjectClassTypeHint ($Node.value)
            $targetType = Get-WasmAstKnownValueType ([pscustomobject]@{ node = "IDENT"; name = [string]$Node.name })
            if ([string]::IsNullOrWhiteSpace($targetType)) { $targetType = Get-WasmAstStaticValueType ([pscustomobject]@{ node = "IDENT"; name = [string]$Node.name }) }
            if ($targetType -eq "value") { return }
            if ($null -ne $Node.key -and [string]$Node.key.node -eq "STR_LIT") {
                if ($valueType -in @("string", "bool", "nil", "num", "array", "dict", "function")) {
                    Set-WasmAstAccessTypeHintAfterWrite ([string]$Node.name) ([string]$Node.key.value) $valueType
                }
                Set-WasmAstAccessFunctionDisplayHintAfterWrite ([string]$Node.name) ([string]$Node.key.value) (Get-WasmAstKnownFunctionDisplayName ($Node.value))
                Set-WasmAstAccessFunctionLiftHintAfterWrite ([string]$Node.name) ([string]$Node.key.value) (Get-WasmAstKnownFunctionLiftName ($Node.value))
                Set-WasmAstAccessObjectClassHint ([string]$Node.name) ([string]$Node.key.value) $valueClass
            } elseif ($null -ne $Node.key -and [string]$Node.key.node -eq "NUM_LIT") {
                if ($valueType -in @("string", "bool", "nil", "num", "array", "dict", "function")) {
                    $indexValue = [int][Math]::Truncate([double]$Node.key.value)
                    Set-WasmAstIndexedAccessTypeHint ([string]$Node.name) $indexValue $valueType
                }
                $indexValue = [int][Math]::Truncate([double]$Node.key.value)
                if ($valueType -eq "function") {
                    Set-WasmAstIndexedAccessFunctionDisplayHint ([string]$Node.name) $indexValue (Get-WasmAstKnownFunctionDisplayName ($Node.value))
                    Set-WasmAstIndexedAccessFunctionLiftHint ([string]$Node.name) $indexValue (Get-WasmAstKnownFunctionLiftName ($Node.value))
                }
                Set-WasmAstIndexedAccessObjectClassHint ([string]$Node.name) $indexValue $valueClass
            } else {
                $keyType = Get-WasmAstKnownValueType ($Node.key)
                if ([string]::IsNullOrWhiteSpace($keyType)) { $keyType = Get-WasmAstStaticValueType ($Node.key) }
                $targetType = Get-WasmAstKnownValueType ([pscustomobject]@{ node = "IDENT"; name = [string]$Node.name })
                if ([string]::IsNullOrWhiteSpace($targetType)) { $targetType = Get-WasmAstStaticValueType ([pscustomobject]@{ node = "IDENT"; name = [string]$Node.name }) }
                $knownStringKey = Get-WasmAstKnownStringLiteralValue ($Node.key)
                $preferExactKnownKey = (-not [string]::IsNullOrWhiteSpace($knownStringKey) -and [string]$Node.key.node -ne "IDENT")
                if ($preferExactKnownKey) {
                    if ($valueType -in @("string", "bool", "nil", "num", "array", "dict", "function")) {
                        Set-WasmAstAccessTypeHint ([string]$Node.name) $knownStringKey $valueType
                    }
                    if ($valueType -eq "function") {
                        Set-WasmAstAccessFunctionDisplayHint ([string]$Node.name) $knownStringKey (Get-WasmAstKnownFunctionDisplayName ($Node.value))
                        Set-WasmAstAccessFunctionLiftHint ([string]$Node.name) $knownStringKey (Get-WasmAstKnownFunctionLiftName ($Node.value))
                    }
                    Set-WasmAstAccessObjectClassHint ([string]$Node.name) $knownStringKey $valueClass
                } elseif ($keyType -eq "string" -and $targetType -eq "dict") {
                    if ($valueType -in @("string", "bool", "nil", "num", "array", "dict", "function")) {
                        Set-WasmAstAccessTypeHint ([string]$Node.name) "*" $valueType
                        if ($null -ne $Node.key -and [string]$Node.key.node -eq "IDENT") {
                            Set-WasmAstDynamicKeyAccessTypeHint ([string]$Node.name) ([string]$Node.key.name) $valueType
                        }
                    }
                    if ($valueType -eq "function" -and $null -ne $Node.key -and [string]$Node.key.node -eq "IDENT") {
                        Set-WasmAstDynamicKeyAccessFunctionDisplayHint ([string]$Node.name) ([string]$Node.key.name) (Get-WasmAstKnownFunctionDisplayName ($Node.value))
                        Set-WasmAstDynamicKeyAccessFunctionLiftHint ([string]$Node.name) ([string]$Node.key.name) (Get-WasmAstKnownFunctionLiftName ($Node.value))
                    }
                    Set-WasmAstAccessObjectClassHint ([string]$Node.name) "*" $valueClass
                    if ($null -ne $Node.key -and [string]$Node.key.node -eq "IDENT") {
                        Set-WasmAstDynamicKeyAccessObjectClassHint ([string]$Node.name) ([string]$Node.key.name) $valueClass
                    }
                } elseif ($keyType -eq "string" -and $targetType -notin @("array", "string")) {
                    if ($valueType -in @("string", "bool", "nil", "num", "array", "dict", "function") -and
                        $null -ne $Node.key -and [string]$Node.key.node -eq "IDENT") {
                        Set-WasmAstDynamicKeyAccessTypeHint ([string]$Node.name) ([string]$Node.key.name) $valueType
                    }
                    if ($valueType -eq "function" -and $null -ne $Node.key -and [string]$Node.key.node -eq "IDENT") {
                        Set-WasmAstDynamicKeyAccessFunctionDisplayHint ([string]$Node.name) ([string]$Node.key.name) (Get-WasmAstKnownFunctionDisplayName ($Node.value))
                        Set-WasmAstDynamicKeyAccessFunctionLiftHint ([string]$Node.name) ([string]$Node.key.name) (Get-WasmAstKnownFunctionLiftName ($Node.value))
                    }
                    if ($null -ne $Node.key -and [string]$Node.key.node -eq "IDENT") {
                        Set-WasmAstDynamicKeyAccessObjectClassHint ([string]$Node.name) ([string]$Node.key.name) $valueClass
                    }
                } elseif ($keyType -eq "num" -and $targetType -eq "array" -and
                    $null -ne $Node.key -and [string]$Node.key.node -eq "IDENT") {
                if ($valueType -in @("string", "bool", "nil", "num", "array", "dict", "function")) {
                    Set-WasmAstDynamicIndexedAccessTypeHint ([string]$Node.name) ([string]$Node.key.name) $valueType
                }
                if ($valueType -eq "function") {
                    Set-WasmAstDynamicIndexedAccessFunctionDisplayHint ([string]$Node.name) ([string]$Node.key.name) (Get-WasmAstKnownFunctionDisplayName ($Node.value))
                    Set-WasmAstDynamicIndexedAccessFunctionLiftHint ([string]$Node.name) ([string]$Node.key.name) (Get-WasmAstKnownFunctionLiftName ($Node.value))
                }
                Set-WasmAstDynamicIndexedAccessObjectClassHint ([string]$Node.name) ([string]$Node.key.name) $valueClass
            }
        }
        }
        "IF" {
            Register-WasmAstStringAccessHints ($Node.then_block) -LocalScope:$LocalScope
            Register-WasmAstStringAccessHints ($Node.else_block) -LocalScope:$LocalScope
        }
        "WHILE" { Register-WasmAstLoopAccessHints ($Node.body) -LocalScope:$LocalScope }
        "REPEAT" { Register-WasmAstLoopAccessHints ($Node.body) -LocalScope:$LocalScope }
        "FOR" { Register-WasmAstLoopAccessHints ($Node.body) -LocalScope:$LocalScope }
        "FOREACH" { Register-WasmAstLoopAccessHints ($Node.body) -LocalScope:$LocalScope }
        "MATCH" {
            foreach ($arm in @(As-WasmAstArray ($Node.arms))) { Register-WasmAstStringAccessHints ($arm.body) -LocalScope:$LocalScope }
        }
        "TRY" {
            Register-WasmAstStringAccessHints ($Node.try_block) -LocalScope:$LocalScope
            Register-WasmAstStringAccessHints ($Node.catch_block) -LocalScope:$LocalScope
            Register-WasmAstStringAccessHints ($Node.finally_block) -LocalScope:$LocalScope
        }
        "FUNC_DEF" { Register-WasmAstStringAccessHints ($Node.body) -LocalScope }
        "EXPR_STMT" { Register-WasmAstObservedCallParamTypesFromExpr ($Node.expr) }
        "RETURN" { Register-WasmAstObservedCallParamTypesFromExpr ($Node.value) }
        "CMD" {
            foreach ($arg in @(As-WasmAstArray ($Node.args))) { Register-WasmAstObservedCallParamTypesFromExpr $arg }
        }
        "CLASS_DEF" {
            Register-WasmAstClassFieldTypeHints $Node
            Register-WasmAstClassMethodReturnTypeHints $Node
            $previousClassContext = $script:wasmCurrentClassContext
            try {
                $script:wasmCurrentClassContext = [string]$Node.name
                foreach ($method in @(As-WasmAstArray ($Node.methods))) { Register-WasmAstStringAccessHints ($method.body) -LocalScope }
            } finally {
                $script:wasmCurrentClassContext = $previousClassContext
            }
        }
        default { }
    }
}

function Set-WasmAstGlobalAssignmentHints {
    param([string]$Name, $Value)

    if ([string]::IsNullOrWhiteSpace($Name)) { return }

    Clear-WasmAstEmptyCollectionHints $Name
    if (Test-WasmAstEmptyArrayLiteral $Value) {
        Set-WasmAstEmptyArrayHint $Name
    }
    if (Test-WasmAstEmptyDictLiteral $Value) {
        Set-WasmAstEmptyDictHint $Name
    }

    if ($null -ne $Value -and [string]$Value.node -eq "DICT_LIT") {
        $keyOrder = New-Object System.Collections.Generic.List[string]
        foreach ($entry in @(As-WasmAstArray ($Value.entries))) {
            $keyOrder.Add([string]$entry.key) | Out-Null
            $entryType = Get-WasmAstStaticValueType ($entry.value)
            if ($entryType -in @("string", "bool", "nil", "num", "array", "dict", "function")) {
                Set-WasmAstAccessTypeHintAfterWrite $Name ([string]$entry.key) $entryType
            }
            if ($entryType -eq "function") {
                Set-WasmAstAccessFunctionDisplayHint $Name ([string]$entry.key) (Get-WasmAstKnownFunctionDisplayName ($entry.value))
                Set-WasmAstAccessFunctionLiftHint $Name ([string]$entry.key) (Get-WasmAstKnownFunctionLiftName ($entry.value))
            }
            $entryClass = Get-WasmAstObjectClassTypeHint ($entry.value)
            Set-WasmAstAccessObjectClassHint $Name ([string]$entry.key) $entryClass
        }
        $script:wasmDictKeyOrderHints[$Name] = [string[]]$keyOrder.ToArray()
    } elseif ($script:wasmDictKeyOrderHints.ContainsKey($Name)) {
        $script:wasmDictKeyOrderHints.Remove($Name)
    }

    if ($null -ne $Value -and [string]$Value.node -eq "ARRAY_LIT") {
        $elementIndex = 0
        foreach ($element in @(As-WasmAstArray ($Value.elements))) {
            $elementType = Get-WasmAstStaticValueType $element
            if ($elementType -in @("string", "bool", "nil", "num", "array", "dict", "function")) {
                Set-WasmAstIndexedAccessTypeHintAfterWrite $Name $elementIndex $elementType
            }
            if ($elementType -eq "function") {
                Set-WasmAstIndexedAccessFunctionDisplayHint $Name $elementIndex (Get-WasmAstKnownFunctionDisplayName $element)
                Set-WasmAstIndexedAccessFunctionLiftHint $Name $elementIndex (Get-WasmAstKnownFunctionLiftName $element)
            }
            $elementClass = Get-WasmAstObjectClassTypeHint $element
            Set-WasmAstIndexedAccessObjectClassHint $Name $elementIndex $elementClass
            $elementIndex++
        }
    }

    $fixedIndexedReturnHints = Get-WasmAstFixedIndexedAccessHintsForExpr $Value
    if (Test-WasmAstFixedIndexedHintMapHasItems $fixedIndexedReturnHints) {
        Set-WasmAstIndexedAccessHintsFromMap $Name $fixedIndexedReturnHints
        Set-WasmAstCurrentLocalIndexedAccessHintsFromMap $Name $fixedIndexedReturnHints
    } else {
        Set-WasmAstCurrentLocalIndexedAccessHintsFromMap $Name @{}
    }
    Add-WasmAstCollectionFieldHintsFromExpr $Name $Value

    if ($null -ne $Value -and [string]$Value.node -eq "NEW_EXPR") {
        $className = [string]$Value.class_name
        $script:wasmObjectClassHints[$Name] = $className
        Set-WasmAstCurrentLocalObjectClassHint $Name $className
        foreach ($entry in (Get-WasmAstClassFieldTypeHints $className).GetEnumerator()) {
            Set-WasmAstAccessTypeHintAfterWrite $Name ([string]$entry.Key) ([string]$entry.Value)
            Set-WasmAstObservedClassFieldTypeHint $className ([string]$entry.Key) ([string]$entry.Value)
        }
        $argTypes = New-Object System.Collections.Generic.List[string]
        $argObjectClasses = New-Object System.Collections.Generic.List[string]
        foreach ($arg in @(As-WasmAstArray ($Value.args))) {
            $argTypes.Add((Get-WasmAstStaticValueType $arg)) | Out-Null
            $argObjectClasses.Add((Get-WasmAstObjectClassTypeHint $arg)) | Out-Null
        }
        foreach ($entry in (Get-WasmAstConstructorParamFieldHints $className @($argTypes.ToArray())).GetEnumerator()) {
            Set-WasmAstAccessTypeHintAfterWrite $Name ([string]$entry.Key) ([string]$entry.Value)
            Set-WasmAstObservedClassFieldTypeHint $className ([string]$entry.Key) ([string]$entry.Value)
        }
        foreach ($entry in (Get-WasmAstConstructorParamFieldObjectHints $className @($argObjectClasses.ToArray())).GetEnumerator()) {
            Set-WasmAstAccessObjectClassHint $Name ([string]$entry.Key) ([string]$entry.Value)
            Set-WasmAstClassFieldObjectClassHint $className ([string]$entry.Key) ([string]$entry.Value)
        }
        Add-WasmAstConstructorFieldCollectionHints $Name $className ($Value.args)
    } else {
        Set-WasmAstCurrentLocalObjectClassHint $Name ""
    }

    $valueType = Get-WasmAstStaticValueType $Value
    if ($valueType -in @("string", "bool", "nil", "num", "array", "dict", "function")) {
        Set-WasmAstValueTypeHintAfterWrite $Name $valueType
        Set-WasmAstCurrentLocalValueTypeHint $Name $valueType
    } else {
        Set-WasmAstCurrentLocalValueTypeHint $Name ""
    }
    if ($valueType -eq "function") {
        $script:wasmGlobalFunctionDisplayHints[$Name] = Get-WasmAstKnownFunctionDisplayName $Value
        $script:wasmGlobalFunctionLiftHints[$Name] = Get-WasmAstKnownFunctionLiftName $Value
    } elseif ($script:wasmGlobalFunctionDisplayHints.ContainsKey($Name)) {
        $script:wasmGlobalFunctionDisplayHints.Remove($Name)
        if ($script:wasmGlobalFunctionLiftHints.ContainsKey($Name)) {
            $script:wasmGlobalFunctionLiftHints.Remove($Name)
        }
    } elseif ($script:wasmGlobalFunctionLiftHints.ContainsKey($Name)) {
        $script:wasmGlobalFunctionLiftHints.Remove($Name)
    }

    if ($null -ne $Value -and [string]$Value.node -eq "STR_LIT" -and
        (Test-WasmAstStringLiteralIsConstant ([string]$Value.value))) {
        Set-WasmAstStringLiteralValueHint $Name ([string]$Value.value)
    } else {
        Clear-WasmAstStringLiteralValueHint $Name
    }
    if ($null -ne $Value -and [string]$Value.node -eq "NUM_LIT") {
        Set-WasmAstNumericLiteralValueHint $Name ([double]$Value.value)
    } else {
        Clear-WasmAstNumericLiteralValueHint $Name
    }
}

function Set-WasmAstGlobalAccessAssignmentHints {
    param([string]$BaseName, [string]$KeyName, $Value)

    if ([string]::IsNullOrWhiteSpace($BaseName) -or [string]::IsNullOrWhiteSpace($KeyName)) { return }
    $accessPath = "$BaseName.$KeyName"
    Clear-WasmAstEmptyCollectionHints $accessPath
    if (Test-WasmAstEmptyArrayLiteral $Value) {
        Set-WasmAstEmptyArrayHint $accessPath
    }
    if (Test-WasmAstEmptyDictLiteral $Value) {
        Set-WasmAstEmptyDictHint $accessPath
    }
    Add-WasmAstCollectionFieldHintsFromExpr $accessPath $Value

    $valueType = Get-WasmAstStaticValueType $Value
    if ($valueType -in @("string", "bool", "nil", "num", "array", "dict", "function")) {
        Set-WasmAstAccessTypeHintAfterWrite $BaseName $KeyName $valueType
    }
    Set-WasmAstAccessFunctionDisplayHintAfterWrite $BaseName $KeyName (Get-WasmAstKnownFunctionDisplayName $Value)
    Set-WasmAstAccessFunctionLiftHintAfterWrite $BaseName $KeyName (Get-WasmAstKnownFunctionLiftName $Value)
    $valueClass = Get-WasmAstObjectClassTypeHint $Value
    Set-WasmAstAccessObjectClassHint $BaseName $KeyName $valueClass
}

function Set-WasmAstGlobalIndexedAssignmentHints {
    param([string]$BaseName, $Key, $Value)

    if ([string]::IsNullOrWhiteSpace($BaseName) -or $null -eq $Key) { return }
    $knownStringKey = ""
    if ([string]$Key.node -eq "STR_LIT") {
        $knownStringKey = [string]$Key.value
    } else {
        $knownStringKey = Get-WasmAstKnownStringLiteralValue $Key
    }
    if (-not [string]::IsNullOrWhiteSpace($knownStringKey)) {
        Set-WasmAstGlobalAccessAssignmentHints $BaseName $knownStringKey $Value
        return
    }

    $literalIndex = Get-WasmAstKnownNumericLiteralValue $Key
    if ($null -eq $literalIndex) { return }
    $index = [int][Math]::Truncate([double]$literalIndex)
    if ($index -lt 0) { return }

    $valueType = Get-WasmAstStaticValueType $Value
    $functionDisplayName = Get-WasmAstKnownFunctionDisplayName $Value
    $valueClass = Get-WasmAstObjectClassTypeHint $Value
    if ($valueType -in @("string", "bool", "nil", "num", "array", "dict", "function")) {
        Set-WasmAstIndexedAccessTypeHintAfterWrite $BaseName $index $valueType
    }
    if ($valueType -eq "function") {
        Set-WasmAstIndexedAccessFunctionDisplayHint $BaseName $index $functionDisplayName
        Set-WasmAstIndexedAccessFunctionLiftHint $BaseName $index (Get-WasmAstKnownFunctionLiftName $Value)
    }
    Set-WasmAstIndexedAccessObjectClassHint $BaseName $index $valueClass
    Set-WasmAstCurrentLocalIndexedAccessHint $BaseName $index $valueType $functionDisplayName $valueClass
}

function Apply-WasmAstGlobalAssignmentHintsFromExpr {
    param($Node, [hashtable]$Seen = @{})

    if ($null -eq $Node) { return }
    switch ([string]$Node.node) {
        "CALL" {
            foreach ($arg in @(As-WasmAstArray ($Node.args))) { Apply-WasmAstGlobalAssignmentHintsFromExpr $arg $Seen }
            Apply-WasmAstGlobalAssignmentHintsForCall $Node $Seen
        }
        "METHOD_CALL" {
            Apply-WasmAstGlobalAssignmentHintsFromExpr ($Node.obj) $Seen
            foreach ($arg in @(As-WasmAstArray ($Node.args))) { Apply-WasmAstGlobalAssignmentHintsFromExpr $arg $Seen }
            Apply-WasmAstGlobalAssignmentHintsForMethodCall $Node $Seen
        }
        "SUPER_CALL" {
            foreach ($arg in @(As-WasmAstArray ($Node.args))) { Apply-WasmAstGlobalAssignmentHintsFromExpr $arg $Seen }
            Apply-WasmAstGlobalAssignmentHintsForSuperCall $Node $Seen
        }
        "NEW_EXPR" {
            foreach ($arg in @(As-WasmAstArray ($Node.args))) { Apply-WasmAstGlobalAssignmentHintsFromExpr $arg $Seen }
            Apply-WasmAstGlobalAssignmentHintsForNewExpr $Node $Seen
        }
        "DOT_ACCESS" { Apply-WasmAstGlobalAssignmentHintsFromExpr ($Node.obj) $Seen }
        "INDEX" {
            Apply-WasmAstGlobalAssignmentHintsFromExpr ($Node.obj) $Seen
            Apply-WasmAstGlobalAssignmentHintsFromExpr ($Node.key) $Seen
        }
        "BIN_OP" {
            Apply-WasmAstGlobalAssignmentHintsFromExpr ($Node.left) $Seen
            Apply-WasmAstGlobalAssignmentHintsFromExpr ($Node.right) $Seen
        }
        "UNARY_OP" { Apply-WasmAstGlobalAssignmentHintsFromExpr ($Node.operand) $Seen }
        "TERNARY" {
            Apply-WasmAstGlobalAssignmentHintsFromExpr ($Node.cond) $Seen
            Apply-WasmAstGlobalAssignmentHintsFromExpr ($Node.then) $Seen
            Apply-WasmAstGlobalAssignmentHintsFromExpr ($Node.else) $Seen
        }
        "ARRAY_LIT" {
            foreach ($element in @(As-WasmAstArray ($Node.elements))) { Apply-WasmAstGlobalAssignmentHintsFromExpr $element $Seen }
        }
        "DICT_LIT" {
            foreach ($entry in @(As-WasmAstArray ($Node.entries))) { Apply-WasmAstGlobalAssignmentHintsFromExpr ($entry.value) $Seen }
        }
        "STR_INTERP" {
            foreach ($part in @(As-WasmAstArray ($Node.parts))) { Apply-WasmAstGlobalAssignmentHintsFromExpr $part $Seen }
        }
        default { }
    }
}

function Apply-WasmAstGlobalAssignmentHintsForCall {
    param($CallNode, [hashtable]$Seen = @{})

    if ($null -eq $CallNode -or [string]$CallNode.node -ne "CALL") { return }
    $name = [string]$CallNode.name
    if ([string]::IsNullOrWhiteSpace($name) -or -not $script:wasmAstFunctionDefs.ContainsKey($name)) { return }
    $seenKey = "call:$name"
    if ($Seen.ContainsKey($seenKey)) { return }
    $Seen[$seenKey] = $true
    try {
        $fn = $script:wasmAstFunctionDefs[$name]
        if ($null -eq $fn.Node -or $null -eq $fn.Node.body) { return }
        Apply-WasmAstGlobalAssignmentHintsFromBody ($fn.Node.body) (New-WasmAstGlobalDeclMap ($fn.Node.body)) $Seen
    } finally {
        [void]$Seen.Remove($seenKey)
    }
}

function Apply-WasmAstGlobalAssignmentHintsForMethodCall {
    param($MethodCallNode, [hashtable]$Seen = @{})

    if ($null -eq $MethodCallNode -or [string]$MethodCallNode.node -ne "METHOD_CALL") { return }
    $method = [string]$MethodCallNode.method
    $className = Get-WasmAstObjectClassTypeWithLocals ($MethodCallNode.obj) $script:wasmCurrentLocalObjectClassHints $script:wasmCurrentClassContext @{}
    if ([string]::IsNullOrWhiteSpace($method) -or [string]::IsNullOrWhiteSpace($className)) { return }
    $methodInfo = Get-WasmAstClassMethod -ClassName $className -MethodName $method
    if ($null -eq $methodInfo -or $null -eq $methodInfo.Method -or $null -eq $methodInfo.Method.body) { return }
    $seenKey = "method:$([string]$methodInfo.ClassName).$method"
    if ($Seen.ContainsKey($seenKey)) { return }
    $Seen[$seenKey] = $true
    $previousClassContext = $script:wasmCurrentClassContext
    try {
        $script:wasmCurrentClassContext = [string]$methodInfo.ClassName
        Apply-WasmAstGlobalAssignmentHintsFromBody ($methodInfo.Method.body) (New-WasmAstGlobalDeclMap ($methodInfo.Method.body)) $Seen
    } finally {
        $script:wasmCurrentClassContext = $previousClassContext
        [void]$Seen.Remove($seenKey)
    }
}

function Apply-WasmAstGlobalAssignmentHintsForSuperCall {
    param($SuperCallNode, [hashtable]$Seen = @{})

    if ($null -eq $SuperCallNode -or [string]$SuperCallNode.node -ne "SUPER_CALL") { return }
    $method = [string]$SuperCallNode.method
    $className = [string]$script:wasmCurrentClassContext
    if ([string]::IsNullOrWhiteSpace($method) -or [string]::IsNullOrWhiteSpace($className)) { return }
    if ($method -eq "init") {
        if (-not $script:wasmClassDefs.ContainsKey($className)) { return }
        $parentName = [string]$script:wasmClassDefs[$className].Parent
        if ([string]::IsNullOrWhiteSpace($parentName) -or -not $script:wasmClassDefs.ContainsKey($parentName)) { return }
        $parentInit = Get-WasmAstClassInitMethod ($script:wasmClassDefs[$parentName].Node)
        if ($null -eq $parentInit -or $null -eq $parentInit.body) { return }
        $seenKey = "super:$parentName.init"
        if ($Seen.ContainsKey($seenKey)) { return }
        $Seen[$seenKey] = $true
        $previousClassContext = $script:wasmCurrentClassContext
        try {
            $script:wasmCurrentClassContext = $parentName
            Apply-WasmAstGlobalAssignmentHintsFromBody ($parentInit.body) (New-WasmAstGlobalDeclMap ($parentInit.body)) $Seen
        } finally {
            $script:wasmCurrentClassContext = $previousClassContext
            [void]$Seen.Remove($seenKey)
        }
        return
    }
    $methodInfo = Get-WasmAstSuperClassMethod -ClassName $className -MethodName $method
    if ($null -eq $methodInfo -or $null -eq $methodInfo.Method -or $null -eq $methodInfo.Method.body) { return }
    $seenKey = "super:$([string]$methodInfo.ClassName).$method"
    if ($Seen.ContainsKey($seenKey)) { return }
    $Seen[$seenKey] = $true
    $previousClassContext = $script:wasmCurrentClassContext
    try {
        $script:wasmCurrentClassContext = [string]$methodInfo.ClassName
        Apply-WasmAstGlobalAssignmentHintsFromBody ($methodInfo.Method.body) (New-WasmAstGlobalDeclMap ($methodInfo.Method.body)) $Seen
    } finally {
        $script:wasmCurrentClassContext = $previousClassContext
        [void]$Seen.Remove($seenKey)
    }
}

function Apply-WasmAstGlobalAssignmentHintsForNewExpr {
    param($NewExprNode, [hashtable]$Seen = @{})

    if ($null -eq $NewExprNode -or [string]$NewExprNode.node -ne "NEW_EXPR") { return }
    $className = [string]$NewExprNode.class_name
    if ([string]::IsNullOrWhiteSpace($className) -or -not $script:wasmClassDefs.ContainsKey($className)) { return }
    $classNode = $script:wasmClassDefs[$className].Node
    $init = Get-WasmAstClassInitMethod $classNode
    if ($null -eq $init -or $null -eq $init.body) { return }
    $seenKey = "new:$className"
    if ($Seen.ContainsKey($seenKey)) { return }
    $Seen[$seenKey] = $true
    $previousClassContext = $script:wasmCurrentClassContext
    try {
        $script:wasmCurrentClassContext = $className
        Apply-WasmAstGlobalAssignmentHintsFromBody ($init.body) (New-WasmAstGlobalDeclMap ($init.body)) $Seen
    } finally {
        $script:wasmCurrentClassContext = $previousClassContext
        [void]$Seen.Remove($seenKey)
    }
}

function Apply-WasmAstGlobalAssignmentHintsFromBody {
    param($Node, [hashtable]$GlobalDecls, [hashtable]$Seen = @{})

    if ($null -eq $Node) { return }
    if ($null -eq $GlobalDecls) { $GlobalDecls = @{} }
    switch ([string]$Node.node) {
        "SuraBlock" {
            foreach ($stmt in @(As-WasmAstArray ($Node.body))) {
                Apply-WasmAstGlobalAssignmentHintsFromBody $stmt $GlobalDecls $Seen
            }
        }
        "GLOBAL_DECL" {
            foreach ($nameValue in @(As-WasmAstArray ($Node.names))) {
                $name = [string]$nameValue
                if (-not [string]::IsNullOrWhiteSpace($name)) { $GlobalDecls[$name] = $true }
            }
        }
        "ASSIGN" {
            Apply-WasmAstGlobalAssignmentHintsFromExpr ($Node.value) $Seen
            $name = [string]$Node.name
            if ($GlobalDecls.ContainsKey($name) -or
                ($GlobalDecls.Count -eq 0 -and $script:wasmModuleGlobals.ContainsKey($name))) {
                Set-WasmAstGlobalAssignmentHints $name ($Node.value)
            }
        }
        "IN_PLACE" {
            Apply-WasmAstGlobalAssignmentHintsFromExpr ($Node.value) $Seen
        }
        "INDEX_ASSIGN" {
            Apply-WasmAstGlobalAssignmentHintsFromExpr ($Node.key) $Seen
            Apply-WasmAstGlobalAssignmentHintsFromExpr ($Node.value) $Seen
            $name = [string]$Node.name
            if ($GlobalDecls.ContainsKey($name)) {
                Set-WasmAstGlobalIndexedAssignmentHints $name ($Node.key) ($Node.value)
            }
        }
        "DOT_ASSIGN" {
            Apply-WasmAstGlobalAssignmentHintsFromExpr ($Node.value) $Seen
            $baseName = [string]$Node.obj_name
            if ($GlobalDecls.ContainsKey($baseName)) {
                Set-WasmAstGlobalAccessAssignmentHints $baseName ([string]$Node.prop) ($Node.value)
            }
        }
        "EXPR_STMT" {
            Apply-WasmAstGlobalAssignmentHintsFromExpr ($Node.expr) $Seen
        }
        "RETURN" {
            Apply-WasmAstGlobalAssignmentHintsFromExpr ($Node.value) $Seen
        }
        "THROW" {
            Apply-WasmAstGlobalAssignmentHintsFromExpr ($Node.msg) $Seen
        }
        "CMD" {
            foreach ($arg in @(As-WasmAstArray ($Node.args))) { Apply-WasmAstGlobalAssignmentHintsFromExpr $arg $Seen }
        }
        "IF" {
            Apply-WasmAstGlobalAssignmentHintsFromExpr ($Node.cond) $Seen
            Apply-WasmAstGlobalAssignmentHintsFromBody ($Node.then_block) $GlobalDecls $Seen
            Apply-WasmAstGlobalAssignmentHintsFromBody ($Node.else_block) $GlobalDecls $Seen
        }
        "WHILE" {
            Apply-WasmAstGlobalAssignmentHintsFromExpr ($Node.cond) $Seen
            Apply-WasmAstGlobalAssignmentHintsFromBody ($Node.body) $GlobalDecls $Seen
        }
        "REPEAT" {
            Apply-WasmAstGlobalAssignmentHintsFromExpr ($Node.count) $Seen
            Apply-WasmAstGlobalAssignmentHintsFromBody ($Node.body) $GlobalDecls $Seen
        }
        "FOR" {
            Apply-WasmAstGlobalAssignmentHintsFromExpr ($Node.from) $Seen
            Apply-WasmAstGlobalAssignmentHintsFromExpr ($Node.to) $Seen
            Apply-WasmAstGlobalAssignmentHintsFromExpr ($Node.step) $Seen
            Apply-WasmAstGlobalAssignmentHintsFromBody ($Node.body) $GlobalDecls $Seen
        }
        "FOREACH" {
            Apply-WasmAstGlobalAssignmentHintsFromExpr ($Node.collection) $Seen
            Apply-WasmAstGlobalAssignmentHintsFromBody ($Node.body) $GlobalDecls $Seen
        }
        "MATCH" {
            Apply-WasmAstGlobalAssignmentHintsFromExpr ($Node.subject) $Seen
            foreach ($arm in @(As-WasmAstArray ($Node.arms))) {
                Apply-WasmAstGlobalAssignmentHintsFromExpr ($arm.pattern) $Seen
                Apply-WasmAstGlobalAssignmentHintsFromExpr ($arm.range_end) $Seen
                Apply-WasmAstGlobalAssignmentHintsFromBody ($arm.body) $GlobalDecls $Seen
            }
        }
        "TRY" {
            Apply-WasmAstGlobalAssignmentHintsFromBody ($Node.try_block) $GlobalDecls $Seen
            Apply-WasmAstGlobalAssignmentHintsFromBody ($Node.catch_block) $GlobalDecls $Seen
            Apply-WasmAstGlobalAssignmentHintsFromBody ($Node.finally_block) $GlobalDecls $Seen
        }
        default { }
    }
}

function Test-WasmAstEffectfulExpr {
    param($Node)

    if ($null -eq $Node) { return $false }
    switch ([string]$Node.node) {
        { $_ -in @("CALL", "METHOD_CALL", "SUPER_CALL", "NEW_EXPR") } { return $true }
        "DOT_ACCESS" { return (Test-WasmAstEffectfulExpr ($Node.obj)) }
        "INDEX" {
            return ((Test-WasmAstEffectfulExpr ($Node.obj)) -or
                (Test-WasmAstEffectfulExpr ($Node.key)))
        }
        "BIN_OP" {
            return ((Test-WasmAstEffectfulExpr ($Node.left)) -or
                (Test-WasmAstEffectfulExpr ($Node.right)))
        }
        "UNARY_OP" { return (Test-WasmAstEffectfulExpr ($Node.operand)) }
        "TERNARY" {
            return ((Test-WasmAstEffectfulExpr ($Node.cond)) -or
                (Test-WasmAstEffectfulExpr ($Node.then)) -or
                (Test-WasmAstEffectfulExpr ($Node.else)))
        }
        "ARRAY_LIT" {
            foreach ($item in @(As-WasmAstArray ($Node.elements))) {
                if (Test-WasmAstEffectfulExpr $item) { return $true }
            }
            return $false
        }
        "DICT_LIT" {
            foreach ($entry in @(As-WasmAstArray ($Node.entries))) {
                if (Test-WasmAstEffectfulExpr ($entry.value)) { return $true }
            }
            return $false
        }
        "STR_INTERP" {
            foreach ($part in @(As-WasmAstArray ($Node.parts))) {
                if (Test-WasmAstEffectfulExpr $part) { return $true }
            }
            return $false
        }
        default { return $false }
    }
}

function Convert-WasmAstNilableStringExpr {
    param($Node)

    $code = New-Object System.Collections.Generic.List[string]
    Add-Code $code @(Convert-WasmAstExpr $Node) ""
    $code.Add("local.set `$__sura_wasm_value_tmp")
    $code.Add("local.get `$__sura_wasm_value_tmp")
    $code.Add("if (result i32)")
    $code.Add("local.get `$__sura_wasm_value_tmp")
    $code.Add("else")
    Add-Code $code @(New-WasmStringLiteralExprCode -Literal '"nil"') ""
    $code.Add("end")
    return @($code.ToArray())
}

function Convert-WasmAstStringExpr {
    param($Node)

    if ($null -eq $Node) { return @(New-WasmStringLiteralExprCode -Literal '"nil"') }
    if ([string]$Node.node -eq "BIN_OP" -and [string]$Node.op -eq "??") {
        return @(Convert-WasmAstValueExpr $Node) + @("call `$__sura_value_to_string")
    }
    if ((Test-WasmAstRuntimeValueIndexCandidate $Node) -or (Test-WasmAstRuntimeValueDotCandidate $Node)) {
        return @(Convert-WasmAstValueExpr $Node) + @("call `$__sura_value_to_string")
    }
    $knownType = Get-WasmAstKnownValueType $Node
    if ([string]::IsNullOrWhiteSpace($knownType)) {
        $knownType = Get-WasmAstStaticValueType $Node
    }
    if (Test-WasmAstStringIndexExpr $Node) {
        return @(Convert-WasmAstNilableStringExpr $Node)
    }
    if ($knownType -eq "string" -and [string]$Node.node -ne "BIN_OP") {
        return @(Convert-WasmAstExpr $Node)
    }
    if ($knownType -eq "value") {
        return @(Convert-WasmAstValueExpr $Node) + @("call `$__sura_value_to_string")
    }
    if ($knownType -eq "bool") {
        return @(
            @(Convert-WasmAstExpr $Node) +
            @("if (result i32)") +
            @(New-WasmStringLiteralExprCode -Literal '"true"') +
            @("else") +
            @(New-WasmStringLiteralExprCode -Literal '"false"') +
            @("end")
        )
    }
    if ($knownType -eq "nil") {
        if (Test-WasmAstEffectfulExpr $Node) {
            return @(Convert-WasmAstExpr $Node) + @("drop") + @(New-WasmStringLiteralExprCode -Literal '"nil"')
        }
        return @(New-WasmStringLiteralExprCode -Literal '"nil"')
    }
    if ($knownType -in @("array", "dict", "function")) {
        return @(Convert-WasmAstToStringExpr $Node)
    }
    switch ([string]$Node.node) {
        "BIN_OP" {
            if ([string]$Node.op -eq "+" -and
                ((Test-WasmAstStringExprCandidate ($Node.left)) -or (Test-WasmAstStringExprCandidate ($Node.right)))) {
                return @(Convert-WasmAstStringExpr ($Node.left)) + @(Convert-WasmAstStringExpr ($Node.right)) + @("call `$__sura_string_concat")
            }
            return @(Convert-WasmAstExpr $Node) + @("call `$__sura_i32_to_string")
        }
        "TERNARY" {
            if ((Test-WasmAstStringConvertibleExprCandidate ($Node.then)) -and
                (Test-WasmAstStringConvertibleExprCandidate ($Node.else))) {
                $condCode = @(Convert-WasmAstConditionExpr ($Node.cond))
                $thenCode = @(Convert-WasmAstStringExpr ($Node.then))
                $elseCode = @(Convert-WasmAstStringExpr ($Node.else))
                return @(
                    $condCode +
                    @("if (result i32)") +
                    $thenCode +
                    @("else") +
                    $elseCode +
                    @("end")
                )
            }
            return @(Convert-WasmAstExpr $Node) + @("call `$__sura_i32_to_string")
        }
        "STR_LIT" {
            return @(Convert-WasmAstExpr $Node)
        }
        "STR_INTERP" {
            return @(Convert-WasmAstExpr $Node)
        }
        "NIL_LIT" {
            return @(New-WasmStringLiteralExprCode -Literal '"nil"')
        }
        "BOOL_LIT" {
            if ([bool]$Node.value) { return @(New-WasmStringLiteralExprCode -Literal '"true"') }
            return @(New-WasmStringLiteralExprCode -Literal '"false"')
        }
        default {
            return @(Convert-WasmAstExpr $Node) + @("call `$__sura_i32_to_string")
        }
    }
}

function Convert-WasmAstValueExprForStringComparison {
    param($Node)

    if ((Test-WasmAstRuntimeValueIndexCandidate $Node) -or
        (Test-WasmAstRuntimeValueDotCandidate $Node)) {
        # Exact element/key hints may prove that the selected Value is a
        # string, but a tagged receiver still has to be read through the Value
        # ABI before content-aware equality can compare it.
        return @(Convert-WasmAstValueExpr $Node)
    }
    if (Test-WasmAstStringIndexExpr $Node) {
        return @(Convert-WasmAstExpr $Node) + @("call `$__sura_value_string_or_nil")
    }
    if ((Test-WasmAstStringExprCandidate $Node) -or (Test-WasmAstKnownStringValueExprCandidate $Node)) {
        return @(Convert-WasmAstExpr $Node) + @("call `$__sura_value_string")
    }
    return @(Convert-WasmAstValueExpr $Node)
}

function Test-WasmAstValueEqualityCandidate {
    param($Left, $Right)

    foreach ($candidate in @($Left, $Right)) {
        if ($null -ne $candidate -and [string]$candidate.node -eq "CALL" -and
            [string]$candidate.name -in @("to_float", "float")) {
            # to_float always returns a tagged numeric Value.  Keep equality on
            # the Value ABI even when the other operand is an integral literal;
            # comparing the returned handle directly with that literal is wrong.
            return $true
        }
    }
    if ((Test-WasmAstValueExprCandidate $Left) -or (Test-WasmAstValueExprCandidate $Right)) {
        return $true
    }
    return (((Test-WasmAstStringExprCandidate $Left) -or (Test-WasmAstStringExprCandidate $Right)) -and
        ((Test-WasmAstKnownStringValueExprCandidate $Left) -or (Test-WasmAstKnownStringValueExprCandidate $Right)))
}

function Convert-WasmAstValueEqualityExpr {
    param($Left, $Right)

    if (((Test-WasmAstStringExprCandidate $Left) -or (Test-WasmAstStringExprCandidate $Right)) -and
        ((Test-WasmAstKnownStringValueExprCandidate $Left) -or (Test-WasmAstKnownStringValueExprCandidate $Right))) {
        return @(Convert-WasmAstValueExprForStringComparison $Left) + @(Convert-WasmAstValueExprForStringComparison $Right) + @("call `$__sura_value_eq")
    }
    return @(Convert-WasmAstValueExpr $Left) + @(Convert-WasmAstValueExpr $Right) + @("call `$__sura_value_eq")
}

function Get-WasmAstRuntimeValueReceiverType {
    param($Node)

    $typeName = Get-WasmAstStaticValueType $Node
    if ([string]::IsNullOrWhiteSpace($typeName)) { $typeName = Get-WasmAstKnownValueType $Node }
    return [string]$typeName
}

function Get-WasmAstDictLiteralShapeSignature {
    param($Node)

    if ($null -eq $Node -or [string]$Node.node -ne "DICT_LIT") { return "" }
    $parts = New-Object System.Collections.Generic.List[string]
    foreach ($entry in @(As-WasmAstArray ($Node.entries))) {
        $key = [string]$entry.key
        if ([string]::IsNullOrWhiteSpace($key)) { return "" }
        $typeName = Get-WasmAstStaticValueType ($entry.value)
        if ([string]::IsNullOrWhiteSpace($typeName)) { $typeName = Get-WasmAstKnownValueType ($entry.value) }
        if ([string]::IsNullOrWhiteSpace($typeName)) { return "" }
        $parts.Add("$key`:$typeName") | Out-Null
    }
    return (($parts.ToArray() | Sort-Object) -join "|")
}

function Get-WasmAstArrayLiteralShapeSignature {
    param($Node)

    if ($null -eq $Node -or [string]$Node.node -ne "ARRAY_LIT") { return "" }
    $parts = New-Object System.Collections.Generic.List[string]
    $index = 0
    foreach ($item in @(As-WasmAstArray ($Node.elements))) {
        $typeName = Get-WasmAstStaticValueType $item
        if ([string]::IsNullOrWhiteSpace($typeName)) { $typeName = Get-WasmAstKnownValueType $item }
        if ([string]::IsNullOrWhiteSpace($typeName)) { return "" }
        $parts.Add("$index`:$typeName") | Out-Null
        $index++
    }
    return ($parts.ToArray() -join "|")
}

function Test-WasmAstRuntimeValueReceiverCandidate {
    param($Node, [string[]]$AllowedTypes)

    if ($null -eq $Node) { return $false }
    if ([string]$Node.node -eq "TERNARY") {
        $thenType = Get-WasmAstRuntimeValueReceiverType ($Node.then)
        $elseType = Get-WasmAstRuntimeValueReceiverType ($Node.else)
        if ($thenType -eq "dict" -and $elseType -eq "dict" -and "dict" -in $AllowedTypes) {
            $thenShape = Get-WasmAstDictLiteralShapeSignature ($Node.then)
            $elseShape = Get-WasmAstDictLiteralShapeSignature ($Node.else)
            if (-not [string]::IsNullOrWhiteSpace($thenShape) -and
                -not [string]::IsNullOrWhiteSpace($elseShape) -and
                $thenShape -ne $elseShape) {
                return $true
            }
        }
        if ($thenType -eq "array" -and $elseType -eq "array" -and "array" -in $AllowedTypes) {
            $thenShape = Get-WasmAstArrayLiteralShapeSignature ($Node.then)
            $elseShape = Get-WasmAstArrayLiteralShapeSignature ($Node.else)
            if (-not [string]::IsNullOrWhiteSpace($thenShape) -and
                -not [string]::IsNullOrWhiteSpace($elseShape) -and
                $thenShape -ne $elseShape) {
                return $true
            }
        }
        return ($thenType -in $AllowedTypes -and $elseType -in $AllowedTypes -and $thenType -ne $elseType)
    }
    if ([string]$Node.node -eq "BIN_OP" -and [string]$Node.op -eq "??") {
        $leftType = Get-WasmAstRuntimeValueReceiverType ($Node.left)
        $rightType = Get-WasmAstRuntimeValueReceiverType ($Node.right)
        if ($leftType -eq "nil" -and $rightType -in $AllowedTypes) {
            return $false
        }
        if ($leftType -eq "dict" -and $rightType -eq "dict" -and "dict" -in $AllowedTypes) {
            $leftShape = Get-WasmAstDictLiteralShapeSignature ($Node.left)
            $rightShape = Get-WasmAstDictLiteralShapeSignature ($Node.right)
            if (-not [string]::IsNullOrWhiteSpace($leftShape) -and
                -not [string]::IsNullOrWhiteSpace($rightShape) -and
                $leftShape -ne $rightShape) {
                return $true
            }
        }
        if ($leftType -eq "array" -and $rightType -eq "array" -and "array" -in $AllowedTypes) {
            $leftShape = Get-WasmAstArrayLiteralShapeSignature ($Node.left)
            $rightShape = Get-WasmAstArrayLiteralShapeSignature ($Node.right)
            if (-not [string]::IsNullOrWhiteSpace($leftShape) -and
                -not [string]::IsNullOrWhiteSpace($rightShape) -and
                $leftShape -ne $rightShape) {
                return $true
            }
        }
        return ($leftType -in $AllowedTypes -and $rightType -in $AllowedTypes -and $leftType -ne $rightType)
    }
    return $false
}

function Test-WasmAstRuntimeValueIndexCandidate {
    param($Node)

    if ($null -eq $Node -or [string]$Node.node -ne "INDEX" -or $null -eq $Node.obj -or $null -eq $Node.key) {
        return $false
    }
    $objType = Get-WasmAstKnownValueType ($Node.obj)
    if ([string]::IsNullOrWhiteSpace($objType)) { $objType = Get-WasmAstStaticValueType ($Node.obj) }
    if ($objType -eq "value") { return $true }
    if ((Test-WasmAstRuntimeValueIndexCandidate ($Node.obj)) -or (Test-WasmAstRuntimeValueDotCandidate ($Node.obj))) {
        return $true
    }
    return (Test-WasmAstRuntimeValueReceiverCandidate ($Node.obj) @("string", "array", "dict", "nil"))
}

function Test-WasmAstRuntimeValueDotCandidate {
    param($Node)

    if ($null -eq $Node -or [string]$Node.node -ne "DOT_ACCESS" -or $null -eq $Node.obj) {
        return $false
    }
    $objType = Get-WasmAstKnownValueType ($Node.obj)
    if ([string]::IsNullOrWhiteSpace($objType)) { $objType = Get-WasmAstStaticValueType ($Node.obj) }
    if ($objType -eq "value") { return $true }
    if ((Test-WasmAstRuntimeValueIndexCandidate ($Node.obj)) -or (Test-WasmAstRuntimeValueDotCandidate ($Node.obj))) {
        return $true
    }
    return (Test-WasmAstRuntimeValueReceiverCandidate ($Node.obj) @("array", "dict", "nil"))
}

function Test-WasmAstIntegerOnlyOperandRequiresValue {
    param($Node)

    if ($null -eq $Node) { return $true }
    $typeName = Get-WasmAstKnownValueType $Node
    if ([string]::IsNullOrWhiteSpace($typeName)) {
        $typeName = Get-WasmAstStaticValueType $Node
    }
    if ($typeName -ne "num") { return $true }
    return (Test-WasmAstFractionalStorageExpr $Node)
}

function Test-WasmAstBitwiseValueExprCandidate {
    param($Node)

    if ($null -eq $Node) { return $false }
    if ([string]$Node.node -eq "BIN_OP") {
        $op = [string]$Node.op
        if ($op -in @("<<", ">>")) {
            # Shifts use the VM's signed 64-bit/safe-integer contract. Even
            # small i32 operands can produce a valid result outside i32.
            return $true
        }
        if ($op -in @("&", "|", "^")) {
            return ((Test-WasmAstIntegerOnlyOperandRequiresValue ($Node.left)) -or
                (Test-WasmAstIntegerOnlyOperandRequiresValue ($Node.right)))
        }
    }
    if ([string]$Node.node -eq "UNARY_OP" -and [string]$Node.op -eq "~") {
        return (Test-WasmAstIntegerOnlyOperandRequiresValue ($Node.operand))
    }
    return $false
}

function Get-WasmAstDirectFunctionValueCallLiftName {
    param($Node)

    if ($null -eq $Node -or [string]$Node.node -ne "CALL") { return "" }
    $name = [string]$Node.name
    if ([string]::IsNullOrWhiteSpace($name) -or $script:wasmAstFunctionDefs.ContainsKey($name)) {
        return ""
    }
    foreach ($hints in @($script:wasmCurrentLocalFunctionLiftHints, $script:wasmGlobalFunctionLiftHints)) {
        if ($hints.ContainsKey($name)) {
            $liftName = [string]$hints[$name]
            if (-not [string]::IsNullOrWhiteSpace($liftName) -and
                $script:wasmAstFunctionDefs.ContainsKey($liftName)) {
                return $liftName
            }
        }
    }
    return ""
}

function Get-WasmAstPromotedLiftCallRawUnwrap {
    param([string]$TargetName)

    # A promoted function expression always returns through the tagged-Value
    # ABI (the dispatcher requires it). When a direct call to it is emitted in
    # the raw-i32 expression context, the tagged result must be unwrapped to
    # the raw kind the surrounding code assumes, or a string-typed capture
    # flows a Value handle into raw string concatenation and traps.
    if ([string]::IsNullOrWhiteSpace($TargetName) -or
        -not $TargetName.StartsWith("__sura_func_expr_") -or
        -not $script:wasmAstFunctionDefs.ContainsKey($TargetName)) {
        return ""
    }
    $promoted = $script:wasmAstFunctionDefs[$TargetName].Node
    if ($null -eq $promoted -or [string]$promoted.node -ne "FUNC_EXPR" -or
        $null -eq $promoted.body -or [string]$promoted.body.node -ne "SuraBlock") {
        return ""
    }
    $returnValue = $null
    foreach ($stmt in @(As-WasmAstArray ($promoted.body.body))) {
        if ($null -ne $stmt -and [string]$stmt.node -eq "RETURN" -and $null -ne $stmt.value) {
            $returnValue = $stmt.value
        }
    }
    if ($null -eq $returnValue) { return "" }
    switch (Get-WasmAstStaticValueType $returnValue) {
        # Promoted bodies are pinned to the tagged-Value return ABI at
        # promotion time, so every raw kind unwraps here at the boundary.
        # value_to_string is the identity for string-tagged Values.
        "string" { return "call `$__sura_value_to_string" }
        "bool"   { return "call `$__sura_value_is_truthy" }
        # Exact for the i32-tagged numbers these specialized captures produce.
        "num"    { return "call `$__sura_value_payload" }
        # The payload of an array/dict Value is the raw container pointer.
        "array"  { return "call `$__sura_value_payload" }
        "dict"   { return "call `$__sura_value_payload" }
        default  { return "" }
    }
}

function Convert-WasmAstFunctionValueCalleeIdExpr {
    param([string]$Name)

    $code = @(Convert-WasmAstNameLoad $Name)
    $storageType = ""
    if ($script:wasmCurrentLocalValueTypeHints.ContainsKey($Name)) {
        $storageType = [string]$script:wasmCurrentLocalValueTypeHints[$Name]
    } elseif ($script:wasmCurrentFunctionParamTypeHints.ContainsKey($Name)) {
        $storageType = [string]$script:wasmCurrentFunctionParamTypeHints[$Name]
    } elseif (-not $script:wasmConflictedValueTypeHints.ContainsKey($Name) -and
        $script:wasmValueTypeHints.ContainsKey($Name)) {
        $storageType = [string]$script:wasmValueTypeHints[$Name]
    }
    if ($storageType -eq "value") {
        return @($code + @("call `$__sura_value_require_function_id"))
    }
    return $code
}

function Test-WasmAstIndirectFunctionValueCall {
    param($Node)

    if ($null -eq $Node -or [string]$Node.node -ne "CALL") { return $false }
    $name = [string]$Node.name
    if ([string]::IsNullOrWhiteSpace($name) -or $script:wasmAstFunctionDefs.ContainsKey($name)) {
        return $false
    }
    if ($script:wasmCurrentLocalFunctionLiftHints.ContainsKey($name) -and
        -not [string]::IsNullOrWhiteSpace([string]$script:wasmCurrentLocalFunctionLiftHints[$name])) {
        return $false
    }
    return (($script:wasmCurrentLocalFunctionLiftCandidates.ContainsKey($name) -and
             @($script:wasmCurrentLocalFunctionLiftCandidates[$name]).Count -gt 0) -or
        ($script:wasmCurrentFunctionParamTypeHints.ContainsKey($name) -and [string]$script:wasmCurrentFunctionParamTypeHints[$name] -eq "function") -or
        ($script:wasmCurrentLocalValueTypeHints.ContainsKey($name) -and [string]$script:wasmCurrentLocalValueTypeHints[$name] -eq "function") -or
        (-not $script:wasmConflictedValueTypeHints.ContainsKey($name) -and
         $script:wasmValueTypeHints.ContainsKey($name) -and
         [string]$script:wasmValueTypeHints[$name] -eq "function"))
}

function Test-WasmAstValuePreservingExprCandidate {
    param($Node, [hashtable]$Seen = @{})

    if ($null -eq $Node) { return $false }
    if (Test-WasmAstBitwiseValueExprCandidate $Node) {
        return $true
    }
    $valueMathName = Get-WasmAstValueMathIntrinsicName $Node
    if (-not [string]::IsNullOrWhiteSpace($valueMathName) -and
        (Test-WasmAstValueMathIntrinsicCandidate -Name $valueMathName -InputArgs ([object[]]@(Get-WasmAstValueMathIntrinsicArgs $Node)))) {
        return $true
    }
    if (Test-WasmAstFractionalNumericValueExpr $Node) {
        # Raw WASM numeric slots are i32-backed.  A fractional Sura number has
        # to enter the tagged Value ABI before it is assigned, returned, passed
        # to a function, or stored in a collection; otherwise Convert-WasmAstExpr
        # would silently truncate it at the raw i32 boundary.
        return $true
    }
    if (Test-WasmAstOptionalAccessExpr $Node) {
        return $true
    }
    if ($null -ne (Get-WasmAstDictGetPathArgs $Node)) {
        return $true
    }
    if ([string]$Node.node -eq "CALL" -and [string]$Node.name -in @("to_float", "float")) {
        $conversionArgs = @(As-WasmAstArray ($Node.args))
        if ($conversionArgs.Count -eq 1) {
            return $true
        }
    }
    if (Test-WasmAstIndirectFunctionValueCall $Node) {
        # The indirect dispatcher normalizes every reachable function result to
        # a tagged Value, regardless of the selected function's raw return type.
        return $true
    }
    $directFunctionValueLift = Get-WasmAstDirectFunctionValueCallLiftName $Node
    if (-not [string]::IsNullOrWhiteSpace($directFunctionValueLift) -and
        (Test-WasmAstFunctionReturnValuePreserving $directFunctionValueLift $Seen)) {
        return $true
    }
    if ([string]$Node.node -eq "CALL" -and
        (Test-WasmAstFunctionReturnValuePreserving ([string]$Node.name) $Seen)) {
        return $true
    }
    if ([string]$Node.node -eq "BIN_OP" -and [string]$Node.op -in @("+", "-", "*", "/", "%")) {
        if ([string]$Node.op -eq "/") {
            # Sura has one numeric type and division is real division even when
            # both operands happen to fit in i32. Keep `/` in the tagged f64
            # path so 3 / 2 is 1.5 instead of being truncated to 1.
            return $true
        }
        # Sura string concatenation coerces the other operand and produces a
        # raw string handle even when that operand is a runtime Value. Do not
        # store the result as a tagged Value and later reinterpret it as a
        # string pointer.
        if ([string]$Node.op -eq "+" -and
            ((Test-WasmAstStringExprCandidate ($Node.left)) -or
            (Test-WasmAstStringExprCandidate ($Node.right)))) {
            return $false
        }
        if ((Test-WasmAstDynamicNumericValueExpr ($Node.left) $Seen) -or
            (Test-WasmAstDynamicNumericValueExpr ($Node.right) $Seen)) {
            return $true
        }
    }
    if ([string]$Node.node -eq "BIN_OP" -and [string]$Node.op -eq "in") {
        return $true
    }
    if ([string]$Node.node -eq "BIN_OP" -and [string]$Node.op -eq "??") {
        if ((Test-WasmAstValuePreservingExprCandidate ($Node.left) $Seen) -or
            (Test-WasmAstValuePreservingExprCandidate ($Node.right) $Seen)) {
            return $true
        }
    }
    if ([string]$Node.node -eq "UNARY_OP" -and [string]$Node.op -eq "-") {
        return (Test-WasmAstValuePreservingExprCandidate ($Node.operand) $Seen)
    }
    if ([string]$Node.node -eq "TERNARY") {
        if ((Test-WasmAstValuePreservingExprCandidate ($Node.then) $Seen) -or
            (Test-WasmAstValuePreservingExprCandidate ($Node.else) $Seen)) {
            return $true
        }
    }
    if ([string]$Node.node -eq "ARRAY_LIT") {
        foreach ($element in @(As-WasmAstArray ($Node.elements))) {
            if (Test-WasmAstFractionalStorageExpr $element $Seen) { return $true }
        }
    }
    if ([string]$Node.node -eq "DICT_LIT") {
        foreach ($entry in @(As-WasmAstArray ($Node.entries))) {
            if (Test-WasmAstFractionalStorageExpr ($entry.value) $Seen) { return $true }
        }
    }
    if ((Test-WasmAstRuntimeValueIndexCandidate $Node) -or
        (Test-WasmAstRuntimeValueDotCandidate $Node) -or
        (Test-WasmAstRuntimeValueReceiverCandidate $Node @("string", "array", "dict", "nil"))) {
        return $true
    }

    if ([string]$Node.node -eq "IDENT") {
        return ((Get-WasmAstKnownValueType $Node) -eq "value")
    }

    return $false
}

function Convert-WasmAstJsonNumberToDouble {
    param($Value)

    if ($Value -is [decimal]) {
        # Windows PowerShell's direct Decimal -> Double conversion can select
        # an adjacent IEEE-754 value for long JSON number literals. Parsing the
        # invariant decimal text follows the same nearest-double rule as the VM.
        $text = ([decimal]$Value).ToString([System.Globalization.CultureInfo]::InvariantCulture)
        return [double]::Parse($text, [System.Globalization.CultureInfo]::InvariantCulture)
    }
    return [double]$Value
}

function Test-WasmAstFractionalNumericValueExpr {
    param($Node)

    if ($null -eq $Node) { return $false }
    $value = $null
    if ([string]$Node.node -eq "NUM_LIT") {
        $value = Convert-WasmAstJsonNumberToDouble $Node.value
    } elseif ([string]$Node.node -eq "UNARY_OP" -and [string]$Node.op -eq "-" -and
        $null -ne $Node.operand -and [string]$Node.operand.node -eq "NUM_LIT") {
        $value = -1.0 * (Convert-WasmAstJsonNumberToDouble $Node.operand.value)
    } elseif ([string]$Node.node -eq "DOT_ACCESS" -and [string]$Node.prop -eq "pi" -and
        $null -ne $Node.obj -and [string]$Node.obj.node -eq "IDENT" -and
        [string]$Node.obj.name -eq "math") {
        $value = [Math]::PI
    }
    if ($null -eq $value) { return $false }
    return (-not [double]::IsNaN($value) -and
        -not [double]::IsInfinity($value) -and
        ($value -ne [Math]::Truncate($value) -or
            $value -lt [int]::MinValue -or $value -gt [int]::MaxValue))
}

function Test-WasmAstFractionalStorageExpr {
    param($Node, [hashtable]$Seen = @{})

    if ($null -eq $Node) { return $false }
    if (Test-WasmAstFractionalNumericValueExpr $Node) { return $true }
    $valueMathName = Get-WasmAstValueMathIntrinsicName $Node
    if (-not [string]::IsNullOrWhiteSpace($valueMathName) -and
        (Test-WasmAstValueMathIntrinsicCandidate -Name $valueMathName -InputArgs ([object[]]@(Get-WasmAstValueMathIntrinsicArgs $Node)))) {
        return $true
    }
    switch ([string]$Node.node) {
        "UNARY_OP" {
            if ([string]$Node.op -eq "-") {
                return (Test-WasmAstFractionalStorageExpr ($Node.operand) $Seen)
            }
        }
        "BIN_OP" {
            if ([string]$Node.op -in @("+", "-", "*", "/", "%", "??")) {
                if ([string]$Node.op -eq "/") { return $true }
                return ((Test-WasmAstFractionalStorageExpr ($Node.left) $Seen) -or
                    (Test-WasmAstFractionalStorageExpr ($Node.right) $Seen))
            }
        }
        "TERNARY" {
            return ((Test-WasmAstFractionalStorageExpr ($Node.then) $Seen) -or
                (Test-WasmAstFractionalStorageExpr ($Node.else) $Seen))
        }
        "ARRAY_LIT" {
            foreach ($element in @(As-WasmAstArray ($Node.elements))) {
                if (Test-WasmAstFractionalStorageExpr $element $Seen) { return $true }
            }
        }
        "DICT_LIT" {
            foreach ($entry in @(As-WasmAstArray ($Node.entries))) {
                if (Test-WasmAstFractionalStorageExpr ($entry.value) $Seen) { return $true }
            }
        }
        "CALL" {
            $name = [string]$Node.name
            $args = @(As-WasmAstArray ($Node.args))
            if ($name -in @("to_float", "float") -and $args.Count -eq 1) {
                return $true
            }
            if (-not [string]::IsNullOrWhiteSpace($name) -and
                -not $Seen.ContainsKey("fractional-call:$name") -and
                $script:wasmAstFunctionDefs.ContainsKey($name)) {
                $nextSeen = [hashtable]$Seen.Clone()
                $nextSeen["fractional-call:$name"] = $true
                $fn = $script:wasmAstFunctionDefs[$name]
                if ($null -ne $fn.Node -and
                    (Test-WasmAstFractionalStorageBody ($fn.Node.body) $nextSeen)) {
                    return $true
                }
            }
        }
    }
    return $false
}

function Test-WasmAstFractionalStorageBody {
    param($Body, [hashtable]$Seen = @{})

    if ($null -eq $Body) { return $false }
    foreach ($stmt in @(As-WasmAstArray ($Body.body))) {
        if ($null -eq $stmt) { continue }
        switch ([string]$stmt.node) {
            "RETURN" {
                if (Test-WasmAstFractionalStorageExpr ($stmt.value) $Seen) { return $true }
            }
            "SuraBlock" {
                if (Test-WasmAstFractionalStorageBody $stmt $Seen) { return $true }
            }
            "IF" {
                if ((Test-WasmAstFractionalStorageBody ($stmt.then_block) $Seen) -or
                    (Test-WasmAstFractionalStorageBody ($stmt.else_block) $Seen)) { return $true }
            }
            { $_ -in @("WHILE", "REPEAT", "FOR", "FOREACH") } {
                if (Test-WasmAstFractionalStorageBody ($stmt.body) $Seen) { return $true }
            }
            "MATCH" {
                foreach ($arm in @(As-WasmAstArray ($stmt.arms))) {
                    if (Test-WasmAstFractionalStorageBody ($arm.body) $Seen) { return $true }
                }
            }
            "TRY" {
                foreach ($block in @($stmt.try_block, $stmt.catch_block, $stmt.finally_block)) {
                    if (Test-WasmAstFractionalStorageBody $block $Seen) { return $true }
                }
            }
        }
    }
    return $false
}

function Test-WasmAstDynamicValueExpr {
    param($Node, [hashtable]$Seen = @{})

    if ($null -eq $Node) { return $false }
    if ([string]$Node.node -eq "CALL" -and $script:wasmAstFunctionDefs.ContainsKey([string]$Node.name)) {
        # Preserve the caller's reachability set.  Asking the general static
        # type resolver here would start a fresh return analysis for recursive
        # calls such as fib(), eventually overflowing PowerShell's call depth.
        return (Test-WasmAstFunctionReturnValuePreserving ([string]$Node.name) $Seen)
    }
    $typeName = Get-WasmAstKnownValueType $Node
    if ([string]::IsNullOrWhiteSpace($typeName)) {
        $typeName = Get-WasmAstStaticValueType $Node
    }
    return ($typeName -eq "value" -or (Test-WasmAstValuePreservingExprCandidate $Node $Seen))
}

function Test-WasmAstDynamicNumericValueExpr {
    param($Node, [hashtable]$Seen = @{})

    if ($null -eq $Node) { return $false }
    if (Test-WasmAstDynamicValueExpr $Node $Seen) { return $true }
    if ([string]$Node.node -eq "TERNARY") {
        return ((Test-WasmAstDynamicNumericValueExpr ($Node.then) $Seen) -or
            (Test-WasmAstDynamicNumericValueExpr ($Node.else) $Seen))
    }
    if ([string]$Node.node -eq "BIN_OP" -and [string]$Node.op -eq "??") {
        return ((Test-WasmAstDynamicNumericValueExpr ($Node.left) $Seen) -or
            (Test-WasmAstDynamicNumericValueExpr ($Node.right) $Seen))
    }
    return $false
}

function Get-WasmStringUnaryTransformHelper {
    param([string]$Name)

    switch ($Name) {
        { $_ -in @("upper", "string.upper", "string_upper") } { return "__sura_string_upper" }
        { $_ -in @("lower", "string.lower", "string_lower") } { return "__sura_string_lower" }
        { $_ -in @("trim", "string.trim", "string_trim") } { return "__sura_string_trim" }
        default { return "" }
    }
}

function Get-WasmStringSearchHelper {
    param([string]$Name)

    switch ($Name) {
        { $_ -in @("contains", "string.contains", "string_contains") } { return "__sura_string_contains" }
        { $_ -in @("indexOf", "index_of", "string.indexOf", "string.index_of", "string_indexOf", "string_index_of") } { return "__sura_string_index_of" }
        { $_ -in @("startsWith", "starts_with", "string.startsWith", "string.starts_with", "string_startsWith", "string_starts_with") } { return "__sura_string_starts_with" }
        { $_ -in @("endsWith", "ends_with", "string.endsWith", "string.ends_with", "string_endsWith", "string_ends_with") } { return "__sura_string_ends_with" }
        default { return "" }
    }
}

function Get-WasmStringReplaceHelper {
    param([string]$Name)

    if ($Name -in @("replace", "string.replace", "string_replace")) { return "__sura_string_replace" }
    return ""
}

function Get-WasmStringRepeatHelper {
    param([string]$Name)

    if ($Name -in @("repeat", "string.repeat", "string_repeat")) { return "__sura_string_repeat" }
    return ""
}

function Get-WasmStringPadHelper {
    param([string]$Name)

    switch ($Name) {
        { $_ -in @("pad_left", "string.pad_left", "string_pad_left") } { return "__sura_string_pad_left" }
        { $_ -in @("pad_right", "string.pad_right", "string_pad_right") } { return "__sura_string_pad_right" }
        default { return "" }
    }
}

function Get-WasmStringSliceHelper {
    param([string]$Name)

    switch ($Name) {
        { $_ -in @("substring", "string.substring", "string_substring") } { return "__sura_string_substring" }
        { $_ -in @("slice", "sub", "string.slice", "string.sub", "string_slice", "string_sub") } { return "__sura_string_slice" }
        default { return "" }
    }
}

function Get-WasmStringSplitHelper {
    param([string]$Name)

    if ($Name -in @("split", "string.split", "string_split")) { return "__sura_string_split" }
    return ""
}

function Get-WasmStringLinesHelper {
    param([string]$Name)

    if ($Name -in @("lines", "string.lines", "string_lines")) { return "__sura_string_lines" }
    return ""
}

function Get-WasmStringWordsHelper {
    param([string]$Name)

    if ($Name -in @("words", "string.words", "string_words")) { return "__sura_string_words" }
    return ""
}

function Get-WasmStringChunksHelper {
    param([string]$Name)

    if ($Name -in @("chunks", "string.chunks", "text_chunks", "text_chunk")) { return "__sura_text_chunks" }
    return ""
}

function Get-WasmStringCallReturnTypeName {
    param([string]$Name)

    if (-not [string]::IsNullOrWhiteSpace((Get-WasmStringUnaryTransformHelper $Name))) { return "string" }
    if (-not [string]::IsNullOrWhiteSpace((Get-WasmStringReplaceHelper $Name))) { return "string" }
    if (-not [string]::IsNullOrWhiteSpace((Get-WasmStringRepeatHelper $Name))) { return "string" }
    if (-not [string]::IsNullOrWhiteSpace((Get-WasmStringPadHelper $Name))) { return "string" }
    if (-not [string]::IsNullOrWhiteSpace((Get-WasmStringSliceHelper $Name))) { return "string" }
    if (-not [string]::IsNullOrWhiteSpace((Get-WasmStringSplitHelper $Name))) { return "array" }
    if (-not [string]::IsNullOrWhiteSpace((Get-WasmStringLinesHelper $Name))) { return "array" }
    if (-not [string]::IsNullOrWhiteSpace((Get-WasmStringWordsHelper $Name))) { return "array" }
    if (-not [string]::IsNullOrWhiteSpace((Get-WasmStringChunksHelper $Name))) { return "array" }
    $searchHelper = Get-WasmStringSearchHelper $Name
    if ([string]::IsNullOrWhiteSpace($searchHelper)) { return "" }
    if ($searchHelper -eq "__sura_string_index_of") { return "num" }
    return "bool"
}

function Get-WasmArrayCallReturnTypeName {
    param([string]$Name)

    switch ($Name) {
        { $_ -in @("array.range", "array_range", "array.repeat", "array_repeat", "array.unique", "array_unique", "array.flatten", "array_flatten", "array.clone", "array.copy", "array.concat", "array.chunk", "array.chunks", "array_chunk", "array.zip", "array_zip", "array.slice", "array_slice", "array.reverse", "array_reverse", "array.sort", "array_sort", "set.union", "set_union", "set.intersection", "set_intersection", "set.difference", "set_difference", "set.symmetric_difference", "set.symdiff", "set_symmetric_difference") } { return "array" }
        { $_ -in @("array.clear", "array_clear", "array.insert", "array_insert") } { return "nil" }
        { $_ -in @("array.len", "array.length", "array.size", "array_len", "array_length", "array_size", "array.sum", "array_sum", "array.avg", "array.average", "array_avg", "array_average", "array.min", "array_min", "array.max", "array_max", "array.index_of", "array.indexOf", "array.index", "array_index_of", "array_indexOf", "array_index") } { return "num" }
        { $_ -in @("array.contains", "array.includes", "array_contains", "array_includes") } { return "bool" }
        { $_ -in @("set.is_subset", "set.subset", "set_is_subset", "set.is_superset", "set.superset", "set_is_superset") } { return "bool" }
        default { return "" }
    }
}

function Get-WasmArrayMethodReturnTypeName {
    param([string]$Method)

    switch ($Method) {
        { $_ -in @("len", "length", "size", "sum", "avg", "average", "min", "max", "index_of", "indexOf", "index") } { return "num" }
        { $_ -in @("contains", "includes") } { return "bool" }
        "slice" { return "array" }
        "reverse" { return "array" }
        "sort" { return "array" }
        "unique" { return "array" }
        "flatten" { return "array" }
        "join" { return "string" }
        "clear" { return "nil" }
        "insert" { return "nil" }
        default { return "" }
    }
}

function Get-WasmDictCallReturnTypeName {
    param([string]$Name)

    switch ($Name) {
        { $_ -in @("dict.keys", "dict_keys", "dict.values", "dict_values", "dict.items", "dict_items") } { return "array" }
        { $_ -in @("dict.pick", "dict_pick", "dict.omit", "dict_omit", "dict.merge", "dict_merge") } { return "dict" }
