function Convert-WasmAstValueArrayIntrinsicCall {
    param([string]$Name, [object[]]$InputArgs)

    $argsList = @(As-WasmAstArray $InputArgs)
    if ($argsList.Count -lt 1 -or -not (Test-WasmAstValueArrayIntrinsicReceiverCandidate ($argsList[0]))) {
        return @()
    }
    switch ($Name) {
        { $_ -in @("array.len", "array.length", "array.size", "array_len", "array_length", "array_size") } {
            if ($argsList.Count -eq 1) { return @(Convert-WasmAstValueExpr ($argsList[0])) + @("call `$__sura_value_length") }
        }
        { $_ -in @("array.sum", "array_sum") } {
            if ($argsList.Count -eq 1) { return @(Convert-WasmAstValueExpr ($argsList[0])) + @("call `$__sura_value_array_sum") }
        }
        { $_ -in @("array.avg", "array.average", "array_avg", "array_average") } {
            if ($argsList.Count -eq 1) { return @(Convert-WasmAstValueExpr ($argsList[0])) + @("call `$__sura_value_array_avg") }
        }
        { $_ -in @("array.min", "array_min") } {
            if ($argsList.Count -eq 1) { return @(Convert-WasmAstValueExpr ($argsList[0])) + @("call `$__sura_value_array_min") }
        }
        { $_ -in @("array.max", "array_max") } {
            if ($argsList.Count -eq 1) { return @(Convert-WasmAstValueExpr ($argsList[0])) + @("call `$__sura_value_array_max") }
        }
        { $_ -in @("array.index_of", "array.indexOf", "array.index", "array_index_of", "array_indexOf", "array_index") } {
            if ($argsList.Count -eq 2) { return @(Convert-WasmAstValueExpr ($argsList[0])) + @(Convert-WasmAstValueExpr ($argsList[1])) + @("call `$__sura_value_array_index_of") }
        }
        { $_ -in @("array.contains", "array.includes", "array_contains", "array_includes") } {
            if ($argsList.Count -eq 2) { return @(Convert-WasmAstValueExpr ($argsList[0])) + @(Convert-WasmAstValueExpr ($argsList[1])) + @("call `$__sura_value_array_contains") }
        }
    }
    return @()
}

