function Convert-WasmAstStringIntrinsicCall {
    param([string]$Name, [object[]]$InputArgs)

    $argsList = @(As-WasmAstArray $InputArgs)
    $unaryHelper = Get-WasmStringUnaryTransformHelper $Name
    if (-not [string]::IsNullOrWhiteSpace($unaryHelper) -and $argsList.Count -eq 1 -and
        (Test-WasmAstStringIntrinsicReceiverCandidate ($argsList[0]))) {
        return @(Convert-WasmAstStringExpr ($argsList[0])) + @("call `$$unaryHelper")
    }

    $searchHelper = Get-WasmStringSearchHelper $Name
    if (-not [string]::IsNullOrWhiteSpace($searchHelper) -and $argsList.Count -eq 2 -and
        (Test-WasmAstStringIntrinsicReceiverCandidate ($argsList[0]))) {
        return @(Convert-WasmAstStringExpr ($argsList[0])) + @(Convert-WasmAstStringExpr ($argsList[1])) + @("call `$$searchHelper")
    }

    $replaceHelper = Get-WasmStringReplaceHelper $Name
    if (-not [string]::IsNullOrWhiteSpace($replaceHelper) -and $argsList.Count -eq 3 -and
        (Test-WasmAstStringIntrinsicReceiverCandidate ($argsList[0]))) {
        return @(Convert-WasmAstStringExpr ($argsList[0])) + @(Convert-WasmAstStringExpr ($argsList[1])) + @(Convert-WasmAstStringExpr ($argsList[2])) + @("call `$$replaceHelper")
    }

    $repeatHelper = Get-WasmStringRepeatHelper $Name
    if (-not [string]::IsNullOrWhiteSpace($repeatHelper) -and $argsList.Count -eq 2 -and
        (Test-WasmAstStringIntrinsicReceiverCandidate ($argsList[0]))) {
        return @(Convert-WasmAstStringExpr ($argsList[0])) + @(Convert-WasmAstExpr ($argsList[1])) + @("call `$$repeatHelper")
    }

    $padHelper = Get-WasmStringPadHelper $Name
    if (-not [string]::IsNullOrWhiteSpace($padHelper) -and $argsList.Count -in @(2, 3) -and
        (Test-WasmAstStringIntrinsicReceiverCandidate ($argsList[0]))) {
        $fillCode = if ($argsList.Count -eq 3) { @(Convert-WasmAstStringExpr ($argsList[2])) } else { @(New-WasmStringLiteralExprCode -Literal '" "') }
        return @(Convert-WasmAstStringExpr ($argsList[0])) + @(Convert-WasmAstExpr ($argsList[1])) + $fillCode + @("call `$$padHelper")
    }

    $sliceHelper = Get-WasmStringSliceHelper $Name
    if (-not [string]::IsNullOrWhiteSpace($sliceHelper) -and $argsList.Count -in @(2, 3) -and
        (Test-WasmAstStringIntrinsicReceiverCandidate ($argsList[0]))) {
        $endCode = if ($argsList.Count -eq 3) { @(Convert-WasmAstExpr ($argsList[2])) } else { @("i32.const 2147483647") }
        return @(Convert-WasmAstStringExpr ($argsList[0])) + @(Convert-WasmAstExpr ($argsList[1])) + $endCode + @("call `$$sliceHelper")
    }

    $splitHelper = Get-WasmStringSplitHelper $Name
    if (-not [string]::IsNullOrWhiteSpace($splitHelper) -and $argsList.Count -eq 2 -and
        (Test-WasmAstStringIntrinsicReceiverCandidate ($argsList[0]))) {
        return @(Convert-WasmAstStringExpr ($argsList[0])) + @(Convert-WasmAstStringExpr ($argsList[1])) + @("call `$$splitHelper")
    }

    $linesHelper = Get-WasmStringLinesHelper $Name
    if (-not [string]::IsNullOrWhiteSpace($linesHelper) -and $argsList.Count -eq 1 -and
        (Test-WasmAstStringIntrinsicReceiverCandidate ($argsList[0]))) {
        return @(Convert-WasmAstStringExpr ($argsList[0])) + @("call `$$linesHelper")
    }

    $wordsHelper = Get-WasmStringWordsHelper $Name
    if (-not [string]::IsNullOrWhiteSpace($wordsHelper) -and $argsList.Count -eq 1 -and
        (Test-WasmAstStringIntrinsicReceiverCandidate ($argsList[0]))) {
        return @(Convert-WasmAstStringExpr ($argsList[0])) + @("call `$$wordsHelper")
    }

    $chunksHelper = Get-WasmStringChunksHelper $Name
    if (-not [string]::IsNullOrWhiteSpace($chunksHelper) -and $argsList.Count -in @(1, 2, 3) -and
        (Test-WasmAstStringIntrinsicReceiverCandidate ($argsList[0]))) {
        $maxCode = if ($argsList.Count -ge 2) { @(Convert-WasmAstExpr ($argsList[1])) } else { @("i32.const 800") }
        $overlapCode = if ($argsList.Count -ge 3) { @(Convert-WasmAstExpr ($argsList[2])) } else { @("i32.const 0") }
        return @(Convert-WasmAstStringExpr ($argsList[0])) + $maxCode + $overlapCode + @("call `$$chunksHelper")
    }

    return @()
}

function Convert-WasmAstStringReceiverMethodCall {
    param($Receiver, [string]$Method, [object[]]$InputArgs)

    if (-not (Test-WasmAstStringIntrinsicReceiverCandidate $Receiver)) { return @() }
    return @(Convert-WasmAstStringIntrinsicCall -Name $Method -InputArgs @(@($Receiver) + @(As-WasmAstArray $InputArgs)))
}

function Test-WasmAstStringSplitExpr {
    param($Node)

    if ($null -eq $Node) { return $false }
    if ([string]$Node.node -eq "CALL") {
        $args = @(As-WasmAstArray ($Node.args))
        return (-not [string]::IsNullOrWhiteSpace((Get-WasmStringSplitHelper ([string]$Node.name))) -and
            $args.Count -eq 2) -or
            (-not [string]::IsNullOrWhiteSpace((Get-WasmStringLinesHelper ([string]$Node.name))) -and
            $args.Count -eq 1) -or
            (-not [string]::IsNullOrWhiteSpace((Get-WasmStringWordsHelper ([string]$Node.name))) -and
            $args.Count -eq 1) -or
            (-not [string]::IsNullOrWhiteSpace((Get-WasmStringChunksHelper ([string]$Node.name))) -and
            $args.Count -in @(1, 2, 3))
    }
    if ([string]$Node.node -eq "METHOD_CALL") {
        $args = @(As-WasmAstArray ($Node.args))
        return (-not [string]::IsNullOrWhiteSpace((Get-WasmStringSplitHelper ([string]$Node.method))) -and
            $args.Count -in @(1, 2)) -or
            (-not [string]::IsNullOrWhiteSpace((Get-WasmStringLinesHelper ([string]$Node.method))) -and
            $args.Count -in @(0, 1)) -or
            (-not [string]::IsNullOrWhiteSpace((Get-WasmStringWordsHelper ([string]$Node.method))) -and
            $args.Count -in @(0, 1)) -or
            (-not [string]::IsNullOrWhiteSpace((Get-WasmStringChunksHelper ([string]$Node.method))) -and
            $args.Count -in @(0, 1, 2, 3))
    }
    return $false
}

