        if ([string]::IsNullOrWhiteSpace($receiverType)) { $receiverType = Get-WasmAstStaticValueType ($Node.obj) }
        return ($receiverType -eq "dict")
    }
    return $false
}

function Get-WasmAstStringArrayLiteralValues {
    param($Node)

    if ($null -eq $Node -or [string]$Node.node -ne "ARRAY_LIT") { return @() }
    $values = New-Object System.Collections.Generic.List[string]
    foreach ($element in @(As-WasmAstArray ($Node.elements))) {
        if ($null -eq $element -or [string]$element.node -ne "STR_LIT") { return @() }
        $values.Add([string]$element.value) | Out-Null
    }
    return [string[]]$values.ToArray()
}

function Get-WasmAstDictPickArgs {
    param($Node)

    if ($null -eq $Node) { return $null }
    if ([string]$Node.node -eq "CALL" -and [string]$Node.name -in @("dict.pick", "dict_pick", "dict.omit", "dict_omit")) {
        $args = @(As-WasmAstArray ($Node.args))
        if ($args.Count -eq 2) {
            return [pscustomobject]@{ Source = $args[0]; Keys = $args[1] }
        }
    }
    if ([string]$Node.node -eq "METHOD_CALL" -and
        $null -ne $Node.obj -and [string]$Node.obj.node -eq "IDENT" -and
        [string]$Node.obj.name -eq "dict" -and [string]$Node.method -in @("pick", "omit")) {
        $args = @(As-WasmAstArray ($Node.args))
        if ($args.Count -eq 2) {
            return [pscustomobject]@{ Source = $args[0]; Keys = $args[1] }
        }
    }
    if ([string]$Node.node -eq "METHOD_CALL" -and [string]$Node.method -in @("pick", "omit")) {
        $args = @(As-WasmAstArray ($Node.args))
        if ($args.Count -eq 1) {
            $receiverType = Get-WasmAstKnownValueType ($Node.obj)
            if ([string]::IsNullOrWhiteSpace($receiverType)) { $receiverType = Get-WasmAstStaticValueType ($Node.obj) }
            if ($receiverType -eq "dict") {
                return [pscustomobject]@{ Source = $Node.obj; Keys = $args[0] }
            }
        }
    }
    return $null
}

function Test-WasmAstDictOmitExpr {
    param($Node)

    if ($null -eq $Node) { return $false }
    if ([string]$Node.node -eq "CALL" -and [string]$Node.name -in @("dict.omit", "dict_omit")) { return $true }
    return ([string]$Node.node -eq "METHOD_CALL" -and [string]$Node.method -eq "omit")
}

function Get-WasmAstDictMergeArgExprs {
    param($Node)

    if ($null -eq $Node) { return @() }
    if ([string]$Node.node -eq "CALL" -and [string]$Node.name -in @("dict.merge", "dict_merge")) {
        return @(As-WasmAstArray ($Node.args))
    }
    if ([string]$Node.node -eq "METHOD_CALL" -and
        $null -ne $Node.obj -and [string]$Node.obj.node -eq "IDENT" -and
        [string]$Node.obj.name -eq "dict" -and [string]$Node.method -eq "merge") {
        return @(As-WasmAstArray ($Node.args))
    }
    if ([string]$Node.node -eq "METHOD_CALL" -and [string]$Node.method -eq "merge") {
        $receiverType = Get-WasmAstKnownValueType ($Node.obj)
        if ([string]::IsNullOrWhiteSpace($receiverType)) { $receiverType = Get-WasmAstStaticValueType ($Node.obj) }
        if ($receiverType -eq "dict") {
            return @(@($Node.obj) + @(As-WasmAstArray ($Node.args)))
        }
    }
    return @()
}

function Get-WasmAstDictMergeOrderedEntryTypes {
    param($Node)

    $argExprs = @(Get-WasmAstDictMergeArgExprs $Node)
    if ($argExprs.Count -eq 0) { return @() }

    $merged = New-Object System.Collections.Generic.List[object]
    $indexByKey = @{}
    foreach ($argExpr in $argExprs) {
        $entries = @(Get-WasmAstOrderedDictEntryTypes $argExpr)
        if ($entries.Count -eq 0) { return @() }
        foreach ($entry in $entries) {
            $key = [string]$entry.Key
            $typeName = [string]$entry.Type
            if ([string]::IsNullOrWhiteSpace($key) -or [string]::IsNullOrWhiteSpace($typeName)) { return @() }
            if ($indexByKey.ContainsKey($key)) {
                $idx = [int]$indexByKey[$key]
                $merged[$idx] = New-WasmAstOrderedDictEntryType $key $typeName
            } else {
                $indexByKey[$key] = $merged.Count
                $merged.Add((New-WasmAstOrderedDictEntryType $key $typeName)) | Out-Null
            }
        }
    }
    return @($merged.ToArray())
}

function Get-WasmAstDictGetPathArgs {
    param($Node)

    if ($null -eq $Node) { return $null }
    if ([string]$Node.node -eq "CALL" -and [string]$Node.name -in @("dict.get_path", "dict_get_path", "json.path", "json.get_path", "json_path")) {
        $args = @(As-WasmAstArray ($Node.args))
        if ($args.Count -eq 2 -and $null -ne $args[1] -and [string]$args[1].node -eq "STR_LIT") {
            return [pscustomobject]@{ Source = $args[0]; Path = [string]$args[1].value }
        }
    }
    if ([string]$Node.node -eq "METHOD_CALL" -and
        $null -ne $Node.obj -and [string]$Node.obj.node -eq "IDENT" -and
        [string]$Node.obj.name -in @("dict", "json") -and [string]$Node.method -in @("get_path", "path")) {
        $args = @(As-WasmAstArray ($Node.args))
        if ($args.Count -eq 2 -and $null -ne $args[1] -and [string]$args[1].node -eq "STR_LIT") {
            return [pscustomobject]@{ Source = $args[0]; Path = [string]$args[1].value }
        }
    }
    if ([string]$Node.node -eq "METHOD_CALL" -and [string]$Node.method -eq "get_path") {
        $args = @(As-WasmAstArray ($Node.args))
        if ($args.Count -eq 1 -and $null -ne $args[0] -and [string]$args[0].node -eq "STR_LIT") {
            $receiverType = Get-WasmAstKnownValueType ($Node.obj)
            if ([string]::IsNullOrWhiteSpace($receiverType)) { $receiverType = Get-WasmAstStaticValueType ($Node.obj) }
            if ($receiverType -eq "dict") {
                return [pscustomobject]@{ Source = $Node.obj; Path = [string]$args[0].value }
            }
        }
    }
    return $null
}

