function Test-WasmAstJsonHasPathExpr {
    param($Node)

    return ($null -ne (Get-WasmAstJsonHasPathArgs $Node))
}

function Get-WasmAstDictPathSegments {
    param([string]$Path)

    if ([string]::IsNullOrWhiteSpace($Path)) { return @() }
    $segments = New-Object System.Collections.Generic.List[string]
    foreach ($part in ($Path -split '\.')) {
        $segment = [string]$part
        if ([string]::IsNullOrWhiteSpace($segment)) { return @() }
        $segments.Add($segment) | Out-Null
    }
    return [string[]]$segments.ToArray()
}

function Convert-WasmAstDictGetPathExpr {
    param($Node)

    $pathArgs = Get-WasmAstDictGetPathArgs $Node
    if ($null -eq $pathArgs) { return @() }
    $segments = @(Get-WasmAstDictPathSegments ([string]$pathArgs.Path))
    if ($segments.Count -eq 0) { return @() }

    $code = @(Convert-WasmAstExpr ($pathArgs.Source))
    foreach ($segment in $segments) {
        $code = @($code + @("i32.const $(Get-WasmStringKeyHash $segment)", "call `$__sura_dict_get"))
    }
    return @($code)
}

function Convert-WasmAstJsonHasPathExpr {
    param($Node)

    $pathArgs = Get-WasmAstJsonHasPathArgs $Node
    if ($null -eq $pathArgs) { return @() }
    $segments = @(Get-WasmAstDictPathSegments ([string]$pathArgs.Path))
    if ($segments.Count -eq 0) { return @() }

    $code = @(Convert-WasmAstExpr ($pathArgs.Source))
    for ($segmentIndex = 0; $segmentIndex -lt $segments.Count; $segmentIndex++) {
        $segment = [string]$segments[$segmentIndex]
        if ($segmentIndex -eq ($segments.Count - 1)) {
            $code = @($code + @("i32.const $(Get-WasmStringKeyHash $segment)", "call `$__sura_dict_has"))
        } else {
            $code = @($code + @("i32.const $(Get-WasmStringKeyHash $segment)", "call `$__sura_dict_get"))
        }
    }
    return @($code)
}

function Get-WasmAstDictGetPathStaticType {
    param($Node)

    $pathArgs = Get-WasmAstDictGetPathArgs $Node
    if ($null -eq $pathArgs) { return "" }
    $segments = @(Get-WasmAstDictPathSegments ([string]$pathArgs.Path))
    if ($segments.Count -eq 0) { return "" }

    $current = $pathArgs.Source
    $knownType = ""
    foreach ($segment in $segments) {
        $structureKnown = $false
        $accessPath = Get-WasmAstAccessPathName $current
        if (-not [string]::IsNullOrWhiteSpace($accessPath) -and
            $script:wasmDictKeyOrderHints.ContainsKey($accessPath)) {
            $structureKnown = $true
            $knownKeys = @($script:wasmDictKeyOrderHints[$accessPath])
            if ($segment -notin $knownKeys) { return "nil" }
            $hintKey = "$accessPath.$segment"
            if (-not $script:wasmConflictedAccessTypeHints.ContainsKey($hintKey) -and
                $script:wasmAccessTypeHints.ContainsKey($hintKey)) {
                $knownType = [string]$script:wasmAccessTypeHints[$hintKey]
            } else {
                $knownType = ""
            }
        }
        if (-not $structureKnown) {
            $orderedEntries = @(Get-WasmAstOrderedDictEntryTypes $current)
            if ($orderedEntries.Count -gt 0) {
                $structureKnown = $true
                $matchedEntry = $null
                foreach ($entry in $orderedEntries) {
                    if ([string]$entry.Key -eq $segment) {
                        $matchedEntry = $entry
                        break
                    }
                }
                if ($null -eq $matchedEntry) { return "nil" }
                $knownType = [string]$matchedEntry.Type
            }
        }
        $current = [pscustomobject]@{
            node = "DOT_ACCESS"
            line = 0
            obj = $current
            prop = $segment
        }
    }
    if (-not [string]::IsNullOrWhiteSpace($knownType)) { return $knownType }
    return (Get-WasmAstStaticValueType $current)
}

function Get-WasmAstDictPickOrderedEntryTypes {
    param($Node)

    $pickArgs = Get-WasmAstDictPickArgs $Node
    if ($null -eq $pickArgs) { return @() }
    $keyNames = @(Get-WasmAstStringArrayLiteralValues ($pickArgs.Keys))
    if ($keyNames.Count -eq 0) { return @() }
    $sourceEntries = @(Get-WasmAstOrderedDictEntryTypes ($pickArgs.Source))
    if ($sourceEntries.Count -eq 0) { return @() }

    $sourceTypes = @{}
    foreach ($entry in $sourceEntries) {
        $sourceTypes[[string]$entry.Key] = [string]$entry.Type
    }

    $picked = New-Object System.Collections.Generic.List[object]
    if (Test-WasmAstDictOmitExpr $Node) {
        $omit = @{}
        foreach ($keyName in $keyNames) { $omit[[string]$keyName] = $true }
        foreach ($entry in $sourceEntries) {
            $key = [string]$entry.Key
            if ($omit.ContainsKey($key)) { continue }
            $picked.Add((New-WasmAstOrderedDictEntryType $key ([string]$entry.Type))) | Out-Null
        }
    } else {
        $seen = @{}
        foreach ($keyName in $keyNames) {
            $key = [string]$keyName
            if ($seen.ContainsKey($key)) { continue }
            $seen[$key] = $true
            if (-not $sourceTypes.ContainsKey($key)) { continue }
            $picked.Add((New-WasmAstOrderedDictEntryType $key ([string]$sourceTypes[$key]))) | Out-Null
        }
    }
    return @($picked.ToArray())
}

function Test-WasmAstValueExprCandidate {
    param($Node)

    if ($null -eq $Node) { return $true }
    if (Test-WasmAstFractionalNumericValueExpr $Node) { return $true }
    if (Test-WasmAstValuePreservingExprCandidate $Node) { return $true }
    if (Test-WasmAstStringExprCandidate $Node) { return $true }
    if (-not [string]::IsNullOrWhiteSpace((Get-WasmAstKnownValueType $Node))) { return $true }
    $staticType = Get-WasmAstStaticValueType $Node
    if ($staticType -in @("string", "bool", "nil", "array", "dict", "function")) { return $true }
    if ([string]$Node.node -eq "BIN_OP" -and [string]$Node.op -eq "in") { return $true }
    if ([string]$Node.node -eq "BIN_OP" -and [string]$Node.op -eq "??") {
        return ((Test-WasmAstValueExprCandidate ($Node.left)) -or (Test-WasmAstValueExprCandidate ($Node.right)))
    }
    if ([string]$Node.node -eq "TERNARY" -and
        ((Test-WasmAstValueExprCandidate ($Node.then)) -or (Test-WasmAstValueExprCandidate ($Node.else)))) {
        return $true
    }
    switch ([string]$Node.node) {
        "STR_LIT" { return $true }
        "STR_INTERP" { return $true }
        "DOT_ACCESS" { return (Test-WasmAstRuntimeValueDotCandidate $Node) }
        "INDEX" { return (Test-WasmAstRuntimeValueIndexCandidate $Node) }
        "NIL_LIT" { return $true }
        "BOOL_LIT" { return $true }
        "ARRAY_LIT" { return $true }
        "DICT_LIT" { return $true }
        "NEW_EXPR" { return $true }
        "FUNC_EXPR" { return $true }
        default { return $false }
    }
}

function Convert-WasmAstRawExprToValue {
    param(
        [string[]]$RawCode,
        [string]$TypeName = "",
        [int]$ArrayElementTag = -1
    )

    switch ($TypeName) {
        "string" { return @($RawCode + @("call `$__sura_value_string_or_nil")) }
        "bool" { return @($RawCode + @("call `$__sura_value_bool")) }
        "nil" { return @($RawCode + @("drop", "call `$__sura_value_nil")) }
        "num" { return @($RawCode + @("call `$__sura_value_num")) }
        "value" { return @($RawCode) }
        "array" {
            $wrapCode = if ($ArrayElementTag -ge 0) {
                @("local.get `$__sura_wasm_value_tmp", "i32.const $ArrayElementTag", "call `$__sura_value_array_typed")
            } else {
                @("local.get `$__sura_wasm_value_tmp", "call `$__sura_value_array")
            }
            return @(
                $RawCode +
                @(
                    "local.set `$__sura_wasm_value_tmp",
                    "local.get `$__sura_wasm_value_tmp",
                    "if (result i32)"
                ) +
                $wrapCode +
                @(
                    "else",
                    "call `$__sura_value_nil",
                    "end"
                )
            )
        }
        { $_ -in @("dict", "function") } {
            $helper = switch ($TypeName) {
                "dict" { "__sura_value_dict" }
                default { "__sura_value_function" }
            }
            return @(
                $RawCode +
                @(
                    "local.set `$__sura_wasm_value_tmp",
                    "local.get `$__sura_wasm_value_tmp",
                    "if (result i32)",
                    "local.get `$__sura_wasm_value_tmp",
                    "call `$$helper",
                    "else",
                    "call `$__sura_value_nil",
                    "end"
                )
            )
        }
        default { return @($RawCode + @("call `$__sura_value_num")) }
    }
}

function Convert-WasmAstRawDictExprToDynamicValue {
    param($Node)

    if ($null -eq $Node) { return @() }
    $orderedEntries = @(Get-WasmAstOrderedDictEntryTypes $Node)
    if ($orderedEntries.Count -eq 0) { return @() }
    foreach ($entry in $orderedEntries) {
        if ([string]$entry.Type -notin @("string", "bool", "nil", "num", "array", "dict", "function")) {
            return @()
        }
    }

    $entries = New-Object System.Collections.Generic.List[object]
    foreach ($entry in $orderedEntries) {
        $key = [string]$entry.Key
        $typeName = [string]$entry.Type
        $rawCode = @(
            "local.get `$__sura_wasm_dict_tmp",
            "i32.const $(Get-WasmStringKeyHash $key)",
            "call `$__sura_dict_get"
        )
        $arrayElementTag = -1
        if ($typeName -eq "array") {
            $entryNode = [pscustomobject]@{
                node = "DOT_ACCESS"
                line = 0
                obj = $Node
                prop = $key
            }
            $arrayElementTag = Get-WasmAstValueTagForTypeName (Get-WasmAstDirectArrayElementTypeHint $entryNode)
        }
        $entries.Add([pscustomobject]@{
            Key = $key
            Hash = Get-WasmStringKeyHash $key
            ValueCode = [string[]]@(Convert-WasmAstRawExprToValue -RawCode $rawCode -TypeName $typeName -ArrayElementTag $arrayElementTag)
        }) | Out-Null
    }

    return @(
        @(Convert-WasmAstExpr $Node) +
        @("local.set `$__sura_wasm_dict_tmp") +
        @(New-WasmDictLiteralExprCode -Entries ([object[]]$entries.ToArray())) +
        @("call `$__sura_value_dynamic_dict")
    )
}

function Convert-WasmAstCoalesceBranchValueExpr {
    param(
        $Node,
        [string]$TypeName = ""
    )

    if (Test-WasmAstOptionalAccessExpr $Node) {
        return @(Convert-WasmAstValueExpr $Node $TypeName)
    }
    if ($TypeName -in @("array", "dict", "function")) {
        $arrayElementTag = if ($TypeName -eq "array") {
            Get-WasmAstValueTagForTypeName (Get-WasmAstDirectArrayElementTypeHint $Node)
        } else { -1 }
        return @(Convert-WasmAstRawExprToValue -RawCode @(Convert-WasmAstExpr $Node) -TypeName $TypeName -ArrayElementTag $arrayElementTag)
    }
    return @(Convert-WasmAstValueExpr $Node $TypeName)
}

function Convert-WasmAstOptionalAccessValueExpr {
    param(
        $Node,
        [string]$ExpectedType = ""
    )

    if ($null -eq $Node -or [string]$Node.node -notin @("DOT_ACCESS", "INDEX")) {
        return @()
    }

    $resultType = $ExpectedType
    if ([string]::IsNullOrWhiteSpace($resultType)) {
        $resultType = Get-WasmAstKnownValueType $Node
    }
    if ([string]::IsNullOrWhiteSpace($resultType)) {
        $resultType = Get-WasmAstStaticValueType $Node
    }

    $objType = Get-WasmAstKnownValueType ($Node.obj)
    if ([string]::IsNullOrWhiteSpace($objType)) {
        $objType = Get-WasmAstStaticValueType ($Node.obj)
    }
    if ($objType -eq "value" -or
        (Test-WasmAstRuntimeValueIndexCandidate ($Node.obj)) -or
        (Test-WasmAstRuntimeValueDotCandidate ($Node.obj))) {
        if ([string]$Node.node -eq "DOT_ACCESS") {
            return @(Convert-WasmAstValueExpr ($Node.obj)) + @(
                "i32.const $(Get-WasmStringKeyHash ([string]$Node.prop))",
                "call `$__sura_value_field"
            )
        }
        return @(Convert-WasmAstValueExpr ($Node.obj)) +
            @(Convert-WasmAstValueExpr ($Node.key)) +
            @("call `$__sura_value_index")
    }

    $receiverCode = @(Convert-WasmAstExpr ($Node.obj))
    if ([string]$Node.node -eq "DOT_ACCESS") {
        $prop = [string]$Node.prop
        if ($prop -eq "len" -and $objType -in @("string", "array", "dict")) {
            $wrappedLength = @(Convert-WasmAstRawExprToValue -RawCode @(
                "local.get `$__sura_wasm_value_tmp",
                "call `$__sura_$($objType)_require"
            ) -TypeName "num")
            return @(
                $receiverCode +
                @(
                    "local.set `$__sura_wasm_value_tmp",
                    "local.get `$__sura_wasm_value_tmp",
                    "if (result i32)"
                ) +
                $wrappedLength +
                @("else", "call `$__sura_value_nil", "end")
            )
        }

        $hash = Get-WasmStringKeyHash $prop
        $resultArrayElementTag = if ($resultType -eq "array") {
            Get-WasmAstValueTagForTypeName (Get-WasmAstDirectArrayElementTypeHint $Node)
        } else { -1 }
        $wrapped = @(Convert-WasmAstRawExprToValue -RawCode @(
            "local.get `$__sura_wasm_value_tmp",
            "i32.const $hash",
            "call `$__sura_dict_get"
        ) -TypeName $resultType -ArrayElementTag $resultArrayElementTag)
        return @(
            $receiverCode +
            @(
                "local.set `$__sura_wasm_value_tmp",
                "local.get `$__sura_wasm_value_tmp",
                "if (result i32)",
                "local.get `$__sura_wasm_value_tmp",
                "i32.const $hash",
                "call `$__sura_dict_has",
                "if (result i32)"
            ) +
            $wrapped +
            @(
                "else",
                "call `$__sura_value_nil",
                "end",
                "else",
                "call `$__sura_value_nil",
                "end"
            )
        )
    }

    $keyType = Get-WasmAstKnownValueType ($Node.key)
    if ([string]::IsNullOrWhiteSpace($keyType)) {
        $keyType = Get-WasmAstStaticValueType ($Node.key)
    }
    $knownStringKey = Get-WasmAstKnownStringLiteralValue ($Node.key)
    $dictIndex = ($objType -eq "dict" -or $keyType -eq "string" -or -not [string]::IsNullOrWhiteSpace($knownStringKey))
    if ($dictIndex -and $objType -notin @("array", "string")) {
        $hashCode = if (-not [string]::IsNullOrWhiteSpace($knownStringKey)) {
            @("i32.const $(Get-WasmStringKeyHash $knownStringKey)")
        } else {
            @(Convert-WasmAstStringExpr ($Node.key)) + @("call `$__sura_string_hash")
        }
        $resultArrayElementTag = if ($resultType -eq "array") {
            Get-WasmAstValueTagForTypeName (Get-WasmAstDirectArrayElementTypeHint $Node)
        } else { -1 }
        $wrapped = @(Convert-WasmAstRawExprToValue -RawCode @(
            "local.get `$__sura_wasm_value_tmp",
            "local.get `$__sura_wasm_array_tmp",
            "call `$__sura_dict_get"
        ) -TypeName $resultType -ArrayElementTag $resultArrayElementTag)
        return @(
            $receiverCode +
            @(
                "local.set `$__sura_wasm_value_tmp",
                "local.get `$__sura_wasm_value_tmp",
                "if (result i32)"
            ) +
            $hashCode +
            @(
                "local.set `$__sura_wasm_array_tmp",
                "local.get `$__sura_wasm_value_tmp",
                "local.get `$__sura_wasm_array_tmp",
                "call `$__sura_dict_has",
                "if (result i32)"
            ) +
            $wrapped +
            @(
                "else",
                "call `$__sura_value_nil",
                "end",
                "else",
                "call `$__sura_value_nil",
                "end"
            )
        )
    }

    $keyCode = @(Convert-WasmAstExpr ($Node.key))
    if ($keyType -eq "value") {
        $keyCode += "call `$__sura_value_as_i32"
    }
    $rawCode = if ($objType -eq "string") {
        @("local.get `$__sura_wasm_value_tmp") + $keyCode + @("call `$__sura_string_at")
    } else {
        @("local.get `$__sura_wasm_value_tmp") + $keyCode + @("call `$__sura_array_get_checked")
    }
    $resultArrayElementTag = if ($resultType -eq "array") {
        Get-WasmAstValueTagForTypeName (Get-WasmAstDirectArrayElementTypeHint $Node)
    } else { -1 }
    $wrapped = @(Convert-WasmAstRawExprToValue -RawCode $rawCode -TypeName $resultType -ArrayElementTag $resultArrayElementTag)
    return @(
        $receiverCode +
        @(
            "local.set `$__sura_wasm_value_tmp",
            "local.get `$__sura_wasm_value_tmp",
            "if (result i32)"
        ) +
        $wrapped +
        @("else", "call `$__sura_value_nil", "end")
    )
}

function Get-WasmAstStaticNumericType {
    param($Node)

    if ($null -eq $Node) { return "" }
    $typeName = Get-WasmAstKnownValueType $Node
    if ([string]::IsNullOrWhiteSpace($typeName)) {
        $typeName = Get-WasmAstStaticValueType $Node
    }
    return [string]$typeName
}

function Test-WasmAstStaticF64ArithmeticExpr {
    param($Node)

    if ($null -eq $Node -or [string]$Node.node -ne "BIN_OP" -or
        [string]$Node.op -notin @("+", "-", "*")) {
        return $false
    }
    if ((Get-WasmAstStaticNumericType ($Node.left)) -ne "num" -or
        (Get-WasmAstStaticNumericType ($Node.right)) -ne "num") {
        return $false
    }
    return (Test-WasmAstFractionalStorageExpr $Node)
}

function Convert-WasmAstStaticF64OperandExpr {
    param($Node)

    $constants = @(Get-WasmAstDecimalConstant $Node)
    if ($constants.Count -gt 0) {
        $value = [double]$constants[0]
        if (-not [double]::IsNaN($value) -and -not [double]::IsInfinity($value)) {
            $text = $value.ToString("G17", [System.Globalization.CultureInfo]::InvariantCulture)
            return @("f64.const $text")
        }
    }
    if (Test-WasmAstStaticF64ArithmeticExpr $Node) {
        return @(Convert-WasmAstStaticF64ArithmeticExpr $Node)
    }
    if (Test-WasmAstValuePreservingExprCandidate $Node) {
        return @(Convert-WasmAstValueExpr $Node) + @("call `$__sura_value_require_number_f64")
    }
    return @(Convert-WasmAstExpr $Node) + @("f64.convert_i32_s")
}

function Convert-WasmAstStaticF64ArithmeticExpr {
    param($Node)

    if (-not (Test-WasmAstStaticF64ArithmeticExpr $Node)) { return @() }
    $watOp = switch ([string]$Node.op) {
        "+" { "f64.add" }
        "-" { "f64.sub" }
        "*" { "f64.mul" }
        default { throw "unsupported static f64 arithmetic operator: $([string]$Node.op)" }
    }
    return @(
        @(Convert-WasmAstStaticF64OperandExpr ($Node.left)) +
        @(Convert-WasmAstStaticF64OperandExpr ($Node.right)) +
        @($watOp)
    )
}

function Convert-WasmAstStaticF64ArithmeticValueExpr {
    param($Node)

    $rawCode = @(Convert-WasmAstStaticF64ArithmeticExpr $Node)
    if ($rawCode.Count -eq 0) { return @() }
    return @($rawCode + @("call `$__sura_value_num_f64"))
}

function Convert-WasmAstValueExpr {
    param($Node, [string]$ExpectedType = "")

    if ($null -eq $Node) { return @("call `$__sura_value_nil") }
    if (Test-WasmAstBitwiseValueExprCandidate $Node) {
        # The checked i64 helpers already return a tagged numeric Value.
        return @(Convert-WasmAstExpr $Node)
    }
    $valueMathName = Get-WasmAstValueMathIntrinsicName $Node
    if (-not [string]::IsNullOrWhiteSpace($valueMathName)) {
        $valueMathArgs = @(Get-WasmAstValueMathIntrinsicArgs $Node)
        $valueMathCode = @(Convert-WasmAstValueMathIntrinsicCall -Name $valueMathName -InputArgs ([object[]]$valueMathArgs))
        if ($valueMathCode.Count -gt 0) { return $valueMathCode }
    }
    if ([string]$Node.node -eq "CALL") {
        $conversionName = [string]$Node.name
        $conversionArgs = @(As-WasmAstArray ($Node.args))
        if ($conversionArgs.Count -eq 1 -and $conversionName -eq "to_float") {
            return @(Convert-WasmAstGuardedCallResult ([string[]]@(
                @(Convert-WasmAstValueExpr ($conversionArgs[0])) +
                @("call `$__sura_value_to_float")
            )))
        }
        if ($conversionArgs.Count -eq 1 -and $conversionName -eq "to_int") {
            return @(Convert-WasmAstExpr $Node) + @("call `$__sura_value_num")
        }
        if (Test-WasmAstIndirectFunctionValueCall $Node) {
            return @(Convert-WasmAstExpr $Node)
        }
        $directFunctionValueLift = Get-WasmAstDirectFunctionValueCallLiftName $Node
        if (-not [string]::IsNullOrWhiteSpace($directFunctionValueLift) -and
            (Test-WasmAstFunctionReturnValuePreserving $directFunctionValueLift)) {
            return @(Convert-WasmAstExpr $Node)
        }
        if (Test-WasmAstFunctionReturnValuePreserving $conversionName) {
            return @(Convert-WasmAstExpr $Node)
        }
    }
    $decimalConstants = @(Get-WasmAstDecimalConstant $Node)
    if ($decimalConstants.Count -gt 0) {
        $decimalValue = [double]$decimalConstants[0]
        if (-not [double]::IsNaN($decimalValue) -and
            -not [double]::IsInfinity($decimalValue) -and
            ($decimalValue -ne [Math]::Truncate($decimalValue) -or
                $decimalValue -lt [int]::MinValue -or $decimalValue -gt [int]::MaxValue)) {
            # Windows PowerShell's legacy "R" formatter can emit a decimal that
            # round-trips in .NET but selects an adjacent f64 in WAT parsers.
            # G17 is the cross-parser round-trip representation for IEEE-754 doubles.
            $decimalText = $decimalValue.ToString("G17", [System.Globalization.CultureInfo]::InvariantCulture)
            return @("f64.const $decimalText", "call `$__sura_value_num_f64")
        }
    }
    $staticF64Arithmetic = @(Convert-WasmAstStaticF64ArithmeticValueExpr $Node)
    if ($staticF64Arithmetic.Count -gt 0) {
        return $staticF64Arithmetic
    }
    if ([string]$Node.node -eq "BIN_OP" -and [string]$Node.op -eq "??") {
        $coalesceType = $ExpectedType
        if ([string]::IsNullOrWhiteSpace($coalesceType)) {
            $coalesceType = Get-WasmAstKnownValueType $Node
        }
        if ([string]::IsNullOrWhiteSpace($coalesceType)) {
            $coalesceType = Get-WasmAstStaticValueType $Node
        }
        if ([string]::IsNullOrWhiteSpace($coalesceType)) {
            $coalesceType = Get-WasmAstKnownValueType ($Node.right)
        }
        if ([string]::IsNullOrWhiteSpace($coalesceType)) {
            $coalesceType = Get-WasmAstStaticValueType ($Node.right)
        }
        return @(
            @(Convert-WasmAstCoalesceBranchValueExpr ($Node.left) $coalesceType) +
            @("local.set `$__sura_wasm_value_tmp", "local.get `$__sura_wasm_value_tmp", "call `$__sura_value_tag", "i32.const 0", "i32.eq", "if (result i32)") +
            @(Convert-WasmAstCoalesceBranchValueExpr ($Node.right) $coalesceType) +
            @("else", "local.get `$__sura_wasm_value_tmp", "end")
        )
    }
    if ([string]$Node.node -eq "TERNARY" -and
        ((Test-WasmAstValueExprCandidate ($Node.then)) -or (Test-WasmAstValueExprCandidate ($Node.else)))) {
        $condCode = @(Convert-WasmAstConditionExpr ($Node.cond))
        $thenCode = @(Convert-WasmAstValueExpr ($Node.then))
        $elseCode = @(Convert-WasmAstValueExpr ($Node.else))
        return @(
            $condCode +
            @("if (result i32)") +
            $thenCode +
            @("else") +
            $elseCode +
            @("end")
        )
    }
    if (Test-WasmAstOptionalAccessExpr $Node) {
        return @(Convert-WasmAstOptionalAccessValueExpr $Node $ExpectedType)
    }
    if (Test-WasmAstRuntimeValueIndexCandidate $Node) {
        return @(Convert-WasmAstValueExpr ($Node.obj) "value") + @(Convert-WasmAstValueExpr ($Node.key)) + @("call `$__sura_value_index")
    }
    if (Test-WasmAstRuntimeValueDotCandidate $Node) {
        return @(Convert-WasmAstValueExpr ($Node.obj) "value") + @("i32.const $(Get-WasmStringKeyHash ([string]$Node.prop))", "call `$__sura_value_field")
    }
    if (Test-WasmAstStringIndexExpr $Node) {
        return @(Convert-WasmAstExpr $Node) + @("call `$__sura_value_string_or_nil")
    }
    $objectClassHint = Get-WasmAstObjectClassSetHintWithLocals $Node $script:wasmCurrentLocalObjectClassHints $script:wasmCurrentClassContext
    if (-not [string]::IsNullOrWhiteSpace($objectClassHint)) {
        return @(Convert-WasmAstExpr $Node) + @("call `$__sura_value_object")
    }
    $earlyKnownType = Get-WasmAstKnownValueType $Node
    if ([string]::IsNullOrWhiteSpace($earlyKnownType)) {
        $earlyKnownType = Get-WasmAstStaticValueType $Node
    }
    if ($earlyKnownType -eq "value") {
        # A runtime Value may currently contain a string, but it is already a
        # tagged handle. Routing it through the static string candidate path
        # recurses back into Convert-WasmAstStringExpr. Keep the handle and let
        # the caller explicitly choose value_to_string/value_require_num/etc.
        return @(Convert-WasmAstExpr $Node)
    }
    if (Test-WasmAstStringExprCandidate $Node) {
        return @(Convert-WasmAstRawExprToValue -RawCode @(Convert-WasmAstStringExpr $Node) -TypeName "string")
    }
    if ([string]$Node.node -eq "ARRAY_LIT") {
        $argCodes = New-Object System.Collections.Generic.List[object]
        foreach ($item in @(As-WasmAstArray ($Node.elements))) {
            $argCodes.Add([string[]]@(Convert-WasmAstValueExpr $item)) | Out-Null
        }
        return @(New-WasmArrayLiteralExprCode -ArgCodes @($argCodes.ToArray())) + @("call `$__sura_value_dynamic_array")
    }
    if ([string]$Node.node -eq "DICT_LIT") {
        $entries = New-Object System.Collections.Generic.List[object]
        foreach ($entry in @(As-WasmAstArray ($Node.entries))) {
            $entries.Add([pscustomobject]@{
                Key = [string]$entry.key
                Hash = Get-WasmStringKeyHash ([string]$entry.key)
                ValueCode = [string[]]@(Convert-WasmAstValueExpr ($entry.value))
            }) | Out-Null
        }
        return @(New-WasmDictLiteralExprCode -Entries ([object[]]$entries.ToArray())) + @("call `$__sura_value_dynamic_dict")
    }
    if ([string]$Node.node -eq "BIN_OP" -and
        (([string]$Node.op -eq "/") -or
         ([string]$Node.op -in @("+", "-", "*", "%") -and
          ((Test-WasmAstDynamicNumericValueExpr ($Node.left)) -or (Test-WasmAstDynamicNumericValueExpr ($Node.right)))) -or
         [string]$Node.op -eq "in")) {
        # Runtime-dispatched numeric arithmetic and membership already return
        # tagged Values.
        # Other value-preserving candidates such as dict_get_path can still
        # return an untagged scalar and must continue through the normal
        # type-specific wrapping below.
        return @(Convert-WasmAstExpr $Node)
    }
    $knownType = Get-WasmAstKnownValueType $Node
    if ([string]::IsNullOrWhiteSpace($knownType)) {
        $knownType = Get-WasmAstStaticValueType $Node
    }
    if ($knownType -eq "string") {
        return @(Convert-WasmAstRawExprToValue -RawCode @(Convert-WasmAstStringExpr $Node) -TypeName "string")
    }
    if ($knownType -eq "value") {
        return @(Convert-WasmAstExpr $Node)
    }
    if ($knownType -eq "bool") {
        return @(Convert-WasmAstExpr $Node) + @("call `$__sura_value_bool")
    }
    if ($knownType -eq "nil") {
        if (Test-WasmAstEffectfulExpr $Node) {
            return @(Convert-WasmAstExpr $Node) + @("drop", "call `$__sura_value_nil")
        }
        return @("call `$__sura_value_nil")
    }
    if ($knownType -eq "array") {
        $arrayElementTag = Get-WasmAstValueTagForTypeName (Get-WasmAstDirectArrayElementTypeHint $Node)
        return @(Convert-WasmAstRawExprToValue -RawCode @(Convert-WasmAstExpr $Node) -TypeName "array" -ArrayElementTag $arrayElementTag)
    }
    if ($knownType -eq "dict") {
        return @(Convert-WasmAstRawExprToValue -RawCode @(Convert-WasmAstExpr $Node) -TypeName "dict")
    }
    if ($knownType -eq "function") {
        return @(Convert-WasmAstRawExprToValue -RawCode @(Convert-WasmAstExpr $Node) -TypeName "function")
    }
    switch ([string]$Node.node) {
        "NIL_LIT" {
            return @("call `$__sura_value_nil")
        }
        "BOOL_LIT" {
            return @(Convert-WasmAstExpr $Node) + @("call `$__sura_value_bool")
        }
        "STR_LIT" {
            return @(Convert-WasmAstExpr $Node) + @("call `$__sura_value_string")
        }
        "STR_INTERP" {
            return @(Convert-WasmAstExpr $Node) + @("call `$__sura_value_string")
        }
        "ARRAY_LIT" {
            return @(Convert-WasmAstExpr $Node) + @("call `$__sura_value_array")
        }
        "DICT_LIT" {
            return @(Convert-WasmAstExpr $Node) + @("call `$__sura_value_dict")
        }
        "NEW_EXPR" {
            return @(Convert-WasmAstExpr $Node) + @("call `$__sura_value_dict")
        }
        "FUNC_EXPR" {
            throw "unsupported WASM AST inline function expression value outside top-level promotion"
        }
        default {
            return @(Convert-WasmAstExpr $Node) + @("call `$__sura_value_num")
        }
    }
}

function Get-WasmAstDirectArrayFixedHints {
    param($Node)

    if ($null -eq $Node) { return @{} }
    if ([string]$Node.node -eq "ARRAY_LIT") {
        return (Get-WasmAstFixedIndexedAccessHintsForExpr $Node $script:wasmCurrentLocalIndexedAccessHints)
    }
    if ([string]$Node.node -notin @("IDENT", "DOT_ACCESS", "INDEX")) { return @{} }
    $baseName = Get-WasmAstAccessPathName $Node
    if ([string]::IsNullOrWhiteSpace($baseName)) { return @{} }
    return (Get-WasmAstFixedIndexedAccessHintsByBase $baseName $script:wasmCurrentLocalIndexedAccessHints)
}

function Get-WasmAstDirectArrayElementTypeHint {
    param($Node, [hashtable]$Seen = @{})

    if ($null -eq $Node) { return "" }
    $nodeId = [System.Runtime.CompilerServices.RuntimeHelpers]::GetHashCode([object]$Node)
    if ($Seen.ContainsKey($nodeId)) { return "" }
    $nextSeen = [hashtable]$Seen.Clone()
    $nextSeen[$nodeId] = $true

    # Keep this helper deliberately structural. It may run from broad Value
    # wrapping paths, so it must not enter whole-function type inference. AST
    # JSON is acyclic, but the explicit visited set also makes prebuilt object
    # graphs terminate safely. This lets arbitrarily long chains of direct
    # array producers preserve their element tag without a magic depth cutoff.
    if ([string]$Node.node -eq "BIN_OP" -and [string]$Node.op -eq "+") {
        $leftType = Get-WasmAstDirectArrayElementTypeHint ($Node.left) $nextSeen
        $rightType = Get-WasmAstDirectArrayElementTypeHint ($Node.right) $nextSeen
        return (Get-WasmAstCommonTypeName @($leftType, $rightType))
    }
    if ([string]$Node.node -eq "BIN_OP" -and [string]$Node.op -eq "??") {
        $leftStaticType = Get-WasmAstStaticValueTypeWithParams ($Node.left) @{}
        if ($leftStaticType -eq "nil") {
            return (Get-WasmAstDirectArrayElementTypeHint ($Node.right) $nextSeen)
        }
        $leftType = Get-WasmAstDirectArrayElementTypeHint ($Node.left) $nextSeen
        $rightType = Get-WasmAstDirectArrayElementTypeHint ($Node.right) $nextSeen
        if ([string]::IsNullOrWhiteSpace($rightType)) {
            $rightStaticType = Get-WasmAstStaticValueTypeWithParams ($Node.right) @{}
            if ($rightStaticType -eq "nil") { return $leftType }
            return ""
        }
        return (Get-WasmAstCommonTypeName @($leftType, $rightType))
    }
    if ([string]$Node.node -eq "TERNARY") {
        $condState = Get-WasmAstKnownBoolLiteralState ($Node.cond)
        if ($condState -eq "true") {
            return (Get-WasmAstDirectArrayElementTypeHint ($Node.then) $nextSeen)
        }
        if ($condState -eq "false") {
            return (Get-WasmAstDirectArrayElementTypeHint ($Node.else) $nextSeen)
        }
        $thenType = Get-WasmAstDirectArrayElementTypeHint ($Node.then) $nextSeen
        $elseType = Get-WasmAstDirectArrayElementTypeHint ($Node.else) $nextSeen
        return (Get-WasmAstCommonTypeName @($thenType, $elseType))
    }
    if (Test-WasmAstArraySliceExpr $Node) {
        return (Get-WasmAstDirectArrayElementTypeHint (Get-WasmAstArraySliceSourceExpr $Node) $nextSeen)
    }
    if (Test-WasmAstArrayReverseExpr $Node) {
        return (Get-WasmAstDirectArrayElementTypeHint (Get-WasmAstArrayReverseSourceExpr $Node) $nextSeen)
    }
    if (Test-WasmAstArraySortExpr $Node) {
        return (Get-WasmAstDirectArrayElementTypeHint (Get-WasmAstArraySortSourceExpr $Node) $nextSeen)
    }
    if (Test-WasmAstArrayUniqueExpr $Node) {
        return (Get-WasmAstDirectArrayElementTypeHint (Get-WasmAstArrayUniqueSourceExpr $Node) $nextSeen)
    }
    if (Test-WasmAstArrayCloneExpr $Node) {
        return (Get-WasmAstDirectArrayElementTypeHint (Get-WasmAstArrayCloneSourceExpr $Node) $nextSeen)
    }
    if (Test-WasmAstArrayConcatExpr $Node) {
        $concatTypes = New-Object System.Collections.Generic.List[string]
        foreach ($arg in @(As-WasmAstArray ($Node.args))) {
            $concatTypes.Add((Get-WasmAstDirectArrayElementTypeHint $arg $nextSeen)) | Out-Null
        }
        return (Get-WasmAstCommonTypeName ([string[]]$concatTypes.ToArray()))
    }
    if (Test-WasmAstArrayRepeatExpr $Node) {
        return (Get-WasmAstStaticValueTypeWithParams (Get-WasmAstArrayRepeatValueExpr $Node) @{})
    }
    if ([string]$Node.node -eq "CALL" -and [string]$Node.name -in @("array.range", "array_range")) {
        return "num"
    }
    if ([string]$Node.node -eq "METHOD_CALL" -and
        $null -ne $Node.obj -and [string]$Node.obj.node -eq "IDENT" -and
        [string]$Node.obj.name -eq "array" -and [string]$Node.method -eq "range") {
        return "num"
    }
    $fixedHints = Get-WasmAstDirectArrayFixedHints $Node
    if (Test-WasmAstFixedIndexedHintMapHasItems $fixedHints) {
        $types = @(Convert-WasmAstFixedIndexedHintMapToTypeList $fixedHints)
        if ($types.Count -gt 0) {
            $common = Get-WasmAstCommonTypeName ([string[]]$types)
            if (-not [string]::IsNullOrWhiteSpace($common)) { return $common }
        }
    }
    if ([string]$Node.node -eq "ARRAY_LIT") {
        $types = New-Object System.Collections.Generic.List[string]
        foreach ($item in @(As-WasmAstArray ($Node.elements))) {
            $types.Add((Get-WasmAstStaticValueTypeWithParams $item @{})) | Out-Null
        }
        return (Get-WasmAstCommonTypeName ([string[]]$types.ToArray()))
    }
    $baseName = Get-WasmAstAccessPathName $Node
    if ([string]::IsNullOrWhiteSpace($baseName)) { return "" }
    $wildcardKey = "$baseName[*]"
    if ($script:wasmAccessTypeHints.ContainsKey($wildcardKey) -and
        -not $script:wasmConflictedAccessTypeHints.ContainsKey($wildcardKey)) {
        return [string]$script:wasmAccessTypeHints[$wildcardKey]
    }
    return ""
}

function Convert-WasmAstDynamicAddOperandValueExpr {
    param($Node)

    $typeName = Get-WasmAstKnownValueType $Node
    if ([string]::IsNullOrWhiteSpace($typeName)) {
        $typeName = Get-WasmAstStaticValueType $Node
    }
    if ($typeName -ne "array" -or [string]$Node.node -eq "ARRAY_LIT") {
        return @(Convert-WasmAstValueExpr $Node)
    }

    # A statically typed array stores raw i32 cells, while a runtime-selected
    # array stores a tagged Value in every cell. Preserve the homogeneous raw
    # array's element tag on its Value handle so __sura_value_add can normalize
    # a real tag-4/tag-8 pair at runtime. Mixed fixed arrays still lower to a
    # value-array because one element tag cannot describe their raw storage.
    $elementType = Get-WasmAstDirectArrayElementTypeHint $Node
    $elementTag = Get-WasmAstValueTagForTypeName $elementType
    if ($elementTag -ge 0) {
        return @(Convert-WasmAstRawExprToValue -RawCode @(Convert-WasmAstExpr $Node) -TypeName "array" -ArrayElementTag $elementTag)
    }

    $fixedHints = Get-WasmAstDirectArrayFixedHints $Node
    $fixedCount = Get-WasmAstContiguousFixedIndexedHintCount $fixedHints
    if ($fixedCount -gt 0) {
        $canConvertFixed = $true
        for ($i = 0; $i -lt $fixedCount; $i++) {
            if (-not $fixedHints.ContainsKey([string]$i) -or
                [string]$fixedHints[[string]$i].TypeName -notin @("nil", "num", "bool", "string", "array", "dict", "function")) {
                $canConvertFixed = $false
                break
            }
        }
        if ($canConvertFixed) {
            $argCodes = New-Object System.Collections.Generic.List[object]
            for ($i = 0; $i -lt $fixedCount; $i++) {
                $rawCell = @(
                    "local.get `$__sura_wasm_array_tmp",
                    "i32.const $i",
                    "call `$__sura_array_get_checked"
                )
                $argCodes.Add([string[]]@(Convert-WasmAstRawExprToValue -RawCode $rawCell -TypeName ([string]$fixedHints[[string]$i].TypeName))) | Out-Null
            }
            return @(
                @(Convert-WasmAstExpr $Node) +
                @("local.set `$__sura_wasm_array_tmp") +
                @(New-WasmArrayLiteralExprCode -ArgCodes ([object[]]$argCodes.ToArray())) +
                @("call `$__sura_value_dynamic_array")
            )
        }
    }

    return @(Convert-WasmAstValueExpr $Node)
}

function Get-WasmAstExprTypeForValueWrap {
    param($Node)

    $typeName = Get-WasmAstKnownValueType $Node
    if ([string]::IsNullOrWhiteSpace($typeName)) {
        $typeName = Get-WasmAstStaticValueType $Node
    }
    return $typeName
}

function Convert-WasmAstStoredValueExpr {
    param([string]$LocalName, [string]$TypeName)

    switch ([string]$TypeName) {
        "string" { return @(Convert-WasmAstRawExprToValue -RawCode @("local.get `$$LocalName") -TypeName "string") }
        "bool" { return @("local.get `$$LocalName", "call `$__sura_value_bool") }
        "nil" { return @("call `$__sura_value_nil") }
        "array" {
            $localNode = [pscustomobject]@{ node = "IDENT"; name = $LocalName; line = 0 }
            $arrayElementTag = Get-WasmAstValueTagForTypeName (Get-WasmAstDirectArrayElementTypeHint $localNode)
            return @(Convert-WasmAstRawExprToValue -RawCode @("local.get `$$LocalName") -TypeName "array" -ArrayElementTag $arrayElementTag)
        }
        "dict" { return @(Convert-WasmAstRawExprToValue -RawCode @("local.get `$$LocalName") -TypeName "dict") }
        "function" { return @(Convert-WasmAstRawExprToValue -RawCode @("local.get `$$LocalName") -TypeName "function") }
        "value" { return @("local.get `$$LocalName") }
        default { return @("local.get `$$LocalName", "call `$__sura_value_num") }
    }
}

function Convert-WasmAstI32NumericExpr {
    param($Node)

    $typeName = Get-WasmAstExprTypeForValueWrap $Node
    $code = @(Convert-WasmAstExpr $Node)
    if ($typeName -eq "value") {
        $code += "call `$__sura_value_as_i32"
    }
    return $code
}

function Convert-WasmAstStoredI32NumericExpr {
    param([string]$LocalName, [string]$TypeName)

    if ($TypeName -eq "value") {
        return @("local.get `$$LocalName", "call `$__sura_value_as_i32")
    }
    return @("local.get `$$LocalName")
}

function Convert-WasmAstConditionExpr {
    param($Node)

    if ($null -ne $Node -and [string]$Node.node -eq "BIN_OP" -and [string]$Node.op -in @("and", "or")) {
        $leftCond = @(Convert-WasmAstConditionExpr ($Node.left))
        $rightCond = @(Convert-WasmAstConditionExpr ($Node.right))
        if ([string]$Node.op -eq "and") {
            return @(
                $leftCond +
                @("if (result i32)") +
                $rightCond +
                @("else", "i32.const 0", "end")
            )
        }
        return @(
            $leftCond +
            @("if (result i32)", "i32.const 1", "else") +
            $rightCond +
            @("end")
        )
    }
    if (Test-WasmAstValueExprCandidate $Node) {
        return @(Convert-WasmAstValueExpr $Node) + @("call `$__sura_value_is_truthy")
    }
    return @(Convert-WasmAstExpr $Node)
}

function Get-WasmAstDecimalConstant {
    param($Node)

    if ($null -eq $Node) { return @() }
    switch ([string]$Node.node) {
        "NUM_LIT" {
            return @(Convert-WasmAstJsonNumberToDouble $Node.value)
        }
        "UNARY_OP" {
            if ([string]$Node.op -eq "-") {
                $inner = @(Get-WasmAstDecimalConstant ($Node.operand))
                if ($inner.Count -gt 0) { return @(-1.0 * [double]$inner[0]) }
            }
        }
        "DOT_ACCESS" {
            if ([string]$Node.prop -eq "pi" -and
                $null -ne $Node.obj -and
                [string]$Node.obj.node -eq "IDENT" -and
                [string]$Node.obj.name -eq "math") {
                return @([Math]::PI)
            }
        }
    }
    return @()
}

function Get-WasmAstValueMathIntrinsicName {
    param($Node)

    if ($null -eq $Node) { return "" }
    $name = ""
    if ([string]$Node.node -eq "CALL") {
        $name = [string]$Node.name
    } elseif ([string]$Node.node -eq "METHOD_CALL" -and
        $null -ne $Node.obj -and [string]$Node.obj.node -eq "IDENT" -and
        [string]$Node.obj.name -eq "math") {
        $name = "math.$([string]$Node.method)"
    }
    if ($name -match '^math\.(.+)$') { $name = [string]$Matches[1] }
    if ($name -in @("abs", "sqrt", "floor", "ceil", "round", "sign", "sin", "cos", "tan", "min", "max", "clamp", "pow")) {
        return $name
    }
    return ""
}

function Get-WasmAstValueMathIntrinsicArgs {
    param($Node)

    if ($null -eq $Node -or [string]$Node.node -notin @("CALL", "METHOD_CALL")) { return @() }
    return @(As-WasmAstArray ($Node.args))
}

function Test-WasmAstValueMathIntrinsicCandidate {
    param([string]$Name, [object[]]$InputArgs)

    $args = @(As-WasmAstArray $InputArgs)
    $validCount = switch ($Name) {
        { $_ -in @("abs", "sqrt", "floor", "ceil", "round", "sign", "sin", "cos", "tan") } { $args.Count -eq 1; break }
        { $_ -in @("min", "max") } { $args.Count -ge 1; break }
        "clamp" { $args.Count -eq 3; break }
        "pow" { $args.Count -eq 2; break }
        default { $false }
    }
    if (-not $validCount) { return $false }
    if ($Name -in @("sin", "cos", "tan")) { return $true }

    if ($Name -in @("floor", "ceil", "round") -and $args.Count -eq 1) {
        # Preserve the existing compile-time fold for constant rounding calls.
        # Runtime-selected/f64 Value arguments still use the guarded math ABI.
        $constant = @(Get-WasmAstDecimalConstant ($args[0]))
        if ($constant.Count -gt 0) { return $false }
    }

    foreach ($arg in $args) {
        if ((Test-WasmAstFractionalNumericValueExpr $arg) -or
            (Test-WasmAstDynamicNumericValueExpr $arg) -or
            (Test-WasmAstValuePreservingExprCandidate $arg)) {
            return $true
        }
    }
    return $false
}

function Convert-WasmAstValueMathIntrinsicCall {
    param([string]$Name, [object[]]$InputArgs)

    $args = @(As-WasmAstArray $InputArgs)
    if (-not (Test-WasmAstValueMathIntrinsicCandidate -Name $Name -InputArgs ([object[]]$args))) {
        return @()
    }

    if ($Name -in @("abs", "sqrt", "floor", "ceil", "round", "sign", "sin", "cos", "tan")) {
        $op = switch ($Name) {
            "abs" { 0 }
            "sqrt" { 1 }
            "floor" { 2 }
            "ceil" { 3 }
            "round" { 4 }
            "sign" { 5 }
            "sin" { 6 }
            "cos" { 7 }
            "tan" { 8 }
        }
        return @(Convert-WasmAstGuardedCallResult ([string[]]@(
            @(Convert-WasmAstValueExpr ($args[0])) +
            @("i32.const $op", "call `$__sura_value_math_unary")
        )))
    }

    if ($Name -in @("min", "max")) {
        $op = if ($Name -eq "min") { 0 } else { 1 }
        $code = [string[]]@(Convert-WasmAstValueExpr ($args[0]))
        for ($i = 1; $i -lt $args.Count; $i++) {
            $code = [string[]]@(Convert-WasmAstGuardedCallResult ([string[]]@(
                @($code) +
                @(Convert-WasmAstValueExpr ($args[$i])) +
                @("i32.const $op", "call `$__sura_value_math_select")
            )))
        }
        return @($code)
    }

    if ($Name -eq "clamp") {
        $maxCode = [string[]]@(Convert-WasmAstGuardedCallResult ([string[]]@(
            @(Convert-WasmAstValueExpr ($args[0])) +
            @(Convert-WasmAstValueExpr ($args[1])) +
            @("i32.const 1", "call `$__sura_value_math_select")
        )))
        return @(Convert-WasmAstGuardedCallResult ([string[]]@(
            @($maxCode) +
            @(Convert-WasmAstValueExpr ($args[2])) +
            @("i32.const 0", "call `$__sura_value_math_select")
        )))
    }

    if ($Name -eq "pow") {
        return @(Convert-WasmAstGuardedCallResult ([string[]]@(
            @(Convert-WasmAstValueExpr ($args[0])) +
            @(Convert-WasmAstValueExpr ($args[1])) +
            @("call `$__sura_value_pow")
        )))
    }
    return @()
}

function Convert-WasmAstRoundedLiteralCall {
    param([string]$Name, [object[]]$InputArgs)

    $roundName = $Name
    if ($roundName -match '^math\.(floor|ceil|round)$') {
        $roundName = $Matches[1]
    }
    if ($roundName -notin @("floor", "ceil", "round") -or $InputArgs.Count -ne 1) {
        return @()
    }
    $values = @(Get-WasmAstDecimalConstant ($InputArgs[0]))
    if ($values.Count -eq 0) { return @() }
    $value = [double]$values[0]
    $rounded = switch ($roundName) {
        "floor" { [Math]::Floor($value) }
        "ceil" { [Math]::Ceiling($value) }
        "round" {
            if ($value -ge 0) { [Math]::Floor($value + 0.5) }
            else { [Math]::Ceiling($value - 0.5) }
        }
    }
    return @("i32.const $([int]$rounded)")
}

function Convert-WasmAstDecimalComparison {
    param($Node)

    if ($null -eq $Node -or [string]$Node.node -ne "BIN_OP") { return @() }
    $op = [string]$Node.op
    if ($op -notin @("==", "!=", "<", "<=", ">", ">=")) { return @() }
    $leftValues = @(Get-WasmAstDecimalConstant ($Node.left))
    $rightValues = @(Get-WasmAstDecimalConstant ($Node.right))
    if ($leftValues.Count -eq 0 -or $rightValues.Count -eq 0) { return @() }
    $left = [double]$leftValues[0]
    $right = [double]$rightValues[0]
    $matched = switch ($op) {
        "==" { $left -eq $right }
        "!=" { $left -ne $right }
        "<" { $left -lt $right }
        "<=" { $left -le $right }
        ">" { $left -gt $right }
        ">=" { $left -ge $right }
    }
    return @("i32.const $(if ($matched) { 1 } else { 0 })")
}

function Convert-WasmAstMembershipExpr {
    param($Node)

    if ($null -eq $Node -or [string]$Node.node -ne "BIN_OP" -or [string]$Node.op -ne "in") {
        return @()
    }

    $elementType = Get-WasmAstArrayElementTypeHint ($Node.right)
    $elementTag = Get-WasmAstValueTagForTypeName $elementType
    # Preserve the VM's left-to-right operand evaluation. The runtime helper
    # receives tagged Values and uses elementTag only for homogeneous raw
    # arrays; dynamic arrays already carry a tag for every element.
    return @(
        @(Convert-WasmAstValueExpr ($Node.left)) +
        @(Convert-WasmAstValueExpr ($Node.right)) +
        @("i32.const $elementTag", "call `$__sura_value_in")
    )
}

function Convert-WasmAstNumericExpr {
    param($Node)

    $typeName = Get-WasmAstKnownValueType $Node
    if ([string]::IsNullOrWhiteSpace($typeName)) {
        $typeName = Get-WasmAstStaticValueType $Node
    }
    if ($typeName -eq "value") {
        return @(Convert-WasmAstGuardedCallResult ([string[]]@(
            @(Convert-WasmAstValueExpr $Node) + @("call `$__sura_value_require_num")
        )))
    }
    if ($null -ne $Node -and [string]$Node.node -eq "BIN_OP" -and [string]$Node.op -eq "??" -and
        ((Test-WasmAstValueExprCandidate ($Node.left)) -or (Test-WasmAstValueExprCandidate ($Node.right)))) {
        return @(Convert-WasmAstGuardedCallResult ([string[]]@(
            @(Convert-WasmAstValueExpr $Node) + @("call `$__sura_value_require_num")
        )))
    }
    if ($null -ne $Node -and [string]$Node.node -eq "TERNARY" -and
        ((Test-WasmAstRuntimeValueIndexCandidate ($Node.then)) -or
         (Test-WasmAstRuntimeValueDotCandidate ($Node.then)) -or
         (Test-WasmAstRuntimeValueIndexCandidate ($Node.else)) -or
         (Test-WasmAstRuntimeValueDotCandidate ($Node.else)))) {
        return @(
            @(Convert-WasmAstConditionExpr ($Node.cond)) +
            @("if (result i32)") +
            @(Convert-WasmAstNumericExpr ($Node.then)) +
            @("else") +
            @(Convert-WasmAstNumericExpr ($Node.else)) +
            @("end")
        )
    }
    if ((Test-WasmAstRuntimeValueIndexCandidate $Node) -or (Test-WasmAstRuntimeValueDotCandidate $Node)) {
        return @(Convert-WasmAstGuardedCallResult ([string[]]@(
            @(Convert-WasmAstValueExpr $Node) + @("call `$__sura_value_require_num")
        )))
    }
    return @(Convert-WasmAstExpr $Node)
}

function Convert-WasmAstExpr {
    param($Node)
    if ($null -eq $Node) { return @("i32.const 0") }

    switch ([string]$Node.node) {
        "NUM_LIT" {
            $value = [double]$Node.value
            if ([double]::IsNaN($value) -or [double]::IsInfinity($value)) { throw "unsupported WASM numeric literal: $($Node.value)" }
            $intValue = [int][Math]::Truncate($value)
            return @("i32.const $intValue")
        }
        "BOOL_LIT" {
            if ([bool]$Node.value) { return @("i32.const 1") }
            return @("i32.const 0")
        }
        "NIL_LIT" {
            return @("i32.const 0")
        }
        "STR_LIT" {
            return @(Convert-WasmAstInterpolatedTextExpr ([string]$Node.value))
        }
        "IDENT" {
            $name = [string]$Node.name
            if ($script:wasmEnumConsts.ContainsKey($name)) {
                return @("i32.const $($script:wasmEnumConsts[$name])")
            }
            if ($script:wasmEnumStringConsts.ContainsKey($name)) {
                return @(New-WasmStringLiteralExprCode -Literal (Convert-WasmAstStringLiteral ($script:wasmEnumStringConsts[$name])))
            }
            if ($script:wasmAstFunctionDefs.ContainsKey($name)) {
                return @("i32.const $(Get-WasmStringKeyHash $name)")
            }
            return @(Convert-WasmAstNameLoad $name)
        }
        "DOT_ACCESS" {
            $prop = [string]$Node.prop
            if ([string]$Node.obj.node -eq "IDENT") {
                $root = [string]$Node.obj.name
                $enumKey = "$root.$prop"
                if ($script:wasmEnumConsts.ContainsKey($enumKey)) {
                    return @("i32.const $($script:wasmEnumConsts[$enumKey])")
                }
                if ($script:wasmEnumStringConsts.ContainsKey($enumKey)) {
                    return @(New-WasmStringLiteralExprCode -Literal (Convert-WasmAstStringLiteral ($script:wasmEnumStringConsts[$enumKey])))
                }
                if ($enumKey -eq "math.pi") {
                    return @("i32.const 3")
                }
            }
            if ($prop -eq "len") {
                $objCode = @(Convert-WasmAstExpr ($Node.obj))
                return @($objCode + @("i32.const 4", "i32.sub", "i32.load"))
            }
            $dictCode = @(Convert-WasmAstExpr ($Node.obj))
            return @($dictCode + @("i32.const $(Get-WasmStringKeyHash $prop)", "call `$__sura_dict_get"))
        }
        "INDEX" {
            $stringIndexResult = Get-WasmAstKnownStringIndexResult $Node
            if ($null -ne $stringIndexResult) {
                $sideEffectCode = @()
                if (Test-WasmAstEffectfulExpr ($Node.key)) {
                    $sideEffectCode = @(Convert-WasmAstExpr ($Node.key)) + @("drop")
                }
                if ([string]$stringIndexResult.Type -eq "nil") { return @($sideEffectCode + @("i32.const 0")) }
                return @($sideEffectCode + @(New-WasmStringLiteralExprCode -Literal (Convert-WasmAstStringLiteral ([string]$stringIndexResult.Value))))
            }
            $objCode = @(Convert-WasmAstExpr ($Node.obj))
            $objType = Get-WasmAstKnownValueType ($Node.obj)
            if ([string]::IsNullOrWhiteSpace($objType)) { $objType = Get-WasmAstStaticValueType ($Node.obj) }
            $receiverObjectClass = Get-WasmAstObjectClassTypeWithLocals ($Node.obj) $script:wasmCurrentLocalObjectClassHints $script:wasmCurrentClassContext @{}
            $indexedObjectClass = Get-WasmAstObjectClassTypeWithLocals $Node $script:wasmCurrentLocalObjectClassHints $script:wasmCurrentClassContext @{}
            if ($objType -eq "nil" -and
                [string]::IsNullOrWhiteSpace($receiverObjectClass) -and
                [string]::IsNullOrWhiteSpace($indexedObjectClass) -and
                $null -eq (Get-WasmAstExactIndexedAccessHint $Node) -and
                $null -eq (Get-WasmAstExactStringKeyAccessHint $Node)) {
                $sideEffectCode = @()
                if (Test-WasmAstEffectfulExpr ($Node.obj)) {
                    $sideEffectCode += @($objCode + @("drop"))
                }
                if (Test-WasmAstEffectfulExpr ($Node.key)) {
                    $sideEffectCode += @(Convert-WasmAstExpr ($Node.key)) + @("drop")
                }
                return @($sideEffectCode + @("i32.const 0"))
            }
            if ($null -ne $Node.key -and [string]$Node.key.node -eq "STR_LIT") {
                return @($objCode + @("i32.const $(Get-WasmStringKeyHash ([string]$Node.key.value))", "call `$__sura_dict_get"))
            }
            $keyType = Get-WasmAstKnownValueType ($Node.key)
            if ([string]::IsNullOrWhiteSpace($keyType)) { $keyType = Get-WasmAstStaticValueType ($Node.key) }
            $knownStringKey = Get-WasmAstKnownStringLiteralValue ($Node.key)
            if (-not [string]::IsNullOrWhiteSpace($knownStringKey) -and
                [string]$Node.key.node -ne "IDENT" -and
                $objType -notin @("array", "string")) {
                $keySideEffectCode = @()
                if (Test-WasmAstEffectfulExpr ($Node.key)) {
                    $keySideEffectCode = @(Convert-WasmAstStringExpr ($Node.key)) + @("drop")
                }
                return @($objCode + $keySideEffectCode + @("i32.const $(Get-WasmStringKeyHash $knownStringKey)", "call `$__sura_dict_get"))
            }
            $knownNumericIndex = Get-WasmAstKnownNumericLiteralValue ($Node.key)
            if ($null -ne $knownNumericIndex -and $objType -ne "dict") {
                $indexValue = [int][Math]::Truncate([double]$knownNumericIndex)
                $keySideEffectCode = @()
                if (Test-WasmAstEffectfulExpr ($Node.key)) {
                    $keySideEffectCode = @(Convert-WasmAstExpr ($Node.key)) + @("drop")
                }
                if ($objType -eq "string") {
                    return @($objCode + $keySideEffectCode + @("i32.const $indexValue", "call `$__sura_string_at"))
                }
                return @($objCode + $keySideEffectCode + @("i32.const $indexValue", "call `$__sura_array_get_checked"))
            }
            if ($keyType -eq "string" -and $objType -eq "dict") {
                $keyCode = @(Convert-WasmAstStringExpr ($Node.key))
                return @($objCode + $keyCode + @("call `$__sura_string_hash", "call `$__sura_dict_get"))
            }
            if ($keyType -eq "string") {
                $exactStringKeyHint = Get-WasmAstExactStringKeyAccessHint $Node
                if ($null -ne $exactStringKeyHint) {
                    $keySideEffectCode = @()
                    if (Test-WasmAstEffectfulExpr ($Node.key)) {
                        $keySideEffectCode = @(Convert-WasmAstStringExpr ($Node.key)) + @("drop")
                    }
                    return @($objCode + $keySideEffectCode + @("i32.const $(Get-WasmStringKeyHash ([string]$exactStringKeyHint.Key))", "call `$__sura_dict_get"))
                }
                if ($objType -notin @("array", "string")) {
                    $keyCode = @(Convert-WasmAstStringExpr ($Node.key))
                    return @($objCode + $keyCode + @("call `$__sura_string_hash", "call `$__sura_dict_get"))
                }
            }
            if ($objType -eq "string" -and $keyType -ne "string") {
                $keyCode = @(Convert-WasmAstExpr ($Node.key))
                if ($keyType -eq "value") {
                    $keyCode += "call `$__sura_value_as_i32"
                }
                return @($objCode + $keyCode + @("call `$__sura_string_at"))
            }
            $keyCode = @(Convert-WasmAstExpr ($Node.key))
            if ($keyType -eq "value") {
                $keyCode += "call `$__sura_value_as_i32"
            }
            return @($objCode + $keyCode + @("call `$__sura_array_get_checked"))
        }
        "ARRAY_LIT" {
            $argCodes = New-Object System.Collections.Generic.List[object]
            foreach ($item in @(As-WasmAstArray ($Node.elements))) {
                $argCodes.Add([string[]]@(Convert-WasmAstExpr $item)) | Out-Null
            }
            return @(New-WasmArrayLiteralExprCode -ArgCodes @($argCodes.ToArray()))
        }
        "DICT_LIT" {
            $entries = New-Object System.Collections.Generic.List[object]
            foreach ($entry in @(As-WasmAstArray ($Node.entries))) {
                $entries.Add([pscustomobject]@{
                    Key = [string]$entry.key
                    Hash = Get-WasmStringKeyHash ([string]$entry.key)
                    ValueCode = [string[]]@(Convert-WasmAstExpr ($entry.value))
                }) | Out-Null
            }
            return @(New-WasmDictLiteralExprCode -Entries ([object[]]$entries.ToArray()))
        }
        "WASM_OBJECT_REGISTER" {
            $className = [string]$Node.class_name
            $classId = Get-WasmClassDispatchId $className
            if ($classId -le 0) {
                throw "unsupported WASM AST object registration for unknown class: $className"
            }
            return @(Convert-WasmAstExpr ($Node.value)) + @("i32.const $classId", "call `$__sura_object_register")
        }
        "FUNC_EXPR" {
            $liftName = Get-WasmAstFuncExprLiftName $Node
            if ([string]::IsNullOrWhiteSpace($liftName)) {
                throw "unsupported WASM AST inline function expression value outside lifted promotion"
            }
            return @("i32.const $(Get-WasmStringKeyHash $liftName)")
        }
        "NEW_EXPR" {
            $className = [string]$Node.class_name
            if (-not $script:wasmClassDefs.ContainsKey($className)) {
                throw "unsupported WASM AST new expression for unknown class: $className"
            }
            $classInfo = $script:wasmClassDefs[$className]
            if (-not (Test-WasmAstClassSupported -ClassName $className)) {
                throw "unsupported WASM AST new expression for unsupported class: $className"
            }
            $init = Get-WasmAstClassInitMethod ($classInfo.Node)
            $ctorParams = if ($null -ne $init) { [string[]]@(Get-WasmAstParamNames ($init.params)) } else { [string[]]@() }
            $joinedArgs = @(Convert-WasmAstObservedCallArgs -TargetName ([string]$classInfo.ConstructorName) -Params $ctorParams -InputArgs ($Node.args))
            return @(Convert-WasmAstGuardedCallResult ([string[]]@($joinedArgs + @("call `$$($classInfo.ConstructorName)"))))
        }
        "BIN_OP" {
            $op = [string]$Node.op
            if ($op -eq "??") {
                $typeName = Get-WasmAstKnownValueType $Node
                if ([string]::IsNullOrWhiteSpace($typeName)) {
                    $typeName = Get-WasmAstStaticValueType $Node
                }
                if ($typeName -eq "string") {
                    return @(Convert-WasmAstStringExpr $Node)
                }
                if ($typeName -in @("num", "bool")) {
                    return @(Convert-WasmAstValueExpr $Node) + @("call `$__sura_value_as_i32")
                }
                if ($typeName -in @("array", "dict", "function")) {
                    return @(Convert-WasmAstValueExpr $Node) + @("call `$__sura_value_payload")
                }
                if (Test-WasmAstStringExprCandidate $Node) {
                    return @(Convert-WasmAstStringExpr $Node)
                }
                return @(
                    @(Convert-WasmAstExpr ($Node.left)) +
                    @("local.set `$__sura_wasm_value_tmp", "local.get `$__sura_wasm_value_tmp", "if (result i32)", "local.get `$__sura_wasm_value_tmp", "else") +
                    @(Convert-WasmAstExpr ($Node.right)) +
                    @("end")
                )
            }
            if ($op -eq "in") {
                return @(Convert-WasmAstMembershipExpr $Node)
            }
            if (Test-WasmAstBitwiseValueExprCandidate $Node) {
                $bitwiseOp = switch ($op) {
                    "&" { 0 }
                    "|" { 1 }
                    "^" { 2 }
                    "<<" { 3 }
                    ">>" { 4 }
                    default { throw "unsupported checked WASM bitwise operator: $op" }
                }
                return @(Convert-WasmAstGuardedCallResult ([string[]]@(
                    @(Convert-WasmAstValueExpr ($Node.left)) +
                    @(Convert-WasmAstValueExpr ($Node.right)) +
                    @("i32.const $bitwiseOp", "call `$__sura_value_bitwise")
                )))
            }
            $decimalComparison = @(Convert-WasmAstDecimalComparison $Node)
            if ($decimalComparison.Count -gt 0) { return $decimalComparison }
            $leftStringish = (Test-WasmAstStringExprCandidate ($Node.left))
            $rightStringish = (Test-WasmAstStringExprCandidate ($Node.right))
            $leftType = Get-WasmAstKnownValueType ($Node.left)
            if ([string]::IsNullOrWhiteSpace($leftType)) { $leftType = Get-WasmAstStaticValueType ($Node.left) }
            $rightType = Get-WasmAstKnownValueType ($Node.right)
            if ([string]::IsNullOrWhiteSpace($rightType)) { $rightType = Get-WasmAstStaticValueType ($Node.right) }
            if ($op -eq "+" -and $leftType -eq "array" -and $rightType -eq "array") {
                return @(Convert-WasmAstExpr ($Node.left)) +
                    @(Convert-WasmAstExpr ($Node.right)) +
                    @("call `$__sura_array_concat2")
            }
            if ($op -eq "+" -and
                ($leftStringish -or $rightStringish)) {
                return @(Convert-WasmAstStringExpr $Node)
            }
            $dynamicNumericOperands = ($op -eq "/" -or
                ($op -in @("+", "-", "*", "%") -and
                 ((Test-WasmAstDynamicNumericValueExpr ($Node.left)) -or (Test-WasmAstDynamicNumericValueExpr ($Node.right)))))
            if ($dynamicNumericOperands) {
                if ($op -eq "+") {
                    return @(Convert-WasmAstDynamicAddOperandValueExpr ($Node.left)) +
                        @(Convert-WasmAstDynamicAddOperandValueExpr ($Node.right)) +
                        @("call `$__sura_value_add")
                }
                $dynamicHelper = switch ($op) {
                    "-" { "__sura_value_sub" }
                    "*" { "__sura_value_mul" }
                    "/" { "__sura_value_div" }
                    "%" { "__sura_value_mod" }
                    default { throw "unsupported WASM AST dynamic numeric operator: $op" }
                }
                return @(Convert-WasmAstGuardedCallResult ([string[]]@(
                    @(Convert-WasmAstValueExpr ($Node.left)) +
                    @(Convert-WasmAstValueExpr ($Node.right)) +
                    @("call `$$dynamicHelper")
                )))
            }
            if ($op -in @("and", "or")) {
                return @(Convert-WasmAstConditionExpr $Node)
            }
            if ($op -in @("<", "<=", ">", ">=") -and
                ((Test-WasmAstDynamicNumericValueExpr ($Node.left)) -or (Test-WasmAstDynamicNumericValueExpr ($Node.right)))) {
                $comparisonOp = switch ($op) {
                    "<" { 0 }
                    "<=" { 1 }
                    ">" { 2 }
                    ">=" { 3 }
                }
                return @(Convert-WasmAstGuardedCallResult ([string[]]@(
                    @(Convert-WasmAstValueExpr ($Node.left)) +
                    @(Convert-WasmAstValueExpr ($Node.right)) +
                    @("i32.const $comparisonOp", "call `$__sura_value_numeric_compare")
                )))
            }
            if ($op -in @("==", "!=") -and ($leftStringish -or $rightStringish) -and
                ((Test-WasmAstStringAccessExprCandidate ($Node.left)) -or (Test-WasmAstStringAccessExprCandidate ($Node.right)))) {
                $valueEq = @(Convert-WasmAstValueEqualityExpr ($Node.left) ($Node.right))
                if ($op -eq "!=") { return @($valueEq + @("i32.eqz")) }
                return $valueEq
            }
            if ($op -in @("==", "!=") -and
                ((Test-WasmAstValueExprCandidate ($Node.left)) -or (Test-WasmAstValueExprCandidate ($Node.right)))) {
                $valueEq = @(Convert-WasmAstValueEqualityExpr ($Node.left) ($Node.right))
                if ($op -eq "!=") { return @($valueEq + @("i32.eqz")) }
                return $valueEq
            }
            $left = @(Convert-WasmAstNumericExpr ($Node.left))
