                        default { "__sura_value_array_max" }
                    }
                    return @(Convert-WasmAstValueExpr ($Node.obj)) + @("call `$$helper")
                }
                if (($receiverType -eq "value" -or
                    (Test-WasmAstRuntimeValueIndexCandidate ($Node.obj)) -or
                    (Test-WasmAstRuntimeValueDotCandidate ($Node.obj))) -and $args.Count -eq 1) {
                    if ($method -in @("index_of", "indexOf", "index")) {
                        return @(Convert-WasmAstValueExpr ($Node.obj)) + @(Convert-WasmAstValueExpr ($args[0])) + @("call `$__sura_value_receiver_index_of")
                    }
                    if ($method -in @("contains", "includes")) {
                        return @(Convert-WasmAstValueExpr ($Node.obj)) + @(Convert-WasmAstValueExpr ($args[0])) + @("call `$__sura_value_receiver_contains")
                    }
                    if ($method -eq "has") {
                        return @(Convert-WasmAstValueExpr ($Node.obj)) + @(Convert-WasmAstValueExpr ($args[0])) + @("call `$__sura_value_receiver_has")
                    }
                }
                $stringReceiverIntrinsic = @(Convert-WasmAstStringReceiverMethodCall -Receiver ($Node.obj) -Method $method -InputArgs $args)
                if ($stringReceiverIntrinsic.Count -gt 0) { return $stringReceiverIntrinsic }
                if ($method -eq "split" -and $args.Count -eq 1) {
                    $splitReceiverType = Get-WasmAstKnownValueType ($Node.obj)
                    if ([string]::IsNullOrWhiteSpace($splitReceiverType)) { $splitReceiverType = Get-WasmAstStaticValueType ($Node.obj) }
                    if ($splitReceiverType -eq "string" -or (Test-WasmAstStringExprCandidate ($Node.obj))) {
                        return @(Convert-WasmAstStringExpr ($Node.obj)) + @(Convert-WasmAstStringExpr ($args[0])) + @("call `$__sura_string_split")
                    }
                }
                if ($receiverType -eq "array") {
                    if ($method -eq "push" -and $args.Count -eq 1) {
                        return @(Convert-WasmAstExpr ($Node.obj)) + @(Convert-WasmAstExpr ($args[0])) + @("call `$__sura_array_push")
                    }
                    if ($method -eq "pop" -and $args.Count -eq 0) {
                        return @(Convert-WasmAstExpr ($Node.obj)) + @("call `$__sura_array_pop")
                    }
                    if ($method -eq "reverse" -and $args.Count -eq 0) {
                        return @(Convert-WasmAstExpr ($Node.obj)) + @("call `$__sura_array_reverse")
                    }
                    if ($method -eq "sort" -and $args.Count -eq 0) {
                        return @(Convert-WasmAstExpr ($Node.obj)) + @("call `$__sura_array_sort")
                    }
                    if ($method -eq "unique" -and $args.Count -eq 0) {
                        return @(Convert-WasmAstExpr ($Node.obj)) + @("call `$__sura_array_unique")
                    }
                    if ($method -eq "flatten" -and $args.Count -eq 0) {
                        return @(Convert-WasmAstExpr ($Node.obj)) + @("call `$__sura_array_flatten1")
                    }
                    if ($method -eq "clear" -and $args.Count -eq 0) {
                        return @(Convert-WasmAstExpr ($Node.obj)) + @("call `$__sura_array_clear")
                    }
                    if ($method -eq "insert" -and $args.Count -eq 2) {
                        return @(Convert-WasmAstExpr ($Node.obj)) + @(Convert-WasmAstExpr ($args[0])) + @(Convert-WasmAstExpr ($args[1])) + @("call `$__sura_array_insert")
                    }
                    if ($method -eq "remove" -and $args.Count -eq 1) {
                        $elementType = Get-WasmAstArrayElementTypeHint ($Node.obj)
                        $valueTag = switch ($elementType) {
                            "nil" { 0 }
                            "num" { 1 }
                            "bool" { 2 }
                            "string" { 3 }
                            "array" { 4 }
                            "dict" { 5 }
                            "object" { 6 }
                            "function" { 7 }
                            "value" { -1 }
                            default { 1 }
                        }
                        return @(Convert-WasmAstExpr ($Node.obj)) + @(Convert-WasmAstExpr ($args[0])) + @("i32.const $valueTag", "call `$__sura_array_remove")
                    }
                    if ($method -eq "join" -and $args.Count -eq 1) {
                        $elementType = Get-WasmAstArrayElementTypeHint ($Node.obj)
                        $helper = switch ($elementType) {
                            "num" { "__sura_array_join_num" }
                            "string" { "__sura_array_join_string" }
                            "bool" { "__sura_array_join_bool" }
                            "nil" { "__sura_array_join_nil" }
                            default { "" }
                        }
                        if (-not [string]::IsNullOrWhiteSpace($helper)) {
                            return @(Convert-WasmAstExpr ($Node.obj)) + @(Convert-WasmAstStringExpr ($args[0])) + @("call `$$helper")
                        }
                    }
                    if ($method -in @("len", "length", "size") -and $args.Count -eq 0) {
                        return @(Convert-WasmAstExpr ($Node.obj)) + @("i32.const 4", "i32.sub", "i32.load")
                    }
                    if ($method -in @("sum", "avg", "average", "min", "max") -and $args.Count -eq 0) {
                        $helper = switch ($method) {
                            "sum" { "__sura_array_sum" }
                            { $_ -in @("avg", "average") } { "__sura_array_avg" }
                            "min" { "__sura_array_min" }
                            default { "__sura_array_max" }
                        }
                        return @(Convert-WasmAstExpr ($Node.obj)) + @("call `$$helper")
                    }
                    if ($method -in @("index_of", "indexOf", "index") -and $args.Count -eq 1) {
                        return @(Convert-WasmAstExpr ($Node.obj)) + @(Convert-WasmAstExpr ($args[0])) + @("call `$__sura_array_index_of")
                    }
                    if ($method -in @("contains", "includes") -and $args.Count -eq 1) {
                        return @(Convert-WasmAstExpr ($Node.obj)) + @(Convert-WasmAstExpr ($args[0])) + @("call `$__sura_array_contains")
                    }
                    if ($method -eq "slice" -and $args.Count -in @(1, 2)) {
                        $endCode = if ($args.Count -eq 2) { @(Convert-WasmAstExpr ($args[1])) } else { @("i32.const 2147483647") }
                        return @(Convert-WasmAstExpr ($Node.obj)) + @(Convert-WasmAstExpr ($args[0])) + $endCode + @("call `$__sura_array_slice")
                    }
                }
                if ($receiverType -eq "dict") {
                    if ($method -in @("has", "contains") -and $args.Count -eq 1) {
                        return @(Convert-WasmAstExpr ($Node.obj)) + @(Convert-WasmAstStringExpr ($args[0])) + @("call `$__sura_string_hash", "call `$__sura_dict_has")
                    }
                    if ($method -eq "keys" -and $args.Count -eq 0) {
                        return @(Convert-WasmAstExpr ($Node.obj)) + @("call `$__sura_dict_keys")
                    }
                    if ($method -eq "values" -and $args.Count -eq 0) {
                        return @(Convert-WasmAstExpr ($Node.obj)) + @("call `$__sura_dict_values")
                    }
                    if ($method -eq "items" -and $args.Count -eq 0) {
                        return @(Convert-WasmAstExpr ($Node.obj)) + @("call `$__sura_dict_items")
                    }
                    if ($method -eq "pick" -and $args.Count -eq 1) {
                        return @(Convert-WasmAstExpr ($Node.obj)) + @(Convert-WasmAstExpr ($args[0])) + @("call `$__sura_dict_pick")
                    }
                    if ($method -eq "omit" -and $args.Count -eq 1) {
                        return @(Convert-WasmAstExpr ($Node.obj)) + @(Convert-WasmAstExpr ($args[0])) + @("call `$__sura_dict_omit")
                    }
                    if ($method -eq "merge" -and $args.Count -ge 1) {
                        $code = @(Convert-WasmAstExpr ($Node.obj))
                        foreach ($mergeArg in $args) {
                            $code = @($code + @(Convert-WasmAstExpr $mergeArg) + @("call `$__sura_dict_merge2"))
                        }
                        return $code
                    }
                }
                if ((Test-WasmAstRuntimeValueIndexCandidate ($Node.obj)) -or (Test-WasmAstRuntimeValueDotCandidate ($Node.obj))) {
                    $valueStringCode = @(Convert-WasmAstValueExpr ($Node.obj)) + @("call `$__sura_value_to_string")
                    if ($method -in @("upper", "lower", "trim") -and $args.Count -eq 0) {
                        $helper = switch ($method) {
                            "upper" { "__sura_string_upper" }
                            "lower" { "__sura_string_lower" }
                            default { "__sura_string_trim" }
                        }
                        return @($valueStringCode + @("call `$$helper"))
                    }
                    if ($method -in @("contains", "startsWith", "starts_with", "endsWith", "ends_with") -and $args.Count -eq 1) {
                        $helper = switch ($method) {
                            "contains" { "__sura_string_contains" }
                            { $_ -in @("startsWith", "starts_with") } { "__sura_string_starts_with" }
                            default { "__sura_string_ends_with" }
                        }
                        return @($valueStringCode + @(Convert-WasmAstStringExpr ($args[0])) + @("call `$$helper"))
                    }
                    if ($method -in @("indexOf", "index_of") -and $args.Count -eq 1) {
                        return @($valueStringCode + @(Convert-WasmAstStringExpr ($args[0])) + @("call `$__sura_string_index_of"))
                    }
                    if ($method -eq "replace" -and $args.Count -eq 2) {
                        return @($valueStringCode + @(Convert-WasmAstStringExpr ($args[0])) + @(Convert-WasmAstStringExpr ($args[1])) + @("call `$__sura_string_replace"))
                    }
                    if ($method -eq "repeat" -and $args.Count -eq 1) {
                        return @($valueStringCode + @(Convert-WasmAstExpr ($args[0])) + @("call `$__sura_string_repeat"))
                    }
                    if ($method -in @("pad_left", "pad_right") -and $args.Count -in @(1, 2)) {
                        $helper = if ($method -eq "pad_left") { "__sura_string_pad_left" } else { "__sura_string_pad_right" }
                        $fillCode = if ($args.Count -eq 2) { @(Convert-WasmAstStringExpr ($args[1])) } else { @(New-WasmStringLiteralExprCode -Literal '" "') }
                        return @($valueStringCode + @(Convert-WasmAstExpr ($args[0])) + $fillCode + @("call `$$helper"))
                    }
                    if ($method -eq "lines" -and $args.Count -eq 0) {
                        return @($valueStringCode + @("call `$__sura_string_lines"))
                    }
                    if ($method -eq "words" -and $args.Count -eq 0) {
                        return @($valueStringCode + @("call `$__sura_string_words"))
                    }
                    if ($method -eq "chunks" -and $args.Count -in @(0, 1, 2)) {
                        $maxCode = if ($args.Count -ge 1) { @(Convert-WasmAstExpr ($args[0])) } else { @("i32.const 800") }
                        $overlapCode = if ($args.Count -ge 2) { @(Convert-WasmAstExpr ($args[1])) } else { @("i32.const 0") }
                        return @($valueStringCode + $maxCode + $overlapCode + @("call `$__sura_text_chunks"))
                    }
                    if ($method -in @("substring", "slice", "sub") -and $args.Count -in @(1, 2)) {
                        $helper = if ($method -eq "substring") { "__sura_string_substring" } else { "__sura_string_slice" }
                        $endCode = if ($args.Count -eq 2) { @(Convert-WasmAstExpr ($args[1])) } else { @("i32.const 2147483647") }
                        return @($valueStringCode + @(Convert-WasmAstExpr ($args[0])) + $endCode + @("call `$$helper"))
                    }
                }
                if ($receiverType -eq "string") {
                    if ($method -in @("upper", "lower", "trim") -and $args.Count -eq 0) {
                        $helper = switch ($method) {
                            "upper" { "__sura_string_upper" }
                            "lower" { "__sura_string_lower" }
                            default { "__sura_string_trim" }
                        }
                        return @(Convert-WasmAstStringExpr ($Node.obj)) + @("call `$$helper")
                    }
                    if ($method -in @("contains", "startsWith", "starts_with", "endsWith", "ends_with") -and $args.Count -eq 1) {
                        $helper = switch ($method) {
                            "contains" { "__sura_string_contains" }
                            { $_ -in @("startsWith", "starts_with") } { "__sura_string_starts_with" }
                            default { "__sura_string_ends_with" }
                        }
                        return @(Convert-WasmAstStringExpr ($Node.obj)) + @(Convert-WasmAstStringExpr ($args[0])) + @("call `$$helper")
                    }
                    if ($method -in @("indexOf", "index_of") -and $args.Count -eq 1) {
                        return @(Convert-WasmAstStringExpr ($Node.obj)) + @(Convert-WasmAstStringExpr ($args[0])) + @("call `$__sura_string_index_of")
                    }
                    if ($method -eq "replace" -and $args.Count -eq 2) {
                        return @(Convert-WasmAstStringExpr ($Node.obj)) + @(Convert-WasmAstStringExpr ($args[0])) + @(Convert-WasmAstStringExpr ($args[1])) + @("call `$__sura_string_replace")
                    }
                    if ($method -eq "repeat" -and $args.Count -eq 1) {
                        return @(Convert-WasmAstStringExpr ($Node.obj)) + @(Convert-WasmAstExpr ($args[0])) + @("call `$__sura_string_repeat")
                    }
                    if ($method -in @("pad_left", "pad_right") -and $args.Count -in @(1, 2)) {
                        $helper = if ($method -eq "pad_left") { "__sura_string_pad_left" } else { "__sura_string_pad_right" }
                        $fillCode = if ($args.Count -eq 2) { @(Convert-WasmAstStringExpr ($args[1])) } else { @(New-WasmStringLiteralExprCode -Literal '" "') }
                        return @(Convert-WasmAstStringExpr ($Node.obj)) + @(Convert-WasmAstExpr ($args[0])) + $fillCode + @("call `$$helper")
                    }
                    if ($method -eq "lines" -and $args.Count -eq 0) {
                        return @(Convert-WasmAstStringExpr ($Node.obj)) + @("call `$__sura_string_lines")
                    }
                    if ($method -eq "words" -and $args.Count -eq 0) {
                        return @(Convert-WasmAstStringExpr ($Node.obj)) + @("call `$__sura_string_words")
                    }
                    if ($method -eq "chunks" -and $args.Count -in @(0, 1, 2)) {
                        $maxCode = if ($args.Count -ge 1) { @(Convert-WasmAstExpr ($args[0])) } else { @("i32.const 800") }
                        $overlapCode = if ($args.Count -ge 2) { @(Convert-WasmAstExpr ($args[1])) } else { @("i32.const 0") }
                        return @(Convert-WasmAstStringExpr ($Node.obj)) + $maxCode + $overlapCode + @("call `$__sura_text_chunks")
                    }
                    if ($method -in @("substring", "slice", "sub") -and $args.Count -in @(1, 2)) {
                        $helper = if ($method -eq "substring") { "__sura_string_substring" } else { "__sura_string_slice" }
                        $endCode = if ($args.Count -eq 2) { @(Convert-WasmAstExpr ($args[1])) } else { @("i32.const 2147483647") }
                        return @(Convert-WasmAstStringExpr ($Node.obj)) + @(Convert-WasmAstExpr ($args[0])) + $endCode + @("call `$$helper")
                    }
                }
            }
            if ($method -in @("len", "length", "size") -and $args.Count -eq 0) {
                $lenReceiverType = Get-WasmAstKnownValueType ($Node.obj)
                if ([string]::IsNullOrWhiteSpace($lenReceiverType)) { $lenReceiverType = Get-WasmAstStaticValueType ($Node.obj) }
                if ($lenReceiverType -eq "value" -or
                    (Test-WasmAstRuntimeValueIndexCandidate ($Node.obj)) -or
                    (Test-WasmAstRuntimeValueDotCandidate ($Node.obj))) {
                    return @(Convert-WasmAstValueExpr ($Node.obj)) + @("call `$__sura_value_length")
                }
                $objCode = @(Convert-WasmAstExpr ($Node.obj))
                return @($objCode + @("i32.const 4", "i32.sub", "i32.load"))
            }
            if ($null -ne $Node.obj) {
                if ($method -eq "chunks" -and $args.Count -in @(0, 1, 2) -and -not (
                    [string]$Node.obj.node -eq "IDENT" -and [string]$Node.obj.name -in @("array", "dict", "math", "vector", "string", "set"))) {
                    $maxCode = if ($args.Count -ge 1) { @(Convert-WasmAstExpr ($args[0])) } else { @("i32.const 800") }
                    $overlapCode = if ($args.Count -ge 2) { @(Convert-WasmAstExpr ($args[1])) } else { @("i32.const 0") }
                    return @(Convert-WasmAstStringExpr ($Node.obj)) + $maxCode + $overlapCode + @("call `$__sura_text_chunks")
                }
                $className = Get-WasmAstObjectClassTypeWithLocals ($Node.obj) $script:wasmCurrentLocalObjectClassHints $script:wasmCurrentClassContext @{}
                if (-not [string]::IsNullOrWhiteSpace($className)) {
                    $methodInfo = Get-WasmAstClassMethod -ClassName $className -MethodName $method
                    if ($null -ne $methodInfo) {
                        $methodParams = [string[]]@(Get-WasmAstParamNames ($methodInfo.Method.params))
                        $joinedArgs = @(Convert-WasmAstExpr ($Node.obj)) +
                            @(Convert-WasmAstObservedCallArgs -TargetName ([string]$methodInfo.FunctionName) -Params $methodParams -InputArgs ($Node.args))
                        return @(Convert-WasmAstGuardedCallResult ([string[]]@($joinedArgs + @("call `$$($methodInfo.FunctionName)"))))
                    }
                }

                $isModuleReceiver = ([string]$Node.obj.node -eq "IDENT" -and
                    [string]$Node.obj.name -in @("array", "dict", "math", "vector", "string", "set"))
                if (-not $isModuleReceiver) {
                    $receiverClassSetHint = Get-WasmAstObjectClassSetHintWithLocals ($Node.obj) $script:wasmCurrentLocalObjectClassHints $script:wasmCurrentClassContext
                    $possibleClasses = @(Get-WasmAstObjectClassNamesFromHint $receiverClassSetHint)
                    $dynamicCandidates = @(Get-WasmAstDynamicMethodCandidates -MethodName $method -Arity $args.Count |
                        Where-Object { [string]$_.ClassName -in $possibleClasses })
                    $dispatchName = Get-WasmMethodDispatchName -MethodName $method -Arity $args.Count
                    if ($dynamicCandidates.Count -gt 0 -and -not [string]::IsNullOrWhiteSpace($dispatchName)) {
                        $argCodes = New-Object System.Collections.Generic.List[object]
                        $argCodes.Add([string[]]@(Convert-WasmAstExpr ($Node.obj))) | Out-Null
                        foreach ($arg in $args) {
                            $argCodes.Add([string[]]@(Convert-WasmAstExpr $arg)) | Out-Null
                        }
                        $joinedArgs = @(Join-WasmArgCodes -ArgCodes ([object[]]$argCodes.ToArray()))
                        return @(Convert-WasmAstGuardedCallResult ([string[]]@($joinedArgs + @("call `$$dispatchName"))))
                    }
                }
            }
            $argCodes = New-Object System.Collections.Generic.List[object]
            $argCodes.Add([string[]]@(Convert-WasmAstExpr ($Node.obj))) | Out-Null
            foreach ($arg in $args) {
                $argCodes.Add([string[]]@(Convert-WasmAstExpr $arg)) | Out-Null
            }
            $intrinsic = Emit-WasmIntrinsicCall -Name $method -ArgCodes ([object[]]$argCodes.ToArray())
            if ($null -ne $intrinsic) { return @($intrinsic) }
            $where = if ([string]::IsNullOrWhiteSpace($script:wasmCurrentFunctionName)) { "" } else { " in $script:wasmCurrentFunctionName" }
            $lineInfo = if ($Node.PSObject.Properties.Name -contains "line") { " at line $([int]$Node.line)" } else { "" }
            $receiverTypeInfo = if ($null -eq $Node.obj) { "nil" } else {
                $knownReceiverType = Get-WasmAstKnownValueType ($Node.obj)
                $staticReceiverType = Get-WasmAstStaticValueType ($Node.obj)
                $receiverName = if ([string]$Node.obj.node -eq "IDENT") { [string]$Node.obj.name } else { "" }
                $localReceiverType = if (-not [string]::IsNullOrWhiteSpace($receiverName) -and $script:wasmCurrentLocalValueTypeHints.ContainsKey($receiverName)) { [string]$script:wasmCurrentLocalValueTypeHints[$receiverName] } else { "" }
                $globalReceiverType = if (-not [string]::IsNullOrWhiteSpace($receiverName) -and $script:wasmValueTypeHints.ContainsKey($receiverName)) { [string]$script:wasmValueTypeHints[$receiverName] } else { "" }
                $globalReceiverConflict = (-not [string]::IsNullOrWhiteSpace($receiverName) -and $script:wasmConflictedValueTypeHints.ContainsKey($receiverName))
                "name=$receiverName, known=$knownReceiverType, static=$staticReceiverType, local=$localReceiverType, global=$globalReceiverType, conflicted=$globalReceiverConflict"
            }
            throw "unsupported WASM AST method call${where}${lineInfo}: $method (receiver $receiverTypeInfo)"
        }
        "SUPER_CALL" {
            $method = [string]$Node.method
            if ([string]::IsNullOrWhiteSpace($script:wasmCurrentClassContext)) {
                throw "WASM AST super call outside class method: $method"
            }
            if ($method -eq "init") {
                throw "WASM AST super.init is only supported inside constructors"
            }
            $methodInfo = Get-WasmAstSuperClassMethod -ClassName $script:wasmCurrentClassContext -MethodName $method
            if ($null -eq $methodInfo) {
                throw "unsupported WASM AST super method call: $method"
            }
            $superParams = [string[]]@(Get-WasmAstParamNames ($methodInfo.Method.params))
            $joinedArgs = @("local.get `$self") +
                @(Convert-WasmAstObservedCallArgs -TargetName ([string]$methodInfo.FunctionName) -Params $superParams -InputArgs ($Node.args))
            return @(Convert-WasmAstGuardedCallResult ([string[]]@($joinedArgs + @("call `$$($methodInfo.FunctionName)"))))
        }
        "TERNARY" {
            $condCode = @(Convert-WasmAstConditionExpr ($Node.cond))
            $thenCode = @(Convert-WasmAstExpr ($Node.then))
            $elseCode = @(Convert-WasmAstExpr ($Node.else))
            return @(
                $condCode +
                @("if (result i32)") +
                $thenCode +
                @("else") +
                $elseCode +
                @("end")
            )
        }
        "STR_INTERP" {
            return @(Convert-WasmAstStringInterpolationNode $Node)
        }
        default {
            throw "unsupported WASM AST expression node: $($Node.node)"
        }
    }
}

function Add-WasmAstAssert {
    param(
        [string]$Name,
        $InputArgs,
        [System.Collections.Generic.List[string]]$Out,
        [string]$Indent
    )
    $cmdArgs = @(As-WasmAstArray $InputArgs)
    if ($Name -eq "assert_neq") { $Name = "assert_ne" }

    if ($Name -eq "assert") {
        if ($cmdArgs.Count -lt 1) { throw "assert requires a condition" }
        Add-Code $Out @(Convert-WasmAstConditionExpr ($cmdArgs[0])) $Indent
        $Out.Add("${Indent}i32.eqz")
    } elseif ($Name -eq "assert_type") {
        if ($cmdArgs.Count -lt 2) { throw "assert_type requires a value and expected type name" }
        $actualTypeName = Get-WasmAstRuntimeTypeName ($cmdArgs[0])
        Add-Code $Out @(Convert-WasmAstExpr ($cmdArgs[0])) $Indent
        $Out.Add("${Indent}drop")
        Add-Code $Out @(New-WasmStringLiteralExprCode -Literal (Convert-WasmAstStringLiteral $actualTypeName)) $Indent
        Add-Code $Out @(Convert-WasmAstStringExpr ($cmdArgs[1])) $Indent
        $Out.Add("${Indent}call `$__sura_string_eq")
        $Out.Add("${Indent}i32.eqz")
    } elseif ($Name -eq "assert_len") {
        if ($cmdArgs.Count -lt 2) { throw "assert_len requires a value and expected length" }
        Add-Code $Out @(Convert-WasmAstLengthExpr ($cmdArgs[0])) $Indent
        Add-Code $Out @(Convert-WasmAstI32NumericExpr ($cmdArgs[1])) $Indent
        $Out.Add("${Indent}i32.ne")
    } elseif ($Name -eq "assert_between") {
        if ($cmdArgs.Count -lt 3) { throw "assert_between requires value, min, and max numeric expressions" }
        Add-Code $Out @(Convert-WasmAstI32NumericExpr ($cmdArgs[0])) $Indent
        Add-Code $Out @(Convert-WasmAstI32NumericExpr ($cmdArgs[1])) $Indent
        $Out.Add("${Indent}i32.lt_s")
        Add-Code $Out @(Convert-WasmAstI32NumericExpr ($cmdArgs[0])) $Indent
        Add-Code $Out @(Convert-WasmAstI32NumericExpr ($cmdArgs[2])) $Indent
        $Out.Add("${Indent}i32.gt_s")
        $Out.Add("${Indent}i32.or")
    } elseif ($Name -eq "assert_approx") {
        if ($cmdArgs.Count -lt 2) { throw "assert_approx requires actual and expected numeric expressions" }
        $actualCode = @(Convert-WasmAstI32NumericExpr ($cmdArgs[0]))
        $expectedCode = @(Convert-WasmAstI32NumericExpr ($cmdArgs[1]))
        $diff = @($actualCode + $expectedCode + @("i32.sub"))
        Add-Code $Out @(New-WasmAbsCode -X $diff) $Indent
        if ($cmdArgs.Count -ge 3) { Add-Code $Out @(Convert-WasmAstI32NumericExpr ($cmdArgs[2])) $Indent } else { $Out.Add("${Indent}i32.const 0") }
        $Out.Add("${Indent}i32.gt_s")
    } else {
        if ($cmdArgs.Count -lt 2) { throw "$Name requires two numeric expressions" }
        if (Test-WasmAstValueEqualityCandidate ($cmdArgs[0]) ($cmdArgs[1])) {
            Add-Code $Out @(Convert-WasmAstValueEqualityExpr ($cmdArgs[0]) ($cmdArgs[1])) $Indent
            if ($Name -eq "assert_eq") { $Out.Add("${Indent}i32.eqz") }
        } else {
            Add-Code $Out @(Convert-WasmAstExpr ($cmdArgs[0])) $Indent
            Add-Code $Out @(Convert-WasmAstExpr ($cmdArgs[1])) $Indent
            if ($Name -eq "assert_eq") { $Out.Add("${Indent}i32.ne") } else { $Out.Add("${Indent}i32.eq") }
        }
    }
    $Out.Add("${Indent}if")
    $Out.Add("${Indent}  unreachable")
    $Out.Add("${Indent}end")
}

function Get-WasmAstLoweredExprResultType {
    param(
        $Node,
        [string[]]$Code,
        [string]$FallbackType = ""
    )

    if ($null -eq $Node) { return $FallbackType }
    switch ([string]$Node.node) {
        "BIN_OP" {
            $op = [string]$Node.op
            if ($op -eq "??") { return $FallbackType }
            if ($op -eq "in") { return "value" }
            if ($op -eq "+") {
                foreach ($line in @($Code)) {
                    if ([string]$line -match 'call \$__sura_string_concat') { return "string" }
                    if ([string]$line -match 'call \$__sura_array_concat2') { return "array" }
                    if ([string]$line -match 'call \$__sura_value_add') { return "value" }
                }
                return "num"
            }
            if ($op -in @("and", "or", "==", "!=", "<", "<=", ">", ">=")) { return "bool" }
            if ($op -eq "/") {
                foreach ($line in @($Code)) {
                    if ([string]$line -match 'call \$__sura_value_div') { return "value" }
                }
                return "num"
            }
            if ($op -in @("&", "|", "^", "<<", ">>")) {
                foreach ($line in @($Code)) {
                    if ([string]$line -match 'call \$__sura_value_bitwise') { return "value" }
                }
                return "num"
            }
            if ($op -in @("-", "*", "%")) { return "num" }
            return $FallbackType
        }
        "UNARY_OP" {
            if ([string]$Node.op -eq "not") { return "bool" }
            if ([string]$Node.op -eq "~") {
                foreach ($line in @($Code)) {
                    if ([string]$line -match 'call \$__sura_value_bitwise_not') { return "value" }
                }
                return "num"
            }
            if ([string]$Node.op -eq "-") { return "num" }
            return $FallbackType
        }
        default { return $FallbackType }
    }
}

function Add-WasmAstStmt {
    param(
        $Node,
        [Parameter(Mandatory=$true)][System.Collections.Generic.List[string]]$Out,
        [string]$Indent = "",
        [switch]$Main
    )
    if ($null -eq $Node) { return }

    switch ([string]$Node.node) {
        "SuraBlock" {
            foreach ($stmt in @(As-WasmAstArray ($Node.body))) {
                Add-WasmAstStmt $stmt $Out $Indent -Main:$Main
            }
        }
        "USE" {
            $Out.Add("${Indent};; use $($Node.lib)")
        }
        "IMPORT" {
            $Out.Add("${Indent};; import $($Node.path)")
        }
        "GLOBAL_DECL" {
            $Out.Add("${Indent};; global $(($Node.names -join ', '))")
            foreach ($nameValue in @(As-WasmAstArray ($Node.names))) {
                $name = [string]$nameValue
                if (-not [string]::IsNullOrWhiteSpace($name)) {
                    $script:wasmCurrentGlobalDecls[$name] = $true
                    $script:wasmModuleGlobals[$name] = $true
                }
            }
        }
        "ENUM_DEF" {
            $Out.Add("${Indent};; numeric enum declarations plus string/bare enum declarations: $($Node.name)")
        }
        "CLASS_DEF" {
            $Out.Add("${Indent};; WASM AST partial class lowering: $($Node.name) uses a generated dict-backed constructor")
        }
        "ASSIGN" {
            $name = [string]$Node.name
            $valueType = if (Test-WasmAstValuePreservingExprCandidate ($Node.value)) { "value" } else { Get-WasmAstStaticValueType ($Node.value) }
            $objectClassName = Get-WasmAstObjectClassTypeHint ($Node.value)
            $functionDisplayName = Get-WasmAstKnownFunctionDisplayName ($Node.value)
            $functionLiftName = Get-WasmAstKnownFunctionLiftName ($Node.value)
            $mayThrowCall = Test-WasmAstMayThrowCallExpr ($Node.value)
            if ($mayThrowCall -and $null -ne (Get-WasmTryContext)) {
                Add-WasmAstClearExceptionState -Out $Out -Indent $Indent
            }
            $valueCode = if ($valueType -eq "value") {
                @(Convert-WasmAstValueExpr ($Node.value))
            } else {
                @(Convert-WasmAstExpr ($Node.value))
            }
            if ($valueType -ne "value") {
                $valueType = Get-WasmAstLoweredExprResultType ($Node.value) ([string[]]$valueCode) $valueType
            }
            Add-Code $Out $valueCode $Indent
            Add-WasmAstNameStore $Out $Indent $name
            if ($mayThrowCall) {
                Add-WasmAstCallExceptionBridge -Out $Out -Indent $Indent
            }
            Apply-WasmAstGlobalAssignmentHintsFromExpr ($Node.value)
            Set-WasmAstCurrentLocalValueTypeHint $name $valueType
            Set-WasmAstCurrentLocalObjectClassHint $name $objectClassName
            Set-WasmAstCurrentLocalFunctionDisplayHint $name $functionDisplayName
            Set-WasmAstCurrentLocalFunctionLiftHint $name $functionLiftName
            $functionLiftCandidates = @(Get-WasmAstFunctionValueLiftCandidatesFromExpr ($Node.value) $script:wasmCurrentClassContext $script:wasmCurrentLocalValueTypeHints $script:wasmCurrentLocalObjectClassHints $script:wasmCurrentLocalFunctionLiftCandidates @{} @{})
            if ($functionLiftCandidates.Count -gt 0) {
                $script:wasmCurrentLocalFunctionLiftCandidates[$name] = [string[]]$functionLiftCandidates
            } elseif ($script:wasmCurrentLocalFunctionLiftCandidates.ContainsKey($name)) {
                [void]$script:wasmCurrentLocalFunctionLiftCandidates.Remove($name)
            }
            if ($null -ne $Node.value -and [string]$Node.value.node -eq "FUNC_EXPR") {
                $script:wasmCurrentLocalFunctionExprs[$name] = $Node.value
            } elseif ($script:wasmCurrentLocalFunctionExprs.ContainsKey($name)) {
                $script:wasmCurrentLocalFunctionExprs.Remove($name)
            }
            Set-WasmAstCurrentLocalCollectionShapeHintsFromExpr $name ($Node.value)
            Add-WasmAstCollectionFieldHintsFromExpr $name ($Node.value)
            if (Test-WasmAstStringSplitExpr ($Node.value)) {
                $script:wasmAccessTypeHints["$name[*]"] = "string"
                $script:wasmStringAccessHints["$name[*]"] = $true
            }
            if (Test-WasmAstArraySliceExpr ($Node.value)) {
                $sliceSource = Get-WasmAstArraySliceSourceExpr ($Node.value)
                $sliceElementType = Get-WasmAstArrayElementTypeHint $sliceSource
                if ($sliceElementType -in @("string", "bool", "nil", "num", "array", "dict", "function")) {
                    $script:wasmAccessTypeHints["$name[*]"] = $sliceElementType
                    if ($sliceElementType -eq "string") {
                        $script:wasmStringAccessHints["$name[*]"] = $true
                    } elseif ($script:wasmStringAccessHints.ContainsKey("$name[*]")) {
                        $script:wasmStringAccessHints.Remove("$name[*]")
                    }
                }
            }
            if (Test-WasmAstArrayReverseExpr ($Node.value)) {
                $reverseSource = Get-WasmAstArrayReverseSourceExpr ($Node.value)
                $reverseElementType = Get-WasmAstArrayElementTypeHint $reverseSource
                if ($reverseElementType -in @("string", "bool", "nil", "num", "array", "dict", "function")) {
                    $script:wasmAccessTypeHints["$name[*]"] = $reverseElementType
                    if ($reverseElementType -eq "string") {
                        $script:wasmStringAccessHints["$name[*]"] = $true
                    } elseif ($script:wasmStringAccessHints.ContainsKey("$name[*]")) {
                        $script:wasmStringAccessHints.Remove("$name[*]")
                    }
                }
            }
            if (Test-WasmAstArraySortExpr ($Node.value)) {
                $sortSource = Get-WasmAstArraySortSourceExpr ($Node.value)
                $sortElementType = Get-WasmAstArrayElementTypeHint $sortSource
                if ($sortElementType -in @("string", "bool", "nil", "num", "array", "dict", "function")) {
                    $script:wasmAccessTypeHints["$name[*]"] = $sortElementType
                    if ($sortElementType -eq "string") {
                        $script:wasmStringAccessHints["$name[*]"] = $true
                    } elseif ($script:wasmStringAccessHints.ContainsKey("$name[*]")) {
                        $script:wasmStringAccessHints.Remove("$name[*]")
                    }
                }
            }
            if (Test-WasmAstArrayRepeatExpr ($Node.value)) {
                $repeatValue = Get-WasmAstArrayRepeatValueExpr ($Node.value)
                $repeatElementType = Get-WasmAstStaticValueType $repeatValue
                if ($repeatElementType -in @("string", "bool", "nil", "num", "array", "dict", "function")) {
                    $script:wasmAccessTypeHints["$name[*]"] = $repeatElementType
                    if ($repeatElementType -eq "string") {
                        $script:wasmStringAccessHints["$name[*]"] = $true
                    } elseif ($script:wasmStringAccessHints.ContainsKey("$name[*]")) {
                        $script:wasmStringAccessHints.Remove("$name[*]")
                    }
                }
            }
            if (Test-WasmAstArrayUniqueExpr ($Node.value)) {
                $uniqueSource = Get-WasmAstArrayUniqueSourceExpr ($Node.value)
                $uniqueElementType = Get-WasmAstArrayElementTypeHint $uniqueSource
                if ($uniqueElementType -in @("string", "bool", "nil", "num", "array", "dict", "function")) {
                    $script:wasmAccessTypeHints["$name[*]"] = $uniqueElementType
                    if ($uniqueElementType -eq "string") {
                        $script:wasmStringAccessHints["$name[*]"] = $true
                    } elseif ($script:wasmStringAccessHints.ContainsKey("$name[*]")) {
                        $script:wasmStringAccessHints.Remove("$name[*]")
                    }
                }
            }
            if (Test-WasmAstArrayCloneExpr ($Node.value)) {
                $cloneSource = Get-WasmAstArrayCloneSourceExpr ($Node.value)
                $cloneElementType = Get-WasmAstArrayElementTypeHint $cloneSource
                if ($cloneElementType -in @("string", "bool", "nil", "num", "array", "dict", "function")) {
                    $script:wasmAccessTypeHints["$name[*]"] = $cloneElementType
                    if ($cloneElementType -eq "string") {
                        $script:wasmStringAccessHints["$name[*]"] = $true
                    } elseif ($script:wasmStringAccessHints.ContainsKey("$name[*]")) {
                        $script:wasmStringAccessHints.Remove("$name[*]")
                    }
                }
            }
            if (Test-WasmAstArrayConcatExpr ($Node.value)) {
                $concatElementType = Get-WasmAstArrayConcatElementTypeHint ($Node.value)
                if ($concatElementType -in @("string", "bool", "nil", "num", "array", "dict", "function")) {
                    $script:wasmAccessTypeHints["$name[*]"] = $concatElementType
                    if ($concatElementType -eq "string") {
                        $script:wasmStringAccessHints["$name[*]"] = $true
                    } elseif ($script:wasmStringAccessHints.ContainsKey("$name[*]")) {
                        $script:wasmStringAccessHints.Remove("$name[*]")
                    }
                }
            }
            if (Test-WasmAstSetArrayResultExpr ($Node.value)) {
                $unionElementType = Get-WasmAstSetArrayResultElementTypeHint ($Node.value)
                if ($unionElementType -in @("string", "bool", "nil", "num", "array", "dict", "function")) {
                    $script:wasmAccessTypeHints["$name[*]"] = $unionElementType
                    if ($unionElementType -eq "string") {
                        $script:wasmStringAccessHints["$name[*]"] = $true
                    } elseif ($script:wasmStringAccessHints.ContainsKey("$name[*]")) {
                        $script:wasmStringAccessHints.Remove("$name[*]")
                    }
                }
            }
            if (Test-WasmAstArrayChunkExpr ($Node.value)) {
                $script:wasmAccessTypeHints["$name[*]"] = "array"
                $chunkNestedElementType = Get-WasmAstArrayNestedElementTypeHint ($Node.value)
                if ($chunkNestedElementType -in @("string", "bool", "nil", "num", "array", "dict", "function")) {
                    $script:wasmAccessTypeHints["$name[*][*]"] = $chunkNestedElementType
                }
                if ($script:wasmStringAccessHints.ContainsKey("$name[*]")) {
                    $script:wasmStringAccessHints.Remove("$name[*]")
                }
            }
            if (Test-WasmAstArrayZipExpr ($Node.value)) {
                $script:wasmAccessTypeHints["$name[*]"] = "array"
                $zipNestedElementType = Get-WasmAstArrayNestedElementTypeHint ($Node.value)
                if ($zipNestedElementType -in @("string", "bool", "nil", "num", "array", "dict", "function")) {
                    $script:wasmAccessTypeHints["$name[*][*]"] = $zipNestedElementType
                }
                if ($script:wasmStringAccessHints.ContainsKey("$name[*]")) {
                    $script:wasmStringAccessHints.Remove("$name[*]")
                }
            }
            if (Test-WasmAstArrayFlattenExpr ($Node.value)) {
                $flattenSource = Get-WasmAstArrayFlattenSourceExpr ($Node.value)
                $flattenElementType = Get-WasmAstArrayNestedElementTypeHint $flattenSource
                if ($flattenElementType -in @("string", "bool", "nil", "num", "array", "dict", "function")) {
                    $script:wasmAccessTypeHints["$name[*]"] = $flattenElementType
                    if ($flattenElementType -eq "string") {
                        $script:wasmStringAccessHints["$name[*]"] = $true
                    } elseif ($script:wasmStringAccessHints.ContainsKey("$name[*]")) {
                        $script:wasmStringAccessHints.Remove("$name[*]")
                    }
                }
            }
            if (Test-WasmAstDictKeysExpr ($Node.value)) {
                $script:wasmAccessTypeHints["$name[*]"] = "string"
                $script:wasmStringAccessHints["$name[*]"] = $true
            }
            if (Test-WasmAstDictItemsExpr ($Node.value)) {
                $script:wasmAccessTypeHints["$name[*]"] = "array"
                if ($script:wasmStringAccessHints.ContainsKey("$name[*]")) {
                    $script:wasmStringAccessHints.Remove("$name[*]")
                }
            }
            $dictValuesSource = Get-WasmAstDictValuesSourceExpr ($Node.value)
            if ($null -ne $dictValuesSource) {
                $dictValueElementType = Get-WasmAstDictValueTypeHint $dictValuesSource
                if ($dictValueElementType -in @("string", "bool", "nil", "num", "array", "dict", "function")) {
                    $script:wasmAccessTypeHints["$name[*]"] = $dictValueElementType
                    if ($dictValueElementType -eq "string") {
                        $script:wasmStringAccessHints["$name[*]"] = $true
                    } elseif ($script:wasmStringAccessHints.ContainsKey("$name[*]")) {
                        $script:wasmStringAccessHints.Remove("$name[*]")
                    }
                }
            }
        }
        "IN_PLACE" {
            $name = [string]$Node.name
            $opName = ([string]$Node.op).Replace("=", "")
            $targetNode = [pscustomobject]@{ node = "IDENT"; line = [int]$Node.line; name = $name }
            $targetStringish = Test-WasmAstStringExprCandidate $targetNode
            $valueStringish = Test-WasmAstStringExprCandidate ($Node.value)
            if ($targetStringish -or $valueStringish) {
                if ($opName -ne "+") {
                    throw "unsupported WASM AST dynamic in-place operator: $($Node.op)"
                }
                Add-Code $Out @(Convert-WasmAstStringExpr $targetNode) $Indent
                Add-Code $Out @(Convert-WasmAstStringExpr ($Node.value)) $Indent
                $Out.Add("${Indent}call `$__sura_string_concat")
                Add-WasmAstNameStore $Out $Indent $name
                Apply-WasmAstGlobalAssignmentHintsFromExpr ($Node.value)
                Set-WasmAstCurrentLocalValueTypeHint $name "string"
                Set-WasmAstCurrentLocalObjectClassHint $name ""
                Set-WasmAstCurrentLocalFunctionDisplayHint $name ""
                Set-WasmAstCurrentLocalFunctionLiftHint $name ""
                if ($script:wasmCurrentLocalIndexedAccessHints.ContainsKey($name)) {
                    $script:wasmCurrentLocalIndexedAccessHints.Remove($name)
                }
                Clear-WasmAstEmptyCollectionHints $name
                return
            }
            $targetValueType = Get-WasmAstKnownValueType $targetNode
            if ([string]::IsNullOrWhiteSpace($targetValueType)) {
                $targetValueType = Get-WasmAstStaticValueType $targetNode
            }
            if ($targetValueType -eq "value") {
                $dynamicHelper = switch ($opName) {
                    "+" { "__sura_value_add" }
                    "-" { "__sura_value_sub" }
                    "*" { "__sura_value_mul" }
                    "/" { "__sura_value_div" }
                    "%" { "__sura_value_mod" }
                    default { throw "unsupported WASM AST dynamic in-place operator: $($Node.op)" }
                }
                $operandCode = @(
                    @(Convert-WasmAstValueExpr $targetNode) +
                    @(Convert-WasmAstValueExpr ($Node.value)) +
                    @("call `$$dynamicHelper")
                )
                Add-Code $Out @(Convert-WasmAstGuardedCallResult ([string[]]$operandCode)) $Indent
                Add-WasmAstNameStore $Out $Indent $name
                Apply-WasmAstGlobalAssignmentHintsFromExpr ($Node.value)
                Set-WasmAstCurrentLocalValueTypeHint $name "value"
                Set-WasmAstCurrentLocalObjectClassHint $name ""
                Set-WasmAstCurrentLocalFunctionDisplayHint $name ""
                Set-WasmAstCurrentLocalFunctionLiftHint $name ""
                if ($script:wasmCurrentLocalIndexedAccessHints.ContainsKey($name)) {
                    $script:wasmCurrentLocalIndexedAccessHints.Remove($name)
                }
                Clear-WasmAstEmptyCollectionHints $name
                return
            }
            $op = switch ($opName) {
                "+" { "i32.add" }
                "-" { "i32.sub" }
                "*" { "i32.mul" }
                "/" { "call `$__sura_value_div" }
                "%" { "call `$__sura_i32_mod" }
                default { throw "unsupported WASM AST in-place operator: $($Node.op)" }
            }
            $mayThrowCall = Test-WasmAstMayThrowCallExpr ($Node.value)
            if ($mayThrowCall -and $null -ne (Get-WasmTryContext)) {
                Add-WasmAstClearExceptionState -Out $Out -Indent $Indent
            }
            if ($opName -eq "/") {
                # Canonicalize the existing number before evaluating a
                # potentially failing `/=`. Both the success and catch paths
                # then keep the same tagged representation, while the numeric
                # value remains unchanged if division raises.
                Add-Code $Out @(Convert-WasmAstValueExpr $targetNode) $Indent
                $Out.Add("${Indent}local.set `$__sura_wasm_value_tmp")
                $Out.Add("${Indent}local.get `$__sura_wasm_value_tmp")
                Add-WasmAstNameStore $Out $Indent $name
                $operandCode = @(
                    "local.get `$__sura_wasm_value_tmp"
                ) + @(Convert-WasmAstValueExpr ($Node.value)) + @($op)
            } else {
                $operandCode = @(
                    @(Convert-WasmAstNameLoad $name) +
                    @(Convert-WasmAstExpr ($Node.value)) +
                    @($op)
                )
            }
            if ($opName -in @("/", "%")) {
                Add-Code $Out @(Convert-WasmAstGuardedCallResult ([string[]]$operandCode)) $Indent
            } else {
                Add-Code $Out $operandCode $Indent
            }
            Add-WasmAstNameStore $Out $Indent $name
            if ($mayThrowCall) {
                Add-WasmAstCallExceptionBridge -Out $Out -Indent $Indent
            }
            Apply-WasmAstGlobalAssignmentHintsFromExpr ($Node.value)
            Set-WasmAstCurrentLocalValueTypeHint $name $(if ($opName -eq "/") { "value" } else { "num" })
            Set-WasmAstCurrentLocalObjectClassHint $name ""
            Set-WasmAstCurrentLocalFunctionDisplayHint $name ""
            Set-WasmAstCurrentLocalFunctionLiftHint $name ""
            if ($script:wasmCurrentLocalIndexedAccessHints.ContainsKey($name)) {
                $script:wasmCurrentLocalIndexedAccessHints.Remove($name)
            }
            Clear-WasmAstEmptyCollectionHints $name
        }
        "INDEX_ASSIGN" {
            $name = [string]$Node.name
            $valueType = Get-WasmAstStaticValueType ($Node.value)
            $valueClass = Get-WasmAstObjectClassTypeHint ($Node.value)
            $functionDisplayName = Get-WasmAstKnownFunctionDisplayName ($Node.value)
            $functionLiftName = Get-WasmAstKnownFunctionLiftName ($Node.value)
            $literalIndex = Get-WasmAstKnownNumericLiteralValue ($Node.key)
            $targetType = Get-WasmAstKnownValueType ([pscustomobject]@{ node = "IDENT"; name = $name })
            if ([string]::IsNullOrWhiteSpace($targetType)) { $targetType = Get-WasmAstStaticValueType ([pscustomobject]@{ node = "IDENT"; name = $name }) }
            if ($targetType -eq "value") {
                Add-Code $Out @(Convert-WasmAstNameLoad $name) $Indent
                Add-Code $Out @(Convert-WasmAstValueExpr ($Node.key)) $Indent
                Add-Code $Out @(Convert-WasmAstValueExpr ($Node.value)) $Indent
                $Out.Add("${Indent}call `$__sura_value_set_index")
                Apply-WasmAstGlobalAssignmentHintsFromExpr ($Node.key)
                Apply-WasmAstGlobalAssignmentHintsFromExpr ($Node.value)
                return
            }
            if ($null -ne $Node.key -and [string]$Node.key.node -eq "STR_LIT") {
                if ($valueType -in @("string", "bool", "nil", "num", "array", "dict", "function")) {
                    Set-WasmAstAccessTypeHintAfterWrite $name ([string]$Node.key.value) $valueType
                }
                Set-WasmAstAccessFunctionDisplayHintAfterWrite $name ([string]$Node.key.value) $functionDisplayName
                Set-WasmAstAccessFunctionLiftHintAfterWrite $name ([string]$Node.key.value) $functionLiftName
                Set-WasmAstAccessObjectClassHint $name ([string]$Node.key.value) $valueClass
                Add-Code $Out @(Convert-WasmAstNameLoad $name) $Indent
                Add-Code $Out @(Convert-WasmAstStringExpr ($Node.key)) $Indent
                Add-Code $Out @(Convert-WasmAstExpr ($Node.value)) $Indent
                $Out.Add("${Indent}call `$__sura_dict_put")
                Add-WasmAstNameStore $Out $Indent $name
                Apply-WasmAstGlobalAssignmentHintsFromExpr ($Node.value)
                Set-WasmAstCurrentLocalKeyedAccessHint $name ([string]$Node.key.value) $valueType $functionDisplayName $valueClass
                Set-WasmAstCurrentLocalCollectionShapeHintsFromExpr "$name.$([string]$Node.key.value)" ($Node.value)
                return
            }
            $keyType = Get-WasmAstKnownValueType ($Node.key)
            if ([string]::IsNullOrWhiteSpace($keyType)) { $keyType = Get-WasmAstStaticValueType ($Node.key) }
            $knownStringKey = Get-WasmAstKnownStringLiteralValue ($Node.key)
            $preferExactKnownKey = (-not [string]::IsNullOrWhiteSpace($knownStringKey) -and [string]$Node.key.node -ne "IDENT")
            if ($preferExactKnownKey) {
                if ($valueType -in @("string", "bool", "nil", "num", "array", "dict", "function")) {
                    Set-WasmAstAccessTypeHintAfterWrite $name $knownStringKey $valueType
                }
                Set-WasmAstAccessFunctionDisplayHintAfterWrite $name $knownStringKey $functionDisplayName
                Set-WasmAstAccessFunctionLiftHintAfterWrite $name $knownStringKey $functionLiftName
                Set-WasmAstAccessObjectClassHint $name $knownStringKey $valueClass
                Add-Code $Out @(Convert-WasmAstNameLoad $name) $Indent
                Add-Code $Out @(Convert-WasmAstStringExpr ($Node.key)) $Indent
                Add-Code $Out @(Convert-WasmAstExpr ($Node.value)) $Indent
                $Out.Add("${Indent}call `$__sura_dict_put")
                Add-WasmAstNameStore $Out $Indent $name
                Apply-WasmAstGlobalAssignmentHintsFromExpr ($Node.key)
                Apply-WasmAstGlobalAssignmentHintsFromExpr ($Node.value)
                Set-WasmAstCurrentLocalKeyedAccessHint $name $knownStringKey $valueType $functionDisplayName $valueClass
                Set-WasmAstCurrentLocalCollectionShapeHintsFromExpr "$name.$knownStringKey" ($Node.value)
                return
            }
            if ($keyType -eq "string" -and $targetType -eq "dict") {
                if ($valueType -in @("string", "bool", "nil", "num", "array", "dict", "function")) {
                    Set-WasmAstAccessTypeHint $name "*" $valueType
                    if ($null -ne $Node.key -and [string]$Node.key.node -eq "IDENT") {
                        Set-WasmAstDynamicKeyAccessTypeHint $name ([string]$Node.key.name) $valueType
                    }
                }
                if ($valueType -eq "function" -and $null -ne $Node.key -and [string]$Node.key.node -eq "IDENT") {
                    Set-WasmAstDynamicKeyAccessFunctionDisplayHint $name ([string]$Node.key.name) $functionDisplayName
                    Set-WasmAstDynamicKeyAccessFunctionLiftHint $name ([string]$Node.key.name) $functionLiftName
                }
                Set-WasmAstAccessObjectClassHint $name "*" $valueClass
                if ($null -ne $Node.key -and [string]$Node.key.node -eq "IDENT") {
                    Set-WasmAstDynamicKeyAccessObjectClassHint $name ([string]$Node.key.name) $valueClass
                }
                Add-Code $Out @(Convert-WasmAstNameLoad $name) $Indent
                Add-Code $Out @(Convert-WasmAstStringExpr ($Node.key)) $Indent
                Add-Code $Out @(Convert-WasmAstExpr ($Node.value)) $Indent
                $Out.Add("${Indent}call `$__sura_dict_put")
                Add-WasmAstNameStore $Out $Indent $name
                Apply-WasmAstGlobalAssignmentHintsFromExpr ($Node.key)
                Apply-WasmAstGlobalAssignmentHintsFromExpr ($Node.value)
                return
            }
            if ($keyType -eq "string") {
                if (-not [string]::IsNullOrWhiteSpace($knownStringKey)) {
                    if ($valueType -in @("string", "bool", "nil", "num", "array", "dict", "function")) {
                        Set-WasmAstAccessTypeHintAfterWrite $name $knownStringKey $valueType
                    }
                    Set-WasmAstAccessFunctionDisplayHintAfterWrite $name $knownStringKey $functionDisplayName
                    Set-WasmAstAccessFunctionLiftHintAfterWrite $name $knownStringKey $functionLiftName
                    Set-WasmAstAccessObjectClassHint $name $knownStringKey $valueClass
                    Add-Code $Out @(Convert-WasmAstNameLoad $name) $Indent
                    Add-Code $Out @(Convert-WasmAstStringExpr ($Node.key)) $Indent
                    Add-Code $Out @(Convert-WasmAstExpr ($Node.value)) $Indent
                    $Out.Add("${Indent}call `$__sura_dict_put")
                    Add-WasmAstNameStore $Out $Indent $name
                    Apply-WasmAstGlobalAssignmentHintsFromExpr ($Node.key)
                    Apply-WasmAstGlobalAssignmentHintsFromExpr ($Node.value)
                    Set-WasmAstCurrentLocalKeyedAccessHint $name $knownStringKey $valueType $functionDisplayName $valueClass
                    Set-WasmAstCurrentLocalCollectionShapeHintsFromExpr "$name.$knownStringKey" ($Node.value)
                    return
                }
                if ($targetType -notin @("array", "string")) {
                    if ($valueType -in @("string", "bool", "nil", "num", "array", "dict", "function") -and
                        $null -ne $Node.key -and [string]$Node.key.node -eq "IDENT") {
                        Set-WasmAstDynamicKeyAccessTypeHint $name ([string]$Node.key.name) $valueType
                    }
                    if ($valueType -eq "function" -and $null -ne $Node.key -and [string]$Node.key.node -eq "IDENT") {
                        Set-WasmAstDynamicKeyAccessFunctionDisplayHint $name ([string]$Node.key.name) $functionDisplayName
                        Set-WasmAstDynamicKeyAccessFunctionLiftHint $name ([string]$Node.key.name) $functionLiftName
                    }
                    if ($null -ne $Node.key -and [string]$Node.key.node -eq "IDENT") {
                        Set-WasmAstDynamicKeyAccessObjectClassHint $name ([string]$Node.key.name) $valueClass
                    }
                    Add-Code $Out @(Convert-WasmAstNameLoad $name) $Indent
                    Add-Code $Out @(Convert-WasmAstStringExpr ($Node.key)) $Indent
                    Add-Code $Out @(Convert-WasmAstExpr ($Node.value)) $Indent
                    $Out.Add("${Indent}call `$__sura_dict_put")
                    Add-WasmAstNameStore $Out $Indent $name
                    Apply-WasmAstGlobalAssignmentHintsFromExpr ($Node.key)
                    Apply-WasmAstGlobalAssignmentHintsFromExpr ($Node.value)
                    return
                }
            }
            $knownArrayIndex = $null
            if ($targetType -eq "array" -and $null -ne $literalIndex) {
                $knownArrayIndex = [int][Math]::Truncate([double]$literalIndex)
            }
            Add-Code $Out @(Convert-WasmAstNameLoad $name) $Indent
            if ($null -ne $knownArrayIndex) {
                if (Test-WasmAstEffectfulExpr ($Node.key)) {
                    Add-Code $Out @(Convert-WasmAstExpr ($Node.key)) $Indent
                    $Out.Add("${Indent}drop")
                }
                $Out.Add("${Indent}i32.const $knownArrayIndex")
            } else {
                Add-Code $Out @(Convert-WasmAstExpr ($Node.key)) $Indent
            }
            Add-Code $Out @(Convert-WasmAstExpr ($Node.value)) $Indent
            $Out.Add("${Indent}call `$__sura_array_set_checked")
            Apply-WasmAstGlobalAssignmentHintsFromExpr ($Node.key)
            Apply-WasmAstGlobalAssignmentHintsFromExpr ($Node.value)
            if ($null -ne $literalIndex) {
                Set-WasmAstCurrentLocalIndexedAccessHint $name ([int][Math]::Truncate([double]$literalIndex)) $valueType $functionDisplayName $valueClass
            } elseif ($script:wasmCurrentLocalIndexedAccessHints.ContainsKey($name)) {
                $script:wasmCurrentLocalIndexedAccessHints.Remove($name)
            }
        }
        "DOT_ASSIGN" {
            $dotBaseName = [string]$Node.obj_name
            $dotPropName = [string]$Node.prop
            $valueType = Get-WasmAstStaticValueType ($Node.value)
            $functionDisplayName = Get-WasmAstKnownFunctionDisplayName ($Node.value)
            $functionLiftName = Get-WasmAstKnownFunctionLiftName ($Node.value)
            $targetType = Get-WasmAstKnownValueType ([pscustomobject]@{ node = "IDENT"; name = $dotBaseName })
            if ([string]::IsNullOrWhiteSpace($targetType)) { $targetType = Get-WasmAstStaticValueType ([pscustomobject]@{ node = "IDENT"; name = $dotBaseName }) }
            if ($targetType -eq "value") {
                Add-Code $Out @(Convert-WasmAstNameLoad $dotBaseName) $Indent
                $Out.Add("${Indent}i32.const $(Get-WasmStringKeyHash $dotPropName)")
                Add-Code $Out @(Convert-WasmAstValueExpr ($Node.value)) $Indent
                $Out.Add("${Indent}call `$__sura_value_set_field")
                Apply-WasmAstGlobalAssignmentHintsFromExpr ($Node.value)
                return
            }
            if ($valueType -in @("string", "bool", "nil", "num", "array", "dict", "function")) {
                Set-WasmAstAccessTypeHintAfterWrite $dotBaseName $dotPropName $valueType
            }
            Set-WasmAstAccessFunctionDisplayHintAfterWrite $dotBaseName $dotPropName $functionDisplayName
            Set-WasmAstAccessFunctionLiftHintAfterWrite $dotBaseName $dotPropName $functionLiftName
            if ($valueType -eq "function") {
                $dotClassName = ""
                if ($dotBaseName -eq "self" -and -not [string]::IsNullOrWhiteSpace($script:wasmCurrentClassContext)) {
                    $dotClassName = $script:wasmCurrentClassContext
                } else {
                    $dotClassName = Get-WasmAstObjectClassTypeWithLocals ([pscustomobject]@{ node = "IDENT"; name = $dotBaseName }) $script:wasmCurrentLocalObjectClassHints $script:wasmCurrentClassContext @{}
                }
                if (-not [string]::IsNullOrWhiteSpace($dotClassName)) {
                    Set-WasmAstClassFieldFunctionDisplayHint $dotClassName $dotPropName $functionDisplayName
                    Set-WasmAstClassFieldFunctionLiftHint $dotClassName $dotPropName $functionLiftName
                }
            }
            Add-Code $Out @(Convert-WasmAstNameLoad $dotBaseName) $Indent
            Add-Code $Out @(New-WasmStringLiteralExprCode -Literal (Convert-WasmAstStringLiteral $dotPropName)) $Indent
            Add-Code $Out @(Convert-WasmAstExpr ($Node.value)) $Indent
            $Out.Add("${Indent}call `$__sura_dict_put")
            Add-WasmAstNameStore $Out $Indent $dotBaseName
            Apply-WasmAstGlobalAssignmentHintsFromExpr ($Node.value)
            $valueClass = Get-WasmAstObjectClassTypeHint ($Node.value)
            Set-WasmAstCurrentLocalKeyedAccessHint $dotBaseName $dotPropName $valueType $functionDisplayName $valueClass
            Set-WasmAstCurrentLocalCollectionShapeHintsFromExpr "$dotBaseName.$dotPropName" ($Node.value)
        }
        "EXPR_STMT" {
            if (Test-WasmAstConsoleOutputCall ($Node.expr)) {
                Add-WasmAstConsoleOutputCall $Node.expr $Out $Indent -Main:$Main
                return
            }
            if ($null -ne $Node.expr -and [string]$Node.expr.node -eq "METHOD_CALL" -and
                [string]$Node.expr.method -eq "push" -and $null -ne $Node.expr.obj -and
                [string]$Node.expr.obj.node -eq "IDENT") {
                $pushName = [string]$Node.expr.obj.name
                $pushArgs = @(As-WasmAstArray ($Node.expr.args))
                if ($pushArgs.Count -eq 1) {
                    Add-Code $Out @(Convert-WasmAstExpr ($Node.expr.obj)) $Indent
                    Add-Code $Out @(Convert-WasmAstExpr ($pushArgs[0])) $Indent
                    $Out.Add("${Indent}call `$__sura_array_push")
                    $Out.Add("${Indent}local.set `$$pushName")
                    Apply-WasmAstGlobalAssignmentHintsFromExpr ($Node.expr)
                    return
                }
            }
            if ($null -ne $Node.expr -and [string]$Node.expr.node -eq "METHOD_CALL" -and
                [string]$Node.expr.method -eq "insert" -and $null -ne $Node.expr.obj -and
                [string]$Node.expr.obj.node -eq "IDENT") {
                $insertName = [string]$Node.expr.obj.name
                $insertArgs = @(As-WasmAstArray ($Node.expr.args))
                if ($insertArgs.Count -eq 2) {
                    Add-Code $Out @(Convert-WasmAstExpr ($Node.expr.obj)) $Indent
                    Add-Code $Out @(Convert-WasmAstExpr ($insertArgs[0])) $Indent
                    Add-Code $Out @(Convert-WasmAstExpr ($insertArgs[1])) $Indent
                    $Out.Add("${Indent}call `$__sura_array_insert")
                    $Out.Add("${Indent}local.set `$$insertName")
                    Apply-WasmAstGlobalAssignmentHintsFromExpr ($Node.expr)
                    return
                }
            }
            if ($null -ne $Node.expr -and [string]$Node.expr.node -eq "CALL") {
                $callName = [string]$Node.expr.name
                $callArgs = @(As-WasmAstArray ($Node.expr.args))
                if ($callName -in @("assert", "assert_eq", "assert_ne", "assert_neq", "assert_type", "assert_len", "assert_between", "assert_approx")) {
                    Add-WasmAstAssert -Name $callName -InputArgs $callArgs -Out $Out -Indent $Indent
                    return
                }
                if ($callName -in @("print", "print_n", "print_no_nl")) {
                    Add-WasmAstPrintOutputCall ([object[]]$callArgs) $Out $Indent -Main:$Main
                    return
                }
            }
            $mayThrowCall = Test-WasmAstMayThrowCallExpr ($Node.expr)
            if ($mayThrowCall -and $null -ne (Get-WasmTryContext)) {
                Add-WasmAstClearExceptionState -Out $Out -Indent $Indent
            }
            Add-Code $Out @(Convert-WasmAstExpr ($Node.expr)) $Indent
            $Out.Add("${Indent}drop")
            if ($mayThrowCall) {
                Add-WasmAstCallExceptionBridge -Out $Out -Indent $Indent
            }
            Apply-WasmAstGlobalAssignmentHintsFromExpr ($Node.expr)
        }
        "CMD" {
            $cmd = [string]$Node.cmd
            $cmdArgs = @(As-WasmAstArray ($Node.args))
            if ($cmd -in @("assert", "assert_eq", "assert_ne", "assert_neq", "assert_type", "assert_len", "assert_between", "assert_approx")) {
                Add-WasmAstAssert -Name $cmd -InputArgs $cmdArgs -Out $Out -Indent $Indent
            } elseif (Test-WasmConsoleOutputName $cmd) {
                $callNode = [pscustomobject]@{ node = "CALL"; name = $cmd; args = @($cmdArgs) }
                Add-WasmAstConsoleOutputCall $callNode $Out $Indent -Main:$Main
            } elseif ($cmd -in @("print", "print_n", "print_no_nl")) {
                Add-WasmAstPrintOutputCall ([object[]]$cmdArgs) $Out $Indent -Main:$Main
            } elseif (Is-WasmRejectedBuiltinName $cmd) {
                Throw-WasmRejectedBuiltin $cmd
            } else {
                throw "unsupported WASM AST command: $cmd"
            }
        }
        "RETURN" {
            # Inside this function a direct call to a locally promoted function
            # expression consistently flows as a tagged Value. Callers of the
            # ENCLOSING named function, however, classify its return without
            # these local lift hints and emit against the raw kind reported by
            # static inference. The function boundary is therefore the one
            # place the tagged result must be unwrapped back to raw.
            $rawKindLiftUnwrap = ""
            if ($null -ne $Node.value -and [string]$Node.value.node -eq "CALL" -and
                $null -ne $env:SURA_WASM_RETURN_DIAG) {
                $diagName = [string]$Node.value.name
                $diagCands = if ($script:wasmCurrentLocalFunctionLiftCandidates.ContainsKey($diagName)) { @($script:wasmCurrentLocalFunctionLiftCandidates[$diagName]) -join "," } else { "<none>" }
                $diagKinds = @()
                if ($script:wasmCurrentLocalFunctionLiftCandidates.ContainsKey($diagName)) {
                    foreach ($c in @($script:wasmCurrentLocalFunctionLiftCandidates[$diagName])) {
                        $fc = [pscustomobject]@{ node = "CALL"; name = [string]$c; args = @(As-WasmAstArray ($Node.value.args)) }
                        $diagKinds += (Get-WasmAstFunctionCallTypeHint $fc (Get-WasmAstCurrentValueTypeScopeHints))
                    }
                }
                [Console]::Error.WriteLine("[ret-diag] fn=$($script:wasmCurrentFunctionName) call=$diagName returnsValue=$($script:wasmCurrentFunctionReturnsValue) hint=$($script:wasmCurrentLocalFunctionLiftHints.ContainsKey($diagName)) indirect=$(Test-WasmAstIndirectFunctionValueCall ($Node.value)) static=$(Get-WasmAstStaticValueType ($Node.value)) cands=$diagCands kinds=$($diagKinds -join ','))")
            }
            if ($null -ne $Node.value -and -not $script:wasmCurrentFunctionReturnsValue -and
                [string]$Node.value.node -eq "CALL") {
                $returnCallName = [string]$Node.value.name
                if (-not [string]::IsNullOrWhiteSpace($returnCallName) -and
                    $script:wasmCurrentLocalFunctionLiftHints.ContainsKey($returnCallName)) {
                    $rawKindLiftUnwrap = Get-WasmAstPromotedLiftCallRawUnwrap ([string]$script:wasmCurrentLocalFunctionLiftHints[$returnCallName])
                }
                if ([string]::IsNullOrWhiteSpace($rawKindLiftUnwrap) -and
                    (Test-WasmAstIndirectFunctionValueCall ($Node.value))) {
                    # The indirect function-value dispatcher normalizes every
                    # result to a tagged Value; unwrap to the raw kind callers
                    # of the enclosing function assume when it is known. The
                    # dispatched call itself has no static type, so mirror the
                    # caller's view: the single known kind among the enclosing
                    # function's other return statements.
                    $externalKind = Get-WasmAstStaticValueType ($Node.value)
                    if (($externalKind -eq "value" -or [string]::IsNullOrWhiteSpace($externalKind)) -and
                        -not [string]::IsNullOrWhiteSpace([string]$script:wasmCurrentFunctionName) -and
                        $script:wasmAstFunctionDefs.ContainsKey([string]$script:wasmCurrentFunctionName)) {
                        $annotatedKind = Get-WasmAstAnnotatedRawReturnKind $script:wasmAstFunctionDefs[[string]$script:wasmCurrentFunctionName].Node
                        if (-not [string]::IsNullOrWhiteSpace($annotatedKind)) { $externalKind = $annotatedKind }
                    }
                    if ([string]::IsNullOrWhiteSpace($externalKind) -and
                        -not [string]::IsNullOrWhiteSpace([string]$script:wasmCurrentFunctionName) -and
                        $script:wasmAstFunctionDefs.ContainsKey([string]$script:wasmCurrentFunctionName)) {
                        $enclosingNode = $script:wasmAstFunctionDefs[[string]$script:wasmCurrentFunctionName].Node
                        if ($null -ne $enclosingNode -and $null -ne $enclosingNode.body) {
                            $knownKinds = @(@(Get-WasmAstReturnValueTypesFromBody ($enclosingNode.body)) |
                                Where-Object { $_ -in @("string", "num", "bool") } | Sort-Object -Unique)
                            if ($knownKinds.Count -eq 1) { $externalKind = [string]$knownKinds[0] }
                        }
                    }
                    if ([string]::IsNullOrWhiteSpace($externalKind) -and
                        $script:wasmCurrentLocalFunctionLiftCandidates.ContainsKey($returnCallName)) {
                        # Last resort: the single source kind every reachable
                        # dispatch candidate returns (before the dispatcher's
                        # tagged normalization).
                        $candidateKinds = New-Object System.Collections.Generic.List[string]
                        foreach ($candidate in @($script:wasmCurrentLocalFunctionLiftCandidates[$returnCallName])) {
                            if ([string]::IsNullOrWhiteSpace([string]$candidate) -or
                                -not $script:wasmAstFunctionDefs.ContainsKey([string]$candidate)) { continue }
                            $candidateCall = [pscustomobject]@{
                                node = "CALL"
                                name = [string]$candidate
                                args = @(As-WasmAstArray ($Node.value.args))
                            }
                            $candidateKinds.Add((Get-WasmAstFunctionCallTypeHint $candidateCall (Get-WasmAstCurrentValueTypeScopeHints))) | Out-Null
                        }
                        $uniqueKinds = @($candidateKinds | Where-Object { $_ -in @("string", "num", "bool") } | Sort-Object -Unique)
                        if ($candidateKinds.Count -gt 0 -and $uniqueKinds.Count -eq 1 -and
                            @($candidateKinds | Sort-Object -Unique).Count -eq 1) {
                            $externalKind = [string]$uniqueKinds[0]
                        }
                    }
                    switch ($externalKind) {
                        "string" { $rawKindLiftUnwrap = "call `$__sura_value_to_string" }
                        "bool"   { $rawKindLiftUnwrap = "call `$__sura_value_is_truthy" }
                        "num"    { $rawKindLiftUnwrap = "call `$__sura_value_payload" }
                        default  { }
                    }
                }
            }
            if ($null -eq $Node.value) {
                $Out.Add("${Indent}i32.const 0")
            } elseif (-not [string]::IsNullOrWhiteSpace($rawKindLiftUnwrap)) {
                Add-Code $Out (@(Convert-WasmAstExpr ($Node.value)) + @($rawKindLiftUnwrap)) $Indent
            } elseif ($script:wasmCurrentFunctionReturnsValue -or (Test-WasmAstValuePreservingExprCandidate ($Node.value))) {
                Add-Code $Out @(Convert-WasmAstValueExpr ($Node.value)) $Indent
            } else {
                Add-Code $Out @(Convert-WasmAstExpr ($Node.value)) $Indent
            }
            $Out.Add("${Indent}return")
        }
        "BREAK" {
            $ctx = Get-WasmLoopContext
            if ($null -eq $ctx) { throw "break outside loop" }
            $Out.Add("${Indent}br `$$($ctx.Break)")
        }
        "CONTINUE" {
            $ctx = Get-WasmLoopContext
            if ($null -eq $ctx) { throw "continue outside loop" }
            $Out.Add("${Indent}br `$$($ctx.Continue)")
        }
        "THROW" {
            $throwObjectHint = if ($null -ne $Node.msg) {
                Get-WasmAstObjectClassSetHintWithLocals ($Node.msg) $script:wasmCurrentLocalObjectClassHints $script:wasmCurrentClassContext
            } else {
                ""
            }
            $throwValueCode = if ($null -eq $Node.msg) {
                @("call `$__sura_value_nil")
            } elseif (-not [string]::IsNullOrWhiteSpace($throwObjectHint)) {
                @(Convert-WasmAstExpr ($Node.msg)) + @("call `$__sura_value_object")
            } else {
                @(Convert-WasmAstValueExpr ($Node.msg))
            }
            $tryCtx = Get-WasmTryContext
            if ($null -ne $tryCtx) {
                Add-Code $Out $throwValueCode $Indent
                if ($null -ne $Node.msg) {
                    Apply-WasmAstGlobalAssignmentHintsFromExpr ($Node.msg)
                }
                $Out.Add("${Indent}local.tee `$$($tryCtx.TaggedValue)")
                $Out.Add("${Indent}call `$__sura_value_payload")
                $Out.Add("${Indent}local.set `$$($tryCtx.Value)")
                $Out.Add("${Indent}i32.const 1")
                $Out.Add("${Indent}local.set `$$($tryCtx.Thrown)")
                $Out.Add("${Indent}br `$$($tryCtx.End)")
            } else {
                if ([string]$script:wasmCurrentFunctionName -eq "main" -or [string]::IsNullOrWhiteSpace($script:wasmCurrentFunctionName)) {
                    if ($null -ne $Node.msg) {
                        Add-Code $Out $throwValueCode $Indent
                        Apply-WasmAstGlobalAssignmentHintsFromExpr ($Node.msg)
                        $Out.Add("${Indent}drop")
                    }
                    $Out.Add("${Indent}unreachable")
                } else {
                    Add-Code $Out $throwValueCode $Indent
                    if ($null -ne $Node.msg) {
                        Apply-WasmAstGlobalAssignmentHintsFromExpr ($Node.msg)
                    }
                    $Out.Add("${Indent}local.tee `$__sura_wasm_value_tmp")
                    $Out.Add("${Indent}global.set `$__sura_exception_value_tagged")
                    $Out.Add("${Indent}local.get `$__sura_wasm_value_tmp")
                    $Out.Add("${Indent}call `$__sura_value_payload")
                    $Out.Add("${Indent}global.set `$__sura_exception_value")
                    $Out.Add("${Indent}i32.const 1")
                    $Out.Add("${Indent}global.set `$__sura_exception_thrown")
                    $Out.Add("${Indent}i32.const 0")
                    $Out.Add("${Indent}return")
                }
            }
        }
        "IF" {
            Add-Code $Out @(Convert-WasmAstConditionExpr ($Node.cond)) $Indent
            Apply-WasmAstGlobalAssignmentHintsFromExpr ($Node.cond)
            $Out.Add("${Indent}if")
            $beforeLocalHints = Copy-WasmAstTypeHints $script:wasmCurrentLocalValueTypeHints
            $beforeObjectHints = Copy-WasmAstTypeHints $script:wasmCurrentLocalObjectClassHints
            $beforeFunctionDisplayHints = Copy-WasmAstTypeHints $script:wasmCurrentLocalFunctionDisplayHints
            $beforeFunctionLiftHints = Copy-WasmAstTypeHints $script:wasmCurrentLocalFunctionLiftHints
            $beforeIndexedHints = Copy-WasmAstLocalIndexedAccessHints $script:wasmCurrentLocalIndexedAccessHints
            $beforeAccessHints = Get-WasmAstAccessHintFlowState
            Add-WasmAstStmt ($Node.then_block) $Out ($Indent + "  ") -Main:$Main
            $thenLocalHints = Copy-WasmAstTypeHints $script:wasmCurrentLocalValueTypeHints
            $thenObjectHints = Copy-WasmAstTypeHints $script:wasmCurrentLocalObjectClassHints
            $thenFunctionDisplayHints = Copy-WasmAstTypeHints $script:wasmCurrentLocalFunctionDisplayHints
            $thenFunctionLiftHints = Copy-WasmAstTypeHints $script:wasmCurrentLocalFunctionLiftHints
            $thenIndexedHints = Copy-WasmAstLocalIndexedAccessHints $script:wasmCurrentLocalIndexedAccessHints
            $thenAccessHints = Get-WasmAstAccessHintFlowState
            $script:wasmCurrentLocalValueTypeHints = Copy-WasmAstTypeHints $beforeLocalHints
            $script:wasmCurrentLocalObjectClassHints = Copy-WasmAstTypeHints $beforeObjectHints
            $script:wasmCurrentLocalFunctionDisplayHints = Copy-WasmAstTypeHints $beforeFunctionDisplayHints
            $script:wasmCurrentLocalFunctionLiftHints = Copy-WasmAstTypeHints $beforeFunctionLiftHints
            $script:wasmCurrentLocalIndexedAccessHints = Copy-WasmAstLocalIndexedAccessHints $beforeIndexedHints
            Set-WasmAstAccessHintFlowState $beforeAccessHints
            if ($null -ne $Node.else_block) {
                $Out.Add("${Indent}else")
                Add-WasmAstStmt ($Node.else_block) $Out ($Indent + "  ") -Main:$Main
                $elseLocalHints = Copy-WasmAstTypeHints $script:wasmCurrentLocalValueTypeHints
                $elseObjectHints = Copy-WasmAstTypeHints $script:wasmCurrentLocalObjectClassHints
                $elseFunctionDisplayHints = Copy-WasmAstTypeHints $script:wasmCurrentLocalFunctionDisplayHints
                $elseFunctionLiftHints = Copy-WasmAstTypeHints $script:wasmCurrentLocalFunctionLiftHints
                $elseIndexedHints = Copy-WasmAstLocalIndexedAccessHints $script:wasmCurrentLocalIndexedAccessHints
                $elseAccessHints = Get-WasmAstAccessHintFlowState
            } else {
                $elseLocalHints = Copy-WasmAstTypeHints $beforeLocalHints
                $elseObjectHints = Copy-WasmAstTypeHints $beforeObjectHints
                $elseFunctionDisplayHints = Copy-WasmAstTypeHints $beforeFunctionDisplayHints
                $elseFunctionLiftHints = Copy-WasmAstTypeHints $beforeFunctionLiftHints
                $elseIndexedHints = Copy-WasmAstLocalIndexedAccessHints $beforeIndexedHints
                $elseAccessHints = $beforeAccessHints
            }
            $script:wasmCurrentLocalValueTypeHints = Merge-WasmAstLocalValueTypeHints $thenLocalHints $elseLocalHints
            $script:wasmCurrentLocalObjectClassHints = Merge-WasmAstLocalObjectClassHints $thenObjectHints $elseObjectHints
            $script:wasmCurrentLocalFunctionDisplayHints = Merge-WasmAstLocalFunctionDisplayHints $thenFunctionDisplayHints $elseFunctionDisplayHints
            $script:wasmCurrentLocalFunctionLiftHints = Merge-WasmAstLocalFunctionLiftHints $thenFunctionLiftHints $elseFunctionLiftHints
            $script:wasmCurrentLocalIndexedAccessHints = Merge-WasmAstLocalIndexedAccessHints $thenIndexedHints $elseIndexedHints
            Set-WasmAstAccessHintFlowState (Merge-WasmAstAccessHintFlowStates $thenAccessHints $elseAccessHints)
            $Out.Add("${Indent}end")
        }
        "WHILE" {
            $ctx = Push-WasmLoopContext -ContinueToLoop
            $Out.Add("${Indent}block `$$($ctx.Break)")
            $Out.Add("${Indent}  loop `$$($ctx.Loop)")
            Add-Code $Out @(Convert-WasmAstConditionExpr ($Node.cond)) ($Indent + "    ")
            Apply-WasmAstGlobalAssignmentHintsFromExpr ($Node.cond)
            $Out.Add("${Indent}    i32.eqz")
            $Out.Add("${Indent}    br_if `$$($ctx.Break)")
            $beforeLoopLocalHints = Copy-WasmAstTypeHints $script:wasmCurrentLocalValueTypeHints
            $beforeLoopObjectHints = Copy-WasmAstTypeHints $script:wasmCurrentLocalObjectClassHints
            $beforeLoopFunctionDisplayHints = Copy-WasmAstTypeHints $script:wasmCurrentLocalFunctionDisplayHints
            $beforeLoopFunctionLiftHints = Copy-WasmAstTypeHints $script:wasmCurrentLocalFunctionLiftHints
            $beforeLoopIndexedHints = Copy-WasmAstLocalIndexedAccessHints $script:wasmCurrentLocalIndexedAccessHints
            $beforeLoopAccessHints = Get-WasmAstAccessHintFlowState
            try {
                Add-WasmAstStmt ($Node.body) $Out ($Indent + "    ") -Main:$Main
            } finally {
                $bodyLoopLocalHints = Copy-WasmAstTypeHints $script:wasmCurrentLocalValueTypeHints
                $bodyLoopObjectHints = Copy-WasmAstTypeHints $script:wasmCurrentLocalObjectClassHints
                $bodyLoopFunctionDisplayHints = Copy-WasmAstTypeHints $script:wasmCurrentLocalFunctionDisplayHints
                $bodyLoopFunctionLiftHints = Copy-WasmAstTypeHints $script:wasmCurrentLocalFunctionLiftHints
                $bodyLoopIndexedHints = Copy-WasmAstLocalIndexedAccessHints $script:wasmCurrentLocalIndexedAccessHints
                $bodyLoopAccessHints = Get-WasmAstAccessHintFlowState
                $script:wasmCurrentLocalValueTypeHints = Merge-WasmAstLocalValueTypeHints $beforeLoopLocalHints $bodyLoopLocalHints
                $script:wasmCurrentLocalObjectClassHints = Merge-WasmAstLocalObjectClassHints $beforeLoopObjectHints $bodyLoopObjectHints
                $script:wasmCurrentLocalFunctionDisplayHints = Merge-WasmAstLocalFunctionDisplayHints $beforeLoopFunctionDisplayHints $bodyLoopFunctionDisplayHints
                $script:wasmCurrentLocalFunctionLiftHints = Merge-WasmAstLocalFunctionLiftHints $beforeLoopFunctionLiftHints $bodyLoopFunctionLiftHints
                $script:wasmCurrentLocalIndexedAccessHints = Merge-WasmAstLocalIndexedAccessHints $beforeLoopIndexedHints $bodyLoopIndexedHints
                Set-WasmAstAccessHintFlowState (Merge-WasmAstAccessHintFlowStates $beforeLoopAccessHints $bodyLoopAccessHints)
            }
