                $Out.Add("${Indent}if")
                if (-not [bool]$arm.is_wildcard) {
                    $Out.Add("${Indent}  i32.const 1")
                    $Out.Add("${Indent}  local.set `$$matched")
                }
                try {
                    Add-WasmAstStmt ($arm.body) $Out ($Indent + "  ") -Main:$Main
                } finally {
                    $armLocalHints = Copy-WasmAstTypeHints $script:wasmCurrentLocalValueTypeHints
                    $armObjectHints = Copy-WasmAstTypeHints $script:wasmCurrentLocalObjectClassHints
                    $armFunctionDisplayHints = Copy-WasmAstTypeHints $script:wasmCurrentLocalFunctionDisplayHints
                    $armFunctionLiftHints = Copy-WasmAstTypeHints $script:wasmCurrentLocalFunctionLiftHints
                    $armIndexedHints = Copy-WasmAstLocalIndexedAccessHints $script:wasmCurrentLocalIndexedAccessHints
                    $armAccessHints = Get-WasmAstAccessHintFlowState
                    if ($null -eq $mergedArmLocalHints) {
                        $mergedArmLocalHints = $armLocalHints
                    } else {
                        $mergedArmLocalHints = Merge-WasmAstLocalValueTypeHints $mergedArmLocalHints $armLocalHints
                    }
                    if ($null -eq $mergedArmObjectHints) {
                        $mergedArmObjectHints = $armObjectHints
                    } else {
                        $mergedArmObjectHints = Merge-WasmAstLocalObjectClassHints $mergedArmObjectHints $armObjectHints
                    }
                    if ($null -eq $mergedArmFunctionDisplayHints) {
                        $mergedArmFunctionDisplayHints = $armFunctionDisplayHints
                    } else {
                        $mergedArmFunctionDisplayHints = Merge-WasmAstLocalFunctionDisplayHints $mergedArmFunctionDisplayHints $armFunctionDisplayHints
                    }
                    if ($null -eq $mergedArmFunctionLiftHints) {
                        $mergedArmFunctionLiftHints = $armFunctionLiftHints
                    } else {
                        $mergedArmFunctionLiftHints = Merge-WasmAstLocalFunctionLiftHints $mergedArmFunctionLiftHints $armFunctionLiftHints
                    }
                    if ($null -eq $mergedArmIndexedHints) {
                        $mergedArmIndexedHints = $armIndexedHints
                    } else {
                        $mergedArmIndexedHints = Merge-WasmAstLocalIndexedAccessHints $mergedArmIndexedHints $armIndexedHints
                    }
                    if ($null -eq $mergedArmAccessHints) {
                        $mergedArmAccessHints = $armAccessHints
                    } else {
                        $mergedArmAccessHints = Merge-WasmAstAccessHintFlowStates $mergedArmAccessHints $armAccessHints
                    }
                }
                $Out.Add("${Indent}end")
            }
            if ($null -eq $mergedArmLocalHints) { $mergedArmLocalHints = Copy-WasmAstTypeHints $beforeMatchLocalHints }
            if ($null -eq $mergedArmObjectHints) { $mergedArmObjectHints = Copy-WasmAstTypeHints $beforeMatchObjectHints }
            if ($null -eq $mergedArmFunctionDisplayHints) { $mergedArmFunctionDisplayHints = Copy-WasmAstTypeHints $beforeMatchFunctionDisplayHints }
            if ($null -eq $mergedArmFunctionLiftHints) { $mergedArmFunctionLiftHints = Copy-WasmAstTypeHints $beforeMatchFunctionLiftHints }
            if ($null -eq $mergedArmIndexedHints) { $mergedArmIndexedHints = Copy-WasmAstLocalIndexedAccessHints $beforeMatchIndexedHints }
            if ($null -eq $mergedArmAccessHints) { $mergedArmAccessHints = $beforeMatchAccessHints }
            if (-not $hasWildcardArm) {
                $mergedArmLocalHints = Merge-WasmAstLocalValueTypeHints $mergedArmLocalHints $beforeMatchLocalHints
                $mergedArmObjectHints = Merge-WasmAstLocalObjectClassHints $mergedArmObjectHints $beforeMatchObjectHints
                $mergedArmFunctionDisplayHints = Merge-WasmAstLocalFunctionDisplayHints $mergedArmFunctionDisplayHints $beforeMatchFunctionDisplayHints
                $mergedArmFunctionLiftHints = Merge-WasmAstLocalFunctionLiftHints $mergedArmFunctionLiftHints $beforeMatchFunctionLiftHints
                $mergedArmIndexedHints = Merge-WasmAstLocalIndexedAccessHints $mergedArmIndexedHints $beforeMatchIndexedHints
                $mergedArmAccessHints = Merge-WasmAstAccessHintFlowStates $mergedArmAccessHints $beforeMatchAccessHints
            }
            $script:wasmCurrentLocalValueTypeHints = $mergedArmLocalHints
            $script:wasmCurrentLocalObjectClassHints = $mergedArmObjectHints
            $script:wasmCurrentLocalFunctionDisplayHints = $mergedArmFunctionDisplayHints
            $script:wasmCurrentLocalFunctionLiftHints = $mergedArmFunctionLiftHints
            $script:wasmCurrentLocalIndexedAccessHints = $mergedArmIndexedHints
            Set-WasmAstAccessHintFlowState $mergedArmAccessHints
        }
        "TRY" {
            $ctx = Push-WasmTryContext
            $payloadType = Get-WasmAstTryThrowPayloadType ($Node.try_block) @{} $script:wasmCurrentClassContext (Get-WasmAstCurrentValueTypeScopeHints)
            $payloadObjectInfo = Get-WasmAstTryThrowPayloadObjectInfo ($Node.try_block) @{} $script:wasmCurrentClassContext $script:wasmCurrentLocalObjectClassHints
            $payloadObjectHint = if ($null -ne $payloadObjectInfo -and [bool]$payloadObjectInfo.AllObjects) {
                [string]$payloadObjectInfo.ClassHint
            } else {
                ""
            }
            $payloadFunctionDisplay = ""
            $payloadFunctionLift = ""
            if ($payloadType -eq "function") {
                $payloadFunctionDisplay = Get-WasmAstTryThrowPayloadFunctionHint ($Node.try_block) "display" @{} $script:wasmCurrentClassContext
                $payloadFunctionLift = Get-WasmAstTryThrowPayloadFunctionHint ($Node.try_block) "lift" @{} $script:wasmCurrentClassContext
            }
            # Collection literals are emitted as tagged Value arrays/dicts.
            # Keeping only their raw payload here loses the per-element/value
            # tags after a cross-function throw. Preserve the complete Value
            # handle for collections and for mixed payload types.
            if (-not [string]::IsNullOrWhiteSpace($payloadObjectHint)) {
                $catchUsesTaggedValue = $false
                $payloadType = "dict"
            } else {
                $catchUsesTaggedValue = ([string]::IsNullOrWhiteSpace($payloadType) -or $payloadType -in @("array", "dict"))
                if ($catchUsesTaggedValue) { $payloadType = "value" }
            }
            $Out.Insert(0, "    (local `$$($ctx.Value) i32)")
            $Out.Insert(0, "    (local `$$($ctx.TaggedValue) i32)")
            $Out.Insert(0, "    (local `$$($ctx.Thrown) i32)")
            $Out.Add("${Indent};; WASM AST structured try/catch/finally lowering uses hidden thrown flag and payload locals")
            $Out.Add("${Indent}i32.const 0")
            $Out.Add("${Indent}local.set `$$($ctx.Thrown)")
            $Out.Add("${Indent}i32.const 0")
            $Out.Add("${Indent}local.set `$$($ctx.Value)")
            $Out.Add("${Indent}i32.const 0")
            $Out.Add("${Indent}local.set `$$($ctx.TaggedValue)")
            $Out.Add("${Indent}block `$$($ctx.End)")
            try {
                Add-WasmAstStmt ($Node.try_block) $Out ($Indent + "  ") -Main:$Main
            } finally {
                Pop-WasmTryContext
            }
            $Out.Add("${Indent}end")
            if ($null -ne $Node.catch_block) {
                $Out.Add("${Indent}local.get `$$($ctx.Thrown)")
                $Out.Add("${Indent}if")
                $catchName = [string]$Node.catch_var
                if (-not [string]::IsNullOrWhiteSpace($catchName)) {
                    if ($catchUsesTaggedValue) {
                        $Out.Add("${Indent}  local.get `$$($ctx.TaggedValue)")
                    } else {
                        $Out.Add("${Indent}  local.get `$$($ctx.Value)")
                    }
                    $Out.Add("${Indent}  local.set `$$catchName")
                    Set-WasmAstCurrentLocalValueTypeHint $catchName $payloadType
                    if (-not [string]::IsNullOrWhiteSpace($payloadObjectHint)) {
                        $script:wasmCurrentLocalObjectClassHints[$catchName] = $payloadObjectHint
                    } else {
                        Set-WasmAstCurrentLocalObjectClassHint $catchName ""
                    }
                    Set-WasmAstCurrentLocalFunctionDisplayHint $catchName $payloadFunctionDisplay
                    Set-WasmAstCurrentLocalFunctionLiftHint $catchName $payloadFunctionLift
                }
                Add-WasmAstStmt ($Node.catch_block) $Out ($Indent + "  ") -Main:$Main
                $Out.Add("${Indent}end")
            }
            if ($null -ne $Node.finally_block) {
                Add-WasmAstStmt ($Node.finally_block) $Out $Indent -Main:$Main
            }
            if ($null -eq $Node.catch_block) {
                $Out.Add("${Indent}local.get `$$($ctx.Thrown)")
                $Out.Add("${Indent}if")
                $parentTryCtx = Get-WasmTryContext
                if ($null -ne $parentTryCtx) {
                    $Out.Add("${Indent}  local.get `$$($ctx.Value)")
                    $Out.Add("${Indent}  local.set `$$($parentTryCtx.Value)")
                    $Out.Add("${Indent}  local.get `$$($ctx.TaggedValue)")
                    $Out.Add("${Indent}  local.set `$$($parentTryCtx.TaggedValue)")
                    $Out.Add("${Indent}  i32.const 1")
                    $Out.Add("${Indent}  local.set `$$($parentTryCtx.Thrown)")
                    $Out.Add("${Indent}  br `$$($parentTryCtx.End)")
                } else {
                    $Out.Add("${Indent}  unreachable")
                }
                $Out.Add("${Indent}end")
            }
        }
        default {
            throw "unsupported WASM AST statement node: $($Node.node)"
        }
    }
}

function Collect-WasmAstLocals {
    param($Node, [string[]]$Params)
    $locals = @{}
    $globalDecls = New-WasmAstGlobalDeclMap $Node
    foreach ($p in $Params) {
        if ($p.Trim()) { $locals[$p.Trim()] = "param" }
    }
    function Add-WasmAstLocal {
        param([string]$Name)
        if (-not [string]::IsNullOrWhiteSpace($Name) -and
            -not $locals.ContainsKey($Name) -and
            -not $globalDecls.ContainsKey($Name)) {
            $locals[$Name] = "local"
        }
    }
    function Visit-WasmAstStmt {
        param($Stmt)
        if ($null -eq $Stmt) { return }
        switch ([string]$Stmt.node) {
            "SuraBlock" {
                foreach ($child in @(As-WasmAstArray ($Stmt.body))) { Visit-WasmAstStmt $child }
            }
            "ASSIGN" { Add-WasmAstLocal ([string]$Stmt.name) }
            "IN_PLACE" { Add-WasmAstLocal ([string]$Stmt.name) }
            "INDEX_ASSIGN" { Add-WasmAstLocal ([string]$Stmt.name) }
            "DOT_ASSIGN" { Add-WasmAstLocal ([string]$Stmt.obj_name) }
            "IF" {
                Visit-WasmAstStmt ($Stmt.then_block)
                Visit-WasmAstStmt ($Stmt.else_block)
            }
            "WHILE" { Visit-WasmAstStmt ($Stmt.body) }
            "REPEAT" { Visit-WasmAstStmt ($Stmt.body) }
            "FOR" {
                Add-WasmAstLocal ([string]$Stmt.var)
                Visit-WasmAstStmt ($Stmt.body)
            }
            "FOREACH" {
                Add-WasmAstLocal ([string]$Stmt.var)
                Add-WasmAstLocal ([string]$Stmt.var2)
                Visit-WasmAstStmt ($Stmt.body)
            }
            "MATCH" {
                foreach ($arm in @(As-WasmAstArray ($Stmt.arms))) { Visit-WasmAstStmt ($arm.body) }
            }
            "TRY" {
                Add-WasmAstLocal ([string]$Stmt.catch_var)
                Visit-WasmAstStmt ($Stmt.try_block)
                Visit-WasmAstStmt ($Stmt.catch_block)
                Visit-WasmAstStmt ($Stmt.finally_block)
            }
            "FUNC_DEF" { }
            "ENUM_DEF" { }
            default { }
        }
    }
    Visit-WasmAstStmt $Node
    return $locals
}

function Register-WasmAstEnumConstants {
    param($Node)
    if ($null -eq $Node) { return }
    switch ([string]$Node.node) {
        "SuraBlock" {
            foreach ($stmt in @(As-WasmAstArray ($Node.body))) { Register-WasmAstEnumConstants $stmt }
        }
        "ENUM_DEF" {
            $enumName = [string]$Node.name
            foreach ($member in @(As-WasmAstArray ($Node.members))) {
                $memberName = [string]$member.name
                $enumKey = "$enumName.$memberName"
                if ($null -eq $member.value) {
                    $script:wasmEnumStringConsts[$enumKey] = $memberName
                    continue
                }
                switch ([string]$member.value.node) {
                    "NUM_LIT" {
                        $script:wasmEnumConsts[$enumKey] = [int][Math]::Truncate([double]$member.value.value)
                    }
                    "STR_LIT" {
                        $script:wasmEnumStringConsts[$enumKey] = [string]$member.value.value
                    }
                    default {
                        throw "WASM AST enum member requires a numeric literal, string literal, or bare member name: $enumKey"
                    }
                }
            }
        }
        default { }
    }
}

