function Add-WasmPayloadSafetyRuntime {
    param([System.Collections.Generic.List[string]]$Wat)

    $Wat.Add("  ;; Raw string/array/dict payloads use a 4-byte element-count header immediately before the returned pointer.")
    $Wat.Add("  ;; Validate spans with division so count*stride and ptr+bytes cannot wrap before the bounds check.")
    $Wat.Add("  (func `$__sura_span_require (param `$ptr i32) (param `$count i32) (param `$stride i32)")
    $Wat.Add("    local.get `$count")
    $Wat.Add("    i32.const 0")
    $Wat.Add("    i32.lt_s")
    $Wat.Add("    if")
    $Wat.Add("      unreachable")
    $Wat.Add("    end")
    $Wat.Add("    local.get `$stride")
    $Wat.Add("    i32.const 0")
    $Wat.Add("    i32.le_s")
    $Wat.Add("    if")
    $Wat.Add("      unreachable")
    $Wat.Add("    end")
    $Wat.Add("    local.get `$ptr")
    $Wat.Add("    global.get `$__heap")
    $Wat.Add("    i32.gt_u")
    $Wat.Add("    if")
    $Wat.Add("      unreachable")
    $Wat.Add("    end")
    $Wat.Add("    local.get `$count")
    $Wat.Add("    global.get `$__heap")
    $Wat.Add("    local.get `$ptr")
    $Wat.Add("    i32.sub")
    $Wat.Add("    local.get `$stride")
    $Wat.Add("    i32.div_u")
    $Wat.Add("    i32.gt_u")
