function Add-WasmContainerEntryGuards {
    param([System.Collections.Generic.List[string]]$Wat)

    $arrayParams = @("arr", "left", "right", "outer")
    $stringParams = @("s", "a", "b", "prefix", "suffix", "needle", "from", "to", "fill", "sep", "text")
    $dictParams = @("dict", "left", "right")
    $index = 0
    while ($index -lt $Wat.Count) {
        $signature = [string]$Wat[$index]
        if ($signature -notmatch '^  \(func \$(?<name>__sura_[A-Za-z0-9_]+)\b') {
            $index++
            continue
        }
        $name = [string]$Matches.name
        $guards = New-Object System.Collections.Generic.List[object]
        foreach ($match in [regex]::Matches($signature, '\(param \$(?<param>[A-Za-z_][A-Za-z0-9_]*) i32\)')) {
            $paramName = [string]$match.Groups["param"].Value
            $kind = ""
            if ($name -like "__sura_array_*") {
                if ($paramName -in $arrayParams) { $kind = "array" }
                elseif ($paramName -eq "sep") { $kind = "string" }
            } elseif ($name -eq "__sura_text_chunks" -and $paramName -eq "s") {
                $kind = "string"
            } elseif ($name -like "__sura_string_*") {
                if ($paramName -in $stringParams) { $kind = "string" }
            } elseif ($name -like "__sura_dict_*") {
                if ($paramName -in $dictParams) { $kind = "dict" }
                elseif ($paramName -eq "keys") { $kind = "array" }
            } elseif ($name -eq "__sura_value_array_to_string" -and $paramName -eq "arr") {
                $kind = "array"
            } elseif ($name -eq "__sura_value_dict_to_string" -and $paramName -eq "dict") {
                $kind = "dict"
            }
            if ($kind) {
                $guards.Add([pscustomobject]@{ Param = $paramName; Kind = $kind }) | Out-Null
            }
        }
        if ($guards.Count -eq 0) {
            $index++
            continue
        }
        $insertAt = $index + 1
        while ($insertAt -lt $Wat.Count -and ([string]$Wat[$insertAt]).TrimStart().StartsWith("(local ")) {
            $insertAt++
        }
        $guardLines = New-Object System.Collections.Generic.List[string]
        foreach ($guard in $guards) {
            if ($name -eq "__sura_string_concat" -and [string]$guard.Param -in @("a", "b")) {
                $guardLines.Add("    local.get `$$($guard.Param)") | Out-Null
                $guardLines.Add("    call `$__sura_string_require") | Out-Null
                $guardLines.Add("    drop") | Out-Null
                continue
            }
            $guardLines.Add("    local.get `$$($guard.Param)") | Out-Null
            $guardLines.Add("    if") | Out-Null
            $guardLines.Add("      local.get `$$($guard.Param)") | Out-Null
            $guardLines.Add("      call `$__sura_$($guard.Kind)_require") | Out-Null
            $guardLines.Add("      drop") | Out-Null
            $guardLines.Add("    end") | Out-Null
        }
        for ($guardIndex = $guardLines.Count - 1; $guardIndex -ge 0; $guardIndex--) {
            $Wat.Insert($insertAt, [string]$guardLines[$guardIndex])
        }
        $index = $insertAt + $guardLines.Count
    }
}

function Protect-WasmContainerAllocations {
    param([System.Collections.Generic.List[string]]$Wat)

    $index = 0
    while ($index + 4 -lt $Wat.Count) {
        $trimmed = @()
        for ($lookahead = 0; $lookahead -lt 5; $lookahead++) {
            $trimmed += ([string]$Wat[$index + $lookahead]).Trim()
        }
        $indent = ([string]$Wat[$index]) -replace '^(\s*).*$', '$1'
        if ($trimmed[0] -eq "i32.const 1" -and
            $trimmed[1] -eq "i32.add" -and
            $trimmed[2] -eq "i32.const 4" -and
            $trimmed[3] -eq "i32.mul" -and
            $trimmed[4] -eq "call `$__sura_alloc") {
            $Wat.RemoveRange($index, 5)
            $Wat.Insert($index, "${indent}call `$__sura_payload_alloc_base")
            $Wat.Insert($index, "${indent}i32.const 4")
            $index += 2
            continue
        }
        if ($trimmed[0] -eq "i32.const 2" -and
            $trimmed[1] -eq "i32.add" -and
            $trimmed[2] -eq "i32.const 4" -and
            $trimmed[3] -eq "i32.mul" -and
            $trimmed[4] -eq "call `$__sura_alloc") {
            $Wat.RemoveRange($index, 5)
            foreach ($line in @("i32.const 1", "i32.add", "i32.const 4", "call `$__sura_payload_alloc_base")) {
                $Wat.Insert($index, "${indent}$line")
                $index++
            }
            continue
        }
        if ($trimmed[0] -match '^i32\.const (4|12)$' -and
            $trimmed[1] -eq "i32.mul" -and
            $trimmed[2] -eq "i32.const 4" -and
            $trimmed[3] -eq "i32.add" -and
            $trimmed[4] -eq "call `$__sura_alloc") {
            $strideLine = [string]$Wat[$index]
            $Wat.RemoveRange($index, 5)
            $Wat.Insert($index, "${indent}call `$__sura_payload_alloc_base")
            $Wat.Insert($index, $strideLine)
            $index += 2
            continue
        }
        $index++
    }
}

