function Add-WasmRuntimeExprCode {
    param([System.Collections.Generic.List[string]]$Wat, [string[]]$Code, [string]$Indent = "    ")

    foreach ($line in @($Code)) {
        $Wat.Add("$Indent$line")
    }
}

function Add-WasmRuntimeStringLiteral {
    param([System.Collections.Generic.List[string]]$Wat, [string]$Text, [string]$Indent = "    ")

    Add-WasmRuntimeExprCode -Wat $Wat -Code ([string[]]@(New-WasmStringLiteralExprCode -Literal (Convert-WasmAstStringLiteral $Text))) -Indent $Indent
}

function New-WasmRyuTableData {
    # Ryu's Apache-2.0/Boost-1.0 lookup-table formulas are generated here
    # instead of copying a platform C runtime or requiring a host import.
    $two64 = [System.Numerics.BigInteger]::Pow([System.Numerics.BigInteger]::new(2), 64)
    $one = [System.Numerics.BigInteger]::One
    $five = [System.Numerics.BigInteger]::new(5)
    $bytes = New-Object System.Collections.Generic.List[byte]

    function Add-RyuUInt128LittleEndian {
        param([System.Numerics.BigInteger]$Value)
        $low = [UInt64]($Value % $two64)
        $high = [UInt64]($Value / $two64)
        $bytes.AddRange([BitConverter]::GetBytes($low))
        $bytes.AddRange([BitConverter]::GetBytes($high))
    }

    $pow5 = $one
    for ($i = 0; $i -lt 342; $i++) {
        $pow5Bits = (($i * 1217359) -shr 19) + 1
        $shift = ($pow5Bits - 1) + 125
        $numerator = [System.Numerics.BigInteger]::op_LeftShift($one, $shift)
        Add-RyuUInt128LittleEndian (($numerator / $pow5) + $one)
        $pow5 *= $five
    }

    $pow5 = $one
    for ($i = 0; $i -lt 326; $i++) {
        $pow5Bits = (($i * 1217359) -shr 19) + 1
        $shift = $pow5Bits - 125
        $scaled = if ($shift -ge 0) {
            [System.Numerics.BigInteger]::op_RightShift($pow5, $shift)
        } else {
            [System.Numerics.BigInteger]::op_LeftShift($pow5, -$shift)
        }
        Add-RyuUInt128LittleEndian $scaled
        $pow5 *= $five
    }

    if ($bytes.Count -ne 10688) {
        throw "internal Ryu table generation produced $($bytes.Count) bytes instead of 10688"
    }
    $escaped = New-Object System.Text.StringBuilder ($bytes.Count * 3)
    foreach ($byte in $bytes) {
        [void]$escaped.Append('\')
        [void]$escaped.Append($byte.ToString('x2', [System.Globalization.CultureInfo]::InvariantCulture))
    }
    return [pscustomobject]@{
        Data = $escaped.ToString()
        InverseOffset = 16
        PowerOffset = 5488
        HeapStart = 10704
    }
}

