function Add-WasmFunctionDispatchRuntime {
    param(
        [System.Collections.Generic.List[string]]$Wat,
        [object[]]$Functions
    )

    $Wat.Add("  (func `$__sura_function_to_string (param `$id i32) (result i32)")
    $seenDisplayIds = @{}
    foreach ($fn in @($Functions | Sort-Object Name)) {
        $name = [string]$fn.Name
        if ([string]::IsNullOrWhiteSpace($name)) { continue }
        $id = Get-WasmStringKeyHash $name
        if ($seenDisplayIds.ContainsKey([string]$id)) { continue }
        $seenDisplayIds[[string]$id] = $true
        $displayName = $name
        if ($fn.PSObject.Properties.Name -contains "WasmFuncExprDisplayName" -and
            -not [string]::IsNullOrWhiteSpace([string]$fn.WasmFuncExprDisplayName)) {
            $displayName = [string]$fn.WasmFuncExprDisplayName
        }
        $Wat.Add("    local.get `$id")
        $Wat.Add("    i32.const $id")
        $Wat.Add("    i32.eq")
        $Wat.Add("    if")
        Add-WasmRuntimeStringLiteral -Wat $Wat -Text ("<Func $displayName>") -Indent "      "
        $Wat.Add("      return")
        $Wat.Add("    end")
    }
    Add-WasmRuntimeStringLiteral -Wat $Wat -Text "<Func>" -Indent "    "
    $Wat.Add("  )")

    $arities = @{}
    for ($i = 0; $i -le 5; $i++) { $arities[$i] = $true }
    foreach ($fn in @($Functions)) {
        $arity = @($fn.Params).Count
        $arities[$arity] = $true
    }

    foreach ($arity in ($arities.Keys | Sort-Object {[int]$_})) {
        $arityInt = [int]$arity
        $params = New-Object System.Collections.Generic.List[string]
        $params.Add("(param `$id i32)") | Out-Null
        for ($i = 0; $i -lt $arityInt; $i++) {
            $params.Add("(param `$arg$i i32)") | Out-Null
        }
        $Wat.Add("  (func `$__sura_call_function_$arityInt $([string]::Join(' ', [string[]]$params.ToArray())) (result i32)")

        $seenIds = @{}
        $candidates = @($Functions | Where-Object {
            @($_.Params).Count -eq $arityInt -and
            $script:wasmEscapingFunctionValueNames.ContainsKey([string]$_.Name)
        } | Sort-Object Name)
        foreach ($fn in $candidates) {
            $name = [string]$fn.Name
            if ([string]::IsNullOrWhiteSpace($name)) { continue }
            $id = Get-WasmStringKeyHash $name
            if ($seenIds.ContainsKey([string]$id)) { continue }
            $seenIds[[string]$id] = $true
            $Wat.Add("    local.get `$id")
            $Wat.Add("    i32.const $id")
            $Wat.Add("    i32.eq")
            $Wat.Add("    if")
            for ($i = 0; $i -lt $arityInt; $i++) {
