    $Wat.Add("        i32.add")
    $Wat.Add("        i32.load")
    $Wat.Add("        local.set `$entry")
    $Wat.Add("        br `$__object_class_lookup")
    $Wat.Add("      end")
    $Wat.Add("    end")
    $Wat.Add("    i32.const 0")
    $Wat.Add("  )")

