    $Wat.Add("    (local `$class_id i32)")
    $Wat.Add("    local.get `$object")
    $Wat.Add("    call `$__sura_object_class_id")
    $Wat.Add("    local.set `$class_id")
    foreach ($className in @($script:wasmClassDefs.Keys | ForEach-Object { [string]$_ } | Sort-Object -Unique)) {
        $classId = Get-WasmClassDispatchId $className
        if ($classId -le 0) { continue }
        $Wat.Add("    local.get `$class_id")
        $Wat.Add("    i32.const $classId")
        $Wat.Add("    i32.eq")
        $Wat.Add("    if")
        Add-WasmRuntimeStringLiteral -Wat $Wat -Text ("<Instance $className>") -Indent "      "
        $Wat.Add("      return")
        $Wat.Add("    end")
    }
    Add-WasmRuntimeStringLiteral -Wat $Wat -Text "<Instance>" -Indent "    "
    $Wat.Add("  )")

    $dispatches = @{}
    foreach ($classEntry in @($script:wasmClassDefs.GetEnumerator())) {
        foreach ($method in @(As-WasmAstArray ($classEntry.Value.Node.methods))) {
            $methodName = [string]$method.name
            if ([string]::IsNullOrWhiteSpace($methodName) -or $methodName -eq "init") { continue }
            $arity = @(Get-WasmAstParamNames ($method.params)).Count
            $dispatches["$methodName`0$arity"] = [pscustomobject]@{ MethodName = $methodName; Arity = $arity }
        }
    }

    foreach ($dispatch in @($dispatches.Values | Sort-Object MethodName, Arity)) {
        $methodName = [string]$dispatch.MethodName
        $arity = [int]$dispatch.Arity
        $dispatchName = Get-WasmMethodDispatchName -MethodName $methodName -Arity $arity
        $candidates = @(Get-WasmAstDynamicMethodCandidates -MethodName $methodName -Arity $arity)
        if ([string]::IsNullOrWhiteSpace($dispatchName) -or $candidates.Count -eq 0) { continue }

        $params = New-Object System.Collections.Generic.List[string]
        $params.Add("(param `$self i32)") | Out-Null
        for ($i = 0; $i -lt $arity; $i++) { $params.Add("(param `$arg$i i32)") | Out-Null }
        $Wat.Add("  (func `$$dispatchName $([string]::Join(' ', [string[]]$params.ToArray())) (result i32)")
        $Wat.Add("    (local `$class_id i32)")
        $Wat.Add("    local.get `$self")
        $Wat.Add("    call `$__sura_object_class_id")
        $Wat.Add("    local.set `$class_id")
        foreach ($candidate in $candidates) {
            $Wat.Add("    local.get `$class_id")
            $Wat.Add("    i32.const $([int]$candidate.ClassId)")
            $Wat.Add("    i32.eq")
            $Wat.Add("    if")
            $Wat.Add("      local.get `$self")
            for ($i = 0; $i -lt $arity; $i++) { $Wat.Add("      local.get `$arg$i") }
            $Wat.Add("      call `$$([string]$candidate.FunctionName)")
            $Wat.Add("      return")
            $Wat.Add("    end")
        }
        $Wat.Add("    unreachable")
        $Wat.Add("    i32.const 0")
        $Wat.Add("  )")
    }
}

