$functions = @()
$mainLines = New-Object System.Collections.Generic.List[string]
$mainAst = $null
$wasmInputBanner = ";; AST JSON input: sura.ast.v1"

if ($AstJson) {
    $astJsonPath = (Resolve-Path -LiteralPath $Source).Path
    $astReport = Read-WasmAstReport $astJsonPath
} else {
    $sourcePath = (Resolve-Path -LiteralPath $Source).Path
    $enginePath = Resolve-WasmEngine $Engine
    $astJsonPath = $sourcePath
    $astReport = Export-WasmAstReport -SourcePath $sourcePath -EnginePath $enginePath
    $wasmInputBanner = ";; AST JSON input: sura.ast.v1 (exported from Sura source)"
}

$expandedAst = Expand-WasmAstImports -AstReport $astReport -AstJsonPath $astJsonPath -State @{} -EnginePath $(if ($AstJson) { "" } else { $enginePath })
Register-WasmAstModuleGlobals $expandedAst
Register-WasmAstEnumConstants $expandedAst
Register-WasmAstFunctionDefs $expandedAst
Register-WasmAstClassDefs $expandedAst
Register-WasmAstStringAccessHints $expandedAst
Register-WasmAstRawF64ExportFunctions $expandedAst
$mainAstBody = New-Object System.Collections.Generic.List[object]
$nestedFuncExprFunctions = New-Object System.Collections.Generic.List[object]
Add-WasmAstNestedFunctionExprPromotions -Node $expandedAst -Functions $nestedFuncExprFunctions -TopLevel $true
foreach ($stmt in @(As-WasmAstArray ($expandedAst.body))) {
    if ([string]$stmt.node -eq "FUNC_DEF") {
        $functions += [pscustomobject]@{
            Name = [string]$stmt.name
            Params = @(Get-WasmAstParamNames ($stmt.params))
            Body = @()
            BodyAst = $stmt.body
        }
    } elseif ([string]$stmt.node -eq "CLASS_DEF") {
        $ctor = New-WasmAstClassConstructorFunction $stmt
        if ($null -ne $ctor) { $functions += $ctor }
        foreach ($methodFn in @(New-WasmAstClassMethodFunctions $stmt)) {
            $functions += $methodFn
        }
        $mainAstBody.Add($stmt) | Out-Null
    } elseif ([string]$stmt.node -eq "ASSIGN" -and $null -ne $stmt.value -and [string]$stmt.value.node -eq "FUNC_EXPR") {
        $functions += [pscustomobject]@{
            Name = [string]$stmt.name
            Params = @(Get-WasmAstParamNames ($stmt.value.params))
            Body = @()
            BodyAst = $stmt.value.body
            WasmFuncExprPromotion = $true
        }
    } else {
        $mainAstBody.Add($stmt) | Out-Null
    }
}
foreach ($liftedFn in @($nestedFuncExprFunctions.ToArray())) {
    $functions += $liftedFn
}
$mainAst = [pscustomobject]@{ node = "SuraBlock"; body = @($mainAstBody.ToArray()) }
Register-WasmAstForwardedFunctionParamTypeHints $functions
Register-WasmAstIndirectFunctionParamTypeHints $functions
Register-WasmAstEscapingFunctionValueParamTypeHints $functions $mainAst
# Escaping functions now have a uniform tagged-Value parameter ABI. Propagate
# that requirement through direct forwarding wrappers before body emission.
Register-WasmAstForwardedFunctionParamTypeHints $functions
Register-WasmAstFlowValueReturnHints $functions
# Earlier discovery passes can ask about a return type before all call sites
# have contributed their parameter observations.  Recompute against the final
# concrete-or-Value ABI before emitting function bodies.
$script:wasmFunctionReturnValuePreservingCache = @{}

