foreach ($fn in $functions) {
    $script:hiddenCounter = 0
    $script:wasmLoopCounter = 0
    $script:wasmLoopStack.Clear()
    $script:wasmTryCounter = 0
    $script:wasmTryStack.Clear()
    $bodyOut = New-Object System.Collections.Generic.List[string]
    $locals = Collect-WasmAstLocals ($fn.BodyAst) $fn.Params
    $sigParams = ($fn.Params | ForEach-Object { "(param `$$($_) i32)" }) -join " "
    $exportClause = if ($fn.Name -eq "main") { "" } else { " (export `"$($fn.Name)`")" }
    $wat.Add("  (func `$$($fn.Name)$exportClause $sigParams (result i32)")
    $bodyOut.Add("    (local `$__sura_wasm_array_tmp i32)")
    $bodyOut.Add("    (local `$__sura_wasm_dict_tmp i32)")
    $bodyOut.Add("    (local `$__sura_wasm_value_tmp i32)")
    $bodyOut.Add("    (local `$__sura_wasm_call_tmp i32)")
    foreach ($k in ($locals.Keys | Sort-Object)) {
        if ($locals[$k] -ne "param") { $bodyOut.Add("    (local `$$k i32)") }
    }
    $previousClassContext = $script:wasmCurrentClassContext
    $previousParamHints = $script:wasmCurrentFunctionParamTypeHints
    $previousLocalHints = $script:wasmCurrentLocalValueTypeHints
    $previousObjectHints = $script:wasmCurrentLocalObjectClassHints
    $previousFunctionDisplayHints = $script:wasmCurrentLocalFunctionDisplayHints
    $previousFunctionLiftHints = $script:wasmCurrentLocalFunctionLiftHints
    $previousFunctionLiftCandidates = $script:wasmCurrentLocalFunctionLiftCandidates
    $previousLocalFunctionExprs = $script:wasmCurrentLocalFunctionExprs
    $previousIndexedHints = $script:wasmCurrentLocalIndexedAccessHints
    $previousAccessTypeHints = $script:wasmAccessTypeHints
    $previousConflictedAccessTypeHints = $script:wasmConflictedAccessTypeHints
    $previousStringAccessHints = $script:wasmStringAccessHints
    $previousAccessFunctionDisplayHints = $script:wasmAccessFunctionDisplayHints
    $previousConflictedAccessFunctionDisplayHints = $script:wasmConflictedAccessFunctionDisplayHints
    $previousAccessObjectClassHints = $script:wasmAccessObjectClassHints
    $previousConflictedAccessObjectClassHints = $script:wasmConflictedAccessObjectClassHints
    $previousEmptyArrayHints = $script:wasmEmptyArrayHints
    $previousEmptyDictHints = $script:wasmEmptyDictHints
    $previousDictKeyOrderHints = $script:wasmDictKeyOrderHints
    $previousFunctionName = $script:wasmCurrentFunctionName
    $previousFunctionReturnsValue = $script:wasmCurrentFunctionReturnsValue
    $previousGlobalDecls = $script:wasmCurrentGlobalDecls
    $script:wasmCurrentFunctionName = [string]$fn.Name
    $script:wasmCurrentFunctionParamTypeHints = Get-WasmAstObservedFunctionParamTypeHints ([string]$fn.Name)
    $script:wasmCurrentLocalValueTypeHints = @{}
    $script:wasmCurrentLocalObjectClassHints = Get-WasmAstObservedFunctionParamObjectClassHints ([string]$fn.Name)
    $script:wasmCurrentLocalFunctionDisplayHints = Get-WasmAstObservedFunctionParamFunctionDisplayHints ([string]$fn.Name)
    $script:wasmCurrentLocalFunctionLiftHints = Get-WasmAstObservedFunctionParamFunctionLiftHints ([string]$fn.Name)
    $script:wasmCurrentLocalFunctionLiftCandidates = @{}
    $script:wasmCurrentLocalFunctionExprs = @{}
    $script:wasmCurrentLocalIndexedAccessHints = @{}
    $script:wasmAccessTypeHints = Copy-WasmAstTypeHints $previousAccessTypeHints
    $script:wasmConflictedAccessTypeHints = Copy-WasmAstTypeHints $previousConflictedAccessTypeHints
    $script:wasmStringAccessHints = Copy-WasmAstTypeHints $previousStringAccessHints
    $script:wasmAccessFunctionDisplayHints = Copy-WasmAstTypeHints $previousAccessFunctionDisplayHints
    $script:wasmConflictedAccessFunctionDisplayHints = Copy-WasmAstTypeHints $previousConflictedAccessFunctionDisplayHints
    $script:wasmAccessObjectClassHints = Copy-WasmAstTypeHints $previousAccessObjectClassHints
    $script:wasmConflictedAccessObjectClassHints = Copy-WasmAstTypeHints $previousConflictedAccessObjectClassHints
    $script:wasmEmptyArrayHints = Copy-WasmAstTypeHints $previousEmptyArrayHints
    $script:wasmEmptyDictHints = Copy-WasmAstTypeHints $previousEmptyDictHints
    $script:wasmDictKeyOrderHints = Copy-WasmAstStringArrayHints $previousDictKeyOrderHints
    $script:wasmCurrentGlobalDecls = New-WasmAstGlobalDeclMap ($fn.BodyAst)
    if ($fn.PSObject.Properties.Name -contains "WasmClassName") {
        $script:wasmCurrentClassContext = [string]$fn.WasmClassName
    } else {
        $script:wasmCurrentClassContext = ""
    }
    $script:wasmCurrentFunctionReturnsValue = Test-WasmAstFunctionReturnValuePreserving ([string]$fn.Name)
    Set-WasmAstCurrentFunctionParamCollectionHints ([string]$fn.Name) ([string[]]$fn.Params)
    try {
        Add-WasmAstStmt ($fn.BodyAst) $bodyOut "    "
    } finally {
        $script:wasmCurrentClassContext = $previousClassContext
        $script:wasmCurrentFunctionParamTypeHints = $previousParamHints
        $script:wasmCurrentLocalValueTypeHints = $previousLocalHints
        $script:wasmCurrentLocalObjectClassHints = $previousObjectHints
        $script:wasmCurrentLocalFunctionDisplayHints = $previousFunctionDisplayHints
