        $script:wasmCurrentLocalIndexedAccessHints = $previousIndexedHints
        $script:wasmAccessTypeHints = $previousAccessTypeHints
        $script:wasmConflictedAccessTypeHints = $previousConflictedAccessTypeHints
        $script:wasmStringAccessHints = $previousStringAccessHints
        $script:wasmAccessFunctionDisplayHints = $previousAccessFunctionDisplayHints
        $script:wasmConflictedAccessFunctionDisplayHints = $previousConflictedAccessFunctionDisplayHints
        $script:wasmAccessObjectClassHints = $previousAccessObjectClassHints
        $script:wasmConflictedAccessObjectClassHints = $previousConflictedAccessObjectClassHints
        $script:wasmEmptyArrayHints = $previousEmptyArrayHints
        $script:wasmEmptyDictHints = $previousEmptyDictHints
        $script:wasmDictKeyOrderHints = $previousDictKeyOrderHints
        $script:wasmCurrentFunctionName = $previousFunctionName
