    $bodyOut.Add("    i32.const 0")
    foreach ($line in $bodyOut) { $wat.Add($line) }
    $wat.Add("  )")
}

Add-WasmRawF64ExportWrappers -Wat $wat -Functions $functions

$script:hiddenCounter = 0
$script:wasmLoopCounter = 0
$script:wasmLoopStack.Clear()
$script:wasmTryCounter = 0
$script:wasmTryStack.Clear()
$mainOut = New-Object System.Collections.Generic.List[string]
$mainLocals = Collect-WasmAstLocals $mainAst @()
$mainOut.Add("    (local `$__result i32)")
$mainOut.Add("    (local `$__sura_wasm_array_tmp i32)")
$mainOut.Add("    (local `$__sura_wasm_dict_tmp i32)")
$mainOut.Add("    (local `$__sura_wasm_value_tmp i32)")
$mainOut.Add("    (local `$__sura_wasm_call_tmp i32)")
foreach ($k in ($mainLocals.Keys | Sort-Object)) {
    $mainOut.Add("    (local `$$k i32)")
}
$previousLocalHints = $script:wasmCurrentLocalValueTypeHints
$previousObjectHints = $script:wasmCurrentLocalObjectClassHints
$previousFunctionDisplayHints = $script:wasmCurrentLocalFunctionDisplayHints
$previousFunctionLiftHints = $script:wasmCurrentLocalFunctionLiftHints
$previousFunctionLiftCandidates = $script:wasmCurrentLocalFunctionLiftCandidates
$previousLocalFunctionExprs = $script:wasmCurrentLocalFunctionExprs
$previousIndexedHints = $script:wasmCurrentLocalIndexedAccessHints
$previousFunctionName = $script:wasmCurrentFunctionName
$previousGlobalDecls = $script:wasmCurrentGlobalDecls
$script:wasmCurrentFunctionName = "main"
$script:wasmCurrentLocalValueTypeHints = @{}
$script:wasmCurrentLocalObjectClassHints = @{}
$script:wasmCurrentLocalFunctionDisplayHints = @{}
$script:wasmCurrentLocalFunctionLiftHints = @{}
$script:wasmCurrentLocalFunctionLiftCandidates = @{}
$script:wasmCurrentLocalFunctionExprs = @{}
$script:wasmCurrentLocalIndexedAccessHints = @{}
$script:wasmCurrentGlobalDecls = @{}
try {
    Add-WasmAstStmt $mainAst $mainOut "    " -Main
} finally {
    $script:wasmCurrentLocalValueTypeHints = $previousLocalHints
    $script:wasmCurrentLocalObjectClassHints = $previousObjectHints
    $script:wasmCurrentLocalFunctionDisplayHints = $previousFunctionDisplayHints
    $script:wasmCurrentLocalFunctionLiftHints = $previousFunctionLiftHints
    $script:wasmCurrentLocalFunctionLiftCandidates = $previousFunctionLiftCandidates
    $script:wasmCurrentLocalFunctionExprs = $previousLocalFunctionExprs
    $script:wasmCurrentLocalIndexedAccessHints = $previousIndexedHints
    $script:wasmCurrentFunctionName = $previousFunctionName
    $script:wasmCurrentGlobalDecls = $previousGlobalDecls
}
$mainOut.Add("    local.get `$__result")
$wat.Add('  (func (export "main") (result i32)')
foreach ($line in $mainOut) { $wat.Add($line) }
$wat.Add("  )")
Add-WasmLiteralConstructorRuntime -Wat $wat
Protect-WasmContainerAllocations -Wat $wat
$wat.Add(")")

function Assert-WasmWatInstructionBoundaries {
    param([string[]]$Lines)

    for ($i = 0; $i -lt $Lines.Count; $i++) {
        $line = [string]$Lines[$i]
        $trimmed = $line.Trim()
        if ([string]::IsNullOrWhiteSpace($trimmed) -or $trimmed.StartsWith(";;")) { continue }
        if ($trimmed -match '\$[A-Za-z_][A-Za-z0-9_]*(?:i32\.|local\.|global\.)' -or
            $trimmed -match '\b-?[0-9]+(?:i32\.|local\.|global\.|call\b|return\b|drop\b|if\b|else\b|end\b)') {
            throw "invalid WASM WAT instruction boundary at generated line $($i + 1): $trimmed"
        }
    }
}

Assert-WasmWatInstructionBoundaries ([string[]]$wat.ToArray())
Set-Content -LiteralPath $Out -Value ($wat -join [Environment]::NewLine) -Encoding ASCII
Write-Host "[OK] wrote $Out"

if ($WasmOut) {
    Invoke-WasmWatCompiler -WatPath $Out -BinaryPath $WasmOut
    Write-Host "[OK] wrote $WasmOut"
}
